import { STEP, heightOnTile, idx, inB, waterDepth, type Town, type World } from '../world/tiles';
import { hash2 } from '../world/rng';
import type { Kit } from './buildings/kit';
import { stoneLantern } from './buildings/regions/terraces';
import { gasLamp, steam, willow } from './buildings/onsenKit';

/**
 * An onsen town's stream (world/onsen.ts cuts it), dressed the way Kinosaki's canal and Ginzan's river are: weeping
 * willows leaning over the water at the edge of the quay, stone lanterns and gas lamps between them, and steam rising
 * off the hot water here and there. Drawn with the town's buildings, a chunk at a time (render/townMesh.ts), from the
 * tiles alone: the water inside the town's square that no road crosses is the stream.
 */
export function onsenDress(k: Kit, w: World, t: Town, x0: number, z0: number, x1: number, z1: number): void {
  k.place(0, 0, 0, 0);
  const inSquare = (x: number, z: number) => x >= t.x0 && z >= t.z0 && x < t.x0 + t.size && z < t.z0 + t.size;
  const stream = (x: number, z: number) => inB(x, z) && inSquare(x, z) && waterDepth(w, idx(x, z)) > 0 && !w.road[idx(x, z)];
  let vents = 0;
  for (let z = Math.max(z0, t.z0); z < Math.min(z1, t.z0 + t.size); z++) {
    for (let x = Math.max(x0, t.x0); x < Math.min(x1, t.x0 + t.size); x++) {
      const i = idx(x, z);
      if (stream(x, z)) {
        // steam off the water now and then
        if (vents < 4 && hash2(x, z, 7311) < 0.07) {
          vents++;
          steam(k, x + 0.5, w.water[i] * STEP + 0.02, z + 0.5, 0.9, 2, 0.6, (x * 31 + z * 17) >>> 0);
        }
        continue;
      }
      if (waterDepth(w, i) > 0 || w.blocked[i]) continue;
      // a bank: the side the stream lies on
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        if (!stream(x + dx, z + dz)) continue;
        if ((x + z) % 2 && hash2(x, z, 7313) < 0.6) break;
        const px = x + 0.5 + dx * 0.4, pz = z + 0.5 + dz * 0.4;
        const y = heightOnTile(w, x, z, px, pz) - 0.01;
        const roll = hash2(x, z, 7317);
        if (roll < 0.5) willow(k, px, y, pz, 0.95 + hash2(x, z, 7319) * 0.3, dx || dz);
        else if (roll < 0.75) stoneLantern(k, px, y, pz, 1.3);
        else gasLamp(k, px, y, pz, 0.36);
        break;
      }
    }
  }
}
