import * as THREE from 'three';
import type { World } from '../world/tiles';
import { buildVehicleMesh, disposeVehicleMesh, poseVehicleMesh, type VehicleMesh } from './vehicleMeshes';
import { spawnState } from '../game/placement';
import { AirState, groundY } from '../game/air';
import { defOf } from '../game/fleet';
import { walkUpReach } from './fleetLayer';
import { placeStash, type Stash } from '../game/stash';
import type { VehicleDef, VehicleState } from '../game/vehicles';

/**
 * The hidden vehicles (game/stash.ts) of the counties in the scene: each parked where it was left, a soft
 * gold glow breathing on the ground under it. Which counties have one is worked out once per county and
 * kept; which have been claimed is saved.
 */

interface Shown { s: Stash; w: World; def: VehicleDef; state: VehicleState; mesh: VehicleMesh; glow: THREE.Mesh; mat: THREE.MeshBasicMaterial }

let glowTex: THREE.Texture | null = null;
function glowTexture(): THREE.Texture {
  if (glowTex) return glowTex;
  const S = 128, c = document.createElement('canvas');
  c.width = c.height = S;
  const g = c.getContext('2d')!;
  const grad = g.createRadialGradient(S / 2, S / 2, 0, S / 2, S / 2, S / 2);
  grad.addColorStop(0, 'rgba(255,236,170,0.0)');
  grad.addColorStop(0.55, 'rgba(255,220,120,0.55)');
  grad.addColorStop(0.78, 'rgba(255,244,200,0.95)');
  grad.addColorStop(1, 'rgba(255,210,100,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, S, S);
  glowTex = new THREE.CanvasTexture(c);
  glowTex.colorSpace = THREE.SRGBColorSpace;
  return glowTex;
}
const DISC = new THREE.PlaneGeometry(2, 2).rotateX(-Math.PI / 2);

export class StashLayer {
  /** Each county's hidden vehicle, or null, by "cx,cz". */
  private cells = new Map<string, Stash | null>();
  /** Counties whose vehicle has been claimed. Saved. */
  readonly claimed = new Set<string>();
  private shown = new Map<string, Shown>();
  private t = 0;

  /** The county's hidden vehicle while it is still there to be found. */
  of(w: World): Stash | null {
    const k = `${w.cx},${w.cz}`;
    if (!this.cells.has(k)) this.cells.set(k, placeStash(w));
    const s = this.cells.get(k) ?? null;
    return s && !this.claimed.has(s.key) ? s : null;
  }

  /** Every unclaimed hidden vehicle of the counties given. */
  within(worlds: Iterable<World>): Stash[] {
    const out: Stash[] = [];
    for (const w of worlds) { const s = this.of(w); if (s) out.push(s); }
    return out;
  }

  /** A mesh for every unclaimed hidden vehicle on an island in the scene; gone for everything else. */
  sync(worlds: Iterable<World>, groupOf: (w: World) => THREE.Group | null): void {
    const want = new Set<string>();
    for (const w of worlds) {
      const s = this.of(w);
      const g = s ? groupOf(w) : null;
      if (!s || !g) continue;
      want.add(s.key);
      const have = this.shown.get(s.key);
      if (have && have.w === w) continue;
      if (have) this.drop(have);
      const def = defOf(s.model);
      const state: VehicleState = def.kind === 'air'
        ? new AirState(def, s.x, s.z, s.heading, s.y ?? groundY(w, s.x, s.z), w)
        : (() => { const q = spawnState(def, w, s.x, s.z, s.heading, -Infinity); q.v = 0; return q; })();
      const mesh = buildVehicleMesh(def);
      poseVehicleMesh(mesh, state, def, w);
      g.add(mesh.holder);
      const mat = new THREE.MeshBasicMaterial({ map: glowTexture(), transparent: true, depthWrite: false, toneMapped: false, blending: THREE.AdditiveBlending,
        polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
      const glow = new THREE.Mesh(DISC, mat);
      glow.renderOrder = 2;
      glow.position.set(state.x, state.y + 0.03, state.z);
      glow.scale.setScalar(Math.max(0.75, (def.halfLen ?? 0.5) * 1.35 + 0.3));
      g.add(glow);
      this.shown.set(s.key, { s, w, def, state, mesh, glow, mat });
    }
    for (const sh of [...this.shown.values()]) if (!want.has(sh.s.key)) this.drop(sh);
  }

  /** The glow breathes. */
  update(dt: number): void {
    this.t += dt;
    const beat = 0.5 + 0.5 * Math.sin(this.t * 2.6);
    for (const sh of this.shown.values()) {
      sh.mat.opacity = 0.55 + 0.45 * beat;
      const base = Math.max(0.75, (sh.def.halfLen ?? 0.5) * 1.35 + 0.3);
      sh.glow.scale.setScalar(base * (0.94 + 0.1 * beat));
    }
  }

  /** The hidden vehicle a player at (x, z) on island w is close enough to climb into, if any. */
  near(w: World, x: number, z: number): { s: Stash; def: VehicleDef; state: VehicleState } | null {
    for (const sh of this.shown.values()) {
      if (sh.w !== w) continue;
      if (Math.hypot(sh.state.x - x, sh.state.z - z) <= walkUpReach(sh.def) + 0.3) return { s: sh.s, def: sh.def, state: sh.state };
    }
    return null;
  }

  /** It's been found: it goes from the map for good. */
  claim(s: Stash): void {
    this.claimed.add(s.key);
    const sh = this.shown.get(s.key);
    if (sh) this.drop(sh);
  }

  private drop(sh: Shown): void {
    sh.mesh.holder.removeFromParent();
    disposeVehicleMesh(sh.mesh);
    sh.glow.removeFromParent();
    sh.mat.dispose();
    this.shown.delete(sh.s.key);
  }

  /** A new world: forget every county. */
  clear(): void {
    for (const sh of [...this.shown.values()]) this.drop(sh);
    this.cells.clear();
  }

  reset(): void { this.clear(); this.claimed.clear(); }

  save(): string[] { return [...this.claimed]; }
  load(list: string[] | undefined): void { this.claimed.clear(); for (const k of list ?? []) this.claimed.add(k); }
}
