/**
 * The ten faction strongholds' plans (docs/strongholds.html, 0.8.0): each one a single great building over its whole lot
 * (one kind per faction, world/kinds080.ts), drawn by render/buildings/strongholds*.ts from these same plans and given
 * its footprint from them (world/kinds080.ts SHAPES_080), so what stands up is exactly what stops a car. Every plan has
 * a shape of its own: its own wall (a polygon, or more than one ring), its own gates, its own ground, its own blocks.
 *
 * The frame is the model's: origin in the lot's middle, x across W, +z the way it faces (the county road; the front).
 * Wall rings are closed polygons; a gate is a gap in a ring, centred on (x, z), `w` wide along that edge. The interior
 * is everything inside ring 0 (the outer ring), and it is drivable except where a block stands (`open` blocks are
 * drawn but driven over: a parade square, a runway marked on salt, a quay).
 *
 * `door` is where the stronghold's cargo is fetched and taken (its headquarters' door, inside the wall); `stage` is
 * where the Oath's last step is held; `pad` the helipad (`y` above the ground for a roof).
 */

import type { FactionId } from '../game/factions/factions';

export interface SBlock { type: string; x: number; z: number; w: number; d: number; h: number; open?: boolean }
export interface SGate {
  x: number; z: number; w: number;
  /** The ring it is cut in (0 is the outer wall). */
  ring: number;
  /** Which way traffic may use it: an in/out pair at the General Post Office. */
  dir: 'both' | 'in' | 'out';
}
export interface SPlan {
  kind: StrongholdKind;
  faction: FactionId;
  /** The lot, W across the front, D deep. */
  size: [number, number];
  /** Where it is levelled (world/wonders.ts planWonder): on the flat, or up on high ground. */
  where: 'flat' | 'high';
  /** Wall rings (closed polygons, the outer first) and how they are built. */
  rings: [number, number][][];
  wall: { h: number; t: number; kind: 'wall' | 'fence' };
  gates: SGate[];
  door: { x: number; z: number };
  stage: { x: number; z: number };
  pad: { x: number; z: number; y: number };
  blocks: SBlock[];
}

export const STRONGHOLD_KINDS = [
  'shYard', 'shVilla', 'shCitadel', 'shSiteNull', 'shFederation', 'shGPO', 'shCantonment', 'shLot', 'shHarbour', 'shVane',
] as const;
export type StrongholdKind = (typeof STRONGHOLD_KINDS)[number];
export const isStronghold = (k: string): k is StrongholdKind => (STRONGHOLD_KINDS as readonly string[]).includes(k);

const rect = (hw: number, hd: number): [number, number][] => [[-hw, hd], [-hw, -hd], [hw, -hd], [hw, hd]];
/** A regular polygon of n sides, radius r, its first corner at angle a0 (radians, from +x toward +z). */
const ngon = (n: number, r: number, a0: number): [number, number][] =>
  Array.from({ length: n }, (_, k) => [r * Math.cos(a0 + (k * 2 * Math.PI) / n), r * Math.sin(a0 + (k * 2 * Math.PI) / n)] as [number, number]);

