const MAKERS: Record<StrongholdKind, () => SPlan> = {
  shYard: yard, shVilla: villa, shCitadel: citadel, shSiteNull: siteNull, shFederation: federation,
  shGPO: gpo, shCantonment: cantonment, shLot: lot, shHarbour: harbour, shVane: vane,
};
const CACHE = new Map<StrongholdKind, SPlan>();

/** A stronghold's plan (made once). */
export function strongholdPlan(kind: StrongholdKind): SPlan {
  let p = CACHE.get(kind);
  if (!p) { p = MAKERS[kind](); CACHE.set(kind, p); }
  return p;
}

/** The stronghold kind each faction has. */
