// ---- geometry ----------------------------------------------------------------------------------------------------

/** Is (x, z) inside the polygon? */
export function inPoly(poly: [number, number][], x: number, z: number): boolean {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, zi] = poly[i], [xj, zj] = poly[j];
    if ((zi > z) !== (zj > z) && x < ((xj - xi) * (z - zi)) / (zj - zi) + xi) inside = !inside;
  }
  return inside;
}

/** Distance from (x, z) to the segment a-b, and how far along it (0..1). */
function segDist(ax: number, az: number, bx: number, bz: number, x: number, z: number): number {
  const dx = bx - ax, dz = bz - az, L = dx * dx + dz * dz;
  const t = L ? Math.max(0, Math.min(1, ((x - ax) * dx + (z - az) * dz) / L)) : 0;
  return Math.hypot(ax + dx * t - x, az + dz * t - z);
}

/** Is (x, z) in a gate's gap (on its ring)? */
export function inGate(p: SPlan, x: number, z: number, pad = 0): SGate | null {
  for (const g of p.gates) if (Math.hypot(x - g.x, z - g.z) <= g.w / 2 + pad) return g;
  return null;
}

/** Is (x, z) on one of the plan's walls (not in a gate)? */
export function onWall(p: SPlan, x: number, z: number): boolean {
  const t = p.wall.t / 2;
  for (const ring of p.rings) {
    for (let i = 0; i < ring.length; i++) {
      const [ax, az] = ring[i], [bx, bz] = ring[(i + 1) % ring.length];
      if (segDist(ax, az, bx, bz, x, z) <= t) return !inGate(p, x, z);
    }
  }
  return false;
}

/** What of a stronghold stands up and stops a car, in the model's frame: its walls (gates open) and its blocks. */
export function strongholdSolid(kind: StrongholdKind): (x: number, z: number) => boolean {
  const p = strongholdPlan(kind);
  const solid = p.blocks.filter((b) => !b.open);
  return (x, z) => onWall(p, x, z) || solid.some((b) => Math.abs(x - b.x) <= b.w / 2 && Math.abs(z - b.z) <= b.d / 2);
}

/** Is (x, z) inside the stronghold's outer wall? */
export function insidePlan(p: SPlan, x: number, z: number): boolean {
  return inPoly(p.rings[0], x, z);
}

/** Every gate's outward direction (unit, model frame): away from the middle of its ring, across the wall. */
export function gateOut(p: SPlan, g: SGate): [number, number] {
  const ring = p.rings[g.ring];
  // the edge the gate is on: the one nearest its middle
  let best = Infinity, nx = 0, nz = 1;
  for (let i = 0; i < ring.length; i++) {
    const [ax, az] = ring[i], [bx, bz] = ring[(i + 1) % ring.length];
    const d = segDist(ax, az, bx, bz, g.x, g.z);
    if (d < best) {
      best = d;
      const ex = bx - ax, ez = bz - az, L = Math.hypot(ex, ez) || 1;
      nx = ez / L; nz = -ex / L;
    }
  }
  // point it away from inside
  if (inPoly(ring, g.x + nx * 0.5, g.z + nz * 0.5)) { nx = -nx; nz = -nz; }
  return [nx, nz];
}
