/**
 * The fit layer (docs/requests.html): the one place that knows what the player can actually do in the
 * vehicle they are in. Every job offered to the player — a request's step or a load by the roadside —
 * passes through `offerable`, so nothing turns up that this car cannot carry, cannot reach, or cannot
 * finish before its own time limit runs out.
 *
 * Nothing here is random and nothing here is per-frame: a fit is worked out when a load is spawned or
 * a request is rolled. CPU haulers never come through here; they keep the random mix, which is what
 * keeps the island's traffic varied.
 */
import { N, Flag, Surface, World, idx, inB, tileMean } from '../world/tiles';
import { jobNote } from '../net/perfJobs';
import { reachable } from '../world/graph';
import { roadSpeedMul } from '../world/roads';
import { SURFACE_GRIP, roughLift } from './car';
import { URGENCY, type CargoType, type Urgency } from './cargoTypes';
import type { AirDef, LandDef, VehicleDef, WaterDef } from './vehicles';

/** Somewhere a job starts or ends: a cargo Site satisfies this, and so does the player's vehicle. */
export interface Place {
  /** The island it is on, and where on it in that island's own tiles. */
  w: World;
  lx: number; lz: number;
  /** The same spot in world tiles across the lattice. */
  x: number; z: number;
  /** A harbour's port id, or -1 for anywhere on land. */
  port: number;
  /** A door on a canal (world/canals.ts) a boat can tie up at, and whether only a boat can. */
  canal?: boolean;
  waterOnly?: boolean;
  /** On the seabed (world/seabed.ts): only a submarine gets there, sounded, one that dives in `depth` steps of water. */
  seabed?: boolean;
  depth?: number;
}

/** The longest hull that turns in a canal: the small boats; the steamers and yachts keep to the harbours. */
export const CANAL_HULL = 0.7;

/** Can a boat of this length tie up at this place: a harbour, or a door on a canal if it is small enough. */
const boatReaches = (halfLen: number, p: Place): boolean => p.port >= 0 || !!p.seabed || (!!p.canal && halfLen <= CANAL_HULL);

/** The share of its top speed a vehicle really holds: on a road, and across open country. */
const ROAD_SHARE = 0.62, CROSS_SHARE = 0.45;
/** A boat's share of its top speed over open water, a flyer's in the air, and a train's on its line. */
const WATER_SHARE = 0.7, AIR_SHARE = 0.85, RAIL_SHARE = 0.6;
/** Seconds added per stop: pulling up, loading, pulling away. Two stops a job, more for a manifest. */
const STOP_SECONDS = 8;
/** The straight line is optimistic: a road never runs straight. This is what a trip really measures. */
export const WANDER = 1.25;
/**
 * A limit fits when its window is at least this much of the estimate. Below 1 the player would have
 * to beat their own average to arrive; at 1.35 there is room for a wrong turn and a hill.
 */
export const SLACK = 1.35;
/** Samples along a route for the pace estimate: enough to feel a ridge, few enough to be free. */
const SAMPLES = 24;

/** Why a job is not offered, or 'ok'. */
type FitReason = 'ok' | 'class' | 'hold' | 'water' | 'reach' | 'far';

export interface Fit {
  ok: boolean;
  why: FitReason;
  /** One line for the board: why not, in the player's words. */
  text: string;
  /** Tiles the trip really runs, and the seconds it takes at this vehicle's pace. */
  dist: number;
  seconds: number;
  /** The tightest limit whose window fits the trip, or null when none does. */
  urgency: Urgency | null;
}

/** Tiles between two places, across the lattice. */
export const spanOf = (a: Place, b: Place): number => Math.hypot(b.x - a.x, b.z - a.z);

/**
 * How fast this vehicle really covers the ground between two places, in tiles a second. A boat and a
 * flyer ignore the ground; a road vehicle walks the line and feels every road, surface and climb on it.
 */
export function paceOf(def: VehicleDef, a: Place, b: Place): number {
  if (def.kind === 'water') return Math.max(0.2, (def as WaterDef).topSpeed * WATER_SHARE);
  if (def.kind === 'air') return Math.max(0.2, (def as AirDef).topSpeed * AIR_SHARE);
  if (def.kind === 'rail') return Math.max(0.2, def.topSpeed * RAIL_SHARE);
  const s = def as LandDef;
  // across a border the ground on the way is not ours to read: take the open-country share
  if (a.w !== b.w) return Math.max(0.2, s.topSpeed * CROSS_SHARE);
  const w = a.w;
  let seconds = 0, climbed = 0;
  const steps = SAMPLES;
  const dx = (b.lx - a.lx) / steps, dz = (b.lz - a.lz) / steps;
  const tiles = Math.hypot(b.lx - a.lx, b.lz - a.lz) / steps;
  let last = NaN;
  for (let k = 0; k <= steps; k++) {
    const x = Math.floor(a.lx + dx * k), z = Math.floor(a.lz + dz * k);
    if (!inB(x, z)) continue;
    const i = idx(x, z);
    const road = w.road[i];
    let share = road ? ROAD_SHARE * roadSpeedMul(road) : CROSS_SHARE;
    if (road) share *= s.surface?.track ?? 1;
    else {
      share *= (w.flags[i] & Flag.Track) ? (s.surface?.track ?? 1) : (s.surface?.offroad ?? 1);
      share *= SURFACE_GRIP[w.surface[i] as Surface]?.speed ?? 1;
      share = CROSS_SHARE * roughLift(share / CROSS_SHARE, s);
    }
    const here = tileMean(w, i);
    if (!Number.isNaN(last)) climbed += Math.max(0, here - last);
    last = here;
    if (k > 0) seconds += tiles / Math.max(0.15, s.topSpeed * share);
  }
  const length = Math.hypot(b.lx - a.lx, b.lz - a.lz);
  if (seconds <= 0 || length <= 0) return Math.max(0.2, s.topSpeed * CROSS_SHARE);
  // the climb, in steps a tile, told the way the car's own uphill penalty reads it
  const grade = climbed / Math.max(1, length);
  const pace = (length / seconds) * Math.max(0.35, 1 - s.uphillPenalty * grade);
  return Math.max(0.2, pace);
}

/**
 * Seconds this vehicle needs for the trip, stops included. `dist` overrides the straight line when a
 * path is known; `stops` is two for a job, and a manifest's own count for a run (docs/manifests.html).
 */
function secondsFor(def: VehicleDef, a: Place, b: Place, dist?: number, stops = 2): number {
  const run = dist ?? spanOf(a, b) * WANDER;
  return run / paceOf(def, a, b) + stops * STOP_SECONDS;
}

/** The limits a load may come with, tightest first. */
const LADDER: Urgency[] = ['urgent', 'timely', 'standard', 'relaxed', 'none'];

/**
 * The tightest limit this vehicle can actually meet over this trip, or null when even `none` can't be:
 * a load's window is its type's own wait scaled by the limit, so a long trip walks down the ladder.
 */
export function limitFor(t: CargoType, seconds: number): Urgency | null {
  const allowed = t.urgency ?? LADDER;
  const wait = (t.ttl[0] + t.ttl[1]) / 2;
  for (const u of LADDER) {
    if (!allowed.includes(u)) continue;
    const span = URGENCY[u].ttl;
    if (!Number.isFinite(span)) return u;
    if (wait * span >= seconds * SLACK) return u;
  }
  return null;
}

// ---- reach: can this vehicle get there at all ----------------------------------------------------

interface Flood { seen: Uint8Array; from: number; revision: number }
const FLOODS = new WeakMap<World, Map<string, Flood[]>>();
/** Floods kept per island per vehicle: one for each road network a carrier of that model stands on. */
const FLOODS_KEPT = 6;

/** The island's revision as far as reach goes: cosmetic growth (boards, storeys, claimed land) left out. */
const reachRev = (w: World): number => w.revision - (w.cosmetic ?? 0);

/**
 * Every tile this vehicle can drive to from where it stands, flooded once per island per vehicle and
 * kept until the world changes under it (a road laid, a tile bulldozed). A flood over 65k tiles costs
 * 60–150 ms (crossBlock on every edge), and it used to be thrown away whenever the player moved onto
 * another tile, so the director's rank before an offer re-flooded and the frame hitched (Oct 2026).
 * Now a start tile the last flood already reached keeps it: everything reachable from there is in it.
 * It can over-count only after a one-way drop (steep ground is passable downhill only), and then it is
 * an offer's reach that is generous, never a road that is wrong.
 *
 * Several are kept per vehicle (Oct 2026 playtest): the cargo demand asks from every carrier's own
 * place (the player, the fleet, rivals, local firms), and with one flood per model two carriers on
 * road networks that don't meet threw each other's away, re-flooding every demand tick (100–300 ms).
 */
/** Console: how often a reach question was answered from a kept flood, and the floods made (pr.reachStats). */
export const REACH_STATS = { hits: 0, floods: 0, ms: 0, recent: [] as { w: string; def: string; from: number; kept: number; blocked: number; road: number }[] };

/**
 * New floods allowed before reachBudget() is called again (null: no limit). The cargo demand sets one a turn
 * (11 Nov 2026 perf audit: a demand turn walked every carrier, each new model, county or road network a fresh
 * 60–150 ms flood, three to five of them in one frame); a question that would need another is answered "not
 * now" (false, reachDeferred() true) and asked again next turn.
 */
let floodsLeft: number | null = null, deferred = false;
export function reachBudget(n: number | null): void { floodsLeft = n; deferred = false; }
/** Did a reach question go unanswered under the budget since reachBudget was set? */
export function reachDeferred(): boolean { return deferred; }

function flood(w: World, def: LandDef, from: number): Uint8Array | null {
  let per = FLOODS.get(w);
  if (!per) FLOODS.set(w, (per = new Map()));
  const rev = reachRev(w);
  let list = per.get(def.id);
  if (list && list.some((f) => f.revision !== rev)) list = list.filter((f) => f.revision === rev);
  if (!list) list = [];
  // a vehicle often stands on a tile marked blocked (its nose in a building's edge, a yard, a kerb) that
  // no flood can ever reach: asked from there, every new spot was a whole new flood (1 s frames in the
  // Oct 2026 playtest). The open tiles round it answer for it, and a new flood starts from the nearest
  const starts = startsNear(w, from);
  const k = list.findIndex((f) => f.from === from || starts.some((t) => f.seen[t]));
  if (k >= 0) {
    REACH_STATS.hits++;
    const have = list[k];
    if (k > 0) { list.splice(k, 1); list.unshift(have); }
    per.set(def.id, list);
    return have.seen;
  }
  if (floodsLeft !== null) {
    if (floodsLeft <= 0) { deferred = true; return null; }
    floodsLeft--;
  }
  const t0 = performance.now();
  const seen = reachable(w, starts[0] ?? from, def);
  REACH_STATS.floods++;
  { const ms = performance.now() - t0; REACH_STATS.ms += ms; jobNote('reach flood', ms, t0); }
  REACH_STATS.recent.push({ w: w.name, def: def.id, from, kept: list.length, blocked: w.blocked[from], road: w.road[from] });
  if (REACH_STATS.recent.length > 40) REACH_STATS.recent.shift();
  list.unshift({ seen, from, revision: rev });
  if (list.length > FLOODS_KEPT) list.length = FLOODS_KEPT;
  per.set(def.id, list);
  return seen;
}

/** The tile itself if it is open, else the open tiles within two of it, nearest first. */
function startsNear(w: World, from: number): number[] {
  if (!w.blocked[from]) return [from];
  const x = from % N, z = (from - x) / N, out: [number, number][] = [];
  for (let dz = -2; dz <= 2; dz++) for (let dx = -2; dx <= 2; dx++) {
    if ((!dx && !dz) || !inB(x + dx, z + dz)) continue;
    const i = idx(x + dx, z + dz);
    if (!w.blocked[i]) out.push([i, dx * dx + dz * dz]);
  }
  return out.sort((a, b) => a[1] - b[1]).map((p) => p[0]);
}

/** Throw away every cached flood on an island: a road was laid, or something was bulldozed. */
export function forgetReach(w: World): void {
  FLOODS.delete(w);
}

const CHANGED = new WeakMap<World, { rev: number; cos: number }>();
/**
 * The island changed (main.ts afterWorldChange): its floods go unless only cosmetic growth moved (boards, storeys,
 * claimed land: reachRev). Every step a town grew threw them all away before (11 Nov 2026 perf audit), and the
 * cargo demand flooded the island again for every carrier on its next turn.
 */
export function worldChangedReach(w: World): void {
  const was = CHANGED.get(w), now = { rev: w.revision, cos: w.cosmetic ?? 0 };
  CHANGED.set(w, now);
  if (was && now.rev - now.cos === was.rev - was.cos && now.cos !== was.cos) return;
  FLOODS.delete(w);
}

/**
 * Can this vehicle, standing at `at`, get to `p`? A boat asks only about harbours, a flyer goes
 * anywhere, and a road vehicle asks the flood. Across a border it asks the same question the cargo
 * system does: a causeway or a county line for a road vehicle, else a harbour at each end.
 */
export function canReach(def: VehicleDef, at: Place, p: Place): boolean {
  if (def.kind === 'air') return true;
  if (def.kind === 'water') return boatReaches(def.halfLen, p);
  if (p.waterOnly) return false;
  if (def.kind === 'rail') return true;
  if (p.w !== at.w) return true;   // the crossing itself is the cargo system's test, not the flood's
  const a = tileOf(at), b = tileOf(p);
  if (a < 0 || b < 0) return false;
  const seen = flood(p.w, def as LandDef, a);
  if (!seen) return false;
  if (seen[b]) return true;
  // goods sit at the kerb; a tile either side of it is close enough to call reached
  const x = b % N, z = (b - x) / N;
  for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    if (inB(x + dx, z + dz) && seen[idx(x + dx, z + dz)]) return true;
  }
  return false;
}

const tileOf = (p: Place): number => {
  const x = Math.floor(p.lx), z = Math.floor(p.lz);
  return inB(x, z) ? idx(x, z) : -1;
};

// ---- the one test every offer passes ------------------------------------------------------------

/**
 * May this job be offered to the player? `at` is where the player is now, which is what reach is
 * measured from. The answer carries its own reason so the board can print it.
 *
 * `anyHold` sets aside the two questions about the hold, which is what a town request wants while it
 * is being filled: a chain is posted whatever is being driven and then greyed on the board with the
 * reason, so the board can say go and get a bigger vehicle. Reach and distance are never set aside —
 * nothing is ever asked for that cannot be got to.
 */
export function offerable(def: VehicleDef, at: Place, from: Place, to: Place, t: CargoType, anyHold = false): Fit {
  const dist = spanOf(from, to) * WANDER;
  const seconds = secondsFor(def, from, to, dist);
  const no = (why: FitReason, text: string): Fit => ({ ok: false, why, text, dist, seconds, urgency: null });
  if (!anyHold && !def.holds.includes(t.cls)) return no('class', `${def.name} can’t carry ${t.name.toLowerCase()}`);
  if (!anyHold && t.units > def.capacity) return no('hold', `needs a hold of ${t.units} · your ${def.name} holds ${def.capacity}`);
  if (def.kind === 'water' && (!boatReaches(def.halfLen, from) || !boatReaches(def.halfLen, to))) return no('water', `${def.name} only reaches the harbours${def.halfLen <= CANAL_HULL ? ' and the canals' : ''}`);
  if (def.kind !== 'water' && def.kind !== 'air' && (from.waterOnly || to.waterOnly)) return no('water', 'only a boat reaches that door on the canal');
  if (t.sea && def.kind !== 'water') return no('water', `${t.name} go by boat`);
  // the seabed: a submarine's, and only one that dives in water that deep (docs/underwater.html)
  const down = (p: Place) => !p.seabed || (def.kind === 'water' && !!def.dive && (p.depth ?? 0) >= def.dive.need);
  if (!down(from) || !down(to)) return no('water', def.kind === 'water' && def.dive ? `too deep down for a ${def.name}` : 'only a submarine reaches the seabed');
  if (!canReach(def, at, from)) return no('reach', `no way to the pick-up in a ${def.name}`);
  if (!canReach(def, at, to)) return no('reach', `no way there in a ${def.name}`);
  const u = limitFor(t, seconds);
  if (!u) return no('far', `too far for a ${def.name}: ${Math.round(dist)} tiles`);
  return { ok: true, why: 'ok', text: '', dist, seconds, urgency: u };
}

// ---- how far along the player is ----------------------------------------------------------------

/** What the stage is read from: numbers the save and the fleet already hold. */
export interface Progress {
  delivered: number;
  cash: number;
  /** Everything ever earned, which never falls when money is spent. */
  earned: number;
  units: number;
  drivers: number;
  /** A boat or a flyer owned: the vehicles the hard places need. */
  seaOrAir: boolean;
  parts: boolean;
  /** Towns the player's own trade graduated to a big city or better; never ones generated that way. */
  bigCities: number;
}

/**
 * How far along the player is, 0 to 4. A stage never falls: it reads the lifetime counters, not what
 * is in the garage this minute. What the player is *driving* is the fit layer's business, not this one.
 */
export function stageOf(p: Progress): number {
  let stage = 0;
  if (p.delivered >= 15 || p.earned >= 2000 || p.units >= 2 || p.parts) stage = 1;
  if (p.delivered >= 60 || p.earned >= 10000 || p.drivers >= 1) stage = 2;
  if (p.delivered >= 200 || p.earned >= 40000 || p.units >= 3 || p.seaOrAir) stage = 3;
  if (p.delivered >= 600 || p.earned >= 150000 || p.bigCities >= 1) stage = 4;
  return stage;
}

/** The stage's own name, for the board. */
export const STAGE_LABEL = ['First hour', 'Settled in', 'Company', 'Established', 'Late'];
