/**
 * The camera sent somewhere far (another player followed, an HQ looked at, an event's place): until the county
 * there is built and its ground drawn, a card in the middle of the screen says so with a bar, rather than an
 * empty blue screen (the user, 28 Oct 2026: players took the wait for a glitch and quit). It only comes up for
 * a county not yet in memory; one already there (a vehicle of yours next door) never shows it.
 */

/** Seconds the wait must last before the card comes up (a county built in a moment shows nothing). */
const SHOW_AFTER = 0.35;
/** The bar's share for building the county; the rest is the ground being drawn. */
const BUILD_SHARE = 0.6;
/** Seconds a county usually takes to build, for the bar's pace while it does (the worker says nothing). */
const BUILD_TYPICAL = 5;
/** Chunks round the target still to draw at which the ground counts as there, and the longest the drawing is waited for. */
const DRAWN_AT = 1, DRAW_CAP = 10;
/** Tiles round the target whose ground is waited for (render/stream.ts pendingNear): what the camera looks at. */
export const TRAVEL_NEAR = 64;
/** Seconds after the county arrives before its ground counts as drawn (its chunks take a frame or two to be queued). */
const DRAW_MIN = 0.3;

export interface TravelWant {
  /** Where to, for the card: a player's name, an HQ's, an event's. */
  name: string;
  /** Which county the camera is going to ("cx,cz"). */
  cell: string;
  /** Is it in memory yet. */
  built: boolean;
  /** Chunks of ground round the target still waiting to be drawn (render/stream.ts pendingNear, TRAVEL_NEAR). */
  pending: number;
}

export class TravelLoading {
  private el = document.createElement('div');
  private title = document.createElement('b');
  private sub = document.createElement('span');
  private fill = document.createElement('i');
  /** The wait under way: its county, how long, whether the county had to be built, the most chunks seen. */
  private cell = '';
  private t = 0;
  private drawT = 0;
  private needed = false;
  private most = 0;
  private shown = 0;
  /** This county is there and drawn: nothing to wait for until the camera goes somewhere else. */
  private done = false;

  constructor() {
    this.el.id = 'travel-load';
    this.el.className = 'hud chip';
    this.el.hidden = true;
    this.el.setAttribute('role', 'status');
    const bar = document.createElement('div');
    bar.className = 'bar';
    bar.append(this.fill);
    this.el.append(this.title, this.sub, bar);
    document.body.append(this.el);
  }

  /** A far county is being waited for (built, then its ground drawn): the frame can spend more on drawing it (main.ts). */
  get waiting(): boolean { return !!this.cell && this.needed && !this.done; }

  /** Every frame: where the camera is being taken, or null when it is on the player (or a map is up). */
  update(dt: number, want: TravelWant | null): void {
    if (!want) { this.reset(''); this.hide(); return; }
    if (want.cell !== this.cell) this.reset(want.cell);
    if (this.done) { this.hide(); return; }
    this.t += dt;
    if (!want.built) this.needed = true;
    // a county already in memory: nothing to show
    if (!this.needed) { this.done = true; this.hide(); return; }
    let p: number, line: string;
    if (!want.built) {
      p = BUILD_SHARE * (1 - Math.exp(-this.t / BUILD_TYPICAL));
      line = 'Building the county';
    } else {
      this.drawT += dt;
      this.most = Math.max(this.most, want.pending);
      const drawn = this.most ? 1 - want.pending / this.most : 1;
      p = BUILD_SHARE + (1 - BUILD_SHARE) * drawn;
      line = 'Drawing the ground';
      if ((want.pending <= DRAWN_AT && this.drawT > DRAW_MIN) || this.drawT > DRAW_CAP) { this.done = true; this.hide(); return; }
    }
    if (this.t < SHOW_AFTER) return;
    // never backwards
    this.shown = Math.max(this.shown, p);
    const title = want.name ? `Heading to ${want.name}…` : 'On the way…';
    if (this.title.textContent !== title) this.title.textContent = title;
    const sub = `${line} · ${Math.round(this.shown * 100)}%`;
    if (this.sub.textContent !== sub) this.sub.textContent = sub;
    this.fill.style.width = `${(this.shown * 100).toFixed(1)}%`;
    if (this.el.hidden) this.el.hidden = false;
  }

  private reset(cell: string): void {
    this.cell = cell;
    this.t = this.drawT = this.most = this.shown = 0;
    this.needed = this.done = false;
  }

  private hide(): void { if (!this.el.hidden) this.el.hidden = true; }
}
