import { hex, scale, type RGB } from '../../../world/biomes';
import type { Building, BuildingKind } from '../../../world/tiles';
import type { Rng } from '../../../world/rng';
import { FLOOR } from '../../../world/towns';
import { COOL_GLOW, GLASS_LIGHT, METAL, RED_LIGHT, WARM_GLOW, pick, windowSched, type Draw, type Kit, type P3 } from '../kit';

/**
 * Alternative models for the glass spire (render/buildings/themes.ts), the tallest tower a big city of any style
 * builds: a modern downtown can have half a dozen, and one model six times over read as one skyline copied. Each
 * stands on the spire's 2 × 2 lot (no SHAPES entry: the whole lot is solid) and reaches about the spire's height
 * (world/towns.ts buildingHeight), but has its own massing, crown, curtain wall and tint: a twisting stack, a
 * bronze setback tower, a slant-topped tower on stilts, twin blades joined by a sky bridge and a tapering diagrid,
 * and seven after famous towers: Taipei 101, the Petronas Towers, One World Trade Center, the Shard, the Shanghai
 * World Financial Center, Salesforce Tower and 432 Park Avenue. Picked from the seed like any kind's alternatives.
 */

const TAU = Math.PI * 2;
const PALE = hex(0xdfe4e8), QUARTZ = hex(0xf4f2ec), WHITE_STONE = hex(0xf6f4ee);
const BEACON: [number, number, number] = [0, 30, 2.8];

/** The spire's own height for this many floors, and the podium's top. */
const shaftH = (b: Building): number => Math.max(30, b.floors) * FLOOR * 0.7;
const PODIUM = 0.38;

/** The plinth every one of them stands on, with an awning over the doors and a lit lobby. */
function podium(k: Kit, base: number, stone: RGB, trim: RGB): void {
  k.box(0, 0, 0, base + 0.2, 0.34, base + 0.2, stone, QUARTZ);
  k.box(0, 0.34, 0, base + 0.26, 0.04, base + 0.26, trim);
  k.box(0, 0.1, base / 2 + 0.16, base * 0.5, 0.04, 0.14, trim);
  k.glowBox(0, 0.02, base / 2 + 0.105, base * 0.4, 0.07, 0.01, GLASS_LIGHT, [16, 30, 1.3], COOL_GLOW);
}

/** The aircraft light on the very top. */
const beacon = (k: Kit, y: number): void => k.glowBox(0, y, 0, 0.06, 0.06, 0.06, hex(0xe2412f), BEACON, RED_LIGHT);

/**
 * A curtain wall's lit floors after dark: a strip across each face every `step` floors, each on its own office hours,
 * in `day` by day, which a shade off the glass makes read as the floor lines.
 */
function litFloors(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, h: number, day: RGB, step = 2, faces: readonly number[] = [0, 1, 2, 3]): void {
  const sh = FLOOR * Math.min(0.5, step * 0.32);
  for (let fy = y + FLOOR * 0.25; fy + sh < y + h - 0.02; fy += FLOOR * step) {
    for (const face of faces) {
      const s = windowSched('office', r);
      if (face === 1 || face === 3) k.pane(x, fy, z + (face === 1 ? d / 2 : -d / 2), w * 0.88, sh, face, day, s, COOL_GLOW);
      else k.pane(x + (face === 0 ? w / 2 : -w / 2), fy, z, d * 0.88, sh, face, day, s, COOL_GLOW);
    }
  }
}

/** Mullions: `n` bays a face, a thin rib between each, the full height. */
function fins(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, n: number, col: RGB): void {
  for (let i = 1; i < n; i++) {
    const ox = -w / 2 + (w * i) / n, oz = -d / 2 + (d * i) / n;
    for (const s of [-1, 1]) {
      k.box(x + ox, y, z + s * d / 2, 0.028, h, 0.028, col);
      k.box(x + s * w / 2, y, z + oz, 0.028, h, 0.028, col);
    }
  }
}

/**
 * The turning tower: a stack of square floor plates of pale green-blue glass, each a few degrees round from the one
 * below, so the whole tower makes a quarter turn (one way or the other) from podium to roof; a white slab edge at
 * every plate, and a slim mast above.
 */
const twistTower: Draw = (k, W, D, b, r) => {
  const floors = Math.max(30, b.floors), H = shaftH(b), base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0x6fb8b0, 0x8ec4dc, 0x9fb4c8, 0x7aa8c8]), plate = hex(0xeef0ee);
  podium(k, base, PALE, WHITE_STONE);
  // the square's corners swing out to half its diagonal: inside the lot at any angle
  const n = Math.max(12, Math.round(floors / 2.5)), h = H / n, s = Math.min(1.3, base * 0.78);
  const turn = (r() < 0.5 ? 1 : -1) * (Math.PI / 2);
  let y = PODIUM;
  for (let i = 0; i < n; i++) {
    k.turned((i / (n - 1)) * turn, () => {
      k.box(0, y, 0, s, h - 0.03, s, glass, scale(glass, 1.1));
      k.box(0, y + h - 0.03, 0, s + 0.05, 0.03, s + 0.05, plate);
      litFloors(k, r, 0, y, 0, s, s, h - 0.03, scale(glass, 0.86), 2.5);
    });
    y += h;
  }
  k.turned(turn, () => k.box(0, y, 0, s * 0.62, 0.22, s * 0.62, plate));
  k.cyl(0, y + 0.22, 0, 0.03, 0.75, METAL, 5);
  beacon(k, y + 0.97);
};

/**
 * The setback tower: smoked bronze (or green, or grey) glass in three tiers, each narrower than the one below, dark
 * mullions up every face, a lit band under each setback's ledge and a glass pyramid on top that glows at night.
 */
const setbackTower: Draw = (k, W, D, b, r) => {
  const H = shaftH(b), base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0xa8865a, 0x8a9a84, 0x8a8a96, 0xb89a72]), frame = pick(r, [0x3a3a3f, 0x4e4236, 0x2e3a40]);
  const light = pick(r, [0xffe0a0, 0xfff4e0]);
  podium(k, base, hex(0x5a5a60), frame);
  const tiers: [number, number][] = [[base * 0.94, 0.5], [base * 0.74, 0.3], [base * 0.52, 0.2]];
  let y = PODIUM;
  for (const [w, f] of tiers) {
    const h = (H - 0.5) * f;
    k.box(0, y, 0, w, h, w, glass, scale(glass, 0.8));
    fins(k, 0, y, 0, w, w, h, w > 1 ? 5 : 3, frame);
    litFloors(k, r, 0, y, 0, w, w, h - 0.14, scale(glass, 0.85), 2);
    k.glowBox(0, y + h - 0.12, 0, w + 0.012, 0.1, w + 0.012, scale(glass, 1.15), [17, 30, 2.2], light);
    k.box(0, y + h, 0, w + 0.07, 0.05, w + 0.07, frame);
    y += h + 0.05;
  }
  // the pyramid of glass, lit from inside
  const w = base * 0.52, ph = 0.55, I: P3 = [0, y + ph / 4, 0], A: P3 = [0, y + ph, 0];
  const c: P3[] = [[-w / 2, y, -w / 2], [w / 2, y, -w / 2], [w / 2, y, w / 2], [-w / 2, y, w / 2]];
  for (let i = 0; i < 4; i++) k.glowTri(c[i], c[(i + 1) % 4], A, I, scale(glass, 1.25), [17, 30, 2.4], light);
  k.cyl(0, y + ph, 0, 0.022, 0.42, METAL, 5);
  beacon(k, y + ph + 0.42);
};

/**
 * The slant top: a square tower lifted on four great columns, one under the middle of each face, over a glass
 * lobby; ribbon windows of glass between white aluminium bands all the way up, and the roof cut off at a steep
 * slant, its sloping face lit after dark.
 */
const slantTower: Draw = (k, W, D, b, r) => {
  const H = shaftH(b), base = Math.min(W, D) - 0.3, s = base * 0.86;
  const skin = pick(r, [0xe8ecee, 0xd8dcd8, 0xc8ccd2]), glass = pick(r, [0x50708a, 0x6a90a8, 0x4e7a7a]);
  podium(k, base, PALE, WHITE_STONE);
  // the columns and the lobby between them
  const lift = 0.55;
  for (const [sx, sz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    k.box(sx * (s / 2 - 0.09), PODIUM, sz * (s / 2 - 0.09), sx ? 0.18 : 0.3, lift, sz ? 0.18 : 0.3, skin);
  }
  k.box(0, PODIUM, 0, s * 0.46, lift, s * 0.46, glass, skin);
  k.glowBox(0, PODIUM + 0.04, 0, s * 0.47, lift * 0.6, s * 0.47, glass, [16, 30, 1.3], COOL_GLOW);
  // the shaft, white, with the glass in ribbons round every floor
  const y0 = PODIUM + lift, slant = s * 0.62, hs = H + 0.3 - lift - slant;
  k.box(0, y0, 0, s, hs, s, skin);
  litFloors(k, r, 0, y0, 0, s, s, hs, glass, 1);
  // the slanted crown: the high side to one of the four quarters, by the seed
  const y1 = y0 + hs;
  k.turned(Math.floor(r() * 4) * (Math.PI / 2), () => {
    k.wedge(0, y1, 0, s, slant, s, skin);
    const e = 0.012, I: P3 = [0, y1, 0];
    k.glowQuad([-s / 2 + 0.05, y1 + e, -s / 2 + 0.05], [s / 2 - 0.05, y1 + e, -s / 2 + 0.05],
      [s / 2 - 0.05, y1 + slant - 0.05 + e, s / 2 - 0.05], [-s / 2 + 0.05, y1 + slant - 0.05 + e, s / 2 - 0.05], I, glass, [17, 30, 2.4], WARM_GLOW);
    k.cyl(0, y1 + slant * 0.5, s * 0.25, 0.022, slant * 0.5 + 0.35, METAL, 5);
  });
  beacon(k, y1 + slant + 0.36);
};

/**
 * The twin blades: two slim slabs of dark glass side by side, one taller, their tops sheared off outward like a pair
 * of horns, a lit sky bridge between them and a strip of light up each one's outer edge after dark.
 */
const twinBlades: Draw = (k, W, D, b, r) => {
  const H = shaftH(b) + 0.4, base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0x3e5a70, 0x4a6670, 0x56607a, 0x40606a]), accent = pick(r, [0x7fe0ff, 0xffffff, 0xb0ffd8, 0xffc0e8]);
  podium(k, base, hex(0xc8ccd0), WHITE_STONE);
  const bw = base * 0.4, bd = base * 0.86, gap = base * 0.1, tall = r() < 0.5 ? 1 : -1;
  for (const sx of [-1, 1]) {
    const x = sx * (gap / 2 + bw / 2), h = sx === tall ? H - 0.45 : (H - 0.45) * 0.78;
    k.box(x, PODIUM, 0, bw, h, bd, glass, scale(glass, 1.2));
    fins(k, x, PODIUM, 0, bw, bd, h, 3, scale(glass, 1.45));
    litFloors(k, r, x, PODIUM, 0, bw, bd, h, scale(glass, 1.3), 2);
    for (const sz of [-1, 1]) k.glowBox(x + sx * (bw / 2 - 0.015), PODIUM, sz * (bd / 2 - 0.015), 0.04, h, 0.04, METAL, [17, 30, 2.5], accent);
    // the sheared top, high on the outside
    k.within(x, 0, sx * (Math.PI / 2), () => k.wedge(0, PODIUM + h, 0, bd, 0.45, bw, scale(glass, 1.15)));
  }
  // the sky bridge, three fifths of the way up the lower blade
  const yb = PODIUM + (H - 0.45) * 0.78 * 0.6;
  k.box(0, yb, 0, gap + 0.04, 0.24, bd * 0.36, scale(glass, 0.8));
  k.glowBox(0, yb + 0.05, 0, gap + 0.05, 0.12, bd * 0.37, glass, [16.5, 30, 2], accent);
  // the beacon at the taller blade's high edge
  const t = (bw - 0.05) / bw;
  k.glowBox(tall * (gap / 2 + bw - 0.05), PODIUM + H - 0.45 + 0.45 * t, 0, 0.06, 0.06, 0.06, hex(0xe2412f), BEACON, RED_LIGHT);
};

/**
 * The diagrid: an eight-sided tower tapering gently as it rises, its glass held in a lattice of diagonals that cross
 * on every face, tier by tier; a ring at the crown round a lit lantern.
 */
const diagridTower: Draw = (k, W, D, b, r) => {
  const H = shaftH(b) + 0.2, base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0x5f9a86, 0x4f7d99, 0x7a9aa8, 0x6a8aa0]), grid = pick(r, [0xf0f0ec, 0x4a4038, 0xb9c2c9]);
  podium(k, base, PALE, WHITE_STONE);
  const R0 = base * 0.5, taper = 0.78, tiers = Math.max(5, Math.round(H / 1.6)), th = (H - 0.3) / tiers, seg = 8;
  const rad = (t: number) => R0 * (1 - (1 - taper) * t);
  const at = (j: number, rr: number, y: number): P3 => [Math.cos((j / seg) * TAU) * rr, y, Math.sin((j / seg) * TAU) * rr];
  // turned an eighth of a half turn, so flat faces, not corners, look down the street
  k.turned(Math.PI / seg, () => {
    for (let i = 0; i < tiers; i++) {
      const y0 = PODIUM + i * th, y1 = y0 + th, r0 = rad(i / tiers), r1 = rad((i + 1) / tiers);
      k.band(0, 0, y0, r0, y1, r1, seg, glass);
      for (let j = 0; j < seg; j++) {
        // the lit floors behind the lattice, two bands a tier
        for (const f of [0.18, 0.62]) {
          const ya = y0 + th * f, yb = ya + th * 0.22, ra = (r0 + (r1 - r0) * f) * 1.004, rb = (r0 + (r1 - r0) * (f + 0.22)) * 1.004;
          k.glowQuad(at(j, ra, ya), at(j + 1, ra, ya), at(j + 1, rb, yb), at(j, rb, yb), [0, (ya + yb) / 2, 0], scale(glass, 0.9), windowSched('office', r), COOL_GLOW);
        }
        // the diagonals, crossing on the face
        const g0 = r0 * 1.012, g1 = r1 * 1.012;
        k.bar(at(j, g0, y0), at(j + 1, g1, y1), 0.018, grid);
        k.bar(at(j + 1, g0, y0), at(j, g1, y1), 0.018, grid);
      }
      k.band(0, 0, y1 - 0.02, r1 * 1.015, y1 + 0.02, r1 * 1.015, seg, grid);
    }
    const yt = PODIUM + tiers * th, rt = rad(1);
    k.band(0, 0, yt, rt * 1.03, yt + 0.24, rt * 1.03, seg, grid, grid);
    k.glowBox(0, yt, 0, rt * 1.1, 0.2, rt * 1.1, scale(glass, 1.2), [17, 30, 2.4], COOL_GLOW);
  });
  const yt = PODIUM + tiers * th;
  k.cyl(0, yt + 0.2, 0, 0.025, 0.36, METAL, 5);
  beacon(k, yt + 0.56);
};

// ---- after famous towers -----------------------------------------------------------------------------------------

/** A plan: corners round the tower's axis, in local (x, z). */
type Ring = [number, number][];
const square = (s: number, t = s): Ring => [[-s / 2, -t / 2], [s / 2, -t / 2], [s / 2, t / 2], [-s / 2, t / 2]];
/** A square with its corners rounded off (a superellipse), `n` points. */
const squircle = (s: number, n = 16): Ring => Array.from({ length: n }, (_, i) => {
  const a = ((i + 0.5) / n) * TAU, c = Math.cos(a), si = Math.sin(a);
  return [Math.sign(c) * Math.sqrt(Math.abs(c)) * s / 2, Math.sign(si) * Math.sqrt(Math.abs(si)) * s / 2];
});
/** An eight-pointed star of two squares laid over each other, `R` to its points. */
const star8 = (R: number): Ring => Array.from({ length: 16 }, (_, i) => {
  const a = (i / 16) * TAU, rr = i % 2 ? R * 0.84 : R;
  return [Math.cos(a) * rr, Math.sin(a) * rr];
});
const lerpRing = (a: Ring, b: Ring, t: number, s = 1): Ring => a.map(([x, z], i) => [(x + (b[i][0] - x) * t) * s, (z + (b[i][1] - z) * t) * s]);

/** The walls between plan `a` at y0 and plan `b` (as many corners) at y1, both round the axis; `cap` roofs it in. */
function loft(k: Kit, y0: number, a: Ring, y1: number, b: Ring, col: RGB, cap?: RGB): void {
  const n = a.length, I: P3 = [0, (y0 + y1) / 2, 0];
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    k.quad([a[i][0], y0, a[i][1]], [a[j][0], y0, a[j][1]], [b[j][0], y1, b[j][1]], [b[i][0], y1, b[i][1]], col, I);
  }
  if (cap) for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    k.tri([0, y1, 0], [b[i][0], y1, b[i][1]], [b[j][0], y1, b[j][1]], cap, [0, y0, 0]);
  }
}

/** litFloors for a lofted wall: a lit ribbon round the plan every `step` floors, just proud of the glass. */
function loftLights(k: Kit, r: Rng, y0: number, a: Ring, y1: number, b: Ring, step: number, day: RGB): void {
  const h = y1 - y0, sh = FLOOR * Math.min(0.5, step * 0.32);
  for (let fy = y0 + FLOOR * 0.25; fy + sh < y1 - 0.02; fy += FLOOR * step) {
    const p = lerpRing(a, b, (fy - y0) / h, 1.006), q = lerpRing(a, b, (fy + sh - y0) / h, 1.006);
    for (let i = 0; i < p.length; i++) {
      const j = (i + 1) % p.length;
      k.glowQuad([p[i][0], fy, p[i][1]], [p[j][0], fy, p[j][1]], [q[j][0], fy + sh, q[j][1]], [q[i][0], fy + sh, q[i][1]], [0, fy + sh / 2, 0], day, windowSched('office', r), COOL_GLOW);
    }
  }
}

/**
 * After Taipei 101: a tall trunk of green glass tapering in, a round charm on each face, then eight flared sections
 * stacked one on another, each wider at its top like a bamboo stem's joints, under a stepped pinnacle and a spire.
 */
const taipei101: Draw = (k, W, D, b, r) => {
  const H = shaftH(b) + 0.3, base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0x5f9a8a, 0x4f8a86, 0x6a9a9a]), trim = scale(glass, 0.7);
  podium(k, base, PALE, WHITE_STONE);
  const trunkH = H * 0.24, t0 = square(base * 0.78), t1 = square(base * 0.66);
  let y = PODIUM;
  loft(k, y, t0, y + trunkH, t1, glass, trim);
  loftLights(k, r, y, t0, y + trunkH, t1, 2, scale(glass, 0.85));
  for (let f = 0; f < 4; f++) k.turned((f * Math.PI) / 2, () => k.face(0, y + trunkH * 0.55, base * 0.36 + 0.02, 0.12, trim, 12));
  y += trunkH;
  const n = 8, sh = (H * 0.64) / n, lo = square(base * 0.6), hi = square(base * 0.74);
  for (let i = 0; i < n; i++) {
    loft(k, y, lo, y + sh, hi, glass, trim);
    loftLights(k, r, y, lo, y + sh, hi, 2, scale(glass, 0.85));
    y += sh;
  }
  k.box(0, y, 0, base * 0.42, 0.22, base * 0.42, glass, trim);
  k.box(0, y + 0.22, 0, base * 0.27, 0.18, base * 0.27, glass, trim);
  k.glowBox(0, y + 0.24, 0, base * 0.28, 0.1, base * 0.28, glass, [17, 30, 2.2], hex(0xfff0c8));
  k.cyl(0, y + 0.4, 0, 0.035, 0.7, METAL, 6);
  beacon(k, y + 1.1);
};

/**
 * After the Petronas Towers: twin towers of stainless steel and glass on an eight-pointed star plan, banded all the way
 * up, stepping in near the top to a pinnacle, joined by a two-storey sky bridge on its splayed legs.
 */
const petronas: Draw = (k, W, D, b, r) => {
  const H = shaftH(b), base = Math.min(W, D) - 0.3;
  const steel = pick(r, [0xc8ccd0, 0xd6d8da]), glass = pick(r, [0x6a8aa0, 0x7a94a8, 0x5e7e94]);
  podium(k, base, PALE, WHITE_STONE);
  const R = base * 0.24, cx = base * 0.27;
  const tiers: [number, number][] = [[0.62, 1], [0.12, 0.9], [0.08, 0.8], [0.06, 0.68], [0.05, 0.55]];
  for (const sx of [-1, 1]) k.within(sx * cx, 0, 0, () => {
    let y = PODIUM;
    for (const [f, sc] of tiers) {
      const h = H * f, ring = star8(R * sc), band = star8(R * sc * 1.012);
      loft(k, y, ring, y + h, ring, glass, steel);
      if (f > 0.3) loftLights(k, r, y, ring, y + h, ring, 3, scale(glass, 0.9));
      for (let by = y + 0.3; by < y + h - 0.1; by += 0.62) loft(k, by, band, by + 0.05, band, steel);
      y += h;
    }
    k.glowBox(0, y, 0, R * 0.7, 0.12, R * 0.7, steel, [17, 30, 2.4], hex(0xfff4e0));
    k.cone(0, y + 0.12, 0, R * 0.42, 0.5, steel, 8);
    k.cyl(0, y + 0.5, 0, 0.018, 0.55, METAL, 5);
    beacon(k, y + 1.05);
  });
  const yb = PODIUM + H * 0.42, span = 2 * (cx - R * 0.84) + 0.08;
  k.box(0, yb, 0, span, 0.12, 0.14, steel);
  k.glowBox(0, yb + 0.03, 0, span + 0.01, 0.05, 0.15, glass, [16.5, 30, 2], COOL_GLOW);
  for (const sx of [-1, 1]) k.bar([sx * (cx - R * 0.8), yb - 0.6, 0], [sx * 0.05, yb, 0], 0.018, steel);
};

/**
 * After One World Trade Center: a glass cube base, and above it the tower's square turns as it rises, its corners
 * cut away into eight long triangles of glass so the roof is a square set at 45° to the street, its edges picked out
 * in white; the parapet carries a tall spire with its rings and a light.
 */
const oneWtc: Draw = (k, W, D, b, r) => {
  const H = shaftH(b) - 0.2, base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0xa8c0d0, 0x9ab4c8, 0xb4c4cc]);
  podium(k, base, PALE, WHITE_STONE);
  const s = base * 0.72, bh = 0.9;
  k.box(0, PODIUM, 0, s, bh, s, scale(glass, 0.85));
  fins(k, 0, PODIUM, 0, s, s, bh, 8, PALE);
  const y0 = PODIUM + bh, y1 = PODIUM + H * 0.93, t = s * 0.56;
  const A = (i: number): P3 => { const a = Math.PI / 4 + (i * Math.PI) / 2; return [Math.cos(a) * s / Math.SQRT2, y0, Math.sin(a) * s / Math.SQRT2]; };
  const B = (i: number): P3 => { const a = (i * Math.PI) / 2; return [Math.cos(a) * t / Math.SQRT2, y1, Math.sin(a) * t / Math.SQRT2]; };
  const I: P3 = [0, (y0 + y1) / 2, 0], lit: [number, number, number] = [17.5, 24, 1];
  for (let i = 0; i < 4; i++) {
    // the glass faintly lit after dark, not a lamp
    k.glowTri(A(i), A(i + 1), B(i + 1), I, glass, lit, scale(COOL_GLOW, 0.42));
    k.glowTri(B(i), B(i + 1), A(i), I, scale(glass, 0.92), lit, scale(COOL_GLOW, 0.38));
    k.bar(A(i), B(i), 0.012, PALE);
    k.bar(A(i), B(i + 1), 0.012, PALE);
  }
  k.turned(Math.PI / 4, () => k.box(0, y1, 0, t, 0.08, t, PALE));
  k.cyl(0, y1 + 0.08, 0, 0.1, 0.12, PALE, 8);
  k.glowBox(0, y1 + 0.2, 0, 0.1, 0.06, 0.1, METAL, [17, 30, 2.4], COOL_GLOW);
  k.cyl(0, y1 + 0.2, 0, 0.025, 1.0, METAL, 6);
  for (const ry of [0.45, 0.7]) k.cyl(0, y1 + ry, 0, 0.055, 0.025, METAL, 8);
  beacon(k, y1 + 1.2);
};

/**
 * After the Shard: a slender pyramid of pale glass whose four faces are each two shards, a seam down the middle of
 * each face, the shards standing proud near the top and running on past it at different heights so the tip is a
 * crown of splinters, lit from within after dark.
 */
const shard: Draw = (k, W, D, b, r) => {
  const H = shaftH(b) + 0.4, base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0xc8dce6, 0xb8ccd8, 0xd0dce0]), pane = scale(glass, 1.06);
  podium(k, base, PALE, WHITE_STONE);
  const s0 = base * 0.84, y0 = PODIUM, top = y0 + H * 0.9, s1 = s0 * 0.1;
  loft(k, y0, square(s0), top, square(s1), glass, glass);
  loftLights(k, r, y0, square(s0), top, square(s1), 2, scale(glass, 0.86));
  // a face toward +z, from its bottom edge at z = s0/2 up toward the axis: half width and depth at a height
  const half = (y: number) => Math.max(0.02, s0 / 2 - ((s0 - s1) / 2) * ((y - y0) / (top - y0)));
  let tip = top;
  for (let f = 0; f < 4; f++) k.turned((f * Math.PI) / 2, () => {
    for (const h of [-1, 1]) {
      const yt = top + 0.2 + r() * 0.55, e = 0.012;
      tip = Math.max(tip, yt);
      const at = (ya: number): P3[] => [[h * 0.02, ya, half(ya) + e], [h * (half(ya) - 0.02), ya, half(ya) + e], [h * Math.max(0.03, half(yt) - 0.01), yt, half(yt) + e], [h * 0.02, yt, half(yt) + e]];
      // proud of the face only near the top, so the lit floors below show; the splinter is seen from behind too
      const p = at(top - 1.6), q = at(top - 0.3);
      k.quad(p[0], p[1], p[2], p[3], pane, [0, (top + yt) / 2, 0]);
      k.quad(q[0], q[1], q[2], q[3], pane, [0, (top + yt) / 2, 9]);
      if (h > 0) k.bar([0, y0, half(y0) + 0.008], [0, top - 1.6, half(top - 1.6) + 0.008], 0.01, scale(glass, 0.8));
    }
  });
  k.glowBox(0, top - 0.35, 0, half(top - 0.35) * 1.6, 0.3, half(top - 0.35) * 1.6, glass, [17, 30, 2.4], COOL_GLOW);
  beacon(k, tip + 0.02);
};

/**
 * After the Shanghai World Financial Center, the bottle opener: a square tower whose sides draw in as it rises until
 * it is a tall blade, with a trapezoid hole cut clean through it near the top, its soffit lit at night.
 */
const bottleOpener: Draw = (k, W, D, b, r) => {
  const H = shaftH(b) + 0.3, base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0x7a9ab8, 0x8aa4bc, 0x6e8ca8]);
  podium(k, base, PALE, WHITE_STONE);
  const s = base * 0.8, y0 = PODIUM, yTop = y0 + H * 0.97;
  const at = (y: number): Ring => { const t = (y - y0) / (yTop - y0); return square(s, s * (1 - 0.84 * t)); };
  const yh0 = y0 + H * 0.78, yh1 = y0 + H * 0.9, hx0 = s * 0.26, hx1 = s * 0.34;
  loft(k, y0, at(y0), yh0, at(yh0), glass, PALE);
  loftLights(k, r, y0, at(y0), yh0, at(yh0), 2, scale(glass, 0.86));
  // the two legs either side of the hole, and the beam over it
  const dzm = at((yh0 + yh1) / 2)[2][1] * 2;
  for (const sx of [-1, 1]) k.box(sx * (s / 2 + (hx0 + hx1) / 2) / 2, yh0, 0, s / 2 - (hx0 + hx1) / 2, yh1 - yh0, dzm, glass);
  k.box(0, yh1, 0, s, 0.04, at(yh1)[2][1] * 2, PALE);
  k.glowBox(0, yh1 - 0.03, 0, hx1 * 2, 0.03, dzm * 0.9, PALE, [17, 30, 2], COOL_GLOW);
  loft(k, yh1 + 0.04, at(yh1 + 0.04), yTop, at(yTop), glass, PALE);
  k.box(0, yTop, 0, s * 0.9, 0.06, at(yTop)[2][1] * 2, PALE);
  beacon(k, yTop + 0.06);
};

/**
 * After Salesforce Tower: a square with rounded corners, tapering gently, pale glass between white piers that run up
 * every other bay; the piers carry on past the roof as an open lattice crown, and inside it a lit core after dark.
 */
const salesforce: Draw = (k, W, D, b, r) => {
  const H = shaftH(b) + 0.2, base = Math.min(W, D) - 0.3;
  const glass = pick(r, [0xc0ccd4, 0xb0c4d0, 0xd0d4d8]), crown = pick(r, [0xe6eeff, 0x9fd0ff, 0xffd0e8]);
  podium(k, base, PALE, WHITE_STONE);
  const s0 = base * 0.82, s1 = base * 0.62, y0 = PODIUM, yc = y0 + H * 0.86, yt = y0 + H * 0.98;
  const ring = (t: number) => squircle(s0 + (s1 - s0) * t);
  const a = ring(0), c = ring(0.88), d = ring(1);
  loft(k, y0, a, yc, c, glass, PALE);
  loftLights(k, r, y0, a, yc, c, 2, scale(glass, 0.86));
  for (let i = 0; i < 16; i += 2) k.bar([a[i][0] * 1.01, y0, a[i][1] * 1.01], [c[i][0] * 1.01, yc, c[i][1] * 1.01], 0.016, PALE);
  for (let i = 0; i < 16; i++) {
    k.bar([c[i][0], yc, c[i][1]], [d[i][0], yt, d[i][1]], 0.014, PALE);
    const j = (i + 1) % 16;
    k.bar([d[i][0], yt, d[i][1]], [d[j][0], yt, d[j][1]], 0.014, PALE);
  }
  k.glowBox(0, yc, 0, s1 * 0.62, (yt - yc) * 0.85, s1 * 0.62, scale(glass, 0.9), [17, 30, 2.6], crown);
  beacon(k, yt + 0.02);
};

/**
 * After 432 Park Avenue: the pencil tower, a slim square of white concrete with big square windows, three to a face
 * every two floors, and an open dark storey every so often where the wind passes through.
 */
const pencilTower: Draw = (k, W, D, b, r) => {
  const H = shaftH(b) + 0.5, base = Math.min(W, D) - 0.3;
  const concrete = pick(r, [0xeeeae2, 0xe4e2dc, 0xd8d6d2]), dark = hex(0x34404a), glass = hex(0x5a6a76);
  podium(k, base, PALE, WHITE_STONE);
  const s = base * 0.5, y0 = PODIUM, h = H - 0.1, rowH = FLOOR * 1.6, cell = s / 3;
  k.box(0, y0, 0, s, h, s, concrete);
  const rows = Math.floor((h - 0.15) / rowH);
  for (let i = 0; i < rows; i++) {
    const y = y0 + 0.1 + i * rowH;
    if (i % 7 === 6) { k.box(0, y + rowH * 0.1, 0, s + 0.004, rowH * 0.7, s + 0.004, dark); continue; }
    for (let f = 0; f < 4; f++) for (let c = 0; c < 3; c++) {
      const o = -s / 2 + cell * (c + 0.5), sched = windowSched('condoTower', r);
      if (f === 1 || f === 3) k.pane(o, y + rowH * 0.12, f === 1 ? s / 2 : -s / 2, cell * 0.78, rowH * 0.76, f, glass, sched, WARM_GLOW);
      else k.pane(f === 0 ? s / 2 : -s / 2, y + rowH * 0.12, o, cell * 0.78, rowH * 0.76, f, glass, sched, WARM_GLOW);
    }
  }
  k.box(0, y0 + h, 0, s + 0.02, 0.05, s + 0.02, concrete);
  beacon(k, y0 + h + 0.05);
};

export const GLASS_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  glassSpire: [twistTower, setbackTower, slantTower, twinBlades, diagridTower, taipei101, petronas, oneWtc, shard, bottleOpener, salesforce, pencilTower],
};
