/**
 * The faction strongholds' models, part B (docs/strongholds.html), drawn from their plans (world/strongholdPlans.ts).
 *
 * - **The General Post Office** (the Post): a columned GPO on the street under its clock tower, two sorting halls with
 *   red vans backed up to their bays along a one-way service road, a giant pillar box, an airmail strip with its
 *   shed and mail plane; a red-brick wall with a postbox on its piers and IN and OUT arches
 * - **The Air Force Base's cantonment** (the Army): the HQ under its flag, a quonset mess, a drill square with a
 *   squad on it, the motor pool's tanks and humvees, a row of barracks huts, a concrete chicane, four watchtowers with
 *   searchlights; a concrete wall under wire, a guard post and barrier at the gate and a jet on a plinth inside it
 * - **Lark Studios** (the Studios): four barrel-roofed soundstages with their numbers, a backlot street between two
 *   rows of propped-up false fronts (the Old West at one end, a city block at the other), a water tank, the
 *   executive tower and the big LARK letters on their frame; a white stucco wall and a grand arch at the gate
 * - **Corran Harbour** (the Guild): a walled basin with trawlers moored in it and a sea lock and boom at its mouth,
 *   setts all round, a striped lighthouse with a turning lamp, a trawler on blocks in the dry dock, the guild hall's
 *   great timber roof, tarred net lofts, the ice house and a chandlery; a stone sea wall
 * - **Vane House** (the Press): a glass broadcast tower with a mast and a helipad on its roof, a spiral ramp painted
 *   round its foot, a sunk press hall whose press shows through its open glazing, a terrace of dishes, the archive,
 *   and a lit news ticker over the gate; a glass-and-steel fence
 */
import { FACTIONS } from '../../game/factions/factions';
import { hex, type RGB } from '../../world/biomes';
import type { Rng } from '../../world/rng';
import { gateOut, inGate, strongholdPlan, type SPlan } from '../../world/strongholdPlans';
import type { Sched } from '../nightLights';
import { DARK, GLASS, METAL, TAU, WARM_GLOW, WHITE, windowGlow, windowSched, type Draw, type Kit, type P3 } from './kit';
import { letters } from './neon';
import { drawWalls } from './strongholdKit';

const NIGHT: Sched = [17.5, 30.5, 1.8];
const LATE: Sched = [17, 30.5, 2.4];
const TYRE = hex(0x2a2a2c), SKIN = hex(0xe0b08a), ASPHALT = hex(0x4a4d52), LINE = hex(0xf4f2ec), YELLOW = hex(0xf2c14e);
const COPPER = hex(0x5f9a84), LAMP = hex(0xfff0c0);

// ---- shared helpers -----------------------------------------------------------------------------------------------

/** Lit windows in a row on a wall facing `face` (0 +x, 1 +z, 2 -x, 3 -z), (x, z) the row's middle on the wall. */
function windowRow(k: Kit, s: Sched, g: RGB, x: number, y: number, z: number, len: number, n: number, face: number, ww = 0.16, wh = 0.2, day = GLASS): void {
  for (let i = 0; i < n; i++) {
    const t = n === 1 ? 0 : (i / (n - 1) - 0.5) * len;
    if (face === 1 || face === 3) k.pane(x + t, y, z, ww, wh, face, day, s, g);
    else k.pane(x, y, z + t, ww, wh, face, day, s, g);
  }
}

function people(k: Kit, r: Rng, x0: number, z0: number, w: number, d: number, n: number, cols?: RGB[]): void {
  const c = cols ?? [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0xf4f2ec].map(hex);
  for (let i = 0; i < n; i++) {
    const x = x0 + (r() - 0.5) * w, z = z0 + (r() - 0.5) * d;
    figure(k, x, z, c[i % c.length]);
  }
}

function figure(k: Kit, x: number, z: number, col: RGB): void {
  k.box(x, 0.02, z, 0.08, 0.13, 0.06, col);
  k.box(x, 0.15, z, 0.06, 0.06, 0.06, SKIN);
}

/** A street lamp: a pole and a head lit at night. */
function lamp(k: Kit, x: number, z: number, h = 0.8, pole = DARK): void {
  k.box(x, 0, z, 0.05, h, 0.05, pole);
  k.glowBox(x, h, z, 0.12, 0.07, 0.12, LAMP, NIGHT, WARM_GLOW);
}

/** A flagpole with its flag flying toward +x (two colours: field and a band). */
function flag(k: Kit, x: number, z: number, h: number, field: RGB, band: RGB, size = 0.4): void {
  k.cyl(x, 0, z, 0.02, h, WHITE, 5);
  k.cyl(x, h, z, 0.035, 0.035, YELLOW, 5);
  k.box(x + size / 2 + 0.02, h - size * 0.65, z, size, size * 0.6, 0.012, field);
  k.box(x + size / 2 + 0.02, h - size * 0.65 + size * 0.22, z, size, size * 0.16, 0.016, band);
}

/** A helipad on y: a disc, a ring, the H. */
function helipad(k: Kit, x: number, y: number, z: number, r: number, base: RGB, ring: RGB = WHITE): void {
  k.cyl(x, y, z, r, 0.03, base, 18);
  k.hoop(x, y + 0.035, z, r * 0.82, 0.03, ring, 18, 'xz');
  const s = r / 1.4;
  for (const sx of [-1, 1]) k.box(x + sx * 0.35 * s, y + 0.035, z, 0.12 * s, 0.004, 0.9 * s, WHITE);
  k.box(x, y + 0.035, z, 0.7 * s, 0.004, 0.12 * s, WHITE);
}

/** Every stretch of every wall ring cut into lengths about `step` long, those in a gate left out. */
function alongWalls(p: SPlan, step: number, fn: (ax: number, az: number, bx: number, bz: number, i: number) => void): void {
  let n = 0;
  for (const ring of p.rings) {
    for (let e = 0; e < ring.length; e++) {
      const [ax, az] = ring[e], [bx, bz] = ring[(e + 1) % ring.length];
      const L = Math.hypot(bx - ax, bz - az), m = Math.max(1, Math.round(L / step));
      for (let i = 0; i < m; i++) {
        const t0 = i / m, t1 = (i + 1) / m;
        const x0 = ax + (bx - ax) * t0, z0 = az + (bz - az) * t0, x1 = ax + (bx - ax) * t1, z1 = az + (bz - az) * t1;
        if (inGate(p, (x0 + x1) / 2, (z0 + z1) / 2, 0.15)) continue;
        fn(x0, z0, x1, z1, n++);
      }
    }
  }
}

/** Piers along every wall about `step` apart, none standing in (or poking into) a gate's gap. */
function piers(k: Kit, p: SPlan, step: number, size: number, h: number, col: RGB, top?: (x: number, z: number, i: number) => void): void {
  alongWalls(p, step, (ax, az, _bx, _bz, i) => {
    if (inGate(p, ax, az, size * 0.75 + 0.05)) return;
    k.box(ax, 0, az, size, h, size, col);
    top?.(ax, az, i);
  });
}

/** Draw in a gate's frame: origin the gate's middle, +x along the wall, +z out of the stronghold. */
function atGate(k: Kit, p: SPlan, gi: number, draw: (w: number) => void): void {
  const g = p.gates[gi], [nx, nz] = gateOut(p, g);
  k.within(g.x, g.z, Math.atan2(nx, nz), () => draw(g.w));
}

/** Letters on a face looking along (nx, nz), centred at (x, y, z). */
function sign(k: Kit, text: string, x: number, y: number, z: number, nx: number, nz: number, h: number, col: RGB): void {
  letters(k, text, [x, y, z], [nz, -nx], h, col);
}

/** An arrow painted flat on the ground at (x, z) pointing along yaw (0 = +z). */
function arrow(k: Kit, x: number, z: number, yaw: number, col: RGB = LINE, s = 1): void {
  k.within(x, z, yaw, () => {
    k.box(0, 0.016, -0.15 * s, 0.09 * s, 0.004, 0.5 * s, col);
    k.bar([-0.2 * s, 0.018, 0.02 * s], [0, 0.018, 0.25 * s], 0.035 * s, col);
    k.bar([0.2 * s, 0.018, 0.02 * s], [0, 0.018, 0.25 * s], 0.035 * s, col);
  });
}

/** A barrel roof on y over a w×d base: the arch spans w and runs along z (or spans d and runs along x). */
function vault(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, col: RGB, end: RGB, alongX = false, n = 8): void {
  const span = alongX ? d : w, run = alongX ? w : d;
  const at = (i: number, e: number): P3 => {
    const a = (Math.PI * i) / n, u = -Math.cos(a) * span / 2, v = y + Math.sin(a) * h;
    return alongX ? [x + e * run / 2, v, z + u] : [x + u, v, z + e * run / 2];
  };
  const mid: P3 = [x, y + h / 3, z];
  for (let i = 0; i < n; i++) {
    k.quad(at(i, -1), at(i + 1, -1), at(i + 1, 1), at(i, 1), col, [x, y, z]);
    for (const e of [-1, 1]) {
      const c: P3 = alongX ? [x + e * run / 2, y, z] : [x, y, z + e * run / 2];
      k.tri(c, at(i, e), at(i + 1, e), end, mid);
    }
  }
}

/** A clock on a wall facing +z with hands that keep the hour. */
function clockFace(k: Kit, x: number, y: number, z: number, r: number, rim: RGB, hands = true): void {
  k.face(x, y, z + 0.004, r * 1.14, rim, 14);
  k.face(x, y, z + 0.01, r, hex(0xf6f0dc), 14);
  k.glowBox(x, y - r * 0.7, z + 0.012, r * 1.4, r * 1.4, 0.003, hex(0xf6f0dc), NIGHT, WARM_GLOW);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    k.box(x + Math.cos(a) * r * 0.82, y + Math.sin(a) * r * 0.82 - 0.012, z + 0.017, 0.024, 0.024, 0.004, DARK);
  }
  if (!hands) return;
  k.spin(x, y, z + 0.024, 'z', 0, (h) => h.box(0, 0, 0, 0.02, r * 0.55, 0.004, DARK), 'hour');
  k.spin(x, y, z + 0.032, 'z', 0, (h) => h.box(0, 0, 0, 0.014, r * 0.85, 0.004, DARK), 'minute');
}

/** A small van, nose toward local +z. */
function van(k: Kit, x: number, z: number, yaw: number, body: RGB, stripe: RGB): void {
  k.within(x, z, yaw, () => {
    for (const a of [0.17, -0.17]) for (const sx of [-1, 1]) k.box(sx * 0.12, 0, a, 0.04, 0.08, 0.08, TYRE);
    k.box(0, 0.05, -0.06, 0.26, 0.27, 0.42, body);
    k.box(0, 0.05, 0.21, 0.26, 0.18, 0.14, body);
    k.box(0, 0.16, 0.282, 0.22, 0.08, 0.006, hex(0x2f3a44));
    for (const sx of [-1, 1]) k.box(sx * 0.131, 0.16, -0.06, 0.004, 0.06, 0.36, stripe);
    k.box(0, 0.06, 0.283, 0.2, 0.04, 0.006, WHITE);
  });
}

/** A small aeroplane parked on its wheels, nose toward local +z: high wing, struts, tail. */
function plane(k: Kit, x: number, z: number, yaw: number, body: RGB, wing: RGB): void {
  k.within(x, z, yaw, () => {
    k.box(0, 0.1, 0, 0.16, 0.15, 0.82, body);
    k.box(0, 0.1, 0.44, 0.12, 0.12, 0.06, body);
    k.box(0, 0.16, 0.48, 0.34, 0.035, 0.012, DARK);
    k.box(0, 0.26, 0.12, 0.012, 0.02, 0.01, DARK);
    k.box(0, 0.26, 0.08, 1.3, 0.03, 0.24, wing);
    for (const sx of [-1, 1]) k.bar([sx * 0.07, 0.12, 0.08], [sx * 0.42, 0.26, 0.08], 0.01, DARK);
    k.box(0, 0.2, 0.22, 0.15, 0.06, 0.14, hex(0x2f3a44));
    k.box(0, 0.17, -0.38, 0.02, 0.2, 0.14, wing);
    k.box(0, 0.16, -0.38, 0.42, 0.02, 0.1, wing);
    for (const sx of [-1, 1]) { k.bar([sx * 0.07, 0.1, 0.18], [sx * 0.14, 0.03, 0.18], 0.01, DARK); k.box(sx * 0.14, 0, 0.18, 0.03, 0.06, 0.06, TYRE); }
    k.box(0, 0, -0.36, 0.02, 0.04, 0.04, TYRE);
  });
}

/** A fighter jet on y, nose toward local +z (scale s). */
function jet(k: Kit, x: number, y: number, z: number, col: RGB, s = 1.6): void {
  k.box(x, y + 0.08 * s, z, 0.14 * s, 0.1 * s, 1.1 * s, col);
  k.wedge(x, y + 0.08 * s, z - 0.05 * s, 0.8 * s, 0.03 * s, 0.55 * s, col);
  for (const sx of [-1, 1]) k.box(x + sx * 0.06 * s, y + 0.15 * s, z - 0.42 * s, 0.02 * s, 0.2 * s, 0.18 * s, col);
  k.box(x, y + 0.17 * s, z + 0.25 * s, 0.08 * s, 0.06 * s, 0.22 * s, hex(0x2f3a44));
  k.cone(x, y + 0.08 * s, z + 0.62 * s, 0.06 * s, 0.14 * s, col, 6);
}

// ---- the General Post Office --------------------------------------------------------------------------------------

const shGPO: Draw = (k, W, D, b, r) => {
  const p = strongholdPlan('shGPO');
  const RED = hex(FACTIONS.post.colour), CREAM = hex(FACTIONS.post.accent);
  const BRICK = hex(0x9c4a38), BRICK2 = hex(0x7e3a2c), PORTLAND = hex(0xe8dcc0), SLATE = hex(0x4d5862), GRASS = hex(0x7fae5e);
  const s = windowSched(b.kind, r), g = windowGlow(b.kind, r);
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, hex(0x8f8a82));

  // the red-brick wall, a pier every so often and a postbox on every other one
  drawWalls(k, p, { face: BRICK, cap: CREAM });
  piers(k, p, 2.6, 0.5, 0.84, BRICK2, (ax, az, i) => {
    k.box(ax, 0.84, az, 0.56, 0.05, 0.56, CREAM);
    if (i % 2 === 0) {
      k.cyl(ax, 0.89, az, 0.1, 0.22, RED, 8);
      k.dome(ax, 1.11, az, 0.11, RED, 8, 2);
    }
  });

  // the gates: brick piers with a postbox each, an arch over, IN or OUT on it both ways
  p.gates.forEach((gt, gi) => atGate(k, p, gi, (w) => {
    const hw = w / 2 + 0.3;
    for (const sx of [-1, 1]) {
      k.box(sx * hw, 0, 0, 0.6, 1.2, 0.6, BRICK2);
      k.box(sx * hw, 1.2, 0, 0.68, 0.06, 0.68, CREAM);
      k.cyl(sx * hw, 1.26, 0, 0.14, 0.3, RED, 10);
      k.dome(sx * hw, 1.56, 0, 0.15, RED, 10, 2);
      k.box(sx * hw, 1.42, 0.14, 0.12, 0.02, 0.01, DARK);
    }
    const R = hw, n = 10;
    for (let i = 0; i < n; i++) {
      const a0 = (i / n) * Math.PI, a1 = ((i + 1) / n) * Math.PI;
      k.bar([Math.cos(a0) * R, 1.25 + Math.sin(a0) * R * 0.55, 0], [Math.cos(a1) * R, 1.25 + Math.sin(a1) * R * 0.55, 0], 0.07, BRICK);
    }
    const word = gt.dir === 'in' ? 'IN' : gt.dir === 'out' ? 'OUT' : 'POST';
    k.box(0, 1.84, 0, 1.0, 0.36, 0.08, RED);
    sign(k, word, 0, 1.9, 0.045, 0, 1, 0.24, CREAM);
    sign(k, word, 0, 1.9, -0.045, 0, -1, 0.24, CREAM);
  }));

  for (const bl of p.blocks) {
    const { x, z, w, d, h } = bl;
    switch (bl.type) {
      case 'gpo': {
        // the hall: a long stone front, two storeys of windows, a portico of columns under a pediment
        const z0 = z - d / 2, zb = z0 + 2.8;
        k.box(x, 0, (z0 + zb) / 2, w, h, 2.8, PORTLAND);
        k.box(x, h, (z0 + zb) / 2, w + 0.1, 0.08, 2.9, CREAM);
        k.hip(x, h + 0.08, (z0 + zb) / 2, w - 0.2, 0.45, 2.6, SLATE);
        k.box(x, 0, (z0 + zb) / 2, w + 0.04, 0.16, 2.84, hex(0xbdb19a));
        for (const sx of [-1, 1]) windowRow(k, s, g, x + sx * 2.5, 0.3, zb, 1.6, 3, 1, 0.2, 0.36);
        for (const sx of [-1, 1]) windowRow(k, s, g, x + sx * 2.5, 0.95, zb, 1.6, 3, 1, 0.2, 0.32);
        windowRow(k, s, g, x, 0.95, z0, w - 1, 9, 3, 0.18, 0.3);
        windowRow(k, s, g, x + 2, 0.3, z0, 2, 3, 3, 0.18, 0.3);
        windowRow(k, s, g, x - 2, 0.3, z0, 2, 3, 3, 0.18, 0.3);
        const pz = zb + 0.2;
        k.box(x, 0, pz, 4.4, 0.1, 0.42, hex(0xbdb19a));
        for (let i = 0; i < 8; i++) k.cyl(x - 1.96 + i * 0.56, 0.1, pz + 0.02, 0.07, 1.2, PORTLAND, 8);
        k.box(x, 1.3, pz, 4.6, 0.18, 0.44, PORTLAND);
        k.gable(x, 1.48, pz, 4.6, 0.38, 0.44, SLATE, PORTLAND, true);
        sign(k, 'GENERAL POST OFFICE', x, 1.33, pz + 0.225, 0, 1, 0.11, RED);
        // the great doors under the portico, lit
        k.box(x, 0.1, zb + 0.005, 0.7, 0.7, 0.01, hex(0x5a3a2a));
        k.glowBox(x, 0.82, zb + 0.005, 0.7, 0.16, 0.01, GLASS, NIGHT, WARM_GLOW);
        // the back door, on the service road: a red canopy and POST over it
        k.box(x, 0, z0 - 0.005, 1.2, 0.6, 0.01, hex(0x3a3f45));
        k.box(x, 0.66, z0 - 0.2, 1.6, 0.05, 0.4, RED);
        sign(k, 'POST', x, 0.73, z0 - 0.006, 0, -1, 0.16, RED);
        break;
      }
      case 'clockTower': {
        // a tall stone shaft through the hall, the clock stage, a copper cupola and a lantern
        k.box(x, 0, z, 1.2, h - 0.9, 1.2, PORTLAND);
        for (const y of [1.7, 2.5]) k.box(x, y, z, 1.26, 0.06, 1.26, CREAM);
        k.box(x, h - 0.9, z, 1.36, 0.7, 1.36, PORTLAND);
        k.box(x, h - 0.2, z, 1.44, 0.08, 1.44, CREAM);
        for (let f = 0; f < 4; f++) k.within(x, z, (f * Math.PI) / 2, () => clockFace(k, 0, h - 0.55, 0.68, 0.27, RED, f === 0 || f === 2));
        for (const sx of [-1, 1]) for (const y of [1.85, 2.35]) k.pane(x + sx * 0.3, y, z + 0.6, 0.1, 0.3, 1, GLASS, s, g);
        k.box(x, h - 0.12, z, 0.9, 0.4, 0.9, PORTLAND);
        for (const [cx, cz] of [[-0.4, -0.4], [0.4, -0.4], [-0.4, 0.4], [0.4, 0.4]]) k.cyl(x + cx, h - 0.12, z + cz, 0.05, 0.4, CREAM, 6);
        k.dome(x, h + 0.28, z, 0.5, COPPER, 10, 3);
        k.cyl(x, h + 0.75, z, 0.08, 0.22, COPPER, 6);
        k.cone(x, h + 0.97, z, 0.1, 0.3, YELLOW, 6);
        k.glowBox(x, h - 0.04, z, 0.4, 0.2, 0.4, CREAM, NIGHT, WARM_GLOW);
        break;
      }
      case 'sortingHall': {
        // a long brick hall under a sawtooth roof, six bays along the road, red vans backed up to them
        k.box(x, 0, z, w, 0.95, d, BRICK);
        const n = 3, td = d / n;
        for (let i = 0; i < n; i++) {
          const tz = z - d / 2 + td * (i + 0.5);
          k.wedge(x, 0.95, tz, w, 0.3, td, SLATE);
          k.pane(x, 0.97, tz + td / 2, w - 0.4, 0.24, 1, GLASS, s, g);
        }
        const zf = z + d / 2, bays = 6;
        for (let i = 0; i < bays; i++) {
          const bx = x - w / 2 + (i + 0.5) * (w / bays);
          k.box(bx, 0.16, zf + 0.005, 0.95, 0.56, 0.01, hex(0x8c9196));
          for (let j = 1; j < 5; j++) k.box(bx, 0.16 + j * 0.11, zf + 0.011, 0.95, 0.008, 0.004, hex(0x6f7478));
          k.box(bx, 0, zf + 0.1, 1.0, 0.16, 0.2, hex(0x5a5d62));
          k.box(bx, 0.03, zf + 0.21, 0.08, 0.1, 0.02, YELLOW);
          if (i % 2 === (x < 0 ? 0 : 1) || i === 2) van(k, bx, zf + 0.5, Math.PI, RED, YELLOW);
        }
        k.box(x, 0.76, zf + 0.25, w, 0.05, 0.5, RED);
        k.box(x, 0.81, zf + 0.005, w, 0.14, 0.01, CREAM);
        sign(k, 'SORTING OFFICE', x, 0.83, zf + 0.012, 0, 1, 0.1, RED);
        for (const sx of [-1, 1]) k.glowBox(x + sx * w * 0.3, 0.7, zf + 0.06, 0.16, 0.05, 0.08, LAMP, NIGHT, WARM_GLOW);
        windowRow(k, s, g, x, 0.4, z - d / 2, w - 1, 8, 3, 0.2, 0.3);
        break;
      }
      case 'pillarBox': {
        k.cyl(x, 0, z, 0.38, 0.12, DARK, 14);
        k.cyl(x, 0.12, z, 0.32, 0.98, RED, 14);
        k.cyl(x, 1.1, z, 0.37, 0.08, RED, 14);
        k.dome(x, 1.18, z, 0.35, RED, 14, 3);
        k.box(x, 0.86, z + 0.31, 0.3, 0.05, 0.03, DARK);
        k.box(x, 0.5, z + 0.315, 0.2, 0.22, 0.02, CREAM);
        k.box(x, 0.68, z + 0.315, 0.08, 0.08, 0.02, YELLOW);
        figure(k, x + 0.5, z + 0.5, RED);
        k.box(x + 0.44, 0.12, z + 0.5, 0.06, 0.04, 0.005, WHITE);
        break;
      }
      case 'serviceRoad': {
        // the one-way service road: asphalt, yellow edge lines, arrows from the IN gate round to the OUT gate
        k.box(x, 0.012, z, w, 0.004, d, ASPHALT);
        for (const sz of [-1, 1]) k.box(x, 0.016, z + sz * (d / 2 - 0.08), w - 0.2, 0.003, 0.05, YELLOW);
        for (let i = -2; i <= 2; i++) arrow(k, x + i * 5.2, z, Math.PI / 2, LINE, 1.2);
        // and the lanes from each gate down to it
        for (const gt of p.gates) {
          const z0 = z + d / 2, z1 = gt.z - 0.2;
          k.box(gt.x, 0.012, (z0 + z1) / 2, gt.w, 0.004, z1 - z0, ASPHALT);
          arrow(k, gt.x, (z0 + z1) / 2, gt.dir === 'out' ? 0 : Math.PI, LINE, 1.1);
        }
        lamp(k, -10.4, 5.6); lamp(k, 10.4, 5.6); lamp(k, -4.6, 3.0); lamp(k, 4.6, 3.0);
        people(k, r, x, z + 1.0, 6, 0.3, 3, [RED, hex(0x2f3a5a)]);
        break;
      }
      case 'airmailStrip': {
        // a short grass strip with an asphalt runway, the mail plane waiting at the far end
        k.box(x, 0.012, z, w, 0.004, d, GRASS);
        k.box(x, 0.014, z, w - 0.8, 0.004, 1.0, ASPHALT);
        for (let i = 0; i < 14; i++) k.box(x - w / 2 + 2.4 + i * 1.3, 0.018, z, 0.6, 0.003, 0.06, LINE);
        for (const sx of [-1, 1]) for (let j = 0; j < 4; j++) k.box(x + sx * (w / 2 - 0.7), 0.018, z - 0.36 + j * 0.24, 0.5, 0.003, 0.1, LINE);
        plane(k, x + w / 2 - 2.6, z, -Math.PI / 2, RED, CREAM);
        // the windsock
        k.box(10.0, 0, -3.5, 0.04, 0.8, 0.04, METAL);
        for (let i = 0; i < 3; i++) k.box(10.0 + 0.1 + i * 0.13, 0.7 - i * 0.02, -3.5, 0.13, 0.1 - i * 0.02, 0.1 - i * 0.02, i % 2 ? WHITE : hex(0xf28c38));
        break;
      }
      case 'airmailShed': {
        k.box(x, 0, z, w, 0.4, d, CREAM);
        vault(k, x, 0.4, z, w, 0.45, d, RED, CREAM);
        k.box(x, 0, z - d / 2 - 0.005, w * 0.75, 0.62, 0.01, hex(0x3a3f45));
        sign(k, 'AIR MAIL', x, 0.72, z - d / 2 - 0.01, 0, -1, 0.14, RED);
        k.glowBox(x, 0.66, z - d / 2 - 0.05, 0.3, 0.04, 0.08, LAMP, NIGHT, WARM_GLOW);
        break;
      }
      case 'pad': {
        helipad(k, x, 0, z, 1.15, hex(0x5a6066), RED);
        break;
      }
    }
  }
};

