          k.glowBox(x + sx * (w / 2 + 0.03), 0.5, z, 0.04, 0.05, 0.12, LAMP, NIGHT, WARM_GLOW);
          windowRow(k, s, g, x + sx * (w / 2 + 0.002), 0.4, z, 1.6, 2, sx > 0 ? 0 : 2, 0.16, 0.16);
