/** A dish on its pedestal at (x, z): a shallow bowl of radius rr tilted up `el` toward heading `yaw`, a feed at its focus. */
function dish(k: Kit, x: number, y: number, z: number, rr: number, yaw: number, el: number, col: RGB): void {
  const cy = y + rr * 0.9;
  k.cyl(x, y, z, 0.06, cy - y, DARK, 6);
  const n: P3 = [Math.sin(yaw) * Math.cos(el), Math.sin(el), Math.cos(yaw) * Math.cos(el)];
  const u: P3 = [Math.cos(yaw), 0, -Math.sin(yaw)];
  const v: P3 = [n[1] * u[2] - n[2] * u[1], n[2] * u[0] - n[0] * u[2], n[0] * u[1] - n[1] * u[0]];
  const C: P3 = [x, cy, z];
  const at = (a: number): P3 => [C[0] + rr * (Math.cos(a) * u[0] + Math.sin(a) * v[0]), C[1] + rr * (Math.cos(a) * u[1] + Math.sin(a) * v[1]), C[2] + rr * (Math.cos(a) * u[2] + Math.sin(a) * v[2])];
  const V: P3 = [C[0] - n[0] * rr * 0.3, C[1] - n[1] * rr * 0.3, C[2] - n[2] * rr * 0.3];
  const front: P3 = [C[0] + n[0] * rr * 3, C[1] + n[1] * rr * 3, C[2] + n[2] * rr * 3];
  const back: P3 = [C[0] - n[0] * rr * 3, C[1] - n[1] * rr * 3, C[2] - n[2] * rr * 3];
  const seg = 12;
  for (let i = 0; i < seg; i++) {
    const a = at((i / seg) * TAU), b2 = at(((i + 1) / seg) * TAU);
    k.tri(V, a, b2, col, back);
    k.tri(V, a, b2, hex(0xb9bdc2), front);
  }
  const F: P3 = [C[0] + n[0] * rr * 0.7, C[1] + n[1] * rr * 0.7, C[2] + n[2] * rr * 0.7];
  for (const a of [0, TAU / 3, (2 * TAU) / 3]) k.bar(at(a + 0.5), F, 0.01, DARK);
  k.box(F[0], F[1] - 0.04, F[2], 0.08, 0.08, 0.08, DARK);
}

const shVane: Draw = (k, W, D, b, r) => {
  const p = strongholdPlan('shVane');
  const RED = hex(FACTIONS.press.colour), BLACK = hex(FACTIONS.press.accent);
  const STEEL = hex(0x9aa3ab), GLASSV = hex(0x5f7f99), CONC = hex(0xb9b6ae);
  const s = windowSched(b.kind, r), g = windowGlow(b.kind, r);
  k.box(0, 0, 0, W - 0.1, 0.012, D - 0.1, hex(0xc9c6bf));

  // the glass-and-steel fence, a steel post at each gate edge
  drawWalls(k, p, { face: hex(0x9fc3cf), cap: STEEL });
  piers(k, p, 3.0, 0.1, p.wall.h + 0.14, BLACK);

  for (const bl of p.blocks) {
    const { x, z, w, d, h } = bl;
    switch (bl.type) {
      case 'tower': {
        // a lobby of light glass under a dark glass shaft, red fins up its corners, steel floor bands, the pad on
        // its roof and a lattice mast at the back corner with its aviation lights
        const fw = w - 0.2, zf = z + fw / 2;
        k.box(x, 0, z, fw - 0.3, 0.6, fw - 0.3, hex(0x9cc6d9));
        k.glowBox(x, 0.05, zf - 0.15 + 0.002, fw - 0.5, 0.5, 0.01, hex(0x9cc6d9), NIGHT, hex(0xe6eeff));
        k.box(x, 0.6, z, fw, h - 0.7, fw, GLASSV);
        for (let y = 0.6; y < h - 0.1; y += 0.45) k.box(x, y, z, fw + 0.06, 0.05, fw + 0.06, STEEL);
        for (const [cx, cz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) k.box(x + cx * fw / 2, 0, z + cz * fw / 2, 0.2, h + 0.2, 0.2, RED);
        for (let f = 0; f < 11; f++) {
          const y = 0.7 + f * 0.45;
          windowRow(k, s, g, x, y, zf, fw - 0.8, 6, 1, 0.42, 0.3, GLASS);
          windowRow(k, s, g, x, y, z - fw / 2, fw - 0.8, 6, 3, 0.42, 0.3, GLASS);
          windowRow(k, s, g, x + fw / 2, y, z, fw - 0.8, 6, 0, 0.42, 0.3, GLASS);
          windowRow(k, s, g, x - fw / 2, y, z, fw - 0.8, 6, 2, 0.42, 0.3, GLASS);
        }
        // the name up top, a lit news band round the lobby, the canopy over the door
        k.box(x, h - 0.75, zf + 0.04, 2.4, 0.5, 0.04, WHITE);
        sign(k, 'VANE', x, h - 0.7, zf + 0.065, 0, 1, 0.4, RED);
        k.box(x, h - 0.75, z - fw / 2 - 0.04, 2.4, 0.5, 0.04, WHITE);
        sign(k, 'VANE', x, h - 0.7, z - fw / 2 - 0.065, 0, -1, 0.4, RED);
        for (const [nx, nz] of [[0, 1], [0, -1], [1, 0], [-1, 0]]) {
          const ox = nx * (fw / 2 + 0.03), oz = nz * (fw / 2 + 0.03);
          k.glowBox(x + ox, 0.62, z + oz, nx ? 0.02 : fw - 0.3, 0.12, nz ? 0.02 : fw - 0.3, RED, [0, 36, 1], hex(0xff5040));
        }
        k.box(x, 0.55, zf + 0.25, 1.6, 0.06, 0.5, RED);
        for (const sx of [-1, 1]) k.box(x + sx * 0.75, 0, zf + 0.45, 0.04, 0.55, 0.04, STEEL);
        // the roof and its pad (at the plan's pad height)
        const ry = p.pad.y;
        k.box(x, ry - 0.1, z, w, 0.1, w, hex(0x3a3f45));
        for (const sz of [-1, 1]) k.box(x, ry, z + sz * (w / 2 - 0.03), w, 0.12, 0.06, STEEL);
        for (const sx of [-1, 1]) k.box(x + sx * (w / 2 - 0.03), ry, z, 0.06, 0.12, w, STEEL);
        helipad(k, p.pad.x, ry, p.pad.z, 1.6, hex(0x2f3438), RED);
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * TAU;
          k.glowBox(p.pad.x + Math.cos(a) * 1.75, ry, p.pad.z + Math.sin(a) * 1.75, 0.06, 0.04, 0.06, hex(0x6fe07a), NIGHT, hex(0x6fe07a));
        }
        const mx = x + w / 2 - 0.35, mz = z - w / 2 + 0.35, top = ry + 3.6;
        for (const [cx, cz] of [[-1, -1], [1, -1], [0, 1]]) k.bar([mx + cx * 0.22, ry, mz + cz * 0.22], [mx, top, mz], 0.025, RED);
        for (let i = 1; i < 6; i++) {
          const t = i / 6, rr = 0.22 * (1 - t), y = ry + t * (top - ry);
          k.box(mx, y, mz, rr * 2 + 0.03, 0.02, rr * 2 + 0.03, WHITE);
        }
        k.bar([mx, top, mz], [mx, top + 0.8, mz], 0.012, STEEL);
        k.glowBox(mx, top + 0.8, mz, 0.08, 0.08, 0.08, hex(0xff3b30), [0, 36, 1], hex(0xff3b30));
        k.glowBox(mx, ry + 1.8, mz, 0.07, 0.07, 0.07, hex(0xff3b30), [0, 36, 1], hex(0xff3b30));
        k.cyl(mx - 0.2, ry + 2.4, mz, 0.12, 0.3, WHITE, 8);
        k.cyl(mx + 0.14, ry + 1.4, mz + 0.14, 0.1, 0.24, WHITE, 8);
        break;
      }
      case 'ramp': {
        // the spiral ramp painted round the tower's foot, kerbed at its edge
        k.cyl(x, 0.012, z, 4.3, 0.004, hex(0x8f9296), 28);
        const turns = 1.75, n = 30, ra = 2.7, rb = 4.1;
        let prev: P3 | null = null;
        for (let i = 0; i <= n; i++) {
          const t = i / n, a = Math.PI / 2 + t * turns * TAU, rr = ra + (rb - ra) * t;
          const pt: P3 = [x + Math.cos(a) * rr, 0.02, z + Math.sin(a) * rr];
          if (prev) k.bar(prev, pt, 0.025, LINE);
          prev = pt;
        }
        for (let i = 0; i < 4; i++) {
          const a = Math.PI / 4 + (i * Math.PI) / 2, rr = 3.4;
          arrow(k, x + Math.cos(a) * rr, z + Math.sin(a) * rr, Math.atan2(-Math.sin(a), Math.cos(a)), YELLOW, 0.9);
        }
        k.hoop(x, 0.02, z, 4.3, 0.04, CONC, 28, 'xz');
        break;
      }
      case 'pressHall': {
        // sunk half below the yard: low walls, a glazed roof of open steel through which the press shows
        const top = 0.32;
        k.box(x, 0.012, z, w - 0.1, 0.004, d - 0.1, hex(0x3a3d42));
        for (const sz of [-1, 1]) k.box(x, 0, z + sz * (d / 2 - 0.08), w, top, 0.16, CONC);
        for (const sx of [-1, 1]) k.box(x + sx * (w / 2 - 0.08), 0, z, 0.16, top, d, CONC);
        // the press: a long bed, four printing units in red and black, the paper web over them, papers stacked
        k.box(x, 0.016, z, 3.8, 0.12, 1.0, hex(0x3a3f45));
        for (let i = 0; i < 4; i++) {
          const ux = x - 1.5 + i * 1.0;
          k.box(ux, 0.13, z, 0.6, 0.4, 0.9, i % 2 ? RED : BLACK);
          for (const y of [0.3, 0.45]) k.bar([ux - 0.2, y, z - 0.46], [ux - 0.2, y, z + 0.46], 0.04, METAL);
        }
        k.box(x, 0.56, z, 3.6, 0.01, 0.6, WHITE);
        for (let i = 0; i < 3; i++) k.box(x + 2.15, 0.016 + i * 0.08, z - 0.2 + i * 0.03, 0.4, 0.08, 0.3, WHITE);
        for (let i = 0; i < 3; i++) k.glowBox(x - 1.5 + i * 1.5, 0.58, z + 0.4, 0.5, 0.03, 0.06, WHITE, NIGHT, hex(0xe6eeff));
        figure(k, x - 2.1, z + 0.6, BLACK); figure(k, x + 1.0, z - 0.7, RED);
        // the roof's steel: a ridge, rafters, a few panes catching the light
        const ry = top + 0.38;
        k.bar([x - w / 2, ry, z], [x + w / 2, ry, z], 0.03, STEEL);
        for (const sz of [-1, 1]) k.bar([x - w / 2, top, z + sz * (d / 2 - 0.08)], [x + w / 2, top, z + sz * (d / 2 - 0.08)], 0.025, STEEL);
        for (let i = 0; i <= 8; i++) for (const sz of [-1, 1]) {
          const rx = x - w / 2 + 0.08 + i * ((w - 0.16) / 8);
          k.bar([rx, top, z + sz * (d / 2 - 0.08)], [rx, ry, z], 0.015, STEEL);
        }
        for (const i of [0, 7]) for (const sz of [-1, 1]) {
          const x0 = x - w / 2 + 0.08 + i * ((w - 0.16) / 8), x1 = x0 + (w - 0.16) / 8, ze = z + sz * (d / 2 - 0.08);
          k.glowQuad([x0, top + 0.005, ze], [x1, top + 0.005, ze], [x1, ry + 0.005, z], [x0, ry + 0.005, z], [x0 + 0.1, 0, z], hex(0x9cc6d9), NIGHT, hex(0xe6eeff));
        }
        sign(k, 'PRESS HALL', x, 0.08, z + d / 2 + 0.005, 0, 1, 0.14, BLACK);
        break;
      }
      case 'dishTerrace': {
        k.box(x, 0, z, w, 0.25, d, CONC);
        k.box(x, 0.25, z, w + 0.04, 0.03, d + 0.04, STEEL);
        for (const sz of [-1, 1]) k.bar([x - w / 2, 0.45, z + sz * d / 2], [x + w / 2, 0.45, z + sz * d / 2], 0.012, STEEL);
        for (const sx of [-1, 1]) k.bar([x + sx * w / 2, 0.45, z - d / 2], [x + sx * w / 2, 0.45, z + d / 2], 0.012, STEEL);
        dish(k, x - 1.5, 0.28, z + 0.6, 0.55, 0.6, 0.75, WHITE);
        dish(k, x + 0.1, 0.28, z - 0.6, 0.75, 2.4, 0.9, WHITE);
        dish(k, x + 1.6, 0.28, z + 0.6, 0.45, -0.5, 0.6, WHITE);
        dish(k, x + 1.9, 0.28, z - 0.9, 0.3, 3.0, 0.5, RED);
        k.box(x - 1.5, 0.28, z - 0.8, 0.6, 0.35, 0.5, STEEL);
        k.glowBox(x - 1.5, 0.64, z - 0.8, 0.06, 0.06, 0.06, hex(0x6fe07a), [0, 36, 1], hex(0x6fe07a));
        break;
      }
      case 'archive': {
        // a stone strongroom: slits for windows, a bronze door toward the tower, the name cut over it
        const ARC = hex(0xb9b2a4);
        k.box(x, 0, z, w, h, d, ARC);
        k.box(x, h, z, w + 0.1, 0.08, d + 0.1, hex(0x8f897d));
        k.box(x, 0, z, w + 0.04, 0.1, d + 0.04, hex(0x8f897d));
        const fx = x + w / 2;
        windowRow(k, s, g, fx, 0.35, z, d - 0.6, 5, 0, 0.06, 0.45);
        windowRow(k, s, g, x - w / 2, 0.35, z, d - 0.6, 5, 2, 0.06, 0.45);
        k.box(fx + 0.01, 0, z, 0.02, 0.5, 0.5, hex(0xa6783a));
        k.box(fx + 0.15, 0, z, 0.3, 0.04, 0.8, ARC);
        sign(k, 'ARCHIVE', fx + 0.012, 0.6, z, 1, 0, 0.12, BLACK);
        k.glowBox(fx + 0.04, 0.55, z, 0.04, 0.04, 0.2, LAMP, NIGHT, WARM_GLOW);
        break;
      }
      case 'ticker': {
        // the news ticker over the gate: two steel posts outside the gap, the lit board high enough to drive under
        const pw = Math.max(w / 2 - 0.1, p.gates[0].w / 2 + 0.18);
        for (const sx of [-1, 1]) {
          k.box(x + sx * pw, 0, z, 0.18, 1.9, 0.18, STEEL);
          k.box(x + sx * pw, 0, z, 0.3, 0.1, 0.3, BLACK);
        }
        k.box(x, 1.3, z, 2 * pw + 0.2, 0.46, 0.3, BLACK);
        k.box(x, 1.76, z, 2 * pw + 0.24, 0.04, 0.34, RED);
        for (const sz of [-1, 1]) {
          k.glowBox(x, 1.36, z + sz * 0.155, 2 * pw - 0.1, 0.34, 0.006, hex(0x3a1410), [0, 36, 1], hex(0xff5a30));
          sign(k, sz > 0 ? 'VANE NEWS - LATE EXTRA' : 'ON AIR - VANE HOUSE', x, 1.43, z + sz * 0.162, 0, sz, 0.18, hex(0xffd23a));
        }
        k.box(x, 1.8, z, 0.5, 0.3, 0.06, RED);
        sign(k, 'NEWS', x, 1.84, z + 0.035, 0, 1, 0.18, WHITE);
        sign(k, 'NEWS', x, 1.84, z - 0.035, 0, -1, 0.18, WHITE);
        break;
      }
    }
  }
  // the yard's life: outside broadcast vans with dishes on their roofs, staff by the door
  for (const [vx, vz, yaw] of [[5.0, 3.0, 0], [5.8, 3.0, 0], [-4.6, 6.2, Math.PI / 2]] as [number, number, number][]) {
    van(k, vx, vz, yaw, WHITE, RED);
    k.within(vx, vz, yaw, () => { k.cyl(0, 0.32, -0.12, 0.02, 0.05, DARK, 4); k.cyl(0, 0.37, -0.12, 0.1, 0.02, WHITE, 8); });
  }
  people(k, r, 0, 4.6, 4, 1.2, 6, [BLACK, RED, WHITE, hex(0x2f4d7a)]);
  lamp(k, -3.0, 6.6, 0.8, BLACK); lamp(k, 3.0, 6.6, 0.8, BLACK); lamp(k, 6.6, -2.0, 0.8, BLACK); lamp(k, -6.6, -2.0, 0.8, BLACK);
};

