import type { Arch, Building, World } from '../world/tiles';

/**
 * Buildings drawn in another town style than their own (the Passport's Architect's Eye, game/treats.ts): a fleet's
 * HQ dressed in any style its player has stamped. The game says which buildings (`setStyleOverrides`, keyed by cell
 * and uid, as render/liveryPaint.ts is); the town mesher asks `styleOf` as it draws each one.
 */

const styles = new Map<string, Arch>();

/** The style a building should be drawn in instead of its own, or null. */
export function styleOf(w: World, b: Building): Arch | null {
  if (!styles.size) return null;
  return styles.get(`${w.cx},${w.cz}#${b.uid}`) ?? null;
}

/** Set every override at once; the buildings whose style changed, as [cx, cz, uid], to be drawn again. */
export function setStyleOverrides(next: Map<string, Arch>): [number, number, number][] {
  const changed: string[] = [];
  for (const [k, v] of next) if (styles.get(k) !== v) changed.push(k);
  for (const k of styles.keys()) if (!next.has(k)) changed.push(k);
  if (!changed.length) return [];
  styles.clear();
  for (const [k, v] of next) styles.set(k, v);
  return changed.map((k) => {
    const m = /^(-?\d+),(-?\d+)#(\d+)$/.exec(k)!;
    return [Number(m[1]), Number(m[2]), Number(m[3])];
  });
}

/** A new world: nothing restyled. */
export function clearStyleOverrides(): void { styles.clear(); }
