import * as THREE from 'three';
import type { Build, Kit } from '../vehicleMeshes';

/** The factions' vehicles, group A (docs/factions.html): a model not drawn yet borrows a similar body (vehicleMeshes STAND_IN). */

type Mat = THREE.Material | number;

const WHITE = 0xf4f2ec, CHROME = 0xd9dde2, DARK = 0x2a2a2e, GOLD = 0xd9b34a, NAVY = 0x1d2f5a, CREAM = 0xf1e4c6;
const TEAL = 0x2bb3a3, CORAL = 0xf49ab5, YELLOW = 0xf2c14e;

/**
 * A side profile extruded across the car: `pts` are (z, y) corners, front is +z, and the slab is `w`
 * wide, centred on x. Bonnets, greenhouses, fins and glass that follow a car's line rather than a box's.
 */
function profile(k: Kit, parent: THREE.Object3D, pts: [number, number][], w: number, mat: Mat, x = 0): THREE.Mesh {
  const s = new THREE.Shape();
  s.moveTo(pts[0][0], pts[0][1]);
  for (const [u, v] of pts.slice(1)) s.lineTo(u, v);
  s.closePath();
  const g = new THREE.ExtrudeGeometry(s, { depth: w, bevelEnabled: false });
  g.rotateY(-Math.PI / 2);
  g.translate(w / 2, 0, 0);
  return k.add(parent, g, mat, x, 0, 0);
}

/**
 * A flat strip `w` wide and `t` thick laid from (z0, y0) to (z1, y1) in the side view: a raked windscreen
 * (lifted a hair off the slope it lies on, outward and up), or a rod when `w` is as thin as `t`.
 */
function strip(k: Kit, parent: THREE.Object3D, z0: number, y0: number, z1: number, y1: number, w: number, t: number, mat: Mat, x = 0, lift = 0.006): THREE.Mesh {
  const dz = z1 - z0, dy = y1 - y0, L = Math.hypot(dz, dy);
  let nz = -dy / L, ny = dz / L;
  if (ny < 0) { nz = -nz; ny = -ny; }
  const m = k.box(parent, w, L, t, mat, x, (y0 + y1) / 2 + ny * lift, (z0 + z1) / 2 + nz * lift);
  m.rotation.x = Math.atan2(dz, dy);
  return m;
}

/** A flashing lamp: `strobe` keeps it out of the merge, `lightbar` lets the police's siren drive it. */
function beacon(color: number, bar?: 'red' | 'blue'): THREE.MeshStandardMaterial {
  const m = new THREE.MeshStandardMaterial({ color, roughness: 0.35, metalness: 0, emissive: color, emissiveIntensity: 0.3, flatShading: true });
  m.userData.strobe = 1;
  if (bar) m.userData.lightbar = bar;
  return m;
}

/** A wheel with a white band round its chrome hub. */
function whitewall(k: Kit, b: THREE.Group, r: number, w: number, x: number, y: number, z: number, steer: boolean): void {
  const g = k.wheel(b, r, w, x, y, z, steer, CHROME);
  k.cyl(g.children[0], r * 0.74, r * 0.74, w + 0.006, 12, WHITE, 0, 0, 0, 'x');
}

/** A small person on a seat (cheaper than Kit.rider): a shirt and a head, origin at the seat. */
function sitter(k: Kit, parent: THREE.Object3D, x: number, y: number, z: number, shirt: number, hat?: number): void {
  k.box(parent, 0.13, 0.15, 0.09, shirt, x, y + 0.075, z);
  k.ball(parent, 0.055, 0xf2c39b, x, y + 0.2, z + 0.005, 1, 1, 1, 0);
  if (hat !== undefined) k.cyl(parent, 0.05, 0.065, 0.035, 8, hat, x, y + 0.255, z);
}

/** A five-pointed star `r` across, standing on a side of the body facing out along ±x. */
function star(k: Kit, parent: THREE.Object3D, r: number, mat: Mat, x: number, y: number, z: number): void {
  const s = new THREE.Shape();
  for (let i = 0; i < 10; i++) {
    const a = Math.PI / 2 + (i * Math.PI) / 5, rr = i % 2 ? r * 0.42 : r;
    if (i) s.lineTo(Math.cos(a) * rr, Math.sin(a) * rr); else s.moveTo(Math.cos(a) * rr, Math.sin(a) * rr);
  }
  const g = new THREE.ExtrudeGeometry(s, { depth: 0.01, bevelEnabled: false });
  g.translate(0, 0, -0.005);
  g.rotateY(Math.PI / 2);
  k.add(parent, g, mat, x, y, z);
}

