/** The pursuit car: a low black saloon with white doors and roof, a pushbar, grille lights and a slim bar. */
const interceptor: Build = (k, b, d, x) => {
  const p = d.color, steel = 0x55595e;
  k.box(b, 0.64, 0.2, 1.06, p, 0, 0.3, 0);
  // bonnet, waist and boot in one line; the greenhouse raked front and back
  profile(k, b, [[0.53, 0.4], [0.53, 0.43], [0.22, 0.47], [-0.38, 0.47], [-0.53, 0.45], [-0.53, 0.4]], 0.62, p);
  profile(k, b, [[0.22, 0.47], [0.03, 0.62], [-0.2, 0.62], [-0.38, 0.47]], 0.54, p);
  const g = k.glass();
  strip(k, b, 0.22, 0.47, 0.03, 0.62, 0.48, 0.012, g);
  strip(k, b, -0.38, 0.47, -0.2, 0.62, 0.46, 0.012, g);
  profile(k, b, [[0.17, 0.485], [0.035, 0.6], [-0.19, 0.6], [-0.325, 0.485]], 0.552, g);
  k.box(b, 0.556, 0.12, 0.035, p, 0, 0.54, -0.07);
  // white doors and roof, a gold star on each door
  k.box(b, 0.5, 0.012, 0.21, WHITE, 0, 0.626, -0.085);
  for (const sx of [-1, 1]) {
    k.box(b, 0.012, 0.17, 0.46, WHITE, sx * 0.322, 0.31, -0.04);
    k.box(b, 0.012, 0.012, 0.46, DARK, sx * 0.323, 0.225, -0.04);
    k.box(b, 0.014, 0.06, 0.06, GOLD, sx * 0.33, 0.33, 0.02);
  }
  // the slim lightbar, and the grille lights that flash with it
  const red = beacon(0xff2a1e, 'red'), blue = beacon(0x2a6bff, 'blue');
  k.box(b, 0.44, 0.022, 0.09, k.dark(), 0, 0.643, -0.09);
  k.box(b, 0.2, 0.038, 0.08, red, -0.105, 0.672, -0.09);
  k.box(b, 0.2, 0.038, 0.08, blue, 0.105, 0.672, -0.09);
  k.box(b, 0.3, 0.07, 0.02, k.dark(), 0, 0.35, 0.535);
  k.box(b, 0.06, 0.03, 0.02, red, -0.08, 0.35, 0.546);
  k.box(b, 0.06, 0.03, 0.02, blue, 0.08, 0.35, 0.546);
  x.beacons = [red, blue];
  // the pushbar on the nose
  for (const sx of [-1, 1]) {
    k.box(b, 0.035, 0.18, 0.035, k.dark(), sx * 0.15, 0.33, 0.6);
    k.box(b, 0.035, 0.03, 0.06, k.dark(), sx * 0.15, 0.3, 0.56);
  }
  k.box(b, 0.42, 0.03, 0.03, k.dark(), 0, 0.41, 0.605);
  k.box(b, 0.42, 0.03, 0.03, k.dark(), 0, 0.28, 0.605);
  // bumpers, the spotlight on the A-pillar, an aerial and the lamps
  k.box(b, 0.66, 0.06, 0.05, k.dark(), 0, 0.235, 0.54);
  k.box(b, 0.66, 0.06, 0.05, k.dark(), 0, 0.235, -0.54);
  k.cyl(b, 0.025, 0.025, 0.06, 8, k.chrome(), -0.29, 0.5, 0.2, 'z');
  k.cyl(b, 0.004, 0.004, 0.28, 4, k.dark(), 0.22, 0.6, -0.46);
  k.lights(b, 0.21, 0.36, 0.535, -0.535);
  for (const sz of [1, -1]) for (const sx of [-1, 1]) k.wheel(b, 0.16, 0.17, sx * 0.33, 0.16, sz * 0.35, sz > 0, steel);
};

