/** The hearse: a long low nose, a tall rear compartment in black vinyl with landau bars and curtained windows. */
const undertaker: Build = (k, b, d) => {
  const p = d.color, tint = k.mat(0x232b33, 0.15, 0.35), c = k.chrome(), vinyl = k.mat(0x1b1b1e, 0.85, 0);
  const curtain = k.mat(0xece6d6, 0.9, 0);
  k.box(b, 0.64, 0.22, 1.6, p, 0, 0.32, 0);
  profile(k, b, [[0.8, 0.43], [0.8, 0.46], [0.42, 0.48], [-0.8, 0.48], [-0.8, 0.43]], 0.62, p);
  profile(k, b, [[0.42, 0.48], [0.28, 0.72], [-0.76, 0.72], [-0.8, 0.68], [-0.8, 0.48]], 0.58, p);
  strip(k, b, 0.42, 0.48, 0.28, 0.72, 0.52, 0.012, tint);
  // the front door's glass, and the long windows of the rear compartment
  profile(k, b, [[0.37, 0.5], [0.27, 0.69], [0.08, 0.69], [0.08, 0.5]], 0.592, tint);
  profile(k, b, [[0.0, 0.5], [0.0, 0.69], [-0.5, 0.69], [-0.5, 0.5]], 0.592, tint);
  // the vinyl roof and rear quarters
  k.box(b, 0.586, 0.01, 1.02, vinyl, 0, 0.724, -0.27);
  for (const sx of [-1, 1]) {
    k.box(b, 0.008, 0.22, 0.26, vinyl, sx * 0.292, 0.6, -0.65);
    // curtains drawn back to the window's ends, and a valance with a gold fringe
    for (const z of [-0.045, -0.455]) k.box(b, 0.008, 0.18, 0.09, curtain, sx * 0.298, 0.595, z);
    k.box(b, 0.008, 0.035, 0.5, curtain, sx * 0.298, 0.672, -0.25);
    k.box(b, 0.009, 0.008, 0.5, GOLD, sx * 0.299, 0.652, -0.25);
    // the landau bar: a chrome S across each rear quarter
    const lx = sx * 0.299;
    strip(k, b, -0.54, 0.55, -0.6, 0.635, 0.012, 0.018, c, lx, 0);
    strip(k, b, -0.6, 0.635, -0.7, 0.652, 0.012, 0.018, c, lx, 0);
    strip(k, b, -0.7, 0.652, -0.765, 0.6, 0.012, 0.018, c, lx, 0);
    k.ball(b, 0.016, c, lx, 0.55, -0.54, 1, 1, 1, 0);
    k.box(b, 0.012, 0.015, 1.56, c, sx * 0.322, 0.43, 0);
  }
  // the tailgate's glass, curtained too
  k.box(b, 0.46, 0.17, 0.012, tint, 0, 0.59, -0.803);
  for (const sx of [-1, 1]) k.box(b, 0.1, 0.17, 0.008, curtain, sx * 0.17, 0.59, -0.811);
  k.box(b, 0.46, 0.03, 0.008, curtain, 0, 0.66, -0.811);
  // an upright grille, chrome bumpers, a mascot and the lamps
  k.box(b, 0.3, 0.13, 0.02, c, 0, 0.36, 0.803);
  for (const gx of [-0.1, -0.05, 0, 0.05, 0.1]) k.box(b, 0.01, 0.1, 0.02, k.dark(), gx, 0.36, 0.81);
  k.box(b, 0.66, 0.05, 0.06, c, 0, 0.23, 0.8);
  k.box(b, 0.66, 0.05, 0.06, c, 0, 0.23, -0.8);
  k.box(b, 0.015, 0.035, 0.05, c, 0, 0.49, 0.76);
  k.lights(b, 0.22, 0.37, 0.805, -0.805);
  for (const sx of [-1, 1]) {
    k.wheel(b, 0.18, 0.16, sx * 0.33, 0.18, 0.52, true, CHROME);
    k.wheel(b, 0.18, 0.16, sx * 0.33, 0.18, -0.5, false, CHROME);
  }
};

