/**
 * The state car: longer and heavier than the Grandee, with thick armoured pillars and small windows, an
 * armour lip round the roof, blue lights in the grille and a navy-and-gold pennant on each front wing.
 */
const statesman: Build = (k, b, d, x) => {
  const p = d.color, tint = k.mat(0x1e262e, 0.12, 0.4), c = k.chrome(), sill = 0x1c1d20;
  k.box(b, 0.66, 0.24, 2.48, p, 0, 0.34, 0);
  profile(k, b, [[1.24, 0.46], [1.24, 0.49], [0.86, 0.51], [-1.0, 0.51], [-1.24, 0.5], [-1.24, 0.46]], 0.64, p);
  profile(k, b, [[0.86, 0.51], [0.7, 0.7], [-0.86, 0.7], [-1.02, 0.51]], 0.6, p);
  k.box(b, 0.62, 0.025, 1.6, p, 0, 0.71, -0.08);
  // narrow windscreen and back light between thick pillars, and five small side windows a side
  strip(k, b, 0.84, 0.535, 0.73, 0.675, 0.44, 0.012, tint);
  strip(k, b, -1.0, 0.535, -0.89, 0.675, 0.4, 0.012, tint);
  for (const z of [0.5, 0.18, -0.14, -0.46, -0.74]) k.box(b, 0.612, 0.1, 0.2, tint, 0, 0.605, z);
  for (const sx of [-1, 1]) {
    k.box(b, 0.012, 0.015, 2.4, c, sx * 0.331, 0.445, 0);
    k.box(b, 0.012, 0.05, 1.9, sill, sx * 0.333, 0.25, -0.02);
    // the armoured doors' seams
    for (const z of [0.66, 0.34, 0.02, -0.3, -0.62]) k.box(b, 0.008, 0.2, 0.012, k.dark(), sx * 0.332, 0.35, z);
    // the wing flags: a chrome staff and a pennant streaming back, gold over navy
    const fx = sx * 0.27;
    k.box(b, 0.012, 0.2, 0.012, c, fx, 0.59, 1.06);
    k.tri(b, [fx, 0.685, 1.06], [fx, 0.645, 1.06], [fx, 0.645, 0.9], k.cloth(GOLD));
    k.tri(b, [fx, 0.645, 1.06], [fx, 0.605, 1.06], [fx, 0.645, 0.9], k.cloth(NAVY));
  }
  // the grille with its blue lights, heavy bumpers and the lamps
  k.box(b, 0.36, 0.13, 0.02, c, 0, 0.37, 1.243);
  k.box(b, 0.31, 0.1, 0.02, k.dark(), 0, 0.37, 1.249);
  for (const gx of [-0.105, -0.035, 0.035, 0.105]) k.box(b, 0.014, 0.1, 0.02, c, gx, 0.37, 1.254);
  const blues = [beacon(0x2a6bff), beacon(0x2a6bff)];
  k.box(b, 0.06, 0.035, 0.02, blues[0], -0.23, 0.31, 1.247);
  k.box(b, 0.06, 0.035, 0.02, blues[1], 0.23, 0.31, 1.247);
  x.beacons = blues;
  k.box(b, 0.68, 0.07, 0.07, c, 0, 0.24, 1.24);
  k.box(b, 0.68, 0.07, 0.07, c, 0, 0.24, -1.24);
  k.box(b, 0.015, 0.035, 0.05, c, 0, 0.525, 1.2);
  k.lights(b, 0.22, 0.38, 1.245, -1.245);
  for (const sx of [-1, 1]) {
    k.wheel(b, 0.18, 0.17, sx * 0.33, 0.18, 0.88, true, 0x9aa0a6);
    k.wheel(b, 0.18, 0.17, sx * 0.33, 0.18, -0.86, false, 0x9aa0a6);
  }
};

