/**
 * The fifties convertible: a long low body with chrome-edged tail fins and bullet tail lamps, whitewalls,
 * chrome bumpers, and a camera crane on the back deck turned on the star at the wheel. The soft top and
 * the passengers work as the Sunny's do (x.roof, x.seats).
 */
const marquee: Build = (k, b, d, x) => {
  const p = d.color, c = k.chrome(), carpet = 0xa02a35, canvas = 0xe9e1cf, rig = 0x2a2c30;
  k.box(b, 0.66, 0.2, 1.22, p, 0, 0.31, 0);
  // bonnet, back deck and the cockpit sunk between them
  profile(k, b, [[0.62, 0.41], [0.62, 0.45], [0.5, 0.475], [0.17, 0.475], [0.17, 0.41]], 0.64, p);
  profile(k, b, [[-0.27, 0.41], [-0.27, 0.475], [-0.52, 0.475], [-0.62, 0.44], [-0.62, 0.41]], 0.64, p);
  for (const sx of [-1, 1]) k.box(b, 0.05, 0.065, 0.44, p, sx * 0.295, 0.4425, -0.05);
  k.box(b, 0.54, 0.04, 0.44, carpet, 0, 0.43, -0.05);
  k.box(b, 0.5, 0.18, 0.06, CREAM, 0, 0.53, -0.08);
  k.box(b, 0.5, 0.16, 0.06, CREAM, 0, 0.52, -0.26);
  // the wraparound windscreen in a chrome frame
  const ws = k.group(b, 0, 0.475, 0.17);
  ws.rotation.x = -0.42;
  k.box(ws, 0.56, 0.17, 0.02, k.glass(), 0, 0.085, 0);
  k.box(ws, 0.58, 0.02, 0.03, c, 0, 0.175, 0);
  for (const sx of [-1, 1]) k.box(ws, 0.02, 0.18, 0.03, c, sx * 0.285, 0.09, 0);
  // tail fins, edged in chrome, a bullet lamp in each
  for (const sx of [-1, 1]) {
    const fx = sx * 0.3;
    profile(k, b, [[-0.28, 0.475], [-0.52, 0.475], [-0.625, 0.44], [-0.645, 0.6], [-0.6, 0.6]], 0.04, p, fx);
    strip(k, b, -0.28, 0.475, -0.6, 0.6, 0.046, 0.012, c, fx, 0.004);
    k.cyl(b, 0.024, 0.024, 0.04, 8, k.tail(), fx, 0.55, -0.645, 'z');
    // the side spear and whitewall wheels' arches
    k.box(b, 0.012, 0.018, 0.84, c, sx * 0.332, 0.36, 0.04);
  }
  // round headlamps under chrome hoods, a wide grille with bullets, bumpers and a mascot
  for (const sx of [-1, 1]) {
    k.cyl(b, 0.045, 0.045, 0.02, 10, k.lamp(), sx * 0.22, 0.38, 0.615, 'z');
    k.box(b, 0.11, 0.02, 0.04, c, sx * 0.22, 0.435, 0.6);
    k.ball(b, 0.03, c, sx * 0.15, 0.32, 0.635, 1, 1, 1.4, 0);
  }
  k.box(b, 0.5, 0.08, 0.02, c, 0, 0.3, 0.613);
  k.box(b, 0.44, 0.05, 0.02, k.dark(), 0, 0.3, 0.619);
  k.box(b, 0.68, 0.06, 0.06, c, 0, 0.24, 0.62);
  k.box(b, 0.68, 0.06, 0.06, c, 0, 0.24, -0.63);
  k.box(b, 0.015, 0.03, 0.06, c, 0, 0.49, 0.58);
  // a chrome strip and the boot lock across the tail
  k.box(b, 0.5, 0.02, 0.012, c, 0, 0.38, -0.616);
  k.box(b, 0.04, 0.03, 0.014, c, 0, 0.41, -0.616);
  // the star at the wheel, in shades and a scarf that streams back in the wind
  const star0 = k.rider(b, -0.13, 0.38, -0.03, WHITE);
  k.box(star0, 0.11, 0.025, 0.02, k.dark(), 0, 0.28, 0.08);
  const scarf = k.group(b, -0.13, 0.62, -0.09);
  k.box(scarf, 0.03, 0.03, 0.2, CORAL, 0, 0, -0.1);
  x.flag = scarf;
  x.seats = [
    k.rider(b, 0.13, 0.38, -0.03, TEAL),
    k.rider(b, -0.13, 0.37, -0.21, YELLOW),
    k.rider(b, 0.13, 0.37, -0.21, NAVY),
  ];
  // the camera crane on the back deck: a turret, a boom with its counterweight, the camera on the end
  const cx = 0.17, cz = -0.48, cy = 0.62, yaw = 0.6, tilt = 0.55, L = 0.34;
  k.cyl(b, 0.05, 0.06, 0.03, 8, rig, cx, 0.49, cz);
  k.box(b, 0.03, 0.12, 0.03, rig, cx, 0.56, cz);
  const boom = k.group(b, cx, cy, cz);
  boom.rotation.set(-tilt, yaw, 0, 'YXZ');
  k.box(boom, 0.025, 0.025, L + 0.1, rig, 0, 0, L / 2 - 0.05);
  k.box(boom, 0.06, 0.05, 0.06, DARK, 0, 0, -0.1);
  const h = L * Math.cos(tilt);
  const cam = k.group(b, cx + h * Math.sin(yaw), cy + L * Math.sin(tilt) - 0.035, cz + h * Math.cos(yaw));
  cam.rotation.y = -1.15;
  k.box(cam, 0.05, 0.065, 0.1, 0x15161a, 0, 0, 0);
  k.cyl(cam, 0.02, 0.026, 0.05, 8, k.mat(0x26313a, 0.15, 0.35), 0, 0, 0.07, 'z');
  for (const rz of [0.03, -0.03]) k.cyl(cam, 0.034, 0.034, 0.012, 10, 0x15161a, 0, 0.06, rz, 'x');
  // the soft top, hinged at the back of the cockpit
  k.box(b, 0.52, 0.05, 0.08, canvas, 0, 0.5, -0.31);
  const roof = k.group(b, 0, 0.475, -0.3);
  k.box(roof, 0.58, 0.03, 0.42, canvas, 0, 0.25, 0.21);
  k.box(roof, 0.58, 0.25, 0.03, canvas, 0, 0.125, 0.0);
  for (const sx of [-1, 1]) k.box(roof, 0.03, 0.2, 0.38, canvas, sx * 0.29, 0.15, 0.2);
  k.box(roof, 0.42, 0.08, 0.02, k.glass(), 0, 0.12, -0.012);
  x.roof = roof;
  for (const sz of [1, -1]) for (const sx of [-1, 1]) whitewall(k, b, 0.17, 0.16, sx * 0.33, 0.17, sz * 0.38, sz > 0);
};

/**
 * The tour bus: a double-decker with its top deck open, rows of seats and a rail round it, an open
 * platform and stairs at the back, big windows below, a gold star on each flank and a few sightseers.
 */
const starTours: Build = (k, b, d) => {
  const p = d.color, g = k.glass(), c = k.chrome(), deck = 0x6b6f75, seat = 0xb02a3a, steel = 0x8a8f96;
  // the lower deck, cut short at the back for the platform
  k.box(b, 0.66, 0.46, 1.48, p, 0, 0.47, 0.08);
  k.box(b, 0.33, 0.46, 0.16, p, -0.165, 0.47, -0.74);
  k.box(b, 0.66, 0.06, 0.16, k.dark(), 0, 0.27, -0.74);
  // the platform's back wall: proud of the lower deck's end (flush with it, the two flashed through each other)
  k.box(b, 0.2, 0.32, 0.012, k.dark(), 0.165, 0.46, -0.668);
  for (let i = 0; i < 5; i++) k.box(b, 0.06, 0.03, 0.15, steel, 0.28 - i * 0.055, 0.33 + i * 0.085, -0.74);
  k.cyl(b, 0.012, 0.012, 0.46, 6, c, 0.315, 0.5, -0.81);
  // big windows below, the door forward on the kerb side
  for (const sx of [-1, 1]) for (const z of [0.6, 0.3, 0, -0.3, -0.6]) {
    if (sx > 0 && (z === 0.6 || z === -0.6)) continue;
    k.box(b, 0.03, 0.22, 0.26, g, sx * 0.332, 0.54, z);
  }
  k.box(b, 0.03, 0.38, 0.18, k.dark(), 0.333, 0.45, 0.62);
  for (const z of [0.58, 0.66]) k.box(b, 0.032, 0.26, 0.065, g, 0.334, 0.5, z);
  k.box(b, 0.6, 0.24, 0.03, g, 0, 0.52, 0.82);
  k.box(b, 0.26, 0.2, 0.012, g, -0.165, 0.54, -0.82);
  k.box(b, 0.44, 0.05, 0.03, k.lamp(), 0, 0.672, 0.825);
  // the band between the decks, and the open top deck: floor, half-height sides, a screen at the front
  k.box(b, 0.68, 0.04, 1.66, CREAM, 0, 0.72, 0);
  k.box(b, 0.62, 0.02, 1.58, deck, 0, 0.745, 0);
  for (const sx of [-1, 1]) {
    k.box(b, 0.04, 0.2, 1.64, p, sx * 0.31, 0.84, 0);
    star(k, b, 0.09, GOLD, sx * 0.333, 0.84, 0);
    for (const z of [0.78, 0.4, 0, -0.4, -0.78]) k.box(b, 0.015, 0.06, 0.015, c, sx * 0.31, 0.97, z);
    k.box(b, 0.018, 0.018, 1.62, c, sx * 0.31, 1.0, 0);
  }
  k.box(b, 0.66, 0.2, 0.04, p, 0, 0.84, 0.8);
  k.box(b, 0.66, 0.2, 0.04, p, 0, 0.84, -0.8);
  k.box(b, 0.6, 0.09, 0.02, g, 0, 0.985, 0.8);
  k.box(b, 0.64, 0.018, 0.018, c, 0, 1.0, -0.8);
  // the stairwell at the back on the kerb side: a hole in the floor and a rail round it
  k.box(b, 0.26, 0.004, 0.15, k.dark(), 0.155, 0.757, -0.71);
  k.box(b, 0.015, 0.015, 0.18, c, 0.02, 0.92, -0.71);
  k.box(b, 0.28, 0.015, 0.015, c, 0.16, 0.92, -0.62);
  k.box(b, 0.015, 0.16, 0.015, c, 0.02, 0.84, -0.62);
  // seven rows of benches either side of the aisle, the last on the kerb side giving way to the stairs
  for (const z of [0.62, 0.42, 0.22, 0.02, -0.18, -0.38, -0.56]) for (const sx of [-1, 1]) {
    if (sx > 0 && z < -0.5) continue;
    k.box(b, 0.24, 0.05, 0.11, seat, sx * 0.16, 0.79, z);
    k.box(b, 0.24, 0.12, 0.03, seat, sx * 0.16, 0.86, z - 0.055);
  }
  sitter(k, b, -0.2, 0.815, 0.62, CORAL, YELLOW);
  sitter(k, b, 0.12, 0.815, 0.42, TEAL);
  sitter(k, b, -0.12, 0.815, 0.02, YELLOW, WHITE);
  sitter(k, b, 0.2, 0.815, -0.38, WHITE);
  k.box(b, 0.7, 0.07, 0.06, k.dark(), 0, 0.26, 0.83);
  k.box(b, 0.7, 0.07, 0.06, k.dark(), 0, 0.22, -0.83);
  // the lamps (the tail lamps low, on the platform's sill)
  for (const sx of [-1, 1]) {
    k.box(b, 0.1, 0.08, 0.03, k.lamp(), sx * 0.24, 0.36, 0.825);
    k.box(b, 0.1, 0.05, 0.03, k.tail(), sx * 0.24, 0.27, -0.825);
  }
  for (const sx of [-1, 1]) {
    k.wheel(b, 0.19, 0.16, sx * 0.34, 0.19, 0.55, true);
    k.wheel(b, 0.19, 0.16, sx * 0.34, 0.19, -0.48);
  }
};

