import * as THREE from 'three';
import type { Looks, VehicleDef } from '../game/vehicles';

/**
 * Workshop parts on a vehicle's body (docs/upgrades.html): the paint's finish and second colour,
 * bigger and wider tyres with the body lifted to suit, hubs coloured by the brakes, and the bolt-ons
 * (a bonnet scoop, pipes, nitrous bottles, a rack, a bull bar, a snorkel, a keel, pods, wing tips).
 *
 * The scope planned a hand-written anchor per model. Instead each body is measured once it is built:
 * the box its static parts fill, and the height of whatever is at a point from above. A roof box then
 * sits on the Mule's cab and on the Tomato's roof without either being told where that is.
 *
 * Runs on the builder's own units, after the model is built and before its parts are merged, so every
 * bolt-on merges into the body like the rest of it. Returns how far the body is lifted, which the pose adds.
 */

const DARK = 0x2a2a2e, CHROME = 0xd9dde2, WHITE = 0xf4f2ec, WOOD = 0xb07a4a, GREY = 0x3a4a55, BLUE = 0x2f7fd8;
const YELLOW = 0xf2c12e, STEEL = 0x5d656e;
const HUBS = [0, 0xd2342a, 0xf2c14e, 0xd9b34a];
/** Tyre radius and width by tier. */
const TYRE_R = [1, 1, 1.15, 1.35];
const TYRE_W = [1, 1.4, 1.5, 1.6];
const RIDE = [0, -0.01, 0.03, 0.06];
/**
 * Where a rack goes on the models whose middle isn't a roof (a rider, an ice cream): a share of the
 * length from the tail. Everything else takes it just behind the middle, on whatever is highest there.
 */
const RACK_AT: Record<string, number> = { zippy: 0.1, pip: 0.08, splash: 0.72, sundae: 0.86, breeze: 0.3 };

/**
 * Where the nitrous bottles lie on models whose rear isn't clear (the user, 11 Nov 2026), in model units: x for one
 * bottle, x for each of two, the height they rest on, and their middle along the car. The Mule's sat on the crate
 * in its bed, so they lie along the bed's side rails; the Bramble's ran into its roof box, so they are
 * strapped beside it on the roof.
 */
const NOS_AT: Record<string, { one: number; two: [number, number]; y: number; z: number }> = {
  mule: { one: 0.295, two: [-0.295, 0.295], y: 0.61, z: -0.3 },
  bramble: { one: 0.27, two: [-0.27, 0.27], y: 0.88, z: -0.13 },
  // the Big Bertha's trailer covers everything behind the cab: on the chassis sides between the wheels instead
  bertha: { one: 0.38, two: [-0.38, 0.38], y: 0.255, z: 0 },
  // the Sundae's sat on its cherry: on the roof behind the cone instead
  sundae: { one: 0, two: [-0.13, 0.13], y: 0.97, z: -0.46 },
  // the Clod's flanks are its rear tyres: on the bonnet, beside the exhaust stack
  clod: { one: -0.07, two: [-0.09, 0.01], y: 0.54, z: 0.2 },
  // the Sandy's flanks are inside its roll cage: on the rear deck either side of the engine
  sandy: { one: 0.21, two: [-0.21, 0.21], y: 0.41, z: -0.43 },
  // the Wasabi's stood up on its deck stripes: low on the rear deck outboard of them, ahead of the ducktail
  wasabi: { one: 0.2, two: [-0.2, 0.2], y: 0.37, z: -0.36 },
  // the Cabbie's hung off the back of its roof: either side of the taxi sign
  cab: { one: 0.17, two: [-0.17, 0.17], y: 0.685, z: -0.12 },
};
/** Where a model's bottles lie, when it has a spot of its own (for the workshop's labels, game/workshopView.ts). */
export const nosSpot = (id: string): { x: number; y: number; z: number } | undefined => {
  const at = NOS_AT[id];
  return at && { x: at.one, y: at.y + 0.045, z: at.z };
};
/**
 * Where the Lifted suspension's snorkel stands, where the side of the cab is over a wheel (the Clod's rose through
 * its rear tyre): its foot and head heights.
 */
const SNORKEL_AT: Record<string, { x: number; z: number; y0: number; y1: number }> = {
  clod: { x: -0.1, z: 0.36, y0: 0.54, y1: 0.95 },
};
/**
 * Where the exhaust leaves on models whose rearmost part is not the body (the Bramble's spare wheel on the
 * tailgate): the back of the bumper, so the pipes come out under the spare, not from behind it.
 */
const PIPES_AT: Record<string, { z: number; x?: number; y?: number; cx?: number }> = {
  bramble: { z: -0.61 },
  // the Zippy's: beside its rear wheel at its own exhaust's height, not through the tyre
  zippy: { z: -0.33, x: 0.1, y: 0.22 },
  // the Big Bertha's: out under the cab doors between the wheels, below the bottles; behind the cab the trailer hides them
  bertha: { z: 0, x: 0.36, y: 0.17 },
  // the Stomper's: out of the back of the body, not down between its rear tyres where nothing showed
  stomper: { z: -0.5, y: 0.72 },
  // the Sandy's engine is the block at the back: its pipes leave under the spare wheel
  sandy: { z: -0.5, x: 0.1, y: 0.4 },
  // the Pip's engine sits to the right of the seat: its pipes leave the block over the rear bar (cx: their middle)
  pip: { z: -0.4, x: 0.045, cx: 0.1, y: 0.27 },
  // the Wasabi's ran into its own twin pipes: a pair outboard of them, under the lamps
  wasabi: { z: -0.55, x: 0.21, y: 0.2 },
  // the Cabbie's came out beside its tail lights: under the bumper
  cab: { z: -0.54, y: 0.19 },
};
/** Where the engine's scoop sits when the top of the model is a rider's head (the Zippy's: on the tank). */
const SCOOP_AT: Record<string, { y: number; z: number; w: number; x?: number }> = {
  zippy: { y: 0.495, z: 0.14, w: 0.09 },
  // the Sandy is rear-engined: the scoop sits on the engine block behind the cage, not on the empty nose
  sandy: { y: 0.55, z: -0.4, w: 0.16 },
  pip: { y: 0.3, z: -0.32, w: 0.12, x: 0.1 },
};
/**
 * A motorbike's bull bar is crash bars round its engine, not a bar across the nose (which on the Zippy sat inside
 * the front wheel): the engine's half-width, its top and front, and how far back the rail runs.
 */
const CRASH_BARS: Record<string, { x: number; y0: number; y1: number; z0: number; z1: number }> = {
  zippy: { x: 0.12, y0: 0.18, y1: 0.37, z0: 0.12, z1: -0.08 },
};
/** Open vehicles, where a bottle on top would sit on the rider: theirs go on the flank. */
export const FLANK_BOTTLES = new Set(['zippy', 'pip', 'sandy', 'splash', 'clod']);

interface Part { mesh: THREE.Mesh; box: THREE.Box3 }

export function dressVehicle(root: THREE.Object3D, body: THREE.Group, def: VehicleDef, wheels: THREE.Object3D[], spinning: THREE.Object3D[] = []): number {
  const looks = def.looks;
  if (!looks || def.kind === 'rail') return 0;
  root.updateMatrixWorld(true);
  const inWheel = new Set<THREE.Object3D>();
  for (const w of wheels) w.parent?.traverse((o) => inWheel.add(o));
  const parts: Part[] = [];
  body.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh || inWheel.has(m)) return;
    m.geometry.computeBoundingBox();
    parts.push({ mesh: m, box: m.geometry.boundingBox!.clone().applyMatrix4(m.matrixWorld) });
  });
  if (!parts.length) return 0;
  const all = new THREE.Box3();
  for (const p of parts) all.union(p.box);
  const kit = new BoltKit(body);

  paint(parts, looks);
  let lift = 0;
  if (def.kind === 'land') lift = tyres(body, wheels, looks);
  else hubs(body, wheels, looks);

  const top = (x: number, z: number): number => {
    let y = -Infinity;
    for (const p of parts) {
      const b = p.box;
      if (x >= b.min.x - 0.02 && x <= b.max.x + 0.02 && z >= b.min.z - 0.02 && z <= b.max.z + 0.02) y = Math.max(y, b.max.y);
    }
    return Number.isFinite(y) ? y : all.max.y;
  };
  const len = all.max.z - all.min.z, wid = all.max.x - all.min.x;
  const nose = all.max.z, tail = all.min.z, mid = (all.max.z + all.min.z) / 2;

  // ---- the model's real surfaces (the user, 11 Nov 2026: parts floated, sank or clashed wherever the model's
  // outer box was not its body — a rotor, a spare wheel, a rider's head, a mast, a hull narrowing to the waterline).
  // Rays against the still, unlit parts find the actual surface under, beside, behind or in front of a point.
  const inSpin = new Set<THREE.Object3D>();
  for (const o of spinning) o.traverse((c) => inSpin.add(c));
  const lit = (p: Part) => {
    const m = p.mesh.material as THREE.MeshStandardMaterial;
    return !!m.emissive && m.emissiveIntensity > 0 && m.emissive.getHex() !== 0;
  };
  const still = parts.filter((p) => !inSpin.has(p.mesh));
  const solid = still.filter((p) => !lit(p));
  const lamps = parts.filter(lit).map((p) => p.box);
  const solidMeshes = solid.map((p) => p.mesh);
  const foot = new Map(solid.map((p) => [p.mesh as THREE.Object3D, (p.box.max.x - p.box.min.x) * (p.box.max.z - p.box.min.z)]));
  const ray = new THREE.Raycaster(), o3 = new THREE.Vector3(), d3 = new THREE.Vector3(), n3 = new THREE.Vector3();
  const mats = [...new Set(solidMeshes.map((m) => m.material as THREE.Material))];
  const cast = (ox: number, oy: number, oz: number, dx: number, dy: number, dz: number) => {
    ray.set(o3.set(ox, oy, oz), d3.set(dx, dy, dz));
    const sides = mats.map((m) => m.side);
    for (const m of mats) m.side = THREE.DoubleSide;
    try { return ray.intersectObjects(solidMeshes, false); } finally { mats.forEach((m, i) => { m.side = sides[i]; }); }
  };
  const normalY = (h: THREE.Intersection) => (h.face ? n3.copy(h.face.normal).transformDirection(h.object.matrixWorld).y : 0);
  const widest = (hs: THREE.Intersection[]) => hs.reduce((a, b) => ((foot.get(b.object) ?? 0) > (foot.get(a.object) ?? 0) ? b : a));
  const bigFoot = Math.max(0, ...foot.values()) * 0.12;
  /** The first upward-facing surface below (x, z); with `big` the first of a part of some size (a deck, not a mast's top). */
  const below = (x: number, z: number, big = false): number => {
    const hs = cast(x, all.max.y + 1, z, 0, -1, 0).filter((h) => normalY(h) > 0.6);
    if (!hs.length) return NaN;
    return big ? (hs.find((h) => (foot.get(h.object) ?? 0) >= bigFoot) ?? hs[0]).point.y : hs[0].point.y;
  };
  /** The underside of the widest part over (x, z): a belly, not a wheel leg. */
  const belly = (x: number, z: number): number => {
    const hs = cast(x, all.min.y - 1, z, 0, 1, 0).filter((h) => normalY(h) < -0.6);
    return hs.length ? widest(hs).point.y : NaN;
  };
  /** How far out the side is at height y and z (the right side; the models are symmetric). */
  const side = (y: number, z: number): number => {
    const h = cast(all.max.x + 1, y, z, -1, 0, 0)[0];
    return h ? h.point.x : NaN;
  };
  /** The back face at (x, y), and the front face. */
  const back = (x: number, y: number): number => { const h = cast(x, y, tail - 1, 0, 0, 1)[0]; return h ? h.point.z : NaN; };
  const front = (x: number, y: number): number => { const h = cast(x, y, nose + 1, 0, 0, -1)[0]; return h ? h.point.z : NaN; };
  const overLamp = (b: THREE.Box3) => lamps.some((l) => l.intersectsBox(b));
  const or = (v: number, f: number) => (Number.isFinite(v) ? v : f);

  // a rival firm's board on the roof, in its accent, so its vans read as its vans (docs/rivals.html)
  if (def.livery !== undefined) {
    if (def.kind === 'land') kit.box(Math.min(0.36, wid * 0.6), 0.07, 0.12, def.livery, 0, top(0, mid - len * 0.12) + 0.04, mid - len * 0.12);
    else kit.box(0.02, 0.16, 0.2, def.livery, 0, top(0, tail + len * 0.15) + 0.09, tail + len * 0.15);
  }
  if (def.kind === 'land') {
    kit.tag = 'engine';
    if (looks.engine >= 2) {
      const at = SCOOP_AT[def.id];
      if (at) kit.box(at.w, 0.05, 0.14, DARK, at.x ?? 0, at.y + 0.022, at.z);
      else {
        // on the bonnet's real surface, stepped back off any lamp or beacon there
        const sw = Math.min(0.18, wid * 0.4);
        let z = nose - len * 0.18, y = or(below(0, z), top(0, z));
        for (let k = 0; k < 6 && overLamp(new THREE.Box3(new THREE.Vector3(-sw / 2, y - 0.01, z - 0.07), new THREE.Vector3(sw / 2, y + 0.06, z + 0.07))); k++) {
          z -= 0.05;
          y = or(below(0, z), top(0, z));
        }
        kit.box(sw, 0.05, 0.14, DARK, 0, y + 0.022, z);
      }
    }
    if (looks.engine >= 3) {
      const at = PIPES_AT[def.id];
      let y = at?.y ?? Math.max(0.16, all.min.y + 0.14), end = at?.z ?? tail;
      const x = at?.x ?? Math.min(0.12, wid * 0.25);
      if (!at) {
        // low, just under the bumper, out of the rear face that is really there at that height (clear of the lamps)
        for (const h of [0.05, 0.09, 0.14]) {
          const yy = Math.max(0.1, all.min.y + h), zz = back(x, yy);
          if (!Number.isFinite(zz) || zz > tail + 0.2) continue;
          if (overLamp(new THREE.Box3(new THREE.Vector3(x - 0.03, yy - 0.03, zz - 0.12), new THREE.Vector3(x + 0.03, yy + 0.03, zz + 0.03)))) continue;
          y = yy; end = zz;
          break;
        }
      }
      for (const sx of [-1, 1]) {
        const cx = (at?.cx ?? 0) + sx * x;
        kit.cyl(0.026, 0.14, CHROME, cx, y, end - 0.04, 'z');
        kit.cyl(0.018, 0.01, 0xff8a3a, cx, y, end - 0.112, 'z', 0.7);
      }
    }
    let rackZ = NaN, rackD = 0, rackW = 0, rackTop = 0;
    kit.tag = 'rack';
    if (looks.rack) {
      const at = RACK_AT[def.id];
      let z = at !== undefined ? tail + len * at + 0.1 : mid - len * 0.05, d = Math.min(at !== undefined ? 0.3 : 0.46, len * 0.4);
      const w = Math.min(0.42, wid * 0.62);
      let y = top(0, z);
      // off any roof lamps: its front edge stops short of them (the Stomper's roof bar)
      const hit = lamps.filter((l) => l.max.y >= y - 0.06 && l.max.x > -w / 2 && l.min.x < w / 2 && l.max.z > z - d / 2 && l.min.z < z + d / 2);
      if (hit.length) {
        const stop = Math.min(...hit.map((l) => l.min.z)) - 0.02, rear = z - d / 2;
        if (stop - rear >= 0.15) { d = stop - rear; z = (stop + rear) / 2; y = top(0, z); }
      }
      rackZ = z; rackD = d; rackW = w; rackTop = y + (looks.rack >= 2 ? 0.03 : 0) + (looks.rack === 3 ? 0.25 : 0.12);
      if (looks.rack >= 2) for (const sx of [-1, 1]) kit.box(0.03, 0.03, d + 0.06, DARK, sx * w * 0.5, y + 0.015, z);
      const boxes = looks.rack === 1 ? 1 : looks.rack === 2 ? 2 : 3;
      for (let k = 0; k < boxes; k++) {
        const bz = boxes === 1 ? z : z + (k === 2 ? 0 : (k === 0 ? -1 : 1) * d * 0.25);
        const by = y + (looks.rack >= 2 ? 0.03 : 0) + (k === 2 ? 0.13 : 0);
        kit.box(w * (boxes === 1 ? 0.8 : 0.9), 0.12, boxes === 1 ? d * 0.8 : d * 0.45, k === 2 ? WOOD : GREY, 0, by + 0.06, bz);
      }
    }
    kit.tag = 'nitrous';
    /**
     * A bottle, unless the rack is there: then behind the rack on the same surface when there is room, else
     * strapped on top of the rack (a fixed spot of a model's own shared the roof with the rack's boxes).
     */
    const place = (x: number, y: number, z: number) => {
      if (Number.isFinite(rackZ)) {
        const rb = new THREE.Box3(new THREE.Vector3(-rackW / 2, y - 0.2, rackZ - rackD / 2), new THREE.Vector3(rackW / 2, rackTop, rackZ + rackD / 2));
        const bb = new THREE.Box3(new THREE.Vector3(x - 0.045, y - 0.045, z - 0.12), new THREE.Vector3(x + 0.045, y + 0.045, z + 0.16));
        if (rb.intersectsBox(bb)) {
          const zb = rackZ - rackD / 2 - 0.17, yb = below(x, zb);
          if (zb - 0.12 >= tail && Number.isFinite(yb) && Math.abs(yb + 0.045 - y) < 0.12) { z = zb; y = yb + 0.045; }
          else { y = rackTop + 0.045; z = rackZ; x = Math.max(-rackW / 2 + 0.05, Math.min(rackW / 2 - 0.05, x)); }
        }
      }
      bottle(kit, x, y, z);
    };
    if (looks.nitrous) {
      const at = NOS_AT[def.id];
      if (at) {
        for (const x of looks.nitrous === 3 ? at.two : [at.one]) place(x, at.y + 0.045, at.z);
      } else if (FLANK_BOTTLES.has(def.id)) {
        const sides = looks.nitrous === 3 ? [-1, 1] : [1];
        const y = Math.max(0.28, all.min.y + 0.26), z = mid - len * 0.1;
        // against the flank that is there at that height, not a guess from the widest part
        const x = or(side(y, z) + 0.035, all.max.x * 0.55 + 0.05);
        for (const sx of sides) place(sx * x, y, z);
      } else {
        let z = tail + len * 0.22;
        // behind the rack when one is fitted: they shared the roof and the bottles sat under the boxes
        if (Number.isFinite(rackZ) && z + 0.16 > rackZ - rackD / 2 && z - 0.12 < rackZ + rackD / 2) z = Math.max(tail + 0.13, rackZ - rackD / 2 - 0.17);
        const xs = looks.nitrous === 3 ? [-0.07, 0.07] : [0];
        // lying on the real surface along the bottle's length: the top of a box under a sloping roof had them inside it
        for (const x of xs) {
          const y = Math.max(or(below(x, z), top(x, z)), or(below(x, z + 0.1), -Infinity), or(below(x, z - 0.1), -Infinity));
          place(x, y + 0.045, z);
        }
      }
    }
    kit.tag = 'bullbar';
    const crash = looks.bullbar ? CRASH_BARS[def.id] : undefined;
    if (crash) {
      // an upright either side of the engine's front and a rail back along its top; chrome from the second tier,
      // and a skid plate under the engine at the third
      const c = looks.bullbar === 1 ? DARK : CHROME, h = crash.y1 - crash.y0, d = crash.z0 - crash.z1;
      for (const sx of [-1, 1]) {
        kit.box(0.03, h, 0.03, c, sx * crash.x, crash.y0 + h / 2, crash.z0);
        kit.box(0.03, 0.03, d, c, sx * crash.x, crash.y1, crash.z1 + d / 2);
        if (looks.bullbar >= 2) kit.box(0.03, 0.03, d, c, sx * crash.x, crash.y0 + 0.02, crash.z1 + d / 2);
      }
      if (looks.bullbar >= 2) kit.box(crash.x * 2 + 0.03, 0.03, 0.03, c, 0, crash.y1, crash.z0);
      if (looks.bullbar >= 3) kit.box(crash.x * 1.6, 0.03, d + 0.04, DARK, 0, crash.y0 - 0.01, crash.z1 + d / 2);
    } else if (looks.bullbar) {
      body.updateMatrixWorld(true);
      bullbar(kit, parts.filter((p) => !lit(p)), looks.bullbar, Math.max(0.2, all.min.y + 0.12), wid, nose, lamps, wheels.map((w) => new THREE.Box3().setFromObject(w)));
    }
    kit.tag = 'suspension';
    if (looks.suspension >= 3) {
      // up the side of the cab to just over its roof, and no higher whatever sits on top
      const at = SNORKEL_AT[def.id];
      const y0 = at ? at.y0 : Math.max(0.25, all.min.y + 0.2);
      const z = at ? at.z : nose - len * 0.3;
      // against the side that is there (a narrow body left it standing in the air beside it)
      const x = at ? at.x : or(side(y0 + 0.08, z) + 0.024, all.max.x + 0.015);
      const y1 = at ? at.y1 : Math.min(top(x - 0.05, z) + 0.1, y0 + 0.55);
      kit.cyl(0.022, y1 - y0, DARK, x, (y0 + y1) / 2, z, 'y');
      kit.box(0.06, 0.05, 0.07, DARK, x, y1, z + 0.02);
    }
  } else if (def.kind === 'water') {
    // the outboard: on the first deck forward of the stern (a paddle wheel or open stern had it hanging in the air),
    // and forward of any stern lamp
    let motorZ = tail + 0.06, motorY = NaN;
    for (const dz of [0.08, 0.15, 0.25, 0.35]) {
      const y = below(0, tail + dz);
      if (!Number.isFinite(y)) continue;
      const z = tail + dz - 0.02;
      if (overLamp(new THREE.Box3(new THREE.Vector3(-0.07, y, z - 0.06), new THREE.Vector3(0.07, y + 0.12, z + 0.06)))) continue;
      motorZ = z; motorY = y;
      break;
    }
    kit.tag = 'engine';
    if (looks.engine >= 2) kit.box(0.14, 0.12, 0.12, DARK, 0, or(motorY, top(0, tail + 0.08)) + 0.06, motorZ);
    const at = RACK_AT[def.id];
    const zc = at !== undefined ? tail + len * at : mid;
    const n = looks.rack + 1;
    const cargo0 = zc - (n - 1) / 2 * 0.12 - 0.07, cargo1 = zc + (n - 1) / 2 * 0.12 + 0.07;
    kit.tag = 'rack';
    if (looks.rack) {
      for (let k = 0; k < n; k++) {
        const x = (k % 2 ? 1 : -1) * wid * 0.14, z = zc + (k - (n - 1) / 2) * 0.12;
        // on the deck (the widest surface under it), not the top of a mast or rail above it
        const y = or(below(x, z, true), top(0, zc));
        kit.box(wid * 0.22, 0.1, 0.14, k % 2 ? GREY : WOOD, x, y + 0.05 + (k >= 2 ? 0.1 : 0), z);
      }
    }
    kit.tag = 'nitrous';
    if (looks.nitrous) {
      if (FLANK_BOTTLES.has(def.id)) {
        const z = tail + len * 0.3, y = 0.16;
        const x = or(side(y, z) + 0.035, all.max.x * 0.7);
        for (const sx of looks.nitrous === 3 ? [-1, 1] : [1]) bottle(kit, sx * x, y, z);
      } else {
        // ahead of the outboard's cowl, which had the bottles inside it on small boats, and off the deck crates
        let z = tail + len * 0.2;
        if (looks.engine >= 2) z = Math.max(z, motorZ + 0.06 + 0.14);
        if (looks.rack && z + 0.16 > cargo0 && z - 0.12 < cargo1) {
          const behind = cargo0 - 0.17, ahead = cargo1 + 0.13;
          z = behind - 0.12 >= (looks.engine >= 2 ? motorZ + 0.06 : tail) ? behind : ahead;
        }
        for (const x of looks.nitrous === 3 ? [-0.07, 0.07] : [0]) bottle(kit, x, or(below(x, z), top(x, z)) + 0.045, z);
      }
    }
    /** The run of the hull at height y that is near its widest: where a strip along it can lie without leaving it. */
    const skin = (y: number): { x: number; z0: number; z1: number } | null => {
      const s: { z: number; x: number }[] = [];
      for (let k = 0; k <= 24; k++) {
        const z = tail + 0.02 + (len - 0.04) * (k / 24), x = side(y, z);
        if (Number.isFinite(x)) s.push({ z, x });
      }
      if (s.length < 3) return null;
      const mx = Math.max(...s.map((e) => e.x)), keep = s.filter((e) => e.x >= mx * 0.93);
      return { x: Math.min(...keep.map((e) => e.x)), z0: Math.min(...keep.map((e) => e.z)), z1: Math.max(...keep.map((e) => e.z)) };
    };
    kit.tag = 'hull';
    if (looks.hull) {
      const hi = skin(0.03);
      const loY = Math.max(all.min.y, -0.1) + 0.02, lo = looks.hull >= 2 ? skin(loY) : null;
      for (const sx of [-1, 1]) {
        if (hi) kit.box(0.02, 0.03, Math.max(0.1, hi.z1 - hi.z0), WHITE, sx * (hi.x + 0.002), 0.03, (hi.z0 + hi.z1) / 2);
        else kit.box(0.02, 0.03, len * 0.8, WHITE, sx * (all.max.x + 0.005), 0.03, mid);
        if (looks.hull >= 2) {
          if (lo) kit.box(0.03, 0.02, Math.max(0.1, lo.z1 - lo.z0), DARK, sx * (lo.x + 0.006), loY, (lo.z0 + lo.z1) / 2);
          else kit.box(0.03, 0.02, len * 0.6, DARK, sx * (all.max.x * 0.8), loY, mid + len * 0.1);
        }
      }
      if (looks.hull >= 3) {
        // the keel hangs from the hull's real bottom
        const bottom = or(belly(0, mid), all.min.y);
        kit.box(0.04, 0.12, len * 0.45, DARK, 0, bottom - 0.04, mid);
      }
    }
    kit.tag = 'bullbar';
    if (looks.bullbar) {
      const n = looks.bullbar + 1;
      for (let k = 0; k < n; k++) {
        const z = mid + (k - (n - 1) / 2) * len * 0.22;
        let y = 0.08, x = NaN;
        for (const yy of [0.08, 0.05, 0.02]) { x = side(yy, z); if (Number.isFinite(x)) { y = yy; break; } }
        if (!Number.isFinite(x)) continue;
        for (const sx of [-1, 1]) kit.ball(0.04, DARK, sx * (x + 0.03), y, z);
      }
      if (looks.bullbar >= 3) kit.box(wid * 0.35, 0.1, 0.06, WHITE, 0, 0.12, or(front(0, 0.12) + 0.01, nose - 0.02));
    }
  } else if (def.kind === 'air') {
    kit.tag = 'rack';
    if (looks.rack) {
      const n = looks.rack === 1 ? 1 : 2, r = 0.07 * (looks.rack === 3 ? 1.4 : 1);
      for (let k = 0; k < n; k++) {
        const x = n === 1 ? 0 : (k ? 1 : -1) * Math.min(0.3, wid * 0.25);
        // slung under the belly (or the wing) above it, not at the bottom of the undercarriage, and off any lamp there
        let z = mid, y = all.min.y + 0.02;
        for (const dz of [0, -0.12, 0.12, -0.24, 0.24]) {
          const yy = or(belly(x, mid + dz) - r * 0.8 * 0.6, all.min.y + 0.02), zz = mid + dz;
          z = zz; y = yy;
          if (!overLamp(new THREE.Box3(new THREE.Vector3(x - r, yy - r * 0.8, zz - r * 2.2), new THREE.Vector3(x + r, yy + r * 0.8, zz + r * 2.2)))) break;
        }
        kit.ball(r, GREY, x, y, z, 1, 0.8, 2.2);
      }
    }
    kit.tag = 'wings';
    if (looks.wings) {
      const s = 0.1 + 0.05 * looks.wings;
      // the winglets go on the airframe, not the rotor disc: a helicopter's main rotor is its widest part, and
      // sized by it they floated off the rotor tips, halfway up between the skids and the blades (the user, 11 Nov 2026)
      const hull = new THREE.Box3();
      for (const p of still) hull.union(p.box);
      const rotor = !hull.isEmpty() && parts.some((p) => inSpin.has(p.mesh) && p.box.max.x - p.box.min.x > (hull.max.x - hull.min.x) * 1.5);
      let x = all.max.x, y = (all.min.y + all.max.y) / 2, z = tail + len * 0.2;
      if (rotor) {
        // stubs either side of the tail boom, at the boom's own height and width
        z = hull.min.z + (hull.max.z - hull.min.z) * 0.2;
        const at = new THREE.Box3();
        for (const p of still) if (z >= p.box.min.z - 0.02 && z <= p.box.max.z + 0.02) at.union(p.box);
        const b = at.isEmpty() ? hull : at;
        x = b.max.x;
        y = (b.min.y + b.max.y) / 2;
      } else if (solid.length) {
        // on the wing's tip itself: its outermost points, not the model's middle height and a guess at the length
        // (a plane's winglets floated well clear of its wings, the Jumbo's by most of a tile)
        const tipPart = solid.reduce((a, b) => (b.box.max.x > a.box.max.x ? b : a));
        const pos = tipPart.mesh.geometry.getAttribute('position'), v = new THREE.Vector3();
        let n = 0, sy = 0, sz = 0;
        const edge = tipPart.box.max.x - 0.015;
        for (let i = 0; i < pos.count; i++) {
          v.fromBufferAttribute(pos, i).applyMatrix4(tipPart.mesh.matrixWorld);
          if (v.x >= edge) { n++; sy += v.y; sz += v.z; }
        }
        x = tipPart.box.max.x - s * 0.5;
        if (n) { y = sy / n; z = sz / n - s * 0.2; }
        // aft of the wingtip's navigation light, not over it
        const wb = new THREE.Box3(new THREE.Vector3(x - 0.01, y - 0.02, z - s * 0.4), new THREE.Vector3(x + s, y + 0.02, z + s * 0.4));
        const nav = lamps.filter((l) => l.intersectsBox(wb));
        if (nav.length) z = Math.min(...nav.map((l) => l.min.z)) - s * 0.4 - 0.01;
      }
      for (const sx of [-1, 1]) kit.box(s, 0.02, s * 0.8, looks.paint >= 3 ? looks.accent : looks.colour, sx * (x + s * 0.4), y, z);
    }
  }
  return lift;
}

/**
 * The bull bar (the user, 11 Nov 2026: a plain rectangle, sometimes hanging in the air off the nose). It is set
 * against the front of the car at its own height, not the furthest-forward point of the whole model (a lamp, a
 * bumper's lip, a ladder), and bolted back to it with brackets, so it never floats. Tubes, not slabs:
 *   1 Nudge bar: a small dark A-frame over the grille.
 *   2 Bull bar: a chrome frame, a low rail the car's width, a hoop over the grille, side guards and a pair of lamps.
 *   3 Plough: a steel V-wedge with hazard chevrons, a chrome top rail, on struts.
 */
function bullbar(kit: BoltKit, parts: Part[], tier: number, y: number, wid: number, nose: number, lamps: THREE.Box3[], wheels: THREE.Box3[]): void {
  const w = Math.min(wid * 0.92, 0.9);
  const h = tier === 1 ? 0.12 : tier === 2 ? 0.17 : 0.15;
  // the face behind it: the furthest-forward part across the bar's height and width
  let face = -Infinity;
  for (const p of parts) {
    const b = p.box;
    if (b.max.y < y - 0.03 || b.min.y > y + h || b.max.x < -w / 2 || b.min.x > w / 2) continue;
    face = Math.max(face, b.max.z);
  }
  if (!Number.isFinite(face)) face = nose;
  // out past the front tyres where they stand ahead of the face (a monster truck's), else the blade cut into them
  let ahead = face;
  for (const b of wheels) if (b.max.x > -w / 2 - 0.03 && b.min.x < w / 2 + 0.03 && b.max.z > face && b.min.y < y + h) ahead = Math.max(ahead, b.max.z);
  const R = 0.017, z = Math.max(face + 0.05, ahead + 0.03);
  /** The legs stand inboard of the headlamps behind the bar, not in front of them. */
  const clear = (x: number): number => {
    let best = x;
    for (const l of lamps) if (l.max.z > face - 0.08 && l.min.y < y + h + 0.03 && l.max.y > y - 0.03 && l.min.x > 0 && l.min.x - 0.03 < best && l.max.x + 0.03 > best) best = Math.min(best, l.min.x - 0.03);
    return Math.max(best, 0.04);
  };
  /** A tube between two points (in the car's frame). */
  const tube = (c: number, x0: number, y0: number, z0: number, x1: number, y1: number, z1: number, r = R) => {
    const a = new THREE.Vector3(x0, y0, z0), b = new THREE.Vector3(x1, y1, z1);
    const m = kit.cyl(r, a.distanceTo(b), c, (x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2, 'y');
    m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.sub(a).normalize());
  };
  const knuckle = (c: number, x: number, yy: number, zz: number) => kit.ball(R * 1.15, c, x, yy, zz);
  /** Brackets from the bar back into the face, at x either side. */
  const brackets = (c: number, x: number, yy: number, from: number) => {
    for (const sx of [-1, 1]) kit.box(0.03, 0.03, from - face + 0.03, c, sx * x, yy, (from + face) / 2 - 0.005);
  };
  if (tier === 1) {
    const x = clear(w * 0.3), top = y + h;
    for (const sx of [-1, 1]) {
      tube(DARK, sx * x, y - 0.03, z, sx * x * 0.8, top, z);
      knuckle(DARK, sx * x * 0.8, top, z);
    }
    tube(DARK, -x * 0.8, top, z, x * 0.8, top, z);
    tube(DARK, -x, y + 0.03, z, x, y + 0.03, z, R * 0.8);
    brackets(DARK, x * 0.9, y + 0.02, z);
  } else if (tier === 2) {
    const lo = y, top = y + h, hx = clear(w * 0.32), zf = z + 0.02;
    // the low rail across the whole front, its ends bent back
    tube(CHROME, -w / 2, lo, zf, w / 2, lo, zf);
    for (const sx of [-1, 1]) {
      tube(CHROME, sx * w / 2, lo, zf, sx * w / 2, lo, face + 0.01);
      knuckle(CHROME, sx * w / 2, lo, zf);
      // the hoop's legs, leaning back a touch, and its corners
      tube(CHROME, sx * hx, lo, zf, sx * hx, top, zf - 0.02);
      knuckle(CHROME, sx * hx, top, zf - 0.02);
      // a side guard from the rail's end up to the hoop
      tube(CHROME, sx * w / 2, lo, zf, sx * hx, lo + h * 0.6, zf - 0.01, R * 0.8);
      // a lamp on the hoop
      kit.cyl(0.032, 0.03, DARK, sx * hx * 0.55, top + 0.035, zf - 0.02, 'z');
      kit.cyl(0.026, 0.006, 0xfff2b0, sx * hx * 0.55, top + 0.035, zf - 0.003, 'z', 0.6);
    }
    tube(CHROME, -hx, top, zf - 0.02, hx, top, zf - 0.02);
    // two upright bars in the hoop
    for (const sx of [-1, 1]) tube(CHROME, sx * hx * 0.35, lo, zf, sx * hx * 0.35, top, zf - 0.02, R * 0.7);
    brackets(DARK, hx * 0.7, lo + 0.03, zf);
  } else {
    // two steel plates meeting in a point ahead, swept back
    const half = w / 2 + 0.03, sweep = 0.32, depth = Math.sin(sweep) * half;
    const lo = y - 0.04, mid = lo + h / 2, tip = z + depth;
    for (const sx of [-1, 1]) {
      const len = half / Math.cos(sweep);
      const plate = kit.box(len, h, 0.03, STEEL, sx * half / 2, mid, tip - depth / 2);
      plate.rotation.y = sx * sweep;
      // hazard chevrons along the blade
      for (let k = 0; k < 3; k++) {
        const t = (k + 0.5) / 3;
        const st = kit.box(0.035, h * 0.8, 0.008, k % 2 ? DARK : YELLOW, sx * half * t, mid, tip - depth * t + 0.018);
        st.rotation.set(0, sx * sweep, sx * 0.5);
      }
      // the top rail along the blade's edge
      tube(CHROME, 0, lo + h, tip, sx * half, lo + h, z);
      knuckle(CHROME, sx * half, lo + h, z);
    }
    knuckle(CHROME, 0, lo + h, tip);
    // struts from the blade back to the car
    for (const sx of [-1, 1]) tube(DARK, sx * half * 0.5, mid, tip - depth * 0.5, sx * half * 0.5, mid, face + 0.005, 0.02);
    tube(DARK, 0, mid, tip, 0, mid, face + 0.005, 0.02);
  }
}

/** A nitrous bottle lying along the car: white, a blue band, a valve. */
function bottle(kit: BoltKit, x: number, y: number, z: number): void {
  kit.cyl(0.045, 0.24, WHITE, x, y, z, 'z');
  kit.cyl(0.047, 0.05, BLUE, x, y, z + 0.03, 'z');
  kit.cyl(0.016, 0.04, CHROME, x, y, z + 0.14, 'z');
}

/** The finish on everything painted in the vehicle's colour, and the second colour on its upper parts. */
function paint(parts: Part[], looks: Looks): void {
  if (looks.paint < 2) return;
  const painted = parts.filter((p) => {
    const m = p.mesh.material as THREE.MeshStandardMaterial;
    return !Array.isArray(p.mesh.material) && m.isMeshStandardMaterial && m.color.getHex() === looks.colour && m.emissive.getHex() === 0;
  });
  if (!painted.length) return;
  let lo = Infinity, hi = -Infinity;
  for (const p of painted) { lo = Math.min(lo, p.box.min.y); hi = Math.max(hi, p.box.max.y); }
  const cut = lo + (hi - lo) * 0.62;
  const mats = new Map<number, THREE.MeshStandardMaterial>();
  const finish = (c: number) => {
    let m = mats.get(c);
    // a light metalness: the scene has no reflections to show, so much more only darkens the colour
    if (!m) { m = new THREE.MeshStandardMaterial({ color: c, roughness: 0.32, metalness: 0.22, flatShading: true }); mats.set(c, m); }
    return m;
  };
  for (const p of painted) {
    const upper = looks.paint >= 3 && painted.length > 1 && (p.box.min.y + p.box.max.y) / 2 >= cut;
    p.mesh.material = finish(upper ? looks.accent : looks.colour);
  }
}

/** Bigger, wider tyres on a car, the body lifted over them, and the hubs; returns the lift. */
function tyres(body: THREE.Group, wheels: THREE.Object3D[], looks: Looks): number {
  const s = TYRE_R[looks.tyres], wmul = TYRE_W[looks.tyres];
  const mine = wheels.filter((w) => isUnder(w, body));
  let grow = 0;
  for (const w of mine) grow = Math.max(grow, radiusOf(w) * (s - 1));
  const lift = grow + RIDE[looks.suspension];
  if (s > 1) mudguards(body, mine, s, wmul, lift);
  for (const w of mine) {
    const r = radiusOf(w);
    if (s !== 1 || wmul !== 1) w.scale.set(wmul, s, s);
    // the wheel stays on the ground while the body goes up round it
    if (w.parent && w.parent !== body) w.parent.position.y += r * (s - 1) - lift;
  }
  if (s > 1) spread(body, mine, s);
  hubs(body, wheels, looks);
  return lift;
}

/**
 * Mudguards follow their tyres up and out (the user, 11 Nov 2026: the Clod's fenders sat down inside its monster
 * tyres, narrower than them). A mudguard is a part no wider or longer than about its wheel, centred over the wheel,
 * whose underside is just over the tyre: it is raised as far as the tyre's top rises against the lifted body, and
 * stretched to the tyre's new width and size.
 */
function mudguards(body: THREE.Group, mine: THREE.Object3D[], s: number, wmul: number, lift: number): void {
  body.updateMatrixWorld(true);
  const inv = new THREE.Matrix4().copy(body.matrixWorld).invert();
  const wheels = mine.map((w) => {
    const r = radiusOf(w), g = (w as THREE.Mesh).geometry as THREE.CylinderGeometry | undefined;
    return { p: w.getWorldPosition(new THREE.Vector3()).applyMatrix4(inv), r, half: (g?.parameters?.height ?? 0.2) / 2 };
  });
  const done = new Set<THREE.Object3D>();
  body.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh || done.has(m) || mine.some((w) => w === m || isUnder(m, w))) return;
    m.geometry.computeBoundingBox();
    const b = m.geometry.boundingBox!.clone().applyMatrix4(new THREE.Matrix4().multiplyMatrices(inv, m.matrixWorld));
    const c = b.getCenter(new THREE.Vector3());
    const w = wheels.find((e) => Math.abs(c.x - e.p.x) <= e.half + 0.03 && Math.abs(c.z - e.p.z) <= e.r * 0.5
      && b.min.y >= e.p.y + e.r - 0.04 && b.min.y <= e.p.y + e.r + 0.12
      && b.max.x - b.min.x <= e.half * 2 * 1.6 && b.max.z - b.min.z <= e.r * 2 * 1.5);
    if (!w || m.parent !== body) return;
    done.add(m);
    m.position.y += 2 * w.r * (s - 1) - lift;
    m.scale.x *= Math.max(1, (w.half * 2 * wmul + 0.02) / (b.max.x - b.min.x));
    m.scale.z *= s;
  });
}

/**
 * Bigger tyres pushed apart along each side until none touch (the user, 11 Nov 2026: the Stomper's front and rear
 * tyres ran into each other at the second and third tiers). Each side's wheels are spaced out from their middle,
 * keeping their order; a model whose wheels already clear each other is left as it is.
 */
function spread(body: THREE.Group, mine: THREE.Object3D[], s: number): void {
  body.updateMatrixWorld(true);
  const inv = new THREE.Matrix4().copy(body.matrixWorld).invert();
  const at = (w: THREE.Object3D) => w.getWorldPosition(new THREE.Vector3()).applyMatrix4(inv);
  for (const side of [-1, 1]) {
    const row = mine.map((w) => ({ w, p: at(w), r: radiusOf(w) * s })).filter((e) => Math.sign(e.p.x || 1) === side).sort((a, b) => a.p.z - b.p.z);
    if (row.length < 2) continue;
    let k = 1;
    for (let i = 1; i < row.length; i++) {
      const gap = row[i].p.z - row[i - 1].p.z, need = row[i].r + row[i - 1].r + 0.03;
      if (gap > 1e-3 && gap < need) k = Math.max(k, need / gap);
    }
    if (k <= 1) continue;
    const mid = (row[0].p.z + row[row.length - 1].p.z) / 2;
    for (const e of row) {
      const dz = (e.p.z - mid) * (k - 1);
      // the mount moves when the wheel has one of its own (an axle, a steering group), else the wheel itself
      const o = e.w.parent && e.w.parent !== body && e.w.parent.children.length === 1 ? e.w.parent : e.w;
      o.position.z += dz;
    }
  }
}

function hubs(body: THREE.Group, wheels: THREE.Object3D[], looks: Looks): void {
  const colour = looks.brakes ? HUBS[looks.brakes] : looks.tyres >= 3 ? (looks.paint >= 3 ? looks.accent : looks.colour) : 0;
  if (!colour) return;
  const m = new THREE.MeshStandardMaterial({ color: colour, roughness: 0.4, metalness: 0.35, flatShading: true });
  for (const w of wheels) {
    if (!isUnder(w, body)) continue;
    for (const c of w.children) if ((c as THREE.Mesh).isMesh) (c as THREE.Mesh).material = m;
  }
}

function isUnder(o: THREE.Object3D, anc: THREE.Object3D): boolean {
  for (let p = o.parent; p; p = p.parent) if (p === anc) return true;
  return false;
}

function radiusOf(w: THREE.Object3D): number {
  const g = (w as THREE.Mesh).geometry as THREE.CylinderGeometry | undefined;
  return g?.parameters?.radiusTop ?? 0.2;
}

/** Adds flat-shaded parts to the body, one material a colour. */
class BoltKit {
  private mats = new Map<string, THREE.MeshStandardMaterial>();
  /** The slot the pieces being added are for (scripts/boltScan.ts). */
  tag = 'part';
  constructor(private body: THREE.Group) {}
  private mat(c: number, glow = 0): THREE.MeshStandardMaterial {
    const key = `${c}|${glow}`;
    let m = this.mats.get(key);
    if (!m) {
      m = new THREE.MeshStandardMaterial({ color: c, roughness: c === CHROME ? 0.35 : 0.6, metalness: c === CHROME ? 0.5 : 0.05, emissive: glow ? c : 0, emissiveIntensity: glow, flatShading: true });
      this.mats.set(key, m);
    }
    return m;
  }
  private put(geo: THREE.BufferGeometry, c: number, x: number, y: number, z: number, glow = 0): THREE.Mesh {
    const m = new THREE.Mesh(geo, this.mat(c, glow));
    m.position.set(x, y, z);
    m.castShadow = true;
    // a bolt-on, and its slot, for the placement scan (scripts/boltScan.ts) to tell it from the model
    m.userData.bolt = this.tag;
    this.body.add(m);
    return m;
  }
  box(w: number, h: number, d: number, c: number, x: number, y: number, z: number, glow = 0): THREE.Mesh {
    return this.put(new THREE.BoxGeometry(w, h, d), c, x, y, z, glow);
  }
  cyl(r: number, h: number, c: number, x: number, y: number, z: number, axis: 'x' | 'y' | 'z', glow = 0): THREE.Mesh {
    const g = new THREE.CylinderGeometry(r, r, h, 10);
    if (axis === 'x') g.rotateZ(-Math.PI / 2);
    else if (axis === 'z') g.rotateX(Math.PI / 2);
    return this.put(g, c, x, y, z, glow);
  }
  ball(r: number, c: number, x: number, y: number, z: number, sx = 1, sy = 1, sz = 1): THREE.Mesh {
    const g = new THREE.IcosahedronGeometry(r, 1);
    g.scale(sx, sy, sz);
    return this.put(g, c, x, y, z);
  }
}
