import { defOf, kerbNear, type Fleet, type FleetSave, type SavedUnit } from '../game/fleet';
import { press } from '../game/press/desk';
import { plain } from '../game/press/hooks';
import type { Wallet } from '../game/economy';
import type { Estate, SavedDeed } from '../game/estate';
import type { Driver } from '../game/drivers';
import type { FleetBrand } from '../game/brand';
import type { SaveGame } from '../game/save';
import type { World } from '../world/tiles';
import type { ClientMsg, Pid, ServerMsg, Welcome } from '../../shared/protocol';
import { ID_BLOCK, idRange, inviteFrom, type CrewMember, type CrewMeta, type CrewView, type WireDriver, type WireUnit } from '../../shared/fleets';
import type { CrewPolicy } from '../../shared/social';

/**
 * Shared fleets, the game's side (docs/sharedfleets.html). Alone this does nothing. In a shared fleet it keeps
 * this game's purse, roster and buildings in step with the server's record of the fleet:
 *
 * - the purse: the wallet stays the game's own, and every so often whatever it has gained or lost since last
 *   time goes to the server as a numbered change; the server's total comes back (and with every other member's
 *   change), and the wallet is set to it plus whatever this game has sent that it hasn't counted yet;
 * - the roster: once a second or two this game's own vehicles (the ones it drives), the drivers in them or on
 *   the bench, the buildings and the HQ's terms are compared with what the server last had, and what differs
 *   goes; other members' changes come back and are laid in. A vehicle another member's game drives is kept in
 *   the list as "away" (game/fleet.ts Unit.away) and drawn from their positions, as any other player's are.
 */

const PENDING_KEY = 'tinyfleet-join';

/** The invite this browser is holding to be asked about at the next sign-in (a /join/ link, or a code pasted at pause). */
export function pendingInvite(): string | null {
  try { return inviteFrom(localStorage.getItem(PENDING_KEY) ?? ''); } catch { return null; }
}
export function setPendingInvite(code: string | null): void {
  try { if (code) localStorage.setItem(PENDING_KEY, code); else localStorage.removeItem(PENDING_KEY); } catch { /* not remembered */ }
}

interface CrewHost {
  fleet: Fleet;
  wallet: Wallet;
  estate: Estate;
  /** The cash chip has changed. */
  cash(): void;
  /** The fleet's livery has changed (the founder repainted it). */
  brand(b: FleetBrand | null): void;
  announce(title: string, body: string, ms?: number): void;
  /** A player's name, for "out with …". */
  nameOf(pid: Pid): string;
}

export class CrewSync {
  /** The shared fleet as last told; null for a fleet of one's own. */
  id: string | null = null;
  creator: Pid | null = null;
  members: CrewMember[] = [];
  code: string | null = null;
  /** Phase 3 of the social window (docs/social.html): the fleet's officers, how it is joined, and each member's takings this week. */
  officers: Pid[] = [];
  policy: CrewPolicy = {};
  week: Record<Pid, number> = {};
  /** An invite the sign-in carried, to be asked about (or why it can't be joined). */
  offer: Welcome['offer'] | null = null;
  private me: Pid | null = null;
  private brandNow: FleetBrand | null = null;
  private view: CrewView | null = null;
  /** Has the shared fleet an HQ already (another member's game settled it in a world begun again)? */
  hasHq(): boolean { return !!this.view?.meta?.hq; }
  /** Having just joined: where to start, [cx, cz, x, z]. Taken once by spot(). */
  private spawn: [number, number, number, number] | null = null;
  /** The shared state is laid into the world in play: changes go both ways from here. */
  private live = false;

  // what the server last had of each (as JSON): anything else here is this game's, unsent
  private units = new Map<number, string>();
  private drivers = new Map<number, string>();
  private deeds = new Set<string>();
  private meta = '';
  private syncT = 0;

  // the purse
  private counted = 0;
  private pending = new Map<number, number>();
  private seq = 0;
  private purseT = 0;
  /** Money this game made or spent that never reached the server (a connection lost), carried into the next session. */
  private carry = 0;

  /** Waiting on an invite code from the server. */
  private inviteWait: ((r: { code: string } | { why: string }) => void) | null = null;
  /** What a fleet of one's own looked like when it asked for its first invite: the shared fleet starts from exactly that. */
  private pre: { cash: number; units: Map<number, string>; drivers: Map<number, string>; deeds: Set<string>; meta: string } | null = null;

  constructor(private host: CrewHost, private send: (m: ClientMsg) => boolean) {}

  /** In a shared fleet (of one or more). */
  get on(): boolean { return !!this.id; }
  /** Its founder: the one who may rename it, recolour it and boot players. Anyone alone is their own. */
  get founder(): boolean { return !this.id || this.creator === this.me; }
  /** An officer of my shared fleet (may invite and let players in). */
  get officer(): boolean { return !!this.me && this.officers.includes(this.me); }
  /** May I hand out invites? Alone, always; in a shared fleet, by its policy (officers unless said). */
  get mayInvite(): boolean {
    if (!this.id || this.creator === this.me) return true;
    const who = this.policy.invites ?? 'officers';
    return who === 'anyone' || (who === 'officers' && this.officer);
  }
  /** Another member of my shared fleet. */
  mate(pid: Pid | null | undefined): boolean { return !!pid && pid !== this.me && this.members.some((m) => m.id === pid); }
  /** Me, or one of my fleet-mates: whose doors are this fleet's. */
  ours(pid: Pid | null | undefined): boolean { return !!pid && (pid === this.me || this.mate(pid)); }

  reset(): void {
    // what this game made or spent that never reached the server (its connection was lost): kept for the next welcome
    if (this.live && this.view) { const d = this.host.wallet.cash - this.counted; if (Number.isFinite(d)) this.carry += d; }
    this.id = this.creator = this.code = this.me = null;
    this.members = [];
    this.officers = []; this.policy = {}; this.week = {};
    this.view = null;
    this.spawn = null;
    this.offer = null;
    this.live = false;
    this.units.clear(); this.drivers.clear(); this.deeds.clear(); this.meta = '';
    this.pending.clear();
    this.pre = null;
    this.inviteWait?.({ why: 'Signed out' });
    this.inviteWait = null;
  }

  /** The welcome: the shared fleet, if any, an invite to ask about, and where to start if this player has just joined. */
  welcome(w: Welcome): void {
    this.reset();
    // a different player, or a fleet of their own now: nothing carries
    if (!w.crew) this.carry = 0;
    this.me = w.you.id;
    this.offer = w.offer ?? null;
    this.spawn = w.spawn ?? null;
    const v = w.crew ?? null;
    if (!v) return;
    this.view = v;
    this.id = v.id;
    this.creator = v.creator;
    this.members = v.members;
    this.code = v.code;
    this.officers = v.officers ?? []; this.policy = v.policy ?? {}; this.week = v.week ?? {};
    this.brandNow = v.brand as FleetBrand | null;
  }

  /** The fleet's livery while in a shared one (the welcome's `you` already wears it), else undefined. */
  get brand(): FleetBrand | null | undefined { return this.id ? this.brandNow : undefined; }

  /**
   * A career about to be loaded: in a shared fleet, its money, buildings, livery and HQ are the fleet's, and of its
   * own vehicles only the one being driven is kept (the rest are laid in from the fleet once the world is up).
   * Having just joined, it starts at the spot the server picked.
   */
  patchSave(save: SaveGame | null): void {
    const v = this.view;
    if (save && this.spawn) { save.cell = [this.spawn[0], this.spawn[1]]; save.x = this.spawn[2]; save.z = this.spawn[3]; }
    if (!v || !save) return;
    save.cash = v.cash;
    save.estate = v.estate as Record<string, SavedDeed>;
    if (v.brand) save.brand = v.brand as FleetBrand;
    if (save.fleet) {
      const fl: FleetSave = save.fleet;
      const ride = fl.ride;
      const row = v.units.find((r) => r.u.uid === ride);
      // the vehicle being driven stays, unless the fleet has it as somebody else's now
      fl.units = fl.units.filter((u) => u.uid === ride && (!row || row.by === this.me || !row.by));
      fl.drivers = [];
      fl.hq = (v.meta.hq ?? null) as FleetSave['hq'];
      fl.charter = v.meta.charter ?? fl.charter;
      if (v.meta.hires) fl.hires = v.meta.hires;
      if (typeof v.meta.bought === 'number') fl.bought = v.meta.bought;
    }
  }

  /** Where this player starts, having just joined: a road tile near the spot the server picked, when `w` is its cell. Once. */
  spot(w: World): { x: number; z: number } | null {
    const s = this.spawn;
    if (!s || w.cx !== s[0] || w.cz !== s[1]) return null;
    this.spawn = null;
    return kerbNear(w, s[2], s[3], 24) ?? { x: s[2], z: s[3] };
  }

  /** Has the player just joined (so a new career must not ask for another home)? */
  get joining(): boolean { return !!this.spawn; }

  /** The world is up: the fleet as the server has it is laid in, and from now on changes go both ways. */
  ready(): void {
    const v = this.view;
    if (!v || !this.me) return;
    const f = this.host.fleet, me = this.me;
    const ridden = f.ridden;
    const inView = new Map(v.units.map((r) => [r.u.uid, r]));
    // anything of this career's the fleet doesn't have is gone (sold by a fleet-mate while away), but the ride
    for (const u of [...f.units]) if (u !== ridden && !inView.has(u.uid)) f.drop(u.uid);
    // this game's numbers for new vehicles and drivers, in a range of its own (shared/fleets.ts idRange)
    const [lo, hi] = idRange(me, this.creator === me);
    const inRange = (n: number) => n >= lo && n < hi;
    let nextU = lo, nextD = lo;
    for (const r of v.units) if (inRange(r.u.uid)) nextU = Math.max(nextU, r.u.uid + 1);
    for (const d of v.drivers) if (inRange(d.id)) nextD = Math.max(nextD, d.id + 1);
    if (ridden && inRange(ridden.uid)) nextU = Math.max(nextU, ridden.uid + 1);
    // the vehicle being driven, new to the fleet (a new player's first car, or the one brought in on joining), or
    // clashing with one of the fleet's: numbered from this game's own range
    if (ridden) {
      const row = inView.get(ridden.uid);
      if ((row && row.by !== me) || (!row && this.creator !== me && !inRange(ridden.uid))) f.renumber(ridden, nextU++);
    }
    f.setIds(Math.max(nextU, this.creator === me ? f.ids.unit : 0), Math.max(nextD, this.creator === me ? f.ids.driver : 0));
    for (const r of v.units) {
      if (ridden && r.u.uid === ridden.uid) continue;
      f.adopt(r.u as unknown as SavedUnit, r.by && r.by !== me ? { by: r.by, name: this.host.nameOf(r.by) } : null);
    }
    f.drivers = v.drivers.map((d) => ({ ...d }) as unknown as Driver);
    f.adoptMeta(v.meta);
    f.settle();
    this.host.estate.fromSave(v.estate as Record<string, SavedDeed>);
    // the purse: the server's, plus anything this game had that never reached it
    this.host.wallet.cash = v.cash + this.carry;
    this.counted = v.cash;
    this.carry = 0;
    this.host.cash();
    // what the server has, so only what changes from here goes
    for (const r of v.units) this.units.set(r.u.uid, JSON.stringify(r.u));
    for (const d of v.drivers) this.drivers.set(d.id, JSON.stringify(d));
    for (const k of Object.keys(v.estate)) this.deeds.add(k);
    this.meta = JSON.stringify(this.metaOf(f.toSave()));
    this.live = true;
    this.syncT = 0.5;
  }

  private metaOf(s: FleetSave): CrewMeta { return { hq: s.hq ?? null, charter: s.charter ?? 0, hires: s.hires, bought: s.bought ?? 0 }; }

  // ---- every frame ------------------------------------------------------------------------------------

  frame(dt: number): void {
    if (!this.live) return;
    this.purseT -= dt;
    if (this.purseT <= 0) { this.purseT = 0.25; this.flushPurse(); }
    this.syncT -= dt;
    if (this.syncT <= 0) { this.syncT = 1.5; this.syncRoster(); }
  }

  /** Whatever the wallet has gained or lost since last time, to the server (kept for later if the line is down). */
  private flushPurse(): void {
    const d = Math.round((this.host.wallet.cash - this.counted) * 100) / 100;
    if (!d) return;
    const s = ++this.seq;
    if (!this.send({ t: 'purse', d, s })) return;
    this.pending.set(s, d);
    this.counted += d;
  }

  /** Everything unsent goes now (signing out). */
  flush(): void { if (this.live) { this.flushPurse(); this.syncRoster(); } }

  /** Signed out: money a lost session never sent stays with that session. */
  dropCarry(): void { this.carry = 0; }

  /** This game's changes to the roster since the server last had it. */
  private syncRoster(): void {
    const f = this.host.fleet;
    const save = f.toSave();
    const m: Extract<ClientMsg, { t: 'roster' }> = { t: 'roster' };
    const here = new Set<number>();
    for (const su of save.units) {
      here.add(su.uid);
      const u = f.unit(su.uid);
      if (!u || u.away) continue;
      const json = JSON.stringify(su);
      if (this.units.get(su.uid) === json) continue;
      this.units.set(su.uid, json);
      (m.units ??= []).push(su as unknown as WireUnit);
    }
    for (const uid of [...this.units.keys()]) if (!here.has(uid)) { this.units.delete(uid); (m.gone ??= []).push(uid); }
    const crew = new Set<number>();
    for (const d of save.drivers) {
      crew.add(d.id);
      if (f.unit(d.unit)?.away) continue;
      const json = JSON.stringify(d);
      if (this.drivers.get(d.id) === json) continue;
      this.drivers.set(d.id, json);
      (m.drivers ??= []).push(d as unknown as WireDriver);
    }
    for (const id of [...this.drivers.keys()]) if (!crew.has(id)) { this.drivers.delete(id); (m.fired ??= []).push(id); }
    const keys = this.host.estate.deeds;
    const added = [...keys.keys()].filter((k) => !this.deeds.has(k));
    if (added.length) {
      const all = this.host.estate.toSave();
      for (const k of added) { this.deeds.add(k); (m.estate ??= {})[k] = all[k]; }
    }
    for (const k of [...this.deeds]) if (!keys.has(k)) { this.deeds.delete(k); (m.sold ??= []).push(k); }
    const meta = JSON.stringify(this.metaOf(save));
    if (meta !== this.meta) { this.meta = meta; m.meta = JSON.parse(meta) as CrewMeta; }
    if (Object.keys(m).length > 1) this.send(m);
  }

  // ---- what the server says ---------------------------------------------------------------------------

  /** A message that is a shared fleet's: handled, and true. */
  got(m: ServerMsg): boolean {
    switch (m.t) {
      case 'invite': {
        if (m.code) this.code = m.code;
        const w = this.inviteWait;
        this.inviteWait = null;
        w?.(m.code ? { code: m.code } : { why: m.why ?? 'No invite just now.' });
        return true;
      }
      case 'crew': {
        const was = this.id;
        // a new partner in the fleet: news (docs/newspaper.html)
        if (was && was === m.id) for (const mb of m.members) if (mb.id !== this.me && !this.members.some((x) => x.id === mb.id)) press.write({ k: 'crewJoin', who: 'you', f: { member: mb.name || this.host.nameOf(mb.id) } });
        this.id = m.id;
        this.creator = m.creator;
        this.members = m.members;
        this.officers = m.officers ?? []; this.policy = m.policy ?? {}; this.week = m.week ?? {};
        if (JSON.stringify(m.brand) !== JSON.stringify(this.brandNow)) { this.brandNow = m.brand as FleetBrand | null; if (was) this.host.brand(this.brandNow); }
        // a fleet of one's own has just become a shared one: it starts from exactly what the server was sent
        if (!was && this.pre) {
          const p = this.pre;
          this.pre = null;
          this.units = p.units; this.drivers = p.drivers; this.deeds = p.deeds; this.meta = p.meta;
          this.counted = p.cash;
          this.view = { id: m.id, creator: m.creator, brand: m.brand, members: m.members, cash: p.cash, units: [], drivers: [], estate: {}, meta: {}, code: this.code ?? '' };
          this.live = true;
        }
        return true;
      }
      case 'purse': {
        if (!this.live) return true;
        this.flushPurse();
        if (m.s !== undefined) for (const s of [...this.pending.keys()]) if (s <= m.s) this.pending.delete(s);
        const owed = [...this.pending.values()].reduce((a, b) => a + b, 0);
        this.host.wallet.cash = Math.round((m.cash + owed) * 100) / 100;
        this.counted = this.host.wallet.cash;
        this.host.cash();
        return true;
      }
      case 'roster': {
        if (this.live) this.lay(m);
        return true;
      }
      default: return false;
    }
  }

  /** Other members' changes (or, `back`, the server's own word on mine), laid into this game. */
  private lay(m: Extract<ServerMsg, { t: 'roster' }>): void {
    const f = this.host.fleet, me = this.me;
    for (const row of m.units ?? []) {
      const uid = row.u.uid;
      const local = f.unit(uid);
      // the one being driven here is this game's, whatever is said
      if (local && local.uid === f.rideUid && local.where === 'ridden') continue;
      // handed to this game: still its own copy if it has one running
      if (row.by === me && local && !local.away && !m.back) continue;
      // a vehicle new to the fleet, bought by a partner: the paper names them
      if (!local && row.by && row.by !== me && !m.back) {
        const model = (row.u as unknown as { model?: string }).model;
        if (model) press.write({ k: 'vehicleBought', v: 'member', who: 'you', f: { model: defOf(model).name, member: this.host.nameOf(row.by) } });
      }
      f.adopt(row.u as unknown as SavedUnit, row.by && row.by !== me ? { by: row.by, name: this.host.nameOf(row.by) } : null);
      this.units.set(uid, JSON.stringify(row.u));
      if (row.by === me && local?.away) this.host.announce(local.name, 'is yours to run now: its last driver signed out', 4000);
    }
    for (const uid of m.gone ?? []) { f.drop(uid); this.units.delete(uid); }
    for (const d of m.drivers ?? []) {
      const have = f.driver(d.id);
      if (have) Object.assign(have, d); else f.drivers.push({ ...d } as unknown as Driver);
      this.drivers.set(d.id, JSON.stringify(d));
    }
    for (const id of m.fired ?? []) { f.drivers = f.drivers.filter((x) => x.id !== id); this.drivers.delete(id); }
    for (const [k, v] of Object.entries(m.estate ?? {})) {
      const fresh = !this.deeds.has(k) && !this.host.estate.deeds.has(k) && !m.back;
      this.host.estate.adopt(k, v as SavedDeed);
      this.deeds.add(k);
      // a door new to the fleet, bought by a partner's game
      const d = fresh ? this.host.estate.deeds.get(k) : undefined;
      if (d) press.write({ k: 'deedBought', who: 'you', town: d.townKey || undefined, f: { building: plain(d.name), town: d.town, price: d.paid } });
    }
    for (const k of m.sold ?? []) { this.host.estate.forget(k); this.deeds.delete(k); }
    if (m.meta) { f.adoptMeta(m.meta); this.meta = JSON.stringify(this.metaOf(f.toSave())); }
    f.onChange();
  }

  // ---- the pause card's asks --------------------------------------------------------------------------

  /** The invite code: the fleet's, or (alone) a shared fleet of one made from this career as just sent. */
  async invite(saveNow: () => boolean | Promise<boolean>): Promise<{ code: string } | { why: string }> {
    if (this.code && this.id) return { code: this.code };
    if (!this.id) {
      // the server makes the shared fleet from the career it was just sent: remember exactly what that was
      if (!(await saveNow())) return { why: 'Not connected just now.' };
      const f = this.host.fleet, s = f.toSave();
      const units = new Map<number, string>(), drivers = new Map<number, string>();
      for (const u of s.units) units.set(u.uid, JSON.stringify(u));
      for (const d of s.drivers) drivers.set(d.id, JSON.stringify(d));
      this.pre = { cash: this.host.wallet.cash, units, drivers, deeds: new Set(this.host.estate.deeds.keys()), meta: JSON.stringify(this.metaOf(s)) };
    }
    return new Promise((done) => {
      this.inviteWait?.({ why: 'Asked again' });
      this.inviteWait = done;
      this.send({ t: 'invite' });
      setTimeout(() => { if (this.inviteWait === done) { this.inviteWait = null; done({ why: 'The server didn’t answer.' }); } }, 8000);
    });
  }

  boot(id: Pid): void { if (this.id && this.founder && id !== this.me) this.send({ t: 'boot', id }); }
  leave(): void { if (this.id && !this.founder) this.send({ t: 'leaveCrew' }); }
}

/** For the console: how ids are blocked out between members. */
const CREW_ID_BLOCK = ID_BLOCK;
