/**
 * Named jobs, counters and experiment arms for the play reports (net/perfField.ts, the /dev Performance tab),
 * 11 Nov 2026, from that day's performance audit: the frame's laps say which part of the frame ran long, never
 * which occasional job inside it did (a reach flood, a route search, a save, a picture drawn), and work in a
 * timer or an idle callback is in no lap at all. A job is timed where it runs, `job('reach flood', () => …)`,
 * and each report carries name → runs, total ms, longest; a freeze names the jobs that ran inside it.
 *
 * Counters are the same for things that are counted, not timed (pedestrian sets made, world changes), so growth
 * in the 15-second windows can be put down to something. Arms say which variant of an experiment this machine
 * runs, so a change can be measured on players' machines against the same day's other half.
 *
 * Nothing here allocates per call once a name has been seen: it runs inside the frames it measures.
 */

interface Job { n: number; ms: number; max: number }
const JOBS = new Map<string, Job>();
const COUNTS = new Map<string, number>();
/** The latest jobs of a millisecond or more, for the freeze they may have been: a ring, oldest overwritten. */
const RING = 32;
const ringName: string[] = new Array(RING).fill('');
const ringAt = new Float64Array(RING), ringMs = new Float32Array(RING);
let ringI = 0;
let on = true;

/** A job's time, measured by the caller (where a closure would be in the way). `at`: when it began. */
export function jobNote(name: string, ms: number, at = performance.now() - ms): void {
  if (!on) return;
  let j = JOBS.get(name);
  if (!j) { j = { n: 0, ms: 0, max: 0 }; JOBS.set(name, j); }
  j.n++; j.ms += ms;
  if (ms > j.max) j.max = ms;
  if (ms < 1) return;
  ringName[ringI] = name; ringAt[ringI] = at; ringMs[ringI] = ms;
  ringI = (ringI + 1) % RING;
}

/** Run a job, timed. What it throws is the caller's, and still timed. */
export function job<T>(name: string, fn: () => T): T {
  if (!on) return fn();
  const t0 = performance.now();
  try { return fn(); } finally { jobNote(name, performance.now() - t0, t0); }
}

/** A job that ends later (a promise): its wall time, which is the wait and not the main thread's. */
export async function jobAsync<T>(name: string, fn: () => Promise<T>): Promise<T> {
  if (!on) return fn();
  const t0 = performance.now();
  try { return await fn(); } finally { jobNote(name, performance.now() - t0, t0); }
}

export function bump(name: string, by = 1): void { if (on) COUNTS.set(name, (COUNTS.get(name) ?? 0) + by); }
export function countOf(name: string): number { return COUNTS.get(name) ?? 0; }
/** A job's runs and total ms so far (a window takes the difference). */
export function jobStat(name: string): [number, number] { const j = JOBS.get(name); return j ? [j.n, j.ms] : [0, 0]; }

/** The jobs that ran between two moments (performance.now()), longest first: what a freeze had inside it. */
export function jobsBetween(from: number, to: number, top = 3): [string, number][] {
  const sum = new Map<string, number>();
  for (let i = 0; i < RING; i++) {
    if (!ringName[i] || ringAt[i] + ringMs[i] < from || ringAt[i] > to) continue;
    sum.set(ringName[i], (sum.get(ringName[i]) ?? 0) + ringMs[i]);
  }
  return [...sum].sort((a, b) => b[1] - a[1]).slice(0, top).map(([k, v]) => [k, Math.round(v)]);
}

/** Every job this page load: [name, runs, total ms, longest ms], the most time first. */
export function jobsReport(top = 40): [string, number, number, number][] {
  return [...JOBS].map(([k, j]) => [k, j.n, Math.round(j.ms), Math.round(j.max)] as [string, number, number, number]).sort((a, b) => b[2] - a[2]).slice(0, top);
}
export function countsReport(top = 24): [string, number][] { return [...COUNTS].sort((a, b) => b[1] - a[1]).slice(0, top); }
/** pr.jobs(false) turns the timing off, to measure its own cost. */
export function jobsOn(v?: boolean): boolean { if (v !== undefined) on = v; return on; }

// ---- this machine, and the experiments it is in ----

const MACHINE_KEY = 'tinyfleet-machine', ARMS_KEY = 'tinyfleet-arms';
let machine: string | null = null;
/**
 * A random name for this browser on this machine, made once and kept here: nothing of the player's, and not
 * sent anywhere but the play reports. It lets the Performance tab follow one machine across versions and
 * accounts (the audit could only guess which visits were the developer's own laptop).
 */
export function machineId(): string {
  if (machine) return machine;
  try { machine = localStorage.getItem(MACHINE_KEY); } catch { /* blocked */ }
  if (!machine || !/^[a-z0-9]{10}$/.test(machine)) {
    machine = Array.from({ length: 10 }, () => 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random() * 36)]).join('');
    try { localStorage.setItem(MACHINE_KEY, machine); } catch { /* kept for this page load only */ }
  }
  return machine;
}

const ARMS = new Map<string, string>();
function hash(s: string): number { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
/**
 * Which variant of an experiment this machine runs: the same one every visit (from its machine id), an even
 * split between the variants given, the first being the control. `localStorage['tinyfleet-arms']`
 * ({"name":"variant"}) or pr.arm(name, variant) overrides it. Asked once where the experiment's code branches:
 *   if (arm('dock-rate', ['every-frame', '10hz']) === '10hz') …
 * and every report then says which arm the visit was in.
 */
export function arm<V extends string>(name: string, variants: readonly V[]): V {
  const had = ARMS.get(name) as V | undefined;
  if (had && variants.includes(had)) return had;
  let pick: V | undefined;
  try { const o = JSON.parse(localStorage.getItem(ARMS_KEY) ?? '{}') as Record<string, unknown>; if (variants.includes(o[name] as V)) pick = o[name] as V; } catch { /* none set */ }
  pick ??= variants[hash(`${name}|${machineId()}`) % variants.length];
  ARMS.set(name, pick);
  return pick;
}
/** Put this machine in an arm from now on (the next page load, for code that asked already). */
export function setArm(name: string, variant: string | null): void {
  try {
    const o = JSON.parse(localStorage.getItem(ARMS_KEY) ?? '{}') as Record<string, unknown>;
    if (variant === null) delete o[name]; else o[name] = variant;
    localStorage.setItem(ARMS_KEY, JSON.stringify(o));
  } catch { /* blocked */ }
  if (variant === null) ARMS.delete(name); else ARMS.set(name, variant);
}
export function armsReport(): Record<string, string> { return Object.fromEntries(ARMS); }
