import type { CargoItem } from './cargo';
import type { Unit } from './fleet';
import type { AirDef } from './vehicles';
import { N } from '../world/tiles';
import { fitsRunway, lockOf, pointOf, frameOf, type Runway } from '../world/runways';
import { airborne, cruiseV, depart, onGround, standing, stepJet, type JetEnv, type JetFlight, type JetGoal, type JetPhase } from './jetFlight';
import { rand } from '../util/math';

/**
 * Hired pilots for jets (docs/rides.html, 0.7.0 behind NEXT_WORLD): a crewed Swift, Jumbo or Stinger flies the
 * air service between the airports in memory that fit it, and an international's jet out to its overseas point
 * and home with the return load. Each sortie is a scripted flight (game/jetFlight.ts) on the airports' runway
 * lock; the jet's loads are the airports' own jet work (game/cargo.ts jetWork), paid at the far stand like any
 * driver's delivery. A sortie under way is flown to the end wherever the camera goes: only setting out needs
 * its airport in memory, the way a driver needs its island.
 */

export interface JetHost {
  env: JetEnv;
  /** The runways in memory. */
  runways(): Runway[];
  /** Work for a jet at this runway, collected into its hold now: all bound for one place it can reach. */
  work(u: Unit, def: AirDef, r: Runway, goals: Runway[]): CargoItem[];
  /**
   * The same work held for it on the apron for `secs` (game/cargo.ts jetReserve), and taken aboard later (jetLoad):
   * what it will load at the end of its turnaround waits beside it meanwhile, to be seen.
   */
  reserve?(u: Unit, def: AirDef, r: Runway, goals: Runway[], secs: number): CargoItem[];
  load?(u: Unit, items: CargoItem[]): CargoItem[];
  /** At the overseas point: the return loads for these, bound back for where they came from. */
  back(u: Unit, def: AirDef, done: CargoItem[]): CargoItem[];
  /** A load delivered, at a world point. */
  paid(u: Unit, it: CargoItem, at: { x: number; y: number; z: number }): void;
  /** A load given up: back on the market where it stands. */
  drop(u: Unit, it: CargoItem, at: { x: number; y: number; z: number }): void;
  /** Its sortie is over for now (its airport went out of memory between flights): the fleet puts it out of sight. */
  rest(u: Unit): void;
  /** Draw it, and stop drawing it. */
  show?(f: JetFlight, u: Unit): void;
  hide?(f: JetFlight): void;
}

/** `away`: on a stand whose airport has gone out of memory, waiting AWAY_WAIT before it flies home empty (ferry). */
/** `cruise`: how long this leg's cruise may run before the stuck watch steps in (aim): a long haul's is longer. */
/** `seek`: flying empty to another airport for the work held for it there (`next`), after IDLE_MOVE with none at its own. */
interface Sortie { u: Unit; def: AirDef; f: JetFlight; aboard: CargoItem[]; home: Runway; idle: number; next?: CargoItem[]; away?: boolean; cruise?: number; seek?: Runway }

/** How long a phase may run before the flight is set right (it never should be: the gate counts these). */
const STUCK: Partial<Record<JetPhase, number>> = { taxiOut: 150, taxiIn: 150, hold: 240, roll: 60, climb: 120, cruise: 400, inbound: 200, around: 150, final: 90, rollout: 60 };
/** Seconds on the stand at each end: unloading, loading, the checks. */
const TURNAROUND: [number, number] = [12, 20];
/** How long a jet's next loads are held for it on the apron (its turnaround, and a good margin). */
const RESERVED = 90;
/** Seconds between looks for work when there is none. */
const RETRY = 20;
/** The farthest a jet's work goes, in tiles: airports further than this are other flights' business. */
const RANGE = 900;
/**
 * Seconds a jet waits on a stand whose airport has gone out of memory, in case the player comes back that way, before
 * it flies home empty to an airport in memory (ferry). Nothing runs there meanwhile but its stand's timer.
 */
const AWAY_WAIT = 60;
/**
 * Seconds a jet waits on the stand with no work for it before it looks for an airport in reach that has some, and
 * flies there empty (the user, 6 Nov 2026: Swifts waited for good at airports with nothing for them).
 */
const IDLE_MOVE = 120;
/** A long haul's loads are handed over within this many tiles of the far airport they are bound for (overseas). */
const FAR_HANDOVER = 60;

export class JetPilots {
  private sorties = new Map<number, Sortie>();
  /** For the gate and the console: legs flown, loads delivered, go-arounds, flights set right. */
  stats = { legs: 0, delivered: 0, overseas: 0, far: 0, arounds: 0, rescued: 0, ferried: 0, sought: 0, rescues: [] as string[] };

  constructor(private host: JetHost) {}

  flying(u: Unit): boolean { return this.sorties.has(u.uid); }
  flight(u: Unit): JetFlight | null { return this.sorties.get(u.uid)?.f ?? null; }
  flights(): { u: Unit; f: JetFlight; aboard: CargoItem[] }[] { return [...this.sorties.values()]; }

  /**
   * Put a crewed jet on the air service from where it stands: at (or taxiing to) a stand of a runway in memory
   * that it fits, or in the air on its way to the nearest. Returns why it can't, or null.
   */
  fly(u: Unit, def: AirDef): string | null {
    if (this.sorties.has(u.uid)) return null;
    const gx = u.cx * N + u.x, gz = u.cz * N + u.z, env = this.host.env;
    const fits = this.host.runways().filter((r) => fitsRunway(def.jet!.runway, r));
    if (!fits.length) return `no airfield in reach is long enough for the ${def.name}`;
    let best: { r: Runway; k: number } | null = null, bd = Infinity;
    for (const r of fits) r.stands.forEach((s, k) => { const d = Math.hypot(s.x - gx, s.z - gz); if (d < bd) { bd = d; best = { r, k }; } });
    const at = best as { r: Runway; k: number } | null;
    if (!at) return `no airfield in reach is long enough for the ${def.name}`;
    const up = u.y - env.ground(gx, gz) > 2;
    const f = standing(-u.uid, def, at.r, at.k, { kind: 'runway', r: at.r });
    if (up) {
      // a save loaded mid-flight: on from here to the nearest airport it fits
      Object.assign(f.st, { x: gx, z: gz, y: u.y, heading: u.heading, gear: 0 });
      airborne(f, env);
    } else if (bd > 1.5) {
      const fr = frameOf(at.r, gx, gz);
      if (bd > 40 || Math.abs(fr.across) > at.r.half + 16) return `${u.name} is parked away from an airfield it fits: fly it to one`;
      // somewhere on the apron: taxi to the stand
      Object.assign(f.st, { x: gx, z: gz, heading: u.heading });
      const s = at.r.stands[at.k], fs = frameOf(at.r, s.x, s.z);
      f.path = [pointOf(at.r, Math.max(0, Math.min(at.r.len, fr.along)), at.r.taxiOff), pointOf(at.r, fs.along, at.r.taxiOff), { x: s.x, z: s.z }];
      f.phase = 'taxiIn';
    } else f.wait = rand(4, 8);
    this.sorties.set(u.uid, { u, def, f, aboard: [], home: at.r, idle: 0 });
    this.host.show?.(f, u);
    return null;
  }

  /**
   * Off the air service (the driver out, the player taking it, the garage): its loads handed back, and its pose
   * kept for the player taking the wheel; otherwise one in the air puts down at the stand it was bound for.
   */
  ground(u: Unit, land = true): CargoItem[] {
    const s = this.sorties.get(u.uid);
    if (!s) return [];
    const f = s.f;
    if (land && !onGround(f)) {
      const r = f.goal.kind === 'runway' ? f.goal.r : s.home, st = r.stands[0];
      Object.assign(f.st, { x: st.x, z: st.z, y: r.y, heading: st.heading, v: 0, pitch: 0, roll: 0, gear: 1 });
    }
    this.sync(s);
    if (s.f.rw) this.host.env.release(s.f.rw, s.f.id);
    this.host.hide?.(s.f);
    this.sorties.delete(u.uid);
    return s.aboard;
  }

  update(dt: number): void {
    if (dt <= 0) return;
    for (const s of [...this.sorties.values()]) {
      const f = s.f;
      const ev = stepJet(f, dt, this.host.env);
      this.sync(s);
      if (ev === 'landed') this.landed(s);
      else if (ev === 'overseas') this.overseas(s);
      else if (ev === 'around') this.stats.arounds++;
      else if (ev === 'airborne') this.stats.legs++;
      if (f.phase === 'stand' && f.wait <= 0) this.next(s);
      const limit = f.phase === 'cruise' ? s.cruise ?? STUCK.cruise : STUCK[f.phase];
      if (limit && f.t > limit) this.rescue(s);
    }
  }

  /** The unit stands where its jet is. */
  private sync(s: Sortie): void {
    const st = s.f.st, u = s.u;
    u.cx = Math.floor(st.x / N); u.cz = Math.floor(st.z / N);
    u.x = st.x - u.cx * N; u.z = st.z - u.cz * N; u.y = st.y; u.heading = st.heading;
  }

  /** Parked at a stand: whatever was bound for this airport is delivered. */
  private landed(s: Sortie): void {
    // (a two-runway airport is known by its first runway, whichever it landed on)
    const r = lockOf(s.f.rw!), st = s.f.st;
    s.home = r;
    const here = s.aboard.filter((it) => it.to.kind !== 'overseas' && Math.hypot(it.to.x - r.stands[0].x, it.to.z - r.stands[0].z) < 3);
    for (const it of here) {
      this.host.paid(s.u, it, { x: st.x, y: st.y, z: st.z });
      this.stats.delivered++;
    }
    s.aboard = s.aboard.filter((it) => !here.includes(it));
    s.f.wait = rand(TURNAROUND[0], TURNAROUND[1]);
    // flown over for work held for it here (seekWork): that is what goes aboard at the end of the turnaround
    const sought = s.seek === r && !!s.next?.length;
    s.seek = undefined;
    // emptied: its next loads come out onto the apron now and wait beside it through the turnaround
    if (!sought && !s.aboard.length && this.host.reserve && this.host.runways().includes(r)) s.next = this.host.reserve(s.u, s.def, r, this.goalsFrom(s, r), RESERVED);
  }

  /** The airports a jet at this runway may fly to: in memory, long enough for it, and within RANGE. */
  private goalsFrom(s: Sortie, r: Runway): Runway[] {
    return this.host.runways().filter((q) => q !== r && fitsRunway(s.def.jet!.runway, q) && Math.hypot(q.ax - r.ax, q.az - r.az) <= RANGE);
  }

  /**
   * Over the overseas point, or over a long haul's far airport (out of memory, five counties or more off): those
   * loads are handed over, the return loads come aboard for the overseas ones, and it flies home.
   */
  private overseas(s: Sortie): void {
    const st = s.f.st;
    const done = s.aboard.filter((it) => it.to.kind === 'overseas' || (!!it.longHaul && Math.hypot(it.to.x - st.x, it.to.z - st.z) < FAR_HANDOVER));
    for (const it of done) {
      this.host.paid(s.u, it, { x: st.x, y: st.y, z: st.z });
      this.stats.delivered++;
      if (it.longHaul) this.stats.far++;
    }
    if (done.some((it) => it.to.kind === 'overseas')) this.stats.overseas++;
    s.aboard = [...s.aboard.filter((it) => !done.includes(it)), ...this.host.back(s.u, s.def, done.filter((it) => it.to.kind === 'overseas'))];
    s.f.goal = this.goalOf(s) ?? { kind: 'runway', r: s.home };
    this.aim(s);
  }

  /** The stuck watch's limit for this leg's cruise: the way there at cruise, half again, and a minute. */
  private aim(s: Sortie): void {
    const g = s.f.goal, st = s.f.st;
    const gx = g.kind === 'overseas' ? g.x : g.r.stands[0].x, gz = g.kind === 'overseas' ? g.z : g.r.stands[0].z;
    s.cruise = Math.max(STUCK.cruise!, Math.hypot(gx - st.x, gz - st.z) / Math.max(0.5, cruiseV(s.def)) * 1.5 + 60);
  }

  /** Where the loads aboard go: the overseas point, or the runway in memory at their airport. */
  private goalOf(s: Sortie): JetGoal | null {
    const it = s.aboard[0];
    if (!it) return null;
    if (it.to.kind === 'overseas') return { kind: 'overseas', x: it.to.x, z: it.to.z, name: it.to.name };
    const r = this.host.runways().find((q) => Math.hypot(q.stands[0].x - it.to.x, q.stands[0].z - it.to.z) < 3)
      ?? (Math.hypot(s.home.stands[0].x - it.to.x, s.home.stands[0].z - it.to.z) < 3 ? s.home : null);
    if (r) return { kind: 'runway', r };
    // a long haul's far airport, never in memory: flown to and handed over there in the air, like an overseas point
    if (it.longHaul) return { kind: 'overseas', x: it.to.x, z: it.to.z, name: it.to.name.split(' · ')[0] };
    return null;
  }

  /** On the stand with the turnaround done: off with the next loads, or a look for work. */
  private next(s: Sortie): void {
    const f = s.f, r = lockOf(f.rw!);
    // its airport has gone out of memory since it landed: no work comes up where nothing runs. It waits a minute on
    // the stand in case the player comes back this way, then flies home empty (the user, 4 Nov 2026: jets stood for
    // good, out of view, at the far end of a long flight); with nowhere in memory to go, it rests there as before
    if (!this.host.runways().includes(r)) {
      if (!s.away) { s.away = true; f.wait = AWAY_WAIT; return; }
      if (this.ferry(s)) return;
      this.ground(s.u); this.host.rest(s.u); return;
    }
    s.away = false;
    if (!s.aboard.length) {
      // what waited for it on the apron goes aboard; failing that (taken, lapsed, none), whatever there is now
      if (s.next?.length && this.host.load) s.aboard = this.host.load(s.u, s.next);
      s.next = undefined;
      if (!s.aboard.length) s.aboard = this.host.work(s.u, s.def, r, this.goalsFrom(s, r));
    }
    let goal = this.goalOf(s);
    // a load for somewhere no longer in memory: put down here for whoever flies there next
    while (s.aboard.length && !goal) {
      this.host.drop(s.u, s.aboard.shift()!, { x: f.st.x, y: f.st.y, z: f.st.z });
      goal = this.goalOf(s);
    }
    if (!goal) {
      s.idle += RETRY;
      if (s.idle >= IDLE_MOVE && this.seekWork(s, r)) return;
      f.wait = RETRY; return;
    }
    s.idle = 0; s.seek = undefined;
    f.goal = goal;
    // a load for the very airport it stands at (a diverted flight's) is delivered without flying
    if (goal.kind === 'runway' && goal.r === r) { this.landed(s); return; }
    this.aim(s);
    depart(f, this.host.env);
  }

  /**
   * Nothing for it here after IDLE_MOVE: the nearest other airport in memory, in reach and long enough for it, with
   * work for it there now (its crew order's, as at its own) gets that work held for it while it flies over empty;
   * it loads on landing, as after any turnaround. False with no such airport: it keeps waiting here and looks again.
   */
  private seekWork(s: Sortie, r: Runway): boolean {
    if (!this.host.reserve) return false;
    const f = s.f, st = f.st;
    const near = this.goalsFrom(s, r).sort((a, b) => Math.hypot(a.ax - r.ax, a.az - r.az) - Math.hypot(b.ax - r.ax, b.az - r.az));
    for (const q of near) {
      // held through the flight there (at cruise, half again) and its turnaround
      const secs = Math.hypot(q.stands[0].x - st.x, q.stands[0].z - st.z) / Math.max(0.5, cruiseV(s.def)) * 1.5 + 60 + RESERVED;
      const items = this.host.reserve(s.u, s.def, q, this.goalsFrom(s, q), secs);
      if (!items.length) continue;
      s.next = items; s.seek = q; s.idle = 0;
      f.goal = { kind: 'runway', r: q };
      this.aim(s);
      depart(f, this.host.env);
      this.stats.sought++;
      return true;
    }
    return false;
  }

  /**
   * Home empty from out of memory: up from where it stands and on, in the air, to the airport in memory its loads
   * are bound for, or else the nearest in memory it fits (loads for anywhere else are given up here). It starts at
   * cruise height over the stand, the way a save loaded mid-flight does (jetFlight airborne): out of memory nobody
   * sees the climb, and the runway there, with nothing running round it, is never used. False with nowhere to go.
   */
  private ferry(s: Sortie): boolean {
    const f = s.f, st = f.st, fits = this.host.runways().filter((q) => fitsRunway(s.def.jet!.runway, q));
    if (!fits.length) return false;
    const bound = (it: CargoItem) => { const g = this.goalOf({ ...s, aboard: [it] }); return g?.kind === 'runway' && fits.includes(g.r) ? g.r : null; };
    for (const it of s.aboard.filter((q) => !bound(q))) this.host.drop(s.u, it, { x: st.x, y: st.y, z: st.z });
    s.aboard = s.aboard.filter((q) => bound(q));
    let to = s.aboard.length ? bound(s.aboard[0]) : null;
    if (!to) {
      let bd = Infinity;
      for (const q of fits) { const d = Math.hypot(q.stands[0].x - st.x, q.stands[0].z - st.z); if (d < bd) { bd = d; to = q; } }
    }
    if (!to) return false;
    if (f.rw) this.host.env.release(f.rw, f.id);
    s.next = undefined; s.away = false; s.idle = 0; s.seek = undefined;
    f.goal = { kind: 'runway', r: to };
    f.path = []; f.stand = -1;
    st.heading = Math.atan2(to.stands[0].x - st.x, to.stands[0].z - st.z);
    airborne(f, this.host.env);
    st.y = Math.max(st.y, f.alt);
    this.aim(s);
    this.stats.ferried++;
    return true;
  }

  /**
   * A crewed jet resting out of memory (a save from before ferry, or one that had nowhere to go): flown home empty
   * now that somewhere is in memory (Fleet.launchAll asks, after a wait). False when there is still nowhere.
   */
  fetch(u: Unit, def: AirDef): boolean {
    if (this.sorties.has(u.uid)) return true;
    const fits = this.host.runways().filter((q) => fitsRunway(def.jet!.runway, q));
    if (!fits.length) return false;
    const f = standing(-u.uid, def, fits[0], 0, { kind: 'runway', r: fits[0] });
    Object.assign(f.st, { x: u.cx * N + u.x, z: u.cz * N + u.z, y: u.y, heading: u.heading });
    f.rw = null;
    const s: Sortie = { u, def, f, aboard: [], home: fits[0], idle: 0 };
    if (!this.ferry(s)) return false;
    this.sorties.set(u.uid, s);
    this.host.show?.(f, u);
    return true;
  }

  /** A flight that has run far too long in one phase: put where it was going (counted, and the gate fails on any). */
  private rescue(s: Sortie): void {
    const f = s.f, why = `${s.u.name} ${f.phase} ${Math.round(f.t)} s`;
    this.stats.rescued++;
    if (this.stats.rescues.length < 20) this.stats.rescues.push(why);
    if (f.rw) this.host.env.release(f.rw, f.id);
    const g = f.goal;
    if (!onGround(f) && g.kind === 'overseas') { f.st.x = g.x; f.st.z = g.z; f.t = 0; return; }
    const r = g.kind === 'runway' && !onGround(f) ? g.r : f.rw ?? s.home;
    const k = 0, st = r.stands[k];
    Object.assign(f.st, { x: st.x, z: st.z, y: r.y, heading: st.heading, v: 0, pitch: 0, roll: 0, gear: 1 });
    f.rw = r; f.stand = k; f.phase = 'stand'; f.t = 0; f.path = [];
    this.landed(s);
  }

  /**
   * A jet's run, for the dock's bubble and its card (main.ts): what is aboard, the place it is all going (the far
   * airport or the overseas point; null on the stand waiting for work) and about how many seconds off it is.
   * Its loads are collected at the stand it stands on, so there is never a pickup to fly to.
   */
  run(u: Unit): { aboard: CargoItem[]; to: string | null; secs: number } | null {
    const s = this.sorties.get(u.uid);
    if (!s) return null;
    const f = s.f;
    const g = f.goal;
    if (!s.aboard.length && !(s.seek && g.kind === 'runway')) return { aboard: [], to: null, secs: 0 };
    const gx = g.kind === 'overseas' ? g.x : g.r.stands[0].x, gz = g.kind === 'overseas' ? g.z : g.r.stands[0].z;
    // the line there at cruise, and a minute for the taxi, the roll and the approach
    const secs = Math.hypot(gx - f.st.x, gz - f.st.z) / Math.max(0.5, cruiseV(s.def)) + 60;
    return { aboard: s.aboard, to: g.kind === 'overseas' ? g.name : g.r.name, secs };
  }

  /** The unit flying this flight, if it is a hired jet's (the sky draws it as one of its own, game/skyTraffic.ts adopt). */
  unitOf(f: JetFlight): Unit | null {
    for (const s of this.sorties.values()) if (s.f === f) return s.u;
    return null;
  }

  /** A line for the garage: what the pilot is doing. */
  describe(u: Unit): string | null {
    const s = this.sorties.get(u.uid);
    if (!s) return null;
    const f = s.f, to = f.goal.kind === 'overseas' ? f.goal.name : f.goal.r.name;
    const n = s.aboard.length, held = n ? `${n} aboard` : 'empty';
    switch (f.phase) {
      case 'stand': {
        const at = `on the stand at ${f.rw?.name ?? 'the airport'}`;
        // its next loads out on the apron beside it (cargo.ts jetReserve), going aboard at the end of the turnaround
        const next = !n && s.next?.length ? s.next[0].to.name.split(' · ')[0] : null;
        if (s.away) return `${at} · out of reach · flying home soon`;
        return next ? `${at} · loading ${s.next!.length} for ${next}` : s.idle > 0 ? `${at} · waiting for jet work` : `${at} · ${held}`;
      }
      case 'taxiOut': case 'hold': return s.seek ? `taxiing out · empty · to ${to} for work` : `taxiing out · ${held} · for ${to}`;
      case 'roll': case 'climb': return `taking off · ${held} · for ${to}`;
      case 'cruise': return s.seek ? `flying empty to ${to} · work waits there` : `flying · ${held} · to ${to}`;
      case 'inbound': case 'final': return `on approach to ${to}`;
      case 'around': return `going around at ${to}`;
      default: return `landed at ${f.rw?.name ?? to} · taxiing in`;
    }
  }

  clear(): void {
    for (const s of [...this.sorties.values()]) this.ground(s.u);
    this.stats = { legs: 0, delivered: 0, overseas: 0, far: 0, arounds: 0, rescued: 0, ferried: 0, sought: 0, rescues: [] };
  }
}
