import type { Soundtrack } from './music';
import { SUBREDDIT } from './photoMode';
import { QUALITY_LABEL, type Quality, type QualitySetting } from '../render/quality';
import { FPS_CHOICES, frameCap } from './frameCap';
import { fpsLog } from './fpsLog';
import type { Sfx } from './sfx';
import { setUnitSystem, unitSystem } from './units';
import { setTheme, theme } from './theme';
import { el } from '../util/dom';

/**
 * The O menu, also opened from the gear in the corner: graphics, effects, fleet, paths, units and looks,
 * with a way to the music player (game/musicMenu.ts), which has a window of its own.
 */
export class SettingsMenu {
  isOpen = false;
  private el = document.getElementById('settings')!;
  private musicNote = el('p', 'q-note');
  private qualityButtons: HTMLButtonElement[] = [];
  private qualityNote = el('p', 'q-note');
  private fxMute = el('button', 'ctl');
  private fxVolume = el('input', 'vol');
  private fxLabel = el('span', 'vol-n');
  private shakeButtons: HTMLButtonElement[] = [];
  /** Effects volume to go back to when unmuting. */
  private fxWas = 0.6;
  /** The frame rate of each of the last few minutes (game/fpsLog.ts), a small bar chart under Frame rate. */
  private fpsChart = el('div', 'fps-chart');
  private fpsTimer = 0;
  private pathButtons: HTMLButtonElement[] = [];
  private unitButtons: HTMLButtonElement[] = [];
  private themeButtons: HTMLButtonElement[] = [];
  /** Auto-Pathing: arrows to the next drop. Read and written by main, which owns the trail. */
  autoPath: { get: () => boolean; set: (on: boolean) => void } = { get: () => false, set: () => {} };
  /** Open the music player's own window (main owns it). */
  openMusic: () => void = () => {};
  /** Move the player to the nearest clear whole tile; returns why it couldn't, or null. */
  unstick: () => string | null = () => null;

  constructor(private music: Soundtrack, private quality?: Quality, private sfx?: Sfx) {

    const panel = el('div', 'panel');
    panel.innerHTML = '<header><h2>Settings<span>.</span></h2><div class="keys"><kbd>O</kbd> close</div></header>';

    // the music has a window of its own (game/musicMenu.ts): a way there, and what is on
    const section = el('h3', '', 'Music');
    const musicRow = el('div', 'quality');
    const musicBtn = el('button', 'q', '♫ Open the music player');
    musicBtn.type = 'button';
    musicBtn.tabIndex = -1;
    musicBtn.addEventListener('click', () => { this.close(); this.openMusic(); });
    musicRow.append(musicBtn);

    // the game's subreddit, at the very bottom: clips, help and news from other players
    const community = el('p', 'credit');
    community.append('Share clips and meet other fleets on ');
    const sub = el('a', '', 'r/TinyFleet');
    sub.href = SUBREDDIT;
    sub.target = '_blank';
    sub.rel = 'noopener';
    sub.tabIndex = -1;
    community.append(sub, ', the official subreddit.');

    panel.append(section, musicRow, this.musicNote, community);
    if (quality) {
      // graphics: Auto walks the levels to keep the frame rate up; the rest hold one level
      const heading = el('h3', '', 'Graphics');
      const row = el('div', 'quality');
      for (const s of ['auto', 'high', 'medium', 'low', 'lowest'] as QualitySetting[]) {
        const b = el('button', 'q', QUALITY_LABEL[s]);
        b.type = 'button';
        b.tabIndex = -1;
        b.dataset.q = s;
        b.addEventListener('click', () => { quality.set(s); this.syncQuality(); });
        this.qualityButtons.push(b);
        row.append(b);
      }
      panel.insertBefore(heading, section);
      panel.insertBefore(row, section);
      panel.insertBefore(this.qualityNote, section);
      quality.onChange = () => { if (this.isOpen) this.syncQuality(); };
      // the frame-rate cap (game/frameCap.ts): 60 keeps frames from piling up behind the graphics card
      const fpsRow = el('div', 'quality');
      const fpsButtons: HTMLButtonElement[] = [];
      const syncFps = () => { for (const b of fpsButtons) b.classList.toggle('on', Number(b.dataset.fps) === frameCap.value); };
      for (const v of FPS_CHOICES) {
        const b = el('button', 'q', v ? `${v} fps` : 'Unlimited');
        b.type = 'button';
        b.tabIndex = -1;
        b.dataset.fps = String(v);
        b.addEventListener('click', () => { frameCap.set(v); syncFps(); });
        fpsButtons.push(b);
        fpsRow.append(b);
      }
      syncFps();
      const fpsNote = el('p', 'q-note', 'Frame rate limit. 60 is smoothest for most screens; Unlimited can stutter now and then as frames pile up behind the graphics card.');
      for (const n of [el('h3', '', 'Frame rate'), fpsRow, fpsNote, this.fpsChart]) panel.insertBefore(n, section);
    }
    if (sfx) {
      // effects: the knocks, thumps, cracks and scrapes, and how much a knock shakes the camera
      const heading = el('h3', '', 'Effects');
      const vol = el('div', 'volume');
      this.fxVolume.type = 'range';
      this.fxVolume.min = '0';
      this.fxVolume.max = '100';
      this.fxVolume.tabIndex = -1;
      this.fxVolume.addEventListener('input', () => sfx.setVolume(Number(this.fxVolume.value) / 100));
      this.fxMute.type = 'button';
      this.fxMute.tabIndex = -1;
      this.fxMute.addEventListener('click', () => {
        if (sfx.volume > 0) { this.fxWas = sfx.volume; sfx.setVolume(0); } else sfx.setVolume(this.fxWas || 0.6);
      });
      vol.append(this.fxMute, this.fxVolume, this.fxLabel);
      const row = el('div', 'quality');
      for (const [label, v] of [['Full shake', 1], ['Gentle', 0.5], ['No shake', 0]] as const) {
        const b = el('button', 'q', label);
        b.type = 'button';
        b.tabIndex = -1;
        b.dataset.shake = String(v);
        b.addEventListener('click', () => sfx.setShake(v));
        this.shakeButtons.push(b);
        row.append(b);
      }
      const note = el('p', 'q-note', 'How much the camera jolts when you hit something.');
      for (const n of [heading, vol, row, note]) panel.insertBefore(n, section);
      sfx.onChange(() => { if (this.isOpen) this.syncEffects(); });
    }
    // (the Fleet choice, bring empty vehicles along or leave them behind, went on 4 Nov 2026: the user wants them
    // always left behind, game/convoy.ts carry)
    {
      // Auto-Pathing: yellow arrows to the first drop of the load aboard
      const heading = el('h3', '', 'Auto-Pathing');
      const row = el('div', 'quality');
      for (const [label, on] of [['On', true], ['Off', false]] as const) {
        const b = el('button', 'q', label);
        b.type = 'button';
        b.tabIndex = -1;
        b.dataset.path = String(on);
        b.addEventListener('click', () => { this.autoPath.set(on); this.syncPath(); });
        this.pathButtons.push(b);
        row.append(b);
      }
      const note = el('p', 'q-note', 'Yellow arrows on the ground to your next delivery, the #1 drop of what you are carrying, by the way that suits what you are driving: roads for a road car, rough ground for an off-roader, open water for a boat, a straight line for anything that flies.');
      for (const n of [heading, row, note]) panel.insertBefore(n, section);
    }
    {
      // metric or imperial: how the speedo, heights and mission targets are written
      const heading = el('h3', '', 'Units');
      const row = el('div', 'quality');
      for (const [label, u] of [['Metric · km/h, m', 'metric'], ['Imperial · mph, ft', 'imperial']] as const) {
        const b = el('button', 'q', label);
        b.type = 'button';
        b.tabIndex = -1;
        b.dataset.units = u;
        b.addEventListener('click', () => { setUnitSystem(u); this.syncUnits(); });
        this.unitButtons.push(b);
        row.append(b);
      }
      const note = el('p', 'q-note', 'Starts out matching your device’s region.');
      for (const n of [heading, row, note]) panel.insertBefore(n, section);
    }
    {
      // light or dark panels, cards and chips (game/theme.ts)
      const heading = el('h3', '', 'Appearance');
      const row = el('div', 'quality');
      for (const [label, t] of [['Light', 'light'], ['Dark', 'dark']] as const) {
        const b = el('button', 'q', label);
        b.type = 'button';
        b.tabIndex = -1;
        b.dataset.theme = t;
        b.addEventListener('click', () => { setTheme(t); this.syncTheme(); });
        this.themeButtons.push(b);
        row.append(b);
      }
      const note = el('p', 'q-note', 'Dark turns every panel, card and chip dark. The world itself is untouched.');
      for (const n of [heading, row, note]) panel.insertBefore(n, section);
    }
    {
      // wedged against a wall, in a building's lot or a ditch: put the vehicle on the nearest clear tile
      const heading = el('h3', '', 'Stuck?');
      const row = el('div', 'quality');
      const b = el('button', 'q', 'Unstick');
      b.type = 'button';
      b.tabIndex = -1;
      const note = el('p', 'q-note', 'Moves your vehicle to the nearest whole tile that is clear: dry, flat, drivable on every side, with no building or wall on it.');
      b.addEventListener('click', () => {
        const why = this.unstick();
        if (why) note.textContent = why;
        else this.close();
      });
      row.append(b);
      for (const n of [heading, row, note]) panel.insertBefore(n, section);
    }
    this.el.append(panel);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });

    window.addEventListener('keydown', (e) => {
      if (this.isOpen && e.code === 'Escape') { this.close(); e.preventDefault(); }
    });
    document.getElementById('gear')?.addEventListener('click', (e) => {
      this.toggle();
      (e.currentTarget as HTMLElement).blur();
    });
    music.onChange(() => { if (this.isOpen) this.syncMusic(); });
  }

  toggle(): void {
    if (this.isOpen) this.close();
    else this.open();
  }

  open(): void {
    this.isOpen = true;
    this.el.hidden = false;
    this.sync();
    this.drawFps();
    clearInterval(this.fpsTimer);
    this.fpsTimer = window.setInterval(() => this.drawFps(), 5000);
  }

  /**
   * The chart: a bar for each of the last few minutes, the average frame rate written over it, the minute under way on
   * the right and paler (it is still filling). Scaled to 60, or higher when a minute ran faster.
   */
  private drawFps(): void {
    const h = fpsLog.history();
    if (!h.length) { this.fpsChart.innerHTML = '<p class="q-note">Your frame rate over the last few minutes shows here once you have been driving a while.</p>'; return; }
    const top = Math.max(60, ...h.map((m) => m.fps));
    const W = 34, GAP = 8, H = 46;
    const bars = h.map((m, k) => {
      const v = Math.round(m.fps), bh = Math.max(2, (m.fps / top) * H), x = k * (W + GAP);
      const label = m.live ? 'now' : `${m.ago}m ago`;
      return `<g class="${m.live ? 'live' : ''}"><rect x="${x}" y="${14 + H - bh}" width="${W}" height="${bh}" rx="3"/>`
        + `<text class="v" x="${x + W / 2}" y="${10 + H - bh}">${v}</text><text class="t" x="${x + W / 2}" y="${H + 27}">${label}</text></g>`;
    }).join('');
    const width = h.length * (W + GAP) - GAP;
    this.fpsChart.innerHTML = `<svg viewBox="0 0 ${width} ${H + 30}" width="${width}" height="${H + 30}" role="img" aria-label="Average frame rate per minute: ${h.map((m) => Math.round(m.fps)).join(', ')} fps">${bars}</svg>`
      + '<p class="q-note">Average frames a second, a minute a bar.</p>';
  }

  close(): void {
    this.isOpen = false;
    this.el.hidden = true;
    clearInterval(this.fpsTimer);
    (document.activeElement as HTMLElement | null)?.blur?.();
  }

  private syncMusic(): void {
    const m = this.music;
    this.musicNote.textContent = `${m.playing ? 'Now playing' : 'Paused on'} ${m.track.title} by ${m.track.artist}. The player also opens from the little bars in the top corner, beside the gear.`;
  }

  private syncQuality(): void {
    const q = this.quality;
    if (!q) return;
    for (const b of this.qualityButtons) b.classList.toggle('on', b.dataset.q === q.setting);
    this.qualityNote.textContent = q.setting === 'auto'
      ? `Running at ${QUALITY_LABEL[q.level]}. Auto keeps the best picture that still runs at 30 frames a second: it lowers the resolution, then the shadows, only when the game drops below that, and tries higher again when there is room.`
      : 'Lower settings render fewer pixels: Medium turns off anti-aliasing, Low renders at three-quarter resolution, Lowest also turns off shadows.';
  }


  private syncTheme(): void {
    const t = theme();
    for (const b of this.themeButtons) b.classList.toggle('on', b.dataset.theme === t);
  }

  private syncUnits(): void {
    const u = unitSystem();
    for (const b of this.unitButtons) b.classList.toggle('on', b.dataset.units === u);
  }

  private syncPath(): void {
    const on = this.autoPath.get();
    for (const b of this.pathButtons) b.classList.toggle('on', (b.dataset.path === 'true') === on);
  }

  private syncEffects(): void {

    const fx = this.sfx;
    if (!fx) return;
    const v = Math.round(fx.volume * 100);
    if (document.activeElement !== this.fxVolume) this.fxVolume.value = String(v);
    this.fxLabel.textContent = v ? `${v}%` : 'off';
    this.fxMute.textContent = v === 0 ? '🔇' : v < 40 ? '🔈' : '🔊';
    this.fxMute.title = v === 0 ? 'Turn effects on' : 'Turn effects off';
    for (const b of this.shakeButtons) b.classList.toggle('on', Number(b.dataset.shake) === fx.shake);
  }

  private sync(): void {
    this.syncQuality();
    this.syncEffects();
    this.syncPath();
    this.syncUnits();
    this.syncTheme();
    this.syncMusic();
  }
}
