import { hex, scale, type RGB } from '../../../world/biomes';
import type { BuildingKind } from '../../../world/tiles';
import { mulberry32, type Rng } from '../../../world/rng';
import { FLOOR } from '../../../world/towns';
import { Vis } from '../../nightLights';
import {
  BRICK, BRIGHT, CARS, DARK, GLASS, GLASS_LIGHT, LEAF, METAL, ROOFS, ROOF_GREY, SHOP_GLOW, STONE, WALLS, WARM_GLOW, WHITE,
  WOOD, car, cur, curArch, gableFace, pick, roofOver, row, styleRoof, styleTrim, styleWall, styledGable, tiledHip,
  win, windowSched, ONION_SKINS, onionDome, type Draw, type Kit, type P3,
} from '../kit';
import { nameModels } from '../kit';
import { clock, flag } from '../civic';

/**
 * Alternative models for the town's everyday institutions and shops: the filling station, the post
 * office, the pub, the church, the bakery, the diner, the school, the general store, the café, the
 * village hall and the grocery. Each is the same job on the same lot as the kind's own model, with a
 * plan or a roofline of its own, and keeps its walls inside the kind's solid shape (world/footprint.ts).
 */

const GOLD = hex(0xd9a441), CROSS = hex(0xf2c14e);

/** A front door in the style's colours. */
const doorOf = (r: Rng): RGB => (cur.doors ? pick(r, cur.doors) : hex(0x5a3a28));

/**
 * A cheap small roof over a block w×d standing to y, in the style's form, for the kinds whose own model
 * is not styled and so has no roof budget to spend: a flat slab, a hip, flared eaves, a false front, or a
 * gable (the ridge along z when `alongZ`). `pitch` sets the height of an unstyled gable. With `rich`, a
 * Dutch gable gets its stepped, neck or bell front to the street. Returns the top.
 */
function lid(k: Kit, r: Rng, x: number, y: number, z: number, w: number, d: number, wall: RGB, roof: RGB, alongZ: boolean, pitch = 0.3, rich = false): number {
  const e = Math.min(cur.eaves, 0.05), span = alongZ ? w : d;
  switch (cur.form) {
    case 'flat':
      k.box(x, y, z, w + 0.02, 0.05, d + 0.02, wall, scale(roof, 0.96));
      return y + 0.05;
    case 'hip': {
      const h = Math.min(0.5, Math.min(w, d) * cur.pitch * 0.9);
      k.hip(x, y, z, w + 2 * e, h, d + 2 * e, roof);
      return y + h;
    }
    case 'curved': {
      const h = Math.min(0.5, Math.min(w, d) * cur.pitch * 1.1);
      flaredLite(k, x, y, z, w + 2 * e, h, d + 2 * e, roof, wall, alongZ);
      return y + h;
    }
    case 'false': {
      const fz = z + d / 2;
      k.box(x, y, z, w + 0.02, 0.04, d + 0.02, wall, roof);
      k.box(x, y, fz - 0.02, w + 0.02, 0.2, 0.04, wall);
      k.box(x, y + 0.2, fz - 0.02, w + 0.06, 0.025, 0.07, scale(wall, 0.68));
      return y + 0.225;
    }
    case 'dutch': {
      // always end-on to the street, as a canal house's is
      const h = Math.min(0.6, w * 0.75);
      k.gable(x, y, z, w, h, d, roof, wall, true);
      if (rich) gableFace(k, x, y, z + d / 2 + 0.012, w + 0.02, h * 1.12, wall, styleTrim(), (['step', 'neck', 'bell'] as const)[Math.floor(r() * 3)], true, 1);
      else k.box(x, y + h - 0.02, z + d / 2 - 0.02, 0.05, 0.08, 0.05, styleTrim());
      return y + h * (rich ? 1.12 : 1);
    }
    default: {
      const h = cur.form ? Math.min(0.5, span * cur.pitch * (cur.form === 'low' ? 0.55 : 0.8)) : Math.min(0.5, span * pitch);
      k.gable(x, y, z, w + 2 * e, h, d + 2 * e, roof, wall, alongZ);
      return y + h;
    }
  }
}

/**
 * The Kit's flared roof (lower slopes flattening, eave corners turned up) with a plain box for its ridge
 * beam in place of the three bars and their curled ends: the same outline for a third fewer triangles,
 * on the small buildings that have none to spare.
 */
function flaredLite(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, roof: RGB, end: RGB, alongZ = false): void {
  const L = (alongZ ? d : w) / 2, H = (alongZ ? w : d) / 2;
  const P = (u: number, v: number, yy: number): P3 => (alongZ ? [x + v, yy, z + u] : [x + u, yy, z + v]);
  const I = P(0, 0, y + h * 0.2);
  const knee = y + h * 0.3, lift = h * 0.22, a = Math.min(L * 0.3, 0.14);
  for (const sv of [-1, 1]) {
    const e = sv * H, kv = sv * H * 0.5;
    const us = [-L, -L + a, L - a, L], ys = [y + lift, y, y, y + lift];
    for (let i = 0; i < 3; i++) k.quad(P(us[i], e, ys[i]), P(us[i + 1], e, ys[i + 1]), P(us[i + 1], kv, knee), P(us[i], kv, knee), roof, I);
    k.quad(P(-L, kv, knee), P(L, kv, knee), P(L, 0, y + h), P(-L, 0, y + h), roof, I);
  }
  for (const su of [-1, 1]) {
    const u = su * L, c = P(u, 0, y + lift);
    k.tri(c, P(u, -H, y + lift), P(u, -H * 0.5, knee), end, I);
    k.tri(c, P(u, -H * 0.5, knee), P(u, 0, y + h), end, I);
    k.tri(c, P(u, 0, y + h), P(u, H * 0.5, knee), end, I);
    k.tri(c, P(u, H * 0.5, knee), P(u, H, y + lift), end, I);
  }
  const [bx, , bz] = P(0, 0, 0);
  k.box(bx, y + h - 0.012, bz, alongZ ? 0.035 : 2 * L, 0.035, alongZ ? 2 * L : 0.035, scale(roof, 0.7));
}

/** A thin slab laid over four corners (any slope), rimmed along its a-b and c-d edges: an awning, a lean-to, a canopy wing. */
function slab(k: Kit, a: P3, b: P3, c: P3, d: P3, t: number, col: RGB): void {
  const up = (p: P3): P3 => [p[0], p[1] + t, p[2]];
  const ring = [a, b, c, d];
  const I: P3 = [(a[0] + b[0] + c[0] + d[0]) / 4, (a[1] + b[1] + c[1] + d[1]) / 4 + t / 2, (a[2] + b[2] + c[2] + d[2]) / 4];
  k.quad(up(a), up(b), up(c), up(d), col, I);
  k.quad(a, b, c, d, col, I);
  for (let i = 0; i < 4; i += 2) {
    const p = ring[i], q = ring[(i + 1) % 4];
    k.quad(p, q, up(q), up(p), col, I);
  }
}

/** A mansard: four steep slopes from the w×d eaves at y up to a flat top `inset` in from them. */
function mansard(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, inset: number, col: RGB, top: RGB): void {
  const I: P3 = [x, y + h / 2, z], yt = y + h;
  const lo: [number, number][] = [[x - w / 2, z - d / 2], [x + w / 2, z - d / 2], [x + w / 2, z + d / 2], [x - w / 2, z + d / 2]];
  const iw = w / 2 - inset, id = d / 2 - inset;
  const hi: [number, number][] = [[x - iw, z - id], [x + iw, z - id], [x + iw, z + id], [x - iw, z + id]];
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4;
    k.quad([lo[i][0], y, lo[i][1]], [lo[j][0], y, lo[j][1]], [hi[j][0], yt, hi[j][1]], [hi[i][0], yt, hi[i][1]], col, I);
  }
  k.quad([hi[0][0], yt, hi[0][1]], [hi[1][0], yt, hi[1][1]], [hi[2][0], yt, hi[2][1]], [hi[3][0], yt, hi[3][1]], top, I);
}

/** A barrel roof along x over a block `d` deep: `seg` strips of a half-round rising `rise`, and its two end caps. */
function barrel(k: Kit, x: number, y: number, z: number, len: number, d: number, rise: number, col: RGB, end: RGB, seg = 3): void {
  const I: P3 = [x, y + rise / 3, z];
  const at = (i: number): [number, number] => {
    const a = (i / seg) * Math.PI;
    return [z + Math.cos(a) * d / 2, y + Math.sin(a) * rise];
  };
  for (let i = 0; i < seg; i++) {
    const [z0, y0] = at(i), [z1, y1] = at(i + 1);
    k.quad([x - len / 2, y0, z0], [x + len / 2, y0, z0], [x + len / 2, y1, z1], [x - len / 2, y1, z1], col, I);
    for (const sx of [-1, 1]) k.tri([x + sx * len / 2, y, z], [x + sx * len / 2, y0, z0], [x + sx * len / 2, y1, z1], end, I);
  }
}

/** A bell hanging in an opening: a dark arch with a gold bell in it, on the wall facing +z at z. */
function bellIn(k: Kit, x: number, y: number, z: number, w: number, h: number): void {
  k.box(x, y, z + 0.004, w, h, 0.012, hex(0x2a2a30));
  k.cone(x, y + h * 0.2, z + 0.012, w * 0.3, h * 0.55, hex(0xc9a24a), 6);
}

/** A gold cross standing at (x, y, z). */
function cross(k: Kit, x: number, y: number, z: number, col = CROSS): void {
  k.box(x, y, z, 0.02, 0.16, 0.02, col);
  k.box(x, y + 0.1, z, 0.09, 0.02, 0.02, col);
}

// ---- gas ---------------------------------------------------------------------------------------

/**
 * A filling station of the old roadside sort: a little pitched-roof office with a one-bay workshop beside
 * it across the back, both pumps on a single island under a butterfly canopy held up on two slim posts
 * down its valley, and a tall lit totem by the road in place of the pole sign.
 */
const roadsideGas: Draw = (k, _W, _D, b, r) => {
  const brand = pick(r, BRIGHT), wall = cur.form ? styleWall(r) : pick(r, WALLS), roof = cur.form ? styleRoof(r) : hex(0x5a5f6b);
  // the office and the workshop fill the shop's box at the back (x ±0.6, z -0.92..-0.32)
  const bz = -0.62, fz = bz + 0.3;
  k.box(-0.2, 0, bz, 0.8, 0.36, 0.6, wall);
  lid(k, r, -0.2, 0.36, bz, 0.8, 0.6, wall, roof, false, 0.34);
  win(k, b, r, -0.38, 0.08, fz, 0.38, 0.18, 1, GLASS_LIGHT);
  k.box(-0.03, 0, fz + 0.006, 0.12, 0.26, 0.012, doorOf(r));
  k.box(0.4, 0, bz, 0.4, 0.3, 0.6, scale(wall, 0.9), ROOF_GREY);
  k.box(0.4, 0.22, fz + 0.006, 0.4, 0.08, 0.012, brand);
  // the butterfly canopy: two wings rising from a valley on the posts; its underside is above a car's roof
  const cx = 0.1, z0 = 0.0, z1 = 0.62, lowY = 0.5, highY = 0.6;
  slab(k, [-0.6, highY, z0], [cx, lowY, z0], [cx, lowY, z1], [-0.6, highY, z1], 0.03, WHITE);
  slab(k, [cx, lowY, z0], [0.8, highY, z0], [0.8, highY, z1], [cx, lowY, z1], 0.03, brand);
  for (const pz of [0.08, 0.54]) k.box(cx, 0, pz, 0.05, lowY, 0.05, WHITE);
  k.glowBox(cx, lowY - 0.03, 0.31, 0.08, 0.02, 0.5, WHITE, [16.8, 30, 1.2], SHOP_GLOW);
  // the island and its two round-shouldered pumps, globes lit
  k.box(cx, 0, 0.31, 1.0, 0.03, 0.14, hex(0xd8d4cc));
  for (const px of [-0.25, 0.45]) {
    k.box(px, 0.03, 0.31, 0.1, 0.13, 0.08, brand);
    k.glowBox(px, 0.16, 0.31, 0.07, 0.05, 0.07, WHITE, [16.8, 30, 1.2], SHOP_GLOW);
  }
  // the totem by the road
  k.box(-0.85, 0, 0.8, 0.05, 0.5, 0.05, METAL);
  k.glowBox(-0.85, 0.5, 0.8, 0.16, 0.4, 0.05, brand, [16.5, 30, 1.6], brand);
  if (r() < 0.7) car(k, 0.3, 0.64, true, pick(r, CARS));
};

// ---- post office -------------------------------------------------------------------------------

/**
 * A post office in pale stone under a pitched roof, its livery on a painted shopfront and a lamp over the
 * door, the clock up in a pediment over the entrance (a raised parapet under a flat roof), and a stamp
 * machine on a post at the kerb in place of the pillar box.
 */
const pedimentPost: Draw = (k, W, D, b, r) => {
  const livery = b.seed % 2 ? hex(0xd23a2e) : hex(0x2f5d9a);
  const wall = W > 1.5 ? styleWall(r) : pick(r, STONE), roof = cur.form ? styleRoof(r) : hex(0x5a5f6b);
  const bw = W - 0.2, bd = D - 0.45, bz = -0.12, h = 0.44, fz = bz + bd / 2;
  k.box(0, 0, bz, bw, h, bd, wall);
  const along = bd > bw, eave = Math.min(cur.eaves, 0.05);
  const top = lid(k, r, 0, h, bz, bw, bd, wall, roof, along, 0.32);
  if (cur.form === 'false') clock(k, 0, h + 0.1, fz, 0.06);
  else if (cur.form === 'flat' || cur.form === 'dutch') {
    // a raised parapet over the door carrying the clock
    const py = cur.form === 'dutch' ? h + 0.02 : top - 0.02;
    k.box(0, py, fz - 0.02, 0.44, 0.18, 0.06, wall);
    k.box(0, py + 0.18, fz - 0.02, 0.48, 0.025, 0.08, livery);
    clock(k, 0, py + 0.09, fz + 0.01, 0.06);
  } else if (!along) {
    // a pediment gable over the entrance, end to the street, standing just proud of the eaves
    const pw = Math.min(0.5, bw * 0.45), ph = Math.min(0.3, (top - h) + 0.04), pz = fz + eave + 0.01;
    k.gable(0, h, pz - 0.15, pw, ph, 0.3, roof, wall, true);
    clock(k, 0, h + ph * 0.38, pz, 0.055);
  } else clock(k, 0, h + 0.1, fz + eave + 0.002, 0.06);
  // the painted shopfront, its windows either side of the door, and the lamp over it
  k.box(0, 0.3, fz + 0.006, bw * 0.92, 0.07, 0.012, livery);
  const side = bw * 0.36, n = Math.max(1, Math.round(side / 0.3));
  for (const sx of [-1, 1]) row(k, b, r, sx * (bw * 0.26), 0.07, fz, side, 0.19, n, 1, GLASS_LIGHT);
  k.box(0, 0, fz + 0.006, 0.12, 0.25, 0.012, doorOf(r));
  k.glowBox(0, 0.26, fz + 0.03, 0.08, 0.04, 0.04, livery, [17, 23, 1.6], WARM_GLOW);
  // the stamp machine at the kerb
  k.box(bw / 2 - 0.1, 0, fz + 0.2, 0.03, 0.12, 0.03, DARK);
  k.box(bw / 2 - 0.1, 0.12, fz + 0.2, 0.08, 0.09, 0.05, hex(0xd23a2e));
  flag(k, -bw / 2 + 0.06, h, bz - bd / 2 + 0.06, 0.5, livery);
  // a van at the side door, if there is room for one
  if (W > 1.5) {
    k.box(-bw / 3, 0.02, bz - bd / 2 - 0.12, 0.34, 0.16, 0.18, livery);
    k.box(-bw / 3 + 0.14, 0.02, bz - bd / 2 - 0.12, 0.08, 0.12, 0.18, GLASS_LIGHT);
  }
};

// ---- pub ---------------------------------------------------------------------------------------

/**
 * An old coaching inn: a stone or darker ground floor with the upper storey jettied out over it, twin
 * gables to the street, lanterns either side of the door, a chimney stack, and the sign hung from its own
 * post at the kerb over a bench table.
 */
export const jettiedInn: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), paint = pick(r, [0x2f4d3a, 0x6b2a2a, 0x2a3a5a, 0x3a3f45]);
  const h = b.floors * FLOOR + 0.04, g = FLOOR;
  const low = cur.plinth ? pick(r, cur.plinth) : scale(wall, 0.9);
  k.box(0, 0, -0.12, 0.8, g, 0.66, low);
  k.box(0, g, -0.1, 0.86, h - g, 0.74, wall);
  if (cur.form === 'flat') lid(k, r, 0, h, -0.1, 0.86, 0.74, wall, roof, false);
  else for (const sx of [-1, 1]) lid(k, r, sx * 0.215, h, -0.1, 0.43, 0.74, wall, roof, true, 0.5 + cur.pitch * 0.4, true);
  const chimney = cur.chimney ? hex(cur.chimney[1]) : pick(r, BRICK);
  k.box(-0.3, h, -0.36, 0.1, 0.34, 0.1, chimney);
  // the ground floor: painted boards, a window either side of the door, a lantern each side of it
  const fz = 0.21;
  k.box(0, 0.02, fz + 0.006, 0.8, 0.22, 0.012, paint);
  for (const sx of [-1, 1]) {
    k.pane(sx * 0.24, 0.06, fz + 0.012, 0.2, 0.13, 1, GLASS_LIGHT, [15.5, 23.5, 1.8], WARM_GLOW);
    k.glowBox(sx * 0.1, 0.19, fz + 0.03, 0.03, 0.05, 0.03, hex(0x3a3a30), [16, 23.5, 1.8], WARM_GLOW);
  }
  k.box(0, 0, fz + 0.014, 0.12, 0.2, 0.012, DARK);
  // the jettied floor's windows
  row(k, { ...b, kind: 'townhouse' }, r, 0, g + 0.07, 0.27, 0.66, 0.12, 3, 1);
  // the sign on its post, and a bench table on the pavement
  k.box(0.42, 0, 0.42, 0.03, 0.5, 0.03, DARK);
  k.box(0.35, 0.48, 0.42, 0.16, 0.02, 0.02, DARK);
  k.box(0.33, 0.3, 0.42, 0.13, 0.16, 0.012, pick(r, BRIGHT));
  k.box(-0.22, 0.08, 0.4, 0.26, 0.02, 0.12, WOOD);
  k.box(-0.22, 0, 0.4, 0.3, 0.05, 0.18, scale(WOOD, 0.8));
};

// ---- church ------------------------------------------------------------------------------------

/**
 * A church with its tower over the crossing instead of at the door: a nave under a steep roof, a lower
 * chancel at the back, the tower rising from the middle of the ridge to a spire (a dome, a copper cone,
 * a tiled spire or battlements, by the town's style), and a low gabled porch on the front. In the
 * towns of flared roofs (the Terraces, Edo, China) it is a temple hall with a three-tiered pagoda before it.
 */
const crossingChurch: Draw = (k, _W, _D, b, r) => {
  const styled = !!cur.form;
  const wall = styled ? styleWall(r) : pick(r, [0xf6f3ec, 0xe3dccb, 0xd8b9a0]);
  const roof = styled ? styleRoof(r) : hex(0x5a5f6b), glass = styled ? GLASS : hex(0x8a6fb0);
  const east = cur.form === 'curved';
  // the nave (z -0.56..0.46) and the chancel behind it (to -0.84), inside the shape's nave box
  const nh = 0.46, nz = -0.05, nl = 1.02;
  k.box(0, 0, nz, 0.6, nh, nl, wall);
  if (styled) roofOver(k, r, 0, nh, nz, 0.6, nl, wall, roof);
  else k.gable(0, nh, nz, 0.66, 0.32, nl + 0.06, roof, wall, true);
  const flat = cur.form === 'flat';
  k.box(0, 0, -0.68, 0.42, 0.36, 0.26, wall, flat ? scale(wall, 0.94) : wall);
  if (!flat) k.hip(0, 0.36, -0.68, 0.48, 0.2, 0.3, roof);
  for (const z of [-0.4, -0.08, 0.24]) for (const sx of [-1, 1]) win(k, b, r, sx * 0.3, 0.14, z, 0.08, 0.22, sx > 0 ? 0 : 2, glass);
  if (east) {
    // the pagoda in the tower's place before the hall: a base, three flared tiers and a finial
    const frame = hex(0x3a2c24), red = hex(0xb5402f);
    k.box(0, 0, 0.6, 0.3, 0.3, 0.3, red);
    let y = 0.3;
    for (let i = 0; i < 3; i++) {
      const s = 0.46 - i * 0.07;
      flaredLite(k, 0, y, 0.6, s, 0.1, s, roof, frame);
      y += 0.1;
      if (i < 2) { k.box(0, y, 0.6, 0.2 - i * 0.03, 0.12, 0.2 - i * 0.03, wall); y += 0.12; }
    }
    k.cyl(0, y, 0.6, 0.014, 0.3, GOLD, 5);
    k.box(0, 0, 0.755, 0.1, 0.2, 0.012, doorOf(r));
    return;
  }
  // the crossing tower, from the ridge up, with its belfry
  const tz = -0.3, tw = 0.28, top = nh + 0.6;
  k.box(0, nh, tz, tw, top - nh, tw, wall);
  if (styled) bellIn(k, 0, top - 0.22, tz + tw / 2, 0.1, 0.14);
  else win(k, b, r, 0, top - 0.2, tz + tw / 2, 0.1, 0.12, 1, hex(0x2a2a30));
  let tip: number;
  switch (curArch) {
    case 'cycladic': case 'adobe': case 'ottoman': {
      // a drum and a dome: blue on the Whitewash, mud in the Sands, tiled in the Ottoman city
      const dome = curArch === 'cycladic' ? styleTrim() : curArch === 'ottoman' ? pick(r, cur.tiles ?? cur.roofs) : wall;
      k.cyl(0, top, tz, 0.13, 0.06, wall, 8);
      k.dome(0, top + 0.06, tz, 0.14, dome, 8, 3);
      tip = top + 0.2;
      break;
    }
    case 'granite': case 'medieval': {
      // battlements round a low slate cap
      for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * 0.11, top, tz + sz * 0.11, 0.07, 0.1, 0.07, wall);
      k.hip(0, top, tz, 0.22, 0.24, 0.22, roof);
      tip = top + 0.24;
      break;
    }
    case 'russian':
      tip = onionDome(k, 0, top, tz, 0.13, pick(r, ONION_SKINS), styleTrim());
      break;
    case 'dutch':
      k.cone(0, top, tz, 0.17, 0.66, hex(0x5a8a7a), 8);
      tip = top + 0.66;
      break;
    case 'budapest':
      tiledHip(k, 0, top, tz, 0.32, 0.7, 0.32, roof, pick(r, cur.tiles ?? cur.roofs));
      tip = top + 0.7;
      break;
    case 'colonial': case 'pastel': case 'western':
      k.hip(0, top, tz, 0.32, 0.38, 0.32, roof);
      tip = top + 0.38;
      break;
    default:
      k.hip(0, top, tz, 0.32, 0.62, 0.32, roof);
      tip = top + 0.62;
  }
  if (curArch !== 'russian') cross(k, 0, tip, tz, curArch === 'cycladic' || curArch === 'western' ? WHITE : CROSS);
  // the porch on the front, filling the shape's tower box
  k.box(0, 0, 0.6, 0.3, 0.3, 0.3, wall, flat ? scale(wall, 0.94) : roof);
  if (!flat) k.gable(0, 0.3, 0.6, 0.34, 0.14, 0.32, roof, wall, true);
  if (styled) k.box(0, 0, 0.755, 0.12, 0.22, 0.012, doorOf(r));
  else win(k, b, r, 0, 0, 0.75, 0.12, 0.22, 1, hex(0x6b4a3a));
};

// ---- bakery ------------------------------------------------------------------------------------

/**
 * A boulangerie: a mansard roof with a dormer (its gable end-on to the street in the biome towns), a
 * painted shop bay standing out on the pavement under a sloping awning, lit before dawn for the early
 * bake, a round brick oven flue smoking at the back, and a gilt sign on a bracket.
 */
const mansardBakery: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), awning = pick(r, [0xe2412f, 0x2f7fb5, 0x3f9b4a, 0xf28c38]);
  const paint = pick(r, [0x3a3f45, 0x2f4d3a, 0x6b2a2a, 0xf1ece0]);
  const h = b.floors * FLOOR + 0.06, bz = -0.12, bd = 0.72, fz = bz + bd / 2;
  k.box(0, 0, bz, 0.84, h, bd, wall, ROOF_GREY);
  if (cur.form) styledGable(k, r, 0, h, bz, 0.9, cur.pitch * 0.5, bd + 0.06, roof, wall, true);
  else if (cur.pitch > 0.15) {
    mansard(k, 0, h, bz, 0.88, 0.76, 0.2, 0.12, roof, ROOF_GREY);
    k.box(0, h + 0.02, fz - 0.06, 0.16, 0.12, 0.08, wall);
    k.gable(0, h + 0.14, fz - 0.06, 0.19, 0.07, 0.1, roof, wall, true);
    win(k, { ...b, kind: 'townhouse' }, r, 0, h + 0.04, fz - 0.02, 0.09, 0.07, 1);
  } else k.box(0, h, bz, 0.88, 0.05, 0.76, scale(wall, 0.9));
  // the shop bay, its window and the lit board over it
  k.box(0, 0, fz + 0.06, 0.62, 0.3, 0.12, paint);
  k.pane(0, 0.06, fz + 0.12, 0.46, 0.17, 1, GLASS_LIGHT, [28, 38, 1.6], WARM_GLOW);
  slab(k, [-0.36, 0.35, fz], [0.36, 0.35, fz], [0.36, 0.3, fz + 0.2], [-0.36, 0.3, fz + 0.2], 0.012, awning);
  for (let f = 1; f < b.floors; f++) row(k, { ...b, kind: 'townhouse' }, r, 0, 0.12 + f * FLOOR, fz, 0.5, 0.12, 2, 1);
  // the oven flue at the back, and the smoke of the early bake
  k.cyl(-0.28, h - 0.05, bz - 0.2, 0.06, 0.38, pick(r, BRICK), 6);
  for (let i = 0; i < 3; i++) k.glowBox(-0.28 + i * 0.03, h + 0.4 + i * 0.1, bz - 0.2, 0.1 - i * 0.02, 0.06, 0.1 - i * 0.02, hex(0xe8e8e4), [28.5, 31, 0.6], hex(0xffe8c8));
  // the gilt sign hung from its bracket, edge-on to the street
  k.box(0.38, 0.5, fz + 0.06, 0.02, 0.02, 0.12, DARK);
  k.box(0.38, 0.38, fz + 0.1, 0.012, 0.11, 0.1, GOLD);
};

// ---- diner -------------------------------------------------------------------------------------

/**
 * A streamlined railcar diner: a long stainless body under a barrel roof, a coloured stripe under its
 * band of windows, an entrance vestibule standing out in front, and its sign on a pole by the road.
 */
const railcarDiner: Draw = (k, _W, _D, b, r) => {
  const accent = pick(r, BRIGHT), steel = hex(0xd4d8dc);
  const bz = -0.06, bd = 0.44, fz = bz + bd / 2;
  k.box(0, 0, bz, 0.9, 0.24, bd, steel);
  barrel(k, 0, 0.24, bz, 0.9, bd, 0.1, scale(steel, 0.92), steel, 3);
  k.box(0, 0.03, bz, 0.912, 0.045, bd + 0.012, accent);
  // one long band of glass, as a railcar's windows read from the road
  win(k, b, r, -0.15, 0.1, fz, 0.54, 0.1, 1, GLASS_LIGHT);
  win(k, b, r, 0, 0.1, bz - bd / 2, 0.7, 0.1, 3, GLASS_LIGHT);
  k.box(0.24, 0, fz + 0.07, 0.2, 0.28, 0.14, accent, steel);
  k.box(0.24, 0, fz + 0.144, 0.1, 0.2, 0.008, GLASS_LIGHT);
  k.box(-0.38, 0, 0.38, 0.03, 0.46, 0.03, METAL);
  k.glowBox(-0.38, 0.46, 0.38, 0.22, 0.12, 0.04, accent, [16.5, 30, 1.8], accent);
  car(k, -0.08, 0.4, true, pick(r, CARS));
};

// ---- school ------------------------------------------------------------------------------------

/**
 * A board school: a taller hall block in the middle with its gable to the playground and a bell cupola on
 * the ridge, a lower classroom wing either side under a shared cornice, a gabled entrance porch, and a
 * netball court painted on the yard.
 */
const wingedSchool: Draw = (k, _W, _D, b, r) => {
  // a hair off the style's own wall colour, so the Kit does not half-timber blocks the original's one
  // long bar (too big to frame) leaves plain
  const brick = cur.form ? scale(styleWall(r), 0.97) : pick(r, BRICK), trim = cur.form ? styleTrim() : hex(0xe9e2d3);
  const roof = cur.form ? styleRoof(r) : hex(0x5a5f6b);
  // the shape's bar: x ±1.75, z -1.2..0.1; the hall block in the middle, a wing either side
  const bz = -0.55, bd = 1.3, fz = bz + bd / 2, cw = 1.2, ch = 0.74, wh = 0.56, ww = (3.5 - cw) / 2, wx = cw / 2 + ww / 2;
  k.box(0, 0, bz, cw, ch, bd, brick);
  for (const sx of [-1, 1]) k.box(sx * wx, 0, bz, ww, wh, bd, brick, ROOF_GREY);
  if (cur.form) {
    lid(k, r, 0, ch, bz, cw, bd, brick, roof, true, 0.3, true);
    // flared eaves run the length of both wings as one roof, the hall rising through it
    if (cur.form === 'curved') flaredLite(k, 0, wh, bz, 3.5, Math.min(0.5, bd * cur.pitch * 0.9), bd + 0.1, roof, brick);
    else for (const sx of [-1, 1]) lid(k, r, sx * wx, wh, bz, ww, bd, brick, roof, false);
  } else {
    k.gable(0, ch, bz, cw + 0.06, 0.26, bd + 0.06, roof, brick, true);
    k.box(0, wh, bz, 3.56, 0.05, bd + 0.06, trim);
    k.box(0, ch + 0.16, bz, 0.16, 0.2, 0.16, trim);
    k.hip(0, ch + 0.36, bz, 0.22, 0.16, 0.22, roof);
  }
  for (const y of [0.12, 0.34]) for (const sx of [-1, 1]) row(k, b, r, sx * wx, y, fz, ww - 0.2, 0.11, 4, 1);
  row(k, b, r, 0, 0.46, fz, cw - 0.3, 0.14, 3, 1);
  for (const sx of [-1, 1]) win(k, b, r, sx * 0.47, 0.12, fz, 0.18, 0.14, 1);
  // the porch, filling the shape's entrance box (x ±0.35, z 0.1..0.3)
  k.box(0, 0, 0.2, 0.7, 0.4, 0.2, trim, ROOF_GREY);
  k.gable(0, 0.4, 0.2, 0.74, 0.12, 0.24, roof, trim);
  k.box(0, 0, 0.305, 0.3, 0.26, 0.02, doorOf(r));
  // the flag, and the court on the yard
  k.cyl(1.3, 0, 0.8, 0.02, 1.0, METAL, 5);
  k.box(1.42, 0.82, 0.8, 0.22, 0.14, 0.01, pick(r, BRIGHT));
  k.box(-0.9, 0, 0.85, 1.3, 0.006, 0.75, hex(0x5a8a6a));
  k.box(-0.9, 0.006, 0.85, 0.03, 0.004, 0.75, WHITE);
};

// ---- store -------------------------------------------------------------------------------------

/**
 * A general store with its gable to the street (a false front out west, a flat parapet in the sands), a
 * canopy across the front carrying the name board, a window either side of the door, and on two floors a
 * room over the shop.
 */
const gableStore: Draw = (k, _W, _D, b, r) => {
  const wall = cur.form ? styleWall(r) : pick(r, [...WALLS, ...BRICK]), roof = cur.form ? styleRoof(r) : pick(r, ROOFS);
  const two = b.floors > 1, h = two ? 0.56 : 0.38, bz = -0.1, bd = 0.72, fz = bz + bd / 2;
  k.box(0, 0, bz, 0.8, h, bd, wall);
  lid(k, r, 0, h, bz, 0.8, bd, wall, roof, true, 0.34, true);
  k.box(0, 0.3, fz + 0.09, 0.84, 0.025, 0.18, roof);
  k.box(0, 0.325, fz + 0.172, 0.56, 0.07, 0.012, pick(r, BRIGHT));
  win(k, b, r, -0.12, 0.05, fz, 0.44, 0.2, 1, GLASS_LIGHT);
  k.pane(0.24, 0, fz, 0.12, 0.25, 1, doorOf(r), windowSched(b.kind, r), SHOP_GLOW);
  if (two) win(k, { ...b, kind: 'townhouse' }, r, 0, 0.4, fz, 0.4, 0.1, 1);
  k.box(0.34, 0, fz + 0.13, 0.12, 0.1, 0.1, WOOD);
};

// ---- cafe --------------------------------------------------------------------------------------

/**
 * A café with a glasshouse out on the pavement: the house set back under a hip roof (or the style's
 * own), and before it a glazed winter garden lit warm in the evening, white bars and a glass ridge roof,
 * planters either side of its door.
 */
export const conservatoryCafe: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), frame = pick(r, [0xf4f2ec, 0x2f4d3a, 0x3a3f45]);
  const h = b.floors * FLOOR + 0.06, bz = -0.22, bd = 0.5, fz = bz + bd / 2;
  k.box(0, 0, bz, 0.86, h, bd, wall, ROOF_GREY);
  if (cur.form) lid(k, r, 0, h, bz, 0.84, bd, wall, styleRoof(r), false, 0.3, true);
  else if (cur.pitch > 0.15) k.hip(0, h, bz, 0.92, 0.22, bd + 0.06, styleRoof(r));
  else k.box(0, h, bz, 0.88, 0.05, bd + 0.02, scale(wall, 0.9));
  for (let f = 1; f < b.floors; f++) row(k, { ...b, kind: 'townhouse' }, r, 0, 0.08 + f * FLOOR, fz, 0.6, 0.13, 3, 1);
  // the winter garden
  const gz = fz + 0.18, gw = 0.74, gd = 0.36, gh = 0.26;
  k.glowBox(0, 0, gz, gw, gh, gd, GLASS_LIGHT, [16.5, 22.5, 1.6], SHOP_GLOW);
  for (const sx of [-1, -0.34, 0.34, 1]) k.box(sx * gw / 2, 0, gz + gd / 2, 0.025, gh, 0.025, frame);
  k.box(0, gh, gz, gw + 0.02, 0.02, gd + 0.02, frame);
  k.gable(0, gh + 0.02, gz, gw + 0.04, 0.1, gd + 0.04, hex(0xbcdce6), frame);
  k.box(0, 0, gz + gd / 2 + 0.004, 0.12, 0.2, 0.008, frame);
  for (const sx of [-1, 1]) k.box(sx * 0.4, 0, 0.44, 0.08, 0.08, 0.08, WOOD, LEAF);
};

// ---- village hall ------------------------------------------------------------------------------

/**
 * A village hall with a cross-wing: the hall's low walls and steep roof end-on to the road with a window
 * up in its gable and a little flèche on the ridge, a taller wing across the back with its ridge the other
 * way, a hooded door, and festoon lights along the front on dance nights.
 */
const crossWingHall: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r);
  const bw = W - 0.34, bd = D - 0.5, bz = -0.14, fz = bz + bd / 2, bk = bz - bd / 2;
  if (bd < bw + 0.3) {
    // a lot too shallow for a wing: the hall broadside to the road, a gabled porch at its middle
    k.box(0, 0, bz, bw, 0.36, bd, wall);
    styledGable(k, r, 0, 0.36, bz, bw + 0.08, 0.34, bd + 0.06, roof, wall);
    row(k, b, r, 0, 0.12, fz, bw * 0.8, 0.14, Math.max(2, Math.round(bw / 0.3)), 1);
    k.box(0, 0, fz + 0.08, 0.3, 0.28, 0.16, wall);
    styledGable(k, r, 0, 0.28, fz + 0.08, 0.36, 0.14, 0.2, roof, wall, true);
    k.box(0, 0, fz + 0.165, 0.12, 0.2, 0.012, doorOf(r));
    return;
  }
  const wd = Math.min(0.44, bd * 0.35), hl = bd - wd, hz = fz - hl / 2, cz = bk + wd / 2, hw = bw - 0.1;
  k.box(0, 0, hz, hw, 0.32, hl, wall);
  styledGable(k, r, 0, 0.32, hz, hw + 0.08, 0.42, hl + 0.04, roof, wall, true);
  k.box(0, 0, cz, bw, 0.4, wd, wall);
  styledGable(k, r, 0, 0.4, cz, bw + 0.06, 0.4, wd + 0.08, roof, wall);
  if (cur.form !== 'flat' && cur.form !== 'false' && cur.form !== 'curved') {
    k.box(0, 0.62, hz, 0.08, 0.2, 0.08, styleTrim());
    k.hip(0, 0.82, hz, 0.11, 0.22, 0.11, roof);
    if (cur.form !== 'dutch') win(k, b, r, 0, 0.38, fz + 0.02, 0.12, 0.12, 1);
  }
  for (let i = 0; i < 3; i++) for (const sx of [-1, 1]) win(k, b, r, sx * hw / 2, 0.1, hz - hl / 2 + (hl * (i + 0.5)) / 3, 0.12, 0.14, sx > 0 ? 0 : 2);
  for (const sx of [-1, 1]) win(k, b, r, sx * bw / 2, 0.12, cz, 0.14, 0.16, sx > 0 ? 0 : 2);
  for (const sx of [-1, 1]) win(k, b, r, sx * 0.17, 0.1, fz, 0.1, 0.13, 1);
  k.box(0, 0, fz + 0.004, 0.13, 0.22, 0.012, doorOf(r));
  k.box(0, 0.25, fz + 0.05, 0.22, 0.02, 0.1, roof);
  k.box(0.3, 0.02, fz + 0.28, 0.14, 0.14, 0.02, WOOD);
  k.box(0.3, 0.06, fz + 0.291, 0.1, 0.08, 0.004, WHITE);
  k.tagged(Vis.Weekend, () => k.glowBox(0, 0.29, fz + 0.03, hw * 0.8, 0.012, 0.012, hex(0xf2c14e), [17.5, 23.5, 1.8], WARM_GLOW));
};

// ---- grocery -----------------------------------------------------------------------------------

/**
 * A market grocery: the hall under three gables to the street (the style's roofs, one per bay), a deep
 * canopy on two slim posts across the front with produce stalls under it, and the lit sign up in the
 * middle gable.
 */
const threeBayGrocery: Draw = (k, _W, _D, b, r) => {
  const body = pick(r, [0xefe6d6, 0xe3e8ec, 0xf2efe6]), brand = pick(r, BRIGHT), roof = cur.form ? styleRoof(r) : hex(0x6a6e74);
  const bz = -0.27, bd = 1.3, fz = bz + bd / 2, h = 0.46;
  k.box(0, 0, bz, 2.7, h, bd, body, ROOF_GREY);
  let top: number;
  if (cur.form === 'flat' || cur.form === 'false' || cur.form === 'curved') top = lid(k, r, 0, h, bz, 2.7, bd, body, roof, false);
  else {
    top = h;
    for (const i of [-1, 0, 1]) top = lid(k, r, i * 0.9, h, bz, 0.9, bd, body, roof, true, 0.3);
  }
  k.glowBox(0, Math.max(h + 0.04, top - 0.24), fz + 0.07, 0.56, 0.12, 0.03, brand, [16.5, 22.5, 1.8], brand);
  row(k, b, r, 0, 0.04, fz, 2.2, 0.24, 4, 1, GLASS_LIGHT);
  // the canopy cantilevered off the front, a car's roof clear under it, and the stalls
  k.box(0, h + 0.005, fz + 0.16, 2.6, 0.03, 0.32, brand, ROOF_GREY);
  k.box(-0.7, 0, fz + 0.14, 0.9, 0.12, 0.14, WOOD, pick(r, [0x6fb04a, 0xf28c38, 0xd8344a]));
  // as many cars in the car park as the original model parks on this lot (it draws them last, from the same seed)
  const o = mulberry32(b.seed);
  for (let i = 0; i < 10; i++) o();
  let n = 0;
  for (let i = 0; i < 4; i++) if (o() < 0.6) { o(); n++; }
  for (const sx of [-1.1, 0.5, -0.4, 1.1].slice(0, n)) car(k, sx, 0.8, false, pick(r, CARS));
};

export const TOWN_VARIANTS: Partial<Record<BuildingKind, Draw[]>> = {
  gas: [roadsideGas],
  postOffice: [pedimentPost],
  pub: [jettiedInn],
  church: [crossingChurch],
  bakery: [mansardBakery],
  diner: [railcarDiner],
  school: [wingedSchool],
  store: [gableStore],
  cafe: [conservatoryCafe],
  villageHall: [crossWingHall],
  grocery: [threeBayGrocery],
};

/** What these models make their buildings called (kit MODEL_NAMES): the rest keep their kind's name. */
nameModels([[jettiedInn, 'Coaching Inn'], [conservatoryCafe, 'Conservatory Café'], [railcarDiner, 'Railcar Diner']]);
