/**
 * The HQ window's Tech tab (docs/hqwindow.html, "Tech"): the three tech trees drawn as one map. Land, Sea
 * and Air are bands on one tier axis (each tier's diamond price in its header), and each band is its tree's
 * named branch rows (tech.ts ROWS): a node stands in one cell of its row, so a row reads left to right as
 * one line of choices, from what it costs ◆ 4 to what it leads to at ◆ 64 and up. A line runs from every
 * node to each parent it opens from, along the row or with one bend into the row beside it (game/techLayout.ts),
 * never across another. The picked node's model turns in the pane beside it, with its numbers as bars
 * against the best in its tree, what it does for the fleet, where it is sold this year, and Unlock; its
 * line of ancestors back to the starter is lit on the map. The rules are game/tech.ts's, unchanged.
 */
import { esc, money } from './cargoHud';
import { priceOf } from './economy';
import { stockThumb } from './garageMenu';
import { ROWS, TECH, TECH_BY_ID, TREES, TREE_ICON, TREE_LABEL, tierCost, type Tech, type TechNode, type Tree } from './tech';
import { route } from './techLayout';
import { DEFS, HOLD_WORD, STATS, best, modifiers, nameOf } from './techWindow';
import { ALL_VEHICLES } from './vehicles';
import { wayTo, type Outlet, type Outlets } from './outlets';
import { hero } from '../render/heroStage';
import { FACTIONS, RUNGS, type FactionId } from './factions/factions';

interface TechTabHost {
  /** Where the player is, in world tiles, to point at a dealer. */
  where(): { x: number; z: number };
  diamonds(): number;
  say(text: string): void;
  /** Bring up the dealer's building card (the tech card names where a model is sold this year). */
  showDealer?(o: Outlet): void;
}

/** Columns in the order the trees use them: every tier any tree has. */
/** Each model's def by id, for its card art. */
const VEHICLE_OF = new Map(ALL_VEHICLES.map((d) => [d.id, d]));
const TIERS = [...new Set(TECH.filter((n) => !n.standing).map((n) => n.tier))].sort((a, b) => a - b);
/** Then the factions' own models, Honoured and Sworn, at the end of every band. */
const OWN_RUNGS = [...new Set(TECH.filter((n) => n.standing).map((n) => n.standing!.rung))].sort((a, b) => a - b);
/** Where a node stands along its row, for the arrow keys: its tier, the factions' own past every tier. */
const along = (n: TechNode): number => (n.standing ? 100 + n.standing.rung : n.tier);
/** The row a node stands on for the arrow keys: a faction's own sit beside the band's middle row. */
const rowOf = (n: TechNode): number => (n.standing ? (ROWS[n.tree].length - 1) / 2 : n.row);
const factionOf = (n: TechNode) => (n.standing ? FACTIONS[n.standing.faction as FactionId] : undefined);
const hex = (c: number) => `#${c.toString(16).padStart(6, '0')}`;
/** A faction's stripe on its models' nodes: its colour, or its accent when the colour is near white. */
const stripe = (n: TechNode): string => {
  const f = factionOf(n);
  if (!f) return '';
  const c = f.colour, light = ((c >> 16) & 255) + ((c >> 8) & 255) + (c & 255) > 600;
  return hex(light ? f.accent : c);
};
/** The grid column a tier's cell is in: after the band label and the row label. */
const colOf = (tier: number): number => 3 + TIERS.indexOf(tier);
/** A node and every node it descends from, back to a starter: the line lit when it's picked. */
const ancestry = (id: string): Set<string> => {
  const out = new Set<string>();
  const walk = (x: string) => { if (out.has(x)) return; out.add(x); for (const p of TECH_BY_ID.get(x)?.from ?? []) walk(p); };
  walk(id);
  return out;
};

export class TechTab {
  readonly el = document.createElement('div');
  private map = document.createElement('div');
  private grid = document.createElement('div');
  private lines = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  private pane = document.createElement('div');
  private stage = document.createElement('div');
  private body = document.createElement('div');
  sel = '';
  private hover = '';
  /** The dealer the pane's card names, for its link. */
  private dealer: Outlet | null = null;
  private shown = false;
  private message = '';
  private html = '';
  private resize = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(() => this.drawLines()) : null;

  constructor(private tech: Tech, private outlets: Outlets, private host: TechTabHost) {
    this.el.className = 'hq-tech';
    this.map.className = 'hq-tmap';
    this.grid.className = 'hq-tgrid';
    this.lines.setAttribute('class', 'hq-tlines');
    this.lines.setAttribute('aria-hidden', 'true');
    this.map.append(this.lines, this.grid);
    this.pane.className = 'hq-pane';
    this.stage.className = 'hq-stage veh';
    this.body.className = 'hq-pbody';
    this.pane.append(this.stage, this.body);
    this.el.append(this.map, this.pane);
    this.resize?.observe(this.map);
    this.grid.addEventListener('click', (e) => {
      const node = (e.target as HTMLElement).closest<HTMLElement>('[data-node]');
      if (!node) return;
      this.pickNode(node.dataset.node!);
    });
    this.grid.addEventListener('mouseover', (e) => {
      const id = (e.target as HTMLElement).closest<HTMLElement>('[data-node]')?.dataset.node ?? '';
      if (id !== this.hover) { this.hover = id; this.drawLines(); }
    });
    this.grid.addEventListener('mouseleave', () => { this.hover = ''; this.drawLines(); });
    this.pane.addEventListener('click', (e) => {
      if ((e.target as HTMLElement).closest('button[data-dealer]')) { if (this.dealer) this.host.showDealer?.(this.dealer); return; }
      const b = (e.target as HTMLElement).closest<HTMLButtonElement>('button[data-unlock]');
      if (b && !b.disabled) this.unlock(this.sel);
    });
    this.map.addEventListener('scroll', () => this.drawLines());
  }

  private pickNode(id: string): void {
    // a second press on the picked one unlocks it, if it can be
    if (this.sel === id && this.tech.state(id) === 'open' && !this.tech.whyNot(id)) { this.unlock(id); return; }
    this.sel = id;
    this.message = '';
    this.render(true);
  }

  private unlock(id: string): void {
    const why = this.tech.unlock(id, nameOf(id));
    this.message = why ?? `${nameOf(id)} unlocked · on sale at dealers that stock it`;
    if (why) this.host.say(why);
    this.render(true);
  }

  /** Open at one model's node (from a locked vehicle, the gem chip, a dealer). */
  focus(id?: string): void {
    if (id && TECH_BY_ID.has(id)) this.sel = id;
  }

  setVisible(on: boolean): void {
    this.shown = on;
    if (!on) return;
    if (!this.sel) this.sel = this.firstOpen();
    this.render(true);
  }

  private firstOpen(): string {
    for (const t of TREES) { const o = this.tech.open(t)[0]; if (o) return o.id; }
    return TECH[0]?.id ?? '';
  }

  /** Arrow keys on the map: along a row by tier, or to the nearest node on the row above or below (on into the next tree). */
  key(code: string): boolean {
    const n = TECH_BY_ID.get(this.sel);
    if (!n) return false;
    let next: TechNode | undefined;
    const nearest = (pool: TechNode[]) => pool.sort((a, b) => Math.abs(along(a) - along(n)) - Math.abs(along(b) - along(n)) || TECH.indexOf(a) - TECH.indexOf(b))[0];
    if (code === 'ArrowRight' || code === 'ArrowLeft') {
      const dir = code === 'ArrowRight' ? 1 : -1;
      // along the row; off its end, the factions' own (or back from them to the row's last node)
      const row = TECH.filter((t) => t.tree === n.tree && (n.standing ? !!t.standing : !t.standing && t.row === n.row))
        .sort((a, b) => along(a) - along(b) || TECH.indexOf(a) - TECH.indexOf(b));
      next = row[row.indexOf(n) + dir];
      if (!next && dir === 1 && !n.standing) next = TECH.filter((t) => t.tree === n.tree && t.standing)[0];
      if (!next && dir === -1 && n.standing) next = nearest(TECH.filter((t) => t.tree === n.tree && !t.standing && t.tier === Math.max(...TECH.filter((x) => x.tree === n.tree && !x.standing).map((x) => x.tier))));
    } else if (code === 'ArrowDown' || code === 'ArrowUp') {
      const dir = code === 'ArrowDown' ? 1 : -1;
      // the nearest node by tier on the next row that has one; past the band's edge, the next tree's nearest row
      const rows = ROWS[n.tree].length;
      for (let r = Math.round(rowOf(n)) + dir; r >= 0 && r < rows && !next; r += dir) next = nearest(TECH.filter((t) => t.tree === n.tree && !t.standing && t.row === r));
      if (!next) {
        const ti = TREES.indexOf(n.tree) + dir, tree: Tree = TREES[(ti + TREES.length) % TREES.length];
        const edge = dir === 1 ? 0 : ROWS[tree].length - 1;
        for (let r = edge; r >= 0 && r < ROWS[tree].length && !next; r += dir) next = nearest(TECH.filter((t) => t.tree === tree && !t.standing && t.row === r));
      }
    } else if (code === 'Enter' || code === 'NumpadEnter') { this.pickNode(this.sel); return true; }
    if (!next) return false;
    this.sel = next.id;
    this.message = '';
    this.render(true);
    this.grid.querySelector(`[data-node="${next.id}"]`)?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    return true;
  }

  render(force = false): void {
    if (!this.shown) return;
    const head = `<div class="hq-tlane head" style="--rows:1"><span class="ln"></span><span class="rl"></span>${TIERS.map((t, i) => `<span class="th" style="grid-column:${i + 3}">${t === 0 ? 'Start' : `Tier ${t}<b>◆ ${tierCost(t)}</b>`}</span>`).join('')}`
      + `${OWN_RUNGS.map((r, i) => `<span class="th own" style="grid-column:${TIERS.length + 3 + i}">Factions<b>${esc(RUNGS[r]?.name ?? '')}</b></span>`).join('')}</div>`;
    const lanes = TREES.map((tree) => {
      const nodes = TECH.filter((n) => n.tree === tree);
      const done = nodes.filter((n) => this.tech.state(n.id) === 'unlocked').length;
      const rows = ROWS[tree];
      const labels = rows.map((name, r) => {
        const first = nodes.filter((n) => !n.standing && n.row === r).sort((a, b) => a.tier - b.tier)[0];
        return `<span class="rl${first && first.tier === 0 ? ' root' : ''}" style="grid-row:${r + 1}" title="${esc(name)}: ${this.rowBlurb(tree, r)}">${esc(name)}</span>`;
      }).join('');
      const cells = nodes.filter((n) => !n.standing).map((n) => this.nodeHtml(n, `grid-column:${colOf(n.tier)};grid-row:${n.row + 1}`)).join('');
      const own = OWN_RUNGS.map((r, i) => `<div class="col own" style="grid-column:${TIERS.length + 3 + i};grid-row:1 / -1">${nodes.filter((n) => n.standing?.rung === r).map((n) => this.nodeHtml(n)).join('')}</div>`).join('');
      return `<div class="hq-tlane" data-tree="${tree}" style="--rows:${rows.length}"><span class="ln" style="grid-row:1 / -1">${TREE_ICON[tree]} <b>${TREE_LABEL[tree]}</b><small>${done} of ${nodes.length}</small></span>${labels}${cells}${own}</div>`;
    }).join('');
    const html = head + lanes;
    if (force || html !== this.html) {
      this.html = html;
      this.grid.style.setProperty('--cols', String(TIERS.length));
      this.grid.style.setProperty('--own', String(OWN_RUNGS.length));
      this.grid.innerHTML = html;
      requestAnimationFrame(() => this.drawLines());
    }
    this.renderPane();
  }

  /** What a row leads to, for its label's tooltip: its models in tier order. */
  private rowBlurb(tree: Tree, row: number): string {
    return TECH.filter((n) => !n.standing && n.tree === tree && n.row === row).sort((a, b) => a.tier - b.tier).map((n) => nameOf(n.id)).join(' → ');
  }

  private nodeHtml(n: TechNode, style = ''): string {
    const st = this.tech.state(n.id);
    const def = VEHICLE_OF.get(n.id);
    const src = def ? stockThumb(def) : undefined;
    const f = factionOf(n);
    const mark = st === 'unlocked' ? '<small class="st">✓</small>' : f ? `<small class="st">${f.glyph} ${esc(f.short)}</small>`
      : st === 'open' ? `<small class="st">◆ ${tierCost(n.tier)}</small>` : '<small class="st">locked</small>';
    const title = f ? `${nameOf(n.id)} · ${f.name}, ${RUNGS[n.standing!.rung]?.name ?? ''}` : nameOf(n.id);
    const css = `${style}${f ? `${style ? ';' : ''}--fc:${stripe(n)}` : ''}`;
    return `<button type="button" class="node ${st}${f ? ' own' : ''}${this.sel === n.id ? ' sel' : ''}" data-node="${n.id}" title="${esc(title)}"${css ? ` style="${css}"` : ''}>`
      + `${src ? `<img alt="" src="${src}" draggable="false">` : '<span class="ph"></span>'}<b>${esc(nameOf(n.id))}</b>${mark}</button>`;
  }

  /**
   * A line from each node to each of its parents: along the row, or along one row with a bend into the other
   * (techLayout.ts). Green from an unlocked parent, grey otherwise; the picked node's ancestry and the hovered
   * node's own lines lit.
   */
  private drawLines(): void {
    if (!this.shown || !this.grid.isConnected) return;
    const box = this.map.getBoundingClientRect();
    const W = this.grid.scrollWidth, H = this.grid.scrollHeight;
    this.lines.setAttribute('width', String(W));
    this.lines.setAttribute('height', String(H));
    this.lines.setAttribute('viewBox', `0 0 ${W} ${H}`);
    const at = new Map<string, DOMRect>();
    for (const el of Array.from(this.grid.querySelectorAll<HTMLElement>('[data-node]'))) at.set(el.dataset.node!, el.getBoundingClientRect());
    // each tier column's span, from the header
    const cols = Array.from(this.grid.querySelectorAll<HTMLElement>('.head .th:not(.own)')).map((el) => el.getBoundingClientRect());
    const ox = box.left - this.map.scrollLeft, oy = box.top - this.map.scrollTop;
    const colL = (tier: number) => (cols[TIERS.indexOf(tier)]?.left ?? 0) - ox, colR = (tier: number) => (cols[TIERS.indexOf(tier)]?.right ?? 0) - ox;
    const bend = (x0: number, y0: number, x1: number, y1: number) => { const m = (x0 + x1) / 2; return `C${m.toFixed(1)} ${y0.toFixed(1)} ${m.toFixed(1)} ${y1.toFixed(1)} ${x1.toFixed(1)} ${y1.toFixed(1)}`; };
    const chain = ancestry(this.sel);
    const paths: string[] = [];
    for (const n of TECH) {
      const c = at.get(n.id);
      if (!c) continue;
      for (const pid of n.from) {
        const p = TECH_BY_ID.get(pid), r = at.get(pid);
        if (!p || !r) continue;
        const x1 = r.right - ox, y1 = r.top + r.height / 2 - oy, x2 = c.left - ox, y2 = c.top + c.height / 2 - oy;
        const kind = route(n, p);
        let d: string;
        if (kind === 'row') d = `M${x1.toFixed(1)} ${y1.toFixed(1)} L${x2.toFixed(1)} ${y2.toFixed(1)}`;
        else if (kind === 'late') { const xb = Math.max(x1, colR(n.tier - 1)); d = `M${x1.toFixed(1)} ${y1.toFixed(1)} H${xb.toFixed(1)} ${bend(xb, y1, x2, y2)}`; }
        else if (kind === 'early') { const xb = Math.min(x2, colL(p.tier + 1)); d = `M${x1.toFixed(1)} ${y1.toFixed(1)} ${bend(x1, y1, xb, y2)} H${x2.toFixed(1)}`; }
        else d = `M${x1.toFixed(1)} ${y1.toFixed(1)} ${bend(x1, y1, x2, y2)}`;
        const lit = this.hover === n.id || this.hover === pid || (chain.has(n.id) && chain.has(pid));
        const cls = `${this.tech.has(pid) ? 'on' : ''}${lit ? ' lit' : ''}`;
        paths.push(`<path class="${cls}" d="${d}"/>`);
      }
    }
    // the lit lines last, over the rest
    paths.sort((a, b) => Number(a.includes(' lit')) - Number(b.includes(' lit')));
    this.lines.innerHTML = paths.join('');
  }

  private renderPane(): void {
    const n = TECH_BY_ID.get(this.sel), d = n ? DEFS.get(n.id) : undefined;
    if (!n || !d) { this.stage.hidden = true; this.body.innerHTML = '<p class="none">Pick a model on the map.</p>'; return; }
    const rail = d.kind === 'rail';
    // every model turns on the plinth, a train as its engine
    this.stage.hidden = false;
    if (this.shown) { hero.mount(this.stage); hero.show({ kind: 'vehicle', model: d.id }, 0x2aa7c9); }
    this.stage.classList.toggle('locked', this.tech.state(n.id) === 'locked');
    const st = this.tech.state(n.id), why = this.tech.whyNot(n.id), price = priceOf(n.id);
    const bars = STATS.map((s) => {
      const v = s.get(d), max = best(n.tree, s, rail);
      if (v === undefined || !(max > 0)) return '';
      const w = Math.max(4, Math.round((v / max) * 100));
      return `<span>${s.label}</span><i><em class="${v >= max ? 'top' : ''}" style="width:${w}%"></em></i><small>${esc(s.text(d, v, max))}</small>`;
    }).join('');
    const holds = d.holds.map((h) => `<span class="pill hold">${HOLD_WORD[h] ?? h}</span>`).join('') || '<span class="pill">carries nothing</span>';
    const tags = d.tags.map((t) => `<span class="pill tag">${esc(t)}</span>`).join('');
    const mods = modifiers(d).map(([ico, what, val]) => `<tr><td>${ico}</td><td>${esc(what)}</td><td>${esc(val)}</td></tr>`).join('');
    const me = this.host.where();
    const dealer = this.outlets.nearest('dealer', me.x, me.z, (o) => this.outlets.models(o).includes(n.id));
    this.dealer = dealer?.o ?? null;
    const sold = dealer ? `<p class="gsub sold">🏷️ Sold this year at <button type="button" class="dealer" data-dealer title="Bring up ${esc(dealer.o.name)}${/s$/i.test(dealer.o.name) ? '’' : '’s'} card">${esc(dealer.o.name)}</button><small>${esc(dealer.o.townName)} · ${esc(wayTo(me.x, me.z, dealer.o))}</small></p>`
      : `<p class="gsub">${rail ? 'Trains are sold only by train dealers, rare, at the bigger stations: none you know of has one this year' : 'No dealer you know of stocks one this year'}.</p>`;
    const state = st === 'unlocked' ? '<span class="pill ok">✓ unlocked</span>' : why ? `<span class="pill no">${esc(why)}</span>` : '<span class="pill ok">ready to unlock</span>';
    const f = factionOf(n), rung = n.standing ? RUNGS[n.standing.rung]?.name ?? '' : '';
    const branch = f ? '' : `${ROWS[n.tree][n.row] ?? ''}${n.branch ? ` · ${n.branch}` : ''}`;
    const btn = st === 'unlocked' || f ? '' : `<button type="button" class="unlock" data-unlock${why ? ` disabled title="${esc(why)}"` : ''}>Unlock · ◆ ${tierCost(n.tier)}</button>`;
    this.body.innerHTML = `<div class="gname"><h4>${esc(d.name)}</h4><span>${TREE_ICON[n.tree]} ${f ? `${f.icon} ${esc(f.name)} · ${esc(rung)}` : n.tier ? `tier ${n.tier}` : 'starter'}${branch ? ` · ${esc(branch)}` : ''}</span></div>
      <p class="gsub">${esc(d.blurb)}</p>
      <div class="tc-row"><span class="pill cash">${price ? money(price) : 'free'} at a ${rail ? 'railway' : 'dealer'}</span>${f ? `<span class="pill dia">no ◆ · earned with ${esc(f.short)} standing</span>` : n.tier ? `<span class="pill dia">◆ ${tierCost(n.tier)} to unlock</span>` : '<span class="pill dia">starter · no ◆</span>'}${state}</div>
      ${btn}${this.message ? `<p class="gsub msg">${esc(this.message)}</p>` : ''}
      ${sold}
      <div class="tc-h">Performance · against the best ${rail ? 'on rails' : `in ${TREE_LABEL[n.tree].toLowerCase()}`}</div><div class="bars">${bars}</div>
      <div class="tc-h">Carries</div><div class="tc-row">${holds}${tags}</div>
      <div class="tc-h">What it gives you</div><table class="tc-mods">${mods}</table>
      ${n.from.length ? `<p class="tc-foot">Opens after ${n.from.map((p) => `${esc(nameOf(p))}${this.tech.has(p) ? ' ✓' : ''}`).join(' or ')}</p>` : ''}`;
  }
}
