import * as THREE from 'three';
import { badgePaint } from '../game/logos';
import { emblemOf } from '../game/treats';

/**
 * Fleet badges in the world: a small disc with the fleet's logo hovering over every vehicle and every
 * building a fleet owns (the player's and each rival firm's), and a shield twice the size over each
 * fleet's HQ. They are sprites, drawn over everything so a badge behind a roof still reads, and faded
 * out with distance from what the camera follows so a far town isn't a cloud of them.
 */

export interface BadgeLook { logo: string; primary: number; accent: number;
  /** An HQ's grade (docs/hq.html): as many gold stars in a ribbon under its shield. */
  stars?: number;
  /** A visa emblem (game/treats.ts EMBLEMS, a deeds group): a frame round the badge in its colour, its glyph on top. */
  frame?: string;
  /** The Front-row pass (the Events seal): a little lanyard pass hanging off the badge. */
  pass?: boolean;
  /** The fleet's birthday (game/birthday.ts): a bunch of balloons in its colours tied over the badge. */
  balloons?: boolean }
export type BadgeShape = 'disc' | 'shield';

/**
 * On-screen height, in CSS pixels, of a vehicle's badge, a building's, and an HQ's shield (twice a
 * building's). Held the same at every zoom so a badge reads whether the camera is close or pulled out.
 */
export const BADGE_SIZE = { vehicle: 20, building: 26, hq: 52 };
/** Tiles from the camera's focus where badges start to fade, and where they are gone. */
const NEAR = 55, FAR = 80;
const MAX = 320;

const lookKey = (l: BadgeLook, s: BadgeShape): string => `${s}|${l.logo}|${l.primary}|${l.accent}|${l.stars ?? 0}|${l.frame ?? ''}|${l.pass ? 1 : 0}|${l.balloons ? 1 : 0}`;

/** A birthday's balloons over a painted badge: the badge's canvas grown upward, three balloons on strings to its top. */
function withBalloons(base: { c: HTMLCanvasElement; tall: number; foot: number }, l: BadgeLook): { c: HTMLCanvasElement; tall: number; foot: number } {
  const B = base.c, UP = Math.round(B.width * 0.95);
  const c = document.createElement('canvas');
  c.width = B.width; c.height = B.height + UP;
  const g = c.getContext('2d')!;
  g.drawImage(B, 0, UP);
  const hex = (n: number) => `#${(n & 0xffffff).toString(16).padStart(6, '0')}`;
  const cols = [hex(l.primary), hex(l.accent), '#f2c14e'];
  const tieX = c.width / 2, tieY = UP + 6;
  const spots: [number, number][] = [[c.width * 0.3, UP * 0.36], [c.width * 0.68, UP * 0.3], [c.width * 0.5, UP * 0.16]];
  spots.forEach(([x, y], k) => {
    const r = c.width * 0.17;
    g.strokeStyle = 'rgba(40,40,40,0.75)'; g.lineWidth = 2;
    g.beginPath(); g.moveTo(tieX, tieY); g.quadraticCurveTo((x + tieX) / 2 + 6, (y + tieY) / 2 + 10, x, y + r * 1.15); g.stroke();
    g.fillStyle = 'rgba(20,28,34,0.45)';
    g.beginPath(); g.ellipse(x, y, r + 2, r * 1.2 + 2, 0, 0, Math.PI * 2); g.fill();
    g.fillStyle = cols[k];
    g.beginPath(); g.ellipse(x, y, r, r * 1.2, 0, 0, Math.PI * 2); g.fill();
    g.fillStyle = 'rgba(255,255,255,0.45)';
    g.beginPath(); g.ellipse(x - r * 0.35, y - r * 0.45, r * 0.22, r * 0.32, -0.5, 0, Math.PI * 2); g.fill();
    g.fillStyle = cols[k];
    g.beginPath(); g.moveTo(x - 5, y + r * 1.2 + 6); g.lineTo(x + 5, y + r * 1.2 + 6); g.lineTo(x, y + r * 1.2 - 2); g.fill();
  });
  return { c, tall: base.tall * c.height / B.height, foot: base.foot * B.height / c.height };
}

function shieldPath(g: CanvasRenderingContext2D, x: number, y: number, w: number, h: number): void {
  g.beginPath();
  g.moveTo(x, y + h * 0.08);
  g.quadraticCurveTo(x + w * 0.5, y - h * 0.04, x + w, y + h * 0.08);
  g.lineTo(x + w, y + h * 0.46);
  g.bezierCurveTo(x + w, y + h * 0.74, x + w * 0.72, y + h * 0.9, x + w * 0.5, y + h);
  g.bezierCurveTo(x + w * 0.28, y + h * 0.9, x, y + h * 0.74, x, y + h * 0.46);
  g.closePath();
}

/** A dark ribbon with `n` gold stars on it, centred at (cx, cy): an HQ's grade under its shield. */
function starRibbon(g: CanvasRenderingContext2D, cx: number, cy: number, n: number): void {
  const R = 7.5, gap = 16, w = n * gap + 10;
  g.fillStyle = 'rgba(20,28,34,0.72)';
  g.beginPath();
  g.roundRect(cx - w / 2, cy - 12, w, 24, 12);
  g.fill();
  g.fillStyle = '#ffc83d';
  g.strokeStyle = '#7a5600';
  g.lineWidth = 1.2;
  for (let k = 0; k < n; k++) {
    const x = cx + (k - (n - 1) / 2) * gap;
    g.beginPath();
    for (let i = 0; i < 10; i++) {
      const a = -Math.PI / 2 + (i * Math.PI) / 5, r = i % 2 ? R * 0.45 : R;
      if (i) g.lineTo(x + Math.cos(a) * r, cy + Math.sin(a) * r); else g.moveTo(x + Math.cos(a) * r, cy + Math.sin(a) * r);
    }
    g.closePath();
    g.fill();
    g.stroke();
  }
}

/** The badge's picture: the logo in the body colour on the accent, ringed in the body colour, on a white rim. */
function paintBadge(l: BadgeLook, shape: BadgeShape): THREE.CanvasTexture {
  const painted = paintCanvas(l, shape);
  const { c, tall, foot } = l.balloons ? withBalloons({ c: painted.c, tall: painted.tall, foot: painted.foot ?? 0 }, l) : painted;
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  t.userData.aspect = c.width / c.height;
  // the ribbon hangs below: the shield keeps its size and the picture grows by the ribbon
  t.userData.tall = tall;
  // a pass hanging under the badge hangs below the point it is put at, so the badge itself stays where it was
  t.userData.foot = foot ?? 0;
  return t;
}

const urls = new Map<string, string>();
/** The same badge as an image for the HUD (the inspector's corner): a data URL, painted once per look. */
export function badgeUrl(l: BadgeLook, shape: BadgeShape = 'shield'): string {
  const k = lookKey(l, shape);
  let u = urls.get(k);
  if (!u) {
    if (urls.size > 256) urls.clear();
    urls.set(k, (u = paintCanvas(l, shape).c.toDataURL()));
  }
  return u;
}

/**
 * The badge with its Passport treats (game/treats.ts): a visa emblem's frame round it, and a lanyard pass hanging
 * under it. A badge without either is the plain one, untouched. `tall` is the whole picture's height over the
 * badge's own, as the sprite is scaled by it.
 */
function paintCanvas(l: BadgeLook, shape: BadgeShape): { c: HTMLCanvasElement; tall: number; foot?: number } {
  const em = emblemOf(l.frame);
  if (!em && !l.pass) return paintPlain(l, shape);
  const base = paintPlain(l, shape);
  const BW = base.c.width, BH = base.c.height, H0 = BH / base.tall;
  const M = em ? 14 : 0, TOP = em ? 22 : 0, PASS = l.pass ? 64 : 0;
  const c = document.createElement('canvas');
  c.width = BW + M * 2; c.height = BH + M + TOP + PASS;
  const g = c.getContext('2d')!;
  const ox = M, oy = M + TOP;
  if (em) {
    // the frame: the badge's own outline grown by the margin, in the emblem's colour, with a gold bead rim
    const outer = (grow: number) => {
      if (shape === 'shield') shieldPath(g, ox + 3 - grow, oy + 3 - grow, BW - 6 + grow * 2, H0 - 6 + grow * 2);
      else { g.beginPath(); g.arc(ox + BW / 2, oy + H0 / 2, BW / 2 - 3 + grow, 0, Math.PI * 2); }
    };
    outer(M); g.fillStyle = 'rgba(20,28,34,0.5)'; g.fill();
    outer(M - 2); g.fillStyle = em.deep; g.fill();
    outer(M - 4); g.fillStyle = em.colour; g.fill();
    // gold beads round it, as on a medal's rim
    g.fillStyle = '#e8c55a';
    const R = (shape === 'shield' ? Math.max(BW, H0) : BW) / 2 - 3 + M / 2;
    for (let i = 0; i < 24; i++) {
      const a = (i / 24) * Math.PI * 2;
      const x = ox + BW / 2 + Math.cos(a) * (shape === 'shield' ? (BW / 2 - 3 + M / 2) : R);
      const y = oy + H0 / 2 + Math.sin(a) * (shape === 'shield' ? (H0 / 2 - 3 + M / 2) : R);
      g.beginPath(); g.arc(x, y, 2.1, 0, Math.PI * 2); g.fill();
    }
  }
  g.drawImage(base.c, ox, oy);
  if (em) {
    // the group's medallion on top
    const mx = ox + BW / 2, my = TOP + 8;
    g.beginPath(); g.arc(mx, my + 6, 21, 0, Math.PI * 2); g.fillStyle = 'rgba(20,28,34,0.55)'; g.fill();
    g.beginPath(); g.arc(mx, my + 6, 19, 0, Math.PI * 2); g.fillStyle = '#e8c55a'; g.fill();
    g.beginPath(); g.arc(mx, my + 6, 15, 0, Math.PI * 2); g.fillStyle = em.colour; g.fill();
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.font = '20px "Segoe UI Emoji","Noto Color Emoji","Segoe UI Symbol",sans-serif';
    g.fillStyle = '#fff';
    g.fillText(em.glyph, mx, my + 7);
  }
  if (l.pass) {
    // a lanyard from either shoulder of the badge's foot to a little pass
    const top = oy + H0 * (shape === 'shield' ? 0.9 : 0.86), cx = ox + BW / 2;
    const pw = 44, ph = 34, py = c.height - ph - 3;
    g.strokeStyle = '#d33a3a'; g.lineWidth = 4; g.lineCap = 'round';
    g.beginPath(); g.moveTo(cx - 26, top - 6); g.lineTo(cx - 6, py + 2); g.moveTo(cx + 26, top - 6); g.lineTo(cx + 6, py + 2); g.stroke();
    g.fillStyle = '#8a8f95'; g.fillRect(cx - 5, py - 3, 10, 7);
    g.fillStyle = 'rgba(20,28,34,0.55)';
    g.beginPath(); g.roundRect(cx - pw / 2 - 2, py - 1, pw + 4, ph + 3, 6); g.fill();
    g.fillStyle = '#ffffff';
    g.beginPath(); g.roundRect(cx - pw / 2, py, pw, ph, 5); g.fill();
    g.fillStyle = '#d33a3a';
    g.beginPath(); g.roundRect(cx - pw / 2, py, pw, 11, [5, 5, 0, 0]); g.fill();
    g.fillStyle = '#ffffff'; g.font = '700 8px "Segoe UI",sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText('VIP', cx, py + 6);
    g.font = '15px "Segoe UI Emoji","Noto Color Emoji",sans-serif';
    g.fillText('🎟️', cx, py + 22);
  }
  return { c, tall: c.height / H0, foot: PASS ? (PASS - 8) / c.height : 0 };
}

function paintPlain(l: BadgeLook, shape: BadgeShape): { c: HTMLCanvasElement; tall: number } {
  const W = 128, H = shape === 'shield' ? 150 : 128;
  const stars = shape === 'shield' ? Math.max(0, Math.min(7, l.stars ?? 0)) : 0;
  const RIB = stars ? 30 : 0;
  const c = document.createElement('canvas');
  c.width = W; c.height = H + RIB;
  const g = c.getContext('2d')!;
  const p = badgePaint(l.primary, l.accent);
  const ring = shape === 'shield' ? 13 : 12;
  const outline = (inset: number) => {
    if (shape === 'shield') shieldPath(g, inset, inset, W - inset * 2, H - inset * 2);
    else { g.beginPath(); g.arc(W / 2, H / 2, W / 2 - inset, 0, Math.PI * 2); }
  };
  // a soft dark edge and a white rim, so it reads on grass, roofs and sea alike
  outline(3); g.fillStyle = 'rgba(20,28,34,0.55)'; g.fill();
  outline(6); g.fillStyle = '#ffffff'; g.fill();
  outline(10); g.fillStyle = p.ring; g.fill();
  outline(10 + ring); g.fillStyle = p.disc; g.fill();
  // a glint across the top, as on an enamel badge
  g.save();
  outline(10 + ring); g.clip();
  const sheen = g.createLinearGradient(0, 0, 0, H);
  sheen.addColorStop(0, 'rgba(255,255,255,0.28)');
  sheen.addColorStop(0.45, 'rgba(255,255,255,0)');
  g.fillStyle = sheen; g.fillRect(0, 0, W, H);
  g.restore();
  g.fillStyle = p.glyph;
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.font = `700 ${shape === 'shield' ? 64 : 60}px "Segoe UI Symbol","Noto Sans Symbols 2","Segoe UI",sans-serif`;
  g.fillText(l.logo, W / 2, shape === 'shield' ? H * 0.46 : H / 2 + 3);
  if (stars) starRibbon(g, W / 2, H + RIB / 2 - 2, stars);
  return { c, tall: (H + RIB) / H };
}

export class FleetBadges {
  private group = new THREE.Group();
  private pool: THREE.Sprite[] = [];
  private tex = new Map<string, THREE.CanvasTexture>();
  private n = 0;
  private fx = 0; private fz = 0;
  private t = 0;
  /** World units a sprite scale of 1 covers per pixel of screen, for this frame's camera. */
  private perPx = 0;
  /** Off in the title reel and wherever the player has hidden them. */
  enabled = true;

  constructor(scene: THREE.Scene) {
    this.group.renderOrder = 6;
    scene.add(this.group);
  }

  private texture(l: BadgeLook, s: BadgeShape): THREE.CanvasTexture {
    const k = lookKey(l, s);
    let t = this.tex.get(k);
    if (!t) {
      // liveries don't change often; a long game shouldn't hoard every one it ever painted
      if (this.tex.size > 64) { for (const x of this.tex.values()) x.dispose(); this.tex.clear(); }
      this.tex.set(k, t = paintBadge(l, s));
    }
    return t;
  }

  /** Start a frame's badges; `fx, fz` is what the camera follows, in world tiles. */
  begin(camera: THREE.PerspectiveCamera, fx: number, fz: number, dt: number): void {
    this.n = 0;
    this.perPx = (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2)) / Math.max(1, window.innerHeight);
    this.fx = fx; this.fz = fz;
    this.t += dt;
  }

  /** One badge `size` pixels high whose bottom hovers at (x, y, z), in world tiles; `seed` staggers its bob. */
  put(l: BadgeLook, x: number, y: number, z: number, size: number, shape: BadgeShape = 'disc', seed = 0): void {
    if (!this.enabled || this.n >= MAX) return;
    const d = Math.hypot(x - this.fx, z - this.fz);
    if (d > FAR) return;
    let s = this.pool[this.n];
    if (!s) {
      s = new THREE.Sprite(new THREE.SpriteMaterial({ transparent: true, depthTest: false, depthWrite: false, toneMapped: false, sizeAttenuation: false }));
      s.center.set(0.5, 0);
      s.renderOrder = 6;
      // off screen, not drawn (its point is tested: a badge is a few pixels round it)
      s.frustumCulled = true;
      this.pool.push(s);
      this.group.add(s);
    }
    this.n++;
    const t = this.texture(l, shape);
    const m = s.material;
    // a picture for a picture needs no new shader, only one where there was none (11 Nov 2026 perf audit: the pool
    // is filled in order each frame, so one vehicle leaving shifted every later badge's picture, and each change
    // marked its material for a program lookup)
    if (m.map !== t) { if (!m.map) m.needsUpdate = true; m.map = t; s.center.set(0.5, (t.userData.foot as number | undefined) ?? 0); }
    m.opacity = d < NEAR ? 1 : 1 - (d - NEAR) / (FAR - NEAR);
    const aspect = t.userData.aspect as number;
    const h = size * this.perPx * ((t.userData.tall as number | undefined) ?? 1);
    s.scale.set(h * aspect, h, 1);
    s.position.set(x, y + 0.04 + Math.sin(this.t * 2.2 + seed * 1.7) * 0.04, z);
    s.visible = true;
  }

  /** Hide whatever this frame didn't use. */
  end(): void {
    for (let i = this.n; i < this.pool.length; i++) this.pool[i].visible = false;
  }

  clear(): void { this.n = 0; this.end(); }
}
