/**
 * Solid vehicles everywhere, ON TRIAL (the user, 11 Nov 2026): what a race meeting does between its own cars
 * (game/circuitRace.ts contact), between every vehicle near the player: the ridden one, the traffic, hired and
 * rival drivers, parked fleet units, trains and the airports' aircraft. Off, nothing here runs and vehicles pass
 * through each other as they always have.
 *
 * The switch is SOLID.on: the cheats menu's "Solid vehicles" button or `pr.solid = true` in the console (both only
 * where the cheats are allowed), kept in this browser's localStorage. It is a client's own trial: other players'
 * vehicles are not solid, and nothing is sent to the server.
 *
 * Each body is a box (halfSize) at a height. Two that overlap, on the ground plan and in height, are pushed apart
 * along the axis they overlap least on, the lighter one further, and trade speed along it by weight in a soft
 * knock. A body with no weight to give (`inv` 0: a train, anything parked, a scripted airliner) is not moved at
 * all, and everything else gets out of its way. An aircraft meets a road vehicle, a boat or a train only while it
 * is on the ground; two aircraft meet in the air when they are at the same height.
 */
const KEY = 'tinyfleet.solid';

function stored(): boolean {
  try { return globalThis.localStorage?.getItem(KEY) === '1'; } catch { return false; }
}

export const SOLID = { on: stored() };

export function setSolid(on: boolean): void {
  SOLID.on = on;
  try { globalThis.localStorage?.setItem(KEY, on ? '1' : '0'); } catch { /* private window: the switch lasts the visit */ }
}

/** How springy a knock is: 0 dead, 1 a perfect bounce (the race meetings' own figure). */
const BUMP = 0.25;

export interface Body {
  /** Whose it is, for the caller to write the result back to. */
  ref: unknown;
  /** 0 the player's, 1 a traffic agent, 2 anything that is never moved. */
  who: number;
  /** Middle of the box in world tiles, the height of its underside and how tall it stands, in world units. */
  x: number; z: number; y: number; tall: number;
  heading: number; hl: number; hw: number;
  /** Its velocity over the ground, tiles a second. */
  vx: number; vz: number;
  /** One over its weight; 0 is never moved. */
  inv: number;
  air: boolean;
  /** An aircraft off the ground: it meets only other aircraft. */
  aloft: boolean;
  /** A CPU driver going through whatever is in its way (traffic's last resort): it meets only the player. */
  ghost: boolean;
  /** Bodies of one group (a train's cars) never meet each other; 0 is no group. */
  group: number;
  /** The answer: how far to move it, the change in its velocity, and the hardest knock it took (closing speed,
   *  the normal back toward it, and where). */
  dx: number; dz: number; kx: number; kz: number;
  hit: number; nx: number; nz: number; px: number; pz: number;
}

const pool: Body[] = [];
let used = 0;

/** Start a frame's list. */
export function beginBodies(): void { used = 0; }

/** The next body of the frame, blank, from a pool (nothing is made while driving once it has grown). */
export function addBody(): Body {
  let b = pool[used];
  if (!b) {
    b = { ref: null, who: 2, x: 0, z: 0, y: 0, tall: 0.4, heading: 0, hl: 0.4, hw: 0.3, vx: 0, vz: 0, inv: 0, air: false, aloft: false, ghost: false, group: 0, dx: 0, dz: 0, kx: 0, kz: 0, hit: 0, nx: 0, nz: 0, px: 0, pz: 0 };
    pool.push(b);
  }
  used++;
  b.ref = null; b.who = 2; b.y = 0; b.tall = 0.4; b.vx = 0; b.vz = 0; b.inv = 0; b.air = false; b.aloft = false; b.ghost = false; b.group = 0;
  b.dx = 0; b.dz = 0; b.kx = 0; b.kz = 0; b.hit = 0; b.nx = 0; b.nz = 0; b.px = 0; b.pz = 0;
  return b;
}

/** Take the last body back (it turned out not to count). */
export function dropBody(): void { used--; }

/** The frame's bodies, pushed apart and knocked: read each one's dx, dz, kx, kz and hit. Returns how many there are. */
export function solveBodies(): number {
  const n = used;
  for (let i = 0; i < n; i++) {
    const a = pool[i];
    const ra = Math.hypot(a.hl, a.hw);
    for (let j = i + 1; j < n; j++) {
      const b = pool[j];
      const inv = a.inv + b.inv;
      if (inv === 0) continue;
      if (a.group && a.group === b.group) continue;
      if ((a.ghost || b.ghost) && a.who !== 0 && b.who !== 0) continue;
      if (a.air !== b.air ? (a.air ? a.aloft : b.aloft) : false) continue;
      const dx = b.x - a.x, dz = b.z - a.z, reach = ra + Math.hypot(b.hl, b.hw);
      if (dx * dx + dz * dz > reach * reach) continue;
      if (a.y > b.y + b.tall || b.y > a.y + a.tall) continue;
      // separating axes: each box's along and across; the overlap on the one it's least on
      const as = Math.sin(a.heading), ac = Math.cos(a.heading), bs = Math.sin(b.heading), bc = Math.cos(b.heading);
      let best = Infinity, nx = 0, nz = 0;
      for (let k = 0; k < 4; k++) {
        const ux = k === 0 ? as : k === 1 ? ac : k === 2 ? bs : bc, uz = k === 0 ? ac : k === 1 ? -as : k === 2 ? bc : -bs;
        const pa = a.hl * Math.abs(ux * as + uz * ac) + a.hw * Math.abs(ux * ac - uz * as);
        const pb = b.hl * Math.abs(ux * bs + uz * bc) + b.hw * Math.abs(ux * bc - uz * bs);
        const c = dx * ux + dz * uz, over = pa + pb - Math.abs(c);
        if (over <= 0) { best = -1; break; }
        if (over < best) { best = over; nx = c < 0 ? -ux : ux; nz = c < 0 ? -uz : uz; }
      }
      if (best <= 0) continue;
      // apart along the normal from a to b, the lighter one further
      const sa = a.inv / inv, sb = b.inv / inv;
      a.x -= nx * best * sa; a.z -= nz * best * sa; a.dx -= nx * best * sa; a.dz -= nz * best * sa;
      b.x += nx * best * sb; b.z += nz * best * sb; b.dx += nx * best * sb; b.dz += nz * best * sb;
      // the knock, shared by weight, with a little bounce
      const closing = (a.vx - b.vx) * nx + (a.vz - b.vz) * nz;
      if (closing <= 0) continue;
      const jn = closing * (1 + BUMP) / inv;
      const ka = jn * a.inv, kb = jn * b.inv;
      a.vx -= nx * ka; a.vz -= nz * ka; a.kx -= nx * ka; a.kz -= nz * ka;
      b.vx += nx * kb; b.vz += nz * kb; b.kx += nx * kb; b.kz += nz * kb;
      const cx = (a.x + b.x) / 2, cz = (a.z + b.z) / 2;
      if (closing > a.hit) { a.hit = closing; a.nx = -nx; a.nz = -nz; a.px = cx; a.pz = cz; }
      if (closing > b.hit) { b.hit = closing; b.nx = nx; b.nz = nz; b.px = cx; b.pz = cz; }
    }
  }
  return n;
}

/** The i-th body of the frame, after solveBodies. */
export const bodyAt = (i: number): Body => pool[i];
