/**
 * Field profiling for the play reports (net/perf.ts, server/analytics.ts, the /dev page), 6 Nov 2026: what makes
 * the frame rate bad or spiky on players' own machines, every combination of GPU, browser, screen and power the
 * developer can never test on. Measured on every frame of play and sent as a few kilobytes a report:
 *
 * - where each frame's time goes: the game's own parts (main.ts lap(): traffic, chunk streaming, render…), the
 *   whole of step() (CPU), and, where the browser has the timer, the GPU's time for the render;
 * - every freeze (a frame of 250 ms or more) with what the frame before it did: its CPU time and slowest parts,
 *   shader programs built, chunks built, textures added, the JS heap, the camera and the window up; a freeze with
 *   little CPU time came from outside the game's code (the GPU, garbage collection, the browser);
 * - every 15 visible seconds: frame-time percentiles, CPU/GPU, draw calls, triangles, programs, heap, pixels
 *   drawn, quality level, frame cap, the camera mode, the vehicle kind, the speed, night, chunks loaded, power;
 * - the browser's own long-frame reports (long-animation-frame, Chrome 123+): which script, which DOM
 *   layout, how long, for the stalls the game's laps can't see (DOM, style, input handlers);
 * - the machine once: browser and OS versions, CPU architecture, a CPU speed score, the screen's refresh rate,
 *   the WebGL limits, the timer, context losses, resizes and pixel-ratio changes, battery and CPU pressure.
 *
 * Since 11 Nov 2026 (that day's audit of this data, which had to guess at all of these):
 *
 * - the named jobs that ran (net/perfJobs.ts: a reach flood, a route search, a save), over the visit and inside
 *   each freeze, with the last thing the player did before it (a key, a click on what) and the browser's own long
 *   frame for it, so a freeze "outside the game" says what was going on;
 * - whether the page had the focus (a browser holds an unfocused or covered page to a frame a second);
 * - once a window, the scene counted (objects, visible ones, counties drawn and held, spare chunks, geometries by
 *   who holds them) and the simulation's load (traffic, pedestrians, route searches), so a cost has a size beside it;
 * - the whole visit thinned to a sample every few minutes, and every freeze counted by cause, so a long visit's
 *   middle isn't lost to the first-and-latest lists;
 * - the CPU score taken again every few minutes (one machine scored 3.8 to 13), and the experiments this machine
 *   is in (perfJobs.ts arm()).
 *
 * Nothing personal: no names, nothing typed. All of it is wrapped so a browser without an API just leaves it out.
 */
import { hitchCause } from './hitchCause';
import { armsReport, countsReport, jobStat, jobsBetween, jobsReport } from './perfJobs';

/**
 * One frame's game-side cost (main.ts, after step()). parts: lap name → ms this frame; steps: chunk-building
 * steps → ms this frame (render/stream.ts FRAME_STEPS). Both are the caller's, cleared next frame: copied here.
 */
export interface FrameCost {
  cpu: number; parts: Map<string, number>; steps: Map<string, number>; calls: number; tris: number;
  programs: number; programsMade: number; chunksMade: number;
  /** Textures held, and added this frame; geometries held, and added this frame (sent to the GPU on first draw). */
  textures: number; texMade: number; geometries: number; geoMade: number;
}

/** What the game is doing, for a window's or a freeze's context (main.ts perfLook). */
export interface PerfLook {
  /** drive / overview / follow / photo / map / region. */
  cam: string;
  /** land / water / air / rail (the vehicle in hand). */
  kind: string;
  speed: number; night: boolean; chunks: number; units: number; cell: string;
  /** The window or tool up, if any. */
  panel: string | null;
  /** The frame cap (0: none). */
  cap: number;
}

/**
 * The scene and the simulation counted, once a window (main.ts perfCensus): too slow for every frame, cheap
 * every 15 seconds. obj/vis: objects in the scene, and those a draw would visit (visible, with visible parents).
 * drawn/light: counties drawn, and held without being drawn (far fleets). spare: chunks kept off the scene.
 * agents/peds: traffic and people being moved. dock: the fleet dock's own draws since the last count (another
 * renderer, so not in the frame's count; the window reports them per frame). own: geometries held, by who holds them, the most first.
 */
export interface PerfCensus {
  obj: number; vis: number; drawn: number; light: number; spare: number; agents: number; peds: number; dock: number;
  own: [string, number][];
}

/** A freeze: a frame of FREEZE_MS or more. */
export interface Hitch {
  /** Visible seconds into play; ms since the page loaded (to join with long frames); the frame's length. */
  t: number; at: number; ms: number;
  /** The frame before it: step()'s CPU ms, shader programs built, chunks built, textures added, its slowest parts. */
  cpu: number | null; prog: number; chunks: number; tex: number; parts: [string, number][];
  /** JS heap MB then (Chrome), a menu up, the camera mode and the window up. */
  heap: number | null; menu: 0 | 1; cam: string; panel: string | null;
  /**
   * Since 7 Nov 2026: the frame before's two slowest chunk-building steps (ms); geometries it added; and how many
   * MB the JS heap shrank across the freeze (a big drop is the garbage collector, a stall outside the game's code).
   */
  steps?: [string, number][]; geo?: number; gc?: number | null;
  /**
   * Since 11 Nov 2026: the last thing the player did before it (`key KeyG`, `click #dock`) and how many ms before
   * it began; the named jobs that ran inside it (ms); whether the page had the focus; and the browser's own long
   * frame over it, with its slowest script (joined when the report is made: the browser tells of one late).
   */
  act?: string; actMs?: number; jobs?: [string, number][]; foc?: 0 | 1;
  lf?: { ms: number; render: number; fn: string; src: string; pos: number; inv: string; sms: number; forced: number };
}

/** 15 visible seconds. */
export interface PerfWindow {
  t: number; fps: number;
  /** Frame intervals ms: median, 95th percentile, longest. */
  p50: number; p95: number; max: number;
  /** step()'s CPU ms per frame, mean and 95th percentile; the GPU's ms per sampled render (null: no timer). */
  cpu: number; cpu95: number; gpu: number | null;
  /** Per frame: draw calls, triangles (thousands); programs, textures, geometries held; JS heap MB; pixels drawn (MP). */
  calls: number; tris: number; prog: number; tex: number; geo: number; heap: number | null; px: number;
  level: string; cap: number;
  /** Share of frames with a menu up. */
  menu: number;
  cam: string; kind: string; spd: number; night: 0 | 1; chunks: number; units: number; cell: string;
  /** On mains (1), on battery (0), unknown (null); CPU pressure state (Chrome 125+); fullscreen. */
  batt: 0 | 1 | null; press: string | null; fs: 0 | 1;
  /** The four slowest parts, ms per frame. */
  parts: [string, number][];
  /** Since 11 Nov 2026: the census (PerfCensus), route searches run in the window and their ms, the share of frames with the focus. */
  obj?: number; vis?: number; drawn?: number; light?: number; spare?: number; agents?: number; peds?: number; dock?: number;
  own?: [string, number][];
  routes?: number; routeMs?: number; foc?: number;
}

/** A long animation frame the browser reported (Chrome 123+), with its slowest scripts. */
export interface Loaf {
  t: number; at: number; ms: number; block: number;
  /** ms spent in style and layout, and in rendering (after the scripts). */
  layout: number; render: number;
  scripts: { inv: string; fn: string; src: string; pos: number; ms: number; forced: number }[];
}

export interface PerfEnv {
  browser: string; os: string; arch: string | null; model: string | null;
  /** Build version (build.json), null in a dev server. */
  build: string | null;
  /** ms for a fixed bit of JS (lower is faster), the best of three. */
  cpuScore: number | null;
  /** The screen's refresh rate, worked out from the shortest steady frame intervals. */
  refreshHz: number | null;
  /** parallel: KHR_parallel_shader_compile (shaders build off the main thread; without it each one stalls a frame). */
  webgl: { samples: number; precision: string; ext: number; timer: boolean; parallel: boolean; buffer: [number, number] } | null;
  battery: { charging: boolean; level: number } | null;
  heapLimit: number | null;
  loafApi: boolean;
}

export interface FieldReport {
  env: PerfEnv;
  /** Frame intervals over the visit: percentiles, and a 1 ms histogram ({ms: frames}; 100 = 100 ms or more). */
  iv: { p10: number; p50: number; p90: number; p95: number; p99: number; bins: Record<string, number> };
  cpu: { mean: number; p95: number };
  gpu: { mean: number; n: number } | null;
  /** Every part's mean ms per frame over the visit, slowest first. */
  parts: [string, number][];
  hitches: Hitch[];
  windows: PerfWindow[];
  loaf: Loaf[];
  ctx: { lost: number; restored: number; at: number[] };
  resizes: number; dprChanges: number;
  /** Named jobs over the visit: [name, runs, total ms, longest ms]; and things counted: [name, count]. */
  jobs: [string, number, number, number][]; counts: [string, number][];
  /** Every freeze of the visit by cause (net/hitchCause.ts): [cause, freezes, total ms], the list above keeps only some. */
  tally: [string, number, number][];
  /**
   * The whole visit, a sample every SERIES_WINDOWS windows (halved, and the spacing doubled, when it fills):
   * [visible s, fps, cpu ms, heap MB, geometries, textures, draw calls, objects, fleet units, spare chunks, traffic agents].
   */
  series: number[][];
  /** The CPU score through the visit: [visible s, ms]. */
  scores: [number, number][];
  /** The experiments this machine is in (net/perfJobs.ts arm()). */
  arms: Record<string, string>;
}

const FREEZE_MS = 250, HITCHES_EARLY = 15, HITCHES_RECENT = 25;
const WINDOWS_EARLY = 4, WINDOWS_RECENT = 24, LOAF_EARLY = 6, LOAF_RECENT = 10, LOAF_MS = 150;
/** The visit's thinned series: a sample every so many windows (12 = 3 minutes), at most so many kept. */
const SERIES_WINDOWS = 12, SERIES_MAX = 64;
/** The browser's long frames kept slim for joining to freezes; the CPU score taken again this often, so many kept. */
const LOAF_JOIN = 48, SCORE_EVERY_S = 300, SCORES_MAX = 16;
const round = (v: number, d = 1): number => Math.round(v * 10 ** d) / 10 ** d;
const heapMb = (): number | null => {
  const m = (performance as Performance & { memory?: { usedJSHeapSize: number } }).memory;
  return m ? Math.round(m.usedJSHeapSize / 1048576) : null;
};
const pct = (sorted: ArrayLike<number>, n: number, p: number): number => (n ? sorted[Math.min(n - 1, Math.floor(p * n))] : 0);
/** Keep the first `early` and the latest `recent`. */
function keep<T>(early: T[], recent: T[], v: T, ne: number, nr: number): void {
  if (early.length < ne) early.push(v);
  else { recent.push(v); if (recent.length > nr) recent.shift(); }
}
const top = (m: Map<string, number>, div: number, n: number): [string, number][] =>
  [...m].map(([k, v]) => [k, round(v / Math.max(1, div), 2)] as [string, number]).filter((e) => e[1] > 0).sort((a, b) => b[1] - a[1]).slice(0, n);

function browserOf(ua: string, brands?: { brand: string; version: string }[]): string {
  const b = brands?.find((x) => /Edge|Opera|Chrome|Brave|Vivaldi|Yandex/i.test(x.brand) && !/Not.A.Brand|Chromium/i.test(x.brand)) ?? brands?.find((x) => /Chromium/.test(x.brand));
  if (b) return `${b.brand.replace('Google ', '').replace('Microsoft ', '')} ${b.version.split('.')[0]}`;
  const m = /(Edg|OPR|Firefox|Chrome|Version)\/(\d+)/.exec(ua);
  if (!m) return 'other';
  const name = m[1] === 'Edg' ? 'Edge' : m[1] === 'OPR' ? 'Opera' : m[1] === 'Version' ? (/Safari/.test(ua) ? 'Safari' : 'other') : m[1];
  return `${name} ${m[2]}`;
}
function osOf(ua: string, platformVersion?: string): string {
  if (/Windows/.test(ua)) return platformVersion ? (Number(platformVersion.split('.')[0]) >= 13 ? 'Windows 11' : 'Windows 10') : 'Windows';
  if (/Mac OS X|Macintosh/.test(ua)) return platformVersion ? `macOS ${platformVersion.split('.').slice(0, 2).join('.')}` : 'macOS';
  if (/CrOS/.test(ua)) return 'ChromeOS';
  if (/Android/.test(ua)) return 'Android';
  if (/iPhone|iPad/.test(ua)) return 'iOS';
  if (/Linux/.test(ua)) return 'Linux';
  return 'other';
}

interface TimerExt { TIME_ELAPSED_EXT: number; GPU_DISJOINT_EXT: number }

export class FieldPerf {
  private env: PerfEnv;
  private look: () => PerfLook | null = () => null;
  private census: () => PerfCensus | null = () => null;
  /** The last thing the player did (a key or a click, never what was typed) and when. */
  private act = '';
  private actAt = 0;
  /** Long frames from the browser, slim, for the freezes they were (it reports one after the frame has ended). */
  private loafJoin: NonNullable<Hitch['lf']>[] = [];
  private loafJoinAt: [number, number][] = [];
  private tally = new Map<string, [number, number]>();
  private series: number[][] = [];
  private seriesEvery = SERIES_WINDOWS;
  private sAcc = { n: 0, fps: 0, cpu: 0, calls: 0 };
  private scores: [number, number][] = [];
  private scoreAt = 0;
  private scoring = false;
  private wFocus = 0;
  private wRoutes: [number, number] = [0, 0];
  private playAt: number | null = null;
  private visible = 0;
  private last: FrameCost | null = null;
  /** The last frame's parts and steps, copied (the caller's maps are cleared every frame), and its heap. */
  private lastParts = new Map<string, number>();
  private lastSteps = new Map<string, number>();
  private lastHeap: number | null = null;
  // the visit
  private bins = new Uint32Array(101);
  private frames = 0;
  private cpuSum = 0;
  private cpuBins = new Uint32Array(101);
  private costFrames = 0;
  private parts = new Map<string, number>();
  private gpuSum = 0;
  private gpuN = 0;
  private hitchesEarly: Hitch[] = [];
  private hitchesRecent: Hitch[] = [];
  private winEarly: PerfWindow[] = [];
  private winRecent: PerfWindow[] = [];
  private loafEarly: Loaf[] = [];
  private loafRecent: Loaf[] = [];
  private ctx = { lost: 0, restored: 0, at: [] as number[] };
  private resizes = 0;
  private dprChanges = 0;
  private dpr = devicePixelRatio;
  // the window
  private wIv = new Float32Array(8192);
  private wN = 0;
  private wCpu = new Float32Array(8192);
  private wCostN = 0;
  private wParts = new Map<string, number>();
  private wCalls = 0;
  private wTris = 0;
  private wMenu = 0;
  private wGpu = 0;
  private wGpuN = 0;
  private wPress: string | null = null;
  // the GPU timer (EXT_disjoint_timer_query_webgl2), one query in flight at a time, sampled twice a second
  private timer: { gl: WebGL2RenderingContext; ext: TimerExt; q: WebGLQuery | null; open: boolean; at: number } | null = null;
  private battery: { charging: boolean; level: number } | null = null;
  private pressure: string | null = null;

  constructor(private gl: () => WebGLRenderingContext | WebGL2RenderingContext | null) {
    const ua = navigator.userAgent;
    const nav = navigator as Navigator & { userAgentData?: { brands?: { brand: string; version: string }[]; getHighEntropyValues?: (h: string[]) => Promise<Record<string, unknown>> } };
    const heapLimit = (performance as Performance & { memory?: { jsHeapSizeLimit: number } }).memory?.jsHeapSizeLimit;
    this.env = {
      browser: browserOf(ua, nav.userAgentData?.brands), os: osOf(ua), arch: null, model: null, build: null, cpuScore: null, refreshHz: null,
      webgl: null, battery: null, heapLimit: heapLimit ? Math.round(heapLimit / 1048576) : null, loafApi: false,
    };
    try {
      void nav.userAgentData?.getHighEntropyValues?.(['platformVersion', 'architecture', 'bitness', 'model', 'fullVersionList']).then((h) => {
        const list = h.fullVersionList as { brand: string; version: string }[] | undefined;
        this.env.browser = browserOf(ua, list ?? nav.userAgentData?.brands);
        this.env.os = osOf(ua, typeof h.platformVersion === 'string' ? h.platformVersion : undefined);
        this.env.arch = [h.architecture, h.bitness].filter(Boolean).join('-') || null;
        this.env.model = typeof h.model === 'string' && h.model ? h.model.slice(0, 40) : null;
      }).catch(() => {});
    } catch { /* not offered */ }
    try {
      void fetch(new URL('build.json', location.href).toString(), { cache: 'no-store' }).then((r) => (r.ok ? r.json() : null))
        .then((b: { version?: unknown } | null) => { if (b && typeof b.version === 'string') this.env.build = b.version.slice(0, 20); }).catch(() => {});
    } catch { /* no fetch */ }
    try {
      const nb = navigator as Navigator & { getBattery?: () => Promise<{ charging: boolean; level: number; addEventListener: (t: string, f: () => void) => void }> };
      void nb.getBattery?.().then((b) => {
        const read = () => { this.battery = { charging: b.charging, level: round(b.level, 2) }; };
        read();
        this.env.battery = this.battery;
        b.addEventListener('chargingchange', read);
        b.addEventListener('levelchange', read);
      }).catch(() => {});
    } catch { /* not offered */ }
    try {
      const PO = (window as unknown as { PressureObserver?: new (cb: (r: { state: string }[]) => void) => { observe: (s: string, o?: unknown) => Promise<void> } }).PressureObserver;
      if (PO) void new PO((recs) => { const s = recs[recs.length - 1]?.state; if (s) { this.pressure = s; if (rank(s) > rank(this.wPress)) this.wPress = s; } }).observe('cpu', { sampleInterval: 2000 }).catch(() => {});
    } catch { /* not offered */ }
    try {
      new PerformanceObserver((list) => { for (const e of list.getEntries()) this.loaf(e as PerformanceEntry & LoafEntry); })
        .observe({ type: 'long-animation-frame', buffered: true });
      this.env.loafApi = true;
    } catch { /* Chrome 123+ only */ }
    window.addEventListener('resize', () => {
      this.resizes++;
      if (devicePixelRatio !== this.dpr) { this.dprChanges++; this.dpr = devicePixelRatio; }
    });
    // the last thing done before a freeze: which key, or what was clicked (an id or a class, never text; a key in
    // a text box is only 'typing')
    window.addEventListener('keydown', (e) => {
      if (e.repeat) return;
      const t = e.target as HTMLElement | null;
      this.act = t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable) ? 'typing' : `key ${e.code}`.slice(0, 32);
      this.actAt = performance.now();
    }, true);
    window.addEventListener('pointerdown', (e) => {
      this.act = `click ${whatOf(e.target as Element | null)}`.slice(0, 40);
      this.actAt = performance.now();
    }, true);
    // a CPU speed score while the browser is idle, the best of three short runs
    setTimeout(() => this.score(3), 15_000);
  }

  /**
   * The CPU score: ms for a fixed bit of JS (lower is faster), the best of `runs`, in an idle moment. The first
   * (three runs) is the machine's; one run every few minutes after says how it holds through the visit (heat, the
   * battery, something else running), each a few ms of an idle slot.
   */
  private score(runs: number): void {
    if (this.scoring) return;
    this.scoring = true;
    const bench = () => {
      this.scoring = false;
      let best = Infinity, x = 0;
      for (let k = 0; k < runs; k++) {
        const t = performance.now();
        for (let i = 1; i < 2_000_000; i++) x += Math.sqrt(i) * (i & 7);
        best = Math.min(best, performance.now() - t);
      }
      if (!(x > 0)) return;
      const v = round(best, 2);
      if (this.env.cpuScore === null) this.env.cpuScore = v;
      this.scores.push([round(this.visible, 0), v]);
      if (this.scores.length > SCORES_MAX) this.scores.splice(1, 1); // the first stays: the machine fresh
    };
    const ric = (window as Window & { requestIdleCallback?: (f: () => void, o?: { timeout: number }) => number }).requestIdleCallback;
    if (ric) ric(bench, { timeout: 20_000 }); else bench();
  }

  /** The canvas, for its context being lost and given back, and the WebGL limits. */
  attach(canvas: HTMLCanvasElement, renderer: { capabilities: { maxSamples?: number; precision: string } }): void {
    canvas.addEventListener('webglcontextlost', () => { this.ctx.lost++; if (this.ctx.at.length < 10) this.ctx.at.push(round(this.visible, 0)); });
    canvas.addEventListener('webglcontextrestored', () => { this.ctx.restored++; });
    try {
      const gl = this.gl();
      if (!gl) return;
      const timerExt = typeof WebGL2RenderingContext !== 'undefined' && gl instanceof WebGL2RenderingContext ? gl.getExtension('EXT_disjoint_timer_query_webgl2') as TimerExt | null : null;
      if (timerExt) this.timer = { gl: gl as WebGL2RenderingContext, ext: timerExt, q: null, open: false, at: 0 };
      this.env.webgl = {
        samples: renderer.capabilities.maxSamples ?? 0, precision: renderer.capabilities.precision,
        ext: gl.getSupportedExtensions()?.length ?? 0, timer: !!timerExt, parallel: !!gl.getExtension('KHR_parallel_shader_compile'), buffer: [gl.drawingBufferWidth, gl.drawingBufferHeight],
      };
    } catch { /* lost already */ }
  }

  setLook(f: () => PerfLook | null): void { this.look = f; }

  /**
   * Is the machine under strain: running on its battery (a laptop's power plan slows it), or its CPU pressure
   * (Chrome 125+) serious or worse. render/quality.ts holds Auto a level down while it is (11 Nov 2026 perf audit:
   * windows on battery ran at 22 fps against 47 on mains).
   */
  strained(): boolean {
    return (!!this.battery && !this.battery.charging) || this.pressure === 'serious' || this.pressure === 'critical';
  }
  setCensus(f: () => PerfCensus | null): void { this.census = f; }

  started(at: number): void { if (this.playAt === null) this.playAt = at; }

  /** Before the main render: start a GPU timing, at most twice a second. */
  gpuBegin(): void {
    const t = this.timer;
    if (!t) return;
    try {
      this.gpuPoll();
      const now = performance.now();
      if (t.q || now - t.at < 500) return;
      t.q = t.gl.createQuery();
      if (!t.q) return;
      t.gl.beginQuery(t.ext.TIME_ELAPSED_EXT, t.q);
      t.open = true;
      t.at = now;
    } catch { this.timer = null; }
  }
  gpuEnd(): void {
    const t = this.timer;
    if (!t?.open) return;
    try { t.gl.endQuery(t.ext.TIME_ELAPSED_EXT); } catch { this.timer = null; return; }
    t.open = false;
  }
  private gpuPoll(): void {
    const t = this.timer;
    if (!t?.q || t.open) return;
    const gl = t.gl;
    if (!gl.getQueryParameter(t.q, gl.QUERY_RESULT_AVAILABLE)) return;
    const disjoint = gl.getParameter(t.ext.GPU_DISJOINT_EXT) as boolean;
    const ns = gl.getQueryParameter(t.q, gl.QUERY_RESULT) as number;
    gl.deleteQuery(t.q);
    t.q = null;
    if (disjoint || !(ns > 0)) return;
    const ms = ns / 1e6;
    this.gpuSum += ms; this.gpuN++;
    this.wGpu += ms; this.wGpuN++;
  }

  /** A frame of play finished: what it cost. */
  frameDone(c: FrameCost, menu: boolean): void {
    this.last = c;
    // copied into maps kept for it, no new ones a frame: the profile mustn't feed the garbage collector it watches
    this.lastParts.clear();
    for (const [k, v] of c.parts) this.lastParts.set(k, v);
    this.lastSteps.clear();
    for (const [k, v] of c.steps) if (v >= 1) this.lastSteps.set(k, v);
    this.lastHeap = heapMb();
    this.costFrames++;
    this.cpuSum += c.cpu;
    this.cpuBins[Math.min(100, Math.floor(c.cpu))]++;
    for (const [k, v] of c.parts) { this.parts.set(k, (this.parts.get(k) ?? 0) + v); this.wParts.set(k, (this.wParts.get(k) ?? 0) + v); }
    if (this.wCostN < this.wCpu.length) this.wCpu[this.wCostN] = c.cpu;
    this.wCostN++;
    this.wCalls += c.calls;
    this.wTris += c.tris;
    if (menu) this.wMenu++;
  }

  /** A visible frame interval (net/perf.ts frame()), and the visible seconds so far. */
  interval(dt: number, visible: number, menu: boolean): void {
    this.visible = visible;
    this.frames++;
    this.bins[Math.min(100, Math.floor(dt))]++;
    if (this.wN < this.wIv.length) this.wIv[this.wN] = dt;
    this.wN++;
    let focus = true;
    try { focus = document.hasFocus(); } catch { /* not offered */ }
    if (focus) this.wFocus++;
    if (dt < FREEZE_MS) return;
    const c = this.last, look = this.safeLook(), heap = heapMb(), now = performance.now(), began = now - dt;
    const h: Hitch = {
      t: round(visible), at: Math.round(began), ms: Math.round(dt),
      cpu: c ? round(c.cpu) : null, prog: c?.programsMade ?? 0, chunks: c?.chunksMade ?? 0, tex: c ? c.texMade : 0,
      parts: c ? top(this.lastParts, 1, 3).map(([k, v]) => [k, round(v, 0)] as [string, number]) : [],
      heap, menu: menu ? 1 : 0, cam: look?.cam ?? '', panel: look?.panel ?? null,
      steps: top(this.lastSteps, 1, 2).map(([k, v]) => [k, round(v, 0)] as [string, number]), geo: c?.geoMade ?? 0,
      gc: heap != null && this.lastHeap != null ? Math.max(0, this.lastHeap - heap) : null,
      jobs: jobsBetween(began, now), foc: focus ? 1 : 0,
    };
    // the last key or click, when it was within a few seconds: before the freeze began, or inside it
    if (this.act && now - this.actAt < 5000 + dt) { h.act = this.act; h.actMs = Math.round(began - this.actAt); }
    keep(this.hitchesEarly, this.hitchesRecent, h, HITCHES_EARLY, HITCHES_RECENT);
    // every freeze counted by cause, the kept list or not (behind the loading screen: its own row, never seen)
    const cause = h.panel === 'loading' ? 'behind the loading screen' : hitchCause(h);
    const tl = this.tally.get(cause);
    if (tl) { tl[0]++; tl[1] += dt; } else if (this.tally.size < 60) this.tally.set(cause, [1, dt]);
  }

  /** Every 15 visible seconds (net/perf.ts): the window's summary. */
  window(fps: number, level: string): void {
    const n = Math.min(this.wN, this.wIv.length), iv = this.wIv.slice(0, n).sort();
    const m = Math.min(this.wCostN, this.wCpu.length), cpu = this.wCpu.slice(0, m).sort();
    const look = this.safeLook();
    const info = this.last;
    let px = 0;
    try { const gl = this.gl(); if (gl) px = round(gl.drawingBufferWidth * gl.drawingBufferHeight / 1e6, 2); } catch { /* lost */ }
    const fn = Math.max(1, this.wCostN);
    let cpuSum = 0;
    for (let i = 0; i < m; i++) cpuSum += cpu[i];
    let cs: PerfCensus | null = null;
    try { cs = this.census(); } catch { /* a count that failed is left out */ }
    const rs = jobStat('route search'), routes = rs[0] - this.wRoutes[0], routeMs = rs[1] - this.wRoutes[1];
    this.wRoutes = rs;
    const win: PerfWindow = {
      t: round(this.visible, 0), fps: round(fps), p50: round(pct(iv, n, 0.5)), p95: round(pct(iv, n, 0.95)), max: Math.round(n ? iv[n - 1] : 0),
      cpu: round(m ? cpuSum / m : 0, 2), cpu95: round(pct(cpu, m, 0.95)), gpu: this.wGpuN ? round(this.wGpu / this.wGpuN, 2) : null,
      calls: Math.round(this.wCalls / fn), tris: round(this.wTris / fn / 1000), prog: info?.programs ?? 0, tex: info?.textures ?? 0, geo: info?.geometries ?? 0,
      heap: heapMb(), px, level, cap: look?.cap ?? 0, menu: round(this.wMenu / fn, 2),
      cam: look?.cam ?? '', kind: look?.kind ?? '', spd: round(look?.speed ?? 0), night: look?.night ? 1 : 0, chunks: look?.chunks ?? 0, units: look?.units ?? 0, cell: look?.cell ?? '',
      batt: this.battery ? (this.battery.charging ? 1 : 0) : null, press: this.wPress ?? this.pressure, fs: document.fullscreenElement ? 1 : 0,
      parts: top(this.wParts, fn, 4),
      routes, routeMs: Math.round(routeMs), foc: round(this.wFocus / Math.max(1, this.wN), 2),
      ...(cs ? { obj: cs.obj, vis: cs.vis, drawn: cs.drawn, light: cs.light, spare: cs.spare, agents: cs.agents, peds: cs.peds, dock: round(cs.dock / fn), own: cs.own.slice(0, 10) } : {}),
    };
    keep(this.winEarly, this.winRecent, win, WINDOWS_EARLY, WINDOWS_RECENT);
    // the whole visit, thinned: fps, CPU and draw calls averaged over the windows since the last sample, the
    // counts as they stand
    const a = this.sAcc;
    a.n++; a.fps += win.fps; a.cpu += win.cpu; a.calls += win.calls;
    if (a.n >= this.seriesEvery) {
      this.series.push([win.t, round(a.fps / a.n), round(a.cpu / a.n), win.heap ?? 0, win.geo, win.tex, Math.round(a.calls / a.n), cs?.obj ?? 0, win.units, cs?.spare ?? 0, cs?.agents ?? 0]);
      a.n = 0; a.fps = 0; a.cpu = 0; a.calls = 0;
      if (this.series.length > SERIES_MAX) { this.series = this.series.filter((_, i) => i % 2 === 1); this.seriesEvery *= 2; }
    }
    if (this.visible - this.scoreAt >= SCORE_EVERY_S && this.env.cpuScore !== null) { this.scoreAt = this.visible; this.score(1); }
    this.wN = 0; this.wCostN = 0; this.wParts.clear(); this.wCalls = 0; this.wTris = 0; this.wMenu = 0; this.wGpu = 0; this.wGpuN = 0; this.wPress = null; this.wFocus = 0;
  }

  private safeLook(): PerfLook | null { try { return this.look(); } catch { return null; } }

  private loaf(e: PerformanceEntry & LoafEntry): void {
    if (e.duration < LOAF_MS) return;
    const scripts = (e.scripts ?? []).slice().sort((a, b) => b.duration - a.duration).slice(0, 3).map((s) => ({
      inv: String(s.invoker ?? '').slice(0, 60), fn: String(s.sourceFunctionName ?? '').slice(0, 40),
      src: String(s.sourceURL ?? '').split('/').pop()?.slice(0, 40) ?? '', pos: s.sourceCharPosition ?? -1,
      ms: Math.round(s.duration), forced: Math.round(s.forcedStyleAndLayoutDuration ?? 0),
    }));
    const end = e.startTime + e.duration;
    // every one kept slim for the freeze it was (report()), beyond the few kept whole
    const s0 = scripts[0];
    this.loafJoin.push({ ms: Math.round(e.duration), render: e.renderStart ? Math.round(end - e.renderStart) : 0, fn: s0?.fn ?? '', src: s0?.src ?? '', pos: s0?.pos ?? -1, inv: s0?.inv ?? '', sms: s0?.ms ?? 0, forced: s0?.forced ?? 0 });
    this.loafJoinAt.push([e.startTime, end]);
    if (this.loafJoin.length > LOAF_JOIN) { this.loafJoin.shift(); this.loafJoinAt.shift(); }
    keep(this.loafEarly, this.loafRecent, {
      t: this.playAt === null ? -1 : round((e.startTime - this.playAt) / 1000), at: Math.round(e.startTime), ms: Math.round(e.duration), block: Math.round(e.blockingDuration ?? 0),
      layout: e.styleAndLayoutStart ? Math.round(end - e.styleAndLayoutStart) : 0, render: e.renderStart ? Math.round(end - e.renderStart) : 0, scripts,
    }, LOAF_EARLY, LOAF_RECENT);
  }

  report(): FieldReport {
    const n = this.frames, p = (q: number) => { let left = Math.max(1, Math.ceil(q * n)); for (let i = 0; i <= 100; i++) { left -= this.bins[i]; if (left <= 0) return i + 0.5; } return 100; };
    const cp = (q: number) => { let left = Math.max(1, Math.ceil(q * this.costFrames)); for (let i = 0; i <= 100; i++) { left -= this.cpuBins[i]; if (left <= 0) return i + 0.5; } return 100; };
    const bins: Record<string, number> = {};
    this.bins.forEach((v, i) => { if (v) bins[i] = v; });
    // the refresh rate: the 10th-percentile interval when uncapped (a 60 Hz screen draws no faster than ~16.7 ms)
    const p10 = n > 300 ? p(0.1) : null;
    this.env.refreshHz = p10 ? Math.round(1000 / Math.max(2, p10)) : null;
    this.env.battery = this.battery ?? this.env.battery;
    // each freeze's long frame from the browser: the one that overlaps it most
    const hitches = [...this.hitchesEarly, ...this.hitchesRecent];
    for (const h of hitches) {
      if (h.lf) continue;
      let best = -1, over = 60;
      for (let i = 0; i < this.loafJoinAt.length; i++) {
        const o = Math.min(h.at + h.ms, this.loafJoinAt[i][1]) - Math.max(h.at, this.loafJoinAt[i][0]);
        if (o > over) { over = o; best = i; }
      }
      if (best >= 0) h.lf = this.loafJoin[best];
    }
    return {
      env: { ...this.env, webgl: this.env.webgl ? { ...this.env.webgl } : null },
      iv: n ? { p10: p(0.1), p50: p(0.5), p90: p(0.9), p95: p(0.95), p99: p(0.99), bins } : { p10: 0, p50: 0, p90: 0, p95: 0, p99: 0, bins },
      cpu: { mean: round(this.costFrames ? this.cpuSum / this.costFrames : 0, 2), p95: this.costFrames ? cp(0.95) : 0 },
      gpu: this.gpuN ? { mean: round(this.gpuSum / this.gpuN, 2), n: this.gpuN } : null,
      parts: top(this.parts, this.costFrames, 24),
      hitches,
      windows: [...this.winEarly, ...this.winRecent],
      loaf: [...this.loafEarly, ...this.loafRecent],
      ctx: { lost: this.ctx.lost, restored: this.ctx.restored, at: this.ctx.at.slice() },
      resizes: this.resizes, dprChanges: this.dprChanges,
      jobs: jobsReport(), counts: countsReport(),
      tally: [...this.tally].map(([k, v]) => [k, v[0], Math.round(v[1])] as [string, number, number]).sort((a, b) => b[2] - a[2]),
      series: this.series.slice(), scores: this.scores.slice(), arms: armsReport(),
    };
  }
}

/** What was clicked, as the page names it: its id, or the nearest named thing above it, or its class. Never its text. */
function whatOf(el: Element | null): string {
  for (let e = el, k = 0; e && k < 5; e = e.parentElement, k++) {
    if (e.id) return `#${e.id}`;
    if (e.tagName === 'CANVAS') return 'canvas';
  }
  const cls = el && typeof el.className === 'string' ? el.className.trim().split(/\s+/)[0] : '';
  return el ? `${el.tagName.toLowerCase()}${cls ? `.${cls}` : ''}` : '?';
}

const rank = (s: string | null): number => ['nominal', 'fair', 'serious', 'critical'].indexOf(s ?? '');

interface LoafEntry {
  blockingDuration?: number; renderStart?: number; styleAndLayoutStart?: number;
  scripts?: { invoker?: string; sourceFunctionName?: string; sourceURL?: string; sourceCharPosition?: number; duration: number; forcedStyleAndLayoutDuration?: number }[];
}
