/**
 * The markets' goods (0.7.0, NEXT_WORLD; docs/events.html "Markets"), apart from eventTemplates.ts because they
 * are deliveries like templates.ts's own and use its siteRef (eventTemplates.ts is loaded by the events' stage
 * before the missions, so it may not import templates.ts).
 */
import type { Obj } from './model';
import { siteRef, type Template } from './templates';
import { cargoById } from '../cargoTypes';
import { valueOf, type Site } from '../cargo';
import { offerable } from '../fit';
import { entry, hoursLeft } from './eventTemplates';

/**
 * A market's goods (0.7.0, docs/events.html "Markets"): while a farmers' market sets up or trades, its stallholders
 * want produce in from the farms round about; a Christmas market wants mulled wine, treats and lanterns for its huts.
 * A delivery like any other, from a site that makes it to a door on the market (a shop on the square, the market
 * hall), offered at the market's diamond.
 */
function marketGoods(id: string, kind: 'produce' | 'xmas', ids: string[], title: string, why: (what: string, from: string) => string, pay: number): Template {
  return {
    id, thread: 'fleet', kind: 'job',
    gate(c) { return entry(c, kind) ? null : 'no market wanting goods'; },
    bind(c) {
      const e = entry(c, kind);
      if (!e) return null;
      // the door on the market the goods go in at
      const tos = c.sites(['marketSquare', 'marketHall', 'grocery', 'farmShop', 'deli', 'cafe', 'bakery', 'pub', 'shop'])
        .filter((s) => Math.hypot(s.x - e.at.x, s.z - e.at.z) < 14)
        .sort((a, b) => Math.hypot(a.x - e.at.x, a.z - e.at.z) - Math.hypot(b.x - e.at.x, b.z - e.at.z));
      const to = tos[0];
      if (!to) return null;
      for (const cid of ids) {
        const type = cargoById(cid);
        if (!type) continue;
        const froms = c.sites(type.from as string[]).filter((s: Site) => { const d = Math.hypot(s.x - to.x, s.z - to.z); return d > 14 && d < 170; })
          .sort((a, b) => Math.hypot(a.x - c.at.x, a.z - c.at.z) - Math.hypot(b.x - c.at.x, b.z - c.at.z)).slice(0, 6);
        for (const from of froms) {
          const fit = offerable(c.def, c.at, from, to, type, true);
          if (!fit.ok || !fit.urgency) continue;
          const value = valueOf(type, fit.dist, fit.urgency, fit.seconds);
          const what = type.name.toLowerCase(), fromName = siteRef(from).name.toLowerCase();
          const w = why(what, fromName);
          let label = `${type.name} → the market`;
          if (label.length > 28) label = `Deliver ${what}`.slice(0, 28);
          const obj: Obj = { t: 'deliver', label, icon: type.icon, cargo: type.id, from: siteRef(from), to: { ...siteRef(to), name: kind === 'xmas' ? 'the Christmas market' : 'the market' }, n: 1, value };
          return {
            title, why: w.length <= 130 ? w : w.slice(0, 130),
            giver: { who: 'organiser', name: kind === 'xmas' ? 'The Christmas market' : 'The market’s stallholders', at: e.at, town: null },
            hero: { kind: 'crate', colour: type.color }, caption: type.name,
            objs: [obj],
            reward: [{ r: 'cash', n: Math.round((value * pay) / 10) * 10 }],
            hours: hoursLeft(c, e),
          };
        }
      }
      return null;
    },
  };
}
const produce = marketGoods('event:produce', 'produce', ['vegetables', 'fruit', 'cheese', 'milk'], 'Market Morning',
  (what, from) => `The farmers’ market is short of ${what}. Bring a load in from the ${from} while the stalls are trading.`, 1.6);
const xmasGoods = marketGoods('event:xmas', 'xmas', ['wine', 'bread', 'lanterns'], 'Christmas Market',
  (what, from) => `The Christmas market’s huts want ${what === 'wine' ? 'wine for the mulled wine' : what} from the ${from}, today while it’s on.`, 1.7);

export const MARKET_TEMPLATES: Template[] = [produce, xmasGoods];
