import * as THREE from 'three';
import { CHUNK, World, Under, heightAt, type RailPath, type RailEra } from '../world/tiles';
import { hex, scale, type RGB } from '../world/biomes';
import { BALLAST_DROP, BALLAST_TOP, BALLAST_TOE } from '../world/railSurface';
import { twinOffset } from './railTwin';

/**
 * The track itself, drawn per chunk: a swept ballast bed (or a bridge's deck slab), two rails, a
 * sleeper every few feet, the embankment skirts, the station platforms and the buffer stops. The
 * structures underneath and around it (trestles, arches, trusses, piers, portals, crossings and
 * signals) are railBridges.ts.
 *
 * Everything is built in the cell's local tile coordinates from the RailPath samples. A stretch of
 * track belongs to the chunk holding the midpoint of each quarter-tile sample segment, a sleeper to
 * the chunk it lies in, so every piece is drawn by exactly one chunk and the sweep joins exactly at
 * chunk edges. Straight runs are merged into long segments, so a straight tile costs a handful of
 * triangles and a tight curve about fifty.
 */

type P3 = [number, number, number];

export const trackMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.93, metalness: 0 });
const steelMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.42, metalness: 0.28 });

// ---- dimensions (tiles / world units) ----
const RAIL_HALF_GAUGE = 0.1;
const RAIL_W = 0.028, RAIL_H = 0.03;
const SLEEPER_EVERY = 0.35, SLEEPER_HALF = 0.18, SLEEPER_HALF_W = 0.03, SLEEPER_H = 0.03;
/** The ballast profile is also what cars ride on over the track: it lives in world/railSurface.ts. */
export { BALLAST_DROP };
/** The ground a platform stands on, below the rail, and the platform's height above that ground. */
const PAD_DROP = 0.1, PLATFORM_H = 0.25, RAMP = 0.6;
const PLATFORM_NEAR = 0.32, PLATFORM_FAR = 0.9, ISLAND_FAR = 0.78;

/** A bridge deck slab per Under: half width and thickness below the ballast top. */
export const DECK: Partial<Record<Under, { half: number; thick: number }>> = {
  [Under.Trestle]: { half: 0.26, thick: 0.09 },
  [Under.Viaduct]: { half: 0.34, thick: 0.2 },
  [Under.Truss]: { half: 0.29, thick: 0.08 },
  [Under.Sea]: { half: 0.31, thick: 0.13 },
};
/** Bottom of the deck slab under rail height y. */
export function deckBottom(under: Under, y: number): number {
  const d = DECK[under];
  return y - BALLAST_DROP - (d ? d.thick : 0.06);
}
const isBridge = (u: number): boolean => u === Under.Trestle || u === Under.Viaduct || u === Under.Truss || u === Under.Sea;

const BALLAST: Record<RailEra, RGB> = { steam: hex(0x857a6e), streamline: hex(0x8f8980), modern: hex(0x9c9890) };
const SLEEPER: Record<RailEra, RGB> = { steam: hex(0x5b4332), streamline: hex(0x66513e), modern: hex(0xb9b5ac) };
const RAIL_TOP = hex(0xc9ccd0), RAIL_SIDE = hex(0x6d6259);
const DECK_TOP: Partial<Record<Under, RGB>> = {
  [Under.Trestle]: hex(0x6e5540), [Under.Truss]: hex(0x5a5f66),
};
const DECK_SIDE: Partial<Record<Under, RGB>> = {
  [Under.Trestle]: hex(0x5e4630), [Under.Viaduct]: hex(0xa89e8a), [Under.Truss]: hex(0x4d5258), [Under.Sea]: hex(0xc4bfb5),
};
const PLATFORM_TOP: Record<RailEra, RGB> = { steam: hex(0xcdbfa6), streamline: hex(0xd4cec2), modern: hex(0xdad8d2) };
const PLATFORM_FACE = hex(0xa89f90), PLATFORM_EDGE: Record<RailEra, RGB> = { steam: hex(0xeeeae0), streamline: hex(0xf2c14e), modern: hex(0xf2c14e) };
const BANK = hex(0x8c8f68);
const BUFFER_RED = hex(0xc0392b), BUFFER_WHITE = hex(0xeeeae0), LEVER = hex(0x3a3f45);

/** Flat-coloured triangles, each wound to face along a hint direction. */
export class TrackBuf {
  pos: number[] = [];
  col: number[] = [];

  tri(a: P3, b: P3, c: P3, col: RGB, h: P3): void {
    const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
    const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
    if (nx * h[0] + ny * h[1] + nz * h[2] < 0) { const t = b; b = c; c = t; }
    this.pos.push(a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2]);
    for (let k = 0; k < 3; k++) this.col.push(col[0], col[1], col[2]);
  }

  quad(a: P3, b: P3, c: P3, d: P3, col: RGB, h: P3): void {
    this.tri(a, b, c, col, h);
    this.tri(a, c, d, col, h);
  }

  /** A box turned to heading (tx, tz), centred on (x, z), standing on y: five faces. */
  obox(x: number, y: number, z: number, tx: number, tz: number, along: number, across: number, h: number, col: RGB, top: RGB = col): void {
    const nx = -tz, nz = tx, a = along / 2, c = across / 2, y1 = y + h;
    const p = (u: number, v: number, yy: number): P3 => [x + tx * u + nx * v, yy, z + tz * u + nz * v];
    this.quad(p(-a, -c, y1), p(a, -c, y1), p(a, c, y1), p(-a, c, y1), top, [0, 1, 0]);
    this.quad(p(a, -c, y), p(a, c, y), p(a, c, y1), p(a, -c, y1), col, [tx, 0, tz]);
    this.quad(p(-a, -c, y), p(-a, c, y), p(-a, c, y1), p(-a, -c, y1), col, [-tx, 0, -tz]);
    this.quad(p(-a, c, y), p(a, c, y), p(a, c, y1), p(-a, c, y1), col, [nx, 0, nz]);
    this.quad(p(-a, -c, y), p(a, -c, y), p(a, -c, y1), p(-a, -c, y1), col, [-nx, 0, -nz]);
  }

  mesh(material: THREE.Material): THREE.Mesh | null {
    if (!this.pos.length) return null;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
    g.computeVertexNormals();
    g.computeBoundingSphere();
    const m = new THREE.Mesh(g, material);
    m.receiveShadow = true;
    return m;
  }
}

// ---------------- sampling a path ----------------

/** A point on a path: position, top of rail, unit tangent, and the sample index it lies after. */
export interface PathPoint { x: number; z: number; y: number; tx: number; tz: number; i: number }

const normals = new WeakMap<RailPath, Float32Array>();
/** Unit tangent per sample (tx, tz pairs), from the neighbours either side. */
export function tangents(p: RailPath): Float32Array {
  let t = normals.get(p);
  if (t) return t;
  const n = p.s.length;
  t = new Float32Array(n * 2);
  for (let i = 0; i < n; i++) {
    const a = Math.max(0, i - 1), b = Math.min(n - 1, i + 1);
    const dx = p.xz[b * 2] - p.xz[a * 2], dz = p.xz[b * 2 + 1] - p.xz[a * 2 + 1];
    const l = Math.hypot(dx, dz) || 1;
    t[i * 2] = dx / l;
    t[i * 2 + 1] = dz / l;
  }
  normals.set(p, t);
  return t;
}

const boxes = new WeakMap<RailPath, [number, number, number, number]>();
/** Whether any of a path lies within `pad` tiles of the rectangle [x0, x1) × [z0, z1). */
export function pathNear(p: RailPath, x0: number, z0: number, x1: number, z1: number, pad = 2): boolean {
  let b = boxes.get(p);
  if (!b) {
    b = [Infinity, Infinity, -Infinity, -Infinity];
    for (let i = 0; i < p.xz.length; i += 2) {
      b[0] = Math.min(b[0], p.xz[i]); b[1] = Math.min(b[1], p.xz[i + 1]);
      b[2] = Math.max(b[2], p.xz[i]); b[3] = Math.max(b[3], p.xz[i + 1]);
    }
    boxes.set(p, b);
  }
  return b[0] < x1 + pad && b[2] >= x0 - pad && b[1] < z1 + pad && b[3] >= z0 - pad;
}

/** Index of the last sample at or before arc length s. */
function sampleBefore(p: RailPath, s: number): number {
  const n = p.s.length;
  if (s <= 0) return 0;
  if (s >= p.length) return n - 2;
  let i = Math.min(n - 2, Math.max(0, Math.floor((s / p.length) * (n - 1))));
  while (i > 0 && p.s[i] > s) i--;
  while (i < n - 2 && p.s[i + 1] <= s) i++;
  return i;
}

/** The point at arc length s, interpolated between samples. */
export function pathAt(p: RailPath, s: number): PathPoint {
  const i = sampleBefore(p, s);
  const t = tangents(p);
  const ds = p.s[i + 1] - p.s[i];
  const f = ds > 1e-6 ? Math.min(1, Math.max(0, (s - p.s[i]) / ds)) : 0;
  const x = p.xz[i * 2] + (p.xz[i * 2 + 2] - p.xz[i * 2]) * f;
  const z = p.xz[i * 2 + 1] + (p.xz[i * 2 + 3] - p.xz[i * 2 + 1]) * f;
  let tx = t[i * 2] + (t[i * 2 + 2] - t[i * 2]) * f, tz = t[i * 2 + 1] + (t[i * 2 + 3] - t[i * 2 + 1]) * f;
  const l = Math.hypot(tx, tz) || 1;
  tx /= l; tz /= l;
  return { x, z, y: p.y[i] + (p.y[i + 1] - p.y[i]) * f, tx, tz, i };
}

/**
 * Samples of a joining path (a loop, a rung's end) that lie on top of the path they join: drawing
 * them twice would only make the ballast shimmer. 1 where the sample sits within a hair of the other.
 */
const overlaps = new WeakMap<RailPath, { sig: string; o: Uint8Array }>();
function overlapOf(w: World, p: RailPath): Uint8Array {
  // keyed on the path's ends too: a built track taken up turns a join beside it into buffers (world/railBuild.ts)
  const sig = `${p.start.kind}${p.start.path ?? ''}:${p.start.s ?? ''}|${p.end.kind}${p.end.path ?? ''}:${p.end.s ?? ''}`;
  const had = overlaps.get(p);
  if (had && had.sig === sig) return had.o;
  const n = p.s.length;
  const o = new Uint8Array(n);

  const check = (end: typeof p.start, from: number, step: 1 | -1) => {
    if (end.kind !== 'join' || end.path === undefined) return;
    const q = w.rails[end.path];
    if (!q || q === p) return;
    let j = sampleBefore(q, end.s ?? 0);
    for (let k = 0, i = from; k < 80 && i >= 0 && i < n; k++, i += step) {
      const x = p.xz[i * 2], z = p.xz[i * 2 + 1];
      // walk the other path's index toward the nearest sample
      let best = Infinity;
      for (let it = 0; it < 40; it++) {
        const d0 = Math.hypot(q.xz[j * 2] - x, q.xz[j * 2 + 1] - z);
        best = d0;
        const up = j + 1 < q.s.length ? Math.hypot(q.xz[j * 2 + 2] - x, q.xz[j * 2 + 3] - z) : Infinity;
        const dn = j > 0 ? Math.hypot(q.xz[j * 2 - 2] - x, q.xz[j * 2 - 1] - z) : Infinity;
        if (up < d0 && up <= dn) j++;
        else if (dn < d0) j--;
        else break;
      }
      if (best > 0.05) break;
      o[i] = 1;
    }
  };
  check(p.start, 0, 1);
  check(p.end, n - 1, -1);
  overlaps.set(p, { sig, o });
  return o;
}


/** Whether segment i (samples i..i+1) of a path shows: not deep in a tunnel, not doubled on another track. */
function segmentShows(w: World, p: RailPath, i: number, ov: Uint8Array): boolean {
  if (ov[i] && ov[i + 1]) return false;
  if (p.under[i] === Under.Tunnel && p.under[i + 1] === Under.Tunnel) {
    // the first few feet inside a portal stay visible; underground is left to the hill
    const g0 = heightAt(w, p.xz[i * 2], p.xz[i * 2 + 1]), g1 = heightAt(w, p.xz[i * 2 + 2], p.xz[i * 2 + 3]);
    if (g0 > p.y[i] + 0.25 && g1 > p.y[i + 1] + 0.25) return false;
  }
  return true;
}

/** What carries segment i: a tunnel's mouth is laid like ordinary ground. */
function segClass(p: RailPath, i: number): Under {
  let u = p.under[i] as Under;
  if (u === Under.Tunnel) u = p.under[i + 1] as Under;
  if (u === Under.Tunnel) u = Under.Ground;
  // a bridge begins at the first sample that is one; the sample before it belongs to the bank
  const next = p.under[i + 1] as Under;
  if (isBridge(u) && !isBridge(next)) u = next === Under.Tunnel ? Under.Ground : next;
  return u;
}

// ---------------- the sweep ----------------

export function buildRailChunk(w: World, cx: number, cz: number): THREE.Object3D | null {
  if (!w.rails.length) return null;
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  const inChunk = (x: number, z: number) => x >= x0 && x < x0 + CHUNK && z >= z0 && z < z0 + CHUNK;
  const bed = new TrackBuf(), steel = new TrackBuf();

  for (const p of w.rails) {
    const n = p.s.length;
    if (n < 2 || !pathNear(p, x0, z0, x0 + CHUNK, z0 + CHUNK)) continue;
    const t = tangents(p);
    const ov = overlapOf(w, p);
    const sink = p.kind === 'main' ? 0 : 0.006;
    // runs of consecutive owned, visible segments of one class
    let i = 0;
    while (i < n - 1) {
      const mx = (p.xz[i * 2] + p.xz[i * 2 + 2]) / 2, mz = (p.xz[i * 2 + 1] + p.xz[i * 2 + 3]) / 2;
      if (!inChunk(mx, mz) || !segmentShows(w, p, i, ov)) { i++; continue; }
      const cls = segClass(p, i);
      let j = i + 1;
      while (j < n - 1) {
        const ax = (p.xz[j * 2] + p.xz[j * 2 + 2]) / 2, az = (p.xz[j * 2 + 1] + p.xz[j * 2 + 3]) / 2;
        if (!inChunk(ax, az) || !segmentShows(w, p, j, ov) || segClass(p, j) !== cls) break;
        j++;
      }
      sweep(w, p, t, i, j, cls, sink, bed, steel);
      i = j;
    }
    sleepers(w, p, t, ov, inChunk, bed);
    ends(w, p, t, inChunk, bed);
  }
  for (const st of w.stations) platforms(w, st.path, st.s0, st.s1, st.side, st.loop >= 0 || !!st.twin, st.era, inChunk, bed);

  const parts = [bed.mesh(trackMaterial), steel.mesh(steelMaterial)].filter((m): m is THREE.Mesh => m !== null);
  if (!parts.length) return null;
  const g = new THREE.Group();
  g.add(...parts);
  return g;
}

const ghostMaterial = new THREE.MeshStandardMaterial({ color: 0x7ec8ff, transparent: true, opacity: 0.62, roughness: 0.9, depthWrite: false, flatShading: true });
const badGhostMaterial = new THREE.MeshStandardMaterial({ color: 0xff6b5f, transparent: true, opacity: 0.62, roughness: 0.9, depthWrite: false, flatShading: true });

/**
 * A ghost of a path about to be laid (the builder's Rails side, game/railBuilder.ts): the whole path swept as
 * the chunks would draw it, in one translucent colour (red where it can't be laid). Local to the cell.
 */
export function buildRailGhost(w: World, p: RailPath, bad = false): THREE.Mesh | null {
  const n = p.s.length;
  if (n < 2) return null;
  const t = tangents(p);
  const buf = new TrackBuf();
  let i = 0;
  while (i < n - 1) {
    const cls = segClass(p, i);
    let j = i + 1;
    while (j < n - 1 && segClass(p, j) === cls) j++;
    sweep(w, p, t, i, j, cls, 0, buf, buf);
    i = j;
  }
  const m = buf.mesh(bad ? badGhostMaterial : ghostMaterial);
  if (m) { m.renderOrder = 6; m.receiveShadow = false; }
  return m;
}

/** Sweep samples a..b (b > a) of one class: merge straight stretches, then lay the bed and the rails. */

function sweep(w: World, p: RailPath, t: Float32Array, a: number, b: number, cls: Under, sink: number, bed: TrackBuf, steel: TrackBuf): void {
  const maxMerge = cls === Under.Embank ? 4 : 8;
  const nodes = [a];
  let k = a;
  while (k < b) {
    let j = k + 1;
    while (j + 1 <= b && j + 1 - k <= maxMerge && straight(p, k, j + 1)) j++;
    nodes.push(j);
    k = j;
  }
  const era = p.era;
  const ballast = BALLAST[era];
  for (let q = 0; q + 1 < nodes.length; q++) {
    const ia = nodes[q], ib = nodes[q + 1];
    const A = frame(p, t, ia), B = frame(p, t, ib);
    if (isBridge(cls)) slab(w, p, cls, A, B, ballast, bed);
    else bank(w, p, cls, A, B, ballast, sink, bed);
    for (const side of [-1, 1]) rail(A, B, side * RAIL_HALF_GAUGE, steel);
  }
}

interface Frame { x: number; z: number; y: number; nx: number; nz: number }
function frame(p: RailPath, t: Float32Array, i: number): Frame {
  return { x: p.xz[i * 2], z: p.xz[i * 2 + 1], y: p.y[i], nx: -t[i * 2 + 1], nz: t[i * 2] };
}
const at = (f: Frame, o: number, y: number): P3 => [f.x + f.nx * o, y, f.z + f.nz * o];

/** Whether samples between k and j lie on the straight line from k to j (plan and height). */
function straight(p: RailPath, k: number, j: number): boolean {
  const ax = p.xz[k * 2], az = p.xz[k * 2 + 1], bx = p.xz[j * 2], bz = p.xz[j * 2 + 1];
  const dx = bx - ax, dz = bz - az, L = Math.hypot(dx, dz) || 1;
  if (p.under[k] !== p.under[j]) return false;
  for (let m = k + 1; m < j; m++) {
    const px = p.xz[m * 2] - ax, pz = p.xz[m * 2 + 1] - az;
    if (Math.abs(px * dz - pz * dx) / L > 0.01) return false;
    const f = (px * dx + pz * dz) / (L * L);
    if (Math.abs(p.y[m] - (p.y[k] + (p.y[j] - p.y[k]) * f)) > 0.004) return false;
    if (p.under[m] !== p.under[k]) return false;
  }
  return true;
}

/**
 * The ballast bed, with its shoulders running down to the ground where the line rides a bank. Double track on a bank
 * (a twin's bank beside it, render/railTwin.ts) rides one formation: the bed runs out to the line between the two
 * and has no shoulder on that side, so no V of ground opens between them (it showed under a double-track viaduct's end).
 */
function bank(w: World, p: RailPath, cls: Under, A: Frame, B: Frame, col: RGB, sink: number, buf: TrackBuf): void {
  const twA = cls === Under.Embank ? twinOffset(w, p, cls, A.x, A.y, A.z, A.nz, -A.nx) : 0;
  const twB = twA ? twinOffset(w, p, cls, B.x, B.y, B.z, B.nz, -B.nx) : 0;
  const tw = twA && twB && twA * twB > 0 ? Math.sign(twA) : 0;
  const shape = (f: Frame, t: number) => {
    const top = f.y - BALLAST_DROP - sink;
    const g = heightAt(w, f.x, f.z);
    const toe = BALLAST_TOE + Math.min(1.4, Math.max(0, (top - g - 0.06) * 1.5));
    const foot = (o: number): P3 => {
      const q = at(f, o, 0);
      q[1] = Math.min(heightAt(w, q[0], q[2]) - 0.03, top - 0.04);
      return q;
    };
    const high = toe > BALLAST_TOE + 0.05;
    // on a bank the ballast shoulder stops a little way down and grassy fill carries on to the toe
    const sh = high ? at(f, BALLAST_TOE, top - 0.06) : null, shr = high ? at(f, -BALLAST_TOE, top - 0.06) : null;
    const mid = t / 2 + Math.sign(t) * 0.03;
    return { l: at(f, tw > 0 ? mid : BALLAST_TOP, top), r: at(f, tw < 0 ? mid : -BALLAST_TOP, top), fl: foot(toe), fr: foot(-toe), sl: sh, sr: shr };
  };
  const a = shape(A, twA), b = shape(B, twB);
  const up: P3 = [0, 1, 0];
  buf.quad(a.l, a.r, b.r, b.l, col, up);
  const dark = scale(col, 0.86);
  for (const [s, ta, tb, fa, fb, sa, sb] of [[1, a.l, b.l, a.fl, b.fl, a.sl, b.sl], [-1, a.r, b.r, a.fr, b.fr, a.sr, b.sr]] as const) {
    if (s === tw) continue;
    const hint: P3 = [A.nx * s, 0.6, A.nz * s];
    if (sa && sb) {
      buf.quad(ta, tb, sb, sa, dark, hint);
      buf.quad(sa, sb, fb, fa, BANK, hint);
    } else if (sa || sb) {
      // where a bank begins, one end has a shoulder and the other not: split the difference
      const m0 = sa ?? fa, m1 = sb ?? fb;
      buf.quad(ta, tb, m1, m0, dark, hint);
      buf.quad(m0, m1, fb, fa, BANK, hint);
    } else buf.quad(ta, tb, fb, fa, dark, hint);
  }
}

/**
 * A bridge's deck slab: ballast (or planks) on top, the structure's colour down the sides. Where a twin deck stands
 * beside it (render/railTwin.ts) the slab runs out to the line between the two, with no side wall there, so double
 * track crosses on one deck rather than two with a slot between.
 */
function slab(w: World, p: RailPath, cls: Under, A: Frame, B: Frame, ballast: RGB, buf: TrackBuf): void {
  const d = DECK[cls]!;
  const topCol = DECK_TOP[cls] ?? ballast, side = DECK_SIDE[cls]!;
  const ta = A.y - BALLAST_DROP, tb = B.y - BALLAST_DROP;
  const twA = twinOffset(w, p, cls, A.x, A.y, A.z, A.nz, -A.nx), twB = twinOffset(w, p, cls, B.x, B.y, B.z, B.nz, -B.nx);
  const tw = twA && twB && twA * twB > 0 ? Math.sign(twA) : 0;
  // the slab's edges, left (+) and right (-): out to just past the middle on a twin's side
  const lA = tw > 0 ? twA / 2 + 0.03 : d.half, lB = tw > 0 ? twB / 2 + 0.03 : d.half;
  const rA = tw < 0 ? twA / 2 - 0.03 : -d.half, rB = tw < 0 ? twB / 2 - 0.03 : -d.half;
  buf.quad(at(A, lA, ta), at(A, rA, ta), at(B, rB, tb), at(B, lB, tb), topCol, [0, 1, 0]);
  if (cls === Under.Viaduct || cls === Under.Sea) {
    // a raised ballast bed on the slab
    const h = 0.004, bw = BALLAST_TOP;
    buf.quad(at(A, bw, ta + h), at(A, -bw, ta + h), at(B, -bw, tb + h), at(B, bw, tb + h), ballast, [0, 1, 0]);
  }
  for (const s of [1, -1]) {
    if (s === tw) continue;
    const oa = s > 0 ? lA : rA, ob = s > 0 ? lB : rB;
    buf.quad(at(A, oa, ta), at(B, ob, tb), at(B, ob, tb - d.thick), at(A, oa, ta - d.thick), side, [A.nx * s, 0, A.nz * s]);
  }
  buf.quad(at(A, lA, ta - d.thick), at(A, rA, ta - d.thick), at(B, rB, tb - d.thick), at(B, lB, tb - d.thick), scale(side, 0.7), [0, -1, 0]);
}

/** One rail: a bright running top and two darker web faces. */
function rail(A: Frame, B: Frame, o: number, buf: TrackBuf): void {
  const h = RAIL_W / 2;
  const ya = A.y, yb = B.y, la = ya - RAIL_H, lb = yb - RAIL_H;
  buf.quad(at(A, o + h, ya), at(A, o - h, ya), at(B, o - h, yb), at(B, o + h, yb), RAIL_TOP, [0, 1, 0]);
  buf.quad(at(A, o + h, ya), at(B, o + h, yb), at(B, o + h, lb), at(A, o + h, la), RAIL_SIDE, [A.nx, 0, A.nz]);
  buf.quad(at(A, o - h, ya), at(B, o - h, yb), at(B, o - h, lb), at(A, o - h, la), RAIL_SIDE, [-A.nx, 0, -A.nz]);
}

/** A sleeper every SLEEPER_EVERY tiles along the path, drawn by the chunk it lies in. */
function sleepers(w: World, p: RailPath, t: Float32Array, ov: Uint8Array, inChunk: (x: number, z: number) => boolean, buf: TrackBuf): void {
  const col = SLEEPER[p.era];
  const n = p.s.length;
  let i = 0;
  for (let s = SLEEPER_EVERY / 2; s < p.length; s += SLEEPER_EVERY) {
    while (i < n - 2 && p.s[i + 1] <= s) i++;
    const ds = p.s[i + 1] - p.s[i];
    const f = ds > 1e-6 ? (s - p.s[i]) / ds : 0;
    const x = p.xz[i * 2] + (p.xz[i * 2 + 2] - p.xz[i * 2]) * f, z = p.xz[i * 2 + 1] + (p.xz[i * 2 + 3] - p.xz[i * 2 + 1]) * f;
    if (!inChunk(x, z) || !segmentShows(w, p, i, ov)) continue;
    const y = p.y[i] + (p.y[i + 1] - p.y[i]) * f - RAIL_H;
    const tx = t[i * 2], tz = t[i * 2 + 1], nx = -tz, nz = tx;
    const pt = (u: number, v: number, yy: number): P3 => [x + tx * u + nx * v, yy, z + tz * u + nz * v];
    const u = SLEEPER_HALF_W, v = SLEEPER_HALF, lo = y - SLEEPER_H;
    buf.quad(pt(-u, -v, y), pt(u, -v, y), pt(u, v, y), pt(-u, v, y), col, [0, 1, 0]);
    buf.quad(pt(u, -v, lo), pt(u, v, lo), pt(u, v, y), pt(u, -v, y), scale(col, 0.8), [tx, 0, tz]);
    buf.quad(pt(-u, -v, lo), pt(-u, v, lo), pt(-u, v, y), pt(-u, -v, y), scale(col, 0.8), [-tx, 0, -tz]);
  }
}

/** Buffer stops where a line stops dead, and a point lever beside every turnout. */
function ends(w: World, p: RailPath, t: Float32Array, inChunk: (x: number, z: number) => boolean, buf: TrackBuf): void {
  const n = p.s.length;
  for (const [end, i, dir] of [[p.start, 0, -1], [p.end, n - 1, 1]] as const) {
    const x = p.xz[i * 2], z = p.xz[i * 2 + 1], y = p.y[i];
    if (!inChunk(x, z)) continue;
    const tx = t[i * 2] * dir, tz = t[i * 2 + 1] * dir, nx = -tz, nz = tx;
    if (end.kind === 'stop') {
      // two posts, a sloping back strut each, and a red beam with a white face
      for (const s of [-1, 1]) {
        const px = x + nx * s * RAIL_HALF_GAUGE, pz = z + nz * s * RAIL_HALF_GAUGE;
        buf.obox(px, y - 0.04, pz, tx, tz, 0.04, 0.04, 0.2, BUFFER_RED);
        buf.obox(px + tx * 0.08, y - 0.04, pz + tz * 0.08, tx, tz, 0.14, 0.03, 0.05, BUFFER_RED);
      }
      buf.obox(x - tx * 0.01, y + 0.08, z - tz * 0.01, tx, tz, 0.05, 0.34, 0.07, BUFFER_RED);
      buf.obox(x - tx * 0.04, y + 0.095, z - tz * 0.04, tx, tz, 0.012, 0.3, 0.04, BUFFER_WHITE);
    } else if (end.kind === 'join' && p.kind !== 'main') {
      // the lever stands on the side away from where this track leaves the other
      const k = Math.max(0, Math.min(n - 1, i - dir * 24));
      const ox = p.xz[k * 2] - x, oz = p.xz[k * 2 + 1] - z;
      const side = ox * nx + oz * nz > 0 ? -1 : 1;
      const lx = x + nx * side * 0.5 - tx * 0.6, lz = z + nz * side * 0.5 - tz * 0.6;
      buf.obox(lx, y - 0.1, lz, tx, tz, 0.12, 0.08, 0.06, LEVER);
      buf.obox(lx, y - 0.04, lz, tx, tz, 0.02, 0.02, 0.12, BUFFER_WHITE, BUFFER_RED);
    }
  }
  void w;
}

/** A station's platforms: one between the main line and the building, an island between it and the loop. */
function platforms(w: World, pathId: number, s0: number, s1: number, side: 1 | -1, loop: boolean, era: RailEra, inChunk: (x: number, z: number) => boolean, buf: TrackBuf): void {
  const p = w.rails[pathId];
  if (!p || s1 <= s0) return;
  const pieces: [number, number, number, number][] = []; // sa, sb, height at sa, height at sb (fractions of PLATFORM_H)
  pieces.push([Math.max(0, s0 - RAMP), s0, 0.05, 1]);
  const count = Math.max(1, Math.ceil((s1 - s0) / 2));
  for (let k = 0; k < count; k++) pieces.push([s0 + ((s1 - s0) * k) / count, s0 + ((s1 - s0) * (k + 1)) / count, 1, 1]);
  pieces.push([s1, Math.min(p.length, s1 + RAMP), 1, 0.05]);
  const top = PLATFORM_TOP[era], edge = PLATFORM_EDGE[era];
  const faces: [number, number, boolean][] = [[PLATFORM_NEAR * side, PLATFORM_FAR * side, false]];
  if (loop) faces.push([-PLATFORM_NEAR * side, -ISLAND_FAR * side, true]);
  for (const [sa, sb, ha, hb] of pieces) {
    if (sb - sa < 0.01) continue;
    const A = pathAt(p, sa), B = pathAt(p, sb), M = pathAt(p, (sa + sb) / 2);
    if (!inChunk(M.x, M.z)) continue;
    const fa: Frame = { x: A.x, z: A.z, y: A.y, nx: -A.tz, nz: A.tx }, fb: Frame = { x: B.x, z: B.z, y: B.y, nx: -B.tz, nz: B.tx };
    const ga = A.y - PAD_DROP - 0.02, gb = B.y - PAD_DROP - 0.02;
    const ya = A.y - PAD_DROP + PLATFORM_H * ha, yb = B.y - PAD_DROP + PLATFORM_H * hb;
    for (const [near, far, island] of faces) {
      const out = Math.sign(near);
      const e = near + out * 0.05;
      buf.quad(at(fa, near, ya), at(fa, e, ya), at(fb, e, yb), at(fb, near, yb), edge, [0, 1, 0]);
      const e2 = island ? far - out * 0.05 : far;
      buf.quad(at(fa, e, ya), at(fa, e2, ya), at(fb, e2, yb), at(fb, e, yb), top, [0, 1, 0]);
      if (island) buf.quad(at(fa, e2, ya), at(fa, far, ya), at(fb, far, yb), at(fb, e2, yb), edge, [0, 1, 0]);
      // the kerb faces, toward the track and away from it
      buf.quad(at(fa, near, ya), at(fb, near, yb), at(fb, near, gb), at(fa, near, ga), PLATFORM_FACE, [-fa.nx * out, 0, -fa.nz * out]);
      buf.quad(at(fa, far, ya), at(fb, far, yb), at(fb, far, gb), at(fa, far, ga), scale(PLATFORM_FACE, 0.92), [fa.nx * out, 0, fa.nz * out]);
    }
  }
}
