/** A plain block for any kind whose model is not drawn yet, so a town never has a hole in it. */
const placeholder: Draw = (k, W, D) => { k.box(0, 0, 0, Math.max(0.4, W - 0.3), 0.5, Math.max(0.4, D - 0.3), hex(0xd8d0c0)); };

const drawn: Partial<Record<RegionBuildingKind, Draw>> = {
  ...SANDS_DRAW, ...ICEFIELD_DRAW, ...SHALLOWS_DRAW, ...GREEN_DRAW, ...HEIGHTS_DRAW, ...MOORS_DRAW, ...VELDT_DRAW, ...FENS_DRAW, ...TERRACES_DRAW, ...WHITEWASH_DRAW, ...GOLDHILLS_DRAW,
  ...FIRECOAST_DRAW, ...FJORDS_DRAW, ...BIGTIMBER_DRAW, ...REDROCK_DRAW, ...DRAGONBAY_DRAW, ...STEPPE_DRAW, ...SALTPAN_DRAW, ...MANGROVE_DRAW, ...LAVENDER_DRAW,
};

export const REGION_DRAW = Object.fromEntries(
  Object.values(REGION_GROUPS).flat().map((kind) => [kind, drawn[kind] ?? placeholder]),
) as Record<RegionBuildingKind, Draw>;

/** Per-group draw tables for the gallery. */
export const REGION_GALLERY: Record<string, Partial<Record<RegionBuildingKind, Draw>>> = Object.fromEntries(
  Object.entries(REGION_GROUPS).map(([g, kinds]) => [g, Object.fromEntries(kinds.map((k) => [k, REGION_DRAW[k]]))]),
);
void REGION_KINDS;
