/**
 * A tow on the ground (docs/missions.html, Tows): the load sitting where the mission put it, the ropes,
 * and the fleet vehicles that come to pull alongside you.
 *
 * Accepting a tow calls in the nearest crewed road vehicles of yours; they drive over on the real roads
 * (Follow mode's routing) and wait beside the load. Pull up, stop, press Enter: your rope goes on, and
 * each helper hitches as it takes its place abreast of you. Then you drive and they keep station either
 * side, their ropes fanned out behind to the load, which comes along if between you all you out-pull the
 * ground. Jerk away too hard and a rope parts; drive back and Enter to hitch again (the helpers do it
 * themselves). Dragged into its drop ring, the job is done.
 *
 * Everything that decides the load's motion is physics.ts; this is the part that knows about the
 * player, the fleet and the scene. A puller on another machine would be one more `Puller` in the list.
 */
import * as THREE from 'three';
import { N, idx, inB, heightAt, waterDepth, type World } from '../../world/tiles';
import { buildHaul, disposeGroup } from '../../render/haulMeshes';
import { halfSize, type VehicleDef, type VehicleState } from '../vehicles';
import type { Unit } from '../fleet';
import type { HaulKind, PlaceRef } from '../missions/model';
import { HaulSim, LOAD_R, ROPE, needFor, pullOf, type Ground, type Puller } from './physics';
import { groundOf } from './ground';
import { GroundRing, drapeMat, groundOf as laidGroundOf } from '../../render/drape';
import { startPrompt } from '../startPrompt';

interface TowHost {
  worldAt(cx: number, cz: number): World | null;
  player(): { w: World; state: VehicleState; def: VehicleDef } | null;
  /** Enter was pressed this frame. */
  go(): boolean;
  say(title: string, body: string): void;
  /** The crewed road vehicles nearest the load, strongest first, up to n. */
  crew(n: number, x: number, z: number): Unit[];
  /** A unit's definition, with its parts. */
  defFor(u: Unit): VehicleDef;
  /** Put a unit into Follow (true) or back to Work (false). */
  follow(u: Unit, on: boolean): void;
  /** Hand the formation the helpers' stations, or take them back. */
  harness(fn: ((u: Unit) => { x: number; z: number; v: number; tow?: { heading: number; pedal: number; taut: boolean } } | null) | null): void;
  crack(): void;
  /**
   * What each helper was doing before a tow called it in, kept with the mission so a reload doesn't forget it:
   * read back (undefined: never called) and written as it is called.
   */
  wasFollow(uid: number): boolean | undefined;
  called(uid: number, wasFollow: boolean): void;
}

type TowPhase = 'muster' | 'ready' | 'towing' | 'done';

/** How near the load a vehicle has to be to hitch, and how near the drop the load has to be. */
const HITCH_R = ROPE + 1.2, DROP_R = 3.5;
const MESH_SCALE = 0.75;
/**
 * The crew are called in once you are this near the load (tiles), not the moment a game is loaded with the tow
 * still to do: a worker taken off its round at sign-in from across the map read as a bug (the user, 29 Oct 2026).
 */
const CALL_R = 150;

export class TowJob {
  phase: TowPhase = 'muster';
  readonly sim: HaulSim;
  private helpers: Unit[] = [];
  /** Each helper's mind before it was called in, to put it back after. */
  private was = new Map<number, boolean>();
  private mesh: THREE.Group;
  private ropes = new Map<string, THREE.Mesh>();
  private ring: GroundRing;
  private group = new THREE.Group();
  private sayCool = 0;
  private w: World | null;
  private local: Puller;
  private result: { ok: boolean } | null = null;

  constructor(
    readonly id: number,
    private host: TowHost,
    private scene: THREE.Scene,
    readonly kind: HaulKind,
    readonly from: PlaceRef,
    readonly to: PlaceRef,
    readonly min: number,
  ) {
    this.w = host.worldAt(from.cell[0], from.cell[1]);
    this.sim = new HaulSim({ x: from.x, z: from.z, vx: 0, vz: 0, heading: Math.atan2(to.x - from.x, to.z - from.z), need: 0 }, this.ground());
    this.mesh = buildHaul(kind);
    this.mesh.scale.setScalar(MESH_SCALE);
    // the drop ring, lying on the ground round the drop (render/drape.ts), not flat at its middle's height
    this.ring = new GroundRing(DROP_R, 0.16, drapeMat(0x5fa84a, 0.85));
    this.group.add(this.mesh, this.ring.mesh);
    scene.add(this.group);
    this.local = {
      id: 'me', name: 'You', kind: 'local',
      pull: 0,
      hitch: () => {
        const p = this.host.player();
        if (!p) return null;
        const [hl] = halfSize(p.def);
        return { x: p.w.ox + p.state.x - Math.sin(p.state.heading) * hl, z: p.w.oz + p.state.z - Math.cos(p.state.heading) * hl, heading: p.state.heading, v: p.state.v };
      },
      tug: (dx, dz, keep) => {
        const p = this.host.player();
        if (!p) return;
        p.state.x += dx;
        p.state.z += dz;
        p.state.v *= keep;
        (p.state as { skid?: number }).skid = 0.9;
      },
      trail: () => this.trail('me'),
    };
    host.harness((u) => this.station(u));
  }

  /** Call the helpers in, once: they have a way to drive. Each keeps what it was doing before, to go back to. */
  private callCrew(): void {
    if (this.calledIn) return;
    this.calledIn = true;
    const crew = this.host.crew(this.min - 1, this.from.x, this.from.z);
    for (const u of crew) {
      const was = this.host.wasFollow(u.uid) ?? u.mode === 'follow';
      this.was.set(u.uid, was);
      this.host.called(u.uid, was);
      this.host.follow(u, true);
      this.helpers.push(u);
    }
    if (crew.length) this.host.say('Crew called in', `${crew.map((u) => u.name).join(' and ')} ${crew.length === 1 ? 'is' : 'are'} on the way to help with the tow`);
  }
  private calledIn = false;

  /** The load's ground: how it drags, how high it is, and what stops it (ground.ts). */
  private ground(): Ground { return groundOf(() => this.w); }

  /**
   * Where a helper belongs. Mustering: in a row beside the load, off to the side the drop is on. Towing:
   * tight abreast of you, alternately either side, facing your way and on your pedal, so every rope
   * pulls the same way yours does. Where the street is too narrow for that it tucks in closer, and
   * failing that drops into line just ahead of you, where its rope is the tautest of all.
   */
  private station(u: Unit): { x: number; z: number; v: number; tow?: { heading: number; pedal: number; taut: boolean } } | null {
    const k = this.helpers.indexOf(u);
    if (k < 0 || this.phase === 'done') return null;
    let side = k % 2 === 0 ? 1 : -1;
    const rank = Math.floor(k / 2) + 1;
    const p = this.host.player();
    const L = this.sim.load;
    if (this.phase === 'towing' && p) {
      const px = p.w.ox + p.state.x, pz = p.w.oz + p.state.z, h = p.state.heading;
      const rx = Math.cos(h), rz = -Math.sin(h), fx = Math.sin(h), fz = Math.cos(h);
      const [hlU, hwU] = halfSize(this.host.defFor(u)), [hlP, hwP] = halfSize(p.def);
      // the first helper keeps whichever side of you it hitched on, rather than crossing your bows to the
      // other; the next takes the other side, and so on outward
      if (!this.sides.has(u.uid)) {
        const a = u.agent;
        const lat = a ? (a.w.ox + a.state.x - px) * rx + (a.w.oz + a.state.z - pz) * rz : 0;
        this.sides.set(u.uid, k === 0 ? (lat < 0 ? -1 : 1) : -(this.sides.get(this.helpers[0].uid) ?? 1) * (k % 2 === 0 ? -1 : 1));
      }
      side = this.sides.get(u.uid)!;
      // your pedal, while your own rope is on (the crew don't haul it without you), and whether this
      // helper's rope is near parting, so it can ease off before it does
      const rope = this.sim.ropes.get(`u${u.uid}`);
      const tow = { heading: h, pedal: this.sim.hitched('me') ? p.state.pedal ?? 0 : 0, taut: !!rope?.on && rope.strain > 0.7 };
      // your rope is off: they stop where they are and wait for you to hitch again
      if (!this.sim.hitched('me') && u.agent) return { x: u.agent.w.ox + u.agent.state.x, z: u.agent.w.oz + u.agent.state.z, v: 0, tow };
      const v = Math.abs(p.state.v);
      // door to door, with a hand's width between: close enough that three fit down a one-tile street
      const snug = hwP + hwU + 0.05, gap = snug + 0.06 + (hwU * 2 + 0.06) * (rank - 1);
      for (const lat of [gap, gap * 0.8, snug + (hwU * 2 + 0.04) * (rank - 1), snug]) {
        const x = px + rx * lat * side, z = pz + rz * lat * side;
        if (this.open(x, z, hwU)) return { x, z, v, tow };
      }
      // no room abreast: in line just ahead of you, a car length (and one more a rank)
      const ahead = (hlP + hlU + 0.08) * rank;
      return { x: px + fx * ahead + rx * 0.04 * side, z: pz + fz * ahead + rz * 0.04 * side, v, tow };
    }
    const dx = this.to.x - L.x, dz = this.to.z - L.z, d = Math.hypot(dx, dz) || 1;
    const fx = dx / d, fz = dz / d;
    const want = { x: L.x + fx * (ROPE + 0.4) + fz * 1.5 * side * rank, z: L.z + fz * (ROPE + 0.4) - fx * 1.5 * side * rank };
    return { ...(this.muster.get(u.uid) ?? this.snap(u, want.x, want.z)), v: 0 };
  }

  /** Which side of you each helper holds while towing, fixed at the first station it is given. */
  private sides = new Map<number, number>();

  /** Can a vehicle this wide sit at (x, z) world tiles: no building, no water, either side of it? */
  private open(x: number, z: number, hw: number): boolean {
    const w = this.host.worldAt(Math.floor(x / N), Math.floor(z / N));
    if (!w) return false;
    for (const [ox, oz] of [[0, 0], [hw, 0], [-hw, 0], [0, hw], [0, -hw]]) {
      const tx = Math.floor(x + ox - w.ox), tz = Math.floor(z + oz - w.oz);
      if (!inB(tx, tz)) return false;
      const i = idx(tx, tz);
      if (w.blocked[i] || waterDepth(w, i) > 0) return false;
    }
    return true;
  }

  /** Every puller's track since the tow began, a crumb every 0.4 tiles: the load is hauled along these. */
  private crumbs = new Map<string, { x: number; z: number }[]>();
  private trail(id: string): { x: number; z: number }[] { return this.crumbs.get(id) ?? []; }
  private drop(id: string, h: { x: number; z: number } | null): void {
    if (!h) return;
    let c = this.crumbs.get(id);
    if (!c) this.crumbs.set(id, (c = []));
    const last = c[c.length - 1];
    if (!last || Math.hypot(h.x - last.x, h.z - last.z) >= 0.4) { c.push({ x: h.x, z: h.z }); if (c.length > 3000) c.splice(0, 1000); }
  }

  /** Each helper's mustering spot, snapped to ground it can drive to once and kept. */
  private muster = new Map<number, { x: number; z: number }>();

  /** The drivable tile nearest (x, z): a road by preference, else open ground; the spot itself if none is near. */
  private snap(u: Unit, x: number, z: number): { x: number; z: number } {
    const w = this.w;
    let best = { x, z }, bestD = Infinity;
    if (w) {
      for (let dz = -6; dz <= 6; dz++) {
        for (let dx = -6; dx <= 6; dx++) {
          const tx = Math.floor(x - w.ox) + dx, tz = Math.floor(z - w.oz) + dz;
          if (!inB(tx, tz)) continue;
          const i = idx(tx, tz);
          if (w.blocked[i] || w.deckAxis[i] || waterDepth(w, i) > 0) continue;
          const d = Math.hypot(dx, dz) + (w.road[i] ? 0 : 3);
          if (d < bestD) { bestD = d; best = { x: w.ox + tx + 0.5, z: w.oz + tz + 0.5 }; }
        }
      }
    }
    this.muster.set(u.uid, best);
    return best;
  }

  /** A helper as a puller: its hitch and its tug, in its own island's frame turned into world tiles. */
  private pullerFor(u: Unit): Puller | null {
    const a = u.agent;
    if (!a) return null;
    const def = this.host.defFor(u);
    const [hl] = halfSize(def);
    return {
      id: `u${u.uid}`, name: u.name, kind: 'fleet', pull: pullOf(def as never),
      hitch: () => (u.agent ? { x: u.agent.w.ox + u.agent.state.x - Math.sin(u.agent.state.heading) * hl, z: u.agent.w.oz + u.agent.state.z - Math.cos(u.agent.state.heading) * hl, heading: u.agent.state.heading, v: u.agent.state.v } : null),
      tug: (dx, dz, keep) => { const s = u.agent?.state; if (!s) return; s.x += dx; s.z += dz; s.v *= keep; },
      trail: () => this.trail(`u${u.uid}`),
    };
  }

  /** Whether the crew has mustered: every helper and the player beside the load. */
  ready(): boolean {
    const L = this.sim.load;
    const p = this.host.player();
    if (!p) return false;
    const near = (x: number, z: number, r: number) => Math.hypot(x - L.x, z - L.z) <= r;
    if (!near(p.w.ox + p.state.x, p.w.oz + p.state.z, 8)) return false;
    return this.helpers.length >= this.min - 1 && this.helpers.every((u) => u.agent && near(u.agent.w.ox + u.agent.state.x, u.agent.w.oz + u.agent.state.z, 9));
  }

  /** The crew step is done: the next is the tow itself. */
  armTow(): void { if (this.phase === 'muster') this.phase = 'ready'; }

  update(dt: number, paused: boolean): void {
    if (this.phase === 'done') return;
    this.w = this.host.worldAt(this.from.cell[0], this.from.cell[1]);
    this.group.visible = !!this.w;
    if (!this.w) return;
    this.sayCool -= dt;
    const L = this.sim.load;
    const p = this.host.player();
    if (!this.calledIn && p && Math.hypot(p.w.ox + p.state.x - L.x, p.w.oz + p.state.z - L.z) <= CALL_R) this.callCrew();
    const me = this.local.hitch();
    // hitching up: stopped beside the load, Enter (the start prompt, game/startPrompt.ts, for as long as it would)
    const hitch = `tow${this.id}`;
    if (!paused && (this.phase === 'ready' || this.phase === 'towing') && p && me && !this.sim.hitched('me')) {
      const close = Math.hypot(me.x - L.x, me.z - L.z) <= HITCH_R && Math.abs(p.state.v) < 0.8;
      if (close) startPrompt.show(hitch, { key: 'Enter', title: this.phase === 'ready' ? 'Tow · hitch up' : 'Tow · back on the rope', action: 'put your rope on', sub: `Then drag it to ${this.to.name}` });
      else startPrompt.hide(hitch);
      if (close && this.host.go()) {
        startPrompt.hide(hitch);
        this.local.pull = pullOf(p.def as never);
        this.sim.hitch(this.local);
        if (this.phase === 'ready') {
          // the load's weight is set now, from who is pulling it: more than any one of you, less than all
          const pulls = [this.local.pull, ...this.helpers.map((u) => pullOf(this.host.defFor(u) as never))];
          L.need = needFor(pulls);
          this.phase = 'towing';
          this.host.say('Hitched', this.helpers.length ? `Drive off gently · your crew hitches beside you` : 'Drive off gently');
        }
      }
    }
    // Enter on the rope slips it: a way off a load that has stuck fast, whatever the rope is doing
    else if (!paused && this.phase === 'towing' && this.sim.hitched('me') && this.host.go()) {
      this.sim.unhitch('me');
      this.host.say('Rope off', 'Back up to the load and Enter to hitch again');
    }
    // the load is solid: a car that drives into it is stopped against it
    if (p) this.shove(p.w.ox + p.state.x, p.w.oz + p.state.z, halfSize(p.def)[1], (dx, dz) => { p.state.x += dx; p.state.z += dz; p.state.v *= 0.5; });
    const pullers: Puller[] = [this.local];
    for (const u of this.helpers) {
      const q = this.pullerFor(u);
      if (!q) continue;
      pullers.push(q);
      // a helper puts its own rope on (and back on) once it is near enough and you are hitched
      if (this.phase === 'towing' && !this.sim.hitched(q.id)) {
        const h = q.hitch();
        if (h && Math.hypot(h.x - L.x, h.z - L.z) <= HITCH_R + 0.6) this.sim.hitch(q);
      }
    }
    if (!paused && this.phase === 'towing') {
      for (const q of pullers) this.drop(q.id, q.hitch());
      const r = this.sim.step(dt, pullers);
      if (r.snapped.length) {
        this.host.crack();
        if (r.snapped.includes('me')) this.host.say('The rope snapped', 'Back up to the load and Enter to hitch again');
      }
      if (r.stopped && this.sayCool <= 0 && Math.hypot(L.vx, L.vz) < 0.05 && this.sim.hitched('me')) {
        this.sayCool = 5;
        this.host.say('Stuck', `${r.stopped} · back it off that, or Enter to slip your rope`);
      }
      if (Math.hypot(L.x - this.to.x, L.z - this.to.z) <= DROP_R) {
        this.phase = 'done';
        this.result = { ok: true };
      }
    }
    this.render(pullers);
  }

  /** Push a vehicle at (x, z) world tiles,  tiles wide, out of the load. */
  private shove(x: number, z: number, r: number, move: (dx: number, dz: number) => void): void {
    const L = this.sim.load;
    const dx = x - L.x, dz = z - L.z, d = Math.hypot(dx, dz), reach = LOAD_R * MESH_SCALE * 1.4 + r;
    if (d >= reach || d < 1e-4) return;
    move((dx / d) * (reach - d), (dz / d) * (reach - d));
  }

  private render(pullers: Puller[]): void {
    const w = this.w!;
    const L = this.sim.load;
    const y = heightAt(w, L.x - w.ox, L.z - w.oz);
    this.mesh.position.set(L.x, y, L.z);
    this.mesh.rotation.y = L.heading;
    this.ring.place(this.to.x, this.to.z, laidGroundOf((cx, cz) => this.host.worldAt(cx, cz)));
    this.ring.mesh.visible = this.phase !== 'muster';
    // one rope per hitched puller: sagging when slack, straight and reddening as it takes the strain
    for (const q of pullers) {
      const rope = this.sim.ropes.get(q.id);
      let mesh = this.ropes.get(q.id);
      const h = q.hitch();
      if (!rope || !rope.on || !h) { if (mesh) mesh.visible = false; continue; }
      const a = this.sim.anchor(h.x, h.z);
      const hy = this.heightAt(h.x, h.z) + 0.12, ay = y + 0.18;
      const d = Math.hypot(h.x - a.x, h.z - a.z);
      const sag = Math.max(0, ROPE - d) * 0.25 + (1 - rope.tension) * 0.08;
      const curve = new THREE.QuadraticBezierCurve3(new THREE.Vector3(a.x, ay, a.z), new THREE.Vector3((a.x + h.x) / 2, (ay + hy) / 2 - sag, (a.z + h.z) / 2), new THREE.Vector3(h.x, hy, h.z));
      const geo = new THREE.TubeGeometry(curve, 10, 0.035, 5, false);
      if (!mesh) {
        mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: 0xc9a86a, roughness: 0.9 }));
        this.group.add(mesh);
        this.ropes.set(q.id, mesh);
      } else { mesh.geometry.dispose(); mesh.geometry = geo; }
      mesh.visible = true;
      (mesh.material as THREE.MeshStandardMaterial).color.setRGB(0.79 + 0.2 * rope.tension, 0.66 - 0.45 * rope.tension, 0.42 - 0.3 * rope.tension);
    }
  }

  private heightAt(x: number, z: number): number {
    const w = this.host.worldAt(Math.floor(x / N), Math.floor(z / N));
    return w ? heightAt(w, x - w.ox, z - w.oz) : 0;
  }

  /** Where the load is now, for the tracker. */
  where(): { x: number; z: number } { return { x: this.sim.load.x, z: this.sim.load.z }; }
  get over(): { ok: boolean } | null { return this.result; }
  get hitched(): boolean { return this.sim.hitched('me'); }

  dispose(): void {
    startPrompt.hide(`tow${this.id}`);
    this.host.harness(null);
    for (const u of this.helpers) if (!this.was.get(u.uid)) this.host.follow(u, false);
    this.scene.remove(this.group);
    disposeGroup(this.mesh);
    for (const m of this.ropes.values()) { m.geometry.dispose(); (m.material as THREE.Material).dispose(); }
    this.ring.dispose();
  }
}
