  k.cyl(x, y + 0.11 * s, z, 0.04 * s, 0.01 * s, DARK, 8);
  const a: P3 = [x - 0.26 * s, y + 0.13 * s, z + 0.16 * s], b: P3 = [x + 0.26 * s, y + 0.13 * s, z - 0.16 * s];
