const BONE = hex(0xefe6cf);
const skeleton: IconDraw = (k, x, y, z, s) => {
  // a long-necked dinosaur's bones on a low plinth, walking toward +x
  const P = (u: number, v: number, w = 0): P3 => [x + u * s, y + v * s, z + w * s];
  const r = 0.018 * s;
  k.box(x, y, z, 0.95 * s, 0.03 * s, 0.26 * s, DARK);
  const spine: P3[] = [P(-0.58, 0.12), P(-0.48, 0.2), P(-0.36, 0.28), P(-0.22, 0.34), P(0, 0.36), P(0.14, 0.36), P(0.24, 0.46), P(0.31, 0.6), P(0.35, 0.72)];
  for (let i = 0; i + 1 < spine.length; i++) {
    const t = i / (spine.length - 1);
    k.bar(spine[i], spine[i + 1], r * (i < 3 ? 0.5 + t * 1.5 : 1), BONE);
    if (i > 1) ball(k, spine[i][0], spine[i][1], spine[i][2], r * 1.4, BONE, 6, 3);
  }
  k.box(x + 0.39 * s, y + 0.71 * s, z, 0.11 * s, 0.05 * s, 0.05 * s, BONE);
  for (let i = 0; i < 5; i++) k.hoop(x + (-0.2 + i * 0.075) * s, y + 0.27 * s, z, 0.085 * s, 0.008 * s, BONE, 10, 'zy');
  for (const lx of [-0.2, 0.1]) for (const sz of [-1, 1]) {
    k.bar(P(lx, 0.32, sz * 0.06), P(lx + 0.02, 0.15, sz * 0.07), r * 1.2, BONE);
    k.bar(P(lx + 0.02, 0.15, sz * 0.07), P(lx - 0.01, 0.03, sz * 0.07), r, BONE);
  }
};

