const recycle: IconDraw = (k, x, y, z, s) => {
  // three green arrows chasing one another round a white disc, laid on the roof
  const col = hex(0x2f9b4a), R = 0.22 * s, yy = y + 0.012;
  k.cyl(x, y, z, 0.38 * s, 0.012, WHITE, 18);
  const corner = (i: number): [number, number] => {
    const a = Math.PI / 2 + (i * TAU) / 3;
    return [x + Math.cos(a) * R, z - Math.sin(a) * R];
  };
  for (let i = 0; i < 3; i++) {
    const [ax, az] = corner(i), [bx, bz] = corner(i + 1);
    const ux = bx - ax, uz = bz - az, L = Math.hypot(ux, uz), dx = ux / L, dz = uz / L, nx = -dz, nz = dx;
    const from: [number, number] = [ax + dx * 0.08 * s, az + dz * 0.08 * s], to: [number, number] = [bx - dx * 0.2 * s, bz - dz * 0.2 * s];
    const hw = 0.035 * s;
    plate(k, [[from[0] + nx * hw, from[1] + nz * hw], [to[0] + nx * hw, to[1] + nz * hw], [to[0] - nx * hw, to[1] - nz * hw], [from[0] - nx * hw, from[1] - nz * hw]], yy, 0.015, col);
    const tip: [number, number] = [bx - dx * 0.06 * s, bz - dz * 0.06 * s], hh = 0.08 * s;
    plate(k, [[to[0] + nx * hh, to[1] + nz * hh], tip, [to[0] - nx * hh, to[1] - nz * hh]], yy, 0.015, col);
  }
};

