const BOOT = hex(0x26282e);
const skate: IconDraw = (k, x, y, z, s) => {
  k.within(x, z, 0.5, () => {
    k.box(0, y, 0, 0.44 * s, 0.03 * s, 0.025 * s, hex(0xdfe6ee));
    k.bar([0.22 * s, y + 0.015 * s, 0], [0.26 * s, y + 0.06 * s, 0], 0.014 * s, hex(0xdfe6ee));
    for (const px of [-0.12, 0.14]) k.box(px * s, y + 0.03 * s, 0, 0.04 * s, 0.04 * s, 0.03 * s, METAL);
    const by = y + 0.07 * s;
    k.box(-0.08 * s, by, 0, 0.15 * s, 0.28 * s, 0.15 * s, BOOT);
    k.box(0.06 * s, by, 0, 0.3 * s, 0.1 * s, 0.15 * s, BOOT);
    k.box(-0.08 * s, by + 0.27 * s, 0, 0.17 * s, 0.04 * s, 0.17 * s, WHITE);
    for (let i = 0; i < 4; i++) k.box((0.08 - i * 0.045) * s, by + (0.1 + (i > 1 ? (i - 1) * 0.06 : 0)) * s, 0, 0.014 * s, 0.014 * s, 0.155 * s, REDS);
  });
};

const basketball: IconDraw = (k, x, y, z, s) => {
  const r = 0.3 * s, seam = hex(0x2a1a10), R = r * 1.012;
  ball(k, x, y, z, r, hex(0xe8742a), 14, 6, r, undefined, true);
  const n = 10;
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI, a1 = ((i + 1) / n) * Math.PI;
    k.bar([x + Math.cos(a0) * R, y + Math.sin(a0) * R, z], [x + Math.cos(a1) * R, y + Math.sin(a1) * R, z], 0.008 * s, seam);
    k.bar([x, y + Math.sin(a0) * R, z + Math.cos(a0) * R], [x, y + Math.sin(a1) * R, z + Math.cos(a1) * R], 0.008 * s, seam);
  }
  const ry = Math.sin(Math.PI / 4) * R;
  k.hoop(x, y + ry, z, Math.cos(Math.PI / 4) * R, 0.008 * s, seam, 16, 'xz');
};

