import type { Happening } from './calendar';
import { placeOf } from './venues';
import { CarShow, MotorcadeShow, NewYearShow, ParadeShow, type Show, type ShowCtx } from './shows';
import { AirShowShow, BoatParadeShow, LightShowShow, MilitaryParadeShow, PrideShow, RegattaShow, SpookyNightShow, TallShipsShow, WinterLightsShow } from './shows2';
import { DragonBoatsShow, DriftShow, GondolaShow, PowerboatShow, RallyShow } from './shows3';
import { phase4Show } from './shows4';
import { phase4bShow } from './shows5';
import { SwimMeetShow } from './swimMeet';
import { ChristmasMarketShow, FarmersMarketShow } from './markets';

/** Put an event on stage (docs/events.html): the show for its kind, in its county as it stands. Null when it has nowhere to happen there. */
export function stageShow(e: Happening, ctx: ShowCtx): Show | null {
  if (e.kind === 'motorcade' || e.kind === 'truckConvoy') return new MotorcadeShow(e, ctx);
  const w = ctx.worldAt(e.cx, e.cz);
  if (!w) return null;
  const p = placeOf(w, e);
  if (!p) return null;
  switch (e.kind) {
    case 'parade': return new ParadeShow(e, ctx, w, p);
    case 'carShow': return new CarShow(e, ctx, w, p);
    case 'newYear': return new NewYearShow(e, ctx, w, p);
    case 'regatta': return new RegattaShow(e, ctx, w, p);
    case 'boatParade': return new BoatParadeShow(e, ctx, w, p);
    case 'militaryParade': return new MilitaryParadeShow(e, ctx, w, p);
    case 'pride': return new PrideShow(e, ctx, w, p);
    case 'airShow': return new AirShowShow(e, ctx, w, p);
    case 'tallShips': return new TallShipsShow(e, ctx, w, p);
    case 'lightShow': return new LightShowShow(e, ctx, w, p);
    case 'winterLights': return new WinterLightsShow(e, ctx, w, p);
    case 'spookyNight': return new SpookyNightShow(e, ctx, w, p);
    case 'offroadRace': return new RallyShow(e, ctx, w, p);
    case 'powerboatRace': return new PowerboatShow(e, ctx, w, p);
    case 'driftMeet': return new DriftShow(e, ctx, w, p);
    case 'dragonBoats': return new DragonBoatsShow(e, ctx, w, p);
    case 'gondolaRegatta': return new GondolaShow(e, ctx, w, p);
    case 'swimMeet': return new SwimMeetShow(e, ctx, w, p);
    case 'farmersMarket': return p.market ? new FarmersMarketShow(e, ctx, w, p) : null;
    case 'christmasMarket': return p.market ? new ChristmasMarketShow(e, ctx, w, p) : null;
    default: return phase4Show(e, ctx, w, p) ?? phase4bShow(e, ctx, w, p);
  }
}
