/**
 * Supply chains (docs/supplychains.html): the recipe book. A building the player owns whose kind is in here is a
 * plant. A base recipe (no `takes`) makes on its clock alone; the others wait for a full set of their inputs in the
 * plant's bins, then run. A kind may hold two recipes: the first whose set is in the bins runs (a print shop with
 * footage in hand prints a special edition, otherwise stationery). One of `makes` is drawn per run by weight, and
 * each of `also` is made alongside with its chance. Hours are at an HQ grade 3–4 building and scale by grade.
 *
 * No step involves a jet (the user, 7 Nov 2026): no recipe makes for an airport, and nothing a plant does helps one.
 */

export interface Slot {
  /** Any one of these cargo ids fills the slot (wool or cotton both make cloth). */
  ids: string[];
  /** Units of it a run takes. */
  n: number;
}

export interface Recipe {
  kind: string;
  takes: Slot[];
  makes: { id: string; w: number }[];
  also?: { id: string; chance: number }[];
  hours: number;
  chain: number;
}

