/** Constants the gate and the bench tune (docs/supplychains.html, "Clocks and rates"). */
export const CHAINS = {
  /** Made loads waiting at one door at most; the clock holds at a full stock. */
  stock: 3,
  /** Runs' worth of an input a bin holds. */
  binRuns: 3,
  /** Hours scale by the plant's HQ grade: a steelworks is quicker than a croft. Ungraded (scenery) runs as grade 2. */
  gradeMul: [1.3, 1.3, 1.3, 1, 1, 0.75, 0.75, 0.75] as const,
  /** A base plant set to make one kind only runs this much slower. */
  setMul: 1.25,
  /** Each step of the fleet's own making behind a load adds this to its value, to `pedigreeCap` steps. */
  pedigree: 0.2,
  pedigreeCap: 3,
  /** The making plant's share of a made load's value when anybody delivers it. */
  makerFee: 0.15,
  /** A plant's maker's fees in a game day go no higher than this many times its deed's rent ceiling (price/9): price/3. */
  feeCeil: 3,
  /** Uncollected this many of its plant's periods, the oldest made load opens to the island's haulers. */
  openAfter: 1,
  /** Time an opened load waits for anybody before it goes, in seconds. */
  openTtl: 240,
};

const R = (kind: string, takes: [string[], number][], makes: [string, number][], hours: number, chain: number, also?: [string, number][]): Recipe => ({
  kind, takes: takes.map(([ids, n]) => ({ ids, n })), makes: makes.map(([id, w]) => ({ id, w })), hours, chain,
  ...(also ? { also: also.map(([id, chance]) => ({ id, chance })) } : {}),
});
const base = (kind: string, makes: [string, number][], hours: number, chain: number): Recipe => R(kind, [], makes, hours, chain);

