/** The new kinds the chains bring with 0.8.0 (world/plants.ts places them behind NEXT_080). */
export const NEW_PLANT_KINDS = [
  'iceHouse', 'creamery', 'bindery', 'joinery', 'printShop', 'parcelHub', 'readyMix', 'smokehouse', 'winery', 'alloyWorks',
  'atelier', 'roastery', 'cooperage', 'glassworks', 'auctionHouse', 'luthier', 'outfitter',
] as const;
export type NewPlantKind = (typeof NEW_PLANT_KINDS)[number];

/**
 * A recipe as this build runs it: ids this world has no cargo for (the 0.8.0 works' goods with that world off)
 * are dropped from a slot, a slot left with none drops the recipe, and so does a recipe that makes nothing here.
 */
function live(r: Recipe): Recipe | null {
  const has = (id: string) => !!cargoById(id);
  const takes = r.takes.map((s) => ({ ids: s.ids.filter(has), n: s.n }));
  if (takes.some((s) => !s.ids.length)) return null;
  const makes = r.makes.filter((m) => has(m.id));
  if (!makes.length) return null;
  const also = r.also?.filter((a) => has(a.id));
  return { ...r, takes, makes, ...(also?.length ? { also } : { also: undefined }) };
}

let byKind: Map<string, Recipe[]> | null = null;
/** Every live recipe, by building kind, in the book's order. */
export function recipeBook(): Map<string, Recipe[]> {
  if (byKind) return byKind;
  byKind = new Map();
  for (const raw of BOOK) {
    // the commonest buildings (HQ grade 1, Lodging: townhouses, houses, flats…) are no part of the chains: there are
    // too many of them for a plant to be anything (the user, 11 Nov 2026, townhouses making antiques)
    if (kindGrade(raw.kind as BuildingKind) === 1) continue;
    const r = live(raw);
    if (!r) continue;
    const l = byKind.get(r.kind) ?? [];
    l.push(r);
    byKind.set(r.kind, l);
  }
  return byKind;
}

/** A kind's recipes (empty when it is no plant). */
export const recipesOf = (kind: string): Recipe[] => recipeBook().get(kind) ?? [];
export const isPlantKind = (kind: string): boolean => recipesOf(kind).length > 0;

/** The raw book, for the gate. */
export const RAW_BOOK: readonly Recipe[] = BOOK;

/** Every cargo id a kind's recipes take in. */
export function inputsOf(kind: string): Set<string> {
  const out = new Set<string>();
  for (const r of recipesOf(kind)) for (const s of r.takes) for (const id of s.ids) out.add(id);
  return out;
}

/** Every cargo id a kind can make (outputs and byproducts). */
export function outputsOf(kind: string): string[] {
  const out = new Set<string>();
  for (const r of recipesOf(kind)) { for (const m of r.makes) out.add(m.id); for (const a of r.also ?? []) out.add(a.id); }
  return [...out];
}

/** The kinds whose recipes take this cargo id in: where a made load of it would rather go. */
export function takersOf(id: string): string[] {
  const out: string[] = [];
  for (const [kind, rs] of recipeBook()) if (rs.some((r) => r.takes.some((s) => s.ids.includes(id)))) out.push(kind);
  return out;
}

/** A run's length in game hours at a building of this HQ grade (0 for scenery), set to one kind or not. */
export function hoursOf(r: Recipe, grade: number, set: boolean): number {
  const g = Math.max(0, Math.min(7, grade));
  return r.hours * CHAINS.gradeMul[g] * (set && !r.takes.length ? CHAINS.setMul : 1);
}

/** Pedigree's value multiplier for a load with this many steps of the fleet's own making behind it. */
export const pedigreeMul = (steps: number): number => 1 + CHAINS.pedigree * Math.min(CHAINS.pedigreeCap, Math.max(0, steps));
