import { hex, scale, type RGB } from '../../world/biomes';
import type { WildKind } from '../../world/wildKinds';
import type { Sched } from '../nightLights';
import { COOL_GLOW, DARK, GLASS_LIGHT, TAU, WARM_GLOW, WATER, WHITE, tree, type Draw, type Kit, type P3 } from './kit';

/**
 * The strange and the lonely: things a driver finds far out past the last town with nobody near them and no
 * reason given. A black slab on scorched ground, a phone box in the grass, a vending machine humming to
 * itself, a door on a hill, a piano in a meadow, a chair for a giant. Most of it is unlit; what does light
 * up after dark lights up for nobody.
 */

const GAP = hex(0x15120f), DIRT = hex(0xa98a5c), SCORCH = hex(0x2c2825), SCORCH2 = hex(0x3a332c);
const ROCK = hex(0x766c60), ROCK_DARK = hex(0x5c554c), STONE = hex(0x85837b), STONE_DARK = hex(0x696760);
const BONE = hex(0xe6dfcc), CONCRETE = hex(0xa3a596), CONCRETE_DARK = hex(0x85877a);
const GRASS = hex(0x7f9a52), GRASS_TOP = hex(0x88a45a), BUSH = hex(0x4f8a45), LEAF_DARK = hex(0x3f7040);
const SLAB = hex(0x0c0c10), SLAB_TOP = hex(0x1c1d24);
const POST_RED = hex(0xc0201c), POST_RED_DARK = hex(0x9a1814), CROWN = hex(0xd9b23c);
const TIMBER = hex(0x5e4a38), TIMBER_DARK = hex(0x4a3a2c), BRASS = hex(0xc9a24a);
const PIANO = hex(0x141416), PIANO_SIDE = hex(0x1f1f23), HARP = hex(0xa88440), KEYS = hex(0xf2efe4);
const OAK = hex(0xb07a44), OAK_TOP = hex(0xc48c54), OAK_DARK = hex(0x8c5e34);
const BARK = hex(0x6a5d50), BARK_DARK = hex(0x544a40);
const FUR = hex(0x5a3e2a), FUR_DARK = hex(0x46301f), FUR_FACE = hex(0x8a6a4c);
const DUCK = hex(0xf6cf2a), DUCK_TOP = hex(0xffdc3a), DUCK_WING = hex(0xe8b81e), BEAK = hex(0xf07a20);
const SAND_WET = hex(0xcdbb88);
/** On from dusk until dawn: the one light out here, for nobody. */
const ALL_NIGHT: Sched = [18.5, 30, 1.2];
const EVENING: Sched = [18, 23.5, 1.4];

// ---- shapes the kit has no word for (as in finds.ts) -------------------------------------------------

/** A frame of its own inside the lot: turned, rolled (the +x end rises) and pitched (the top leans to +z). */
type Xf = (p: P3) => P3;

function frame(o: P3, yaw = 0, roll = 0, pitch = 0): Xf {
  const cr = Math.cos(roll), sr = Math.sin(roll), cp = Math.cos(pitch), sp = Math.sin(pitch), cy = Math.cos(yaw), sy = Math.sin(yaw);
  return ([x, y, z]) => {
    const x1 = x * cr - y * sr, y1 = x * sr + y * cr;
    const y2 = y1 * cp - z * sp, z2 = y1 * sp + z * cp;
    return [o[0] + x1 * cy + z2 * sy, o[1] + y2, o[2] - x1 * sy + z2 * cy];
  };
}

/** `k.box` in a frame: for anything that leans, swings or hangs. All six faces are drawn. */
function fbox(k: Kit, f: Xf, x: number, y: number, z: number, w: number, h: number, d: number, col: RGB, top: RGB = col): void {
  const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, y1 = y + h;
  const I = f([x, y + h / 2, z]);
  const q = (a: P3, b: P3, c: P3, e: P3, cl: RGB) => k.quad(f(a), f(b), f(c), f(e), cl, I);
  q([x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1], top);
  q([x0, y, z0], [x1, y, z0], [x1, y, z1], [x0, y, z1], col);
  q([x0, y, z1], [x1, y, z1], [x1, y1, z1], [x0, y1, z1], col);
  q([x0, y, z0], [x1, y, z0], [x1, y1, z0], [x0, y1, z0], col);
  q([x1, y, z0], [x1, y, z1], [x1, y1, z1], [x1, y1, z0], col);
  q([x0, y, z0], [x0, y, z1], [x0, y1, z1], [x0, y1, z0], col);
}

/** A round tube from a to b, radius r0 at a and r1 at b (either may be nothing), capped at both ends. */
function tube(k: Kit, a: P3, b: P3, r0: number, r1: number, col: RGB, seg = 8, capA: RGB = col, capB: RGB = capA): void {
  const dx = b[0] - a[0], dy = b[1] - a[1], dz = b[2] - a[2];
  const len = Math.hypot(dx, dy, dz);
  if (len < 1e-5) return;
  const ux = dx / len, uy = dy / len, uz = dz / len;
  let px = -uz, py = 0, pz = ux;
  let pl = Math.hypot(px, py, pz);
  if (pl < 1e-4) { px = 1; py = 0; pz = 0; pl = 1; }
  px /= pl; py /= pl; pz /= pl;
  const qx = uy * pz - uz * py, qy = uz * px - ux * pz, qz = ux * py - uy * px;
  const at = (o: P3, rr: number, ang: number): P3 => {
    const c = Math.cos(ang) * rr, s = Math.sin(ang) * rr;
    return [o[0] + px * c + qx * s, o[1] + py * c + qy * s, o[2] + pz * c + qz * s];
  };
  const mid: P3 = [a[0] + dx / 2, a[1] + dy / 2, a[2] + dz / 2];
  for (let i = 0; i < seg; i++) {
    const a0 = (i / seg) * TAU, a1 = ((i + 1) / seg) * TAU;
    const p0 = at(a, r0, a0), p1 = at(a, r0, a1), p2 = at(b, r1, a1), p3 = at(b, r1, a0);
    if (r0 > 0 && r1 > 0) k.quad(p0, p1, p2, p3, col, mid);
    else if (r0 > 0) k.tri(p0, p1, b, col, mid);
    else k.tri(a, p2, p3, col, mid);
    if (r0 > 0) k.tri(a, p0, p1, capA, mid);
    if (r1 > 0) k.tri(b, p3, p2, capB, mid);
  }
}

/** A faceted ball: a bush, a knob, a head. */
function ball(k: Kit, x: number, y: number, z: number, rr: number, col: RGB): void {
  k.dome(x, y + rr, z, rr, col, 6, 2);
  k.cone(x, y + rr, z, rr, -rr, scale(col, 0.86), 6);
}

/** A whole faceted ellipsoid about (cx, cy, cz): a rubber duck's body, its head, its beak. */
function blob(k: Kit, cx: number, cy: number, cz: number, rx: number, ry: number, rz: number, col: RGB, seg = 10, rings = 6, top: RGB = col): void {
  const I: P3 = [cx, cy, cz];
  const pt = (lat: number, lon: number): P3 => [cx + Math.cos(lat) * Math.cos(lon) * rx, cy + Math.sin(lat) * ry, cz + Math.cos(lat) * Math.sin(lon) * rz];
  for (let j = 0; j < rings; j++) {
    const l0 = -Math.PI / 2 + (j / rings) * Math.PI, l1 = -Math.PI / 2 + ((j + 1) / rings) * Math.PI;
    const cl = j >= rings / 2 ? top : col;
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
      if (j === 0) k.tri(pt(l0, 0), pt(l1, a0), pt(l1, a1), cl, I);
      else if (j === rings - 1) k.tri(pt(l0, a0), pt(l0, a1), pt(l1, 0), cl, I);
      else k.quad(pt(l0, a0), pt(l0, a1), pt(l1, a1), pt(l1, a0), cl, I);
    }
  }
}

/** A flat outline (x, z) stood up from y0 to y1 in a frame: a grand piano's case and its lid. */
function prism(k: Kit, f: Xf, pts: [number, number][], y0: number, y1: number, side: RGB, top: RGB, bottom: RGB = side): void {
  const n = pts.length;
  let area = 0, cx = 0, cz = 0;
  for (let i = 0; i < n; i++) {
    const [ax, az] = pts[i], [bx, bz] = pts[(i + 1) % n];
    area += ax * bz - bx * az;
    cx += ax / n; cz += az / n;
  }
  const sgn = area > 0 ? 1 : -1, ym = (y0 + y1) / 2;
  for (let i = 0; i < n; i++) {
    const [ax, az] = pts[i], [bx, bz] = pts[(i + 1) % n];
    // a point just inside this edge, so a concave side is wound the right way too
    const ex = bx - ax, ez = bz - az, el = Math.hypot(ex, ez) || 1;
    const ix = (ax + bx) / 2 - (sgn * ez) / el * 0.01, iz = (az + bz) / 2 + (sgn * ex) / el * 0.01;
    k.quad(f([ax, y0, az]), f([bx, y0, bz]), f([bx, y1, bz]), f([ax, y1, az]), side, f([ix, ym, iz]));
    k.tri(f([cx, y1, cz]), f([ax, y1, az]), f([bx, y1, bz]), top, f([cx, y1 - 0.01, cz]));
    k.tri(f([cx, y0, cz]), f([ax, y0, az]), f([bx, y0, bz]), bottom, f([cx, y0 + 0.01, cz]));
  }
}

/** Letters across a face looking along +z in frame f, centred on (x, y) at depth z: spaces are left out. */
function letters(k: Kit, f: Xf, text: string, x: number, y: number, z: number, cw: number, ch: number, col: RGB): void {
  const x0 = x - (text.length * cw) / 2;
  [...text].forEach((c, i) => {
    if (c === ' ') return;
    const a = x0 + i * cw, b = a + cw * 0.9;
    k.glyph(c, f([a, y, z]), f([b, y, z]), f([b, y + ch, z]), f([a, y + ch, z]), col);
  });
}

/** Somebody about 1.8 m tall, for scale: legs, a coat, a head. */
function person(k: Kit, x: number, z: number, yaw: number, coat: RGB): void {
  const f = frame([x, 0, z], yaw);
  fbox(k, f, 0, 0, 0, 0.032, 0.05, 0.018, hex(0x2e3440));
  fbox(k, f, 0, 0.05, 0, 0.038, 0.045, 0.022, coat);
  const h = f([0, 0.095, 0]);
  ball(k, h[0], h[1], h[2], 0.012, hex(0xd9a982));
}

const ID: Xf = (p) => p;

// ---- monolith (1 × 1) --------------------------------------------------------------------------------

/** A black slab, one by four by nine, standing on scorched ground among broken rock and old bones. */
const monolith: Draw = (k, _W, _D, _b, r) => {
  k.cyl(0, 0, 0, 0.44, 0.008, SCORCH, 10);
  k.cyl(0, 0.008, 0, 0.26, 0.004, SCORCH2, 9);
  k.turned((r() - 0.5) * 0.6, () => {
    k.box(0, 0, 0, 0.54, 1.22, 0.135, SLAB, SLAB_TOP);
  });
  // rock split and thrown about, nothing growing
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU + r() * 0.5, d = 0.3 + r() * 0.12, s = 0.035 + r() * 0.035;
    fbox(k, frame([Math.cos(a) * d, 0.008, Math.sin(a) * d], r() * 3, (r() - 0.5) * 0.5), 0, 0, 0, s * 1.4, s * 0.8, s, i % 2 ? ROCK : ROCK_DARK);
  }
  // bones: a long one, a short one, a skull
  const bone = (a: P3, b: P3) => {
    k.bar(a, b, 0.008, BONE);
    for (const e of [a, b]) ball(k, e[0], 0.012, e[2], 0.012, BONE);
  };
  const bx = 0.12 + r() * 0.08;
  bone([bx, 0.024, 0.2], [bx + 0.12, 0.024, 0.28]);
  bone([-0.2, 0.024, 0.18], [-0.27, 0.024, 0.24]);
  ball(k, -0.12, 0.012, 0.3, 0.022, BONE);
  k.box(-0.12, 0.016, 0.322, 0.024, 0.012, 0.004, GAP);
};

// ---- phone box (1 × 1) -------------------------------------------------------------------------------

/** A red telephone box alone in the grass, its door at the end of a path worn by somebody, lit inside at night. */
const phoneBox: Draw = (k, _W, _D, _b, r) => {
  k.turned((r() - 0.5) * 0.5, () => {
    // the path worn to its door
    k.box(0, 0.001, 0.29, 0.08, 0.005, 0.36, DIRT);
    k.box(0, 0, 0, 0.21, 0.03, 0.21, CONCRETE, CONCRETE_DARK);
    const H0 = 0.03, H1 = 0.42, F = 0.085;
    k.box(0, H0, 0, 0.17, H1 - H0, 0.17, POST_RED);
    for (let i = 0; i < 4; i++) {
      k.turned(i * (Math.PI / 2), () => {
        // the glazing, lit from within, and its bars
        k.pane(0, 0.12, F, 0.12, 0.25, 1, GLASS_LIGHT, EVENING, WARM_GLOW);
        const z = F + 0.009;
        for (const x of [-0.02, 0.02]) k.box(x, 0.12, z, 0.007, 0.25, 0.008, POST_RED_DARK);
        for (let j = 1; j < 6; j++) k.box(0, 0.12 + (j * 0.25) / 6, z, 0.12, 0.006, 0.008, POST_RED_DARK);
        // the strip that says what it is
        letters(k, ID, 'TELEPHONE', 0, H1 + 0.007, F + 0.0035, 0.016, 0.02, hex(0x222222));
        if (i === 0) k.box(0.068, 0.24, F + 0.008, 0.012, 0.03, 0.01, DARK);
      });
    }
    k.glowBox(0, H1, 0, 0.17, 0.034, 0.17, hex(0xeeeadb), EVENING, WARM_GLOW);
    // the roof, stepped, and its little crown
    k.box(0, H1 + 0.034, 0, 0.19, 0.022, 0.19, POST_RED, POST_RED_DARK);
    k.box(0, H1 + 0.056, 0, 0.14, 0.018, 0.14, POST_RED);
    k.box(0, H1 + 0.074, 0, 0.03, 0.012, 0.03, CROWN);
  });
  for (let i = 0; i < 4; i++) ball(k, (r() - 0.5) * 0.7, 0, -0.25 - r() * 0.15, 0.025 + r() * 0.02, i % 2 ? GRASS : BUSH);
};

// ---- vending machine (1 × 1) -------------------------------------------------------------------------

/** A drinks machine on a scrap of concrete, a cable off a pole and a bin beside it: lit all night for nobody. */
const lonelyVending: Draw = (k, _W, _D, _b, r) => {
  const brands = [0xc8282e, 0x2a5fb0, 0xe8e8e4, 0x2f8a4a, 0xe0802a];
  const brand = hex(brands[Math.floor(r() * brands.length)]);
  const pale = brand[0] + brand[1] + brand[2] > 2.2;
  k.box(0, 0, -0.04, 0.5, 0.03, 0.4, CONCRETE, CONCRETE_DARK);
  // the pool of light it throws on the slab
  k.glowBox(0, 0.03, 0.08, 0.3, 0.004, 0.16, CONCRETE, ALL_NIGHT, scale(COOL_GLOW, 0.45));
  const mz = -0.1, F = mz + 0.09, Y = 0.03;
  k.box(0, Y, mz, 0.24, 0.38, 0.18, brand, scale(brand, 0.8));
  k.box(0, Y + 0.38, mz, 0.25, 0.012, 0.19, DARK);
  // the window full of cans, its shelves, the cans themselves
  k.pane(-0.025, Y + 0.11, F, 0.17, 0.24, 1, hex(0xcfe3ee), ALL_NIGHT, COOL_GLOW);
  const cans = [0xd23a2e, 0xf2c230, 0x3a8ad8, 0xe8e8e4, 0x3f9b4a, 0xe86aa0];
  for (let row = 0; row < 3; row++) {
    const y = Y + 0.125 + row * 0.075;
    k.box(-0.025, y - 0.008, F + 0.012, 0.17, 0.006, 0.01, DARK);
    for (let i = 0; i < 4; i++) k.box(-0.09 + i * 0.043, y, F + 0.011, 0.02, 0.034, 0.008, hex(cans[Math.floor(r() * cans.length)]));
  }
  // the header, the buttons, the coin slot, the flap the can falls out of
  k.glowBox(0, Y + 0.355, F + 0.004, 0.22, 0.04, 0.012, pale ? hex(0xc8282e) : scale(brand, 1.25), ALL_NIGHT, pale ? hex(0xff6a5a) : WHITE);
  k.glowBox(0.085, Y + 0.13, F + 0.004, 0.036, 0.2, 0.02, hex(0x2a2e34), ALL_NIGHT, hex(0x9ff0ff));
  k.box(0.085, Y + 0.09, F + 0.006, 0.02, 0.025, 0.02, DARK);
  k.box(-0.025, Y + 0.03, F + 0.006, 0.17, 0.055, 0.02, GAP);
  // a bin, overflowing, and a can that missed
  k.cyl(0.19, 0.03, 0.02, 0.045, 0.1, hex(0x3d5a3e), 8, hex(0x2a2a2a));
  ball(k, 0.18, 0.11, 0.02, 0.03, hex(0xd8d4c8));
  k.cyl(0.13, 0.03, 0.14, 0.009, 0.03, hex(cans[Math.floor(r() * cans.length)]), 6);
  // the pole its power comes off, and the cable sagging across
  const px = -0.36, pz = -0.36, ph = 0.44;
  k.box(px, 0, pz, 0.03, ph, 0.03, TIMBER);
  k.box(px, ph - 0.05, pz, 0.14, 0.018, 0.022, TIMBER_DARK);
  k.box(px + 0.05, ph - 0.032, pz, 0.012, 0.016, 0.012, WHITE);
  const a: P3 = [px + 0.05, ph - 0.018, pz], b: P3 = [-0.08, Y + 0.37, mz - 0.09];
  const m: P3 = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2 - 0.045, (a[2] + b[2]) / 2];
  k.bar(a, m, 0.004, DARK);
  k.bar(m, b, 0.004, DARK);
  k.box(-0.08, Y + 0.25, mz - 0.096, 0.05, 0.08, 0.012, hex(0x8a8f92));
  for (let i = 0; i < 3; i++) ball(k, 0.25 + r() * 0.15, 0, -0.3 + r() * 0.15, 0.025 + r() * 0.015, GRASS);
};

// ---- door to nowhere (1 × 1) -------------------------------------------------------------------------

/** A painted front door in its frame on a hilltop, standing ajar on nothing, mat out, lamp on after dark. */
const doorToNowhere: Draw = (k, _W, _D, _b, r) => {
  const G = 0.04;
  k.band(0, 0, 0, 0.45, G - 0.004, 0.32, 10, GRASS);
  k.cyl(0, 0, 0, 0.32, G, GRASS_TOP, 10);
  const doors = [0x2f5f9a, 0xb8282a, 0x2f7a46, 0xf2c230, 0x1f2328, 0x7a3a8a];
  const DOOR = hex(doors[Math.floor(r() * doors.length)]), PANEL = scale(DOOR, 1.15);
  const FRAME_COL = hex(0xf0ede4);
  k.turned((r() - 0.5) * 0.7, () => {
    k.box(0, G, 0, 0.36, 0.025, 0.13, STONE, STONE);
    const y0 = G + 0.025, OH = 0.6;
    for (const s of [-1, 1]) k.box(s * 0.145, y0, 0, 0.04, OH, 0.06, FRAME_COL);
    k.box(0, y0 + OH, 0, 0.35, 0.045, 0.07, FRAME_COL);
    // the door, swung open toward you, hinged on the left
    const f = frame([-0.124, y0 + 0.004, 0], -(0.5 + r() * 0.7));
    const DW = 0.244, DH = 0.592;
    fbox(k, f, DW / 2, 0, 0, DW, DH, 0.03, DOOR);
    for (const sz of [-1, 1]) {
      for (const [px, py, ph] of [[0.065, 0.06, 0.22], [0.18, 0.06, 0.22], [0.065, 0.34, 0.2], [0.18, 0.34, 0.2]] as const) {
        fbox(k, f, px, py, sz * 0.021, 0.075, ph, 0.008, PANEL);
      }
      const kb = f([0.21, 0.29, sz * 0.027]);
      ball(k, kb[0], kb[1] - 0.012, kb[2], 0.012, BRASS);
    }
    fbox(k, f, DW / 2, 0.29, 0.02, 0.07, 0.016, 0.01, BRASS);
    letters(k, f, String(1 + Math.floor(r() * 99)), DW / 2, 0.47, 0.0255, 0.03, 0.04, BRASS);
    // the mat, the lamp by the door, a pot plant
    k.box(0, G, 0.16, 0.2, 0.008, 0.1, hex(0x8a6a3a), hex(0x9c7a44));
    k.box(-0.145, y0 + 0.43, 0.034, 0.012, 0.012, 0.008, DARK);
    k.glowBox(-0.145, y0 + 0.4, 0.046, 0.03, 0.05, 0.026, hex(0xe8dcb8), ALL_NIGHT, WARM_GLOW);
    k.cyl(0.24, G, 0.07, 0.035, 0.05, hex(0xb0603a), 8, hex(0x5a3a26));
    ball(k, 0.24, G + 0.04, 0.07, 0.045, BUSH);
  });
};

// ---- piano in a field (1 × 1) ------------------------------------------------------------------------

/** A black grand piano in a meadow, lid up, stool out, flowers growing round its legs. */
const fieldPiano: Draw = (k, _W, _D, _b, r) => {
  // the case outline: keyboard to +z, straight bass side at -x, the bentside curving in to the tail
  const P: [number, number][] = [
    [-0.15, 0.13], [0.15, 0.13], [0.15, 0.02], [0.115, -0.06], [0.07, -0.12], [0.045, -0.19], [0.02, -0.25], [-0.03, -0.28], [-0.1, -0.285], [-0.15, -0.25],
  ];
  const yaw = (r() - 0.5) * 0.8;
  k.turned(yaw, () => {
    const C0 = 0.125, C1 = 0.2;
    for (const [lx, lz] of [[-0.12, 0.1], [0.12, 0.1], [-0.07, -0.23]] as const) k.box(lx, 0, lz, 0.026, C0 + 0.004, 0.026, PIANO);
    prism(k, ID, P, C0, C1, PIANO_SIDE, HARP, PIANO);
    // the lid, up on its stick
    const lid = frame([-0.15, C1, 0], 0, 0.45);
    const L: [number, number][] = P.map(([x, z]) => [x + 0.15, z]);
    prism(k, lid, L, 0.004, 0.016, PIANO, PIANO_SIDE, PIANO_SIDE);
    k.bar([0.02, C1, -0.03], lid([0.17, 0.004, -0.03]), 0.005, PIANO);
    // the keys, the cheeks either side, the stand, the pedals
    k.box(0, C0 - 0.015, 0.165, 0.3, 0.05, 0.07, PIANO);
    k.box(0, C0 + 0.035, 0.168, 0.27, 0.012, 0.062, KEYS);
    for (let i = 0; i < 11; i++) {
      if (i === 2 || i === 6 || i === 9) continue;
      k.box(-0.125 + i * 0.025, C0 + 0.047, 0.153, 0.011, 0.008, 0.03, PIANO);
    }
    for (const s of [-1, 1]) k.box(s * 0.142, C0 + 0.035, 0.168, 0.016, 0.03, 0.066, PIANO);
    fbox(k, frame([0, C1, 0.115], 0, 0, -0.35), 0, 0, 0, 0.18, 0.07, 0.008, PIANO);
    k.box(0, 0, 0.11, 0.05, 0.11, 0.012, PIANO);
    k.box(0, 0.012, 0.13, 0.05, 0.006, 0.03, BRASS);
    // the stool
    const sz = 0.33;
    k.box(0, 0.075, sz, 0.12, 0.022, 0.07, PIANO, hex(0x2a2a30));
    for (const sx of [-1, 1]) for (const dz of [-1, 1]) k.box(sx * 0.05, 0, sz + dz * 0.025, 0.012, 0.075, 0.012, PIANO);
  });
  // flowers in the meadow, kept clear of the piano and the stool
  const cols = [0xf2f0ea, 0xf2c230, 0xe85a8a, 0x8e5cc7, 0xe2412f, 0x5d8ad8];
  for (let i = 0, n = 0; i < 60 && n < 22; i++) {
    const x = (r() - 0.5) * 0.88, z = (r() - 0.5) * 0.88;
    if (Math.abs(x) < 0.2 && z > -0.33 && z < 0.4) continue;
    n++;
    k.box(x, 0, z, 0.016, 0.03, 0.016, LEAF_DARK);
    k.box(x, 0.03, z, 0.024, 0.014, 0.024, hex(cols[Math.floor(r() * cols.length)]));
  }
  for (let i = 0; i < 4; i++) {
    const a = r() * TAU;
    ball(k, Math.cos(a) * 0.4, 0, Math.sin(a) * 0.4, 0.03 + r() * 0.02, GRASS);
  }
};

// ---- giant chair (1 × 1) -----------------------------------------------------------------------------

/** A kitchen chair, back to -z, standing 1.05 s tall: four legs, stretchers, a spindle back. */
function chair(k: Kit, x: number, z: number, s: number, col: RGB, top: RGB, dark: RGB): void {
  const SY = 0.46 * s, LX = 0.25 * s, LZ = 0.23 * s, T = 0.06 * s;
  k.box(x, SY, z, 0.6 * s, 0.05 * s, 0.56 * s, col, top);
  for (const sx of [-1, 1]) {
    k.box(x + sx * LX, 0, z + LZ, T, SY, T, dark);
    // the back legs run on up as the uprights
    k.box(x + sx * LX, 0, z - LZ, T, 1.0 * s, T, dark);
    k.box(x + sx * LX, 1.0 * s, z - LZ, T * 0.7, 0.05 * s, T * 0.7, col);
    k.bar([x + sx * LX, 0.15 * s, z - LZ], [x + sx * LX, 0.15 * s, z + LZ], 0.018 * s, dark);
  }
  k.bar([x - LX, 0.22 * s, z + LZ], [x + LX, 0.22 * s, z + LZ], 0.018 * s, dark);
  k.box(x, 0.86 * s, z - LZ, 0.52 * s, 0.1 * s, 0.045 * s, col, top);
  for (const sx of [-0.12, 0, 0.12]) k.box(x + sx * s, SY + 0.05 * s, z - LZ, 0.035 * s, 0.36 * s, 0.03 * s, col);
}

/** A chair for a giant, out on its own: a ladder up to the seat, an ordinary chair beneath it, somebody looking up. */
const giantChair: Draw = (k, _W, _D, _b, r) => {
  k.turned((r() - 0.5) * 0.6, () => {
    chair(k, 0, -0.04, 1, OAK, OAK_TOP, OAK_DARK);
    // the ordinary one, under it
    chair(k, -0.08, 0.02, 0.07, OAK, OAK_TOP, OAK_DARK);
    // the ladder somebody left against the seat
    const lz0 = 0.42, lz1 = 0.25, top = 0.5;
    for (const s of [-1, 1]) k.bar([0.12 + s * 0.04, 0, lz0], [0.12 + s * 0.04, top, lz1], 0.008, hex(0x9a9ea2));
    for (let i = 1; i < 7; i++) {
      const t = i / 7;
      k.bar([0.08, top * t, lz0 + (lz1 - lz0) * t], [0.16, top * t, lz0 + (lz1 - lz0) * t], 0.005, hex(0x9a9ea2));
    }
    person(k, -0.2, 0.36, Math.PI + 0.4, hex([0xc8282e, 0x2a5fb0, 0xf2c230][Math.floor(r() * 3)]));
  });
  for (let i = 0; i < 3; i++) ball(k, 0.3 + r() * 0.1, 0, -0.35 + i * 0.12, 0.03 + r() * 0.02, GRASS);
};

// ---- shoe tree (1 × 1) -------------------------------------------------------------------------------

/** A dead tree hung all over with shoes: pairs thrown up by their laces, a pile of odd ones at its foot. */
const shoeTree: Draw = (k, _W, _D, _b, r) => {
  const SHOES = [0xf0efe8, 0xd23a2e, 0x2f6fc0, 0x2a2a2e, 0xe86aa0, 0xf2c230, 0x3f9b4a, 0xf07a28, 0x8e5cc7, 0x7a5232];
  const shoe = () => hex(SHOES[Math.floor(r() * SHOES.length)]);
  k.cone(0, 0, 0, 0.1, 0.14, BARK_DARK, 7);
  const crown: P3 = [0.02, 0.5, 0];
  tube(k, [0, 0, 0], crown, 0.065, 0.042, BARK, 7);
  const hangs: P3[] = [];
  const along = (a: P3, b: P3, t: number): P3 => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
  const n = 5, spin = r() * TAU;
  for (let i = 0; i < n; i++) {
    const a = spin + (i / n) * TAU + (r() - 0.5) * 0.5;
    const s0: P3 = [crown[0], 0.4 + i * 0.025, crown[2]];
    const s1: P3 = [Math.cos(a) * 0.27, 0.8 + r() * 0.1, Math.sin(a) * 0.27];
    tube(k, s0, s1, 0.034, 0.018, BARK, 6);
    hangs.push(along(s0, s1, 0.6), along(s0, s1, 0.9));
    for (const da of [-0.4, 0.4]) {
      const t1: P3 = [Math.cos(a + da) * 0.4, 1.08 + r() * 0.1, Math.sin(a + da) * 0.4];
      k.bar(s1, t1, 0.01, BARK_DARK);
      hangs.push(along(s1, t1, 0.45), along(s1, t1, 0.8));
    }
  }
  k.bar(crown, [0.0, 1.2, 0.03], 0.012, BARK_DARK);
  // the shoes, in pairs, hanging under their branches by the laces
  for (const p of hangs) {
    if (r() < 0.25) continue;
    // a size up from life, so they still read as shoes at the game's zoom
    const L = 0.06 + r() * 0.11, yaw = r() * TAU, col = shoe(), cx = Math.cos(yaw) * 0.022, cz = -Math.sin(yaw) * 0.022;
    for (const s of [-1, 1]) {
      const sx = p[0] + s * cx, sz = p[2] + s * cz, sy = p[1] - L - s * 0.008;
      k.bar(p, [sx, sy + 0.05, sz], 0.003, hex(0xe8e4d8));
      fbox(k, frame([sx, sy, sz], yaw, 0, s * 0.25), 0, 0, 0, 0.029, 0.05, 0.044, col, WHITE);
    }
  }
  // and the odd ones that came down again
  for (let i = 0; i < 5; i++) {
    const a = r() * TAU, d = 0.14 + r() * 0.12;
    fbox(k, frame([Math.cos(a) * d, 0, Math.sin(a) * d], r() * TAU, (r() - 0.5) * 0.3), 0, 0, 0, 0.018, 0.016, 0.036, shoe(), WHITE);
  }
};

// ---- sign forest (2 × 2) -----------------------------------------------------------------------------

/** Posts and posts of road signs and number plates from everywhere, pointing every way, a lane through the middle. */
const signForest: Draw = (k, _W, _D, _b, r) => {
  const BOARDS = [0x2f7a46, 0x2a5fb0, 0xeeeee8, 0xf2c230, 0xb8282a, 0x7a5232, 0xe7782a, 0x3a3f45];
  const POST = hex(0x8a6e50), POST_TOP = hex(0x6e5840);
  const light = (c: RGB) => c[0] + c[1] + c[2] > 1.9;
  // the lane through, and the board over its mouth
  k.box(0, 0.001, 0, 0.42, 0.004, 1.9, scale(DIRT, 0.92));
  for (const s of [-1, 1]) k.box(s * 0.3, 0, 0.86, 0.04, 0.62, 0.04, POST, POST_TOP);
  k.box(0, 0.5, 0.86, 0.66, 0.1, 0.02, hex(0x6e4a2a));
  letters(k, ID, 'SIGN FOREST', 0, 0.515, 0.8715, 0.052, 0.07, hex(0xf2e6c8));
  // the posts, each its own collection
  for (const px of [-0.66, -0.4, 0.4, 0.66]) {
    for (const pz of [-0.66, -0.33, 0, 0.33, 0.66]) {
      if (r() < 0.22) continue;
      const x = px + (r() - 0.5) * 0.1, z = pz + (r() - 0.5) * 0.1, H = 0.5 + r() * 0.22;
      k.box(x, 0, z, 0.032, H, 0.032, POST, POST_TOP);
      let y = 0.12 + r() * 0.05;
      while (true) {
        const plate = r() < 0.3, arrow = !plate && r() < 0.45;
        const w = plate ? 0.07 : 0.08 + r() * 0.08, h = plate ? 0.035 : 0.04 + r() * 0.03;
        if (y + h > H - 0.015) break;
        const col = plate ? hex(r() < 0.6 ? 0xf4f2ec : 0xf2c230) : hex(BOARDS[Math.floor(r() * BOARDS.length)]);
        const ink = light(col) ? hex(0x2a2a2e) : hex(0xf4f2ec);
        // an arrow points away from its post, toward wherever it was taken from; most of them out of the lane
        let yaw = r() * TAU;
        if (arrow && Math.sign(x) !== Math.sign(Math.cos(yaw))) yaw = Math.PI - yaw;
        const f = frame([x, y, z], yaw);
        const ox = arrow ? w / 2 + 0.01 : (r() - 0.5) * 0.02, zb = 0.022, bw = w;
        fbox(k, f, ox, 0, zb, bw, h, 0.01, col);
        if (arrow) fbox(k, frame(f([ox + bw / 2, h / 2, zb]), yaw, Math.PI / 4), 0, -h * 0.35, 0, h * 0.7, h * 0.7, 0.01, col);
        if (r() < 0.6) fbox(k, f, ox, h * 0.38, zb + 0.008, bw * 0.7, h * 0.24, 0.002, ink);
        y += h + 0.012;
      }
      k.box(x, H, z, 0.04, 0.012, 0.04, POST_TOP);
    }
  }
  for (let i = 0; i < 5; i++) ball(k, (r() < 0.5 ? -1 : 1) * (0.5 + r() * 0.4), 0, (r() - 0.5) * 1.8, 0.04 + r() * 0.03, GRASS);
};

// ---- Bigfoot (1 × 1) ---------------------------------------------------------------------------------

/** A carved Bigfoot caught mid-stride on its plinth among the pines, a sign in front saying who it is. */
const bigfootStatue: Draw = (k, _W, _D, _b, r) => {
  tree(k, -0.33, 0, -0.34, 0.5 + r() * 0.06, true);
  tree(k, 0.33, 0, -0.33, 0.45 + r() * 0.06, true);
  ball(k, -0.36, 0, 0.12, 0.07, BUSH);
  ball(k, 0.36, 0, 0.28, 0.06, BUSH);
  k.turned((r() - 0.5) * 0.5, () => {
    const PY = 0.08;
    k.box(0, 0, -0.05, 0.36, PY, 0.34, STONE, STONE_DARK);
    // the legs, left forward, right back, and the great feet
    const hipL: P3 = [-0.065, 0.42, -0.05], hipR: P3 = [0.065, 0.42, -0.05];
    const kneeL: P3 = [-0.068, 0.26, 0.03], kneeR: P3 = [0.068, 0.25, -0.1];
    const ankL: P3 = [-0.065, PY + 0.03, 0.06], ankR: P3 = [0.065, PY + 0.05, -0.17];
    tube(k, hipL, kneeL, 0.058, 0.05, FUR, 7);
    tube(k, kneeL, ankL, 0.05, 0.04, FUR, 7);
    tube(k, hipR, kneeR, 0.058, 0.05, FUR, 7);
    tube(k, kneeR, ankR, 0.05, 0.04, FUR, 7);
    k.box(-0.065, PY, 0.08, 0.075, 0.035, 0.13, FUR_DARK);
    fbox(k, frame([0.065, PY + 0.02, -0.17], 0, 0, 0.35), 0, 0, 0.02, 0.075, 0.035, 0.13, FUR_DARK);
    k.box(0, 0.37, -0.05, 0.2, 0.1, 0.15, FUR);
    // the body, stooped forward, shaggy at the shoulders
    const f = frame([0, 0.46, -0.05], 0, 0, 0.15);
    fbox(k, f, 0, 0, 0, 0.26, 0.32, 0.17, FUR, FUR_DARK);
    for (const [sx, sy, sz] of [[-0.1, 0.26, -0.07], [0.1, 0.25, -0.07], [0, 0.18, -0.09], [-0.12, 0.12, 0.02], [0.12, 0.13, 0.02]] as const) {
      fbox(k, f, sx, sy, sz, 0.07, 0.06, 0.05, FUR_DARK);
    }
    fbox(k, f, 0, 0.32, 0.01, 0.13, 0.12, 0.13, FUR);
    fbox(k, f, 0, 0.44, -0.01, 0.08, 0.04, 0.09, FUR_DARK);
    fbox(k, f, 0, 0.335, 0.075, 0.09, 0.075, 0.012, FUR_FACE);
    fbox(k, f, 0, 0.395, 0.08, 0.11, 0.022, 0.02, FUR_DARK);
    for (const s of [-1, 1]) fbox(k, f, s * 0.025, 0.37, 0.084, 0.016, 0.012, 0.006, GAP);
    // the arms, swinging long against the stride
    const shL = f([-0.15, 0.27, 0]), shR = f([0.15, 0.27, 0]);
    const elL: P3 = [-0.17, 0.57, -0.13], elR: P3 = [0.17, 0.59, 0.06];
    const hnL: P3 = [-0.175, 0.42, -0.2], hnR: P3 = [0.175, 0.43, 0.14];
    tube(k, shL, elL, 0.045, 0.04, FUR, 6);
    tube(k, elL, hnL, 0.04, 0.034, FUR, 6);
    tube(k, shR, elR, 0.045, 0.04, FUR, 6);
    tube(k, elR, hnR, 0.04, 0.034, FUR, 6);
    ball(k, hnL[0], hnL[1] - 0.04, hnL[2], 0.035, FUR_DARK);
    ball(k, hnR[0], hnR[1] - 0.04, hnR[2], 0.035, FUR_DARK);
    // the sign
    const signZ = 0.33;
    for (const s of [-1, 1]) k.box(s * 0.11, 0, signZ, 0.02, 0.2, 0.02, TIMBER);
    k.box(0, 0.12, signZ, 0.27, 0.085, 0.014, hex(0x6e4a2a));
    letters(k, ID, 'BIGFOOT', 0, 0.135, signZ + 0.0105, 0.032, 0.05, hex(0xf2e6c8));
  });
};

// ---- giant duck (2 × 2) ------------------------------------------------------------------------------

/** A rubber duck the size of a boat, bobbing in a pool at the water's edge, somebody beside it for scale. */
const giantDuck: Draw = (k, _W, _D, _b, r) => {
  k.cyl(0, 0, 0, 0.93, 0.003, SAND_WET, 16);
  k.cyl(0, 0.003, 0, 0.86, 0.006, WATER, 16);
  k.hoop(0, 0.012, 0, 0.66, 0.005, hex(0xd8eef8), 16, 'xz');
  k.turned(-0.5 + r() * 1.0, () => {
    // body, wings, the tail flicked up behind
    blob(k, 0, 0.2, -0.02, 0.38, 0.26, 0.54, DUCK, 12, 6, DUCK_TOP);
    for (const s of [-1, 1]) blob(k, s * 0.35, 0.26, -0.06, 0.05, 0.13, 0.27, DUCK_WING, 8, 4);
    tube(k, [0, 0.3, -0.38], [0, 0.5, -0.62], 0.17, 0.02, DUCK_TOP, 8);
    // head, beak, eyes
    blob(k, 0, 0.6, 0.28, 0.21, 0.2, 0.21, DUCK, 10, 6, DUCK_TOP);
    blob(k, 0, 0.55, 0.5, 0.13, 0.045, 0.12, BEAK, 8, 4);
    for (const s of [-1, 1]) {
      blob(k, s * 0.1, 0.665, 0.44, 0.04, 0.045, 0.03, WHITE, 6, 4);
      blob(k, s * 0.108, 0.67, 0.462, 0.022, 0.026, 0.016, GAP, 6, 4);
    }
  });
  // on the sand: somebody come to look, a lifebuoy, a bucket
  person(k, 0.78, 0.68, 2.3, hex([0xe2412f, 0x2f7fb5, 0x3f9b4a][Math.floor(r() * 3)]));
  k.hoop(-0.8, 0.012, 0.72, 0.045, 0.01, hex(0xe8402e), 8, 'xz');
  k.cyl(0.72, 0, -0.78, 0.025, 0.04, hex(0x2f7fb5), 8, hex(0x22508a));
  ball(k, -0.85, 0, -0.7, 0.05, BUSH);
};

