/**
 * Property (docs/property.html): the deed book. Any building can be bought, and every harbour as one
 * holding; from then on every load that starts or ends at that door pays its owner a share of its
 * worth, whoever drove it. The money is paid out of the same two calls that credit a building's own
 * books in the ledger (`Economy.lotCredit`), and never written back into them, so owning a town can't
 * grow it. A deed earns only while its cell is in memory: nothing earns off screen.
 */

/** One lot the player owns. Keyed like `LotLedger`: `cx,cz#b<uid>` or `cx,cz#p<port id>`. */
export interface Deed {
  key: string;
  /** The building's kind when bought, or 'harbour'. */
  kind: string;
  name: string;
  /** The town it trades through, by key and by name ('' for none). */
  townKey: string;
  town: string;
  /** Its middle in its cell's tiles, for the map. */
  x: number; z: number;
  /** The game day it was bought, what was paid, and the most it may take in a day. */
  day: number; paid: number; ceil: number;
  /** Lifetime takings after the levy, and the levy paid on them. */
  took: number; tax: number;
  /** Loads paid on at each end, and CPU cars that parked at the door. */
  ins: number; outs: number; visits: number;
  /**
   * Bought as the HQ on HQ terms, under its market price: it sells, and takes at its door, on what was
   * paid, not on the market's figure (or a busy building bought cheap as an HQ is a free fortune).
   */
  hqTerms?: boolean;
  /** Taken today (before the levy, against the ceiling), and the game day that belongs to. */
  today: number; d0: number;
  /** Taken on the current day's loads alone, for the window. */
  loadsToday: number; visitsToday: number;
  /** The last WEEK game days with any trade, oldest first: [day, taken after the levy, loads, visits]. */
  week: WeekDay[];
  /**
   * What it would have sold for when last saved with its island in memory: what the online world pays back
   * for it when it begins again (estateRefund), when the old island can no longer be priced.
   */
  worth?: number;
  /** What it makes, when its kind is in the recipe book (docs/supplychains.html, game/chains/plants.ts). */
  plant?: Plant;
}

/** One game day of a lot's trade: [day, taken after the levy, loads, visits]. */
type WeekDay = [number, number, number, number];
/** Game days the estate window's takings run over. */
export const WEEK = 7;

/** What a lot would cost and pay, for the building card and the town card. */
interface Quote {
  key: string;
  /** The faction that holds this building outright (docs/factions.html): it is not for sale. */
  faction?: string;
  harbour: Port | null;
  name: string;
  town: string;
  townKey: string;
  townKind: TownKind | null;
  /** Whether goods ever come or go here. */
  trades: boolean;
  /** Its trade now, dollars an hour, and what that pays an owner in a game day. */
  rate: number;
  perDay: number;
  price: number;
  /** Game days of trade like today's the price stands for; Infinity for a lot that takes nothing. */
  days: number;
  word: PaybackWord;
  derelict: boolean;
  /** Lots already held in the same town (not counting this one). */
  held: number;
  owned: Deed | null;
  /** Tiles from the player, or Infinity when the player isn't on this island's lattice. */
  far: number;
  /** What owning it does beyond its rent: an Auto Shop's or a dealer's discount. */
  perk?: string;
  /** What it costs bought as the fleet's HQ: the same as `price` since 4 Oct 2026 (it once had cheaper HQ terms). */
  hqPrice: number;
  /** What it is as an HQ (docs/hq.html), and whether that grade's prestige floor set the price over what trade alone (`byTrade`) would. */
  grade: HqGrade;
  prestiged: boolean;
  byTrade: number;
}

/**
 * An Auto Shop or a car dealership (world/storefronts.ts) sells at a premium: it is worth its trade times
 * `mul`, and never less than `floor`. Owning one takes 10% off everything the fleet buys there.
 */
const STOREFRONT_PRICE: Record<'shop' | 'dealer', { mul: number; floor: number; perk: string }> = {
  shop: { mul: 5, floor: 24000, perk: 'Owning this Auto Shop takes 10% off every part you buy here.' },
  dealer: { mul: 6, floor: 60000, perk: 'Owning this dealership takes 10% off every vehicle you buy here.' },
};

interface EstateHost {
  /** Islands in memory. */
  worlds(): World[];
  /** Only a game in play earns: the title screen's reel runs traffic too. */
  playing(): boolean;
  /** The player's vehicle in world tiles. */
  playerAt(): { x: number; z: number } | null;
  seed(): string;
  /** The cash chip, ticked in the colour of whoever paid. */
  cash(source: CashSource): void;
  float(text: string, x: number, y: number, z: number): void;
  announce(title: string, body: string): void;
  /** A gold card in the earnings ticker. */
  ticker(icon: string, head: string, body: string): void;
  /** Rent taken on `n` loads at one of the player's doors: a mission may be counting them. */
  rent?(n: number, sum: number): void;
  letter(n: Note): void;
  /** Something about the deeds changed: windows redraw. */
  changed(): void;
}

/** The saved form: [kind, name, townKey, town, x, z, day, paid, ceil, took, tax, ins, outs, visits, hqTerms?]. */
export type SavedDeed = [string, string, string, string, number, number, number, number, number, number, number, number, number, number, hqTerms?: 1 | null, week?: WeekDay[] | null, worth?: number, plant?: SavedPlant];

/**
 * The online world has begun again (a world update): every building a career held is refunded in full, at what was
 * paid for it (the user, 10 Nov 2026, for 0.8.0; it was sold back at its worth before), the HQ with the rest: the
 * new world's like of it is then bought out of that (main.ts carryHq). A deed with no price paid kept goes at what it
 * would have fetched (Deed.worth), or the sale share of the price its ceiling was set from.
 */
export function estateRefund(saved: Record<string, SavedDeed> | undefined | null): { n: number; total: number } {
  let n = 0, total = 0;
  for (const t of Object.values(saved ?? {})) {
    if (!Array.isArray(t)) continue;
    const paid = Number(t[7]), worth = Number(t[16]);
    const v = Number.isFinite(paid) && paid > 0 ? paid
      : Number.isFinite(worth) && worth >= 0 ? worth : Math.round((Math.max(0, Number(t[8]) || 0) * ESTATE.ceilingDays * ESTATE.sell) / 10) * 10;
    n++;
    total += v;
  }
  return { n, total: Math.round(total) };
}

