/** "bigBox" → "Big box": a label for a building kind nobody wrote one for. */
function label(kind: string): string {
  const own = SITE_LABEL[kind as SiteKind];
  if (own) return own;
  const words = kind.replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
  return words[0].toUpperCase() + words.slice(1);
}

export class Estate implements EstateHook {
  readonly deeds = new Map<string, Deed>();
  /** Rent gathered for the ticker: one card per door every couple of seconds. */
  private gather = new Map<string, { n: number; sum: number; t: number }>();
  /** When each CPU car last paid footfall at each door, in seconds of play. */
  private seen = new Map<string, number>();
  private now = 0;
  private sweep = 0;
  /** The gold pennants on owned roofs. */
  private poles: THREE.InstancedMesh;
  private flags: THREE.InstancedMesh;
  private m = new THREE.Matrix4();
  private at = new THREE.Vector3();
  /**
   * The rival firms (docs/rivals.html): whose doors are not the player's to buy, what they are paid at
   * doors of their own, and the tenth off a lot in a town that prefers the player's company.
   */
  others: {
    heldBy(key: string): string | null;
    trade(key: string, amount: number, dir: 'in' | 'out', s: Site): void;
    footfall(key: string, a: Agent, b: Building): void;
    worn(key: string): void;
    discount(townKey: string): number;
  } | null = null;


  /**
   * Online (src/net): the doors other players hold, which are nobody else's to buy, and the trade at them,
   * which is passed on to their owners rather than paid here.
   */
  remote: {
    /** Whose door this is, as a line for its card; null when no other player holds it. */
    heldBy(key: string): string | null;
    /**
     * Trade of `gross` dollars at a door, by the player's company or by the CPU: true when it is not this
     * game's to pay (another player's door, or CPU trade in a county somebody else's game is running).
     */
    trade(key: string, gross: number, player: boolean): boolean;
  } | null = null;

  /** A building has become the fleet's (bought, granted, bought off a rival): its plans go in the blueprint book (docs/blueprints.html). */
  onBought: ((w: World, b: Building) => void) | null = null;

  constructor(private economy: Economy, private wallet: Wallet, private host: EstateHost, scene: THREE.Scene) {
    economy.estate = this;
    const MAX = 96;
    this.poles = new THREE.InstancedMesh(new THREE.BoxGeometry(0.035, 0.42, 0.035).translate(0, 0.21, 0),
      new THREE.MeshLambertMaterial({ color: 0x5b4a2e }), MAX);
    const flag = new THREE.BufferGeometry();
    flag.setAttribute('position', new THREE.Float32BufferAttribute([0.02, 0.42, 0, 0.26, 0.345, 0, 0.02, 0.27, 0], 3));
    flag.computeVertexNormals();
    this.flags = new THREE.InstancedMesh(flag, new THREE.MeshLambertMaterial({ color: 0xf2b632, emissive: 0x5a3a00, side: THREE.DoubleSide }), MAX);
    for (const im of [this.poles, this.flags]) { im.count = 0; im.frustumCulled = false; scene.add(im); }
  }

  // ---- keys and what they stand for ----

  /** The deed key a building's card is about: its own, or its harbour's. */
  keyOf(w: World, b: Building): string {
    const port = w.ports.find((p) => p.buildings.includes(b));
    return port ? `${w.cx},${w.cz}#p${port.id}` : `${w.cx},${w.cz}#b${b.uid}`;
  }

  owns(w: World, b: Building): Deed | null { return this.deeds.get(this.keyOf(w, b)) ?? null; }

  /** Is this door the player's, or (online) another player's? Either way no firm can have it. */
  taken(key: string): boolean { return this.deeds.has(key) || !!this.remote?.heldBy(key); }

  /** The island and buildings a key stands for, while its island is in memory. */
  resolve(key: string): { w: World; b: Building; all: Building[]; port: Port | null } | null {
    const m = /^(-?\d+),(-?\d+)#([bp])(\d+)$/.exec(key);
    if (!m) return null;
    const cx = Number(m[1]), cz = Number(m[2]), id = Number(m[4]);
    const w = this.host.worlds().find((q) => q.cx === cx && q.cz === cz);
    if (!w) return null;
    if (m[3] === 'p') {
      const port = w.ports.find((p) => p.id === id);
      const all = port?.buildings.filter((b) => !b.gone) ?? [];
      return port && all.length ? { w, b: all[0], all, port } : null;
    }
    const b = w.allBuildings[id];
    return b && b.uid === id ? { w, b, all: [b], port: null } : null;
  }

  // ---- the price ----

  quote(w: World, b: Building): Quote {
    const key = this.keyOf(w, b);
    const port = key.includes('#p') ? w.ports.find((p) => p.buildings.includes(b)) ?? null : null;
    const r = this.economy.report(w, b);
    const all = port ? port.buildings.filter((q) => !q.gone) : [b];
    const floor = all.reduce((s, q) => s + lotFloor(q), 0);
    const tk = r.town ? townKey(w, r.town) : '';
    const owned = this.deeds.get(key) ?? null;
    let held = 0;
    if (tk) for (const d of this.deeds.values()) if (d.townKey === tk && d.key !== key) held++;
    const derelict = !port && !!b.derelict;
    // a country lot on a town's books is still a country lot: the town's kind doesn't dress it up
    const kind = r.town && r.via === 'town' ? r.town.kind : null;
    const front = !port && (b.storefront === 'shop' || b.storefront === 'dealer') ? STOREFRONT_PRICE[b.storefront] : null;
    let price = Math.max(100, Math.round((lotPrice(r.lotRate, floor, kind, derelict, held) * (tk ? (this.others?.discount(tk) ?? 1) : 1)) / 100) * 100);
    if (front) price = Math.max(front.floor, Math.round((price * front.mul) / 100) * 100);
    // the prestige floor: a grand building is dear whether or not anything comes through its door
    const grade = gradeOf(b, !!port);
    const byTrade = price;
    const prestige = prestigeFloor(grade, kind ? ESTATE.town[kind] : ESTATE.country, holdingMul(held));
    if (prestige > price) price = prestige;
    // one price either way (4 Oct 2026): the HQ terms that once undercut the deed are gone
    const hqPrice = price;
    const perDay = derelict ? 0 : ESTATE.yield * r.lotRate * 24;
    const days = perDay > 0.05 ? price / perDay : Infinity;
    const p = this.host.playerAt();
    const far = p ? Math.hypot(p.x - (w.ox + b.x + b.w / 2), p.z - (w.oz + b.z + b.d / 2)) - Math.max(b.w, b.d) / 2 : Infinity;
    const place = port ? port.name : r.town?.name ?? '';
    return {
      key, ...(!port && OWNED_OUTRIGHT.has(b.kind) ? { faction: FACTIONS[buildingFaction(b.kind)!]?.name } : {}), harbour: port, name: port ? port.name : label(b.kind), town: place, townKey: tk, townKind: r.town?.kind ?? null,
      trades: r.trades, rate: r.lotRate, perDay, price, days, word: paybackWord(days), derelict, held, owned, far: Math.max(0, far),
      perk: front?.perk, grade, prestiged: prestige > byTrade, byTrade, hqPrice,
    };
  }

  /** Why a lot can't be bought now, or null when it can. */
  whyNot(q: Quote, asHq = false): string | null {
    if (q.owned) return 'Already yours';
    if (q.faction) return `Held by ${q.faction}: not for sale`;
    const theirs = this.remote?.heldBy(q.key) ?? this.others?.heldBy(q.key);
    if (theirs) return theirs;
    if (q.far > ESTATE.reach) return `Drive within ${ESTATE.reach} tiles to buy · ${Math.round(q.far)} away`;
    if (!this.wallet.canAfford(asHq ? q.hqPrice : q.price)) return `Not enough cash · you have ${money(this.wallet.cash)}`;
    return null;
  }

  // ---- buying, selling, mending ----

  /** Buy a lot: at its market price, or `asHq` on HQ terms (the caller makes it the HQ straight after). */
  buy(w: World, b: Building, asHq = false): string | null {
    if (!this.host.playing()) return 'Not now';
    const q = this.quote(w, b);
    const why = this.whyNot(q, asHq);
    if (why) return why;
    const price = asHq ? q.hqPrice : q.price;
    const terms = asHq && q.hqPrice < q.price;
    if (!this.wallet.spend(price, 'property')) return 'Not enough cash';
    this.host.cash('you');
    const all = q.harbour ? q.harbour.buildings : [b];
    const mx = all.reduce((s, x) => s + x.x + x.w / 2, 0) / all.length, mz = all.reduce((s, x) => s + x.z + x.d / 2, 0) / all.length;
    const day = this.day();
    const d: Deed = {
      key: q.key, kind: q.harbour ? 'harbour' : b.kind, name: q.name, townKey: q.townKey, town: q.town, x: mx, z: mz,
      day, paid: price, ceil: price / ESTATE.ceilingDays, took: 0, tax: 0, ins: 0, outs: 0, visits: 0,
      today: 0, d0: day, loadsToday: 0, visitsToday: 0, week: [], ...(terms ? { hqTerms: true } : {}),
    };
    this.deeds.set(q.key, d);
    this.tally();
    deeds.best('blueChip', price);
    if (q.townKey) deeds.mark('estateTowns', `${this.host.seed()}|${q.townKey}`);
    const extra = q.harbour ? ` — ${q.harbour.buildings.length} buildings, one set of books` : '';
    this.host.announce('The deed is yours', `${q.name}${q.harbour ? '' : q.town ? `, ${q.town}` : ''} · ${money(price)}${terms ? ' on HQ terms' : ''}${extra}`);
    // the paper (docs/newspaper.html): a big buy is front-page news
    const tw = q.townKey ? townOf(w, q.townKey) : null;
    press.write({
      k: 'deedBought', who: 'you', town: q.townKey || undefined, at: buildingAt(w, b), w: price >= 20000 ? 5 : undefined,
      f: { building: plain(q.name), town: q.harbour ? '' : q.town, price }, pic: buildingPic(w, b, tw?.style),
    });
    if (q.townKey) press.dealt(q.townKey, 3);
    this.host.changed();
    this.onBought?.(w, b);
    return null;
  }

  /**
   * A deed given, not bought (a mission's reward, docs/missions.html): the lot is the player's at its
   * price today, which is what it is booked at and what a sale would start from. Null when done.
   */
  grant(w: World, b: Building): string | null {
    const q = this.quote(w, b);
    if (q.owned) return 'Already yours';
    const all = q.harbour ? q.harbour.buildings : [b];
    const mx = all.reduce((s, x) => s + x.x + x.w / 2, 0) / all.length, mz = all.reduce((s, x) => s + x.z + x.d / 2, 0) / all.length;
    const day = this.day();
    this.deeds.set(q.key, {
      key: q.key, kind: q.harbour ? 'harbour' : b.kind, name: q.name, townKey: q.townKey, town: q.town, x: mx, z: mz,
      day, paid: q.price, ceil: q.price / ESTATE.ceilingDays, took: 0, tax: 0, ins: 0, outs: 0, visits: 0,
      today: 0, d0: day, loadsToday: 0, visitsToday: 0, week: [],
    });
    this.tally();
    if (q.townKey) deeds.mark('estateTowns', `${this.host.seed()}|${q.townKey}`);
    this.host.changed();
    this.onBought?.(w, b);
    return null;
  }

  /**
   * A building the fleet put up from its blueprints (docs/blueprints.html) is its by deed from the first spade: booked
   * at what the construction cost, which sets its daily ceiling as a purchase would. Trade waits for the site to
   * finish (game/cargo.ts buildSites). Returns the deed.
   */
  grantBuilt(w: World, b: Building, paid: number): Deed {
    const q = this.quote(w, b);
    const day = this.day();
    const d: Deed = {
      key: q.key, kind: b.kind, name: q.name, townKey: q.townKey, town: q.town, x: b.x + b.w / 2, z: b.z + b.d / 2,
      day, paid, ceil: Math.max(q.price, paid) / ESTATE.ceilingDays, took: 0, tax: 0, ins: 0, outs: 0, visits: 0,
      today: 0, d0: day, loadsToday: 0, visitsToday: 0, week: [],
    };
    this.deeds.set(q.key, d);
    this.tally();
    deeds.best('blueChip', paid);
    if (q.townKey) deeds.mark('estateTowns', `${this.host.seed()}|${q.townKey}`);
    this.host.changed();
    return d;
  }

  /**
   * What buying the same building would cost in this county (docs/blueprints.html): the median asking price of the
   * copies of its kind standing here, each scaled by storeys and footprint to this one's size, and never less than a fresh lot of that size would be quoted at (its demolition
   * floor and its grade's prestige floor, at the town's rate inside a town's lines or the country's outside, with the
   * usual mark-up for every lot already held in that town).
   */
  equivalentPrice(w: World, like: Pick<Building, 'kind' | 'w' | 'd' | 'floors' | 'solid'>, town: Town | null): number {
    const tk = town ? townKey(w, town) : '';
    let held = 0;
    if (tk) for (const d of this.deeds.values()) if (d.townKey === tk) held++;
    const fake: Building = { kind: like.kind, x: 0, z: 0, w: like.w, d: like.d, facing: 0, floors: like.floors, seed: 0, solid: like.solid, level: 0, uid: -1 };
    const kind = town?.kind ?? null;
    const discount = tk ? (this.others?.discount(tk) ?? 1) : 1;
    let fresh = Math.max(100, Math.round((lotPrice(0, lotFloor(fake), kind, false, held) * discount) / 100) * 100);
    fresh = Math.max(fresh, prestigeFloor(gradeOf(fake), kind ? ESTATE.town[kind] : ESTATE.country, holdingMul(held)));
    // the county's own of that kind, each scaled to this one's size: storeys times footprint, so a taller variant of
    // the same building costs that much more than the base model (the user, 6 Nov 2026), and a lower one less
    const size = (b: Pick<Building, 'w' | 'd' | 'floors'>) => Math.max(1, b.floors) * b.w * b.d;
    const quotes: number[] = [];
    for (const b of w.allBuildings) {
      if (b.gone || b.derelict || b.kind !== like.kind || b.storefront) continue;
      if (w.ports.some((p) => p.buildings.includes(b)) || w.works.some((g) => g.buildings.includes(b))) continue;
      quotes.push(this.quote(w, b).price * size(like) / size(b));
    }
    quotes.sort((a, b) => a - b);
    const median = quotes.length ? quotes[Math.floor(quotes.length / 2)] : 0;
    return Math.max(fresh, median);
  }

  /** What putting the copy up costs: the equivalent purchase and half again (shared/erect.ts ERECT_MARKUP). */
  buildPrice(w: World, like: Pick<Building, 'kind' | 'w' | 'd' | 'floors' | 'solid'>, town: Town | null): number {
    return Math.max(100, Math.round((this.equivalentPrice(w, like, town) * ERECT_MARKUP) / 100) * 100);
  }

  /**
   * A door bought off a rival firm (game/buyout.ts) for `price`, over its market price: the caller has
   * checked and paid. The deed books what was paid; its daily ceiling, and what it sells for, stay on
   * the market's figure, as for any other lot.
   */
  boughtFrom(w: World, b: Building, price: number, seller: string): void {
    const q = this.quote(w, b);
    const all = q.harbour ? q.harbour.buildings : [b];
    const mx = all.reduce((s, x) => s + x.x + x.w / 2, 0) / all.length, mz = all.reduce((s, x) => s + x.z + x.d / 2, 0) / all.length;
    const day = this.day();
    this.deeds.set(q.key, {
      key: q.key, kind: q.harbour ? 'harbour' : b.kind, name: q.name, townKey: q.townKey, town: q.town, x: mx, z: mz,
      day, paid: price, ceil: q.price / ESTATE.ceilingDays, took: 0, tax: 0, ins: 0, outs: 0, visits: 0,
      today: 0, d0: day, loadsToday: 0, visitsToday: 0, week: [],
    });
    this.tally();
    deeds.best('blueChip', q.price);
    if (q.townKey) deeds.mark('estateTowns', `${this.host.seed()}|${q.townKey}`);
    this.host.announce('The deed is yours', `${q.name}${q.town ? `, ${q.town}` : ''} · bought from ${seller} for ${money(price)}`);
    press.write({ k: 'deedBought', who: 'you', town: q.townKey || undefined, at: buildingAt(w, b), w: price >= 20000 ? 5 : undefined,
      f: { building: plain(q.name), town: q.harbour ? '' : q.town, price }, pic: buildingPic(w, b, q.townKey ? townOf(w, q.townKey)?.style : undefined) });
    if (q.townKey) press.dealt(q.townKey, 3);
    this.host.changed();
    this.onBought?.(w, b);
  }

  /** What a lot of yours would fetch now. */
  saleValue(key: string): number | null {
    const r = this.resolve(key);
    if (!r) return null;
    const q = this.quote(r.w, r.b);
    const d = this.deeds.get(key);
    const base = d?.hqTerms ? Math.min(q.price, d.paid) : q.price;
    return Math.round((base * ESTATE.sell) / 10) * 10;
  }

  sell(key: string): string | null {
    const d = this.deeds.get(key);
    const v = this.saleValue(key);
    if (!d || v === null) return 'Too far away to sell';
    this.deeds.delete(key);
    this.wallet.earn(v, 'propertySales');
    this.host.cash('you');
    this.host.announce('Sold', `${d.name} · ${money(v)}`);
    press.write({ k: 'deedSold', who: 'you', town: d.townKey || undefined, f: { building: plain(d.name), price: v } });
    this.tally();
    this.host.changed();
    return null;
  }

  mendCost(b: Building): number { return Math.round((ESTATE.mend * demolishCost(b)) / 5) * 5; }

  mend(key: string): string | null {
    const d = this.deeds.get(key), r = this.resolve(key);
    if (!d || !r) return 'Too far away to mend';
    if (!r.b.derelict) return 'Not boarded up';
    const cost = this.mendCost(r.b);
    if (!this.wallet.spend(cost, 'property')) return `Mending costs ${money(cost)}`;
    this.host.cash('you');
    this.economy.mendLot(r.w, r.b);
    // the trade went with the boards: the ceiling is read again from the lot as it stands
    const now = this.quote(r.w, r.b).price;
    d.ceil = (d.hqTerms ? Math.min(now, d.paid) : now) / ESTATE.ceilingDays;
    deeds.add('mended');
    this.host.announce('Mended', `${d.name} · ${money(cost)} · the boards are down`);
    press.write({ k: 'deedMended', who: 'you', town: d.townKey || undefined, at: buildingAt(r.w, r.b), f: { building: plain(d.name), price: cost }, pic: buildingPic(r.w, r.b, townOf(r.w, d.townKey)?.style) });
    this.host.changed();
    return null;
  }

  /** The bulldozer took it: the deed is void, and nothing comes back — unless it was a site of the fleet's own still going up, which refunds `refund` (docs/blueprints.html). */
  razed(w: World, b: Building, refund = 0): void {
    const key = this.keyOf(w, b);
    const d = this.deeds.get(key);
    // a harbour stands while any of its buildings do
    if (!d || (key.includes('#p') && this.resolve(key))) return;
    this.deeds.delete(key);
    if (refund > 0) this.host.announce('Site cleared', `${d.name} · ${money(refund)} of the ${money(d.paid)} refunded`);
    else this.host.announce('Deed void', `${d.name} is gone, and the ${money(d.paid)} with it`);
    press.write({ k: 'deedVoid', who: 'you', town: d.townKey || undefined, f: { building: plain(d.name), price: d.paid - refund } });
    this.host.changed();
  }

  // ---- being paid ----

  private day(): number { return Math.floor(this.economy.hours / 24); }

  private roll(d: Deed): void {
    const day = this.day();
    if (d.d0 !== day) { d.d0 = day; d.today = 0; d.loadsToday = 0; d.visitsToday = 0; }
  }

  /** Book takings on today's line of a lot's week, and let days older than the week fall off. */
  private log(d: Deed, net: number, loads: number, visits: number): void {
    const day = this.day();
    let last = d.week[d.week.length - 1];
    if (!last || last[0] !== day) { last = [day, 0, 0, 0]; d.week.push(last); }
    last[1] += net; last[2] += loads; last[3] += visits;
    while (d.week.length && d.week[0][0] <= day - WEEK) d.week.shift();
  }

  /** A lot's takings (after the levy), loads and visits over the trailing WEEK game days, today included. */
  trailing(d: Deed): { took: number; loads: number; visits: number } {
    const from = this.day() - WEEK;
    let took = 0, loads = 0, visits = 0;
    for (const [day, t, l, v] of d.week) if (day > from) { took += t; loads += l; visits += v; }
    return { took, loads, visits };
  }

  /** Called by the ledger at each end of every delivery. `amount` is value0 × the ledger's share. */
  trade(key: string, amount: number, dir: 'in' | 'out', player: boolean, s: Site, by: Who = player ? 'you' : 'other'): void {
    if (!this.host.playing()) return;
    if (this.remote?.trade(key, s.b?.derelict ? 0 : Math.round(amount * ESTATE.yield), player)) return;
    const d = this.deeds.get(key);
    if (!d) { this.others?.trade(key, amount, dir, s); return; }
    if (s.b?.derelict) return;
    this.roll(d);
    let gross = Math.round(amount * ESTATE.yield);
    const room = Math.floor(d.ceil - d.today);
    gross = Math.min(gross, room);
    if (gross <= 0) return;
    const levy = Math.round((gross * this.economy.levyAt(s)) / 100);
    const paid = gross - levy;
    d.today += gross;
    d.loadsToday++;
    d.took += paid;
    d.tax += levy;
    this.log(d, paid, 1, 0);
    this.economy.rentShare(d.townKey, YOU, gross);
    if (dir === 'in') d.ins++; else d.outs++;
    if (paid <= 0) return;
    this.wallet.earn(paid, 'rent', by);
    this.host.cash('rent');
    // a moment after the delivery's own pay float, so the two rise one after the other instead of on top of each
    // other (the user, 11 Nov 2026: a fleet driver's delivery to a door you own put both on the same spot at once)
    const line = `+${money(paid)} · ${d.name}`, sx = s.x, sy = s.y + 0.8, sz = s.z;
    setTimeout(() => { if (this.host.playing()) this.host.float(line, sx, sy, sz); }, RENT_FLOAT_DELAY);
    deeds.add('rent', paid);
    const g = this.gather.get(key) ?? { n: 0, sum: 0, t: 0 };
    g.n++;
    g.sum += paid;
    this.gather.set(key, g);
  }

  /**
   * A load a plant of the player's made has been delivered, by anybody (docs/supplychains.html): the plant takes
   * its maker’s fee. Its own daily allowance is the plant's to keep (game/chains/plants.ts), not the rent ceiling's:
   * a cheap mill's rent is spent by its morning deliveries. Returns what was paid.
   */
  makerFee(key: string, amount: number, at: Site): number {
    if (!this.host.playing() || !(amount > 0)) return 0;
    const d = this.deeds.get(key);
    if (!d) return 0;
    this.roll(d);
    // no levy: the delivery it rides on paid its town already
    const paid = Math.round(amount);
    d.took += paid;
    this.log(d, paid, 0, 0);
    if (paid <= 0) return 0;
    this.wallet.earn(paid, 'rent', 'other');
    this.host.cash('rent');
    if (chainsShown()) this.host.float(`+${money(paid)} · made at ${d.name}`, at.x, at.y + 1, at.z);
    deeds.add('rent', paid);
    const g = this.gather.get(key) ?? { n: 0, sum: 0, t: 0 };
    g.n++;
    g.sum += paid;
    this.gather.set(key, g);
    return paid;
  }

  /** A CPU car has parked at a building: a small fee, silently, if the door is the player's. */
  footfall(a: Agent, b: Building): void {
    if (!this.host.playing() || b.derelict) return;
    const key = this.keyOf(a.w, b);
    if (this.remote?.trade(key, ESTATE.footfall[TAG_OF[b.kind] ?? 'home'] ?? 1, false)) return;
    const d = this.deeds.get(key);
    if (!d) { this.others?.footfall(key, a, b); return; }
    const tag = `${key}|${a.id}`;
    const last = this.seen.get(tag);
    if (last !== undefined && this.now - last < ESTATE.footfallGuard) return;
    this.seen.set(tag, this.now);
    this.roll(d);
    const fee = Math.min(ESTATE.footfall[TAG_OF[b.kind] ?? 'home'] ?? 1, Math.floor(d.ceil - d.today));
    if (fee <= 0) return;
    d.today += fee;
    d.took += fee;
    d.visits++;
    d.visitsToday++;
    this.log(d, fee, 0, 1);
    this.wallet.earn(fee, 'rent', 'other');
    this.host.cash('rent');
    deeds.add('rent', fee);
  }

  /**
   * Online: trade at one of the player's doors that another game saw (another player's delivery, or the
   * CPU's in a county another game is running), already held to the door's ceiling by the server.
   */
  credit(key: string, amount: number): void {
    const d = this.deeds.get(key);
    if (!d || !(amount > 0) || !this.host.playing()) return;
    this.roll(d);
    d.today += amount;
    d.loadsToday++;
    d.took += amount;
    d.ins++;
    this.log(d, amount, 1, 0);
    this.economy.rentShare(d.townKey, YOU, amount);
    this.wallet.earn(amount, 'rent', 'other');
    this.host.cash('rent');
    deeds.add('rent', amount);
    const g = this.gather.get(key) ?? { n: 0, sum: 0, t: 0 };
    g.n++;
    g.sum += amount;
    this.gather.set(key, g);
  }

  /** Online: the server says this door was somebody else's first. The deed is void and what was paid comes back. */
  revoke(key: string, whose: string): void {
    const d = this.deeds.get(key);
    if (!d) return;
    this.deeds.delete(key);
    this.wallet.earn(d.paid, 'refunds');
    this.host.cash('you');
    this.host.announce('Not yours after all', `${d.name} already belongs to ${whose} · ${money(d.paid)} refunded`);
    this.tally();
    this.host.changed();
  }

  /** A building boarded up by its town: if it is the player's, the mayor writes. */
  worn(w: World, uid: number): void {
    const d = this.deeds.get(`${w.cx},${w.cz}#b${uid}`);
    const b = w.allBuildings[uid];
    if (!d) this.others?.worn(`${w.cx},${w.cz}#b${uid}`);
    if (!d || !b) return;
    this.host.letter({
      town: d.town || w.name,
      tag: 'Boarded up',
      note: [
        `I regret to tell you that your property, ${d.name}, has been boarded up. ${d.town || 'The town'} has fallen on hard times.`,
        `It will pay you nothing until it is mended, which the builders put at ${money(this.mendCost(b))}.`,
      ],
    });
    this.host.changed();
  }

  // ---- time ----

  update(dt: number): void {
    this.now += dt;
    for (const [key, g] of this.gather) {
      g.t += dt;
      if (g.t < GATHER) continue;
      this.gather.delete(key);
      const d = this.deeds.get(key);
      if (d) this.host.ticker(deedIcon(d.kind), `+${money(g.sum)}`, `Rent · ${d.name} · ${g.n} load${g.n === 1 ? '' : 's'}`);
      if (d) this.host.rent?.(g.n, g.sum);
    }
    this.sweep -= dt;
    if (this.sweep > 0) return;
    this.sweep = 1;
    // a building that has gone some other way than the bulldozer takes its deed with it
    for (const [key, d] of [...this.deeds]) {
      const m = /^(-?\d+),(-?\d+)#b(\d+)$/.exec(key);
      if (!m) continue;
      const w = this.host.worlds().find((q) => q.cx === Number(m[1]) && q.cz === Number(m[2]));
      const b = w?.allBuildings[Number(m[3])];
      if (w && (!b || b.gone)) { this.deeds.delete(key); this.host.announce('Deed void', `${d.name} is gone`); this.host.changed(); }
    }
    if (this.seen.size > 2000) this.seen.clear();
    this.pennants();
  }

  /** One gold pennant on the top of every lot of the player's in memory, stood on its own roof (render/roofTop.ts). */
  private pennants(): void {
    let n = 0;
    const max = this.poles.instanceMatrix.count;
    roofBudget(6);
    for (const key of this.deeds.keys()) {
      const r = this.resolve(key);
      if (!r) continue;
      for (const b of r.port ? [r.b] : r.all) {
        if (n >= max) break;
        if (!pennantAt(r.w, b, 'nw', this.at)) continue;
        this.m.makeTranslation(this.at.x, this.at.y, this.at.z);
        this.poles.setMatrixAt(n, this.m);
        this.flags.setMatrixAt(n, this.m);
        n++;
      }
    }
    this.poles.count = this.flags.count = n;
    this.poles.instanceMatrix.needsUpdate = this.flags.instanceMatrix.needsUpdate = true;
  }

  // ---- the window's numbers ----

  /** Lots held, what they cost, what they have taken, and their takings over the trailing week. */
  totals(): { lots: number; paid: number; took: number; week: number } {
    let paid = 0, took = 0, week = 0;
    for (const d of this.deeds.values()) {
      this.roll(d);
      paid += d.paid; took += d.took; week += this.trailing(d).took;
    }
    return { lots: this.deeds.size, paid, took, week };
  }

  /** How many lots are held in each town, and the high-water marks the deeds watch. */
  private tally(): void {
    deeds.best('lotsHeld', this.deeds.size);
    const by = new Map<string, number>();
    for (const d of this.deeds.values()) if (d.townKey) by.set(d.townKey, (by.get(d.townKey) ?? 0) + 1);
    deeds.best('monopoly', Math.max(0, ...by.values()));
  }

  heldIn(townKey: string): Deed[] { return [...this.deeds.values()].filter((d) => d.townKey === townKey); }

  /** Owned lots for the map: which cell, and where in it. */
  pins(): { cx: number; cz: number; x: number; z: number }[] {
    return [...this.deeds.values()].map((d) => {
      const [cx, cz] = d.key.split('#')[0].split(',').map(Number);
      return { cx, cz, x: d.x, z: d.z };
    });
  }

  // ---- the save ----

  toSave(): Record<string, SavedDeed> {
    const out: Record<string, SavedDeed> = {};
    for (const d of this.deeds.values()) {
      out[d.key] = [d.kind, d.name, d.townKey, d.town, +d.x.toFixed(1), +d.z.toFixed(1), d.day, d.paid, Math.round(d.ceil), Math.round(d.took), Math.round(d.tax), d.ins, d.outs, d.visits];
      if (d.hqTerms) out[d.key][14] = 1;
      const from = this.day() - WEEK;
      const week = d.week.filter((w) => w[0] > from).map((w) => [w[0], Math.round(w[1]), w[2], w[3]] as WeekDay);
      if (week.length) { out[d.key][14] ??= null; out[d.key][15] = week; }
      // what it would fetch now, kept for a world update (estateRefund); an island not in memory keeps the last figure
      const v = this.saleValue(d.key);
      if (v !== null) d.worth = v;
      if (d.worth !== undefined) { out[d.key][14] ??= null; out[d.key][15] ??= null; out[d.key][16] = d.worth; }
      // a plant (docs/supplychains.html): its bins, run, clock and stock; worth −1 stands in where none was ever priced
      // (estateRefund and parse read a negative worth as none)
      if (d.plant) { out[d.key][14] ??= null; out[d.key][15] ??= null; out[d.key][16] ??= -1; out[d.key][17] = packPlant(d.plant); }
    }
    return out;
  }

  fromSave(saved: Record<string, SavedDeed> | undefined): void {
    this.deeds.clear();
    this.gather.clear();
    this.seen.clear();
    for (const [key, t] of Object.entries(saved ?? {})) {
      const d = this.parse(key, t);
      if (d) this.deeds.set(key, d);
    }
    this.poles.count = this.flags.count = 0;
  }

  /** One saved deed as a deed, or null (with a word in the console) when it makes no sense. */
  private parse(key: string, t: SavedDeed): Deed | null {
    if (!Array.isArray(t) || t.length < 14 || !/#[bp]\d+$/.test(key)) { console.warn(`estate: dropped a deed that makes no sense: ${key}`); return null; }
    const [kind, name, tk, town, x, z, day, paid, ceil, took, tax, ins, outs, visits, hqTerms, wk, worth, pl] = t;
    // the trailing week (absent from saves before it was kept): only well-formed days
    const week = (Array.isArray(wk) ? wk : []).filter((w): w is WeekDay => Array.isArray(w) && w.length === 4 && w.every((n) => typeof n === 'number' && Number.isFinite(n)));
    const plant = pl ? unpackPlant(pl) : null;
    return { key, kind, name, townKey: tk, town, x, z, day, paid, ceil, took, tax, ins, outs, visits, today: 0, d0: -1, loadsToday: 0, visitsToday: 0, week, ...(typeof worth === 'number' && Number.isFinite(worth) && worth >= 0 ? { worth } : {}), ...(hqTerms === 1 ? { hqTerms: true } : {}), ...(plant ? { plant } : {}) };
  }

  /**
   * A shared fleet's building, as another member's game saved it (docs/sharedfleets.html): this game's from now
   * on too. Kept as it stands when already held (its takings here are this game's own count).
   */
  adopt(key: string, t: SavedDeed): void {
    if (this.deeds.has(key)) return;
    const d = this.parse(key, t);
    if (!d) return;
    this.deeds.set(key, d);
    this.tally();
    this.host.changed();
  }

  /** A shared fleet's building sold by another member: no longer this game's. */
  forget(key: string): void {
    if (!this.deeds.delete(key)) return;
    this.tally();
    this.host.changed();
  }

  // ---- the console: pr.estate ----

  console() {
    return {
      list: () => [...this.deeds.values()].map((d) => ({ key: d.key, name: d.name, town: d.town, paid: d.paid, took: Math.round(d.took), today: Math.round(d.today), week: Math.round(this.trailing(d).took), ceil: Math.round(d.ceil) })),
      /** Grant a deed without paying, for a building key `cx,cz#b<uid>` or harbour `cx,cz#p<id>`. */
      give: (key: string) => {
        const r = this.resolve(key);
        if (!r) return 'not in memory';
        const q = this.quote(r.w, r.b);
        const day = this.day();
        this.deeds.set(q.key, {
          key: q.key, kind: q.harbour ? 'harbour' : r.b.kind, name: q.name, townKey: q.townKey, town: q.town,
          x: r.b.x + r.b.w / 2, z: r.b.z + r.b.d / 2, day, paid: 0, ceil: q.price / ESTATE.ceilingDays,
          took: 0, tax: 0, ins: 0, outs: 0, visits: 0, today: 0, d0: day, loadsToday: 0, visitsToday: 0, week: [],
        });
        this.host.changed();
        this.onBought?.(r.w, r.b);
        return q.name;
      },
      /**
       * The trade the ledger has measured at every door in memory, by town kind: median and busiest $/h,
       * and the payback each would quote. What ESTATE.yield and ESTATE.payback are to be fitted against.
       */
      norms: () => {
        const by = new Map<string, { rate: number; days: number }[]>();
        for (const w of this.host.worlds()) {
          for (const t of w.towns) {
            const list = by.get(t.kind) ?? [];
            for (const b of t.buildings) {
              if (b.gone || b.uid < 0) continue;
              const q = this.quote(w, b);
              if (q.trades) list.push({ rate: q.rate, days: q.days });
            }
            by.set(t.kind, list);
          }
        }
        const days = (d: number) => (Number.isFinite(d) ? Math.round(d) : 'floor only');
        const out: Record<string, unknown> = {};
        for (const [kind, all] of by) {
          if (!all.length) continue;
          all.sort((p, q) => p.rate - q.rate);
          const mid = all[Math.floor(all.length / 2)], top = all[all.length - 1];
          out[kind] = { lots: all.length, 'median $/h': +mid.rate.toFixed(2), 'busiest $/h': +top.rate.toFixed(2), 'median payback': days(mid.days), 'busiest payback': days(top.days) };
        }
        console.table(out);
        return `yield ${ESTATE.yield} · payback ${ESTATE.payback} days · lot unit ${ECONOMY.lotUnit} $/h`;
      },
    };
  }
}
