import type { World } from '../../world/tiles';
import { townKey, LEVY_FAC } from '../ledger';
import { ROAD_MUL } from '../economy';
import { Carriage } from '../carriage';
import type { Agent } from '../traffic';
import type { VehicleDef } from '../vehicles';
import { FACTIONS, RUNG, type FactionId } from './factions';
import { reputation } from './reputation';

/**
 * What the factions' people do about the player (docs/factions.html, the roster's Hostile and Sworn lines).
 * Friends acknowledge you as they pass. A faction you are Hostile with makes trouble: a patrol pulls you
 * over by day, your drivers' tyres are slashed after dark, a hired vehicle goes missing for an hour, the
 * levy and the road builder cost more, the ferries charge double, the papers forget your trade. Honoured
 * and Sworn, the same levers go the other way. Everything is a lever another file already has; this sets
 * them as the bars move, and runs the few things that happen on the road.
 */
interface FactionFxHost {
  /** The player in world tiles; null when there is none. */
  player(): { x: number; y: number; z: number; v: number; def: VehicleDef } | null;
  /** The hour of the day, and game hours since the world began. */
  hour(): number;
  hours(): number;
  /** Islands in memory (for the towns with a news station). */
  worlds(): World[];
  fine(n: number, why: string): void;
  announce(title: string, body: string): void;
  float(text: string, x: number, y: number, z: number, kind: 'info' | 'bad'): void;
  /** Hired drivers out on the road: a name and where. */
  crew(): { name: string; x: number; z: number }[];
  /** A short toot or a chime for a faction's greeting. */
  greet?(): void;
}

/** Seconds a pull-over holds the car. */
const PULL_HOLD = 5;
/** Tiles within which a faction vehicle greets a friend, or a hostile patrol stops you. */
const GREET_R = 4, PATROL_R = 7;
/** Seconds between greetings from one faction. */
const GREET_GAP = 60;

const isNight = (h: number): boolean => h >= 19 || h < 5.5;

export class FactionFx {
  /** A patrol is pulling the player over: the car brakes to a halt on its own. */
  holding = false;
  private holdT = 0;
  private scanT = 0;
  private leverT = 0;
  private greeted = new Map<FactionId, number>();
  private clock = 0;
  /** Game hours of the last pull-over, slashing and vanishing. */
  private lastPull = -99;
  private lastSlash = -99;
  private lastVanish = -99;
  private news = new Set<string>();
  private newsT = 0;
  /** Ferries cost this many times their fare (the Guild). */
  ferryMul = 1;

  constructor(private host: FactionFxHost) {
    Carriage.memory = (key) => this.memory(key);
  }

  /** Hold the player's car for a few seconds (a checkpoint, a search). */
  hold(seconds: number): void {
    this.holding = true;
    this.holdT = Math.max(this.holdT, seconds);
  }

  update(dt: number, agents: Agent[]): void {
    if (dt <= 0) return;
    this.clock += dt;
    if (this.holding && (this.holdT -= dt) <= 0) this.holding = false;
    if ((this.leverT -= dt) <= 0) { this.leverT = 1; this.levers(); }
    if ((this.newsT -= dt) <= 0) { this.newsT = 6; this.findNews(); }
    if ((this.scanT -= dt) > 0) return;
    this.scanT = 0.25;
    const p = this.host.player();
    if (!p) return;
    const hour = this.host.hour(), now = this.host.hours();
    for (const a of agents) {
      const f = a.faction as FactionId | undefined;
      if (!f) continue;
      const ax = a.w.ox + a.state.x, az = a.w.oz + a.state.z;
      const d = Math.hypot(ax - p.x, az - p.z);
      if (d > PATROL_R) continue;
      reputation.meet(f);
      const r = reputation.rung(f);
      if (r >= RUNG.friend && d < GREET_R && this.clock - (this.greeted.get(f) ?? -1e9) > GREET_GAP) {
        this.greeted.set(f, this.clock);
        this.host.float(`${FACTIONS[f].icon} ${greeting(f, r)}`, ax, a.state.y + 0.6, az, 'info');
        this.host.greet?.();
      }
      // a hostile constabulary pulls you over by day, once a game hour at most
      if (f === 'police' && r <= RUNG.hostile && !isNight(hour) && Math.abs(p.v) > 0.4 && now - this.lastPull > 1) {
        this.lastPull = now;
        this.holding = true;
        this.holdT = PULL_HOLD;
        const fine = 40;
        this.host.fine(fine, 'Pulled over');
        this.host.float(`−$${fine} pulled over`, p.x, p.y + 0.6, p.z, 'bad');
        this.host.announce('🚓 Pulled over', `The Constabulary has nothing good to say about you: $${fine} for a broken tail light that wasn’t broken`);
      }
    }
    // after dark: the Family's men find your drivers, and the Visitors take a vehicle for an hour
    if (isNight(hour)) {
      const crew = this.host.crew();
      if (crew.length && reputation.rung('family') <= RUNG.hostile && now - this.lastSlash > 24) {
        this.lastSlash = now;
        const c = crew[Math.floor(Math.random() * crew.length)];
        this.host.fine(60, 'Slashed tyres');
        this.host.announce('🎩 Slashed tyres', `${c.name} came back to four flat tyres on a quiet road: $60 to put it right. The Family remembers you`);
      }
      if (crew.length && reputation.rung('visitors') <= RUNG.hostile && now - this.lastVanish > 48) {
        this.lastVanish = now;
        const c = crew[Math.floor(Math.random() * crew.length)];
        this.host.fine(90, 'Fetched from a field');
        this.host.announce('🛸 Missing time', `${c.name} lost an hour on the road and woke up in a field, the vehicle beside them: $90 to tow it out`);
      }
    }
  }

  /** The levers other files read, set from the bars. */
  private levers(): void {
    const m = reputation.rung('ministry');
    LEVY_FAC.add = m <= RUNG.hostile ? 5 : 0;
    LEVY_FAC.halfUnheld = m >= RUNG.sworn;
    const u = reputation.rung('unions');
    ROAD_MUL.v = u <= RUNG.hostile ? 1.25 : u >= RUNG.sworn ? 0.85 : u >= RUNG.honoured ? 0.9 : 1;
    const g = reputation.rung('guild');
    this.ferryMul = g <= RUNG.hostile ? 2 : g >= RUNG.honoured ? 0.5 : 1;
  }

  /** How long a town with a news station remembers the player's trade, by the Press. */
  private memory(key: string): number {
    if (!this.news.has(key)) return 1;
    const r = reputation.rung('press');
    return r <= RUNG.hostile ? 2 / 3 : r >= RUNG.sworn ? 4 / 3 : r >= RUNG.honoured ? 1.15 : 1;
  }

  private findNews(): void {
    for (const w of this.host.worlds()) {
      for (const t of w.towns) if (t.buildings.some((b) => b.kind === 'newsStation' && !b.gone)) this.news.add(townKey(w, t));
    }
  }
}

function greeting(f: FactionId, r: number): string {
  const lines: Record<FactionId, string[]> = {
    police: ['A wave from the patrol', 'Lights flashed, friendly'],
    family: ['A nod from the back seat', 'The window rolls down an inch'],
    ministry: ['A gloved wave', 'The driver touches his cap'],
    visitors: ['The lights blink twice', 'A hum you feel in your teeth'],
    unions: ['A horn from the cab', 'A thumbs up from the crew'],
    post: ['A toot from the postie', 'A wave from the round'],
    army: ['A salute from the hatch', 'A flash of the headlamps'],
    studios: ['Air kisses', 'A wave from behind sunglasses'],
    guild: ['A wave from the wheel', 'Gulls and a shout'],
    press: ['Flashbulbs', '“Any comment?”'],
  };
  const l = lines[f];
  return r >= RUNG.sworn ? `${FACTIONS[f].short} salute you` : l[Math.floor(Math.random() * l.length)];
}
