import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import { N, STEP, Feature, World, DIRS, idx, inB, waterDepth, heightAt, edgeMismatch, type Building, type Town, type TownKind } from '../world/tiles';
import { stadiumPlanOf, stadiumToIsland, stadiumToLocal } from '../world/stadiums';
import { regionOf } from '../world/regions';
import { Herds } from './herds';
import { Wildlife } from './wildlife';
import { PoolLife, lidoDeckSpot } from './pools';
import { rand } from '../util/math';

/** People per building, by kind of town: a handful in the country, crowds downtown. */
const DENSITY: Record<TownKind, number> = { rural: 0.08, suburb: 0.35, city: 0.7, metro: 0.9, mega: 1.3 };
const MAX_PEOPLE = 900;
const RADIUS = 0.045;
const WALK = 0.34;             // tiles per second
const PATHS_PER_FRAME = 14;
const PAIR_CHANCE = 0.2;       // how often someone sets off with a companion beside them
const MAX_PROTEST = 26;
/** Most people out at beaches and pistes at once. */
const MAX_VISITORS = 180;
/**
 * A grown-up is a little figure, the one sitting in a Sunny convertible (render/vehicleMeshes.ts Kit.rider): a shirt
 * of a torso and a head over it, standing on the ground and turned the way they walk. Children stay the round little
 * balls everybody used to be (the user, 10 Nov 2026), about one in seven, one in three round a school or a playground.
 */
const TORSO_W = 0.07, TORSO_H = 0.1, TORSO_D = 0.05, HEAD_R = 0.032;
const CHILD_SHARE = 1 / 7, CHILD_SHARE_PLAY = 1 / 3;
const SKIN = [0xf1c9a5, 0xe0ac84, 0xc68a62, 0x9a6440, 0x6e4630];
/** How fast a figure turns to face the way it walks (radians a second). */
const TURN = 6;
/** What a beach or a piste is doing: lying about, strolling, or in and out of the water. */
type Doing2 = 'lie' | 'stroll' | 'paddle';

/** Somebody spending the afternoon somewhere that is not a town. */
interface Visitor {
  x: number; z: number; y: number;
  hx: number; hz: number;        // where they are heading
  doing: Doing2;
  timer: number;
  speed: number;
  phase: number;
  spot: { kind: 'beach' | 'quarry' | 'ski'; x: number; z: number; r: number };
  child: boolean;
  yaw: number;
}

const COLOURS = [0xe2412f, 0x2f7fb5, 0xf2c14e, 0x3f9b4a, 0x8e5cc7, 0xf28c38, 0x2bb3a3, 0xf49ab5, 0xf4f2ec, 0x3a3f45, 0xc9463d, 0x6fb8e0];
const SIGNS = [0xf4f2ec, 0xf2c14e, 0xf49ab5, 0x9fd8ff, 0xffffff];

type Pt = { x: number; z: number };
type Doing = 'walk' | 'inside' | 'wander' | 'sit' | 'queue' | 'follow' | 'protest';

/** What a person is heading for: a front door, or an open place to spend time in. */
interface Goal { b: Building; door: Pt; activity: boolean }

interface Person {
  /** Where it was last drawn (update): one standing still, or indoors, isn't written into the buffers again. */
  dx?: number; dz?: number; dyaw?: number; hid?: boolean;
  town: Town;
  x: number; z: number; y: number;
  doing: Doing;
  timer: number;
  path: Pt[];
  wp: number;
  goal: Goal | null;
  here: Building | null;     // where they are (or were last)
  speed: number;
  phase: number;             // walking bob
  wantsPath: boolean;
  partner: Person | null;    // someone walking beside us
  leader: Person | null;     // the person we're walking beside
  slot: number;              // place in a protest's ranks
  /** A child: a ball. Everyone else is a figure with a torso and a head. */
  child: boolean;
  /** The way the figure faces, and where it was last frame (to turn it the way it walks). */
  yaw: number; lx: number; lz: number;
}

/** A march: gathering at one end of a street, walking it in ranks of four with signs up, a rally at the other end. */
interface Protest {
  town: Town;
  path: Pt[];
  lengths: number[];         // distance along the path to each point
  s: number;                 // how far the front rank has marched
  phase: 'gather' | 'march' | 'rally';
  timer: number;
  members: Person[];
}

const pick = <T,>(a: T[]): T => a[Math.floor(Math.random() * a.length)];

/** Kinds of place people go and spend a while doing something rather than going indoors. */
const ACTIVITY = new Set<Building['kind']>([
  'park', 'pitch', 'plaza', 'stadium',
  'meadow', 'civicSquare', 'fountainSquare', 'greenway', 'picnicGround', 'dogRun', 'plazaSteps', 'sculpturePark', 'bandstandGreen',
  'memorial', 'skatePark', 'promenade', 'cemetery', 'amphitheatre', 'marketSquare', 'lakePark', 'courts', 'formalGarden',
  'allotments', 'botanicalGarden', 'playground', 'grove', 'greatPark', 'zoo', 'fairground', 'lido', 'waterPark', 'miniGolf', 'racetrack',
]);
/** Open places where people sit down once they get there: on rims, steps, tiers, rugs and loungers. */
const SIT = new Set<Building['kind']>(['picnicGround', 'bandstandGreen', 'amphitheatre', 'fountainSquare', 'plazaSteps', 'lido', 'ashiyu']);
/** Open places where people play: quick loops round a small patch. */
const PLAY = new Set<Building['kind']>(['pitch', 'playground', 'skatePark', 'courts', 'dogRun', 'waterPark']);
/** Where more of the people are children: schools, playgrounds, pitches, parks for the young. */
const CHILDREN = new Set<Building['kind']>(['school', 'elementarySchool', 'kindergarten', 'playground', 'pitch', 'waterPark', 'skatePark', 'zoo', 'fairground']);
/** Doors people queue at rather than walk straight through: a marquee, a velvet rope, the court steps. */
const QUEUE = new Set<Building['kind']>(['cinema', 'theatre', 'nightclub', 'courthouse', 'operaHouse', 'chicagoTheatre']);
/** Solid buildings people go into. */
const INDOORS = new Set<Building['kind']>([
  'house', 'townhouse', 'apartment', 'farmhouse', 'shop', 'store', 'grocery', 'mall', 'diner', 'gas', 'office', 'skyscraper',
  'school', 'police', 'fire', 'hospital', 'clinic', 'library', 'museum', 'cityHall', 'church', 'barn', 'harbourOffice',
  'courthouse', 'postOffice', 'villageHall', 'communityCentre', 'kindergarten', 'university', 'busStation', 'cathedral', 'chapel',
  'mosque', 'temple', 'ministry', 'hotel', 'motel', 'bank', 'carDealership', 'bigBox', 'stripMall', 'cafe', 'bakery', 'officePark',
  'techCampus', 'factory', 'brewery', 'pub', 'fastFood', 'garage', 'marketHall', 'departmentStore', 'exchange', 'cinema', 'theatre',
  'arena', 'concertHall', 'bowlingAlley', 'casino', 'aquarium', 'iceRink', 'nightclub', 'sportsHall', 'bungalow', 'cottage', 'duplex',
  'terraceRow', 'mansion', 'retirementHome', 'trailerPark', 'courtyardBlock', 'towerBlock', 'condoTower', 'stables', 'farmShop',
  'canalWarehouse', 'parliament', 'thermalBath', 'saloon', 'meetingHouse', 'statehouse',
  'kremlin', 'stalinTower', 'blueMosque', 'bazaar', 'stepPyramid', 'ballCourt',
  'colosseum', 'forum', 'tulou', 'drumTower', 'wat', 'khmerTemple',
  'coitTower', 'palaceFineArts', 'pyramidTower', 'glassSpire',
  'shibuyaTower', 'metroGovTower', 'cocoonTower', 'godzillaTower', 'yokocho',
  'notreDame', 'louvrePyramid', 'sacreCoeur', 'empireState', 'chryslerBuilding', 'flatironBuilding',
  'capitolBuilding', 'lincolnMemorial', 'whiteHouse', 'jeffersonMemorial',
  'operaHouse', 'willisTower', 'hancockCenter', 'marinaCity', 'wrigleyBuilding', 'tribuneTower', 'chicagoTheatre',
  'rijksmuseum', 'centraalStation', 'westerkerk', 'canalHouses',
  'circusMaximus', 'pantheon', 'stPeters', 'vittoriano', 'treviFountain', 'spanishSteps',
  'dotonbori', 'tsutenkaku', 'osakaCastle', 'shotengai', 'umedaSky',
  'stEuphemia', 'pileGate', 'clockLoggia', 'riva', 'peristyle',
  // an onsen town's inns and its grand bath (world/onsenKinds.ts)
  'ryokan', 'fukuzumiro', 'resortRyokan', 'minshuku', 'dogoHonkan',
  // a lake town's palace hotels, estates, villas and its church (world/lakeKinds.ts)
  'grandHotel', 'lakeEstate', 'comoVilla', 'lakeChurch', 'lakeCottage', 'lakeBoathouse',
  'arcade', 'ramenShop', 'sushiBar', 'dumplingHouse', 'noodleBar', 'trattoria', 'curryHouse', 'deli', 'taqueria', 'kebabShop', 'chippy',
  // places to play (world/playKinds.ts)
  'elementarySchool', 'kartTrack', 'archeryRange', 'outdoorMall', 'beachResort',
]);

/** Is this open place or queue open at this hour? */
function openAt(kind: Building['kind'], hour: number): boolean {
  switch (kind) {
    case 'cinema': case 'theatre': case 'operaHouse': case 'chicagoTheatre': return hour >= 17 && hour < 23.5;
    case 'nightclub': return hour >= 22 || hour < 4;
    case 'courthouse': return hour >= 9 && hour < 16;
    case 'amphitheatre': case 'bandstandGreen': case 'fairground': case 'promenade': return hour >= 9 && hour < 23;
    default: return hour >= 7 && hour < 20.5;
  }
}

/** Standing out of doors, whether in an open place or in a queue at a door. */
const outdoors = (kind: Building['kind']) => ACTIVITY.has(kind) || QUEUE.has(kind);
/** Where a protest can begin or end. */
const GOVERNMENT = new Set<Building['kind']>(['cityHall', 'police']);

/** A march has formed: the town, the building it marches on, how many (main.ts writes it down for the paper, docs/newspaper.html). */
export const protestNews: { on: ((w: World, town: Town, b: Building, n: number) => void) | null } = { on: null };

/**
 * Pedestrians: little coloured spheres walking short hops between nearby buildings in towns (a
 * few in the country, plenty downtown), sometimes in pairs, going indoors for a while, lingering in
 * parks, on pitches, round plazas and in the stadium stands, and mostly home late at night. Now
 * and then in a big city a group gathers with signs and marches a street to or from city hall or
 * the police station.
 */
export class Pedestrians {
  /** The children, as balls (and nobody else: a grown-up's slot in it is hidden). */
  readonly mesh: THREE.InstancedMesh;
  /** The grown-ups: shirts (torsos) and heads, a slot each for every person (a child's hidden). */
  readonly torsos: THREE.InstancedMesh;
  readonly heads: THREE.InstancedMesh;
  readonly visitorTorsos: THREE.InstancedMesh;
  readonly visitorHeads: THREE.InstancedMesh;
  private e = new THREE.Euler();
  readonly signs: THREE.InstancedMesh;
  private people: Person[] = [];
  private w: World | null = null;
  private places = new Map<Town, Building[]>();
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private v = new THREE.Vector3();
  private one = new THREE.Vector3(1, 1, 1);
  private up = new THREE.Vector3(0, 1, 0);
  private hidden = new THREE.Matrix4().makeScale(0, 0, 0);
  private protest: Protest | null = null;
  private protestTimer = rand(150, 360);
  private time = 0;
  /** People at the beaches in summer and on the pistes in winter. */
  readonly visitorMesh: THREE.InstancedMesh;
  private visitors: Visitor[] = [];
  private season = { warm: 0, cold: 0 };
  private visitorTimer = 0;

  /** Share of the usual crowd this island gets (the one the player is on gets all of it). */
  budget = 1;
  /** The biome's animals and country folk: camel trains, herds, flocks, surfers, pilgrims. */
  readonly herds: Herds;
  /** Public swim time at the lidos (pools.ts). */
  readonly pools: PoolLife;
  /** The wild animals: hawks, eagles, geese, deer, foxes, the odd bear and mountain lion (wildlife.ts). */
  readonly wild: Wildlife;

  constructor(parent: THREE.Object3D) {
    this.herds = new Herds(parent);
    this.wild = new Wildlife(parent);
    this.pools = new PoolLife(parent);
    const mat = new THREE.MeshStandardMaterial({ roughness: 0.6, metalness: 0 });
    this.mesh = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(RADIUS, 1), mat, MAX_PEOPLE);
    this.mesh.count = 0;
    this.mesh.frustumCulled = false;
    const c = new THREE.Color();
    for (let i = 0; i < MAX_PEOPLE; i++) this.mesh.setColorAt(i, c.setHex(COLOURS[i % COLOURS.length]).offsetHSL(0, 0, (Math.random() - 0.5) * 0.12));
    parent.add(this.mesh);

    const stick = new THREE.BoxGeometry(0.008, 0.09, 0.008).translate(0, 0.045, 0);
    const board = new THREE.BoxGeometry(0.075, 0.05, 0.008).translate(0, 0.11, 0);
    this.signs = new THREE.InstancedMesh(mergeGeometries([stick, board])!, new THREE.MeshStandardMaterial({ roughness: 0.8 }), MAX_PROTEST);
    this.signs.count = 0;
    this.signs.frustumCulled = false;
    for (let i = 0; i < MAX_PROTEST; i++) this.signs.setColorAt(i, c.setHex(SIGNS[i % SIGNS.length]));
    parent.add(this.signs);

    this.visitorMesh = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(RADIUS * 1.25, 1), mat, MAX_VISITORS);
    this.visitorMesh.count = 0;
    this.visitorMesh.frustumCulled = false;
    for (let i = 0; i < MAX_VISITORS; i++) {
      this.visitorMesh.setColorAt(i, c.setHex(COLOURS[(i * 5 + 3) % COLOURS.length]).offsetHSL(0, 0, (Math.random() - 0.5) * 0.16));
    }
    parent.add(this.visitorMesh);

    // the grown-ups' figures: a torso standing on the ground, a head on it; shirts in the crowd's colours, five skins
    const torso = new THREE.BoxGeometry(TORSO_W, TORSO_H, TORSO_D).translate(0, TORSO_H / 2, 0);
    const head = new THREE.IcosahedronGeometry(HEAD_R, 1).translate(0, TORSO_H + HEAD_R * 0.85, 0);
    const figure = (geo: THREE.BufferGeometry, n: number, colour: (i: number) => number) => {
      const im = new THREE.InstancedMesh(geo, mat, n);
      im.count = 0;
      im.frustumCulled = false;
      for (let i = 0; i < n; i++) im.setColorAt(i, c.setHex(colour(i)).offsetHSL(0, 0, (Math.random() - 0.5) * 0.1));
      parent.add(im);
      return im;
    };
    this.torsos = figure(torso, MAX_PEOPLE, (i) => COLOURS[i % COLOURS.length]);
    this.heads = figure(head, MAX_PEOPLE, (i) => SKIN[(i * 7 + 3) % SKIN.length]);
    this.visitorTorsos = figure(torso.clone(), MAX_VISITORS, (i) => COLOURS[(i * 5 + 3) % COLOURS.length]);
    this.visitorHeads = figure(head.clone(), MAX_VISITORS, (i) => SKIN[(i * 3 + 1) % SKIN.length]);
  }

  /** Pose a grown-up's figure in slot i of a pair of meshes: standing (or lying flat out along its way) at (x, y, z). */
  private poseFigure(torsos: THREE.InstancedMesh, heads: THREE.InstancedMesh, i: number, x: number, y: number, z: number, yaw: number, lying = false): void {
    this.e.set(lying ? -Math.PI / 2 : 0, yaw, 0, 'YXZ');
    this.q.setFromEuler(this.e);
    this.v.set(x, y, z);
    this.m.compose(this.v, this.q, this.one);
    torsos.setMatrixAt(i, this.m);
    heads.setMatrixAt(i, this.m);
  }

  /** How warm and how cold it is, 0..1: beaches fill up in one, pistes in the other. */
  setSeason(warm: number, cold: number): void {
    this.season.warm = warm;
    this.season.cold = cold;
    this.herds.setSeason(warm, cold);
    // the geese are on the move between summer and winter, either way
    this.wild.setSeason(warm, cold, warm > 0.1 && warm < 0.7 && cold < 0.4 ? 1 : 0);
    this.pools.setSeason(warm);
  }

  /** Where the player is in this island's frame, and how fast they are going: herds scatter from the car. */
  setPlayer(x: number, z: number, speed: number): void {
    this.herds.setPlayer(x, z, speed);
    this.wild.setPlayer(x, z, speed);
  }

  /** Beaches in a biome that keeps them busy all year (the Shallows) are never out of season. */
  private beachSeason(w: World, sp: { x: number; z: number }): number {
    const tx = Math.min(N - 1, Math.max(0, Math.floor(sp.x))), tz = Math.min(N - 1, Math.max(0, Math.floor(sp.z)));
    return regionOf(w.regionK[idx(tx, tz)])?.beachAllYear ? Math.max(this.season.warm, 0.85) : this.season.warm;
  }

  dispose(): void {
    this.herds.dispose();
    this.wild.dispose();
    this.pools.dispose();
    this.setWorld(null);
    // each county's crowd is its own: its geometries, instance buffers and materials go with it (11 Nov 2026
    // perf audit: a crowd is made for every county that comes alive or flips light/drawn, ~20 geometries a time)
    const mats = new Set<THREE.Material>();
    for (const im of [this.mesh, this.signs, this.visitorMesh, this.torsos, this.heads, this.visitorTorsos, this.visitorHeads]) {
      im.removeFromParent();
      im.geometry.dispose();
      mats.add(im.material as THREE.Material);
      im.dispose();
    }
    mats.forEach((m) => m.dispose());
  }

  get count(): number { return this.people.length; }

  /**
   * Film only (title/film.ts drive shots; the user, 11 Nov 2026: the car must never meet anyone): a stretch of road
   * nobody walks onto, in this world's tiles. Anyone on it now is put on the nearer kerb, and walkers wait at its edge.
   * Null lets the road be crossed again.
   */
  keepOff: { x0: number; z0: number; x1: number; z1: number } | null = null;
  setKeepOff(r: { x0: number; z0: number; x1: number; z1: number } | null): void {
    this.keepOff = r;
    if (!r) return;
    for (const p of this.people) {
      if (!this.offLimits(p.x, p.z)) continue;
      // out the shorter way across it
      const ex = [r.x0 - 0.4 - p.x, r.x1 + 0.4 - p.x], ez = [r.z0 - 0.4 - p.z, r.z1 + 0.4 - p.z];
      const bx = Math.abs(ex[0]) < Math.abs(ex[1]) ? ex[0] : ex[1], bz = Math.abs(ez[0]) < Math.abs(ez[1]) ? ez[0] : ez[1];
      if (Math.abs(bx) < Math.abs(bz)) p.x += bx; else p.z += bz;
    }
  }
  private offLimits(x: number, z: number): boolean {
    const r = this.keepOff;
    return !!r && x >= r.x0 && x <= r.x1 && z >= r.z0 && z <= r.z1;
  }
  counts(): Record<Doing, number> {
    const out: Record<Doing, number> = { walk: 0, inside: 0, wander: 0, sit: 0, queue: 0, follow: 0, protest: 0 };
    for (const p of this.people) out[p.doing]++;
    return out;
  }
  get marching(): { phase: string; members: number; along: number; length: number } | null {
    const p = this.protest;
    return p ? { phase: p.phase, members: p.members.length, along: +p.s.toFixed(1), length: +p.lengths[p.lengths.length - 1].toFixed(1) } : null;
  }

  /**
   * The seasonal crowds: a beach fills up on a summer afternoon and empties by evening, a piste
   * fills in winter. They are not town folk and want none of the pathfinding — they simply drift
   * about their own patch of sand or snow, lie down for a while, and wander back to the water.
   */
  private updateVisitors(dt: number, hour: number, w: World): void {
    const spots = w.spots;
    this.visitorTimer -= dt;
    if (this.visitorTimer <= 0) {
      this.visitorTimer = 2.5;
      // how busy it should be: daylight hours, in the right season, and never for a quarry
      const daytime = Math.max(0, Math.min(1, (hour - 8.5) / 2)) * Math.max(0, Math.min(1, (19.5 - hour) / 2));
      let want = 0;
      for (const sp of spots) {
        const season = sp.kind === 'beach' ? this.beachSeason(w, sp) : sp.kind === 'ski' ? this.season.cold : 0;
        want += Math.round(Math.min(34, sp.r * 1.6) * season * daytime);
      }
      want = Math.min(MAX_VISITORS, want);
      while (this.visitors.length > want) this.visitors.pop();
      while (this.visitors.length < want && spots.length) {
        const busy = spots.filter((sp) => (sp.kind === 'beach' ? this.beachSeason(w, sp) : sp.kind === 'ski' ? this.season.cold : 0) > 0.2);
        if (!busy.length) break;
        const sp = pick(busy);
        const at = this.groundIn(w, sp);
        if (!at) break;
        this.visitors.push({
          x: at.x, z: at.z, y: 0, hx: at.x, hz: at.z, doing: 'stroll', timer: rand(1, 8),
          speed: WALK * rand(0.5, 1.1), phase: Math.random() * 6, spot: sp,
          child: Math.random() < CHILD_SHARE * 1.5, yaw: Math.random() * Math.PI * 2,
        });
      }
    }

    const m = this.m, q = this.q, v = this.v, one = this.one;
    let n = 0;
    for (const p of this.visitors) {
      p.timer -= dt;
      if (p.timer <= 0) {
        const r = Math.random();
        p.doing = r < 0.42 ? 'lie' : r < 0.76 ? 'stroll' : 'paddle';
        p.timer = p.doing === 'lie' ? rand(6, 22) : rand(4, 12);
        const sp = p.spot;
        if (p.doing === 'paddle') {
          const edge = this.waterEdge(w, p.x, p.z);
          if (edge) { p.hx = edge.x; p.hz = edge.z; } else p.doing = 'stroll';
        }
        if (p.doing !== 'paddle') {
          const at = this.groundIn(w, sp);
          if (at) { p.hx = at.x; p.hz = at.z; }
        }
      }
      if (p.doing !== 'lie') {
        const dx = p.hx - p.x, dz = p.hz - p.z, d = Math.hypot(dx, dz);
        if (d > 0.08) {
          const step = Math.min(d, p.speed * dt);
          p.x += (dx / d) * step;
          p.z += (dz / d) * step;
        }
      }
      const gx = Math.min(N - 0.001, Math.max(0, p.x)), gz = Math.min(N - 0.001, Math.max(0, p.z));
      const tile = idx(Math.floor(gx), Math.floor(gz));
      const ground = heightAt(w, gx, gz);
      const surf = w.water[tile] >= 0 ? Math.max(ground, w.water[tile] * STEP - 0.035) : ground;
      const bob = p.doing === 'lie' ? -RADIUS * 0.45 : Math.abs(Math.sin(this.time * 5 + p.phase)) * 0.035;
      p.y = surf + RADIUS + bob;
      if (n < MAX_VISITORS) {
        if (p.doing !== 'lie') {
          const dx = p.hx - p.x, dz = p.hz - p.z;
          if (Math.hypot(dx, dz) > 0.08) p.yaw = turnToward(p.yaw, Math.atan2(dx, dz), TURN * dt);
        }
        if (p.child) {
          v.set(p.x, p.y, p.z);
          m.compose(v, q, one);
          this.visitorMesh.setMatrixAt(n, m);
          this.visitorTorsos.setMatrixAt(n, this.hidden);
          this.visitorHeads.setMatrixAt(n, this.hidden);
        } else {
          this.visitorMesh.setMatrixAt(n, this.hidden);
          // a grown-up lies flat on the sand, or stands (up to the knees in the water when paddling)
          const lie = p.doing === 'lie';
          this.poseFigure(this.visitorTorsos, this.visitorHeads, n, p.x, lie ? surf + TORSO_D / 2 : surf + bob * 0.4, p.z, p.yaw, lie);
        }
        n++;
      }
    }
    this.visitorMesh.count = n;
    this.visitorTorsos.count = n;
    this.visitorHeads.count = n;
    if (n) {
      this.visitorMesh.instanceMatrix.needsUpdate = true;
      this.visitorTorsos.instanceMatrix.needsUpdate = true;
      this.visitorHeads.instanceMatrix.needsUpdate = true;
    }
  }

  /** A spot on the sand (or the snow) inside this place, rather than out in the water. */
  private groundIn(w: World, sp: { kind: string; x: number; z: number; r: number }): { x: number; z: number } | null {
    const want = sp.kind === 'ski' ? Feature.Piste : Feature.Beach;
    for (let k = 0; k < 24; k++) {
      const a = Math.random() * Math.PI * 2, rr = Math.sqrt(Math.random()) * sp.r * 0.9;
      const x = sp.x + Math.cos(a) * rr, z = sp.z + Math.sin(a) * rr;
      const tx = Math.floor(x), tz = Math.floor(z);
      if (!inB(tx, tz)) continue;
      const i = idx(tx, tz);
      if (w.feature[i] !== want || waterDepth(w, i) > 0 || w.blocked[i]) continue;
      return { x, z };
    }
    return null;
  }

  /** The nearest tile of shallow water, for anybody who fancies a paddle. */
  private waterEdge(w: World, x: number, z: number): { x: number; z: number } | null {
    const tx = Math.floor(x), tz = Math.floor(z);
    for (let r = 1; r <= 9; r++) {
      for (let k = 0; k < 10; k++) {
        const a = Math.random() * Math.PI * 2;
        const nx = Math.round(tx + Math.cos(a) * r), nz = Math.round(tz + Math.sin(a) * r);
        if (!inB(nx, nz)) continue;
        const i = idx(nx, nz);
        const d = waterDepth(w, i);
        if (d > 0 && d <= 1) return { x: nx + 0.5, z: nz + 0.5 };
      }
    }
    return null;
  }

  setWorld(w: World | null): void {
    this.w = w;
    this.visitors = [];
    this.visitorMesh.count = 0;
    this.people = [];
    this.places.clear();
    this.protest = null;
    this.signs.count = 0;
    this.herds.budget = this.budget;
    this.herds.setWorld(w);
    this.wild.setWorld(w);
    this.pools.budget = this.budget;
    this.pools.setWorld(w);
    if (!w) { this.mesh.count = this.torsos.count = this.heads.count = 0; return; }
    const budget: [Town, number][] = w.towns.map((t) => [t, Math.max(t.kind === 'rural' ? 2 : 6, Math.round(t.buildings.filter((b) => INDOORS.has(b.kind)).length * DENSITY[t.kind]))]);
    const total = budget.reduce((s, [, n]) => s + n, 0);
    const cap = MAX_PEOPLE * this.budget;
    const scale = Math.min(this.budget, total > cap ? cap / total : 1);
    for (const [t, n] of budget) {
      const spots = t.buildings.filter((b) => INDOORS.has(b.kind) || ACTIVITY.has(b.kind));
      if (!spots.length) continue;
      this.places.set(t, spots);
      for (let k = Math.round(n * scale); k > 0; k--) {
        const b = pick(spots);
        const at = ACTIVITY.has(b.kind) ? spotIn(b) : door(b);
        this.people.push({
          town: t, x: at.x, z: at.z, y: 0, doing: ACTIVITY.has(b.kind) ? 'wander' : 'inside', timer: rand(0, 25),
          path: [], wp: 0, goal: null, here: b, speed: WALK * rand(0.8, 1.25), phase: Math.random() * 6, wantsPath: false,
          partner: null, leader: null, slot: 0,
          child: Math.random() < (CHILDREN.has(b.kind) ? CHILD_SHARE_PLAY : CHILD_SHARE), yaw: Math.random() * Math.PI * 2, lx: at.x, lz: at.z,
        });
      }
    }
    this.mesh.count = this.torsos.count = this.heads.count = this.people.length;
  }

  private tickN = 0;
  private owed = 0;

  update(dt: number, hour: number): void {
    const w = this.w;
    if (!w || dt <= 0) return;
    this.time += dt;
    this.updateVisitors(dt, hour, w);
    this.herds.update(dt, hour);
    this.wild.update(dt, hour);
    this.pools.update(dt, hour);
    const late = hour >= 22.5 || hour < 6;

    this.protestTimer -= dt;
    if (this.protestTimer <= 0) {
      this.protestTimer = rand(180, 420);
      if (hour >= 9.5 && hour < 16.5 && Math.random() < 0.6) this.startProtest();
    }
    this.advanceProtest(dt);

    // a county round the one underfoot (budget under 1): its people every third frame, on the frames' time
    // (11 Nov 2026 perf audit: up to 900 a county, every one stepped and written to the GPU every frame)
    this.tickN++;
    if (this.budget < 1) {
      this.owed += dt;
      if (this.tickN % 3 !== 0) { this.drawSigns(); return; }
      dt = Math.min(0.15, this.owed);
    }
    this.owed = 0;
    let paths = PATHS_PER_FRAME, wrote = false;
    for (let i = 0; i < this.people.length; i++) {
      const p = this.people[i];
      p.timer -= dt;
      switch (p.doing) {
        case 'inside':
          if (p.timer <= 0) {
            if (late && Math.random() < 0.85) { p.timer = rand(20, 60); break; }
            this.chooseGoal(p, hour);
          }
          break;
        case 'wander':
        case 'sit':
          this.linger(p, dt, hour);
          break;
        case 'queue':
          if (p.wantsPath && paths > 0) { paths--; this.route(p); }
          break;
        case 'walk':
          this.walk(p, dt);
          break;
        case 'follow':
          this.accompany(p, dt);
          break;
        case 'protest':
          this.march(p, dt);
          break;
      }
      if (p.doing === 'inside') {
        p.lx = p.x; p.lz = p.z;
        if (p.hid) continue;
        this.mesh.setMatrixAt(i, this.hidden);
        this.torsos.setMatrixAt(i, this.hidden);
        this.heads.setMatrixAt(i, this.hidden);
        p.hid = true; wrote = true;
        continue;
      }
      const moving = p.doing === 'walk' || p.doing === 'follow' || p.doing === 'protest';
      if (!moving && !p.hid && p.dx === p.x && p.dz === p.z && p.dyaw === p.yaw) { p.lx = p.x; p.lz = p.z; continue; }
      const bob = moving ? Math.abs(Math.sin(p.phase)) * 0.018 : 0;
      p.y = p.doing === 'sit' && p.here?.kind === 'stadium' ? standY(p, p.here) : heightAt(w, clamp(p.x), clamp(p.z)) + RADIUS;
      // face the way they are going
      const mx = p.x - p.lx, mz = p.z - p.lz;
      if (mx * mx + mz * mz > 1e-6) p.yaw = turnToward(p.yaw, Math.atan2(mx, mz), TURN * dt);
      p.lx = p.x; p.lz = p.z;
      if (p.child) {
        this.m.makeTranslation(p.x, p.y + bob, p.z);
        this.mesh.setMatrixAt(i, this.m);
        this.torsos.setMatrixAt(i, this.hidden);
        this.heads.setMatrixAt(i, this.hidden);
      } else {
        this.mesh.setMatrixAt(i, this.hidden);
        // a grown-up stands on the ground (RADIUS above it was a ball's middle), or on a stand's step at a stadium
        this.poseFigure(this.torsos, this.heads, i, p.x, p.y - RADIUS + bob * 0.6, p.z, p.yaw);
      }
      p.hid = false; p.dx = p.x; p.dz = p.z; p.dyaw = p.yaw; wrote = true;
    }
    if (wrote) {
      this.mesh.instanceMatrix.needsUpdate = true;
      this.torsos.instanceMatrix.needsUpdate = true;
      this.heads.instanceMatrix.needsUpdate = true;
    }
    this.drawSigns();
  }

  // ---- everyday walking ----

  /** Pick somewhere nearby to go next: mostly a building, sometimes a park or the stadium (not after dark). */
  private chooseGoal(p: Person, hour: number): void {
    const spots = this.places.get(p.town);
    if (!spots) return;
    const from: Pt = { x: p.x, z: p.z };
    const night = hour >= 20.5 || hour < 7;
    const game = hour >= 17.5 && hour < 22.5;
    const near = spots.filter((b) => {
      const d = Math.hypot(b.x + b.w / 2 - from.x, b.z + b.d / 2 - from.z);
      if (b.kind === 'stadium') return game && d < 30;
      if (QUEUE.has(b.kind) && openAt(b.kind, hour)) return d < 16 && b !== p.here;
      if (ACTIVITY.has(b.kind)) return !night && openAt(b.kind, hour) && d < 14;
      return d < 12 && b !== p.here && !(night && QUEUE.has(b.kind));
    });

    if (!near.length) { p.timer = rand(10, 30); return; }
    // open places are few among many doors, so give them a fair share of outings
    const outings = near.filter((b) => outdoors(b.kind) && (ACTIVITY.has(b.kind) || openAt(b.kind, hour)));
    const b = outings.length && Math.random() < 0.28 ? pick(outings) : pick(near);
    const activity = ACTIVITY.has(b.kind) || (QUEUE.has(b.kind) && openAt(b.kind, hour));
    p.goal = { b, door: ACTIVITY.has(b.kind) ? edgeOf(b, from) : door(b), activity };
    if (p.here && !outdoors(p.here.kind)) {
      const out = door(p.here);
      p.x = out.x; p.z = out.z;
    }
    p.doing = 'queue';
    p.wantsPath = true;
    // sometimes a friend from the same doorway comes along
    if (Math.random() < PAIR_CHANCE) {
      const friend = this.people.find((o) => o !== p && o.town === p.town && o.doing === 'inside' && !o.leader && !o.partner && Math.hypot(o.x - p.x, o.z - p.z) < 2.5);
      if (friend) {
        friend.leader = p;
        p.partner = friend;
        friend.doing = 'follow';
        friend.x = p.x; friend.z = p.z;
      }
    }
  }

  /** Find a short walking route; failing that, try somewhere else later. */
  private route(p: Person): void {
    p.wantsPath = false;
    const goal = p.goal!;
    const path = footpath(this.w!, p.x, p.z, goal.door.x, goal.door.z);
    if (!path) {
      p.doing = 'inside';
      p.timer = rand(8, 20);
      p.goal = null;
      this.part(p);
      return;
    }
    p.path = path;
    p.wp = 0;
    p.doing = 'walk';
  }

  private walk(p: Person, dt: number): void {
    const target = p.path[p.wp];
    const dx = target.x - p.x, dz = target.z - p.z, d = Math.hypot(dx, dz);
    const step = p.speed * (p.partner ? 0.9 : 1) * dt;
    p.phase += dt * 9;
    // a film drive's road (keepOff): a walker about to step onto it waits at the kerb
    if (this.keepOff) {
      const nx = d <= step ? target.x : p.x + (dx / d) * step, nz = d <= step ? target.z : p.z + (dz / d) * step;
      if (this.offLimits(nx, nz) && !this.offLimits(p.x, p.z)) return;
    }
    if (d <= step) {
      p.x = target.x; p.z = target.z;
      if (++p.wp >= p.path.length) this.arrive(p);
    } else {
      p.x += (dx / d) * step;
      p.z += (dz / d) * step;
    }
  }

  private arrive(p: Person): void {
    const g = p.goal!;
    p.here = g.b;
    p.goal = null;
    if (g.activity) {
      const queue = QUEUE.has(g.b.kind);
      p.doing = g.b.kind === 'stadium' || SIT.has(g.b.kind) ? 'sit' : queue ? 'sit' : 'wander';
      p.timer = g.b.kind === 'stadium' ? rand(90, 240) : queue ? rand(15, 45) : rand(25, 80);
      p.path = [queue ? queueSpot(g.b) : spotIn(g.b)];
      p.wp = 0;
    } else {
      p.doing = 'inside';
      p.timer = rand(15, 70);
    }
    const f = p.partner;
    if (f) {
      this.part(p);
      f.here = p.here;
      f.doing = p.doing;
      f.timer = p.timer + rand(-3, 3);
      f.path = p.doing === 'inside' ? [] : [spotIn(p.here!)];
    }
  }

  /** Walk half a step to the leader's left, matching their pace. */
  private accompany(p: Person, dt: number): void {
    const l = p.leader;
    if (!l || (l.doing !== 'walk' && l.doing !== 'queue')) {
      if (l) this.part(l);
      if (p.doing === 'follow') { p.doing = 'inside'; p.timer = rand(5, 20); }
      return;
    }
    let fx = 1, fz = 0;
    const t = l.path[l.wp];
    if (l.doing === 'walk' && t) {
      const d = Math.hypot(t.x - l.x, t.z - l.z);
      if (d > 1e-3) { fx = (t.x - l.x) / d; fz = (t.z - l.z) / d; }
    }
    const tx = l.x - fz * 0.1, tz = l.z + fx * 0.1;
    const k = Math.min(1, dt * 8);
    p.x += (tx - p.x) * k;
    p.z += (tz - p.z) * k;
    p.phase = l.phase + 1.4;
  }

  private part(leader: Person): void {
    if (leader.partner) leader.partner.leader = null;
    leader.partner = null;
  }

  /** Time in an open place: strolling (or jogging on a pitch) between random spots, sitting in the stands. */
  private linger(p: Person, dt: number, hour: number): void {
    const b = p.here!;
    if (p.timer <= 0 || (b.kind !== 'stadium' && !openAt(b.kind, hour))) {
      this.chooseGoal(p, hour);
      if (p.doing === 'queue') return;
      p.doing = 'inside';
      p.timer = rand(10, 30);
      return;
    }
    if (p.doing === 'sit') {
      if (p.path.length) { const s = p.path[0]; p.x += (s.x - p.x) * Math.min(1, dt * 2); p.z += (s.z - p.z) * Math.min(1, dt * 2); }
      return;
    }
    const target = p.path[0] ?? spotIn(b);
    const dx = target.x - p.x, dz = target.z - p.z, d = Math.hypot(dx, dz);
    const play = PLAY.has(b.kind);
    const pace = play ? p.speed * 2.2 : p.speed * 0.7;
    p.phase += dt * (play ? 16 : 7);
    if (d < 0.05) {
      if (Math.random() < 0.004) p.path = [spotIn(b)];
    } else {
      const step = Math.min(d, pace * dt);
      p.x += (dx / d) * step;
      p.z += (dz / d) * step;
    }
  }

  // ---- protests ----

  /** Gather a group outside city hall or the police station (or bring them to it) and march a street. */
  startProtest(): boolean {
    const w = this.w;
    if (!w || this.protest) return false;
    const town = w.towns.find((t) => t.kind === 'metro');
    if (!town) return false;
    const govt = town.buildings.filter((b) => GOVERNMENT.has(b.kind));
    if (!govt.length) return false;
    const b = pick(govt);
    const kerb = kerbTile(w, b);
    if (kerb < 0) return false;
    const tiles = streetWalk(w, town, kerb, 14, 30);
    if (!tiles) return false;
    if (Math.random() < 0.5) tiles.reverse(); // end at the building instead of starting there
    const recruits = this.people.filter((p) => p.town === town && p.doing === 'inside' && !p.partner && !p.leader);
    const size = Math.min(recruits.length, MAX_PROTEST, 12 + Math.floor(Math.random() * 13));
    if (size < 8) return false;
    for (let k = recruits.length - 1; k > 0; k--) { const j = Math.floor(Math.random() * (k + 1)); [recruits[k], recruits[j]] = [recruits[j], recruits[k]]; }
    const path = tiles.map((t) => ({ x: (t % N) + 0.5, z: Math.floor(t / N) + 0.5 }));
    const lengths = [0];
    for (let k = 1; k < path.length; k++) lengths.push(lengths[k - 1] + Math.hypot(path[k].x - path[k - 1].x, path[k].z - path[k - 1].z));
    const protest: Protest = { town, path, lengths, s: 0, phase: 'gather', timer: 25, members: recruits.slice(0, size) };
    protest.s = this.rearOffset(protest);
    protest.members.forEach((m, k) => {
      m.doing = 'protest';
      m.slot = k;
      m.goal = null;
      if (m.here && !outdoors(m.here.kind)) { const d = door(m.here); m.x = d.x; m.z = d.z; }
    });
    this.protest = protest;
    protestNews.on?.(w, town, b, size);
    return true;
  }

  private rearOffset(p: Protest): number { return Math.ceil(p.members.length / 4) * 0.16; }

  private advanceProtest(dt: number): void {
    const p = this.protest;
    if (!p) return;
    const total = p.lengths[p.lengths.length - 1];
    if (p.phase === 'gather') {
      p.timer -= dt;
      const ready = p.members.every((m) => { const s = this.slot(p, m.slot); return Math.hypot(s.x - m.x, s.z - m.z) < 0.1; });
      if (ready || p.timer <= 0) p.phase = 'march';
    } else if (p.phase === 'march') {
      p.s = Math.min(total, p.s + 0.2 * dt);
      if (p.s >= total) { p.phase = 'rally'; p.timer = 30; }
    } else {
      p.timer -= dt;
      if (p.timer <= 0) this.disperse(p);
    }
  }

  /** Where rank-and-file member k belongs: four abreast, each rank a step behind the one in front. */
  private slot(p: Protest, k: number): Pt & { fx: number; fz: number } {
    const row = Math.floor(k / 4), col = k % 4;
    const s = p.s - row * 0.16;
    const [pt, fx, fz] = along(p, s);
    const side = (col - 1.5) * 0.11;
    return { x: pt.x - fz * side, z: pt.z + fx * side, fx, fz };
  }

  private march(m: Person, dt: number): void {
    const p = this.protest;
    if (!p) { m.doing = 'inside'; m.timer = rand(5, 20); return; }
    const t = this.slot(p, m.slot);
    const dx = t.x - m.x, dz = t.z - m.z, d = Math.hypot(dx, dz);
    const pace = p.phase === 'gather' ? 0.7 : 0.45;
    const step = Math.min(d, pace * dt);
    if (d > 1e-4) { m.x += (dx / d) * step; m.z += (dz / d) * step; }
    m.phase += dt * (p.phase === 'rally' ? 5 : 8);
  }

  /** Everyone heads for the nearest door. */
  private disperse(p: Protest): void {
    const spots = this.places.get(p.town) ?? [];
    for (const m of p.members) {
      let best: Building | null = null, bestD = Infinity;
      for (const b of spots) {
        if (!INDOORS.has(b.kind)) continue;
        const d = Math.hypot(b.x + b.w / 2 - m.x, b.z + b.d / 2 - m.z);
        if (d < bestD) { bestD = d; best = b; }
      }
      if (best && bestD < 12) {
        m.goal = { b: best, door: door(best), activity: false };
        m.doing = 'queue';
        m.wantsPath = true;
      } else {
        m.doing = 'inside';
        m.timer = rand(10, 40);
      }
    }
    this.protest = null;
  }

  private drawSigns(): void {
    const p = this.protest;
    if (!p) { this.signs.count = 0; return; }
    this.signs.count = p.members.length;
    p.members.forEach((m, k) => {
      const s = this.slot(p, m.slot);
      const wave = p.phase === 'gather' ? 0 : Math.sin(this.time * 4 + k) * 0.015;
      this.q.setFromAxisAngle(this.up, Math.atan2(s.fx, s.fz));
      this.v.set(m.x, m.y + RADIUS * 0.6 + wave, m.z);
      this.m.compose(this.v, this.q, this.one);
      this.signs.setMatrixAt(k, this.m);
    });
    this.signs.instanceMatrix.needsUpdate = true;
  }
}

const clamp = (v: number) => Math.min(N - 0.001, Math.max(0, v));

/** A point s along a protest's route (before its start, straight back from it) and the direction there. */
function along(p: Protest, s: number): [Pt, number, number] {
  const pts = p.path, L = p.lengths;
  if (pts.length < 2) return [pts[0], 1, 0];
  let k = 1;
  while (k < pts.length - 1 && L[k] < s) k++;
  const a = pts[k - 1], b = pts[k], seg = L[k] - L[k - 1] || 1;
  const fx = (b.x - a.x) / seg, fz = (b.z - a.z) / seg;
  const t = s - L[k - 1];
  return [{ x: a.x + fx * t, z: a.z + fz * t }, fx, fz];
}

/** Just outside a building's front, a little way along the frontage. */
function door(b: Building): Pt {
  const [dx, dz] = DIRS[b.facing];
  const cx = b.x + b.w / 2, cz = b.z + b.d / 2;
  const alongFront = (Math.random() - 0.5) * 0.4;
  return {
    x: cx + dx * (b.w / 2 + 0.12) + (dz !== 0 ? alongFront : 0),
    z: cz + dz * (b.d / 2 + 0.12) + (dx !== 0 ? alongFront : 0),
  };
}

/** The road tile at a building's front door, or -1. */
function kerbTile(w: World, b: Building): number {
  const [dx, dz] = DIRS[b.facing];
  const x = Math.floor(b.x + b.w / 2 + dx * (b.w / 2 + 0.5)), z = Math.floor(b.z + b.d / 2 + dz * (b.d / 2 + 0.5));
  return inB(x, z) && w.road[idx(x, z)] ? idx(x, z) : -1;
}

/** Tiles of a walk along a town's streets from `start` to a random road tile between min and max steps away. */
function streetWalk(w: World, t: Town, start: number, min: number, max: number): number[] | null {
  const prev = new Map<number, number>([[start, -1]]);
  const dist = new Map<number, number>([[start, 0]]);
  const queue = [start];
  const far: number[] = [];
  for (let h = 0; h < queue.length; h++) {
    const i = queue[h], d = dist.get(i)!;
    if (d >= min) far.push(i);
    if (d >= max) continue;
    const x = i % N, z = (i - x) / N;
    for (const [dx, dz] of DIRS) {
      const nx = x + dx, nz = z + dz;
      if (nx < t.x0 || nz < t.z0 || nx >= t.x0 + t.size || nz >= t.z0 + t.size) continue;
      const j = idx(nx, nz);
      if (prev.has(j) || !w.road[j] || w.deckAxis[j]) continue;
      prev.set(j, i);
      dist.set(j, d + 1);
      queue.push(j);
    }
  }
  if (!far.length) return null;
  const tiles: number[] = [];
  for (let i = pick(far); i >= 0; i = prev.get(i)!) tiles.push(i);
  return tiles.reverse();
}

/** A random point inside an open lot (in a stadium, somewhere in the stands). */
function spotIn(b: Building): Pt {
  // on a lido's deck, not on its water
  if (b.kind === 'lido') return lidoDeckSpot(b);
  if (b.kind === 'stadium') {
    // a seat, whichever of the four it is (world/stadiums.ts)
    const p = stadiumPlanOf(b);
    for (let k = 0; k < 40; k++) {
      const x = (Math.random() - 0.5) * p.W, z = (Math.random() - 0.5) * p.D;
      if (p.seatY(x, z) !== null) return stadiumToIsland(b, x, z);
    }
  }
  return { x: b.x + rand(0.25, b.w - 0.25), z: b.z + rand(0.25, b.d - 0.25) };
}

/** A place in the line outside a door: a loose cluster along the front. */
function queueSpot(b: Building): Pt {
  const [dx, dz] = DIRS[b.facing];
  const d = door(b);
  const back = rand(0.05, 0.35), along = rand(-0.45, 0.45);
  return { x: d.x + dx * back + (dz !== 0 ? along : 0), z: d.z + dz * back + (dx !== 0 ? along : 0) };
}

/** Where to step into an open lot coming from `from`: its nearest edge. */
function edgeOf(b: Building, from: Pt): Pt {
  return {
    x: Math.min(b.x + b.w - 0.15, Math.max(b.x + 0.15, from.x)),
    z: Math.min(b.z + b.d - 0.15, Math.max(b.z + 0.15, from.z)),
  };
}

/** Height of a seat in the stadium stands under (p.x, p.z). */
function standY(p: Person, b: Building): number {
  const q = stadiumToLocal(b, p.x, p.z);
  return b.level * STEP + (stadiumPlanOf(b).seatY(q.x, q.z) ?? 0.15) + RADIUS;
}

/**
 * A short walk: A* over the tiles in a small box around both ends, avoiding buildings and deep
 * water, stepping up or down at most one height step, keeping off the road where it can.
 */
function footpath(w: World, sx: number, sz: number, tx: number, tz: number): Pt[] | null {
  const ax = Math.floor(sx), az = Math.floor(sz), bx = Math.floor(tx), bz = Math.floor(tz);
  const x0 = Math.max(0, Math.min(ax, bx) - 4), z0 = Math.max(0, Math.min(az, bz) - 4);
  const x1 = Math.min(N, Math.max(ax, bx) + 5), z1 = Math.min(N, Math.max(az, bz) + 5);
  const W = x1 - x0, H = z1 - z0;
  if (W * H > 1600 || !inB(ax, az) || !inB(bx, bz)) return null;
  const walkable = (x: number, z: number) => { const i = idx(x, z); return !w.blocked[i] && waterDepth(w, i) === 0; };
  const g = new Float32Array(W * H).fill(Infinity);
  const prev = new Int32Array(W * H).fill(-1);
  const closed = new Uint8Array(W * H);
  const li = (x: number, z: number) => (z - z0) * W + (x - x0);
  const start = li(ax, az), goal = li(bx, bz);
  g[start] = 0;
  const open: number[] = [start];
  while (open.length) {
    let bi = 0, bf = Infinity;
    for (let k = 0; k < open.length; k++) {
      const l = open[k], x = x0 + (l % W), z = z0 + Math.floor(l / W);
      const f = g[l] + Math.abs(x - bx) + Math.abs(z - bz);
      if (f < bf) { bf = f; bi = k; }
    }
    const cur = open.splice(bi, 1)[0];
    if (cur === goal) break;
    if (closed[cur]) continue;
    closed[cur] = 1;
    const cx = x0 + (cur % W), cz = z0 + Math.floor(cur / W);
    for (let d = 0; d < 4; d++) {
      const nx = cx + DIRS[d][0], nz = cz + DIRS[d][1];
      if (nx < x0 || nz < z0 || nx >= x1 || nz >= z1) continue;
      const ni = li(nx, nz);
      if (closed[ni] || (ni !== goal && !walkable(nx, nz))) continue;
      if (edgeMismatch(w, idx(cx, cz), d) > 1) continue;
      const ng = g[cur] + (w.road[idx(nx, nz)] ? 2.5 : 1);
      if (ng < g[ni]) { g[ni] = ng; prev[ni] = cur; open.push(ni); }
    }
  }
  if (!Number.isFinite(g[goal])) return null;
  const tiles: number[] = [];
  for (let l = goal; l >= 0; l = prev[l]) tiles.push(l);
  tiles.reverse();
  const pts: Pt[] = tiles.slice(1, -1).map((l) => {
    const x = x0 + (l % W), z = z0 + Math.floor(l / W), i = idx(x, z);
    let px = x + rand(0.3, 0.7), pz = z + rand(0.3, 0.7);
    // on a road tile, keep to the side next to the verge
    if (w.road[i]) {
      for (let d = 0; d < 4; d++) {
        const vx = x + DIRS[d][0], vz = z + DIRS[d][1];
        if (inB(vx, vz) && !w.road[idx(vx, vz)]) { px = x + 0.5 + DIRS[d][0] * 0.4; pz = z + 0.5 + DIRS[d][1] * 0.4; break; }
      }
    }
    return { x: px, z: pz };
  });
  pts.push({ x: tx, z: tz });
  return pts;
}

/** An angle turned from `a` toward `b` by at most `step`, the short way round. */
function turnToward(a: number, b: number, step: number): number {
  let d = b - a;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return a + Math.max(-step, Math.min(step, d));
}
