/**
 * What the story chains' missions are made of (docs/storychains.html). Each of the forty steps is a template
 * like any other, binding to real places or declining; these are the pieces they share:
 *
 * - a chain's places, found once and remembered (game/story.ts anchors), so the observatory of the first
 *   mission is the observatory of the sixteenth, and the pad the rocket is stacked on is the pad the fleet
 *   drives to at dawn;
 * - deliveries of the chains' own loads between those places, meetings there (at night, held, or with the
 *   fleet behind), races against the chains' rivals, tows, and tails;
 * - the gate every step goes through: its turn in its chain, a game day since the last, the other chain not
 *   waiting at a diamond, and the fleet the act asks for.
 */
import { N, idx, inB, type Building, type Town, type World } from '../../../world/tiles';
import type { Site } from '../../cargo';
import { cargoById, type CargoType } from '../../cargoTypes';
import { canReach } from '../../fit';
import { applyParts } from '../../parts';
import { reachAmong } from '../../race/route';
import { ALL_VEHICLES, isHelicopter, type LandDef } from '../../vehicles';
import { isNight } from '../../nightRules';
import { NEXT_WORLD } from '../../../world/nextWorld';
import { STORY_GAP, story, type Beat, type Chain } from '../../story';
import type { MissionCtx, Missions } from '../missions';
import type { Arc, Giver, HaulKind, HeroSpec, Kind, Obj, PlaceRef, Reward, TailAct, TailCar, TailEnd, Thread } from '../model';
import { rivalById, rivalModel, rivalParts } from '../rivals';
import { chain as tailChain, giverSpot, kerbOf, picker } from '../tailTemplates';
import { roadNear, siteRef, squareOf, towable, townRef, townsNear, type Draft, type Template } from '../templates';
import { shortSite } from '../text';

/** The acts every chain climbs through, four steps each. */
export const ACTS = ['Curiosity', 'Somebody Official', 'It Goes Public', 'It Answers', 'Gearing Up'];
/** A chain's steps. */
export const CHAIN_LEN = 20;

// ---- places -------------------------------------------------------------------------------------

/** A place a step goes to: a building (or a lighthouse on its headland), where a vehicle stands at it, and its town. */
export interface Spot { w: World; b: Building | null; town: Town | null; at: PlaceRef; kind: string; x: number; z: number }

type Pt = { x: number; z: number };

/** Why the last bind came back empty: 'far' when a chain's place is in a county not in memory (wait), 'none' when nothing fits. */
export let lastMiss: 'far' | 'none' | null = null;
const miss = (why: 'far' | 'none'): null => { lastMiss = why; return null; };
/** What the last bind tripped on, in words, for the story gate's report. */
export let lastWhy = '';
const trip = (why: string): null => { lastWhy = why; return null; };
/** A step that can't bind yet because its place is somewhere else (not in this county): wait, don't skip it. */
export const notHere = (): null => miss('far');

const lots = new WeakMap<World, Building[]>();
/** Every building of a county, the wonders' among them. */
function buildingsOf(w: World): Building[] {
  let l = lots.get(w);
  if (!l || l.length < w.allBuildings.length) {
    l = [...w.allBuildings, ...w.works.flatMap((g) => g.buildings)];
    lots.set(w, l);
  }
  return l;
}

const townAt = (w: World, x: number, z: number): Town | null => {
  const tx = Math.max(0, Math.min(N - 1, Math.floor(x))), tz = Math.max(0, Math.min(N - 1, Math.floor(z)));
  const id = w.townId[idx(tx, tz)];
  if (id >= 0) return w.towns.find((t) => t.id === id) ?? null;
  // out of town: the nearest within a short drive, for the card's header
  let best: Town | null = null, bd = 60;
  for (const t of w.towns) {
    const d = Math.hypot(t.x0 + t.size / 2 - x, t.z0 + t.size / 2 - z) - t.size / 2;
    if (d < bd) { bd = d; best = t; }
  }
  return best;
};

/** A tile a vehicle can stand on near (x, z), in w's tiles: a road first, then any drivable ground. */
function standNear(w: World, x: number, z: number, r = 10): Pt | null {
  const road = roadNear(w, x, z, Math.min(r, 9));
  if (road >= 0) return { x: (road % N) + 0.5, z: Math.floor(road / N) + 0.5 };
  let best: Pt | null = null, bd = Infinity;
  for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) {
    const tx = Math.floor(x) + dx, tz = Math.floor(z) + dz;
    if (!inB(tx, tz) || tx < 3 || tz < 3 || tx > N - 4 || tz > N - 4) continue;
    const i = idx(tx, tz);
    if (!w.edges[i] || w.blocked[i] || w.water[i] >= 0) continue;
    const d = Math.hypot(dx, dz);
    if (d < bd) { bd = d; best = { x: tx + 0.5, z: tz + 0.5 }; }
  }
  return best;
}

/** A building as a place to drive to. */
function spotOf(w: World, b: Building, name: string): Spot | null {
  const cx = b.x + b.w / 2, cz = b.z + b.d / 2;
  const p = standNear(w, cx, cz, Math.max(8, Math.ceil(Math.max(b.w, b.d) / 2) + 4));
  if (!p) return null;
  return { w, b, town: townAt(w, cx, cz), at: { x: w.ox + p.x, z: w.oz + p.z, cell: [w.cx, w.cz], name }, kind: b.kind, x: w.ox + cx, z: w.oz + cz };
}

/** A harbour (they are not buildings either) as a place to drive to: the quay by its pier. */
function portSpot(w: World, x: number, z: number, major: boolean, name: string): Spot | null {
  const p = standNear(w, x, z, 10);
  if (!p) return null;
  return { w, b: null, town: townAt(w, x, z), at: { x: w.ox + p.x, z: w.oz + p.z, cell: [w.cx, w.cz], name }, kind: major ? 'majorPort' : 'minorPort', x: w.ox + x, z: w.oz + z };
}

/** A lighthouse on its headland (they are points of interest, not buildings) as a place to drive to. */
function lightOf(w: World, x: number, z: number, name: string): Spot | null {
  const p = standNear(w, x + 0.5, z + 0.5, 12);
  if (!p) return null;
  return { w, b: null, town: townAt(w, x, z), at: { x: w.ox + p.x, z: w.oz + p.z, cell: [w.cx, w.cz], name }, kind: 'lighthouse', x: w.ox + x + 0.5, z: w.oz + z + 0.5 };
}

/**
 * The nearest of the first of `kinds` there is, within `max` tiles of `near`: kinds are tried in order, so
 * an observatory beats a research dome however close the dome is. Boarded-up buildings don't count.
 */
export function findSpot(c: MissionCtx, kinds: string[], near: Pt, max: number, name: (kind: string) => string, not: Spot[] = [], only?: World, keep?: (x: number, z: number) => boolean): Spot | null {
  // a place the vehicle driven can get to by road, when it is a road vehicle: not on another island of the county
  const reach = (s: Spot | null): Spot | null => {
    if (!s || c.def.kind !== 'land') return s;
    if (s.w === c.at.w) {
      const p = { w: s.w, lx: s.at.x - s.w.ox, lz: s.at.z - s.w.oz, x: s.at.x, z: s.at.z, port: -1 };
      return canReach(c.def, c.at, p) ? s : null;
    }
    // in another county: by road across the borders, not on an island over the water
    return roadFrom(c, c.at, s.at) ? s : null;
  };
  for (const kind of kinds) {
    let best: Spot | null = null, bd = max;
    for (const w of c.worlds) {
      if (only && w !== only) continue;
      if (kind === 'minorPort' || kind === 'majorPort') {
        for (const p of w.ports) {
          if (p.major !== (kind === 'majorPort')) continue;
          const d = Math.hypot(w.ox + p.x - near.x, w.oz + p.z - near.z);
          if (d >= bd || not.some((q) => Math.hypot(q.x - (w.ox + p.x), q.z - (w.oz + p.z)) < 4) || (keep && !keep(w.ox + p.x, w.oz + p.z))) continue;
          const s = reach(portSpot(w, p.x, p.z, p.major, name(kind)));
          if (s) { best = s; bd = d; }
        }
        continue;
      }
      if (kind === 'lighthouse') {
        for (const p of w.pois) {
          if (p.type !== 'lighthouse') continue;
          const d = Math.hypot(w.ox + p.x - near.x, w.oz + p.z - near.z);
          if (d >= bd || not.some((q) => Math.hypot(q.x - (w.ox + p.x), q.z - (w.oz + p.z)) < 4) || (keep && !keep(w.ox + p.x, w.oz + p.z))) continue;
          const s = reach(lightOf(w, p.x, p.z, name(kind)));
          if (s) { best = s; bd = d; }
        }
        continue;
      }
      for (const b of buildingsOf(w)) {
        if (b.kind !== kind || b.gone || b.derelict) continue;
        const x = w.ox + b.x + b.w / 2, z = w.oz + b.z + b.d / 2;
        const d = Math.hypot(x - near.x, z - near.z);
        if (d >= bd || not.some((q) => q.b === b) || (keep && !keep(x, z))) continue;
        const s = reach(spotOf(w, b, name(kind)));
        if (s) { best = s; bd = d; }
      }
    }
    if (best) return best;
  }
  return null;
}

/**
 * A chain's place by its key ("moon:obs"): the one it went to before, found again, or the nearest that
 * fits now, remembered for every later step. Null while the remembered place's county is out of memory.
 */
export function anchored(c: MissionCtx, key: string, kinds: string[], near: Pt | null, max: number, name: (kind: string) => string, o: { not?: Spot[]; root?: boolean } = {}): Spot | null {
  const a = story.anchor(key);
  if (a) {
    const w = c.worlds.find((q) => q.cx === a.cx && q.cz === a.cz);
    if (!w) return miss('far');
    if (a.kind === 'minorPort' || a.kind === 'majorPort') {
      const p = w.ports.find((q) => Math.abs(w.ox + q.x - a.x) < 2 && Math.abs(w.oz + q.z - a.z) < 2);
      const s = p ? portSpot(w, p.x, p.z, p.major, name(a.kind)) : null;
      if (s) return s;
    } else if (a.kind === 'lighthouse') {
      const p = w.pois.find((q) => q.type === 'lighthouse' && Math.abs(w.ox + q.x - a.x) < 2 && Math.abs(w.oz + q.z - a.z) < 2);
      const s = p ? lightOf(w, p.x, p.z, name(a.kind)) : null;
      if (s) return s;
    } else {
      const b = buildingsOf(w).find((q) => q.x === a.bx && q.z === a.bz && q.kind === a.kind && !q.gone);
      const s = b ? spotOf(w, b, name(a.kind)) : null;
      if (s) return s;
    }
    // gone (bulldozed, or the world changed): find another
  }
  const s = findSpot(c, kinds, near ?? c.at, max, name, o.not ?? []);
  // a chain's own stage (its harbour, its observatory) not in reach yet: it waits for the player to go somewhere with one
  if (!s) return miss(o.root ? 'far' : 'none');
  story.bind(key, { x: s.x, z: s.z, kind: s.kind, cx: s.w.cx, cz: s.w.cz, bx: s.b ? s.b.x : -1, bz: s.b ? s.b.z : -1 });
  return s;
}

/** Can a road car get from a to b, across counties (the flood the races use)? Kept per pair while it binds. */
const reachMemo = new Map<string, boolean>();
export function roadFrom(c: MissionCtx, a: { x: number; z: number }, b: { x: number; z: number }, def: LandDef = TOMATO_DEF): boolean {
  const k = `${Math.floor(a.x)},${Math.floor(a.z)}>${Math.floor(b.x)},${Math.floor(b.z)}|${def.id}`;
  let v = reachMemo.get(k);
  if (v === undefined) {
    if (reachMemo.size > 4000) reachMemo.clear();
    const worldAt = (cx: number, cz: number) => c.worlds.find((w) => w.cx === cx && w.cz === cz) ?? null;
    v = reachAmong(worldAt, def, a.x, a.z, [b])[0];
    reachMemo.set(k, v);
  }
  return v;
}
const TOMATO_DEF = ALL_VEHICLES.find((v) => v.id === 'tomato') as LandDef;

/** A plain label for a kind of place, lower case: "the observatory". */
export const the = (kind: string): string => `the ${shortSite(kind).toLowerCase()}`;

// ---- deliveries --------------------------------------------------------------------------------

/** The cargo site at a place, if its building trades (every place the chains bind does). */
export function siteAt(c: MissionCtx, s: Spot): Site | null {
  let best: Site | null = null, bd = 9;
  // an airfield's buildings trade at the stand on its apron
  const kinds = s.kind === 'controlTower' || s.kind === 'hangar' ? ['airport'] : [s.kind];
  if (kinds[0] === 'airport') bd = 40;
  for (const q of c.sites(kinds)) {
    // the building's own site, wherever round its lot the gate is (a wonder's 14-tile lot puts it well out)
    if (s.b && q.b === s.b) return q;
    const d = Math.hypot(q.x - s.x, q.z - s.z);
    if (d < bd) { bd = d; best = q; }
  }
  return best ?? trip(`no ${s.kind} site at ${Math.round(s.x)},${Math.round(s.z)}`);
}

/** The nearest site of the first of these kinds there is, `lo`–`hi` tiles from `near`, that the vehicle driven can reach. */
export function siteNear(c: MissionCtx, kinds: string[], near: Pt, lo: number, hi: number, not: (Site | null)[] = []): Site | null {
  for (const kind of kinds) {
    let best: Site | null = null, bd = hi;
    for (const q of c.sites([kind])) {
      if (q.b?.derelict || not.includes(q) || q.waterOnly) continue;
      const d = Math.hypot(q.x - near.x, q.z - near.z);
      if (d < lo || d >= bd) continue;
      if (c.def.kind === 'land' && !canReach(c.def, c.at, q)) continue;
      best = q; bd = d;
    }
    if (best) return best;
  }
  return trip(`nothing reachable of ${kinds.slice(0, 3).join('/')} ${lo}–${hi} from ${Math.round(near.x)},${Math.round(near.z)}`);
}

/** A delivery of one of the chain's own loads from one site to another: "🔭 Telescope Lens → Observatory". */
export function carry(cargo: string, from: Site, to: Site, n = 1, toName?: string): Extract<Obj, { t: 'deliver' }> | null {
  const type: CargoType | undefined = cargoById(cargo);
  if (!type || from === to) return null;
  if (c0 && c0.def.kind === 'land' && (!canReach(c0.def, c0.at, from) || !canReach(c0.def, c0.at, to))) return trip(`${cargo}: no road to ${!canReach(c0.def, c0.at, from) ? from.kind : to.kind}`);
  // a shed on a quay is named for what it is, not for the harbour it trades through ("Cannery", not "Dock")
  const tref = { ...siteRef(to), ...(toName ? { name: toName } : to.quay ? { name: shortSite(String(to.kind)) } : {}) };
  const dist = Math.hypot(to.x - from.x, to.z - from.z);
  let label = `${n > 1 ? `${n}× ` : ''}${type.name} → ${tref.name}`;
  if (label.length > 28) label = `${type.name} → ${tref.name.split(' ')[0]}`;
  if (label.length > 28) label = `Deliver ${type.name.toLowerCase()}`.slice(0, 28);
  return { t: 'deliver', label, icon: type.icon, cargo: type.id, from: siteRef(from), to: tref, n, value: Math.round((40 + dist * 0.9) / 5) * 5 };
}
/** The context the last bind ran in, for `carry`'s reach test. */
let c0: MissionCtx | null = null;

// ---- meetings, races, tows, tails ----------------------------------------------------------------

/** Drive to a place: `night` between 21:00 and 04:00, `midnight` 23:00 to 01:00, `dawn` 04:00 to 08:00. */
export function meet(s: Spot, label: string, icon: string, o: { when?: 'night' | 'midnight' | 'dawn'; hold?: number; with?: number; hidden?: number; r?: number } = {}): Obj {
  const hours = o.when === 'night' ? [21, 4] : o.when === 'midnight' ? [23, 1] : o.when === 'dawn' ? [4, 8] : null;
  return {
    t: 'reach', label, icon, at: s.at, r: o.r ?? 5, stop: !!o.hold || undefined,
    ...(hours ? { after: hours[0], before: hours[1] } : {}),
    ...(o.hold ? { hold: o.hold } : {}), ...(o.with ? { with: o.with } : {}), ...(o.hidden ? { hidden: o.hidden } : {}),
  };
}

/**
 * A race against a chain's rival from `from` to `to`: only when the rival's car can get there, and only
 * a road car takes it. The start is the square of the town nearest `from`.
 */
export function race(c: MissionCtx, rival: string, tier: 1 | 2 | 3, from: Spot, to: Spot, label: string): Obj[] | null {
  if (c.def.kind !== 'land') return trip('race: not in a road vehicle');
  const r = rivalById(rival);
  const def = applyParts(ALL_VEHICLES.find((v) => v.id === rivalModel(r, tier))!, rivalParts(r, tier)) as LandDef;
  // the start: the square of the town by `from`, else of another town the rival can race from and the player can get to
  const firstStart = from.town ? squareOf(from.w, from.town, 'the start line') : { ...from.at, name: 'the start line' };
  const starts = [firstStart, ...townsNear(c, 320).map(({ w, t }) => squareOf(w, t, 'the start line'))];
  let start: typeof firstStart | null = null, why = '';
  for (const s of starts.slice(0, 10)) {
    const far = Math.hypot(to.at.x - s.x, to.at.z - s.z);
    if (far < 60 || far > 420) { why = `race: ${Math.round(far)} tiles`; continue; }
    if (!roadFrom(c, s, to.at, def)) { why = `race: the rival can't get to ${to.at.name}`; continue; }
    if (!roadFrom(c, c.at, s)) { why = 'race: no road to the start'; continue; }
    start = s;
    break;
  }
  if (!start) return trip(why || 'race: no start');
  return [
    { t: 'reach', label: `Meet ${r.short} at the start`.length <= 28 ? `Meet ${r.short} at the start` : 'Meet at the start line', icon: '🏁', at: start, r: 5 },
    { t: 'race', label, icon: '🏎️', rival, tier, from: start, to: { ...to.at } },
  ];
}

/**
 * A tow to a place: the load set down on a road `lo`–`hi` tiles off, somewhere a lorry could drag it
 * from without a bridge or a ford, and `min` vehicles on the ropes. In the place's own county.
 */
export function tow(c: MissionCtx, to: Spot, load: HaulKind, min: number, h: number, label: string, lo = 18, hi = 80): Obj[] | null {
  const w = to.w;
  const near = roadNear(w, to.at.x - w.ox, to.at.z - w.oz, 12);
  const goal = near >= 0 ? near : idx(Math.floor(to.at.x - w.ox), Math.floor(to.at.z - w.oz));
  if (goal < 0 || !w.edges[goal]) return trip(`no road at the tow's drop`);
  // flood out from the drop: every tile the load could be dragged in from, and how far by the drag
  const reach = towable(w, goal, 14000);
  const gx = goal % N, gz = Math.floor(goal / N);
  const cands: number[] = [];
  for (const [i, walked] of reach) {
    if (!w.road[i]) continue;
    const x = i % N, z = Math.floor(i / N), straight = Math.hypot(x - gx, z - gz);
    if (straight < lo || straight > hi || walked > straight * 2.6) continue;
    cands.push(i);
  }
  if (!cands.length) return trip(`nowhere ${lo}–${hi} tiles off to drag a ${load} from`);
  const a = cands[h % cands.length];
  const from: PlaceRef = { x: w.ox + (a % N) + 0.5, z: w.oz + Math.floor(a / N) + 0.5, cell: [w.cx, w.cz], name: 'the load' };
  const drop: PlaceRef = { x: w.ox + gx + 0.5, z: w.oz + gz + 0.5, cell: [w.cx, w.cz], name: to.at.name.replace(/^the /, '') };
  return [
    { t: 'crew', label: `Bring ${min} vehicles`, icon: '🚚', n: min },
    { t: 'tow', label, icon: '⛓️', load, from, to: drop, min, need: 0 },
  ];
}

/**
 * A tail: `car` waits at the kerb of `from`, drives `acts` by road and ends at `to`, all in one county.
 * Returns the giver's spot across the street with it.
 */
export function tail(c: MissionCtx, from: Spot, to: Spot, car: TailCar, acts: TailAct[], end: TailEnd, label: string, h: number): { obj: Obj; giver: PlaceRef } | null {
  if (c.def.kind !== 'land' || !from.b || from.w !== to.w) return trip('tail: not one county');
  const w = from.w, pick = picker(h);
  const a = kerbOf(w, from.b) ?? { x: from.at.x - w.ox, z: from.at.z - w.oz };
  const b = (to.b ? kerbOf(w, to.b) : null) ?? { x: to.at.x - w.ox, z: to.at.z - w.oz };
  let legs: ReturnType<typeof tailChain> = null;
  for (let k = 0; k < 4 && !legs; k++) legs = tailChain(w, a, b, k < 2 ? acts : acts.slice(0, 2), pick, 40, 560);
  if (!legs) return trip('tail: no road run between them');
  const g = giverSpot(w, a, pick, legs[0] ?? b);
  if (!g) return trip('tail: nowhere for the giver to wait');
  return {
    obj: { t: 'tail', label, icon: '🕵️', at: { x: w.ox + a.x, z: w.oz + a.z, cell: [w.cx, w.cz], name: from.at.name }, to: { x: w.ox + b.x, z: w.oz + b.z, cell: [w.cx, w.cz], name: to.at.name }, legs, car, end },
    giver: { x: w.ox + g.x, z: w.oz + g.z, cell: [w.cx, w.cz], name: 'across the street' },
  };
}

// ---- the gate, and the template -----------------------------------------------------------------

/** What each act asks of the fleet before its steps are offered. */
function actWhy(c: MissionCtx, i: number): string | null {
  const act = Math.floor(i / 4);
  const crewed = c.units.filter((u) => u.crew && u.land).length;
  // neither chain begins before the fleet is a real one (the user, 7 Oct 2026): an HQ of two slots or more,
  // and two drivers hired and out at the wheel
  if (i === 0 && ((c.hqSlots ?? 0) < 2 || c.units.filter((u) => u.crew).length < 2)) return 'a 2-slot HQ and 2 drivers out first';
  if (act >= 1 && (c.hqSlots ?? 0) < 1) return 'an HQ first';
  if (act >= 2 && c.units.length < 2) return 'two vehicles first';
  if (act === 3 && c.units.length < 3 && crewed < 1) return 'a bigger fleet first';
  if (act >= 4 && c.units.length < 3) return 'three vehicles first';
  return null;
}

/** Closer than this (tiles) to where the offer is taken, a mission's opening meeting is no trip at all. */
export const MEET_MIN = 70;
/** And no further than this from the meeting: the offer is still somewhere on the way. */
const MEET_MAX = 280;
/** Where word of a meeting can be left for the player: anywhere public. */
const MESSAGE_KINDS = ['pub', 'tavern', 'cafe', 'diner', 'postOffice', 'hotel', 'library', 'busStation', 'cityHall'];

/**
 * Somewhere else to take an offer whose first step is a meeting, when the giver stands at the meeting place
 * itself: the nearest public building to the player that is between MEET_MIN and MEET_MAX tiles from the
 * meeting, so taking the offer and keeping the appointment are two places, with a drive between (the user,
 * 18 Oct 2026: "you accept the mission really really close to where you have to go meet the person").
 * Null when there is nowhere like that.
 */
export function messageSpot(c: MissionCtx, meetAt: Pt): Spot | null {
  // judged on the building first (with room for where its stopping place stands off it), then on that place
  const apart = (x: number, z: number) => { const d = Math.hypot(x - meetAt.x, z - meetAt.z); return d >= MEET_MIN + 10 && d <= MEET_MAX; };
  let best: Spot | null = null, bd = Infinity;
  for (const kind of MESSAGE_KINDS) {
    const s = findSpot(c, [kind], c.at, Math.min(bd, MEET_MAX + 200), the, [], undefined, apart);
    if (!s || Math.hypot(s.at.x - meetAt.x, s.at.z - meetAt.z) < MEET_MIN) continue;
    const d = Math.hypot(s.x - c.at.x, s.z - c.at.z);
    if (d < bd) { best = s; bd = d; }
  }
  return best;
}

/** A giver at a place. */
export const giver = (who: string, name: string, s: Spot): Giver => ({ who, name, at: s.at, town: s.town ? townRef(s.w, s.town) : null });

/** A building's hero: itself, drawn in its town's style. */
export function heroOf(s: Spot | null, fallback: HeroSpec): HeroSpec {
  if (!s?.b) return fallback;
  return { kind: 'building', b: s.b.kind, arch: s.b.style ?? s.town?.style ?? 'classic', w: s.b.w, d: s.b.d, floors: s.b.floors };
}

/** One step of a chain. */
export interface Step {
  /** Its place in the chain, 0 to 19. */
  i: number;
  kind: Kind;
  /** Only a road vehicle can do it (deliveries inland, races, tows, tails). Every step but a meeting. */
  road?: boolean;
  /** Anything else it needs before it is offered (crew for a tow, say). */
  needs?: (c: MissionCtx) => string | null;
  bind(c: MissionCtx, h: number): Draft | null;
  /** The journal's "so far" line once it is done. */
  so: string;
  beat?: Beat;
  /**
   * The step's other forms (0.7.0): in a helicopter (any time, or only after dark when it is a night op) or in a
   * boat. It binds in one only when that is what the player is driving at bind time (user rule, 5 Oct 2026);
   * otherwise in its road form.
   */
  forms?: StepForms;
}

/** `sub`: a submarine's form, under the waves (docs/underwater.html); it wins over `boat` in a submarine. */
interface StepForms { heli?: 'any' | 'night'; boat?: boolean; sub?: boolean }

/** The form a step binds in for what the player is driving now: 'heli', 'sub', 'boat', or null for its road form. */
export function formIn(c: MissionCtx, f: StepForms | undefined): 'heli' | 'boat' | 'sub' | null {
  if (!NEXT_WORLD || !f) return null;
  if (f.heli && isHelicopter(c.def) && (f.heli === 'any' || isNight(((c.hours % 24) + 24) % 24))) return 'heli';
  if (f.sub && c.def.kind === 'water' && c.def.dive) return 'sub';
  if (f.boat && c.def.kind === 'water') return 'boat';
  return null;
}

/** The arc a chain is, for ARCS. */
export const arcOf = (chain: Chain, title: string, thread: Thread, who: string): Arc => ({
  id: chain, title, thread, who, tpls: Array.from({ length: CHAIN_LEN }, (_, i) => tplId(chain, i)), acts: ACTS,
});
export const tplId = (chain: Chain, i: number): string => `${chain}:${String(i + 1).padStart(2, '0')}`;

/** Every step's journal line and news, by template id, for the mission system to hand to the story when one ends. */
export const STEP_INFO = new Map<string, { chain: Chain; i: number; so: string; beat?: Beat }>();

/** A chain's step as a template. */
export function stepTemplate(chain: Chain, thread: Thread, also: Thread | undefined, s: Step): Template {
  const id = tplId(chain, s.i);
  STEP_INFO.set(id, { chain, i: s.i, so: s.so, beat: s.beat });
  const other: Chain = chain === 'moon' ? 'deep' : 'moon';
  return {
    id, thread, also, kind: s.kind, arc: chain,
    gate(c: MissionCtx, ms: Missions) {
      if ((ms.arcs?.get(chain) ?? 0) !== s.i) return 'not its turn';
      if (c.hours - story.ended[chain] < STORY_GAP) return 'a day between steps';
      // the two stories take turns: not within a day of the other posting a step
      if ((ms.offered ?? []).some((m) => m.arc?.id === other && c.hours - m.posted < STORY_GAP)) return 'the other story first';
      if (s.road && c.def.kind !== 'land' && !formIn(c, s.forms)) return 'a road vehicle';
      return actWhy(c, s.i) ?? s.needs?.(c) ?? null;
    },
    bind(c: MissionCtx, h: number) {
      lastMiss = null;
      lastWhy = '';
      c0 = c;
      try { return s.bind(c, h); } finally { c0 = null; }
    },
  };
}

/** Round to ten. */
export const r10 = (v: number): number => Math.round(v / 10) * 10;
/** Cash. */
export const cash = (n: number): Reward => ({ r: 'cash', n });
/** Standing with a place's town, if it has one. */
export const talk = (s: Spot | null, n = 1): Reward[] => (s?.town ? [{ r: 'standing', town: townRef(s.w, s.town), n }] : []);

/**
 * A tow with nowhere to drag from (the place's ground is all water and steep hill): the load comes by road
 * instead, on the back of the fleet, from a works or a harbour a short way off.
 */
export function heavyRun(c: MissionCtx, to: Spot, cargo: string, kinds: string[], n = 1): Obj | null {
  const dest = siteAt(c, to);
  const from = dest && siteNear(c, kinds, to, 15, 320, [dest]);
  return dest && from ? carry(cargo, from, dest, n) : null;
}
