/**
 * Transmission lines (world/powerLines.ts, 0.8.0): lattice pylons and the wires slung between them, drawn into the
 * town chunks' kit (render/townMesh.ts). A pylon belongs to the chunk its foot is in; each span of wire to whichever
 * chunk holds its middle, so nothing is drawn twice where chunks meet. A span that runs over the seam into the next
 * county is drawn half from each side, both halves meeting at the same point over the seam.
 */
import type { Kit } from './buildings/kit';
import { CHUNK, type World } from '../world/tiles';
import { hex } from '../world/biomes';
import { PYLON_H, type Pylon } from '../world/powerLines';

type P3 = [number, number, number];
const STEEL = hex(0x9aa1a6), WIRE = hex(0x3a3d40);
/** The wires' attachments on a pylon: [across, down from the top], four conductors and the earth wire over them. */
const WIRES: [number, number][] = [[-0.68, 0.62], [0.68, 0.62], [-0.48, 0.26], [0.48, 0.26], [0, -0.02]];
/** How far a wire sags at mid-span, a tile of span at a time. */
const SAG = 0.045;

/** The unit vector across the line at pylon k (the mean of the ways in and out). */
function acrossAt(ps: Pylon[], k: number): [number, number] {
  const p = ps[k], a = ps[Math.max(0, k - 1)], b = ps[Math.min(ps.length - 1, k + 1)];
  let dx = b.x - a.x, dz = b.z - a.z;
  if (!dx && !dz) { dx = 1; dz = 0; }
  const l = Math.hypot(dx, dz);
  void p;
  // one way round for every line (+x, or +z square to x), so the two counties either side of a seam agree on it
  let ux = -dz / l, uz = dx / l;
  if (ux < -1e-6 || (Math.abs(ux) <= 1e-6 && uz < 0)) { ux = -ux; uz = -uz; }
  return [ux, uz];
}

function drawPylon(k: Kit, p: Pylon, ux: number, uz: number): void {
  const x = p.x + 0.5, z = p.z + 0.5, y0 = p.foot - 0.05, H = PYLON_H;
  // the along-line axis
  const vx = -uz, vz = ux;
  const at = (a: number, b: number, h: number, w: number): P3 => [x + (ux * a + vx * b) * w, y0 + h, z + (uz * a + vz * b) * w];
  // the four legs, tapering from a wide foot to the waist and on to the peak
  const width = (h: number) => (h < H * 0.7 ? 0.32 - (0.22 * h) / (H * 0.7) : 0.1 - (0.05 * (h - H * 0.7)) / (H * 0.3));
  const corners: [number, number][] = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
  const levels = [0, H * 0.3, H * 0.55, H * 0.7, H];
  for (let s = 0; s + 1 < levels.length; s++) {
    const ha = levels[s], hb = levels[s + 1];
    for (let c = 0; c < 4; c++) {
      const [a, b] = corners[c], [a2, b2] = corners[(c + 1) % 4];
      k.bar(at(a, b, ha, width(ha)), at(a, b, hb, width(hb)), 0.035, STEEL);
      // a brace across each face, zig-zagging up
      if (s < 3) k.bar(at(a, b, ha, width(ha)), at(a2, b2, hb, width(hb)), 0.018, STEEL);
    }
  }
  // the cross arms the conductors hang from, and the earth peak
  for (const [arm, down] of [[0.7, 0.62], [0.5, 0.26]] as [number, number][]) {
    k.bar(at(-arm, 0, H - down, 1), at(arm, 0, H - down, 1), 0.04, STEEL);
    k.bar(at(-arm, 0, H - down, 1), at(0, 0, H - down - 0.25, 1), 0.02, STEEL);
    k.bar(at(arm, 0, H - down, 1), at(0, 0, H - down - 0.25, 1), 0.02, STEEL);
  }
}

/** A sagging wire from a to b, in a few straight pieces. */
function wire(k: Kit, a: P3, b: P3, len: number): void {
  const n = 4, sag = SAG * len;
  let prev = a;
  for (let i = 1; i <= n; i++) {
    const t = i / n;
    const p: P3 = [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t - 4 * sag * t * (1 - t), a[2] + (b[2] - a[2]) * t];
    k.bar(prev, p, 0.016, WIRE);
    prev = p;
  }
}

export function drawPowerLines(k: Kit, w: World, x0: number, z0: number): void {
  const x1 = x0 + CHUNK, z1 = z0 + CHUNK;
  const mine = (x: number, z: number) => x >= x0 && x < x1 && z >= z0 && z < z1;
  k.place(0, 0, 0, 0);
  for (const line of w.powerLines) {
    const ps = line.pylons;
    const across = ps.map((_, i) => acrossAt(ps, i));
    // the attachment point of wire j on pylon i
    const attach = (i: number, j: number): P3 => {
      const p = ps[i], [ux, uz] = across[i], [a, d] = WIRES[j];
      return [p.x + 0.5 + ux * a, p.foot - 0.05 + PYLON_H - d, p.z + 0.5 + uz * a];
    };
    for (let i = 0; i < ps.length; i++) {
      if (mine(ps[i].x + 0.5, ps[i].z + 0.5)) drawPylon(k, ps[i], across[i][0], across[i][1]);
      if (i + 1 < ps.length) {
        const mx = (ps[i].x + ps[i + 1].x) / 2 + 0.5, mz = (ps[i].z + ps[i + 1].z) / 2 + 0.5;
        if (!mine(mx, mz)) continue;
        const len = Math.hypot(ps[i + 1].x - ps[i].x, ps[i + 1].z - ps[i].z);
        for (let j = 0; j < WIRES.length; j++) wire(k, attach(i, j), attach(i + 1, j), len);
      }
    }
    // the half span out to the seam: both counties hang the wires at the seam from the same points, spread along it
    const seam = line.seamA;
    if (seam) {
      const p = ps[0];
      const mx = (p.x + 0.5 + seam.x) / 2, mz = (p.z + 0.5 + seam.z) / 2;
      if (mine(mx, mz)) {
        const alongSeamX = seam.z === 0 || seam.z >= 256 - 0.01;
        // (a fixed sag at the seam, the same from either side however far each county's last pylon stands from it)
        const dip = SAG * 7;
        for (let j = 0; j < WIRES.length; j++) {
          const [a, d] = WIRES[j];
          const s: P3 = alongSeamX ? [seam.x + a, seam.y + 0.25 - d - dip, seam.z] : [seam.x, seam.y + 0.25 - d - dip, seam.z + a];
          // the half span's sag: the low point of the whole span is over the seam
          const a3 = attach(0, j);
          const n = 3;
          let prev = a3;
          for (let q = 1; q <= n; q++) {
            const t = q / n;
            const pt: P3 = [a3[0] + (s[0] - a3[0]) * t, a3[1] + (s[1] - a3[1]) * (1 - (1 - t) * (1 - t)), a3[2] + (s[2] - a3[2]) * t];
            k.bar(prev, pt, 0.016, WIRE);
            prev = pt;
          }
        }
      }
    }
  }
}
