import { N, STEP, Biome, Feature, Flag, RoadType, World, idx, inB, waterDepth, type Building, type BuildingKind } from './tiles';
import type { FieldInfo } from './biomes';
import { cellNoise, hash2, type Rng } from './rng';
import { cellKind, coastalContinent } from './macro';
import type { TownPlan } from './towns';
import { buildingHeight } from './towns';
import { solidMask } from './footprint';
import { KIND_SPEC } from './townKinds';
import { layGenerated } from './roads';
import { BELT_ID0 } from './crops';
import type { WorkSite } from './industry';

/**
 * Farm belts (0.8.0, NEXT_080, docs/phonelist.html item 12): the corn and wheat country of Iowa, fields after fields
 * to the horizon. In a belt county the open plains are cut into the section grid: a square section every SECTION
 * tiles both ways, lined up across the whole world (a county is a whole number of sections), each section cut into
 * one, two or four rectangular fields of one crop, a grass strip between them, and a gravel road along every other
 * section line. A farmstead (house, barn, silo) stands in the corner of about one section in three, its yard taken
 * out of the field, a lane from its gate to the section road.
 *
 * Belts come in runs of counties (a smooth noise over the county grid), inland on the continent, on temperate plains,
 * never a biome's county or a megalopolis's. Rolled from the seed and the county alone, and every draw is on a
 * stream of its own, so a county that is not a belt is exactly what it was.
 */

/** Tiles on a side of a section; 256 / 16 = 16 sections a county, so the grid runs on unbroken across the seams. */
export const SECTION = 16;
/** A gravel road runs along every ROAD_EVERY-th section line. */
const ROAD_EVERY = 2;
/** The county noise above which a county is belt, if the ground lets it: about a third of the eligible ones. */
const BELT_NOISE = 0.55;
/** The noise's scale in counties: belts run three or four counties across. */
const BELT_SCALE = 3.2;
export const BELT_SALT = 0xbe17;
/** Share of the county's land that must be open plain or gentle hills for a belt. */
const MIN_PLAIN = 0.3;
/** The farmland's temperature (w.temp, 0..1): temperate, not desert-hot or tundra. */
const TEMP_LO = 0.35, TEMP_HI = 0.97;
/** Tiles kept clear round a planned town's square. */
const TOWN_CLEAR = 6;
/** Tiles of woods left standing either side of a river or a stream. */
const CREEK_WOOD = 3;
/** Fields keep this many tiles off the county's edge; section roads and farmsteads ROAD_EDGE. */
const EDGE = 1, ROAD_EDGE = 6;

/** Why counties and tiles missed out, counted for the gate (scripts/farmbelts.ts). */
export const BELT_WHY = new Map<string, number>();
const why = (k: string) => BELT_WHY.set(k, (BELT_WHY.get(k) ?? 0) + 1);

/** Does this county look for a belt at all (before its ground is checked)? */
export function beltRoll(seedHash: number, cx: number, cz: number): boolean {
  return cellNoise(seedHash, cx, cz, BELT_SCALE, BELT_SALT) > BELT_NOISE;
}

/** Is the county one that would be belt country, as far as the map alone says (inland continent, the roll up)? */
export function beltCounty(seedHash: number, cx: number, cz: number): boolean {
  return cellKind(seedHash, cx, cz) === 'continent' && !coastalContinent(seedHash, cx, cz) && beltRoll(seedHash, cx, cz);
}

/** Tiles in from an edge with no belt beyond it over which the sections thin out, so a belt has no ruled edge. */
const FEATHER = 72;

/** What a belt laid: its fields (ids from BELT_ID0), and the section corners kept for farmsteads. */
export interface Belt { fields: FieldInfo[]; steads: { x: number; z: number }[] }

/**
 * Cut the county's open plains into sections and fields. Called with the other fields (generate.ts, after
 * reshapeFields), so the railway, the towns and the roads all see the farmland. Null where the county is not belt
 * country after all (too little flat plain, the wrong climate).
 */
export function growBelt(w: World, seedHash: number, E: Float32Array, river: Uint8Array, plans: TownPlan[], works: readonly WorkSite[], band: number, r: Rng): Belt | null {
  const NN = N * N;
  const arable = (b: number) => b === Biome.Plains || b === Biome.Hills;
  // in belt country the woods were cleared for the plough long ago, all but the strips along the creeks
  const creek = new Uint8Array(NN);
  for (let i = 0; i < NN; i++) {
    if (!river[i] && !(w.flags[i] & (Flag.River | Flag.Stream))) continue;
    const x = i % N, z = (i - x) / N;
    for (let dz = -CREEK_WOOD; dz <= CREEK_WOOD; dz++) for (let dx = -CREEK_WOOD; dx <= CREEK_WOOD; dx++) if (inB(x + dx, z + dz)) creek[idx(x + dx, z + dz)] = 1;
  }
  const ploughed = (t: number) => arable(w.biome[t]) || (w.biome[t] === Biome.Forest && !creek[t]);
  let plain = 0, land = 0, temp = 0;
  for (let i = 0; i < NN; i += 3) {
    if (w.biome[i] === Biome.Ocean) continue;
    land++;
    if (ploughed(i)) { plain++; temp += w.temp[i]; }
  }
  if (!land || plain / land < MIN_PLAIN) { why(`county: plain ${(plain / Math.max(1, land)).toFixed(2)}`); return null; }
  temp /= plain;
  if (temp < TEMP_LO || temp > TEMP_HI) { why(`county: temp ${temp.toFixed(2)}`); return null; }

  const nearTown = new Uint8Array(NN);
  for (const p of plans) {
    for (let z = p.z0 - TOWN_CLEAR; z < p.z0 + p.size + TOWN_CLEAR; z++) {
      for (let x = p.x0 - TOWN_CLEAR; x < p.x0 + p.size + TOWN_CLEAR; x++) if (inB(x, z)) nearTown[idx(x, z)] = 1;
    }
  }
  // and the works: an airfield's runway and hangars, a quarry, a wonder, a circuit, with room round them
  for (const g of works) {
    const R = Math.max(g.len, g.half) + 4;
    for (let z = g.z - R; z <= g.z + R; z++) for (let x = g.x - R; x <= g.x + R; x++) if (inB(x, z)) nearTown[idx(x, z)] = 1;
    if (g.lot) for (let z = g.lot.z - 2; z < g.lot.z + g.lot.d + 2; z++) for (let x = g.lot.x - 2; x < g.lot.x + g.lot.w + 2; x++) if (inB(x, z)) nearTown[idx(x, z)] = 1;
  }
  // a belt field only colours the ground and changes nothing of its height, so unlike an ordinary field (levelled,
  // and so kept out of the seam band) it runs on to within EDGE tiles of the county's edge, and the sections carry on
  // across the seam into the next belt county
  void band;
  const lo = EDGE, hi = N - EDGE;
  const free = (t: number) => {
    const x = t % N, z = (t - x) / N;
    if (x < lo || z < lo || x >= hi || z >= hi) return false;
    if (!ploughed(t)) { why(`tile: biome ${w.biome[t]}`); return false; }
    if (w.feature[t] !== Feature.None) { why(`tile: feature ${w.feature[t]}`); return false; }
    if (w.flags[t] & (Flag.Poi | Flag.Field)) { why('tile: poi/field'); return false; }
    if (river[t] || w.water[t] >= 0) { why('tile: water'); return false; }
    if (nearTown[t]) { why('tile: town'); return false; }
    return true;
  };

  // the edges with no belt beyond them: west, east, north, south
  const open = [[-1, 0], [1, 0], [0, -1], [0, 1]].map(([dx, dz]) => !beltCounty(seedHash, w.cx + dx, w.cz + dz));
  /** How far in from the nearest open edge a tile is (Infinity with none). */
  const inFrom = (x: number, z: number) => Math.min(open[0] ? x : Infinity, open[1] ? N - 1 - x : Infinity, open[2] ? z : Infinity, open[3] ? N - 1 - z : Infinity);
  const belt: Belt = { fields: [], steads: [] };
  let id = BELT_ID0;
  // the field: what of the rectangle is free and near the level of its middle, if enough of it is
  const field = (x0: number, z0: number, wx: number, wz: number): void => {
    if (wx < 3 || wz < 3) return;
    const mid = idx(x0 + (wx >> 1), z0 + (wz >> 1));
    const ref = E[mid];
    const tiles: number[] = [];
    for (let z = z0; z < z0 + wz; z++) for (let x = x0; x < x0 + wx; x++) {
      if (!inB(x, z)) continue;
      const t = idx(x, z);
      if (!free(t)) continue;
      if (Math.abs(E[t] - ref) <= 1.6) tiles.push(t); else why('tile: height');
    }
    if (tiles.length < Math.max(12, wx * wz * 0.6)) { why('field: too little'); return; }
    why('field: made');
    const was = tiles.map((t) => w.biome[t]);
    let sum = 0;
    for (const t of tiles) { sum += E[t]; w.biome[t] = Biome.Farm; w.flags[t] |= Flag.Field; w.fieldId[t] = id; }
    belt.fields.push({ level: Math.round(sum / tiles.length), tiles, center: [x0 + (wx >> 1), z0 + (wz >> 1)], was });
    id++;
  };

  for (let sz = 0; sz < N; sz += SECTION) {
    for (let sx = 0; sx < N; sx += SECTION) {
      // the section's inside: a strip of grass (or the section road) left along its west and north lines
      const x0 = sx + 1, z0 = sz + 1, S = SECTION - 1;
      if (x0 + S <= lo || z0 + S <= lo || x0 >= hi || z0 >= hi) continue;
      // a farmstead's yard: a 5 x 5 corner kept out of the fields, on the side of a road line where there is one
      // near an edge with no belt beyond, a section is left to the open plain more often the nearer it is, a field
      // or two at a time, so the belt frays out into the country around it
      const keep = Math.min(1, inFrom(sx + SECTION / 2, sz + SECTION / 2) / FEATHER);
      const thin = r();
      const stead = r() < 0.34;
      const roadX = (sx / SECTION) % ROAD_EVERY === 0, roadZ = (sz / SECTION) % ROAD_EVERY === 0;
      const yard = stead ? { x: roadX ? x0 : x0 + S - 5, z: roadZ ? z0 : z0 + S - 5 } : null;
      const cut = r();
      const half = S >> 1;
      const rects: [number, number, number, number][] = [];
      if (cut < 0.3) rects.push([x0, z0, S, S]);                                                   // one whole section
      else if (cut < 0.55) rects.push([x0, z0, S, half], [x0, z0 + half + 1, S, S - half - 1]);    // north and south halves
      else if (cut < 0.8) rects.push([x0, z0, half, S], [x0 + half + 1, z0, S - half - 1, S]);     // east and west halves
      else {                                                                                      // four quarters
        rects.push([x0, z0, half, half], [x0 + half + 1, z0, S - half - 1, half]);
        rects.push([x0, z0 + half + 1, half, S - half - 1], [x0 + half + 1, z0 + half + 1, S - half - 1, S - half - 1]);
      }
      if (yard) {
        // the yard's tiles are kept out of every field: mark them as taken for the moment
        for (let z = yard.z; z < yard.z + 5; z++) for (let x = yard.x; x < yard.x + 5; x++) if (inB(x, z)) w.flags[idx(x, z)] |= Flag.Field;
      }
      for (const [x, z, a, b] of rects) {
        if (keep < 1 && thin * 0.6 + hash2(x, z, 73) * 0.4 > keep) continue;
        field(x, z, a, b);
      }
      if (yard) {
        for (let z = yard.z; z < yard.z + 5; z++) for (let x = yard.x; x < yard.x + 5; x++) {
          if (inB(x, z) && w.fieldId[idx(x, z)] < 0) w.flags[idx(x, z)] &= ~Flag.Field;
        }
        // only a yard beside farmland is a farm's
        const fed = belt.fields.length && belt.fields[belt.fields.length - 1].tiles.some((t) => {
          const tx = t % N, tz = (t - tx) / N;
          return tx >= x0 - 1 && tx < x0 + S + 1 && tz >= z0 - 1 && tz < z0 + S + 1;
        });
        if (fed) belt.steads.push({ x: yard.x, z: yard.z });
      }
    }
  }
  return belt.fields.length >= 12 ? belt : null;
}

/** Undo a belt that was cut: every field back to the ground it was. */
export function unBelt(w: World, belt: Belt): void {
  for (const f of belt.fields) f.tiles.forEach((t, k) => { w.biome[t] = f.was![k]; w.flags[t] &= ~Flag.Field; w.fieldId[t] = -1; });
}

/**
 * The section roads and the farmsteads, laid once every town, road and work is in (generate.ts, last of all, on a
 * stream of its own). A road goes along a section line wherever it has farmland beside it for a good long run, and
 * stops at water, the railway, buildings, steep ground and the seam band; each run is joined to the county's roads
 * at an end if it meets none of them on its way. Returns the tiles of road laid.
 */
export function finishBelt(w: World, belt: Belt, band: number, r: Rng, lane: (gate: number) => void, join: (from: number, own: number[]) => void): number {
  void band;
  const lo = ROAD_EDGE, hi = N - ROAD_EDGE;
  const farm = (x: number, z: number) => inB(x, z) && !!(w.flags[idx(x, z)] & Flag.Field) && w.fieldId[idx(x, z)] >= BELT_ID0;
  const ok = (x: number, z: number, px: number, pz: number) => {
    if (x < lo || z < lo || x >= hi || z >= hi) return false;
    const i = idx(x, z);
    if (w.blocked[i] || w.rail[i] || w.deckAxis[i] || w.water[i] >= 0 || waterDepth(w, i) > 0) return false;
    if (w.flags[i] & (Flag.River | Flag.Poi | Flag.Ramp | Flag.Field | Flag.Corridor)) return false;
    if (w.feature[i] !== Feature.None && !w.road[i]) return false;
    if (w.townId[i] >= 0 && !w.road[i]) return false;
    // no step of more than one height level between neighbouring tiles of the road
    if (px >= 0) {
      const a = w.corners[i * 4], b = w.corners[idx(px, pz) * 4];
      if (Math.abs(a - b) > 1) return false;
    }
    let lo2 = 127, hi2 = -128;
    for (let q = 0; q < 4; q++) { lo2 = Math.min(lo2, w.corners[i * 4 + q]); hi2 = Math.max(hi2, w.corners[i * 4 + q]); }
    return hi2 - lo2 <= 1;
  };
  // a field gives way to whatever was built on it after it was cut (a station, a siding, a hangar)
  for (const b of w.allBuildings) {
    if (b.gone) continue;
    for (let z = b.z; z < b.z + b.d; z++) for (let x = b.x; x < b.x + b.w; x++) {
      if (!inB(x, z)) continue;
      const i = idx(x, z);
      if (w.fieldId[i] >= BELT_ID0) { w.flags[i] &= ~Flag.Field; w.fieldId[i] = -1; if (w.biome[i] === Biome.Farm) w.biome[i] = Biome.Plains; }
    }
  }
  let laid = 0;
  const runs: number[][] = [];
  for (let k = 0; k < N; k += SECTION * ROAD_EVERY) {
    for (const vertical of [true, false]) {
      let run: number[] = [], fed = 0;
      const flush = () => {
        if (run.length >= 12 && fed >= run.length * 0.5) runs.push(run);
        run = []; fed = 0;
      };
      for (let s = 0; s < N; s++) {
        const x = vertical ? k : s, z = vertical ? s : k;
        const prev = run.length ? run[run.length - 1] : -1;
        if (!ok(x, z, prev >= 0 ? prev % N : -1, prev >= 0 ? Math.floor(prev / N) : -1)) { flush(); continue; }
        run.push(idx(x, z));
        if (vertical ? farm(x + 1, z) || farm(x - 1, z) : farm(x, z + 1) || farm(x, z - 1)) fed++;
      }
      flush();
    }
  }
  for (const run of runs) {
    layGenerated(w, RoadType.Gravel, run, -1);
    laid += run.length;
  }
  // each run that met no other road is joined to the county's network from its middle-most end
  const before = new Set<number>();
  for (const run of runs) for (const t of run) before.add(t);
  for (const run of runs) {
    const met = run.some((t) => {
      const x = t % N, z = (t - x) / N;
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        if (!inB(x + dx, z + dz)) continue;
        const j = idx(x + dx, z + dz);
        if (w.road[j] && !before.has(j)) return true;
      }
      return false;
    });
    if (!met) join(run[0], run);
  }

  // the farmsteads, in their yards
  for (const s of belt.steads) {
    if (!yardOk(w, s.x, s.z, lo, hi)) continue;
    const corner = hash2(s.x, s.z, 71);
    const home = put(w, r, 'farmhouse', s.x + 1, s.z + 1, 1, 1, true);
    if (!home) continue;
    put(w, r, 'barn', s.x + 2 + (corner < 0.5 ? 1 : 0), s.z + 3, 2, 2, true);
    if (r() < 0.7) put(w, r, 'silo', s.x + 3, s.z + 1, 1, 1, true);
    for (const [dx, dz] of [[0, -1], [-1, 0], [0, 1], [1, 0]]) {
      const gx = home.x + dx, gz = home.z + dz;
      if (inB(gx, gz) && !w.blocked[idx(gx, gz)] && !(w.flags[idx(gx, gz)] & Flag.Poi)) { lane(idx(gx, gz)); break; }
    }
  }
  return laid;
}

/** A yard still open and flat enough for a farmstead (a road or a building may have come since). */
function yardOk(w: World, x: number, z: number, lo: number, hi: number): boolean {
  let lo2 = 127, hi2 = -128;
  for (let zz = z; zz < z + 5; zz++) for (let xx = x; xx < x + 5; xx++) {
    if (xx < lo || zz < lo || xx >= hi || zz >= hi) return false;
    const i = idx(xx, zz);
    if (w.road[i] || w.rail[i] || w.blocked[i] || w.townId[i] >= 0 || w.water[i] >= 0 || w.feature[i] !== Feature.None) return false;
    if (w.flags[i] & (Flag.Poi | Flag.Field | Flag.Track | Flag.Ramp | Flag.Corridor)) return false;
    for (let q = 0; q < 4; q++) { lo2 = Math.min(lo2, w.corners[i * 4 + q]); hi2 = Math.max(hi2, w.corners[i * 4 + q]); }
  }
  return hi2 - lo2 <= 1;
}

/** A country building, as world/countryside.ts puts one. */
function put(w: World, r: Rng, kind: BuildingKind, x: number, z: number, wx: number, wz: number, solidWanted: boolean): Building | null {
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
    if (!inB(xx, zz)) return null;
    const i = idx(xx, zz);
    if (w.flags[i] & Flag.Poi || w.blocked[i] || w.road[i]) return null;
  }
  const solid = solidWanted && KIND_SPEC[kind]?.solid !== false;
  let sum = 0;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) for (let q = 0; q < 4; q++) sum += w.corners[idx(xx, zz) * 4 + q];
  const level = Math.round(sum / (wx * wz * 4));
  const b: Building = { kind, x, z, w: wx, d: wz, facing: Math.floor(r() * 4), floors: 1, seed: Math.floor(r() * 2 ** 31), solid, level, uid: w.allBuildings.length };
  w.allBuildings.push(b);
  w.countryside.push(b);
  const top = level * STEP + buildingHeight(b);
  const mask = solid ? solidMask(b) : null;
  for (let zz = z; zz < z + wz; zz++) for (let xx = x; xx < x + wx; xx++) {
    const i = idx(xx, zz);
    w.flags[i] |= Flag.Poi;
    if (mask && mask[(zz - z) * wx + xx - x]) { w.blocked[i] = 1; w.roof[i] = Math.max(w.roof[i], top); }
  }
  return b;
}
