import type { Fleet, Unit } from './fleet';
import type { Hud } from './hud';
import type { Sfx } from './sfx';
import { NOS_REFILL } from './parts';
import { deeds } from './deeds';
import type { VehicleDef, VehicleState } from './vehicles';

/**
 * Nitrous (docs/upgrades.html): the one part with a button. Shift fires a full bottle while moving
 * forward on the throttle; the burst lasts its tier's seconds and ends early if the throttle is let go,
 * and the bottle then takes 60 real seconds to fill again (the fleet ticks the clock). A car afloat or
 * wading, a flyer, and a hired driver never fire one.
 */
export class Nitrous {
  /** Seconds left of the burst burning now. */
  burn = 0;
  /** Seconds since the burst lit, for the effects that only happen as it lights. */
  age = 0;

  constructor(private fleet: Fleet, private hud: Hud, private sfx: Sfx) {}

  /**
   * One frame. `press` is Shift pressed this frame; `allowed` is false in a menu, while watching
   * another vehicle, or with a tool out. Returns the share added to top speed (0 when not burning)
   * and whether a bottle was fired this frame.
   */
  step(dt: number, u: Unit | null, def: VehicleDef, veh: VehicleState, press: boolean, throttle: number, allowed: boolean): { boost: number; fired: boolean } {
    const n = def.nitrous;
    if (!n || !u || (def.kind !== 'land' && def.kind !== 'water')) {
      this.burn = 0;
      this.hud.setNitrous(null, false, 0);
      return { boost: 0, fired: false };
    }
    const bottles = this.fleet.bottles(u);
    let fired = false;
    if (this.burn > 0) {
      this.burn -= dt;
      this.age += dt;
      // a bottle is a bottle: lift off and the rest of it is gone
      if (throttle <= 0 || !allowed) this.burn = 0;
    }
    if (press && this.burn <= 0) {
      const car = veh as VehicleState & { inWater?: boolean; swimming?: boolean };
      const k = bottles.findIndex((b) => b <= 0);
      if (allowed && k >= 0 && throttle > 0 && veh.v > 0.3 && !car.inWater && !car.swimming) {
        this.fleet.fireBottle(u, k);
        this.burn = n.secs;
        this.age = 0;
        this.sfx.hiss(n.secs);
        deeds.add('shove');
        fired = true;
      } else if (allowed) this.hud.nitrousRefused();
    }
    const burning = this.burn > 0;
    const wait = Math.min(...bottles.map((b) => (b > 0 ? b : Infinity)));
    this.hud.setNitrous(bottles.map((b) => 1 - b / NOS_REFILL), burning, Number.isFinite(wait) ? wait : 0);
    return { boost: burning ? n.mul - 1 : 0, fired };
  }
}
