/**
 * The weather over a biome.
 *
 * Built like the seasons: a handful of shared uniforms (WEATHER in season.ts) and a few cheap
 * meshes, no per-tile state. Each biome has a schedule, a deterministic function of the game hour,
 * giving the strength of each of its effects; the weather right now is the schedule of the biome
 * under the player, scaled by the region weight at the player's tile, so driving out of a blob fades
 * the rain over a cell rather than switching it off. Ordinary cells keep what they had: winter snow.
 *
 * Draw calls: the streaks (rain, dust, snow), the aurora, the rainbow and the fireflies, each only
 * while its strength is above zero. The aurora and the rainbow are drawn in screen space, across
 * the top of the frame, because the tilt-shift camera looks down and never sees the sky itself.
 */
import * as THREE from 'three';
import { REGIONS } from '../world/regions';
import { N, REGION_KINDS, type RegionKind, type World } from '../world/tiles';
import { SEASON, WEATHER, seasonAt } from './season';
import type { DayNight } from './daynight';
import { clamp01 } from '../util/math';

/** Every effect's strength, 0..1. */
interface Wx {
  /** Rain; above 0.8 it is a downpour. The Moors' drizzle is 0.3. */
  rain: number;
  /** Thunder light: the sky goes dark under the rain. */
  storm: number;
  dust: number;
  /** A blizzard: snow down to the shore, streaks slanting, the fog in. */
  blizzard: number;
  /** Light snow falling: streaks only. */
  flurry: number;
  /** Mist lying below the biome's mist height. */
  mist: number;
  /** Low cloud: mist above that height instead (the Moors). */
  mistTop: number;
  haze: number;
  cloud: number;
  wind: number;
  aurora: number;
  rainbow: number;
  fireflies: number;
  /** Unpaved ground has turned to mud (the Green, during and an hour after its downpour). */
  mud: number;
  /** Thick fog: rolling banks over everything, the view closed right in (the rare wild weather). */
  fog: number;
}
type WxKey = keyof Wx;
const KEYS: WxKey[] = ['rain', 'storm', 'dust', 'blizzard', 'flurry', 'mist', 'mistTop', 'haze', 'cloud', 'wind', 'aurora', 'rainbow', 'fireflies', 'mud', 'fog'];
const calm = (): Wx => ({ rain: 0, storm: 0, dust: 0, blizzard: 0, flurry: 0, mist: 0, mistTop: 0, haze: 0, cloud: 0, wind: 0, aurora: 0, rainbow: 0, fireflies: 0, mud: 0, fog: 0 });

/** What the car and the traffic feel: see setDriveWeather in game/car.ts. */
interface DriveWeather { rain: number; dust: number; blizzard: number; mud: number; wind: number }

// ------------------------------------------------------------------------------------ schedules

const smooth = (a: number, b: number, x: number) => { const t = clamp01((x - a) / (b - a)); return t * t * (3 - 2 * t); };

/** 0..1 for a game day, a salt and the world's seed. */
function dayHash(day: number, salt: number, seed: number): number {
  let h = Math.imul(day | 0, 0x27d4eb2d) ^ Math.imul(salt | 0, 0x165667b1) ^ Math.imul(seed | 0, 0x9e3779b1);
  h = Math.imul(h ^ (h >>> 15), 0x85ebca6b);
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** A trapezoid over absolute hours: 0 before a, ramping to 1 by a + ramp, back to 0 at b + ramp. */
function span(t: number, a: number, b: number, ramp: number): number {
  return Math.min(smooth(a, a + ramp, t), 1 - smooth(b, b + ramp, t));
}

/** Within the day's hours [a, b), wrapping nothing: for the daily rhythms (mist until nine). */
function hours(t: number, a: number, b: number, ramp: number): number {
  const d = Math.floor(t / 24) * 24;
  return Math.max(span(t, d + a, d + b, ramp), span(t, d - 24 + a, d - 24 + b, ramp));
}

/**
 * An event that happens on `chance` of days, starting somewhere between `early` and `late` o'clock
 * and lasting `len` hours. Yesterday's is checked too, so a night storm runs on past midnight.
 */
function event(t: number, seed: number, salt: number, chance: number, early: number, late: number, len: number, ramp: number): number {
  const today = Math.floor(t / 24);
  let v = 0;
  for (let d = today - 1; d <= today; d++) {
    if (dayHash(d, salt, seed) >= chance) continue;
    const start = d * 24 + early + (late - early) * dayHash(d, salt + 101, seed);
    v = Math.max(v, span(t, start, start + len, ramp));
  }
  return v;
}

interface Sched {
  at(t: number, seed: number): Partial<Wx>;
  /** World height the mist lies below (or the low cloud above). */
  mistH?: number;
  /** How readily a rainbow follows the rain here. */
  bow?: number;
}

const season = (t: number) => seasonAt(Math.floor(t / 24), ((t % 24) + 24) % 24);

/** The Moors' drizzle: on most days, most of the day, with breaks. */
function drizzle(t: number, seed: number): number {
  const d = Math.floor(t / 24);
  if (dayHash(d, 31, seed) > 0.8) return 0;
  const f = Math.sin(t * 1.19 + dayHash(d, 32, seed) * 6.3) * 0.6 + Math.sin(t * 2.99 + dayHash(d, 33, seed) * 6.3) * 0.4 + 0.2;
  return 0.3 * clamp01(f * 3);
}

const SCHEDULES: Record<RegionKind, Sched> = {
  sands: {
    at(t, s) {
      const se = season(t);
      const dust = event(t, s, 1, 1 / 3, 9, 16, 1, 0.3);
      return { haze: hours(t, 11, 18.5, 1.5) * (0.45 + 0.55 * (se.summer + 0.5 * se.spring)) * (1 - dust), dust, wind: 0.25 + 0.75 * dust };
    },
  },
  icefield: {
    at(t, s) {
      const blizzard = event(t, s, 2, 1 / 3, 3, 18, 2, 0.5);
      const flurry = (dayHash(Math.floor(t / 24), 3, s) < 0.75 ? hours(t, 5, 10, 1) * 0.55 : 0) * (1 - blizzard);
      return { blizzard, flurry, aurora: 1 - Math.max(blizzard, flurry * 1.5), wind: 0.3 + 0.7 * blizzard };
    },
  },
  shallows: {
    bow: 1,
    at(t, s) {
      return { rain: 0.85 * event(t, s, 5, 0.5, 16, 16, 1 / 3, 0.1), wind: 0.25 };
    },
  },
  green: {
    mistH: 3.5, bow: 0.5,
    at(t) {
      return { rain: hours(t, 14, 15, 0.25), mud: hours(t, 14, 16, 0.25), mist: hours(t, 4, 9, 1) * 0.85, cloud: 0.65, wind: 0.1 };
    },
  },
  heights: {
    mistH: 3.0, bow: 0.6,
    at(t, s) {
      const se = season(t);
      const cold = se.autumn + se.winter;
      const flurry = cold > 0.5 ? event(t, s, 7, 0.7, 13, 15, 2, 0.5) * 0.7 * cold : 0;
      const storm = se.summer > 0.4 ? event(t, s, 8, 1 / 3, 18, 18, 2, 0.4) : 0;
      return { cloud: 0.6, mist: hours(t, 4.5, 9.5, 1) * 0.7, flurry, rain: storm, storm, wind: 0.35 + 0.4 * storm };
    },
  },
  moors: {
    mistH: 4.0, bow: 1,
    at(t, s) {
      const rain = drizzle(t, s);
      return { rain, mistTop: 0.45 + rain, cloud: 0.4, wind: 0.7 };
    },
  },
  veldt: {
    bow: 0.6,
    at(t, s) {
      const se = season(t);
      const wet = se.autumn + se.winter;
      const storm = wet > 0.5 ? event(t, s, 11, 0.75, 17.5, 18.5, 1.5, 0.4) * wet : 0;
      return { haze: hours(t, 11, 18, 1.5) * (0.4 + 0.5 * (se.spring + se.summer)) * (1 - storm), rain: storm, storm, wind: 0.3 + 0.5 * storm };
    },
  },
  fens: {
    mistH: 2.4, bow: 0.5,
    at(t, s) {
      const se = season(t);
      const storm = se.summer > 0.4 ? event(t, s, 13, 0.5, 18.5, 18.5, 1.5, 0.4) : 0;
      return { mist: hours(t, 3, 8, 1) * 0.9, haze: hours(t, 9, 19, 2) * 0.3 * (1 - storm), rain: storm, storm, fireflies: 1 - storm, wind: 0.1 + 0.5 * storm };
    },
  },
  terraces: {
    mistH: 3.5, bow: 0.7,
    at(t, s) {
      const se = season(t);
      const rain = se.spring > 0.3 ? event(t, s, 17, 0.7, 9, 12, 5, 1) * 0.5 * se.spring : 0;
      return { rain, mist: hours(t, 4, 9, 1) * 0.75, wind: 0.15 };
    },
  },
  goldhills: {
    mistH: 3.2, bow: 0.5,
    at(t, s) {
      const se = season(t);
      const rain = se.winter > 0.4 ? event(t, s, 23, 0.45, 10, 16, 3, 0.8) * 0.6 * se.winter : 0;
      // the marine layer: low cloud in the valleys most mornings of the dry season, burnt off by noon
      const layer = (dayHash(Math.floor(t / 24), 24, s) < 0.7 ? hours(t, 4, 11, 1.5) * 0.85 : 0) * (0.4 + 0.6 * (se.summer + se.spring));
      return { mist: layer * (1 - rain), haze: hours(t, 12, 18, 1.5) * 0.35 * se.summer, rain, wind: 0.2 + 0.2 * se.summer };
    },
  },
  whitewash: {
    bow: 0.4,
    at(t, s) {
      const se = season(t);
      const storm = se.winter > 0.4 ? event(t, s, 19, 0.25, 20, 21, 7, 0.6) : 0;
      return { wind: Math.max(0.15 + 0.75 * se.summer, storm), cloud: 0.55 * se.summer, rain: 0.9 * storm, storm: 0.7 * storm };
    },
  },
  // the Fire Coast: steam and sea fog in the mornings, squalls off the sea, snow showers and the aurora in winter
  firecoast: {
    mistH: 2.6, bow: 0.9,
    at(t, s) {
      const se = season(t);
      const squall = event(t, s, 41, 0.45, 8, 17, 2, 0.5);
      const flurry = se.winter > 0.4 ? squall * 0.7 * se.winter : 0;
      return { mist: hours(t, 4, 10, 1.5) * 0.7, rain: squall * (1 - se.winter) * 0.7, flurry, cloud: 0.5, aurora: se.winter * (1 - squall), wind: 0.4 + 0.5 * squall };
    },
  },
  // the Fjordlands: rain most days, cloud sitting on the tops, snow and the aurora in winter
  fjords: {
    mistH: 4.2, bow: 1,
    at(t, s) {
      const se = season(t);
      const rain = drizzle(t, s);
      const cold = se.winter + 0.5 * se.autumn;
      return { rain: rain * (1 - se.winter), flurry: rain * 1.6 * se.winter, mistTop: 0.4 + rain, mist: hours(t, 4, 9, 1) * 0.6, cloud: 0.5, aurora: cold > 0.5 ? cold * (1 - rain * 2) : 0, wind: 0.35 };
    },
  },
  // the Big Timber: fog in the trees every morning and soft rain for days
  bigtimber: {
    mistH: 4.5, bow: 0.7,
    at(t, s) {
      const se = season(t);
      const rain = drizzle(t, s) * (0.5 + 0.7 * (se.autumn + se.winter + 0.5 * se.spring));
      return { rain, mist: hours(t, 3, 11, 1.5) * 0.9, mistTop: 0.3 + rain, cloud: 0.6, wind: 0.15 };
    },
  },
  // the Red Rock: heat haze, dust devils on the flats, and a violent storm some summer evenings
  redrock: {
    bow: 0.8,
    at(t, s) {
      const se = season(t);
      const dust = event(t, s, 43, 0.25, 12, 17, 1, 0.3);
      const storm = se.summer > 0.4 ? event(t, s, 44, 0.3, 17, 19, 1.2, 0.3) : 0;
      return { haze: hours(t, 11, 18.5, 1.5) * (0.5 + 0.5 * se.summer) * (1 - dust) * (1 - storm), dust: dust * (1 - storm), rain: storm, storm, wind: 0.2 + 0.7 * Math.max(dust, storm) };
    },
  },
  // Dragon Bay: mist among the towers till noon, warm rain in the afternoon
  dragonbay: {
    mistH: 4.0, bow: 0.8,
    at(t, s) {
      const rain = event(t, s, 45, 0.55, 14, 17, 1.5, 0.4) * 0.7;
      return { mist: hours(t, 3, 11, 2) * 0.9, rain, cloud: 0.5, wind: 0.12 };
    },
  },
  // the Steppe: wind, always; dust in the dry months and snow blown flat across the grass in winter
  steppe: {
    bow: 0.5,
    at(t, s) {
      const se = season(t);
      const blow = event(t, s, 46, 0.35, 9, 18, 3, 0.5);
      return { wind: 0.6 + 0.4 * blow, dust: blow * 0.6 * se.summer, flurry: blow * se.winter, haze: hours(t, 12, 17, 2) * 0.3 * se.summer, cloud: 0.3 };
    },
  },
  // the Salt Pan: the heat shimmer off the flats all afternoon, and a white-out when the wind gets up
  saltpan: {
    bow: 0.3,
    at(t, s) {
      const se = season(t);
      const dust = event(t, s, 47, 0.2, 13, 17, 1, 0.3);
      return { haze: hours(t, 10, 19, 1.5) * (0.7 + 0.3 * se.summer) * (1 - dust), dust: dust * 0.8, wind: 0.2 + 0.7 * dust };
    },
  },
  // the Mangroves: a downpour every afternoon of the wet season, steam after, fireflies at night
  mangrove: {
    mistH: 2.2, bow: 0.8,
    at(t, s) {
      const se = season(t);
      const wet = 0.4 + 0.6 * (se.summer + se.autumn);
      const storm = event(t, s, 48, 0.7, 15, 17, 1.2, 0.3) * wet;
      return { rain: storm, storm: storm * 0.7, mud: hours(t, 15, 18, 0.5) * wet, mist: hours(t, 4, 8, 1) * 0.8, haze: hours(t, 10, 18, 2) * 0.3 * (1 - storm), fireflies: 1 - storm, wind: 0.1 + 0.5 * storm };
    },
  },
  // the Lavender Plateau: clear light, summer haze, and the mistral blowing down it for days
  lavender: {
    bow: 0.5,
    at(t, s) {
      const se = season(t);
      const mistral = dayHash(Math.floor(t / 24), 49, s) < 0.3 ? 1 : 0;
      const rain = se.autumn > 0.4 ? event(t, s, 50, 0.4, 10, 16, 3, 0.8) * 0.6 * se.autumn : 0;
      return { haze: hours(t, 12, 18, 1.5) * 0.4 * se.summer * (1 - mistral), wind: Math.max(0.15, 0.85 * mistral), rain };
    },
  },
};

/**
 * The wild weather (the user, 7 Oct 2026): rare, random spells over any county, the ordinary country included,
 * each county rolling its own days so the weather changes as you drive from one to the next. Thick fog on about
 * one evening in nine and one small hours in nine, lifting by mid-morning; rain on about one day in twelve;
 * a thunderstorm on about one afternoon or evening in twenty-five. Where it is cold (the season, and the ground's
 * own temperature) rain falls as snow, snow showers come far more often, and a storm is a blizzard. `dry` (the
 * deserts) keeps most of it away.
 */
function wildAt(t: number, seed: number, cx: number, cz: number, cold: number, dry: number): Partial<Wx> {
  const S = (seed ^ Math.imul(cx | 0, 0x3c6ef35f) ^ Math.imul(cz | 0, 0x2545f491)) | 0;
  const fog = Math.max(event(t, S, 61, 0.11, 18, 23, 6, 1.2), event(t, S, 62, 0.11, 1, 5, 4, 1.2));
  const rain = event(t, S, 63, 0.08, 0, 22, 3, 0.8);
  const storm = event(t, S, 64, 0.04, 13, 20, 2, 0.5);
  const snow = cold > 0.3 ? event(t, S, 65, 0.06 + 0.2 * cold, 0, 22, 5, 1) * clamp01(cold * 1.4) : 0;
  const blow = cold > 0.6 ? event(t, S, 66, 0.05, 0, 22, 3, 0.8) : 0;
  const wet = 1 - dry, asSnow = smooth(0.35, 0.6, cold);
  const falling = Math.max(rain * 0.75, storm) * wet;
  return {
    fog: fog * (1 - 0.9 * dry) * 0.95,
    rain: falling * (1 - asSnow),
    storm: storm * wet * (1 - asSnow),
    flurry: Math.max(snow, falling * asSnow) * 0.9,
    blizzard: Math.max(blow, storm * wet * asSnow),
    cloud: 0.55 * Math.max(rain, snow, storm),
    wind: 0.15 + 0.7 * Math.max(storm, blow),
  };
}
/** The deserts and the dry lands, where the wild weather's fog and rain hardly come. */
const DRY_KINDS = new Set<RegionKind>(['sands', 'saltpan', 'redrock', 'whitewash', 'steppe']);

/** The schedule of a biome at a game day and hour, before the night and the region weight act. */
export function weatherAt(kind: RegionKind, days: number, hour: number, seed = 1): Wx {
  const t = days * 24 + hour;
  const sc = SCHEDULES[kind];
  const out = Object.assign(calm(), sc.at(t, seed));
  // a rainbow follows the rain as it breaks, when the sun is low enough to throw one
  const before = Object.assign(calm(), sc.at(t - 0.6, seed)).rain;
  const breaking = clamp01((before - out.rain) * 3.5) * (sc.bow ?? 0.6);
  const el = Math.sin(((hour - 6) / 12) * Math.PI);
  out.rainbow = Math.max(out.rainbow, breaking * smooth(0.02, 0.12, el) * (1 - smooth(0.5, 0.7, el)));
  return out;
}

// ------------------------------------------------------------------------------------ the meshes

const STREAKS = 1800;
const FLIES = 320;

function streakMesh(): THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial> {
  const pos = new Float32Array(STREAKS * 4 * 3);
  const seed = new Float32Array(STREAKS * 4 * 4);
  const index = new Uint32Array(STREAKS * 6);
  let r = 12345;
  const rnd = () => ((r = (Math.imul(r, 1103515245) + 12345) >>> 0) / 4294967296);
  for (let i = 0; i < STREAKS; i++) {
    const s = [rnd(), rnd(), rnd(), (i + 0.5) / STREAKS];
    const corners = [[-0.5, 0], [0.5, 0], [0.5, 1], [-0.5, 1]];
    for (let k = 0; k < 4; k++) {
      pos.set([corners[k][0], corners[k][1], 0], (i * 4 + k) * 3);
      seed.set(s, (i * 4 + k) * 4);
    }
    const b = i * 4;
    index.set([b, b + 1, b + 2, b, b + 2, b + 3], i * 6);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('aSeed', new THREE.BufferAttribute(seed, 4));
  g.setIndex(new THREE.BufferAttribute(index, 1));
  const m = new THREE.ShaderMaterial({
    uniforms: {
      uCentre: { value: new THREE.Vector3() }, uBox: { value: new THREE.Vector3(44, 32, 44) },
      uVel: { value: new THREE.Vector3(0, -20, 0) }, uT: { value: 0 }, uLen: { value: 1 }, uWidth: { value: 0.05 },
      uCount: { value: 0 }, uFlutter: { value: 0 }, uColor: { value: new THREE.Color() }, uOpacity: { value: 0.5 },
      uSoft: { value: 0 }, uVary: { value: 0 }, uWave: { value: 0 },
    },
    vertexShader: /* glsl */ `
      attribute vec4 aSeed;
      uniform vec3 uCentre; uniform vec3 uBox; uniform vec3 uVel;
      uniform float uT; uniform float uLen; uniform float uWidth; uniform float uCount; uniform float uFlutter;
      uniform float uVary; uniform float uWave;
      varying float vA; varying float vY; varying float vX;
      void main() {
        float sp = 0.75 + 0.5 * fract(aSeed.x * 91.7 + aSeed.z * 13.3);
        vec3 p = aSeed.xyz * uBox + uVel * uT * sp;
        p.x += uFlutter * sin(uT * 1.7 + aSeed.y * 40.0);
        p.z += uFlutter * cos(uT * 1.3 + aSeed.x * 40.0);
        // blown sand skims and bounces rather than flying straight
        p.y += uWave * 0.7 * sin(uT * 2.3 + aSeed.z * 50.0) * sin(uT * 0.9 + aSeed.x * 23.0);
        p = mod(p - uCentre + uBox * 0.5, uBox) + uCentre - uBox * 0.5;
        vec3 dir = normalize(uVel);
        vec3 side = cross(dir, normalize(cameraPosition - p));
        float sl = length(side);
        side = sl > 0.001 ? side / sl : vec3(1.0, 0.0, 0.0);
        float on = step(aSeed.w, uCount);
        // each grain its own length, width and weight, so a gust reads as many things and not one pattern
        float len = uLen * mix(1.0, 0.35 + 1.3 * fract(aSeed.z * 57.1), uVary);
        float wid = uWidth * mix(1.0, 0.5 + 1.0 * fract(aSeed.y * 33.7), uVary);
        vec3 wp = p + (side * position.x * wid - dir * position.y * len) * on;
        vec3 e = abs(p - uCentre) / (uBox * 0.5);
        vA = on * (1.0 - smoothstep(0.6, 1.0, max(max(e.x, e.y), e.z))) * mix(1.0, 0.35 + 0.65 * fract(aSeed.x * 71.3), uVary);
        vY = position.y;
        vX = position.x * 2.0;
        gl_Position = projectionMatrix * viewMatrix * vec4(wp, 1.0);
      }`,
    fragmentShader: /* glsl */ `
      uniform vec3 uColor; uniform float uOpacity; uniform float uSoft;
      varying float vA; varying float vY; varying float vX;
      void main() {
        // rain and snow: a bright head fading back. Dust: tapered at both ends and soft at the sides, so the blur
        // outside the band in focus turns it to a wisp rather than a hard oval
        float hard = 1.0 - vY * 0.75;
        float soft = smoothstep(0.0, 0.35, vY) * (1.0 - smoothstep(0.45, 1.0, vY)) * (1.0 - vX * vX);
        gl_FragColor = vec4(uColor, uOpacity * vA * mix(hard, soft, uSoft));
      }`,
    transparent: true, depthWrite: false, fog: false, side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(g, m);
  mesh.frustumCulled = false;
  mesh.renderOrder = 5;
  return mesh;
}

/**
 * The sandstorm's veil: sheets of blown sand across the whole frame, stretched along the wind and rolling down it.
 * Drawn in clip space over the scene (before the tilt-shift, which softens it further); only while there is dust.
 */
function dustVeilMesh(): THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial> {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute([-1, -1, 0, 1, -1, 0, 1, 1, 0, -1, 1, 0], 3));
  g.setIndex([0, 1, 2, 0, 2, 3]);
  const m = new THREE.ShaderMaterial({
    uniforms: {
      uT: { value: 0 }, uStrength: { value: 0 }, uColor: { value: new THREE.Color() }, uDir: { value: new THREE.Vector2(1, 0) },
      uAspect: { value: 1 }, uScroll: { value: 0 },
      // how the sheets are drawn: stretched along and across the wind, the edges of a sheet, the fine grain, a floor
      uAlong: { value: 0.45 }, uAcross: { value: 1.6 }, uLo: { value: 0.38 }, uHi: { value: 0.78 }, uGrain: { value: 1 }, uBase: { value: 0.12 },
    },
    vertexShader: /* glsl */ `
      varying vec2 vUv;
      void main() { vUv = position.xy * 0.5 + 0.5; gl_Position = vec4(position.xy, 0.0, 1.0); }`,
    fragmentShader: /* glsl */ `
      uniform float uT; uniform float uStrength; uniform vec3 uColor; uniform vec2 uDir; uniform float uAspect; uniform float uScroll;
      uniform float uAlong; uniform float uAcross; uniform float uLo; uniform float uHi; uniform float uGrain; uniform float uBase;
      varying vec2 vUv;
      float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
      float noise(vec2 p) {
        vec2 i = floor(p), f = fract(p);
        vec2 u = f * f * (3.0 - 2.0 * f);
        return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
      }
      float fbm(vec2 p) {
        float s = 0.0, a = 0.5;
        for (int k = 0; k < 4; k++) { s += a * noise(p); p = p * 2.03 + vec2(1.7, 9.2); a *= 0.5; }
        return s;
      }
      void main() {
        vec2 p = vec2((vUv.x - 0.5) * uAspect, vUv.y - 0.5) * 2.4;
        // into the wind's frame: long along it, short across it, and carried down it
        vec2 q = vec2(dot(p, uDir), dot(p, vec2(-uDir.y, uDir.x)));
        q.x = q.x * uAlong - uScroll;
        q.y *= uAcross;
        // a slow warp so the sheets billow and fold instead of sliding by as one picture
        vec2 w = vec2(fbm(q * 0.6 + vec2(uT * 0.07, 0.0)), fbm(q * 0.6 + vec2(4.1, uT * 0.05)));
        float n = fbm(q + (w - 0.5) * 1.6);
        float sheet = smoothstep(uLo, uHi, n);
        // a fine grain on top, carried faster, so it reads as sand and not cloud (none in fog)
        float grain = uGrain > 0.0 ? fbm(vec2(q.x * 6.0 - uScroll * 3.0, q.y * 14.0)) : 0.0;
        float a = uStrength * (0.55 * sheet + 0.25 * sheet * grain * uGrain + uBase);
        gl_FragColor = vec4(uColor, clamp(a, 0.0, 0.85));
      }`,
    transparent: true, depthWrite: false, depthTest: false, fog: false,
  });
  const mesh = new THREE.Mesh(g, m);
  mesh.frustumCulled = false;
  mesh.renderOrder = 6;
  return mesh;
}

/** A strip across the top of the screen, subdivided along its length; the shaders place it in clip space. */
function screenStrip(segments: number): THREE.BufferGeometry {
  const pos: number[] = [];
  const index: number[] = [];
  for (let i = 0; i <= segments; i++) {
    const u = i / segments;
    pos.push(u, 0, 0, u, 1, 0);
    if (i < segments) { const b = i * 2; index.push(b, b + 2, b + 1, b + 1, b + 2, b + 3); }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(index);
  return g;
}

function auroraMesh(): THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial> {
  const m = new THREE.ShaderMaterial({
    uniforms: { uT: { value: 0 }, uPan: { value: 0 }, uStrength: { value: 0 } },
    vertexShader: /* glsl */ `
      uniform float uT; uniform float uPan;
      varying vec2 vUv; varying float vU;
      void main() {
        float u = position.x;
        // the curtain is anchored to the compass: turning the camera slides it across the frame
        float wu = u * 1.6 + uPan;
        float fold = sin(wu * 7.0 + uT * 0.21) * 0.07 + sin(wu * 17.0 - uT * 0.37) * 0.03;
        float x = u * 2.4 - 1.2;
        float y = 0.28 + fold + position.y * (0.55 + 0.12 * sin(wu * 5.0 + uT * 0.3));
        vUv = vec2(u, position.y); vU = wu;
        gl_Position = vec4(x, y, 0.0, 1.0);
      }`,
    fragmentShader: /* glsl */ `
      uniform float uT; uniform float uStrength;
      varying vec2 vUv; varying float vU;
      void main() {
        float v = vUv.y;
        float rays = 0.55 + 0.45 * sin(vU * 150.0 + uT * 0.9 + sin(vU * 31.0 + uT * 0.5) * 3.0);
        float band = 0.6 + 0.4 * sin(vU * 9.0 - uT * 0.45);
        float a = uStrength * smoothstep(0.0, 0.25, v) * pow(max(1.0 - v, 0.0), 1.6) * rays * band;
        a *= smoothstep(0.0, 0.15, vUv.x) * smoothstep(1.0, 0.85, vUv.x);
        vec3 col = mix(vec3(0.15, 1.0, 0.55), vec3(0.62, 0.3, 1.0), smoothstep(0.25, 0.9, v));
        gl_FragColor = vec4(col * max(a, 0.0) * 0.6, 1.0);
      }`,
    transparent: true, depthTest: false, depthWrite: false, fog: false,
    blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(screenStrip(160), m);
  mesh.frustumCulled = false;
  mesh.renderOrder = 10;
  return mesh;
}

function rainbowMesh(): THREE.Mesh<THREE.BufferGeometry, THREE.ShaderMaterial> {
  const m = new THREE.ShaderMaterial({
    uniforms: { uCentreX: { value: 0 }, uStrength: { value: 0 }, uAspect: { value: 1 } },
    vertexShader: /* glsl */ `
      uniform float uCentreX; uniform float uAspect;
      varying float vBand; varying float vU;
      void main() {
        // a half ring standing on the bottom of the frame, opposite the sun
        float ang = position.x * 3.14159;
        float r = 1.25 + position.y * 0.1;
        vec2 p = vec2(uCentreX + cos(ang) * r / uAspect * 1.15, -0.55 + sin(ang) * r);
        vBand = position.y; vU = position.x;
        gl_Position = vec4(p, 0.0, 1.0);
      }`,
    fragmentShader: /* glsl */ `
      uniform float uStrength;
      varying float vBand; varying float vU;
      vec3 hue(float h) { return clamp(abs(mod(h * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
      void main() {
        vec3 col = hue(vBand * 0.78);
        float edge = smoothstep(0.0, 0.2, vBand) * smoothstep(1.0, 0.8, vBand);
        float feet = smoothstep(0.0, 0.3, vU) * smoothstep(1.0, 0.7, vU);
        gl_FragColor = vec4(col * uStrength * edge * (0.35 + 0.65 * feet) * 0.55, 1.0);
      }`,
    transparent: true, depthTest: false, depthWrite: false, fog: false,
    blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
  });
  const mesh = new THREE.Mesh(screenStrip(96), m);
  mesh.frustumCulled = false;
  mesh.renderOrder = 10;
  return mesh;
}

function fireflyMesh(): THREE.Points<THREE.BufferGeometry, THREE.ShaderMaterial> {
  const pos = new Float32Array(FLIES * 3);
  let r = 777;
  const rnd = () => ((r = (Math.imul(r, 1103515245) + 12345) >>> 0) / 4294967296);
  for (let i = 0; i < FLIES * 3; i++) pos[i] = rnd();
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const m = new THREE.ShaderMaterial({
    uniforms: { uCentre: { value: new THREE.Vector3() }, uT: { value: 0 }, uStrength: { value: 0 }, uPx: { value: 1 } },
    vertexShader: /* glsl */ `
      uniform vec3 uCentre; uniform float uT; uniform float uPx;
      varying float vA;
      void main() {
        vec3 s = position;
        vec3 box = vec3(64.0, 1.0, 64.0);
        vec3 p = vec3(s.x * box.x + sin(uT * 0.23 + s.y * 30.0) * 3.0, 0.0, s.z * box.z + cos(uT * 0.19 + s.x * 30.0) * 3.0);
        p.xz = mod(p.xz - uCentre.xz + box.xz * 0.5, box.xz) + uCentre.xz - box.xz * 0.5;
        p.y = uCentre.y + 0.4 + s.y * 2.8 + sin(uT * 0.7 + s.z * 20.0) * 0.4;
        vec2 e = abs(p.xz - uCentre.xz) / (box.xz * 0.5);
        float blink = pow(0.5 + 0.5 * sin(uT * (1.1 + s.x) + s.z * 60.0), 4.0);
        vA = blink * (1.0 - smoothstep(0.6, 1.0, max(e.x, e.y)));
        vec4 mv = viewMatrix * vec4(p, 1.0);
        gl_PointSize = max(3.0, uPx * 1000.0 / -mv.z);
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: /* glsl */ `
      uniform float uStrength;
      varying float vA;
      void main() {
        float d = length(gl_PointCoord - 0.5) * 2.0;
        float glow = pow(max(0.0, 1.0 - d), 1.5);
        gl_FragColor = vec4(vec3(0.9, 1.0, 0.4) * glow * vA * uStrength * 1.8, 1.0);
      }`,
    transparent: true, depthWrite: false, fog: false, blending: THREE.AdditiveBlending,
  });
  const pts = new THREE.Points(g, m);
  pts.frustumCulled = false;
  pts.renderOrder = 6;
  return pts;
}

// ------------------------------------------------------------------------------------ the system

const DUSK_BASE = new THREE.Color(0.42, 0.45, 0.5);
const OCHRE = new THREE.Color(0xc79a5c);
const WHITEOUT = new THREE.Color(0.86, 0.89, 0.93);
const MIST = new THREE.Color(0.8, 0.84, 0.87);

/** Thick fog's grey, a touch blue. */
const FOG_GREY = new THREE.Color(0.74, 0.78, 0.82);
/** The camera's yaw on the ground, for laying the veils along the wind as it crosses the screen. */
const yawFwd = new THREE.Vector3();
function yawOf(camera: THREE.Camera): number { camera.getWorldDirection(yawFwd); return Math.atan2(yawFwd.x, yawFwd.z); }

/** The ordinary fog, relative to the focus: it starts well beyond anything the camera looks at. */
const FOG_NEAR = 830, FOG_FAR = 1330;

const KEEP_KEY = 'pocketRoads.weatherDebug';
interface Kept { force?: RegionKind | 'none' | null; set?: Partial<Wx>; hour?: number }

export class Weather {
  /** The smoothed weather right now, already scaled by the region weight. */
  readonly now: Wx = calm();
  /** The biome under the player, and how far into it they are. */
  region: RegionKind | null = null;
  weight = 0;
  /** How dark it is for driving, 0..1: headlights come on in dust and snow. */
  gloom = 0;
  private forced: RegionKind | null | undefined = undefined;
  private pinned: Partial<Wx> = {};
  private target = calm();
  private tint = new THREE.Color(1, 1, 1);
  private tintW = 0;
  private sky = new THREE.Color();
  private tmp = new THREE.Color();
  private clock = 0;
  private streaks = streakMesh();
  private veil = dustVeilMesh();
  /** The wild weather's veils: fog banks rolling by, and sheets of rain or snow driving across the frame. */
  private fogVeil = dustVeilMesh();
  private fallVeil = dustVeilMesh();
  /** Lightning: how bright the flash is now, and when the next comes (the clock's seconds). */
  private flash = 0;
  private nextFlash = 0;
  private flicker = 0;
  /** A lightning strike just lit the sky (main.ts plays the thunder, a beat later). */
  onLightning: ((near: number) => void) | null = null;
  private veilA = new THREE.Vector3();
  private veilB = new THREE.Vector3();
  private aurora = auroraMesh();
  private rainbow = rainbowMesh();
  private flies = fireflyMesh();
  private camFwd = new THREE.Vector3();
  /** Milliseconds the last update took, for the budget. */
  ms = 0;

  constructor(scene: THREE.Scene) {
    for (const m of [this.streaks, this.veil, this.fogVeil, this.fallVeil, this.aurora, this.rainbow, this.flies]) { m.visible = false; scene.add(m); }
    // fog: big soft banks, slow, no grain; the falling sheets: long thin streaks, fast
    const fu = this.fogVeil.material.uniforms;
    fu.uAlong.value = 0.22; fu.uAcross.value = 0.7; fu.uLo.value = 0.3; fu.uHi.value = 0.85; fu.uGrain.value = 0; fu.uBase.value = 0.2;
    const ru = this.fallVeil.material.uniforms;
    ru.uAlong.value = 0.09; ru.uAcross.value = 5.5; ru.uLo.value = 0.5; ru.uHi.value = 0.8; ru.uGrain.value = 0.6; ru.uBase.value = 0.04;
    // a debug override that survives a reload: pr.weather.keep({ force: 'sands', set: { dust: 1 }, hour: 13 })
    try {
      const kept = JSON.parse(sessionStorage.getItem(KEEP_KEY) ?? 'null') as Kept | null;
      if (kept) {
        if (kept.force !== undefined) this.force(kept.force);
        if (kept.set) this.set(kept.set);
        this.keptHour = kept.hour;
        this.snapNext = true;
      }
    } catch { /* no storage: nothing kept */ }
  }

  /** Keep a forced weather across reloads (for testing); keep(null) forgets it. */
  keep(k: Kept | null): void {
    try {
      if (k) sessionStorage.setItem(KEEP_KEY, JSON.stringify(k)); else sessionStorage.removeItem(KEEP_KEY);
    } catch { /* no storage */ }
    if (!k) { this.clear(); return; }
    this.clear();
    if (k.force !== undefined) this.force(k.force);
    if (k.set) this.set(k.set);
    this.keptHour = k.hour;
    this.snapNext = true;
  }
  private keptHour: number | undefined;

  /** Force a biome's schedule wherever the player is ('none' for ordinary weather); null or no argument lets the world decide again. */
  force(kind?: RegionKind | 'none' | null): void {
    this.forced = kind === 'none' ? null : kind ?? undefined;
  }

  /** Pin effects at fixed strengths on top of the schedule, e.g. set({ dust: 1 }); clear() lets go. */
  set(p: Partial<Wx>): void { Object.assign(this.pinned, p); }
  clear(): void { this.pinned = {}; this.forced = undefined; this.keptHour = undefined; }
  /** Jump straight to the target on the next frame instead of easing (for screenshots and tests). */
  snap(): void { this.snapNext = true; }
  private snapNext = false;

  /** What the car, the traffic and the sailboat feel. */
  get drive(): DriveWeather {
    const n = this.now;
    return { rain: n.rain, dust: n.dust, blizzard: Math.max(n.blizzard, n.flurry * 0.4), mud: n.mud, wind: n.wind };
  }

  /** The clock chip's weather: a raindrop, a dust swirl, snow or mist, or nothing. */
  icon(): '' | 'rain' | 'dust' | 'snow' | 'mist' {
    const n = this.now;
    if (n.blizzard > 0.3 || n.flurry > 0.3) return 'snow';
    if (n.dust > 0.3) return 'dust';
    if (n.rain > 0.15) return 'rain';
    if (Math.max(n.mist, n.mistTop, n.fog) > 0.4) return 'mist';
    return '';
  }

  /**
   * Once a frame, after the day/night cycle has lit the sky: read the biome under the player (tile
   * i on world w), work out its weather, and bend the sky, the fog, the lights and the uniforms.
   */
  update(dt: number, dayNight: DayNight, scene: THREE.Scene, camera: THREE.Camera, focus: THREE.Vector3, w: World | null, i: number, windHeading: number): void {
    const t0 = performance.now();
    if (this.keptHour !== undefined) { dayNight.hour = this.keptHour; }
    this.clock = (this.clock + dt) % 2000;

    // ---- which biome, how strongly
    let kind: RegionKind | null = null;
    let weight = 0;
    if (this.forced !== undefined) {
      kind = this.forced; weight = kind ? 1 : 0;
    } else if (w && i >= 0 && i < N * N) {
      const k = w.regionK[i];
      if (k > 0) { kind = REGION_KINDS[k - 1]; weight = w.regionW[i] / 255; }
      else if (w.region && w.kind !== 'continent') { kind = w.region; weight = 1; }
    }
    this.region = kind;
    this.weight = weight;

    // ---- the schedule, the night, the weight
    const tg = this.target;
    if (kind && weight > 0) {
      const s = weatherAt(kind, dayNight.days, dayNight.hour, dayNight.weatherSeed);
      for (const key of KEYS) tg[key] = s[key] * weight;
    } else for (const key of KEYS) tg[key] = 0;
    // the wild weather over every county (wildAt): cold by the season and the ground's own temperature, dry in the deserts
    if (w && i >= 0 && i < N * N) {
      const se = seasonAt(dayNight.days, dayNight.hour);
      const cold = clamp01(se.winter * 0.85 + se.autumn * 0.15 + (0.42 - w.temp[i]) * 2.2);
      const dry = kind && DRY_KINDS.has(kind) ? weight : 0;
      const wild = wildAt(dayNight.days * 24 + dayNight.hour, dayNight.weatherSeed, w.cx, w.cz, cold, dry);
      const share = 1 - 0.5 * weight;
      for (const key of KEYS) { const v = wild[key]; if (v !== undefined) tg[key] = Math.max(tg[key], v * share); }
    }
    tg.aurora *= smooth(0.55, 0.95, dayNight.night);
    tg.fireflies *= smooth(0.45, 0.85, dayNight.night);
    tg.rainbow *= 1 - smooth(0.2, 0.5, dayNight.night);
    for (const key of KEYS) if (this.pinned[key] !== undefined) tg[key] = this.pinned[key]!;

    // ---- ease toward it: a few seconds for the air, longer for the ground to dry
    const n = this.now;
    const k = this.snapNext ? 1 : 1 - Math.exp(-dt * 0.8);
    for (const key of KEYS) n[key] += (tg[key] - n[key]) * k;
    const wetTarget = clamp01(n.rain * 1.6);
    const wet = WEATHER.uWet.value;
    WEATHER.uWet.value = this.snapNext ? wetTarget : wet + (wetTarget - wet) * (1 - Math.exp(-dt * (wetTarget > wet ? 0.35 : 0.025)));
    this.snapNext = false;

    // ---- the sky: the biome's tint by day, then the weather over it
    if (kind) this.tint.set(REGIONS[kind].sky);
    this.tintW += (weight - this.tintW) * k;
    const day = 1 - dayNight.night;
    const bright = 0.12 + 0.88 * day;
    const bg = scene.background as THREE.Color;
    const sky = this.sky.copy(bg);
    sky.lerp(this.tint, this.tintW * 0.6 * day);
    const downpour = smooth(0.35, 1, n.rain);
    const overcast = Math.max(downpour * 0.75, n.storm, n.mistTop * 0.4);
    sky.lerp(this.tmp.copy(DUSK_BASE).multiplyScalar(bright), overcast * 0.7);
    sky.lerp(this.tmp.setRGB(0.2, 0.23, 0.28).multiplyScalar(0.4 + 0.6 * bright), n.storm * 0.6);
    sky.lerp(this.tmp.copy(OCHRE).multiplyScalar(bright), n.dust * 0.85);
    sky.lerp(this.tmp.copy(WHITEOUT).multiplyScalar(bright), n.blizzard * 0.8);
    const misty = Math.max(n.mist, n.mistTop, n.fog);
    sky.lerp(this.tmp.copy(MIST).multiplyScalar(bright), misty * 0.45);
    // thick fog greys the whole sky out, and lightning lights it for an instant
    sky.lerp(this.tmp.copy(FOG_GREY).multiplyScalar(0.3 + 0.7 * bright), n.fog * 0.55);
    if (this.flash > 0.01) sky.lerp(this.tmp.setRGB(0.92, 0.94, 1), this.flash * 0.55);
    bg.copy(sky);
    const focusD = camera.position.distanceTo(focus);
    const fog = scene.fog as THREE.Fog | null;
    if (fog) {
      fog.color.copy(sky);
      let near = FOG_NEAR, far = FOG_FAR;
      const pull = (s: number, nr: number, fr: number) => {
        near = Math.min(near, FOG_NEAR + (nr - FOG_NEAR) * s);
        far = Math.min(far, FOG_FAR + (fr - FOG_FAR) * s);
      };
      // the tilt-shift frame only spans about ±15% of the focus distance, so these are set
      // relative to it: what share of fog colour lies over the car is -near / (far - near)
      pull(downpour, -0.4 * focusD, 0.9 * focusD);
      pull(n.dust, -0.6 * focusD, 0.65 * focusD);
      pull(n.blizzard, -0.45 * focusD, 0.55 * focusD);
      pull(n.flurry, -0.12 * focusD, 1.0 * focusD);
      pull(misty, -0.45 * focusD, 1.0 * focusD);
      pull(n.fog, -0.5 * focusD, 0.75 * focusD);
      fog.near = Math.max(1, focusD + near);
      fog.far = Math.max(fog.near + 5, focusD + far);
    }
    // a thunderstorm darkens the day right down, as a sandstorm does (the lightning lights it up again)
    const dim = Math.max(overcast * 0.6, n.storm * 0.78, n.dust * 0.45, n.blizzard * 0.55, misty * 0.3, n.fog * 0.4);
    dayNight.key.intensity *= 1 - dim;
    dayNight.hemi.intensity *= 1 - dim * 0.25;
    // lightning, in a thunderstorm: a flash every few seconds, now and then a double, the sky white for a blink
    if (n.storm > 0.35 && dt > 0) {
      if (this.clock >= this.nextFlash || this.nextFlash - this.clock > 30) {
        this.flash = 1;
        this.flicker = Math.random() < 0.4 ? 0.18 : 0;
        this.nextFlash = this.clock + (2.5 + Math.random() * 9) / Math.min(1, n.storm + 0.2);
        this.onLightning?.(Math.random());
      }
    }
    if (this.flicker > 0) { this.flicker -= dt; if (this.flicker <= 0) this.flash = 0.8; }
    this.flash *= Math.exp(-dt * 7);
    if (this.flash > 0.01) {
      dayNight.key.intensity += this.flash * 2.2;
      dayNight.hemi.intensity += this.flash * 1.4;
    }
    if (n.aurora > 0.01) dayNight.hemi.color.lerp(this.tmp.setRGB(0.3, 0.9, 0.6), n.aurora * 0.12);
    this.gloom = Math.max(n.dust, n.blizzard, n.fog) * 0.8 + n.storm * 0.4;

    // ---- the ground's uniforms
    if (n.blizzard > 0.001) {
      SEASON.uSnow.value = Math.max(SEASON.uSnow.value, n.blizzard);
      SEASON.uSnowLine.value += (0.4 - SEASON.uSnowLine.value) * clamp01(n.blizzard * 1.25);
    }
    WEATHER.uCloud.value = n.cloud * (1 - overcast);
    WEATHER.uHaze.value = n.haze;
    WEATHER.uMist.value = misty;
    WEATHER.uMistTop.value = misty > 0.001 ? n.mistTop / (n.mist + n.mistTop + 1e-6) : 0;
    WEATHER.uMistH.value = kind ? SCHEDULES[kind].mistH ?? 3 : 3;
    this.tmp.copy(sky).lerp(MIST, 0.35 * day);
    WEATHER.uMistCol.value[0] = this.tmp.r; WEATHER.uMistCol.value[1] = this.tmp.g; WEATHER.uMistCol.value[2] = this.tmp.b;
    WEATHER.uSkyCol.value[0] = sky.r; WEATHER.uSkyCol.value[1] = sky.g; WEATHER.uSkyCol.value[2] = sky.b;
    WEATHER.uWind.value = n.wind;
    WEATHER.uWindDir.value[0] = Math.sin(windHeading);
    WEATHER.uWindDir.value[1] = Math.cos(windHeading);
    WEATHER.uDaylight.value = day;
    WEATHER.uFocusD.value = focusD;

    // ---- the streaks: rain, dust and snow share one mesh
    const r = n.rain, d = n.dust, sn = Math.max(n.blizzard, n.flurry * 0.6);
    const total = r + d + sn;
    const st = this.streaks;
    st.visible = total > 0.01;
    if (st.visible) {
      const u = st.material.uniforms;
      const wr = r / total, wd = d / total, ws = sn / total;
      const wx = Math.sin(windHeading), wz = Math.cos(windHeading);
      const gust = 1 + n.wind;
      (u.uVel.value as THREE.Vector3).set(
        wx * (wr * 3 * gust + wd * 22 + ws * 9 * gust),
        -(wr * 24 + wd * 1.2 + ws * 6),
        wz * (wr * 3 * gust + wd * 22 + ws * 9 * gust),
      );
      // thick enough to survive the tilt-shift blur outside the band in focus; dust is many fine, uneven wisps
      // (the veil below carries the storm's body), where one fat streak each blurred into a sliding oval
      u.uLen.value = wr * 1.4 + wd * 1.7 + ws * 0.75;
      u.uWidth.value = wr * 0.09 + wd * 0.07 + ws * 0.13;
      u.uFlutter.value = ws * 1.2 + wd * 0.4;
      u.uSoft.value = wd;
      u.uVary.value = wd;
      u.uWave.value = wd;
      u.uOpacity.value = (wr * 0.5 + wd * 0.4 + ws * 0.95) * (0.45 + 0.55 * bright);
      (u.uColor.value as THREE.Color).setRGB(
        wr * 0.78 + wd * 0.8 + ws * 1.0,
        wr * 0.82 + wd * 0.64 + ws * 1.0,
        wr * 0.9 + wd * 0.42 + ws * 1.0,
      ).multiplyScalar(0.3 + 0.7 * bright);
      u.uCount.value = clamp01(Math.max(r, d, sn) * 1.05);
      u.uT.value = this.clock;
      // the box sits over the car and a little toward the camera, where the eye is in focus
      (u.uCentre.value as THREE.Vector3).copy(focus).lerp(camera.position, 0.22);
    }

    // ---- the sandstorm's veil: sheets of sand rolling down the wind across the frame
    this.veil.visible = n.dust > 0.01;
    if (this.veil.visible) {
      const u = this.veil.material.uniforms;
      // the wind's way across the screen: the focus and a point downwind of it, projected
      this.veilA.copy(focus).project(camera);
      this.veilB.set(focus.x + Math.sin(windHeading) * 20, focus.y, focus.z + Math.cos(windHeading) * 20).project(camera);
      const dx = (this.veilB.x - this.veilA.x) * ((camera as THREE.PerspectiveCamera).aspect ?? 1), dy = this.veilB.y - this.veilA.y;
      const dl = Math.hypot(dx, dy);
      if (dl > 1e-4) (u.uDir.value as THREE.Vector2).set(dx / dl, dy / dl);
      u.uScroll.value = this.clock * (0.35 + 0.45 * n.wind);
      u.uT.value = this.clock;
      u.uAspect.value = (camera as THREE.PerspectiveCamera).aspect ?? 1;
      u.uStrength.value = n.dust * 0.42;
      (u.uColor.value as THREE.Color).setRGB(0.86, 0.68, 0.46).multiplyScalar(0.35 + 0.65 * bright);
    }

    // ---- the wild weather's veils: fog banks drifting with the breeze, sheets of rain or snow driving across
    const cam = camera as THREE.PerspectiveCamera;
    this.fogVeil.visible = n.fog > 0.01;
    if (this.fogVeil.visible) {
      const u = this.fogVeil.material.uniforms;
      if (this.veil.visible) (u.uDir.value as THREE.Vector2).copy(this.veil.material.uniforms.uDir.value as THREE.Vector2);
      else (u.uDir.value as THREE.Vector2).set(Math.sin(windHeading - yawOf(camera)), Math.cos(windHeading - yawOf(camera)) * 0.4).normalize();
      u.uScroll.value = this.clock * 0.03;
      u.uT.value = this.clock * 0.4;
      u.uAspect.value = cam.aspect ?? 1;
      u.uStrength.value = n.fog * 0.46;
      (u.uColor.value as THREE.Color).copy(FOG_GREY).multiplyScalar(0.28 + 0.72 * bright);
    }
    const sheets = Math.max(smooth(0.5, 1, n.rain) * 0.8, n.storm, n.blizzard);
    this.fallVeil.visible = sheets > 0.02;
    if (this.fallVeil.visible) {
      const u = this.fallVeil.material.uniforms;
      // falling down the screen, slanted by the wind across it
      const across = Math.sin(windHeading - yawOf(camera)) * (0.25 + 0.6 * n.wind);
      (u.uDir.value as THREE.Vector2).set(across, -1).normalize();
      const snowy = n.blizzard / (n.blizzard + n.rain + 1e-6);
      u.uScroll.value = this.clock * (2.4 - 1.6 * snowy);
      u.uT.value = this.clock;
      u.uAspect.value = cam.aspect ?? 1;
      u.uAcross.value = 5.5 - 3.5 * snowy;
      u.uStrength.value = sheets * (0.22 + 0.14 * snowy);
      (u.uColor.value as THREE.Color).setRGB(0.72 + 0.26 * snowy, 0.76 + 0.22 * snowy, 0.84 + 0.14 * snowy).multiplyScalar(0.3 + 0.7 * bright + this.flash * 0.6);
    }

    // ---- the aurora and the rainbow, across the top of the frame
    camera.getWorldDirection(this.camFwd);
    const yaw = Math.atan2(this.camFwd.x, this.camFwd.z);
    this.aurora.visible = n.aurora > 0.01;
    if (this.aurora.visible) {
      const u = this.aurora.material.uniforms;
      u.uT.value = this.clock; u.uStrength.value = n.aurora; u.uPan.value = -yaw / 1.2;
    }
    this.rainbow.visible = n.rainbow > 0.01;
    if (this.rainbow.visible) {
      // the bow stands opposite the sun; turn away from the sun to see it square on
      const a = ((dayNight.hour - 6) / 12) * Math.PI;
      const antiSun = Math.atan2(-Math.cos(a), -0.35);
      let rel = antiSun - yaw;
      rel = Math.atan2(Math.sin(rel), Math.cos(rel));
      const u = this.rainbow.material.uniforms;
      u.uCentreX.value = Math.max(-1.6, Math.min(1.6, -rel * 1.1));
      u.uStrength.value = n.rainbow * (0.45 + 0.55 * smooth(-0.2, 0.6, Math.cos(rel)));
      const cam = camera as THREE.PerspectiveCamera;
      u.uAspect.value = cam.aspect ?? 1;
    }

    // ---- fireflies over the marsh
    this.flies.visible = n.fireflies > 0.01;
    if (this.flies.visible) {
      const u = this.flies.material.uniforms;
      (u.uCentre.value as THREE.Vector3).copy(focus);
      u.uT.value = this.clock; u.uStrength.value = n.fireflies;
      u.uPx.value = Math.min(2, window.devicePixelRatio || 1) * Math.max(0.6, window.innerHeight / 900);
    }
    this.ms = performance.now() - t0;
  }
}
