import { CHAL } from '../../../shared/challenges';

/**
 * A game hour's ◆ for the PvP boards held (docs/challenges.html): each pays its twenty-fourth of CHAL.perDay, on the
 * account's line for that board (game/territory.ts payPvp), so a board held all day has paid exactly ◆ 1.
 */
export function payHeld(held: readonly string[], nameOf: (id: string) => string, pay: (n: number, what: string, key: string) => void): void {
  for (const id of held) pay(CHAL.perDay / 24, `PvP: ${nameOf(id)}`, id);
}
