import { N, World, DIRS } from './tiles';
import { job } from '../net/perfJobs';
import { generateWorld } from './generate';
import { refreshSeams } from './graph';
import { applyDelta, emptyDelta, isEmptyDelta, type CellDelta } from './delta';
import type { GenReply, GenRequest } from './genWorker';
import type { CellSurvey } from './survey';

export const key = (cx: number, cz: number): string => `${cx},${cz}`;
const parseKey = (k: string): [number, number] => k.split(',').map(Number) as [number, number];

/** How far out from the player's cell islands stay in memory: 1 keeps the 3x3 around them. */
const RESIDENT = 1;

/**
 * A second worker for the queue, on machines with the cores and memory for it: a county takes 3–9 s to build, so
 * the one the camera is sent to never waits behind one already under way, and its neighbours come two at a time.
 */
const TWO_WORKERS = typeof navigator !== 'undefined' && (navigator.hardwareConcurrency ?? 2) >= 4
  && ((navigator as Navigator & { deviceMemory?: number }).deviceMemory ?? 8) >= 4;

/**
 * Cells as the generator made them, before any edit, kept from the title reel so a game of the same seed
 * starts on them instead of building them again (the online world, main.ts): one use each, newest kept.
 */
const PRISTINE = new Map<string, { world: Record<string, unknown>; survey?: CellSurvey }>();
const PRISTINE_MAX = 16;
/** Kept cells never evicted for newer ones: the 3 × 3 the online game is expected to start in. */
const PROTECTED = new Set<string>();
const pristineKey = (seed: string, k: string) => `${seed}|${k}`;
/** The seed whose cells are kept (keepOnly): a cell built ahead for any other is let go. */
let keptSeed: string | null = null;
/** Forget every kept cell not of this seed (null: all of them); with `around`, its 3 × 3 is kept first and longest. */
export function keepOnly(seed: string | null, around?: [number, number] | null): void {
  for (const k of [...PRISTINE.keys()]) if (!seed || !k.startsWith(`${seed}|`)) PRISTINE.delete(k);
  if (seed !== keptSeed) for (const e of warmQueue.splice(0)) e.finish();
  keptSeed = seed;
  PROTECTED.clear();
  if (seed && around) for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) PROTECTED.add(pristineKey(seed, key(around[0] + dx, around[1] + dz)));
}
/** Keep a cell as generated, the oldest unprotected ones going past PRISTINE_MAX. */
function keepCell(pk: string, world: Record<string, unknown>, survey?: CellSurvey): void {
  PRISTINE.delete(pk);
  PRISTINE.set(pk, { world, survey });
  while (PRISTINE.size > PRISTINE_MAX) {
    const old = [...PRISTINE.keys()].find((q) => !PROTECTED.has(q));
    if (!old) break;
    PRISTINE.delete(old);
  }
}

/**
 * Cells built ahead of an online game, one at a time on a worker of their own that outlives any one world: the
 * title's first county (Islands.forceAsync), so a game signed into before the title is up still finds it, and the
 * county a player last played in and its neighbours, started while they type their PIN (prewarm). Each lands in
 * PRISTINE, where the game finds it; `done` settles when it is there, or when it is given up.
 */
interface Warm { seed: string; cx: number; cz: number; pk: string; done: Promise<void>; finish: () => void }
const warmQueue: Warm[] = [];
let warmer: Worker | null = null;
let warming: Warm | null = null;
function warmOf(seed: string, cx: number, cz: number): Warm {
  let finish!: () => void;
  const done = new Promise<void>((r) => { finish = r; });
  return { seed, cx, cz, pk: pristineKey(seed, key(cx, cz)), done, finish };
}
/**
 * Build the cell a game of this seed will start in ahead, then its neighbours, their 3 × 3 kept longest; cells
 * `busy` says are already being built (the title reel's own) are left to it.
 */
export function prewarm(seed: string, at: [number, number], busy: (k: string) => boolean = () => false): void {
  if (seed !== keptSeed) return;
  keepOnly(seed, at);
  // the cell itself first
  const cells: [number, number][] = [at];
  for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (dx || dz) cells.push([at[0] + dx, at[1] + dz]);
  // the latest name's cells replace whatever was still waiting to be built (one already waited for keeps its place)
  const was = warmQueue.splice(0);
  for (const [cx, cz] of cells) {
    const pk = pristineKey(seed, key(cx, cz));
    if (PRISTINE.has(pk) || warming?.pk === pk || busy(key(cx, cz))) continue;
    const i = was.findIndex((e) => e.pk === pk);
    warmQueue.push(i >= 0 ? was.splice(i, 1)[0] : warmOf(seed, cx, cz));
  }
  for (const e of was) e.finish();
  warmNext();
}
/** This cell next, before anything still waiting: settles once it is kept (or could not be). */
function warmFirst(seed: string, cx: number, cz: number): Promise<void> {
  const pk = pristineKey(seed, key(cx, cz));
  if (PRISTINE.has(pk)) return Promise.resolve();
  if (warming?.pk === pk) return warming.done;
  const i = warmQueue.findIndex((e) => e.pk === pk);
  const e = i >= 0 ? warmQueue.splice(i, 1)[0] : warmOf(seed, cx, cz);
  warmQueue.unshift(e);
  warmNext();
  return e.done;
}
function warmNext(): void {
  if (warming) return;
  const now = warmQueue.shift();
  if (!now) { warmer?.terminate(); warmer = null; return; }
  try {
    warmer ??= new Worker(new URL('./genWorker.ts', import.meta.url), { type: 'module' });
  } catch { for (const e of [now, ...warmQueue.splice(0)]) e.finish(); return; }
  warming = now;
  warmer.onmessage = (e: MessageEvent<GenReply>) => {
    // made by the worker for nobody else: kept as it came, no copy needed
    if (now.seed === keptSeed) keepCell(now.pk, e.data.world, e.data.survey);
    warming = null;
    now.finish();
    warmNext();
  };
  warmer.onerror = () => { warmer = null; warming = null; for (const e of [now, ...warmQueue.splice(0)]) e.finish(); };
  warmer.postMessage({ id: 1, seed: now.seed, cx: now.cx, cz: now.cz } satisfies GenRequest);
}
/**
 * A cell being built ahead: the promise of it while it is under way, so it is waited for rather than built twice;
 * one still queued is taken off the queue (null), for the game's own worker to build alongside.
 */
function warmingFor(pk: string): Promise<void> | null {
  if (warming?.pk === pk) return warming.done;
  const i = warmQueue.findIndex((e) => e.pk === pk);
  if (i >= 0) warmQueue.splice(i, 1)[0].finish();
  return null;
}
/** The kept cells, for the console (pr.islands.pristineKeys()). */
export const pristineKeys = (): string[] => [...PRISTINE.keys()];
/** A plain, unshared copy of a cell as generated: no neighbour links, nothing a later edit could reach. */
function pristineCopy(w: Record<string, unknown>): Record<string, unknown> {
  const out = { ...w };
  delete out.nbr;
  return structuredClone(out);
}

/**
 * The islands in memory, and the little factory that makes more.
 *
 * Only the 3x3 of cells around the player is kept. Anything further out is thrown away and built
 * again from the seed if they come back, so memory never grows however far they travel; the only
 * thing kept for an island the player has left is the short list of edits they made to it.
 */
export class Islands {
  readonly live = new Map<string, World>();
  /** What the player has changed on each island they have visited. */
  readonly deltas = new Map<string, CellDelta>();
  /** Every cell the player has set foot (or wheel, hull or wing) on. */
  readonly seen = new Set<string>();
  private pending = new Map<string, number>();
  private worker: Worker | null = null;
  /** How many workers the queue may build on at once (TWO_WORKERS; the console can set 1 to compare). */
  workers = TWO_WORKERS ? 2 : 1;
  /** The queue's second worker, made the first time both are wanted at once. */
  private second: Worker | null = null;
  /** The second worker couldn't be made, or failed: the first builds alone. */
  private noSecond = false;
  /** Milliseconds spent copying finished cells out of the worker (debug). */
  cloneMs = 0;
  /**
   * The pristine cells (PRISTINE): 'keep' copies every cell this world generates (the title reel of the
   * online world), 'use' starts on any kept for its seed (the online game), null neither.
   */
  pristine: 'keep' | 'use' | null = null;
  /** Disposed: a cell that arrives after is not adopted. */
  private gone = false;
  private nextId = 1;
  private waiting = new Map<number, [number, number]>();
  /**
   * Cells asked for and not yet handed to the worker, which builds one at a time in the order it is given them
   * and can't be told to stop. Kept here instead, so a cell no longer wanted by the time its turn comes is never
   * built, and the next one built is the nearest the centre, ahead first (the user, 28 Oct 2026: following a jet
   * across the country waited on counties it had long since flown past).
   */
  private queue: [number, number][] = [];
  /** The queue's cell each worker has now, by request id (forceAsync's aside). */
  private onWorker = new Map<Worker, number>();
  /** Which way the camera's subject is going (x, z, about a unit long): the county it is heading into goes first. */
  ahead: [number, number] | null = null;
  /** Cells asked for by forceAsync, built in the worker and adopted whatever the centre is. */
  private forced = new Map<number, { cx: number; cz: number; done: (w: World) => void }>();
  private cx = 0;
  private cz = 0;
  /** Cells held with their neighbours whatever the centre is: the title reel's next stop. */
  private kept: [number, number][] = [];
  /** Single cells held whatever the centre is: where the player's fleet is driving after them. */
  private pinned = new Set<string>();

  /** Called whenever an island arrives or leaves, so the renderer can catch up. */
  onArrive: ((w: World) => void) | null = null;
  onLeave: ((w: World) => void) | null = null;
  /** Called on a freshly generated island just before its edits are replayed (towns take the kinds they graduated to). */
  /** Called on each island before it is adopted; true if it changed what the island's survey shows. */
  prepare: ((w: World) => boolean | void) | null = null;
  /** The survey the worker made of an island as generated, while nothing since has changed it. */
  readonly surveys = new WeakMap<World, CellSurvey>();
  /**
   * Online (src/net): a cell's shared edits come from the server, and must be in hand before the cell is
   * adopted. Asked whenever a cell is wanted and again when it has been built: false holds the built
   * cell back until `admit` says its edits have arrived.
   */
  gate: ((cx: number, cz: number) => boolean) | null = null;
  private held = new Map<string, { w: World; survey?: CellSurvey }>();

  constructor(public seed: string) {
    try {
      this.worker = this.newWorker(true);
    } catch {
      this.worker = null; // no workers here: fall back to building islands on the main thread
    }
  }

  /** A worker for the queue: the first (forceAsync's cells go to it too) or the second. */
  private newWorker(first: boolean): Worker {
    const w = new Worker(new URL('./genWorker.ts', import.meta.url), { type: 'module' });
    w.onmessage = (e: MessageEvent<GenReply>) => {
      const t = performance.now();
      const data = e.data; // the copy out of the worker is made here, on the main thread
      this.cloneMs += performance.now() - t;
      this.receive(data, w);
    };
    w.onerror = first ? () => this.firstFailed() : () => this.secondFailed(w);
    return w;
  }

  /** The first worker failed: whatever was waiting on either is built here instead. */
  private firstFailed(): void {
    this.worker = null;
    this.second?.terminate();
    this.second = null;
    for (const [id, f] of [...this.forced]) { this.forced.delete(id); f.done(this.force(f.cx, f.cz)); }
    const again = [...this.waiting.values(), ...this.queue];
    this.waiting.clear();
    this.queue = [];
    this.onWorker.clear();
    for (const [x, z] of again) { this.pending.delete(key(x, z)); this.request(x, z); }
  }

  /** The second worker failed: the first carries on alone, and the cell this one had goes back in the queue. */
  private secondFailed(w: Worker): void {
    this.noSecond = true;
    w.terminate();
    if (this.second === w) this.second = null;
    const id = this.onWorker.get(w);
    this.onWorker.delete(w);
    const c = id !== undefined ? this.waiting.get(id) : undefined;
    if (id !== undefined) this.waiting.delete(id);
    if (c) { this.pending.delete(key(c[0], c[1])); this.request(c[0], c[1]); }
  }

  /** A worker with no cell of the queue's, the second made if both are wanted; null when both are busy. */
  private idleWorker(): Worker | null {
    if (!this.worker) return null;
    if (!this.onWorker.has(this.worker)) return this.worker;
    if (this.workers < 2 || this.noSecond || this.gone) return null;
    if (!this.second) {
      try { this.second = this.newWorker(false); } catch { this.noSecond = true; return null; }
    }
    return this.onWorker.has(this.second) ? null : this.second;
  }

  /**
   * Stop every worker still building a county nobody wants any more (the camera sent on somewhere else), rather
   * than have the centre's wait behind it or share the machine with it: up to 9 s either way. The first is made
   * again at once, and only while no forceAsync cell is with it; the second when next wanted.
   */
  private stopStale(): void {
    for (const w of [this.second, this.worker]) {
      if (!w || (w === this.worker && this.forced.size)) continue;
      const id = this.onWorker.get(w);
      const c = id !== undefined ? this.waiting.get(id) : undefined;
      if (id === undefined || !c || this.wanted(c[0], c[1])) continue;
      if (w === this.worker) { try { this.worker = this.newWorker(true); } catch { continue; } } else this.second = null;
      w.terminate();
      this.onWorker.delete(w);
      this.waiting.delete(id);
      if (this.pending.get(key(c[0], c[1])) === id) this.pending.delete(key(c[0], c[1]));
    }
  }

  get centre(): [number, number] { return [this.cx, this.cz]; }

  /** Is (cx, cz) within reach of the centre or of a kept cell? */
  private wanted(cx: number, cz: number): boolean {
    if (Math.abs(cx - this.cx) <= RESIDENT && Math.abs(cz - this.cz) <= RESIDENT) return true;
    if (this.pinned.has(key(cx, cz))) return true;
    return this.kept.some(([x, z]) => Math.abs(cx - x) <= RESIDENT && Math.abs(cz - z) <= RESIDENT);
  }

  /**
   * Hold a cell and its neighbours in memory whatever the centre does, and start building them:
   * the title reel generates its next stop while the current one is still on screen.
   */
  keep(cx: number, cz: number, build = true): void {
    if (!this.kept.some(([x, z]) => x === cx && z === cz)) this.kept.push([cx, cz]);
    // (`build` false: only held, so a setCentre straight after doesn't drop them; their building is asked for later)
    if (!build) return;
    for (let dz = -RESIDENT; dz <= RESIDENT; dz++) for (let dx = -RESIDENT; dx <= RESIDENT; dx++) this.request(cx + dx, cz + dz);
  }

  /**
   * Hold exactly these cells in memory, as well as the window round the centre: the cells the fleet
   * is driving through and into (game/convoy.ts). Cells pinned before and not now are let go, unless
   * something else still wants them.
   */
  pin(cells: [number, number][]): void {
    const next = new Set(cells.map(([x, z]) => key(x, z)));
    if (next.size === this.pinned.size && [...next].every((k) => this.pinned.has(k))) return;
    this.pinned = next;
    for (const k of [...this.live.keys()]) {
      const [x, z] = parseKey(k);
      if (!this.wanted(x, z)) this.drop(k);
    }
    for (const [x, z] of cells) this.request(x, z);
  }

  /** Let every kept cell go; the next setCentre drops whatever is out of reach. */
  release(): void { this.kept = []; }

  /** Are a cell and all its neighbours in memory? */
  /** Is this one county in memory? */
  has(cx: number, cz: number): boolean { return this.live.has(key(cx, cz)); }

  ready(cx: number, cz: number): boolean {
    for (let dz = -RESIDENT; dz <= RESIDENT; dz++) for (let dx = -RESIDENT; dx <= RESIDENT; dx++) {
      if (!this.live.has(key(cx + dx, cz + dz))) return false;
    }
    return true;
  }
  get busy(): number { return this.pending.size; }

  dispose(): void {
    this.gone = true;
    this.worker?.terminate();
    this.worker = null;
    this.second?.terminate();
    this.second = null;
    this.onWorker.clear();
    for (const w of this.live.values()) this.onLeave?.(w);
    this.live.clear();
    this.pending.clear();
    this.waiting.clear();
    this.queue = [];
    this.forced.clear();
    this.held.clear();
  }

  /** Every cell in memory, being built, or built and waiting at the gate. */
  wantedKeys(): string[] { return [...new Set([...this.live.keys(), ...this.pending.keys(), ...this.held.keys()])]; }

  /** A gated cell's edits have arrived (they are in `deltas` by now): adopt it if it was built and waiting. */
  admit(cx: number, cz: number): void {
    const k = key(cx, cz);
    const h = this.held.get(k);
    if (!h) return;
    this.held.delete(k);
    if (this.wanted(cx, cz)) this.finish(h.w, h.survey);
  }

  /** The gate has been taken away (signed out): whatever was waiting at it comes in as it is. */
  admitAll(): void {
    for (const k of [...this.held.keys()]) { const [x, z] = parseKey(k); this.admit(x, z); }
  }

  /** A built cell takes its towns' kinds and its edits, and joins the world. */
  private finish(w: World, survey?: CellSurvey): void {
    const k = key(w.cx, w.cz);
    const changed = this.prepare?.(w);
    const delta = this.deltas.get(k);
    applyDelta(w, delta);
    if (survey && !changed && isEmptyDelta(delta)) this.surveys.set(w, survey);
    this.adopt(w);
  }

  at(cx: number, cz: number): World | null { return this.live.get(key(cx, cz)) ?? null; }

  delta(cx: number, cz: number): CellDelta {
    const k = key(cx, cz);
    let d = this.deltas.get(k);
    if (!d) this.deltas.set(k, (d = emptyDelta()));
    return d;
  }

  /**
   * Move the resident window to the player's cell: ask for anything missing around it, and drop
   * whatever has fallen outside. Returns true when the centre island is ready to play on. A window
   * moved only to watch something far off (`visit` false) doesn't count as the player having been there.
   */
  setCentre(cx: number, cz: number, visit = true): boolean {
    this.cx = cx;
    this.cz = cz;
    if (visit) this.seen.add(key(cx, cz));
    for (const k of [...this.live.keys()]) {
      const [x, z] = parseKey(k);
      if (!this.wanted(x, z)) this.drop(k);
    }
    for (const k of [...this.held.keys()]) { const [x, z] = parseKey(k); if (!this.wanted(x, z)) this.held.delete(k); }
    // the island under the player first, then its neighbours
    const order: [number, number][] = [[0, 0]];
    for (let dz = -RESIDENT; dz <= RESIDENT; dz++) for (let dx = -RESIDENT; dx <= RESIDENT; dx++) if (dx || dz) order.push([dx, dz]);
    for (const [dx, dz] of order) this.request(cx + dx, cz + dz);
    return this.live.has(key(cx, cz));
  }

  /** Build the island at (cx, cz) here and now, however long it takes. Used for the first one. */
  force(cx: number, cz: number): World {
    const k = key(cx, cz);
    const have = this.live.get(k);
    if (have) return have;
    // asked for here and now: it cannot wait at the gate, so edits that arrive later are laid over it as they come
    this.gate?.(cx, cz);
    this.held.delete(k);
    const kept = this.takePristine(k);
    const w = kept ? kept.w : job('world gen (main thread)', () => generateWorld(this.seed, cx, cz));
    if (!kept) this.keepPristine(k, w as unknown as Record<string, unknown>);
    this.prepare?.(w);
    applyDelta(w, this.deltas.get(k));
    this.adopt(w);
    return w;
  }

  /**
   * force, without stopping the page: built in the worker (the loading screen keeps turning meanwhile) and
   * adopted the moment it arrives, wanted or not and whatever the gate says, as force would.
   */
  forceAsync(cx: number, cz: number): Promise<World> {
    const k = key(cx, cz);
    const have = this.live.get(k);
    if (have) return Promise.resolve(have);
    // a world keeping its cells (the online world's title): built on the worker that outlives this world, so a
    // game signed into before the title is up starts on it rather than building it again
    if (this.pristine === 'keep' && this.seed === keptSeed && this.worker) {
      this.gate?.(cx, cz);
      return warmFirst(this.seed, cx, cz).then(() => this.fromKept(cx, cz) ?? this.ownAsync(cx, cz));
    }
    return this.ownAsync(cx, cz);
  }

  /** A kept cell, copied into this world (the copy kept stays for the game); null if it isn't kept after all. */
  private fromKept(cx: number, cz: number): World | null {
    const k = key(cx, cz);
    const have = this.live.get(k);
    if (have) return have;
    const hit = PRISTINE.get(pristineKey(this.seed, k));
    if (!hit) return null;
    const w = Object.assign(Object.create(World.prototype) as World, structuredClone(hit.world));
    w.nbr = [null, null, null, null];
    // this world went while it was being built: nobody is waiting on its arrival
    if (this.gone) return w;
    this.held.delete(k);
    this.finish(w, hit.survey && structuredClone(hit.survey));
    return this.live.get(k) ?? w;
  }

  private ownAsync(cx: number, cz: number): Promise<World> {
    const k = key(cx, cz);
    const have = this.live.get(k);
    if (have) return Promise.resolve(have);
    const kept = this.pristine === 'use' && PRISTINE.has(pristineKey(this.seed, k));
    // being built ahead (prewarm): taken when it is done
    const ahead = this.pristine === 'use' && !kept ? warmingFor(pristineKey(this.seed, k)) : null;
    if (ahead) return ahead.then(() => this.forceAsync(cx, cz));
    if (kept || !this.worker) return new Promise((done) => setTimeout(() => done(this.force(cx, cz)), 0));
    this.gate?.(cx, cz);
    const id = this.nextId++;
    return new Promise((done) => {
      this.forced.set(id, { cx, cz, done });
      this.worker!.postMessage({ id, seed: this.seed, cx, cz } satisfies GenRequest);
    });
  }

  private request(cx: number, cz: number): void {
    const k = key(cx, cz);
    if (this.live.has(k) || this.pending.has(k) || this.held.has(k)) return;
    // online, its shared edits are sent for while it is being built
    this.gate?.(cx, cz);
    // being built ahead (prewarm): asked for again once it is kept, unless this world has gone meanwhile
    const ahead = this.pristine === 'use' && !PRISTINE.has(pristineKey(this.seed, k)) ? warmingFor(pristineKey(this.seed, k)) : null;
    if (ahead) {
      this.pending.set(k, 0);
      void ahead.then(() => {
        if (!this.pending.has(k)) return;
        this.pending.delete(k);
        if (this.wanted(cx, cz)) this.request(cx, cz);
      });
      return;
    }
    // the title reel built it already: it comes in on the next idle moment, as if from the worker
    const kept = this.takePristine(k);
    if (kept) {
      this.pending.set(k, 0);
      setTimeout(() => {
        this.pending.delete(k);
        if (!this.wanted(cx, cz)) return;
        if (this.gate && !this.gate(cx, cz)) { this.held.set(k, { w: kept.w, survey: kept.survey }); return; }
        this.finish(kept.w, kept.survey);
      }, 0);
      return;
    }
    if (!this.worker) {
      // no worker: build it here, but only one an idle moment, so the frame still lands
      this.pending.set(k, 0);
      setTimeout(() => {
        this.pending.delete(k);
        if (!this.wanted(cx, cz)) return;
        const w = job('world gen (main thread)', () => generateWorld(this.seed, cx, cz));
        if (this.gate && !this.gate(cx, cz)) { this.held.set(k, { w }); return; }
        this.finish(w);
      }, 0);
      return;
    }
    this.pending.set(k, -1);
    this.queue.push([cx, cz]);
    this.pump();
  }

  /** Each idle worker's next cell: the nearest the centre still wanted, the one ahead first. */
  private pump(): void {
    if (!this.worker) return;
    this.queue = this.queue.filter(([x, z]) => {
      if (this.wanted(x, z)) return true;
      this.pending.delete(key(x, z));
      return false;
    });
    // the centre's county still to come: nothing nobody wants is built ahead of it or beside it
    if (this.pending.has(key(this.cx, this.cz))) this.stopStale();
    while (this.queue.length) {
      // and it is built on its own, the machine to itself; its neighbours follow two at a time
      const c = this.pending.get(key(this.cx, this.cz));
      if (c !== undefined && c > 0 && this.waiting.has(c)) return;
      const wk = this.idleWorker();
      if (!wk) return;
      let best = 0, bestRank = Infinity;
      this.queue.forEach(([x, z], i) => { const r = this.rank(x, z); if (r < bestRank) { bestRank = r; best = i; } });
      const [cx, cz] = this.queue.splice(best, 1)[0];
      const id = this.nextId++;
      this.pending.set(key(cx, cz), id);
      this.waiting.set(id, [cx, cz]);
      this.onWorker.set(wk, id);
      wk.postMessage({ id, seed: this.seed, cx, cz } satisfies GenRequest);
    }
  }

  /** Lower first: the centre, then by rings out from it, and within a ring the cells the subject is heading for. */
  private rank(x: number, z: number): number {
    const dx = x - this.cx, dz = z - this.cz;
    if (!dx && !dz) return 0;
    const d = Math.hypot(dx, dz);
    const along = this.ahead ? (dx * this.ahead[0] + dz * this.ahead[1]) / d : 0;
    return Math.max(Math.abs(dx), Math.abs(dz)) * 4 + d - 2 * along;
  }

  private receive(r: GenReply, from: Worker): void {
    // the worker's next cell first, so it is busy again while this one is taken in
    if (this.onWorker.get(from) === r.id) this.onWorker.delete(from);
    if (this.waiting.delete(r.id)) this.pump();
    const k = key(r.cx, r.cz);
    const f = this.forced.get(r.id);
    if (f) {
      this.forced.delete(r.id);
      const have = this.live.get(k);
      if (have) { f.done(have); return; }
      this.keepPristine(k, r.world, r.survey);
      const w = Object.assign(Object.create(World.prototype) as World, r.world);
      w.nbr = [null, null, null, null];
      this.held.delete(k);
      this.finish(w, r.survey);
      f.done(this.live.get(k) ?? w);
      return;
    }
    if (this.pending.get(k) !== r.id) return;
    this.pending.delete(k);
    // out of range while it was being built: let it go
    if (!this.wanted(r.cx, r.cz)) return;
    this.keepPristine(k, r.world, r.survey);
    const w = Object.assign(Object.create(World.prototype) as World, r.world);
    w.nbr = [null, null, null, null];
    if (this.gate && !this.gate(r.cx, r.cz)) { this.held.set(k, { w, survey: r.survey }); return; }
    this.finish(w, r.survey);
  }

  /** A kept cell of this seed, taken (it is used once), as a world of its own; null if none or not using them. */
  private takePristine(k: string): { w: World; survey?: CellSurvey } | null {
    if (this.pristine !== 'use') return null;
    const pk = pristineKey(this.seed, k);
    const hit = PRISTINE.get(pk);
    if (!hit) return null;
    PRISTINE.delete(pk);
    const w = Object.assign(Object.create(World.prototype) as World, hit.world);
    w.nbr = [null, null, null, null];
    return { w, survey: hit.survey };
  }

  /** Copy a cell as it was generated, before anything changes it, if this world keeps them. */
  private keepPristine(k: string, world: Record<string, unknown>, survey?: CellSurvey): void {
    if (this.pristine !== 'keep') return;
    keepCell(pristineKey(this.seed, k), pristineCopy(world), survey && structuredClone(survey));
  }

  private adopt(w: World): void {
    const k = key(w.cx, w.cz);
    if (this.live.has(k)) return;
    this.live.set(k, w);
    this.linkNeighbours(w);
    this.onArrive?.(w);
  }

  private drop(k: string): void {
    const w = this.live.get(k);
    if (!w) return;
    this.live.delete(k);
    for (let d = 0; d < 4; d++) {
      const nb = w.nbr[d];
      if (!nb) continue;
      nb.nbr[(d + 2) & 3] = null;
      refreshSeams(nb);
      w.nbr[d] = null;
    }
    this.onLeave?.(w);
  }

  /** Join an island to whichever of its four neighbours are already here, both ways. */
  private linkNeighbours(w: World): void {
    for (let d = 0; d < 4; d++) {
      const nb = this.live.get(key(w.cx + DIRS[d][0], w.cz + DIRS[d][1]));
      if (!nb) continue;
      w.nbr[d] = nb;
      nb.nbr[(d + 2) & 3] = w;
      refreshSeams(nb);
    }
    refreshSeams(w);
  }
}

/** Global tile coordinates of a point on an island. */
const globalX = (w: World, x: number): number => w.ox + x;
const globalZ = (w: World, z: number): number => w.oz + z;
/** Which cell a global tile coordinate falls in. */
export const cellAt = (v: number): number => Math.floor(v / N);
