import { N, World } from './tiles';
import { job } from '../net/perfJobs';
import { surveyOf, type CellSurvey, type SurveyAirport } from './survey';
import { generateWorld } from './generate';
import type { GenReply, GenRequest } from './genWorker';

/** Surveys kept at once; a 7 × 7 region and a flier's ring fit several times over. */
const KEEP = 160;

const key = (cx: number, cz: number): string => `${cx},${cz}`;
/** Workers made again after one dies, at most, before the surveys fall back to the main thread. */
const RESPAWNS = 6;
/** With no workers at all: a county generated on the main thread at most this often (ms), while wanted. */
const BY_HAND_MS = 1200;

/** An island in memory to survey off the main thread, and who wants the result. */
interface Edit { w: World; then?: (s: CellSurvey) => void }
/** A survey worker, and the cell it is on. */
interface Slot { w: Worker; job: { id: number; k: string; edit?: Edit } | null }

/** An airport anywhere surveyed, in world tiles, with its three-letter code. */
export interface KnownAirport extends SurveyAirport { cx: number; cz: number; gx: number; gz: number; code: string }

/**
 * Counties at a glance, well beyond the 3 × 3 in memory: the region map's ground and the airports a
 * flier sees codes over. A cell in memory is surveyed on the spot; any other is generated in a worker
 * of its own (so it never queues behind the islands the player is about to drive onto), one at a time,
 * nearest first, a few at a time, and only while something wants it.
 */
export class Surveyor {
  private cache = new Map<string, CellSurvey>();
  /** Cells whose survey came from the island in memory, with the player's edits: a worker's copy never replaces one. */
  private live = new Set<string>();
  /** The survey workers, made on first use, and which cell each is on. */
  private pool: Slot[] = [];
  private respawns = 0;
  /** Cells whose survey failed in a worker: not asked for again. */
  private failed = new Set<string>();
  /** The last job handed out was an edit: the next free worker takes a wanted cell, if any (so edits never starve the map). */
  private lastEdit = false;
  private byHandAt = 0;
  /**
   * With no workers: wanted counties may be generated on the main thread (a hitch each). Only while the region
   * map is up, where a hitch costs nothing; a flier's ring of airports waits.
   */
  byHandOk = false;
  /** Islands in memory waiting for a worker to survey a copy of them (later), oldest first. */
  private edits: Edit[] = [];
  private made = false;
  private nextId = 1;
  private wanted: [number, number][] = [];
  /** Bumped whenever a survey arrives or changes, so views drawn from them know to redraw. */
  version = 0;
  /** A survey arrived from the worker (not from memory): the atlas takes its stamp and its towns. */
  onSurvey: ((s: CellSurvey) => void) | null = null;

  constructor(private seed: string) {}

  /** A worker or a few, on the cores the islands and the page are not using. */
  private start(): void {
    this.made = true;
    const n = Math.max(1, Math.min(3, (navigator.hardwareConcurrency || 4) - 3));
    for (let k = 0; k < n; k++) if (!this.spawn()) break;
  }

  /**
   * One worker into the pool; false when none can be made. One that dies (failed to load, ran out of
   * memory) hands its job back and is made again, a few times: the region map had stuck at the one county in
   * memory when its only worker died and nothing replaced it (the user, 22 Oct 2026).
   */
  private spawn(): boolean {
    let w: Worker;
    try { w = new Worker(new URL('./genWorker.ts', import.meta.url), { type: 'module' }); } catch { return false; }
    const slot: Slot = { w, job: null };
    w.onmessage = (e: MessageEvent<GenReply>) => this.receive(slot, e.data);
    w.onerror = (e) => {
      e.preventDefault();
      w.terminate();
      if (!this.pool.includes(slot)) return;
      this.pool = this.pool.filter((q) => q !== slot);
      const edit = slot.job?.edit;
      slot.job = null;
      // its island goes back to the front of the queue
      if (edit && !this.edits.some((q) => q.w === edit.w)) this.edits.unshift(edit);
      if (this.respawns < RESPAWNS) { this.respawns++; this.spawn(); }
      this.pump();
    };
    this.pool.push(slot);
    return true;
  }

  dispose(): void {
    for (const s of this.pool) s.w.terminate();
    this.pool = [];
    this.edits = [];
    this.wanted = [];
    this.cache.clear();
    this.live.clear();
  }

  get(cx: number, cz: number): CellSurvey | undefined { return this.cache.get(key(cx, cz)); }
  has(cx: number, cz: number): boolean { return this.cache.has(key(cx, cz)); }

  /** An island in memory arrived or changed: its survey, edits and all. */
  put(w: World, made?: CellSurvey): void {
    const k = key(w.cx, w.cz);
    this.cache.delete(k);
    this.cache.set(k, made ?? surveyOf(w));
    this.live.add(k);
    this.version++;
    this.trim();
  }

  /**
   * An island in memory changed (a road, a razed lot, a town grown): survey a copy of it in a worker,
   * then put it and hand it to `then`. Done here at once when there are no workers. The survey had
   * been worked out on the main thread, up to 60 ms a time (the lag audit, Oct 2026); the old one
   * stands until the new arrives.
   */
  later(w: World, then?: (s: CellSurvey) => void): void {
    if (!this.made) this.start();
    if (!this.pool.length) { this.edits = this.edits.filter((e) => e.w !== w); this.byHand({ w, then }); return; }
    // the same island twice: only its latest state matters
    this.edits = this.edits.filter((e) => e.w !== w);
    this.edits.push({ w, then });
    this.pump();
  }

  /** The cells wanted now, most wanted first; anything missing is fetched in that order. */
  want(cells: [number, number][]): void { this.wanted = cells; }

  /** A square of cells round (cx, cz), nearest first. */
  static ring(cx: number, cz: number, r: number): [number, number][] {
    const out: [number, number][] = [];
    for (let dz = -r; dz <= r; dz++) for (let dx = -r; dx <= r; dx++) out.push([cx + dx, cz + dz]);
    return out.sort((a, b) => Math.hypot(a[0] - cx, a[1] - cz) - Math.hypot(b[0] - cx, b[1] - cz));
  }

  /** Hand the next wanted cells to whichever workers are free. Call once a frame. */
  pump(): void {
    if (!this.wanted.length && !this.edits.length) return;
    if (!this.made) this.start();
    if (!this.pool.length) { this.pumpByHand(); return; }
    for (const slot of this.pool) {
      if (slot.job) continue;
      // islands in memory that changed go first, but never twice running while the map waits on a county
      const next = this.nextWanted();
      const edit = this.lastEdit && next ? undefined : this.edits.shift();
      this.lastEdit = !!edit;
      if (edit) {
        const id = this.nextId++, w = edit.w;
        // neighbour links are main-thread state and needn't travel (the copy is surveyed alone)
        const copy = { ...w } as unknown as Record<string, unknown>;
        delete copy.nbr;
        try {
          slot.w.postMessage({ id, seed: this.seed, cx: w.cx, cz: w.cz, survey: true, world: copy } satisfies GenRequest);
          slot.job = { id, k: key(w.cx, w.cz), edit };
        } catch {
          // something in it that won't copy: survey it here, as before
          this.byHand(edit);
        }
        continue;
      }
      if (!next) return;
      const id = this.nextId++;
      slot.job = { id, k: key(next[0], next[1]) };
      slot.w.postMessage({ id, seed: this.seed, cx: next[0], cz: next[1], survey: true } satisfies GenRequest);
    }
  }

  /** The most wanted cell not surveyed, not failed and not already out with a worker. */
  private nextWanted(): [number, number] | undefined {
    return this.wanted.find(([x, z]) => {
      const k = key(x, z);
      return !this.cache.has(k) && !this.failed.has(k) && !this.pool.some((q) => q.job?.k === k);
    });
  }

  /** An island in memory surveyed here, on the main thread, and handed on. */
  private byHand(edit: Edit): void {
    this.put(edit.w);
    edit.then?.(this.cache.get(key(edit.w.cx, edit.w.cz))!);
  }

  /**
   * No workers left: the queue is worked through on the main thread instead, a changed island a pump and a
   * wanted county now and then (generating one costs most of a second), so the map still fills.
   */
  private pumpByHand(): void {
    const edit = this.edits.shift();
    if (edit) { this.byHand(edit); return; }
    if (!this.byHandOk || performance.now() - this.byHandAt < BY_HAND_MS) return;
    const next = this.nextWanted();
    if (!next) return;
    const k = key(next[0], next[1]);
    try {
      const s = job('world gen (main thread)', () => surveyOf(generateWorld(this.seed, next[0], next[1])));
      this.cache.set(k, s);
      this.version++;
      this.onSurvey?.(s);
      this.trim();
    } catch {
      this.failed.add(k);
    }
    this.byHandAt = performance.now();
  }

  /** How many wanted cells are still to come. */
  missing(): number { return this.wanted.filter(([x, z]) => !this.cache.has(key(x, z)) && !this.failed.has(key(x, z))).length; }

  /** Every surveyed airport, in world tiles. */
  airports(): KnownAirport[] {
    const out: KnownAirport[] = [];
    for (const s of this.cache.values()) {
      for (const a of s.airports) out.push({ ...a, cx: s.cx, cz: s.cz, gx: s.cx * N + a.x, gz: s.cz * N + a.z, code: airportCode(a.name, s.cx, s.cz) });
    }
    return out;
  }

  private receive(slot: Slot, r: GenReply): void {
    if (!slot.job || slot.job.id !== r.id) return;
    const edit = slot.job.edit;
    slot.job = null;
    const k = key(r.cx, r.cz);
    if (edit) {
      // changed again while it was away: the newer copy is queued and will land after this one
      if (r.survey) { this.put(edit.w, r.survey); edit.then?.(r.survey); }
      else if (!this.edits.some((q) => q.w === edit.w)) this.byHand(edit);
      this.pump();
      return;
    }
    if (r.failed) this.failed.add(k);
    if (!r.survey || this.live.has(k)) { this.pump(); return; }
    this.cache.set(k, r.survey);
    this.version++;
    this.onSurvey?.(r.survey);
    this.trim();
    this.pump();
  }

  /** Forget the oldest surveys past KEEP, keeping whatever is wanted now. */
  private trim(): void {
    if (this.cache.size <= KEEP) return;
    const keep = new Set(this.wanted.map(([x, z]) => key(x, z)));
    for (const k of this.cache.keys()) {
      if (this.cache.size <= KEEP) break;
      if (keep.has(k)) continue;
      this.cache.delete(k);
      this.live.delete(k);
    }
  }
}

/** Words an airport's name ends in that say what it is rather than where. */
const GENERIC = new Set(['international', 'municipal', 'airport', 'airfield', 'regional', 'field']);

/**
 * An airport's three-letter code, like a real one: the first letter of its place name and the next
 * sound in it, then a letter the county draws, so two fields of the same name in different counties
 * still read differently. Always the same for the same airport.
 */
function airportCode(name: string, cx: number, cz: number): string {
  const words = name.toUpperCase().replace(/[^A-Z ]/g, ' ').split(/\s+/).filter((w) => w && !GENERIC.has(w.toLowerCase()) && w !== 'THE');
  const place = words.join('') || 'X';
  const second = place.slice(1).replace(/[AEIOU]/g, '')[0] ?? place[1] ?? 'X';
  let h = Math.imul(cx | 0, 73856093) ^ Math.imul(cz | 0, 19349663);
  for (let k = 0; k < place.length; k++) h = Math.imul(h ^ place.charCodeAt(k), 16777619);
  h ^= h >>> 15;
  return place[0] + second + String.fromCharCode(65 + ((h >>> 0) % 26));
}
