/** A transit operator (0.7.0): a bus authority or a commuter railway, in a county slot of its own (firmSpec.ts TRANSIT). */
export const isTransit = (f: Spec): boolean => f.trade === 'bus' || f.trade === 'rail';
/** What a firm's vehicles are called, for this many of them. */
export function unitWord(f: Spec, n: number): string {
  const one = n === 1;
  return f.trade === 'taxi' ? (one ? 'cab' : 'cabs') : f.trade === 'bus' ? (one ? 'bus' : 'buses') : f.trade === 'rail' ? (one ? 'train' : 'trains') : one ? 'vehicle' : 'vehicles';
}
/** The train set a railway's units are, by the era of its county's line. */
const RAIL_SET: Record<string, string> = { steam: 'kettle', streamline: 'silverComet', modern: 'arrow' };
