const r10 = (v: number) => Math.round(v / 10) * 10;
/** Seconds a newly met firm's beacon stands over its depot, and how near the player has to come to put it out early. */
const BEACON_SECS = 120;
const BEACON_NEAR = 6;
/** A compass word for a step in world tiles (+z is south). */
const compass = (dx: number, dz: number): string =>
  ['east', 'south-east', 'south', 'south-west', 'west', 'north-west', 'north', 'north-east'][((Math.round(Math.atan2(dz, dx) / (Math.PI / 4)) % 8) + 8) % 8];
const cellKey = (cx: number, cz: number): string => `${cx},${cz}`;

// ---- the registry -----------------------------------------------------------------------------------

export class Firms implements FleetBrain {
  readonly firms = new Map<string, Firm>();
  /** County slots whose firm folded: [epoch, day]. */
  folded: Record<string, [number, number]> = {};
  /** County slots whose firm the player bought outright: the day. Never founded again, never adopted online. */
  bought: Record<string, number> = {};
  /** How keen the world's firms are: 0 none, 1 quiet, 2 keen, 3 cut-throat. */
  keen = 2;
  private next = RIVAL_BASE + 1;
  /** County slots looked at in this session whose county had no town fit for a firm, or no building for its depot. */
  private empty = new Set<string>();
  /** Each county's slots and summary, once generated this session (firmSpec.ts slotsFor). */
  private counties = new Map<string, { n: number; village: boolean; sum: CountySummary; transit: number | null }>();
  /** Seconds before another firm may have a title card; firms met meanwhile, for the ticker's roll-call. */
  private cardT = 0;
  private rollCall: Firm[] = [];
  private byUid = new Map<number, { f: Firm; u: FirmUnit }>();
  private defs = new Map<string, VehicleDef>();
  private sweep = 0;
  private sh = 0;
  private shFor = '';
  private poles: THREE.InstancedMesh;
  private flags: THREE.InstancedMesh;
  private m = new THREE.Matrix4();
  /** The light over the depot of the firm met last: a column in its colour, pulsing, for a couple of minutes. */
  private beacon: THREE.Mesh;
  private beaconFor: Firm | null = null;
  private beaconT = 0;

  constructor(private cargo: CargoSystem, private books: Economy, private estate: Estate, private host: FirmsHost, scene: THREE.Scene) {
    const MAX = 256;
    this.poles = new THREE.InstancedMesh(new THREE.BoxGeometry(0.035, 0.46, 0.035).translate(0, 0.23, 0),
      new THREE.MeshLambertMaterial({ color: 0x3b3f44 }), MAX);
    const flag = new THREE.BufferGeometry();
    flag.setAttribute('position', new THREE.Float32BufferAttribute([0.02, 0.46, 0, 0.3, 0.375, 0, 0.02, 0.29, 0], 3));
    flag.computeVertexNormals();
    this.flags = new THREE.InstancedMesh(flag, new THREE.MeshLambertMaterial({ color: 0xffffff, side: THREE.DoubleSide }), MAX);
    this.flags.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(MAX * 3), 3);
    for (const im of [this.poles, this.flags]) { im.count = 0; im.frustumCulled = false; scene.add(im); }
    this.beacon = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.34, 7, 12, 1, true).translate(0, 3.5, 0),
      new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.5, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending }));
    this.beacon.visible = false;
    this.beacon.frustumCulled = false;
    scene.add(this.beacon);

    // the hooks: first refusal on young loads, the player taking a load from under a rival, and the doors
    cargo.refusal = (it) => this.refusalFor(it);
    cargo.onSnatch = (it) => this.snatched(it);
    cargo.onRivalTook = (it, c) => this.took(it, c);
    estate.others = {
      heldBy: (key) => {
        const f = this.ownerOf(key);
        const d = f?.deeds.get(key);
        return f && d ? `Held by ${f.name} since day ${d.day + 1}` : null;
      },
      trade: (key, amount, dir, s) => this.rent(key, amount, dir, s),
      footfall: (key, _a, b) => this.footfall(key, b),
      worn: () => {},
      // a town that trusts the player (docs/standing.html) sells it lots for a tenth less
      discount: (tk) => (books.carriage.rungOf(tk, YOU) >= RUNG.trusted ? CARRIAGE.deeds : 1),
    };
    books.carriage.onChange = (tk, was, now) => this.townTurned(tk, was, now);
  }

  private seedHash(): number {
    const s = this.host.seed();
    if (s !== this.shFor) { this.shFor = s; this.sh = hashString(s); }
    return this.sh;
  }

  private day(): number { return Math.floor(this.host.hours() / 24); }

  /** The firm that holds a door, if one does. */
  ownerOf(key: string): Firm | null {
    for (const f of this.firms.values()) if (f.deeds.has(key)) return f;
    return null;
  }

  /** A firm by id. */
  firm(id: string): Firm | null { return this.firms.get(id) ?? null; }

  /** The firm an agent on the road belongs to, and which of its units it is. */
  of(a: Agent): { f: Firm; u: FirmUnit } | null { return a.firm ? this.byUid.get(a.owner) ?? null : null; }

  /** The firm a claim id (minus a unit's uid) belongs to. */
  private byClaim(c: number): Firm | null { return this.byUid.get(-c)?.f ?? null; }

  // ---- meeting firms ----

  /** What the lattice needs to know about a county in memory: its towns, their standing buildings, their usual trade. */
  static summary(w: World): CountySummary {
    const norm = ECONOMY.norm as Record<string, number>;
    return {
      towns: w.towns.map((t) => ({ kind: t.kind, buildings: t.buildings.reduce((n, b) => n + (!b.gone && b.uid >= 0 ? 1 : 0), 0) })),
      norm: w.towns.reduce((s, t) => s + (norm[t.kind] ?? 0), 0),
      stations: w.stations.filter((st) => st.kind === 'terminus' || st.kind === 'cityStation' || st.kind === 'townStation').length,
    };
  }

  /** A county's slots, worked out the first time it is in memory this session. */
  private county(w: World): { n: number; village: boolean; sum: CountySummary; transit: number | null } {
    const k = cellKey(w.cx, w.cz);
    let c = this.counties.get(k);
    if (!c) {
      const sum = Firms.summary(w);
      // a transit operator only in the 0.7.0 world: 0.6.x's firms are exactly as they were
      const transit = NEXT_WORLD ? transitSlot(this.seedHash(), w.cx, w.cz, sum, this.keen) : null;
      c = { ...countySlots(this.seedHash(), w.cx, w.cz, sum, this.keen), sum, transit };
      this.counties.set(k, c);
    }
    return c;
  }

  /** Firms whose home is this county; a transit operator not among them unless asked for, so it never thins the others' share. */
  private homedIn(cx: number, cz: number, transit = false): Firm[] {
    return [...this.firms.values()].filter((f) => f.home[0] === cx && f.home[1] === cz && (transit || !isTransit(f)));
  }

  /**
   * Look at the counties in memory, nearest the player first: any slot of one with no firm yet has its
   * firm founded and met now. Firms saved from the old lattice take the first slots of their county.
   */
  private discover(): void {
    if (this.host.quiet?.()) return;
    const sh = this.seedHash();
    const me = this.host.playerCell() ?? [0, 0];
    const worlds = this.host.worlds().sort((a, b) =>
      Math.max(Math.abs(a.cx - me[0]), Math.abs(a.cz - me[1])) - Math.max(Math.abs(b.cx - me[0]), Math.abs(b.cz - me[1])));
    for (const w of worlds) {
      const c = this.county(w);
      const here = this.homedIn(w.cx, w.cz);
      const legacy = here.filter((f) => !parseSlotId(f.id)).length;
      const slots = Array.from({ length: Math.max(0, c.n - legacy) }, (_, k) => legacy + k);
      if (c.transit !== null) slots.push(c.transit);
      for (const slot of slots) {
        const id = slotId(w.cx, w.cz, slot);
        if (this.firms.has(id) || this.empty.has(id) || this.bought[id] !== undefined) continue;
        const fold = this.folded[id];
        if (fold && this.day() < fold[1] + FIRMS.succession) continue;
        const spec = specFor(sh, w.cx, w.cz, slot, fold ? fold[0] + 1 : 0, c.village);
        const taken = new Set(this.homedIn(w.cx, w.cz, true).map((g) => g.townKey));
        const f = this.found(spec, w, taken);
        if (!f) { this.empty.add(id); continue; }
        this.firms.set(id, f);
        for (const u of f.units) this.byUid.set(u.uid, { f, u });
        this.host.changed();
      }
    }
  }

  /**
   * The best town in a home county for a firm: the biggest of suburb size or more that no other firm
   * of the county is homed in; for a village start-up, the biggest village.
   */
  private homeTown(w: World, taken: Set<string>, village: boolean, transit = false): Town | null {
    const rank = { rural: 0, suburb: 1, city: 2, metro: 3, mega: 4 } as Record<string, number>;
    // a transit operator is the big city's own, whoever else is homed there
    if (transit) return w.towns.filter((t) => (rank[t.kind] ?? 0) >= 3).sort((a, b) => (rank[b.kind] ?? 0) - (rank[a.kind] ?? 0) || b.size - a.size)[0] ?? null;
    const ok = w.towns.filter((t) => !taken.has(townKey(w, t)) && (village || (rank[t.kind] ?? 0) >= 1))
      .sort((a, b) => ((rank[b.kind] ?? 0) - (rank[a.kind] ?? 0)) || b.size - a.size);
    return ok[0] ?? null;
  }

  /**
   * Most vehicles a firm's board will run: its county's usual trade ÷ perNorm, clamped, shared between
   * the firms homed there; a village start-up stays small.
   */
  private capOf(f: Firm, w: World): number {
    if (f.village) return FIRMS.village;
    if (f.trade === 'rail') return TRANSIT.trains[TRANSIT.trains.length - 1];
    const c = this.county(w);
    // a bus authority runs half the county's ceiling, beside whatever firms it has
    if (f.trade === 'bus') return Math.max(3, Math.round(Math.max(FIRMS.ceilMin, Math.min(FIRMS.ceilMax, Math.round(c.sum.norm / FIRMS.perNorm))) / 2));
    const ceil = Math.max(FIRMS.ceilMin, Math.min(FIRMS.ceilMax, Math.round(c.sum.norm / FIRMS.perNorm)));
    const n = Math.max(1, c.n, this.homedIn(w.cx, w.cz).length);
    return Math.min(FIRMS.maxUnits, Math.max(3, Math.round(ceil / n)));
  }

  /** A building for a depot: a works or depot building in the town, standing, not the player's, with a kerb near. */
  private depotIn(w: World, t: Town, salt: string): { b: Building; x: number; z: number } | null {
    const rng = mulberry32(hashString(`depot|${salt}`));
    // somewhere a fleet can be run from: never scenery (a windmill, a mast), which has no HQ grade
    const fits = (tag: string) => t.buildings.filter((b) => b.solid && !b.gone && !b.derelict && b.uid >= 0 && TAG_OF[b.kind] === tag && gradeOf(b).grade > 0
      && !this.estate.taken(this.estate.keyOf(w, b)) && !this.ownerOf(this.estate.keyOf(w, b)) && !w.ports.some((p) => p.buildings.includes(b)));
    for (const tag of ['depot', 'work', 'shop', 'leisure', 'poi']) {
      const list = fits(tag);
      for (let k = 0; k < 6 && list.length; k++) {
        const b = list.splice(Math.floor(rng() * list.length), 1)[0];
        const kerb = kerbNear(w, b.x + b.w / 2, b.z + b.d / 2, 6);
        if (kerb) return { b, ...kerb };
      }
    }
    return null;
  }

  /** A firm met for the first time: its home town, its depot, and the fleet it has already built up. */
  private found(spec: Spec, w: World, taken: Set<string>): Firm | null {
    const t = this.homeTown(w, taken, !!spec.village, isTransit(spec));
    if (!t) return null;
    const depot = this.depotIn(w, t, spec.salt);
    if (!depot) return null;
    const day = this.day();
    const name = firmName(spec, t.name, isTransit(spec) ? w.name : '');
    const f: Firm = {
      ...spec, name, town: plainName(t), townKey: townKey(w, t),
      depot: this.estate.keyOf(w, depot.b), dx: depot.x, dz: depot.z,
      cash: 0, units: [], deeds: new Map(), founded: day, stage: spec.start, board: day,
      days: [], d0: day, red: 0, towed: 0, tows: 0, snatched: 0, feeds: {}, refused: {}, idleT: 0, outT: 0,
      log: [], met: false, earned: 0, deliveries: 0,
      hq: { key: '', name: '', grade: 0, slots: 0 }, floor: 0,
    };
    // the depot is the firm's from the start, at the price the estate would put on it, and its first HQ
    const q = this.estate.quote(w, depot.b);
    const g0 = gradeOf(depot.b);
    f.hq = { key: f.depot, name: q.name, grade: g0.grade, slots: g0.slots };
    f.deeds.set(f.depot, { key: f.depot, name: q.name, kind: depot.b.kind, townKey: f.townKey, town: f.town, day, paid: q.price, ceil: q.price / ESTATE.ceilingDays, today: 0, d0: day, took: 0 });
    // what it has already built up: two or three, four to six, or eight to ten vehicles
    const rng = mulberry32(hashString(`fleet|${spec.salt}`));
    const n0 = spec.village ? 1 : spec.start === 0 ? 2 + Math.floor(rng() * 2) : spec.start === 1 ? 4 + Math.floor(rng() * 3) : 8 + Math.floor(rng() * 3);
    f.cap = this.capOf(f, w);
    const n = Math.min(n0, f.cap);
    const models = MODELS[spec.trade];
    // a railway's units are the trains it runs on the county's line: they never take the road (launch)
    if (spec.trade === 'rail') {
      const era = w.stations.find((st) => st.kind === 'terminus' || st.kind === 'cityStation')?.era ?? w.stations[0]?.era ?? 'modern';
      for (let k = 0; k < TRANSIT.trains[Math.min(TRANSIT.trains.length - 1, spec.start)]; k++) this.addUnit(f, RAIL_SET[era] ?? 'arrow', this.driverFor(f, k, 1));
    }
    for (let k = 0; k < (spec.trade === 'rail' ? 0 : n); k++) {
      // start-ups run the cheapest thing (a village's one van); bigger firms have a truck or two among them
      const m = spec.village ? 'mule' : spec.trade === 'taxi' ? 'cab' : spec.trade === 'bus' ? 'bus'
        : spec.start >= 2 && k % 4 === 3 ? models[models.length - 1]
          : models[Math.min(models.length - 1, Math.floor(rng() * Math.min(2, models.length)))];
      this.addUnit(f, m, this.driverFor(f, k, rng() < 0.3 ? 1 : 0));
    }
    // a regional firm already holds a couple of doors in its home town
    if (spec.start >= 2) {
      const lots = t.buildings.filter((b) => b.solid && !b.gone && !b.derelict && b.uid >= 0 && TAG_OF[b.kind] && TAG_OF[b.kind] !== 'home'
        && !this.estate.taken(this.estate.keyOf(w, b)) && !f.deeds.has(this.estate.keyOf(w, b)));
      for (let k = 0; k < 2 && lots.length; k++) {
        const b = lots.splice(Math.floor(rng() * lots.length), 1)[0];
        const key = this.estate.keyOf(w, b);
        if (this.ownerOf(key)) continue;
        const bq = this.estate.quote(w, b);
        f.deeds.set(key, { key, name: bq.name, kind: b.kind, townKey: bq.townKey, town: bq.town, day, paid: bq.price, ceil: bq.price / ESTATE.ceilingDays, today: 0, d0: day, took: 0 });
      }
    }
    // a railway's trains were the authority's to begin with: it starts with a float, not a train's price
    f.cash = spec.trade === 'rail' ? 1500 : priceOf(models[0]);
    f.floor = f.units.length;
    f.stage = spec.trade === 'rail' ? spec.start : stageFor(f.units.length);
    this.note(f, `Met · ${f.units.length} ${unitWord(f, f.units.length)} out of ${f.town}`);
    return f;
  }

  /** A driver for a firm's vehicle: a rookie or a regular, named from the firm's salt, at the steady cut. */
  private driverFor(f: Firm, k: number, rank: number): Driver {
    const rng = mulberry32(hashString(`fdriver|${f.salt}|${k}`));
    const tempers: Temper[] = ['careful', 'steady', 'quick'];
    return {
      id: -(k + 1), name: personName(`fdriver|${f.salt}|${k}`), licences: ['road'],
      temper: tempers[Math.floor(rng() * 3)], nose: null, deliveries: [0, 25][rank] ?? 0,
      kept: 0, mood: 0.75, cut: FIRMS.cut, unit: 0,
    };
  }

  private addUnit(f: Firm, model: string, d: Driver, parts?: Parts, uid?: number): FirmUnit {
    const yards = [f.depot, ...[...f.deeds.keys()].filter((k) => k !== f.depot && this.isYard(f, k))];
    const u: FirmUnit = {
      uid: uid ?? this.next++, model, parts: parts ?? { t: {}, spent: 0 }, driver: d,
      yard: yards[f.units.length % yards.length], paid: 0, hours: 0,
    };
    this.next = Math.max(this.next, u.uid + 1);
    d.unit = u.uid;
    f.units.push(u);
    this.byUid.set(u.uid, { f, u });
    return u;
  }

  /** Is a deed of the firm's a yard: a door in another cell it launches vehicles from? */
  private isYard(f: Firm, key: string): boolean {
    return !key.startsWith(`${f.home[0]},${f.home[1]}#`);
  }

  /** Its vehicle's own definition: the model, its parts, and the livery over both. */
  defFor(f: Firm, u: FirmUnit): VehicleDef {
    const key = `${f.id}|${u.model}|${partsKey(u.parts)}`;
    let d = this.defs.get(key);
    if (!d) {
      const base = VEHICLES.find((v) => v.id === u.model) ?? VEHICLES[0];
      const parts: Parts = { ...u.parts, t: { ...u.parts.t, paint: [3, 3] }, c: f.livery[0], a: f.livery[1] };
      d = { ...applyParts(base, parts), livery: f.livery[1] };
      this.defs.set(key, d);
    }
    return d;
  }

  // ---- time ----

  update(dt: number): void {
    if (!this.host.playing() || this.keen <= 0) { this.hideAll(); return; }
    this.cardT = Math.max(0, this.cardT - dt);
    this.poseBeacon(dt);
    this.sweep -= dt;
    if (this.sweep <= 0) {
      this.sweep = 1;
      this.discover();
      this.voidGone();
      this.pennants();
      this.callRoll();
    }
    const hours = this.host.hours(), day = Math.floor(hours / 24), hour = hours - day * 24;
    for (const f of [...this.firms.values()]) {
      const w = this.host.worldAt(f.home[0], f.home[1]);
      const tr = w ? this.host.trafficOf(w) : null;
      // nothing off screen: a firm whose home is not in memory keeps its clock stopped
      if (!w || !tr) continue;
      f.cap ??= this.capOf(f, w);
      if (!f.hq.name && f.hq.key === f.depot) this.hqToDepot(f);
      if (!f.rehomed) this.rehomeScenery(f, w);
      if (!f.met) { f.met = true; if (!this.metAway.has(f.id)) this.meet(f); }
      this.launch(f, dt);
      for (const u of f.units) {
        if (!u.agent) continue;
        f.outT += dt;
        u.hours += dt / SECONDS_PER_HOUR;
        if (u.agent.phase === 'parked' && !u.agent.run) f.idleT += dt;
      }
      if (day > f.board && hour >= FIRMS.boardHour) this.meeting(f, day);
    }
  }

  /**
   * The first time the player has a firm's home county in memory: the paper hears of it. No card and no beacon any more
   * (the user, 5 Nov 2026: "rivals nearby" was noise): a nearby firm is told of when it does something, buying a
   * vehicle or a building or moving its HQ up a grade (act).
   */
  private meet(f: Firm): void {
    // the paper (docs/newspaper.html): a firm at work near the player
    const d0 = this.depotAt(f);
    press.write({ k: 'firmMet', who: f.name, town: f.townKey || undefined, at: d0 ? { x: d0.x, z: d0.z } : undefined, f: { firm: f.name, town: f.town, trade: f.trade } });
  }

  /** The met card as it was, kept for the console (pr.firms): which way the depot lies, and the beacon over it. */
  showMeet(f: Firm): void {
    // with a firm in nearly every county, only the first few and the ones by the HQ get a card
    const before = [...this.firms.values()].filter((g) => g.met && g !== f).length;
    const at0 = this.depotAt(f);
    const hq = this.host.hqKey?.() ? this.estate.resolve(this.host.hqKey!()!) : null;
    const byHq = !!(hq && at0 && Math.hypot(hq.w.ox + hq.b.x - at0.x, hq.w.oz + hq.b.z - at0.z) < FIRMS.hqNear);
    if ((before >= FIRMS.cards && !byHq) || this.cardT > 0) { this.rollCall.push(f); return; }
    this.cardT = FIRMS.cardGap;
    const n = f.units.length;
    const what = `${n} ${unitWord(f, n)}`;
    const at = this.depotAt(f), me = this.host.playerAt();
    let where = 'they were here first';
    if (at && me) {
      const dx = at.x - me[0], dz = at.z - me[1], d = Math.hypot(dx, dz);
      where = d < BEACON_NEAR * 2 ? 'their depot is right here' : `depot ${Math.round(d)} tiles ${compass(dx, dz)} · follow the beacon`;
    }
    this.host.announce(f.name, `${what} out of ${f.town} · ${TRADE_LABEL[f.trade]} · ${where}`, 6000);
    if (at) {
      this.beaconFor = f;
      this.beaconT = BEACON_SECS;
      (this.beacon.material as THREE.MeshBasicMaterial).color.setHex(f.livery[0]);
    }
  }

  /** Firms met without a card: one ticker line naming them all. */
  private callRoll(): void {
    if (!this.rollCall.length) return;
    const names = this.rollCall.map((f) => `${f.name} (${TRADE_LABEL[f.trade]}, ${f.town})`);
    this.rollCall = [];
    this.host.ticker('🚩', names.length === 1 ? 'A rival nearby' : 'Rivals nearby', names.join(' · '));
  }

  /** The top middle of a firm's depot building in world tiles, while its cell is in memory. */
  private depotAt(f: Firm): { x: number; y: number; z: number } | null {
    const r = this.estate.resolve(f.depot);
    if (!r) return null;
    const { w, b } = r;
    const gx = b.x + b.w / 2, gz = b.z + b.d / 2;
    const y = Math.max(b.level * STEP, heightAt(w, Math.min(N - 0.01, gx), Math.min(N - 0.01, gz))) + (b.solid ? buildingHeight(b) : 0);
    return { x: w.ox + gx, y, z: w.oz + gz };
  }

  /** The beacon breathes over the depot until its time is up or the player has driven to it. */
  private poseBeacon(dt: number): void {
    const f = this.beaconFor;
    const at = f && this.beaconT > 0 ? this.depotAt(f) : null;
    const me = this.host.playerAt();
    if (!f || !at || (me && Math.hypot(at.x - me[0], at.z - me[1]) < BEACON_NEAR)) {
      this.beacon.visible = false;
      this.beaconFor = null;
      return;
    }
    this.beaconT -= dt;
    const t = BEACON_SECS - this.beaconT;
    const fade = Math.min(1, this.beaconT / 10);
    this.beacon.position.set(at.x, at.y, at.z);
    this.beacon.scale.set(1 + 0.25 * Math.sin(t * 3), 1, 1 + 0.25 * Math.sin(t * 3));
    (this.beacon.material as THREE.MeshBasicMaterial).opacity = (0.35 + 0.25 * (0.5 + 0.5 * Math.sin(t * 3))) * fade;
    this.beacon.visible = true;
  }

  /**
   * A rival's driver picked up goods waiting near the player: who, over the spot. Not in the notifications
   * as well (the user, 15 Oct 2026): the float is there to see when it happens near you.
   */
  private took(it: CargoItem, claim: number): void {
    const f = this.byClaim(claim);
    if (!f || !f.met) return;
    this.host.float(`Taken · ${f.name}`, it.x, it.y + 0.6, it.z);
  }

  /** Put the firm's idle vehicles on the road, one at a time, at the depot or their yard. */
  private launch(f: Firm, dt: number): void {
    // a railway's trains are on the line, not the road (Trains, railOperator)
    if (f.trade === 'rail') return;
    f.launchT = (f.launchT ?? 0) - dt;
    if (f.launchT > 0) return;
    for (const u of f.units) {
      if (u.agent) continue;
      const at = this.yardSpot(f, u.yard);
      if (!at) continue;
      const tr = this.host.trafficOf(at.w);
      if (!tr) continue;
      const mine = tr.rivalAgents.filter((a) => a.firm === f.id).length;
      const homes = this.homedIn(at.w.cx, at.w.cz).length;
      const cap = FIRMS.cellCaps[Math.min(2, Math.max(homes, this.county(at.w).n))];
      const share = Math.ceil(cap / Math.max(1, homes + (f.home[0] === at.w.cx && f.home[1] === at.w.cz ? 0 : 1)));
      if (mine >= Math.min(FIRMS.onRoad, share) || tr.rivalAgents.length >= cap) continue;
      // out only when there is something out there for it: a unit with nothing to do just parks in the street
      if (!this.workFor(f, at.w, at.x, at.z)) { f.launchT = FIRMS.launchEvery; return; }
      tr.rivals = this;
      const def = this.defFor(f, u);
      const spot = kerbNear(at.w, at.x, at.z, 8, tr.rivalAgents.filter((a) => a.w === at.w).map((a) => ({ x: a.state.x, z: a.state.z }))) ?? at;
      const a = tr.launchOwned(u.uid, def, spot.x, spot.z, Math.random() * Math.PI * 2, null, f.id);
      if (!a) continue;
      u.agent = a;
      u.traffic = tr;
      f.launchT = FIRMS.launchEvery;
      return;
    }
  }

  /** Where a unit launches from: its yard's kerb, in the yard's cell, if that cell is in memory. */
  private yardSpot(f: Firm, key: string): { w: World; x: number; z: number } | null {
    if (key === f.depot || !f.deeds.has(key)) {
      const w = this.host.worldAt(f.home[0], f.home[1]);
      return w ? { w, x: f.dx, z: f.dz } : null;
    }
    const r = this.estate.resolve(key);
    if (!r) return null;
    const k = kerbNear(r.w, r.b.x + r.b.w / 2, r.b.z + r.b.d / 2, 8);
    return k ? { w: r.w, ...k } : null;
  }

  /**
   * A firm founded before depots had to be able to house a fleet may be running from scenery (a windmill):
   * it moves to a proper building in its town, keeping the old one as an ordinary door. Checked once a session.
   */
  private rehomeScenery(f: Firm, w: World): void {
    f.rehomed = true;
    const r = this.estate.resolve(f.depot);
    if (!r || gradeOf(r.b).grade > 0) return;
    const t = w.towns.find((q) => townKey(w, q) === f.townKey);
    const nd = t ? this.depotIn(w, t, `${f.salt}|rehome`) : null;
    if (!nd) return;
    const key = this.estate.keyOf(w, nd.b), q = this.estate.quote(w, nd.b), day = this.day();
    const wasHq = f.hq.key === f.depot;
    f.depot = key; f.dx = nd.x; f.dz = nd.z;
    f.deeds.set(key, { key, name: q.name, kind: nd.b.kind, townKey: f.townKey, town: f.town, day, paid: q.price, ceil: q.price / ESTATE.ceilingDays, today: 0, d0: day, took: 0 });
    if (wasHq) this.hqToDepot(f);
  }

  /** A firm without its HQ runs from its depot again, at the depot's grade. */
  private hqToDepot(f: Firm): void {
    const r = this.estate.resolve(f.depot);
    const g = r ? gradeOf(r.b) : null;
    f.hq = { key: f.depot, name: r ? this.estate.quote(r.w, r.b).name : 'its depot', grade: g?.grade ?? 0, slots: g?.slots ?? 0 };
  }

  /** A building of a firm's that has gone takes its deed with it. */
  private voidGone(): void {
    for (const f of this.firms.values()) {
      for (const key of [...f.deeds.keys()]) {
        const m = /^(-?\d+),(-?\d+)#b(\d+)$/.exec(key);
        if (!m) continue;
        const w = this.host.worldAt(Number(m[1]), Number(m[2]));
        const b = w?.allBuildings[Number(m[3])];
        if (w && (!b || b.gone)) {
          const tk = f.deeds.get(key)?.townKey;
          f.deeds.delete(key);
          this.note(f, `Lost ${key === f.depot ? 'its depot' : key === f.hq.key ? 'its HQ' : 'a door'} to the bulldozer`);
          if (key === f.hq.key && key !== f.depot) this.hqToDepot(f);
          // the bulldozer on a rival's door costs the player a fifth of their standing in that town
          if (tk) this.books.carriage.dent(tk, YOU, 0.2);
        }
      }
    }
  }

  // ---- the board ----

  /** Once a game day: at most one purchase or sale, and the days-in-the-red count. */
  private meeting(f: Firm, day: number): void {
    f.board = day;
    this.rollDays(f);
    // doors it feeds fade, so what it wants is what it has fed lately
    for (const k of Object.keys(f.feeds)) { f.feeds[k] *= FIRMS.feedFade; if (f.feeds[k] < 0.3) delete f.feeds[k]; }
    f.red = f.cash < 0 ? f.red + 1 : 0;
    const idle = f.outT > 0 ? f.idleT / f.outT : 0;
    const d = this.decide(f, idle);
    f.idleT = 0; f.outT = 0; f.refused = {};
    if (d) this.act(f, d);
    if (f.trade !== 'rail') f.stage = stageFor(f.units.length);
    if (f.units.length === 0 && f.red >= FIRMS.foldAfter) this.fold(f);
    this.host.changed();
  }

  /** What a firm will not spend below. */
  reserve(f: Firm): number {
    const days = Math.max(1, this.day() - f.founded);
    return Math.max(FIRMS.reserveMin, (FIRMS.reserveDays[this.keen] ?? 2) * (f.towed / days));
  }

  /** The board's one decision today, or null to keep the money. */
  decide(f: Firm, idle: number): Decision | null {
    // a railway's board runs the trains it has: it buys nothing and sells nothing
    if (f.trade === 'rail') return null;
    const spare = f.cash - this.reserve(f);
    const rateOf = (u: FirmUnit) => (u.hours >= 0.5 ? u.paid / u.hours : 0);
    // 1. in the red: sell the worst earner, then a door
    if (f.red >= FIRMS.sellAfter) {
      const worst = [...f.units].sort((a, b) => rateOf(a) - rateOf(b))[0];
      if (worst) return { sell: 'vehicle', uid: worst.uid };
      const door = [...f.deeds.keys()].find((k) => k !== f.depot && k !== f.hq.key);
      if (door) return { sell: 'deed', key: door };
      return null;
    }
    const want = this.wantedModel(f);
    const room = this.roomOf(f);
    // at its HQ's slots with the county's trade to grow into: a grander HQ first (docs/hq.html)
    const buyHq = (): Decision | null => {
      if (!want || idle > FIRMS.busy || f.units.length < room || room >= (f.cap ?? FIRMS.maxUnits)) return null;
      const t = this.hqWanted(f);
      return t && spare >= t.price ? { buy: 'hq', key: t.key, price: t.price } : null;
    };
    const buyVehicle = (): Decision | null => {
      if (!want || f.units.length >= room || idle > FIRMS.busy) return null;
      // most of it standing in the depot for want of road room: another would only stand with them
      if (f.outT > 60 && f.units.filter((u) => !u.agent).length > f.units.length * FIRMS.benched) return null;
      const cost = priceOf(want) + 300;
      return spare >= cost ? { buy: 'vehicle', model: want } : null;
    };
    const buyPart = (): Decision | null => {
      const best = [...f.units].sort((a, b) => rateOf(b) - rateOf(a))[0];
      if (!best) return null;
      const def = VEHICLES.find((v) => v.id === best.model);
      if (!def) return null;
      const slots = slotsFor(def).map((s) => s.id);
      const order: SlotId[] = f.trade === 'taxi' ? ['engine', 'brakes', 'rack'] : ['rack', 'engine', 'brakes'];
      for (const slot of order) {
        if (!slots.includes(slot)) continue;
        const tier = owned(best.parts, slot) + 1;
        if (tier > 3) continue;
        const cost = owedFor(def, best.parts, slot, tier);
        if (cost > 0 && spare >= cost) return { buy: 'part', uid: best.uid, slot, tier };
      }
      return null;
    };
    const buyDoor = (): Decision | null => {
      const q = this.doorWanted(f);
      if (!q) return null;
      const ok = q.word === 'A bargain' || q.word === 'Fair' || (f.bent === 'landlord' && q.word === 'Steep');
      return ok && spare >= q.price ? { buy: 'deed', key: q.key, price: q.price } : null;
    };
    const steps = f.bent === 'landlord' ? [buyDoor, buyHq, buyVehicle, buyPart]
      : f.bent === 'courtier' ? [buyHq, buyVehicle, buyDoor, buyPart]
        : [buyHq, buyVehicle, buyPart, buyDoor];
    for (const s of steps) {
      const d = s();
      if (d) return d;
    }
    // too many vehicles for the work in reach: sell one that earns nothing
    if (idle > FIRMS.glut && f.units.length > 2) {
      const lazy = f.units.find((u) => u.hours > 12 && rateOf(u) < 0.5);
      if (lazy) return { sell: 'vehicle', uid: lazy.uid };
    }
    return null;
  }

  /** Most vehicles the firm runs: its HQ's slots (or the fleet it had when met), within its county's share. */
  roomOf(f: Firm): number {
    return Math.min(f.cap ?? FIRMS.maxUnits, Math.max(f.hq.slots, f.floor));
  }

  /**
   * The HQ the firm would move to: a building in its home cell that opens more slots than it has, the
   * least grand of those first and the cheapest among them. One it already holds costs nothing.
   */
  private hqWanted(f: Firm): { key: string; price: number } | null {
    const w = this.host.worldAt(f.home[0], f.home[1]);
    if (!w) return null;
    const have = this.roomOf(f);
    let best: { key: string; price: number; slots: number } | null = null;
    for (const b of w.allBuildings) {
      if (b.gone || b.derelict || b.uid < 0 || !b.solid) continue;
      const g = gradeOf(b);
      if (!g.grade || g.slots <= have || (best && g.slots > best.slots)) continue;
      const key = this.estate.keyOf(w, b);
      if (key.includes('#p') || this.estate.taken(key)) continue;
      const other = this.ownerOf(key);
      if (other && other !== f) continue;
      const price = other === f ? 0 : this.quote(f, w, b).price;
      if (!best || g.slots < best.slots || price < best.price) best = { key, price, slots: g.slots };
    }
    return best;
  }

  /** The vehicle the firm would buy next: the cheapest of its trade that takes what it had to refuse, or its commonest. */
  private wantedModel(f: Firm): string | null {
    const models = MODELS[f.trade];
    const refused = Object.entries(f.refused).sort((a, b) => (b[1] ?? 0) - (a[1] ?? 0));
    for (const [cls] of refused) {
      const fit = models.map((m) => VEHICLES.find((v) => v.id === m)!).filter((d) => d && d.holds.includes(cls as CargoClass))
        .sort((a, b) => priceOf(a.id) - priceOf(b.id))[0];
      if (fit) return fit.id;
    }
    const count = new Map<string, number>();
    for (const u of f.units) count.set(u.model, (count.get(u.model) ?? 0) + 1);
    // a regional firm steps up to its biggest model now and then
    if (f.stage >= 2 && models.length > 1 && !f.units.some((u) => u.model === models[models.length - 1])) return models[models.length - 1];
    return [...count].sort((a, b) => b[1] - a[1])[0]?.[0] ?? models[0];
  }

  /** The door the firm wants most: the one its loads go through most that it does not hold and may buy. */
  private doorWanted(f: Firm): (FirmQuote & { key: string }) | null {
    const fed = Object.entries(f.feeds).sort((a, b) => b[1] - a[1]).slice(0, 6);
    for (const [key] of fed) {
      if (f.deeds.has(key) || this.estate.taken(key) || this.ownerOf(key)) continue;
      const r = this.estate.resolve(key);
      if (!r || (!r.port && r.b.derelict)) continue;
      const q = this.quote(f, r.w, r.b);
      if (!q.townKey || this.books.carriage.shareOf(q.townKey, f.id) < FIRMS.buyIn) continue;
      // a courtier only buys where it is courting or preferred
      if (f.bent === 'courtier' && this.books.carriage.shareOf(q.townKey, f.id) < 0.2) continue;
      return { ...q, key };
    }
    return null;
  }

  /** What a lot costs this firm: the estate's price, with its own holding premium and a tenth off where the town trusts it. */
  quote(f: Firm, w: World, b: Building): FirmQuote {
    const q = this.estate.quote(w, b);
    const all = q.harbour ? q.harbour.buildings.filter((x) => !x.gone) : [b];
    const floor = all.reduce((s, x) => s + lotFloor(x), 0);
    const r = this.books.report(w, b);
    const kind = r.town && r.via === 'town' ? r.town.kind : null;
    let held = 0;
    for (const d of f.deeds.values()) if (d.townKey === q.townKey) held++;
    const off = q.townKey && this.books.carriage.rungOf(q.townKey, f.id) >= RUNG.trusted ? CARRIAGE.deeds : 1;
    const byTrade = Math.max(100, Math.round((lotPrice(q.rate, floor, kind, q.derelict, held) * off) / 100) * 100);
    // the prestige floor (docs/hq.html) holds for a firm as for the player
    const price = Math.max(byTrade, prestigeFloor(gradeOf(b, !!q.harbour), kind ? ESTATE.town[kind] : ESTATE.country, holdingMul(held)));
    const days = q.perDay > 0.05 ? price / q.perDay : Infinity;
    return { name: q.name, town: q.town, townKey: q.townKey, price, word: paybackWord(days), kind: q.harbour ? 'harbour' : b.kind };
  }

  private act(f: Firm, d: Decision): void {
    const day = this.day();
    if ('buy' in d) {
      if (d.buy === 'vehicle') {
        const drv = this.driverFor(f, f.units.length + f.log.length + 7, Math.random() < 0.3 ? 1 : 0);
        const cost = priceOf(d.model) + feeOf(drv);
        if (f.cash < cost) return;
        f.cash -= cost;
        this.addUnit(f, d.model, drv);
        const def = VEHICLES.find((v) => v.id === d.model);
        this.note(f, `Bought a ${def?.name ?? d.model}, ${money(cost)} with its driver`);
        if (f.met) {
          press.write({ k: 'board', v: 'buy', who: f.name, town: f.townKey || undefined, f: { firm: f.name, model: def?.name ?? d.model, price: cost } });
          // a firm acts only while its home is in memory: always one near the player
          this.host.ticker('🚚', f.name, `bought a ${def?.name ?? d.model} · ${f.units.length} vehicle${f.units.length === 1 ? '' : 's'} now · out of ${f.town}`);
        }
      } else if (d.buy === 'part') {
        const hit = this.byUid.get(d.uid);
        const def = hit && VEHICLES.find((v) => v.id === hit.u.model);
        if (!hit || !def) return;
        const cost = owedFor(def, hit.u.parts, d.slot, d.tier);
        if (f.cash < cost) return;
        f.cash -= cost;
        const p = hit.u.parts;
        p.t[d.slot] = [d.tier, d.tier];
        p.spent = (p.spent ?? 0) + cost;
        // it drives on in the new body next time it comes out
        this.remeshUnit(f, hit.u);
        this.note(f, `Fitted ${d.slot} ${d.tier} to a ${def.name}, ${money(cost)}`);
        if (f.met) press.write({ k: 'board', v: 'fit', who: f.name, town: f.townKey || undefined, f: { firm: f.name, model: def.name, slot: d.slot, tier: d.tier } });
      } else if (d.buy === 'hq') {
        const r = this.estate.resolve(d.key);
        if (!r || this.estate.taken(d.key)) return;
        const other = this.ownerOf(d.key);
        if (other && other !== f) return;
        const q = this.quote(f, r.w, r.b);
        if (!other) {
          if (f.cash < q.price) return;
          f.cash -= q.price;
          f.deeds.set(d.key, { key: d.key, name: q.name, kind: q.kind, townKey: q.townKey, town: q.town, day, paid: q.price, ceil: q.price / ESTATE.ceilingDays, today: 0, d0: day, took: 0 });
        }
        const g = gradeOf(r.b);
        const was = f.hq.grade ?? 0;
        f.hq = { key: d.key, name: q.name, grade: g.grade, slots: g.slots };
        this.note(f, `Moved its HQ to ${q.name}${q.town && q.town !== q.name ? `, ${q.town}` : ''} · ${g.name}, ${g.slots} vehicles${other ? '' : ` · ${money(q.price)}`}`);
        if (f.met) {
          this.host.ticker('🏢', f.name, `${g.grade > was ? 'upgraded its HQ' : 'moved its HQ'} to ${q.name}${q.town ? ` in ${q.town}` : ''} · ${gradePips(g.grade)} ${g.slots} vehicles`);
          press.write({ k: 'hq', who: f.name, town: q.townKey || undefined, at: { x: r.w.ox + r.b.x + r.b.w / 2, z: r.w.oz + r.b.z + r.b.d / 2 }, f: { firm: f.name, building: plain(q.name), town: q.town, grade: gradeWords(g.name), slots: g.slots } });
        }
      } else {
        const r = this.estate.resolve(d.key);
        if (!r || this.estate.taken(d.key) || this.ownerOf(d.key) || f.cash < d.price) return;
        const q = this.quote(f, r.w, r.b);
        f.cash -= q.price;
        f.deeds.set(d.key, { key: d.key, name: q.name, kind: q.kind, townKey: q.townKey, town: q.town, day, paid: q.price, ceil: q.price / ESTATE.ceilingDays, today: 0, d0: day, took: 0 });
        this.note(f, `Bought ${q.name}${q.town && q.town !== q.name ? `, ${q.town}` : ''}, ${money(q.price)}`);
        if (f.met) press.write({ k: 'deedBought', who: f.name, town: q.townKey || undefined, at: { x: r.w.ox + r.b.x + r.b.w / 2, z: r.w.oz + r.b.z + r.b.d / 2 }, f: { firm: f.name, building: plain(q.name), town: q.town, price: q.price } });
        if (f.met) this.host.ticker('🏷️', f.name, `bought ${q.name}${q.town && q.town !== q.name ? ` in ${q.town}` : ''} · ${money(q.price)}`);
      }
      return;
    }
    if (d.sell === 'vehicle') {
      const hit = this.byUid.get(d.uid);
      if (!hit) return;
      this.pullUnit(hit.u);
      f.units = f.units.filter((u) => u !== hit.u);
      this.byUid.delete(d.uid);
      const back = r10(priceOf(hit.u.model) * 0.6 + (hit.u.parts.spent ?? 0) * 0.4);
      f.cash += back;
      this.note(f, `Sold a ${VEHICLES.find((v) => v.id === hit.u.model)?.name ?? hit.u.model}, ${money(back)}`);
      if (f.met) press.write({ k: 'board', v: 'sell', who: f.name, town: f.townKey || undefined, f: { firm: f.name, model: VEHICLES.find((v) => v.id === hit.u.model)?.name ?? hit.u.model, price: back } });
    } else {
      const deed = f.deeds.get(d.key);
      if (!deed) return;
      f.deeds.delete(d.key);
      const back = r10(deed.paid * ESTATE.sell);
      f.cash += back;
      this.note(f, `Sold ${deed.name}, ${money(back)}`);
      if (f.met) press.write({ k: 'board', v: 'sellDoor', who: f.name, town: deed.townKey || undefined, f: { firm: f.name, building: plain(deed.name), price: back } });
    }
  }

  /** Take a unit off the road now, whatever it was doing: its loads go back on the kerb. */
  private pullUnit(u: FirmUnit): void {
    const a = u.agent, tr = u.traffic;
    if (!a || !tr) return;
    this.dropLoads(a);
    tr.dropOwned(a);
    u.agent = null;
    u.traffic = null;
  }

  private remeshUnit(f: Firm, u: FirmUnit): void {
    if (u.agent && u.traffic) u.traffic.remesh(u.agent, this.defFor(f, u));
  }

  /** A firm with nothing left: its doors go back on the market and its county slot waits for a new one. */
  private fold(f: Firm): void {
    this.firms.delete(f.id);
    for (const u of f.units) { this.pullUnit(u); this.byUid.delete(u.uid); }
    this.folded[f.id] = [f.epoch, this.day()];
    this.books.carriage.forget(f.id);
    this.host.ticker('📉', f.name, 'have ceased trading · their doors are for sale');
    if (f.met) press.write({ k: 'firmCeased', who: f.name, town: f.townKey || undefined, f: { firm: f.name, town: f.town } });
    this.host.announce(f.name, 'have ceased trading');
    this.host.changed();
  }

  // ---- bought out by the player (game/buyout.ts) ----

  /** What the firm is worth, as Standings counts it (game/metrics.ts): cash, its vehicles' and its doors' resale. */
  worth(f: Firm): { worth: number; assets: number } {
    let assets = 0;
    for (const u of f.units) assets += r10(priceOf(u.model) * RESALE + (u.parts.spent ?? 0) * PARTS_RESALE);
    for (const d of f.deeds.values()) assets += r10(d.paid * ESTATE.sell);
    return { worth: Math.round(f.cash + assets), assets };
  }

  /** The player has bought one of the firm's doors for `price`: the deed is theirs, the money in the firm's bank. */
  sellDoor(f: Firm, key: string, price: number): void {
    const d = f.deeds.get(key);
    if (!d) return;
    f.deeds.delete(key);
    f.cash += price;
    delete f.feeds[key];
    for (const u of f.units) if (u.yard === key) u.yard = f.depot;
    this.note(f, `Sold ${d.name} to ${this.carrierName(YOU)}, ${money(price)}`);
    this.host.changed();
  }

  /**
   * The player has bought the whole firm: off the road and out of the registry for good, its towns'
   * carriage forgotten, and its county slot marked so no firm is ever founded in its place.
   * What it had, for the buyer to take over.
   */
  sellOut(f: Firm): { units: FirmUnit[]; deeds: string[] } {
    for (const u of f.units) { this.pullUnit(u); this.byUid.delete(u.uid); }
    this.firms.delete(f.id);
    this.bought[f.id] = this.day();
    delete this.folded[f.id];
    this.books.carriage.forget(f.id);
    if (this.beaconFor === f) { this.beaconFor = null; this.beacon.visible = false; }
    this.rollCall = this.rollCall.filter((g) => g !== f);
    this.host.changed();
    return { units: f.units, deeds: [...f.deeds.keys()] };
  }

  private note(f: Firm, what: string): void {
    f.log.unshift([this.day(), what]);
    if (f.log.length > 40) f.log.length = 40;
  }

  private rollDays(f: Firm): void {
    const today = this.day();
    if (today > f.d0) {
      for (let k = 0; k < Math.min(14, today - f.d0); k++) f.days.unshift(0);
      f.days.length = Math.min(f.days.length, 14);
      f.d0 = today;
    }
    if (!f.days.length) f.days.push(0);
  }

  private earn(f: Firm, v: number): void {
    f.cash += v;
    f.earned += v;
    this.rollDays(f);
    f.days[0] += v;
  }

  // ---- doors ----

  /** A delivery at a door a firm holds: it takes its share as the player would, under the same ceiling and levy. */
  private rent(key: string, amount: number, _dir: 'in' | 'out', s: Site): void {
    const f = this.ownerOf(key);
    const d = f?.deeds.get(key);
    if (!f || !d || s.b?.derelict) return;
    const day = this.day();
    if (d.d0 !== day) { d.d0 = day; d.today = 0; }
    const gross = Math.min(Math.round(amount * ESTATE.yield), Math.floor(d.ceil - d.today));
    if (gross <= 0) return;
    const levy = Math.round((gross * this.books.levyAt(s, f.id)) / 100);
    d.today += gross;
    d.took += gross - levy;
    this.earn(f, gross - levy);
    this.books.rentShare(d.townKey, f.id, gross);
  }

  private footfall(key: string, b: Building): void {
    const f = this.ownerOf(key);
    const d = f?.deeds.get(key);
    if (!f || !d || b.derelict) return;
    const fee = Math.min(ESTATE.footfall[TAG_OF[b.kind] ?? 'home'] ?? 1, Math.floor(d.ceil - d.today));
    if (fee <= 0) return;
    d.today += fee;
    d.took += fee;
    this.earn(f, fee);
  }

  // ---- towns ----

  /** First refusal: a young load in a town that prefers some carrier is held for that carrier. */
  private refusalFor(it: CargoItem): string {
    if (this.cargo.ageOf(it) > CARRIAGE.refusal) return '';
    const tk = this.books.townKeyOf(it.from);
    return tk ? this.books.carriage.preferred(tk) : '';
  }

  /** The name of a carrier: 'You', a firm's name, or 'Nobody'. */
  carrierName(who: string): string {
    return who === YOU ? playerBrand.current?.name ?? 'You' : this.firms.get(who)?.name ?? this.metAway.get(who)?.[0] ?? OTHERS.name(who) ?? (who ? 'A firm long gone' : 'Nobody');
  }
  carrierColour(who: string): number { return who === YOU ? playerBrand.current?.primary ?? 0xe2412f : this.firms.get(who)?.livery[0] ?? this.metAway.get(who)?.[1] ?? OTHERS.colour(who) ?? 0x9aa6ad; }

  /** A town has changed its preferred carrier: news, when it touches the player or a town in memory. */
  private townTurned(tk: string, was: string, now: string): void {
    if (!this.host.playing()) return;
    const [cell] = tk.split('#');
    const [cx, cz] = cell.split(',').map(Number);
    const w = this.host.worldAt(cx, cz);
    const t = w?.towns[Number(tk.split('#')[1])];
    if (!t) return;
    const town = plainName(t);
    // a town your drivers won while you were elsewhere: say where it is, and put it on the maps
    const gx = w!.ox + t.x0 + t.size / 2, gz = w!.oz + t.z0 + t.size / 2;
    const me = this.host.playerAt();
    const d = me ? Math.hypot(gx - me[0], gz - me[1]) : 0;
    const where = !me || d < t.size / 2 + 20 ? 'here' : `${Math.round(d)} tiles ${compass(gx - me[0], gz - me[1])}`;
    // the player's own wins and losses are territory's news (game/territory.ts): one card, near or far
    if (now === YOU) {
      this.host.reveal?.(gx, gz, t.size / 2 + 12);
      if (where !== 'here') this.host.ticker('🏛️', town, `is your territory now (${where})`, 'Territory');
    }
    else if (now && was !== YOU) this.host.ticker('🏛️', town, `is ${this.carrierName(now)}’s territory now`, 'Territory');
    const firm = now && now !== YOU ? this.firms.get(now) : undefined;
    if (firm) press.write({ k: 'territoryWon', who: firm.name, town: tk, at: { x: gx, z: gz }, f: { firm: firm.name, town } });
    this.host.changed();
  }

  /** The player loaded goods a rival's driver was on the way for. */
  private snatched(it: CargoItem): void {
    const f = this.byClaim(it.claimedBy);
    if (!f) return;
    f.snatched++;
    this.host.ticker('😏', 'Beat them to it', `${it.type.icon} ${it.type.name} · ${f.name} were on their way`);
  }

  // ---- pennants ----

  /** Pennants in the firm's colour on every door of a firm's in memory, and on every town hall that prefers someone. */
  private pennants(): void {
    let n = 0;
    const max = this.poles.instanceMatrix.count;
    const col = new THREE.Color();
    const at = new THREE.Vector3();
    roofBudget(6);
    const put = (w: World, b: Building, colour: number) => {
      if (n >= max) return;
      // stood on the building's own roof (render/roofTop.ts)
      if (!pennantAt(w, b, 'ne', at)) return;
      this.m.makeTranslation(at.x, at.y, at.z);
      this.poles.setMatrixAt(n, this.m);
      this.flags.setMatrixAt(n, this.m);
      this.flags.setColorAt(n, col.setHex(colour));
      n++;
    };
    for (const f of this.firms.values()) {
      for (const key of f.deeds.keys()) {
        const r = this.estate.resolve(key);
        if (r) put(r.w, r.b, f.livery[0]);
      }
    }
    for (const w of this.host.worlds()) {
      for (const t of w.towns) {
        const who = this.books.carriage.preferred(townKey(w, t));
        if (!who) continue;
        const hall = t.buildings.find((b) => b.kind === 'cityHall' && !b.gone) ?? t.buildings.find((b) => TAG_OF[b.kind] === 'work' && b.solid && !b.gone);
        if (hall) put(w, hall, this.carrierColour(who));
      }
    }
    this.poles.count = this.flags.count = n;
    this.poles.instanceMatrix.needsUpdate = this.flags.instanceMatrix.needsUpdate = true;
    if (this.flags.instanceColor) this.flags.instanceColor.needsUpdate = true;
  }

  private hideAll(): void { this.poles.count = this.flags.count = 0; this.beacon.visible = false; }

  // ---- FleetBrain: what traffic asks about a firm's vehicle ----

  private order(f: Firm): Order {
    const fares = f.trade === 'taxi' || f.trade === 'bus';
    const o = preset(fares ? 'passengers' : 'anything', null);
    o.takes = [...TAKES[f.trade]];
    o.floor = 'none';
    o.range = 'near';
    o.cross = fares ? 'no' : 'yes';
    o.pack = 'some';
    return o;
  }

  manifest(a: Agent, pace: number, ok: (it: CargoItem) => boolean, run: Run | null): Manifest | null {
    const o = this.of(a);
    if (!o) return null;
    const { f, u } = o;
    const d = u.driver, order = this.order(f);
    const here = { x: a.w.ox + a.state.x, z: a.w.oz + a.state.z };
    const rest = run ? run.stops.slice(run.k) : [];
    const inRun = new Set(rest.map((s) => s.item)).size;
    const room = this.cargo.firmRoom(a.w);
    const maxLoads = Math.min(packOf(d, order), run ? inRun + (room > 0 ? 1 : 0) : Math.max(room > 0 ? 1 : 0, room));
    if (maxLoads <= inRun) return null;
    const from = rest.length ? stopAt(rest[rest.length - 1]) : here;
    // (a plant's made load held for the player's fleet is never a rival's: docs/supplychains.html)
    const jobs = this.cargo.items.filter((it) => !it.claimedBy && !it.type.heli && !it.type.jet && !it.type.sub && !it.type.ultra && !it.type.self && !(it.made && it.for) && it.ttl > 20 && !this.cargo.refused(it, f.id));
    // what it had to pass over for want of a vehicle that could take it: the board's shopping list
    const takes = TAKES[f.trade];
    for (const it of jobs) {
      if (Math.hypot(it.x - here.x, it.z - here.z) > 40 || (takes.length && !takes.includes(it.type.cls))) continue;
      if (!f.units.some((q) => canHaul(this.defFor(f, q), it))) f.refused[it.type.cls] = (f.refused[it.type.cls] ?? 0) + 1;
    }
    const tax = (it: CargoItem) => this.books.taxOf(it, f.id);
    let picked = pickJobs(order, d, a.def, jobs, from, { cx: f.home[0], cz: f.home[1] }, tax, canHaul);
    if (!picked.length) return null;
    // its own doors first (twice as keen, three times for both ends), and the towns it is courting
    const ends = (it: CargoItem) => (this.doorOf(it.from) && f.deeds.has(this.doorOf(it.from)!) ? 1 : 0) + (f.deeds.has(this.doorOf(it.to) ?? '') ? 1 : 0);
    const courting = (it: CargoItem) => {
      const tk = this.books.townKeyOf(it.to);
      if (!tk) return 1;
      const s = this.books.carriage.shareOf(tk, f.id);
      const pref = this.books.carriage.preferred(tk) === f.id;
      return pref ? 0.8 : s >= 0.2 && s <= 0.45 ? (f.bent === 'courtier' ? 2 : 1.5) : 1;
    };
    const n = picked.length;
    picked = picked.map((it, i) => ({ it, s: (n - i) * [1, 2, 3][ends(it)] * courting(it) })).sort((x, y) => y.s - x.s).map((e) => e.it);
    const byId = new Map<number, CargoItem>();
    for (const it of [...rest.map((s) => s.item), ...picked]) byId.set(it.id, it);
    const aboard = new Set(run?.aboard ?? []);
    const calls: Call[] = rest.map((s) => ({ kind: s.kind, load: this.loadOf(s.item, aboard.has(s.item), tax(s.item)) }));
    const plan = solveRun(here, calls, picked.map((it) => this.loadOf(it, false, tax(it))),
      { capacity: a.def.capacity, used: run?.used ?? 0, maxLoads, pace, cut: d.cut },
      { ok: (l) => ok(byId.get(l.id)!), tail: !!run });
    if (!plan || (run && plan.calls.length === rest.length)) return null;
    const stops: Stop[] = plan.calls.map((c, k) => ({ kind: c.kind, item: byId.get(c.load.id)!, held: plan.held[k], pays: Math.round(plan.pays[k]) }));
    return { stops, tiles: plan.tiles, seconds: plan.seconds, eta: plan.eta };
  }

  private loadOf(it: CargoItem, aboard: boolean, tax: number): Load {
    return {
      id: it.id, px: it.x, pz: it.z, dx: it.to.x, dz: it.to.z, units: it.type.units,
      value: it.value, value0: it.value0, decay: URGENCY[it.urgency].decay, tax, ttl: it.ttl, aboard,
    };
  }

  /** The deed key of a cargo site's door, as the ledger keys its books. */
  private doorOf(s: Site | null): string | null {
    if (!s) return null;
    if (s.port >= 0) return `${s.w.cx},${s.w.cz}#p${s.port}`;
    return s.b && s.b.uid >= 0 ? `${s.w.cx},${s.w.cz}#b${s.b.uid}` : null;
  }

  claimed(a: Agent, it: CargoItem): void {
    const o = this.of(a);
    if (o) it.claimName = `${o.f.name} · ${o.u.driver.name}`;
  }

  delivered(a: Agent, it: CargoItem): void {
    const o = this.of(a);
    if (!o) return;
    const { f, u } = o;
    const at = { x: a.w.ox + a.state.x, y: a.state.y, z: a.w.oz + a.state.z };
    const net = this.cargo.deliverFirm(it, at, f.id, f.name);
    const share = Math.round(net * FIRMS.cut);
    this.earn(f, share);
    f.deliveries++;
    u.paid += share;
    u.driver.deliveries++;
    u.driver.kept += net - share;
    for (const s of [it.from, it.to]) {
      const k = this.doorOf(s);
      if (k) f.feeds[k] = (f.feeds[k] ?? 0) + 1;
    }
  }

  setDown(a: Agent, it: CargoItem): void {
    const k = kerbNear(a.w, a.state.x, a.state.z, 14) ?? { x: Math.min(N - 0.5, Math.max(0.5, a.state.x)), z: Math.min(N - 0.5, Math.max(0.5, a.state.z)) };
    this.cargo.setDown(it, a.w, k.x, k.z, a.state.y);
  }

  runDone(): void {}

  tops(a: Agent): boolean {
    const o = this.of(a);
    return !!o && rankOf(o.u.driver) === 'ace';
  }

  stuck(a: Agent): 'retry' | 'tow' {
    const o = this.of(a);
    if (!o) return 'tow';
    if (rankOf(o.u.driver) === 'ace') return 'retry';
    const sorts = o.u.driver.temper === 'careful' ? 0.5 : o.u.driver.temper === 'steady' ? 0.25 : 0;
    return Math.random() < sorts ? 'retry' : 'tow';
  }

  base(a: Agent): { x: number; z: number; cx: number; cz: number } | null {
    const o = this.of(a);
    if (!o) return null;
    const w = this.host.worldAt(o.f.home[0], o.f.home[1]);
    return w ? { x: w.ox + o.f.dx, z: w.oz + o.f.dz, cx: w.cx, cz: w.cz } : null;
  }

  pace(a: Agent): number {
    const o = this.of(a);
    if (!o) return 1;
    return TEMPER[o.u.driver.temper].pace + MODES.steady.pace + 0.04 * rankIndex(o.u.driver);
  }

  /** A rival's driver uses the parts on their vehicle on the same terms as the player's. */
  tricks(a: Agent): { nitrous: boolean; drift: boolean } {
    const o = this.of(a);
    return o ? tricksOf(o.u.driver) : { nitrous: false, drift: false };
  }

  idleLimit(): number { return MODES.steady.idle * SECONDS_PER_HOUR; }

  /**
   * A rival's unit with nothing to do goes indoors rather than stand in the street: at once at its depot,
   * and after half a minute anywhere else (it has asked for work a couple of times by then). launch puts it
   * back out when there is a load it could take.
   */
  parkAway(a: Agent, atBase: boolean): boolean {
    if (!this.of(a)) return false;
    return atBase || a.idle > PARK_AWAY_S;
  }

  /** Is there a load near this spot that the firm takes, that one of its vehicles can carry, with room on the cell's board for rivals? */
  private workFor(f: Firm, w: World, x: number, z: number): boolean {
    if (this.cargo.firmRoom(w) <= 0) return false;
    const takes = TAKES[f.trade];
    const gx = w.ox + x, gz = w.oz + z;
    return this.cargo.items.some((it) => !it.claimedBy && !it.type.heli && !it.type.jet && !it.type.sub && !(it.made && it.for) && it.ttl > 20
      && (!takes.length || takes.includes(it.type.cls)) && Math.hypot(it.x - gx, it.z - gz) < WORK_REACH
      && !this.cargo.refused(it, f.id) && f.units.some((q) => canHaul(this.defFor(f, q), it)));
  }
  waiting(): boolean { return false; }
  quits(): boolean { return false; }

  /** Loads aboard go back on the kerb where it stands, and goods it was going for are let go. */
  private dropLoads(a: Agent): void {
    const run = a.run;
    if (!run) return;
    for (const it of pending(run)) this.cargo.release(it, -a.owner);
    for (const it of run.aboard) this.setDown(a, it);
    run.aboard = [];
  }

  suspend(a: Agent): void {
    const o = this.of(a);
    this.dropLoads(a);
    if (!o) return;
    o.u.agent = null;
    o.u.traffic = null;
  }

  released(a: Agent, why: 'quit' | 'tow', reason = 'gave up'): void {
    const o = this.of(a);
    if (!o) return;
    const { f, u } = o;
    const tr = u.traffic;
    if (!tr) return;
    const w = this.host.worldAt(f.home[0], f.home[1]);
    const gx = a.w.ox + a.state.x, gz = a.w.oz + a.state.z;
    const tiles = w ? Math.round(Math.hypot(w.ox + f.dx - gx, w.oz + f.dz - gz)) : 0;
    const fee = why === 'tow' && rankOf(u.driver) !== 'ace' ? Math.min(TOW_CAP, TOW_BASE + TOW_PER_TILE * tiles) : 0;
    this.dropLoads(a);
    f.cash -= fee;
    f.towed += fee;
    if (fee) f.tows++;
    if (fee) this.note(f, `Towed · ${reason} · ${money(fee)}`);
    if (w && (a.w === w || a.w.nbr.includes(w))) tr.relocate(a, w, f.dx, f.dz);
    else { tr.dropOwned(a); u.agent = null; u.traffic = null; }
  }

  /** A wrecker has hauled one of theirs clear (Traffic's tows): the firm pays the tow's rate and carries on. */
  towBill(a: Agent, tiles: number, reason: string): void {
    const o = this.of(a);
    if (!o) return;
    const { f, u } = o;
    const fee = rankOf(u.driver) !== 'ace' ? Math.min(TOW_CAP, TOW_BASE + TOW_PER_TILE * tiles) : 0;
    f.cash -= fee;
    f.towed += fee;
    if (fee) { f.tows++; this.note(f, `Towed clear · ${reason} · ${money(fee)}`); }
  }

  odometer(): void {}
  convoying(): boolean { return false; }
  convoyStuck(): void {}

  // ---- a railway's trains (0.7.0): game/trains.ts asks who runs a county's passenger trains, and pays each call ----

  /** The railway that runs this county's passenger trains, if one is homed in it and its county is in memory. */
  railOperator(cx: number, cz: number): { id: string; name: string; livery: [number, number]; trains: number } | null {
    for (const f of this.firms.values()) {
      if (f.trade === 'rail' && f.home[0] === cx && f.home[1] === cz) return { id: f.id, name: f.name, livery: f.livery, trains: f.units.length };
    }
    return null;
  }

  /** One of a railway's trains called at a station: its share of the fares. */
  railCall(id: string): void {
    const f = this.firms.get(id);
    if (!f || f.trade !== 'rail') return;
    this.earn(f, TRANSIT.fare);
    f.deliveries++;
    const u = f.units[f.deliveries % Math.max(1, f.units.length)];
    if (u) { u.paid += TRANSIT.fare; u.driver.deliveries++; }
  }

  // ---- the window's numbers ----

  /** Firms the player has met, busiest first. */
  list(): Firm[] {
    return [...this.firms.values()].filter((f) => f.met).sort((a, b) => b.units.length - a.units.length || a.name.localeCompare(b.name));
  }

  /** A firm's takings an hour lately, from its last few days' books. */
  rateOf(f: Firm): number {
    const days = f.days.slice(0, 3);
    return days.length ? days.reduce((s, v) => s + v, 0) / (days.length * 24) : 0;
  }

  /** How many of its vehicles are out now. */
  out(f: Firm): number { return f.units.filter((u) => u.agent).length; }

  /** The depots of firms met, for the map: the home cell, the kerb in it, and the livery. */
  homes(): { cx: number; cz: number; x: number; z: number; colour: number; accent: number; name: string; pref: boolean }[] {
    return this.list().map((f) => ({ cx: f.home[0], cz: f.home[1], x: f.dx, z: f.dz, colour: f.livery[0], accent: f.livery[1], name: f.name,
      pref: this.books.carriage.heldBy(f.id).length > 0 }));
  }

  /** Every firm's depot kerb in memory, in world tiles, with its colours: a tail can follow one of their vans home (game/tail). */
  depots(): { id: string; name: string; colour: number; x: number; z: number; cell: [number, number]; town: string }[] {
    const out: { id: string; name: string; colour: number; x: number; z: number; cell: [number, number]; town: string }[] = [];
    for (const f of this.firms.values()) {
      const w = this.host.worldAt(f.home[0], f.home[1]);
      if (w) out.push({ id: f.id, name: f.name, colour: f.livery[0], x: w.ox + f.dx, z: w.oz + f.dz, cell: [f.home[0], f.home[1]], town: f.town });
    }
    return out;
  }

  /** Stand a firm's beacon over its depot again (a tail has just found it). False with no such firm in memory. */
  spotlight(id: string): boolean {
    const f = this.firms.get(id);
    if (!f || !this.depotAt(f)) return false;
    this.beaconFor = f;
    this.beaconT = BEACON_SECS;
    (this.beacon.material as THREE.MeshBasicMaterial).color.setHex(f.livery[0]);
    return true;
  }

  /** Is a firm's home county in memory? */
  here(f: Firm): boolean { return !!this.host.worldAt(f.home[0], f.home[1]); }

  /** Counties between the player's and a firm's home (the larger of the two steps). */
  away(f: Firm): number {
    const c = this.host.playerCell();
    return c ? Math.max(Math.abs(f.home[0] - c[0]), Math.abs(f.home[1] - c[1])) : 0;
  }

  /** Is this building a door some firm holds? */
  doorHolder(w: World, b: Building): Firm | null { return this.ownerOf(this.estate.keyOf(w, b)); }

  // ---- the save ----

  /** One firm as it is written down. */
  saveFirm(f: Firm): SavedFirm {
    return {
      id: f.id, epoch: f.epoch, name: f.name, town: f.town, townKey: f.townKey, depot: f.depot, dx: +f.dx.toFixed(2), dz: +f.dz.toFixed(2),
      cash: Math.round(f.cash), founded: f.founded, stage: f.stage, board: f.board, days: f.days.map(Math.round), d0: f.d0, red: f.red,
      towed: Math.round(f.towed), tows: f.tows, snatched: f.snatched, met: f.met, earned: Math.round(f.earned), deliveries: f.deliveries,
      ...(f.village ? { village: true } : {}),
      hq: f.hq, floor: f.floor,
      feeds: Object.fromEntries(Object.entries(f.feeds).map(([k, v]) => [k, Math.round(v * 10) / 10])),
      log: f.log.slice(0, 20),
      units: f.units.map((u) => [u.uid, u.model, packParts(u.parts), u.driver, u.yard, Math.round(u.paid), Math.round(u.hours * 10) / 10]),
      deeds: [...f.deeds.values()].map((d) => ({ ...d, ceil: Math.round(d.ceil), took: Math.round(d.took), today: 0 })),
    };
  }

  /**
   * The firms as written down. With `near` (an online save) only those whose home it keeps: the rest are the
   * server's, with their counties, and come back from there (a wide-roaming career kept every firm of every county
   * it had loaded and passed the server's 2 MB: mickle, 28 Oct 2026); which of them were met is kept, by id.
   */
  toSave(near?: (cx: number, cz: number) => boolean): FirmsSave {
    const firms: SavedFirm[] = [], away = new Map(this.metAway);
    for (const f of this.firms.values()) {
      if (!near || near(f.home[0], f.home[1])) { firms.push(this.saveFirm(f)); away.delete(f.id); }
      else if (f.met) away.set(f.id, [f.name, f.livery[0]]);
    }
    return {
      keen: this.keen, next: this.next, firms, folded: { ...this.folded }, ...(Object.keys(this.bought).length ? { bought: { ...this.bought } } : {}),
      ...(away.size ? { metAway: Object.fromEntries(away) } : {}), carriage: this.books.carriage.toSave(),
    };
  }

  /** Firms met that an online save left out, by id: their name and colour. Met already, whenever they come back. */
  private metAway = new Map<string, [string, number]>();

  fromSave(s: FirmsSave | undefined): void {
    for (const f of this.firms.values()) for (const u of f.units) this.pullUnit(u);
    this.firms.clear();
    this.byUid.clear();
    this.empty.clear();
    this.counties.clear();
    this.rollCall = [];
    this.cardT = 0;
    this.defs.clear();
    this.keen = s?.keen ?? 2;
    this.next = Math.max(RIVAL_BASE + 1, s?.next ?? 0);
    // the old lattice's folded blocks are forgotten: their counties roll firms of their own now
    this.folded = Object.fromEntries(Object.entries(s?.folded ?? {}).filter(([k]) => parseSlotId(k)));
    this.bought = Object.fromEntries(Object.entries(s?.bought ?? {}).filter(([k, v]) => typeof k === 'string' && Number.isFinite(v)));
    this.metAway = new Map(Object.entries(s?.metAway ?? {}).filter(([, v]) => Array.isArray(v) && typeof v[0] === 'string' && Number.isFinite(v[1])));
    this.books.carriage.fromSave(s?.carriage);
    for (const sf of s?.firms ?? []) if (this.bought[sf.id] === undefined) this.load(sf, true);
    this.hideAll();
  }

  /** One saved firm back in the registry. Its units keep their numbers from a save of this game's own; another game's are numbered afresh. */
  private load(sf: SavedFirm, ownNumbers: boolean): Firm | null {
    const sh = this.seedHash();
    // a firm of the local lattice, or one of the old blocks' kept as it was
    const at = parseSlotId(sf.id);
    const [bx, bz] = sf.id.split(',').map(Number);
    const spec = at ? specFor(sh, at.cx, at.cz, at.slot, sf.epoch, !!sf.village) : legacySpec(sh, bx, bz, sf.epoch, Math.max(1, this.keen));
    if (!spec) return null;
    const f: Firm = {
      ...spec, name: sf.name, town: sf.town, townKey: sf.townKey, depot: sf.depot, dx: sf.dx, dz: sf.dz,
      cash: sf.cash, units: [], deeds: new Map(), founded: sf.founded, stage: sf.stage, board: sf.board,
      days: sf.days ?? [], d0: sf.d0, red: sf.red, towed: sf.towed, tows: sf.tows, snatched: sf.snatched,
      feeds: sf.feeds ?? {}, refused: {}, idleT: 0, outT: 0, log: sf.log ?? [], met: !!sf.met,
      earned: sf.earned ?? (sf.days ?? []).reduce((a, v) => a + v, 0),
      deliveries: sf.deliveries ?? (sf.units ?? []).reduce((a, u) => a + (u[3]?.deliveries ?? 0), 0),
      // a firm from before HQ grades runs from its depot, graded when its cell is next in memory
      hq: sf.hq ?? { key: sf.depot, name: '', grade: 0, slots: 0 }, floor: sf.floor ?? (sf.units ?? []).length,
    };
    for (const d of sf.deeds ?? []) f.deeds.set(d.key, { ...d, d0: -1 });
    this.firms.set(f.id, f);
    for (const [uid, model, parts, driver, yard, paid, hours] of sf.units ?? []) {
      const u = this.addUnit(f, model, { ...driver }, unpackParts(parts) ?? { t: {}, spent: 0 }, ownNumbers ? uid : undefined);
      u.yard = yard; u.paid = paid; u.hours = hours;
    }
    return f;
  }

  /**
   * Online: a firm as the game running its home county last had it. It takes the place of this game's
   * own idea of the firm (which may be days out of date, or nothing), but keeps whether this player has met it.
   */
  adopt(sf: SavedFirm): void {
    if (!sf || typeof sf.id !== 'string' || !parseSlotId(sf.id)) return;
    // a firm this player bought out is gone from their world, whatever another game still has of it
    if (this.bought[sf.id] !== undefined) return;
    const was = this.firms.get(sf.id);
    if (was) {
      for (const u of was.units) { this.pullUnit(u); this.byUid.delete(u.uid); }
      this.firms.delete(sf.id);
    }
    delete this.folded[sf.id];
    try { this.load({ ...sf, met: was ? was.met : this.metAway.has(sf.id) }, false); } catch (e) { console.warn(`firms: could not adopt ${sf.id}`, e); }
    this.host.changed();
  }

  /** Online: a door a player now holds is no firm's: whichever firm thought it had it lets it go, at what it paid. */
  evict(key: string): void {
    for (const f of this.firms.values()) {
      const d = f.deeds.get(key);
      if (!d || key === f.depot || key === f.hq.key) continue;
      f.deeds.delete(key);
      f.cash += d.paid;
    }
  }

  /** Every firm and every town's carriage forgotten: a new world. */
  clear(): void { this.fromSave(undefined); }

  // ---- the console: pr.firms ----

  console() {
    return {
      list: () => [...this.firms.values()].map((f) => `${f.name} (${f.id}) · ${f.trade}/${f.bent} · stage ${f.stage} · ${f.units.length} units (${this.out(f)} out) · ${f.deeds.size} doors · ${money(f.cash)} · home ${f.home.join(',')}${f.met ? '' : ' · not met'}`),
      firm: (id: string) => this.firms.get(id),
      keen: (k?: number) => { if (k !== undefined) { this.keen = Math.max(0, Math.min(3, k)); this.empty.clear(); this.counties.clear(); } return this.keen; },
      /** The counties in memory: how many firms each holds, and who they are. */
      near: () => this.host.worlds().map((w) => {
        const c = this.county(w);
        const who = this.homedIn(w.cx, w.cz).map((f) => `${f.name} (${f.id}, ${f.trade}, cap ${f.cap ?? '?'})`).join(' · ');
        return `${w.cx},${w.cz}: ${w.towns.length} towns · $${c.sum.norm}/h · ${c.sum.towns.reduce((n, t) => n + t.buildings, 0)} buildings → ${c.n}${c.village ? ' village' : ''} · ${who || 'none yet'}`;
      }),
      /** Hold a board meeting now for every firm in memory. */
      board: () => { for (const f of this.firms.values()) if (this.host.worldAt(f.home[0], f.home[1])) this.meeting(f, this.day()); },
      /** The registry itself, for poking at from the console. */
      self: () => this,
      /** Give a firm cash, to watch its board spend it. */
      fund: (id: string, v: number) => { const f = this.firms.get(id); if (f) f.cash += v; return f?.cash; },
      towns: () => {
        const out: string[] = [];
        for (const w of this.host.worlds()) for (const t of w.towns) {
          const tk = townKey(w, t);
          const sh = this.books.carriage.shares(tk);
          if (!sh.length) continue;
          out.push(`${t.name}: ${sh.map((s) => `${this.carrierName(s.who)} ${Math.round(s.share * 100)}%`).join(' · ')}${this.books.carriage.preferred(tk) ? ` → ${this.carrierName(this.books.carriage.preferred(tk))}` : ''}`);
        }
        return out;
      },
    };
  }
}


interface FirmQuote { name: string; town: string; townKey: string; price: number; word: PaybackWord; kind: string }

type Decision =
  | { buy: 'vehicle'; model: string }
  | { buy: 'part'; uid: number; slot: SlotId; tier: number }
  | { buy: 'deed'; key: string; price: number }
  | { buy: 'hq'; key: string; price: number }
  | { sell: 'vehicle'; uid: number }
  | { sell: 'deed'; key: string };
