/** The most a trailer may pitch away from its tractor, radians: past this the hitch would have torn off. */
const TRAILER_TILT = 0.3;

export interface Spinner { obj: THREE.Object3D; axis: 'x' | 'y' | 'z'; speed: number }

export interface VehicleMesh {
  holder: THREE.Group;          // added to the scene, stays at the origin
  root: THREE.Group;            // posed at the vehicle
  body: THREE.Group;            // bob and lean
  wheels: THREE.Object3D[];
  steerGroups: THREE.Group[];
  spinners: Spinner[];
  trailer?: THREE.Group;        // sibling of root, posed separately
  /** How far workshop tyres and suspension lift the body, in the model's own units. */
  lift?: number;
  /** Each wheel's mount inside the body and its resting height: held on the ground while the body bobs. */
  axles?: { obj: THREE.Object3D; y: number }[];
  sail?: THREE.Object3D;
  jib?: THREE.Object3D;
  flag?: THREE.Object3D;
  /** A convertible's folding roof, eased between up (0) and stowed (1) by `roofT`. */
  roof?: THREE.Object3D;
  roofT?: number;
  /** A convertible's passengers, shown one per rider aboard; `seatDefault` is how many a CPU car carries. */
  seats?: THREE.Object3D[];
  seatDefault?: number;
  /** A jet's undercarriage, folded up into the belly in flight. */
  gear?: THREE.Object3D;
  /** An ambulance's beacons, red and blue, flashing while it is on the move. */
  beacons?: THREE.MeshStandardMaterial[];
  /** A carriage's horses' legs, swung by the distance covered (each pair half a stride apart). */
  legs?: { obj: THREE.Object3D; phase: number }[];
  // ---- traffic's shared bodies (trafficVehicleMesh) ----
  /** The model this body's geometry is shared with, when it is one of traffic's clones. */
  shared?: VehicleDef;
  /** Materials this clone owns (its glowing ones, copied so its lamps and lightbars are its own). */
  own?: THREE.Material[];
  /** Its glowing materials, so the night's glow need not walk the whole body every frame. */
  lit?: THREE.MeshStandardMaterial[];
  /** The whole body merged into a few meshes at rest, and the parts it stands in for: shown when the car is small on screen. */
  far?: THREE.Object3D[];
  near?: THREE.Object3D[];
  /** Showing the far body. */
  lod?: boolean;
}

type Axis = 'x' | 'y' | 'z';
type MatLike = THREE.Material | number;

const GLASS = 0xa8d8f0, DARK = 0x2a2a2e, HUB = 0xc9c9cd, SKIN = 0xf2c39b, WHITE = 0xf4f2ec, CHROME = 0xd9dde2;
const WOOD = 0xb07a4a, NAVY = 0x2f4d7a, YELLOW = 0xf2c14e, RED = 0xe2412f, TEAL = 0x2bb3a3, CORAL = 0xf49ab5;

/** Small helper that keeps the flat-shaded toy look consistent across every vehicle. */
export class Kit {
  wheels: THREE.Object3D[] = [];
  steer: THREE.Group[] = [];
  spinners: Spinner[] = [];
  private cache = new Map<string, THREE.MeshStandardMaterial>();

  mat(color: number, rough = 0.55, metal = 0.05, emissive = 0, intensity = 0, side: THREE.Side = THREE.FrontSide): THREE.MeshStandardMaterial {
    const key = `${color}|${rough}|${metal}|${emissive}|${intensity}|${side}`;
    let m = this.cache.get(key);
    if (!m) {
      m = new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal, emissive, emissiveIntensity: intensity, flatShading: true, side });
      this.cache.set(key, m);
    }
    return m;
  }
  glass() { return this.mat(GLASS, 0.2, 0.1); }
  dark() { return this.mat(DARK, 0.9, 0); }
  chrome() { return this.mat(CHROME, 0.35, 0.5); }
  lamp() { return this.mat(0xfff2b0, 0.5, 0, 0xffe08a, 0.6); }
  /** An aircraft navigation light: bright enough to read against a night sky, and optionally flashing. */
  nav(color: number, strobe = false): THREE.MeshStandardMaterial {
    const m = this.mat(color, 0.35, 0, color, strobe ? 2.6 : 1.7);
    if (strobe) m.userData.strobe = 1;
    return m;
  }

  /**
   * Wingtip lights (red to port, green to starboard), a white tail light and a flashing red beacon:
   * the pattern that makes an aircraft legible in the dark from any angle.
   */
  navLights(parent: THREE.Object3D, hx: number, y: number, zf: number, zb: number, beaconY = y + 0.2): void {
    this.ball(parent, 0.055, this.nav(0xff2a1e), -hx, y, zf);
    this.ball(parent, 0.055, this.nav(0x2bff5a), hx, y, zf);
    this.ball(parent, 0.05, this.nav(0xffffff), 0, y, zb);
    this.ball(parent, 0.05, this.nav(0xff3a2a, true), 0, beaconY, (zf + zb) * 0.5);
  }
  tail() { return this.mat(0xb02020, 0.5, 0, 0x801010, 0.4); }
  cloth(color: number) { return this.mat(color, 0.85, 0, 0, 0, THREE.DoubleSide); }

  private m(x: MatLike): THREE.Material { return typeof x === 'number' ? this.mat(x) : x; }

  add(parent: THREE.Object3D, geo: THREE.BufferGeometry, mat: MatLike, x = 0, y = 0, z = 0): THREE.Mesh {
    const mesh = new THREE.Mesh(geo, this.m(mat));
    mesh.position.set(x, y, z);
    parent.add(mesh);
    return mesh;
  }
  group(parent: THREE.Object3D, x = 0, y = 0, z = 0): THREE.Group {
    const g = new THREE.Group();
    g.position.set(x, y, z);
    parent.add(g);
    return g;
  }
  box(parent: THREE.Object3D, w: number, h: number, d: number, mat: MatLike, x = 0, y = 0, z = 0): THREE.Mesh {
    return this.add(parent, new THREE.BoxGeometry(w, h, d), mat, x, y, z);
  }
  cyl(parent: THREE.Object3D, rTop: number, rBot: number, h: number, seg: number, mat: MatLike, x = 0, y = 0, z = 0, axis: Axis = 'y'): THREE.Mesh {
    const g = new THREE.CylinderGeometry(rTop, rBot, h, seg);
    if (axis === 'x') g.rotateZ(-Math.PI / 2);
    else if (axis === 'z') g.rotateX(Math.PI / 2);
    return this.add(parent, g, mat, x, y, z);
  }
  ball(parent: THREE.Object3D, r: number, mat: MatLike, x = 0, y = 0, z = 0, sx = 1, sy = 1, sz = 1, detail = 1): THREE.Mesh {
    const g = new THREE.IcosahedronGeometry(r, detail);
    g.scale(sx, sy, sz);
    return this.add(parent, g, mat, x, y, z);
  }
  cone(parent: THREE.Object3D, r: number, h: number, seg: number, mat: MatLike, x = 0, y = 0, z = 0): THREE.Mesh {
    return this.add(parent, new THREE.ConeGeometry(r, h, seg), mat, x, y, z);
  }
  tri(parent: THREE.Object3D, a: number[], b: number[], c: number[], mat: MatLike): THREE.Mesh {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute([...a, ...b, ...c], 3));
    g.computeVertexNormals();
    return this.add(parent, g, mat);
  }
  /** Boat-shaped prism: flat stern, pointed bow toward +z, from y = 0 up to height. */
  hull(parent: THREE.Object3D, halfW: number, halfL: number, height: number, bow: number, mat: MatLike, y = 0): THREE.Mesh {
    const s = new THREE.Shape();
    // shape y maps to -z after the rotation below
    s.moveTo(-halfW, halfL);
    s.lineTo(halfW, halfL);
    s.lineTo(halfW, -halfL * bow);
    s.lineTo(0, -halfL);
    s.lineTo(-halfW, -halfL * bow);
    s.closePath();
    const g = new THREE.ExtrudeGeometry(s, { depth: height, bevelEnabled: false });
    g.rotateX(-Math.PI / 2);
    return this.add(parent, g, mat, 0, y, 0);
  }
  wheel(parent: THREE.Object3D, r: number, width: number, x: number, y: number, z: number, steer = false, hub = HUB, spin = true): THREE.Group {
    const g = this.group(parent, x, y, z);
    const tyre = this.cyl(g, r, r, width, 12, this.dark(), 0, 0, 0, 'x');
    this.cyl(tyre, r * 0.45, r * 0.45, width + 0.01, 8, this.mat(hub, 0.5, 0.3), 0, 0, 0, 'x');
    if (spin) this.wheels.push(tyre);
    if (steer) this.steer.push(g);
    return g;
  }
  spin(obj: THREE.Object3D, axis: Axis, speed: number): void { this.spinners.push({ obj, axis, speed }); }
  /** A little seated person. Origin at the seat. */
  rider(parent: THREE.Object3D, x: number, y: number, z: number, shirt: number, helmet?: number): THREE.Group {
    const g = this.group(parent, x, y, z);
    this.box(g, 0.17, 0.2, 0.12, shirt, 0, 0.1, 0);
    this.ball(g, 0.075, SKIN, 0, 0.27, 0.01);
    if (helmet !== undefined) {
      this.ball(g, 0.088, this.mat(helmet, 0.35, 0.1), 0, 0.285, -0.005);
      this.box(g, 0.12, 0.04, 0.03, this.mat(0x3a4a55, 0.2, 0.2), 0, 0.28, 0.08);
    }
    return g;
  }
  lights(parent: THREE.Object3D, hx: number, y: number, zf: number, zb: number): void {
    for (const sx of [-1, 1]) {
      this.box(parent, 0.1, 0.08, 0.03, this.lamp(), sx * hx, y, zf);
      this.box(parent, 0.1, 0.06, 0.03, this.tail(), sx * hx, y, zb);
    }
  }
  /** Windshield, rear glass and side windows around a cabin box. */
  cabinGlass(parent: THREE.Object3D, w: number, h: number, len: number, y: number, zc: number): void {
    const g = this.glass();
    this.box(parent, w - 0.06, h * 0.62, 0.03, g, 0, y + 0.01, zc + len / 2 + 0.005);
    this.box(parent, w - 0.06, h * 0.55, 0.03, g, 0, y + 0.01, zc - len / 2 - 0.005);
    for (const sx of [-1, 1]) this.box(parent, 0.03, h * 0.55, len - 0.12, g, sx * (w / 2 + 0.005), y + 0.01, zc);
  }
}

interface Extras {
  holder: THREE.Group; trailer?: THREE.Group; sail?: THREE.Object3D; jib?: THREE.Object3D; flag?: THREE.Object3D;
  roof?: THREE.Object3D; seats?: THREE.Object3D[]; gear?: THREE.Object3D; beacons?: THREE.MeshStandardMaterial[];
  legs?: { obj: THREE.Object3D; phase: number }[];
}
export type Build = (k: Kit, b: THREE.Group, d: VehicleDef, x: Extras) => void;

