/** A flat ring in the deck plane (a helipad's circle), radius r, at (x, y, z). */
function deckRing(k: Kit, b: THREE.Object3D, r: number, tube: number, mat: MatLike, x: number, y: number, z: number): void {
  const g = new THREE.TorusGeometry(r, tube, 4, 28);
  g.rotateX(Math.PI / 2);
  k.add(b, g, mat, x, y, z);
}

