  k.box(b, 0.66, 0.26, 0.46, oak, 0, 0.27, -0.74);
  k.box(b, 0.7, 0.03, 0.5, gold, 0, 0.41, -0.74);
  k.box(b, 0.56, 0.16, 0.3, oak, 0, 0.5, -0.82);
