  for (let n = 0; n < 4; n++) k.box(b, 0.08, 0.07, 0.01, k.lamp(), -0.21 + n * 0.14, 0.3, -0.976);
  for (let n = 0; n < 3; n++) k.box(b, 0.08, 0.06, 0.01, k.lamp(), -0.14 + n * 0.14, 0.5, -0.976);
  for (const sx of [-0.2, 0, 0.2]) {
    k.cyl(b, 0.008, 0.008, 0.1, 4, DARK, sx, 0.66, -0.95);
    k.ball(b, 0.035, k.lamp(), sx, 0.73, -0.95, 1, 1.3, 1, 0);
  }
  for (const sx of [-1, 1]) for (let n = 0; n < 3; n++) k.box(b, 0.01, 0.05, 0.06, k.lamp(), sx * 0.331, 0.29, -0.62 - n * 0.12);
