  k.box(b, 0.02, 0.05, 0.04, k.dark(), 0.0, R + 0.32, 0.27);
  // small running lights on the sail: red to port, green to starboard, a white masthead and a flashing beacon
  k.ball(b, 0.016, k.nav(0xff2a1e), -0.038, R + 0.17, 0.4, 1, 1, 1, 0);
  k.ball(b, 0.016, k.nav(0x2bff5a), 0.038, R + 0.17, 0.4, 1, 1, 1, 0);
  k.ball(b, 0.014, k.nav(0xffffff), 0, R + 0.38, 0.4, 1, 1, 1, 0);
  k.ball(b, 0.014, k.nav(0xff3a2a, true), 0, R + 0.34, 0.3, 1, 1, 1, 0);
  // the tail: rudders above and below, planes either side, and the shrouded screw
  k.box(b, 0.012, 0.3, 0.16, p, 0, 0, -1.12);
  k.box(b, 0.32, 0.012, 0.16, p, 0, 0, -1.12);
  k.cyl(b, 0.07, 0.07, 0.07, 14, k.dark(), 0, 0, -1.4, 'z');
  const screw = k.group(b, 0, 0, -1.44);
  for (let i = 0; i < 7; i++) {
    const blade = k.box(screw, 0.11, 0.012, 0.012, 0x6b6f75, 0, 0, 0);
    blade.rotation.z = (i / 7) * Math.PI;
  }
  k.spin(screw, 'z', 22);
  // the hatches and the escape trunk on the casing
  for (const z of [-0.5, -0.2, 0.7]) k.cyl(b, 0.025, 0.025, 0.012, 8, deck, 0, R + 0.012, z);
