/**
 * The hot air balloon: gores round an envelope over a throat, four ropes down to a wicker basket with its burner.
 * The envelope is painted by its pattern (def.envelope), each gore cut into bands so a pattern can colour any
 * patch of it; the Sunrise's own is its colour and yellow in stripes.
 */
export const BALLOON_PATTERNS = 8;
const balloon: Build = (k, b, d) => {
  const env = d.envelope ?? { p: 0, c: [d.color, YELLOW] };
  const c = env.c.length ? env.c : [d.color];
  const C = (i: number) => c[((i % c.length) + c.length) % c.length];
  // the bands down a gore, as shares of the envelope from its crown (0) to its mouth (1)
  const BANDS = [0, 0.26, 0.47, 0.66, 1];
  const gores = env.p === 1 ? 12 : 8;
  /** The colour of gore i's band j. */
  const paint = (i: number, j: number): number => {
    switch (env.p) {
      case 1: return C(i); // rainbow: every gore its own
      case 2: return C((i + j) % 2); // harlequin checks
      case 3: return j === 0 ? C(1) : j === 2 ? C(2) : C(0); // a crown and a belt
      case 4: return C(i + j); // a spiral running round it
      case 5: return j < 2 ? C(0) : j === 2 ? C(2) : C(1); // two halves, a stripe between
      case 6: return j === 1 || j === 2 ? (i % 2 ? C(1) : C(2)) : C(0); // diamonds round the middle
      case 7: return j === 3 ? C(1) : i % 4 === 0 ? C(2) : C(0); // a few gores picked out, a dark skirt
      default: return C(i % 2); // stripes
    }
  };
  const top = Math.PI * 0.78;
  for (let i = 0; i < gores; i++) {
    for (let j = 0; j < BANDS.length - 1; j++) {
      const t0 = BANDS[j] * top, t1 = BANDS[j + 1] * top;
      const g = new THREE.SphereGeometry(0.44, gores === 12 ? 2 : 3, Math.max(2, Math.round((10 * (t1 - t0)) / top)), (i / gores) * Math.PI * 2, (Math.PI * 2) / gores, t0, t1 - t0);
      g.scale(1, 1.18, 1);
      k.add(b, g, paint(i, j), 0, 1.0, 0);
    }
  }
  k.cyl(b, 0.27, 0.1, 0.26, 10, C(env.p === 5 ? 1 : 0), 0, 0.5, 0);
  k.add(b, new THREE.TorusGeometry(0.1, 0.012, 4, 12).rotateX(Math.PI / 2), k.dark(), 0, 0.37, 0);
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) {
    const rope = k.cyl(b, 0.006, 0.006, 0.26, 3, k.dark(), sx * 0.085, 0.24, sz * 0.085);
    rope.rotation.set(sz * 0.06, 0, -sx * 0.06);
  }
  k.box(b, 0.2, 0.13, 0.2, WOOD, 0, 0.065, 0);
  k.box(b, 0.215, 0.025, 0.215, 0x7a5230, 0, 0.13, 0);
  k.box(b, 0.06, 0.04, 0.06, CHROME, 0, 0.3, 0);
  // the burner's flame, lit so the balloon glows at night
  k.cone(b, 0.03, 0.08, 6, k.nav(0xffa63a), 0, 0.36, 0);
  for (const sx of [-1, 1]) k.ball(b, 0.035, 0xf2d3b0, sx * 0.05, 0.16, 0.03);
};

