/**
 * An undercarriage leg: a strut down from the belly and its wheels, in the gear group so the whole set
 * folds up into the fuselage in flight. Wheels here don't turn on the ground.
 */
function leg(k: Kit, g: THREE.Group, x: number, z: number, drop: number, r: number, pair: boolean): void {
  k.box(g, 0.025, drop, 0.025, k.chrome(), x, -drop / 2, z);
  for (const sx of pair ? [-1, 1] : [0]) k.wheel(g, r, r * 0.8, x + sx * r * 0.7, -drop + r, z, false, HUB, false);
}

