const DRAB = 0x3d4430, CAMO_DARK = 0x4a5236, CAMO_SAND = 0xa89a64;
type Patch = [number, number, number, number, number, number];

/** A flat plate from a top-view outline of (x, z) points, `thick` deep, its underside at `y`. */
function slab(k: Kit, parent: THREE.Object3D, pts: [number, number][], thick: number, mat: MatLike, y: number): THREE.Mesh {
  const s = new THREE.Shape();
  s.moveTo(pts[0][0], -pts[0][1]);
  for (const [px, pz] of pts.slice(1)) s.lineTo(px, -pz);
  s.closePath();
  const g = new THREE.ExtrudeGeometry(s, { depth: thick, bevelEnabled: false });
  g.rotateX(-Math.PI / 2);
  return k.add(parent, g, mat, 0, y, 0);
}

/** Camouflage: thin patches, [x, y, z, width, depth, colour] lying on a top, or [x, y, z, height, length, colour] on a flank. */
function camo(k: Kit, parent: THREE.Object3D, top: Patch[], side: Patch[] = []): void {
  for (const [x, y, z, w, dd, c] of top) k.box(parent, w, 0.006, dd, c, x, y, z);
  for (const [x, y, z, h, l, c] of side) k.box(parent, 0.006, h, l, c, x, y, z);
}

