/** A faction model not drawn yet wears a similar body meanwhile. */
const STAND_IN: Record<string, string> = {
  interceptor: 'wasabi', getaway: 'limo', undertaker: 'limo', statesman: 'limo', saucerScout: 'hover', saucer: 'dragonfly',
  mixer: 'dump', bigHook: 'wrecker', mailTruck: 'postal', nightflyer: 'barnstormer', deuce: 'humvee', starTours: 'bus',
  marquee: 'sunny', liveTruck: 'mule', pelican: 'defender', greyGull: 'riverboat', northernLight: 'riverboat', eyeInSky: 'dragonfly',
};

/**
 * Merge a vehicle's static parts. Every box, cylinder and ball of a toy vehicle was its own mesh, so
 * twenty CPU vehicles cost hundreds of draw calls in the shadow pass and again on screen. Within each
 * group, the leaf meshes that share a finish (roughness, metalness, glow, sidedness) become one
 * vertex-coloured mesh; anything that moves on its own — a wheel, a rotor, a sail, a trailer — keeps
 * its group, so its merged parts still move with it.
 */
function mergeStatic(holder: THREE.Object3D, keep: Set<THREE.Object3D>): void {
  const groups: THREE.Object3D[] = [];
  holder.traverse((o) => { if (!(o as THREE.Mesh).isMesh) groups.push(o); });
  const mats = new Map<string, THREE.MeshStandardMaterial>();
  for (const g of groups) {
    const buckets = new Map<string, THREE.Mesh[]>();
    for (const child of g.children) {
      const mesh = child as THREE.Mesh;
      const m = mesh.material as THREE.MeshStandardMaterial;
      if (!mesh.isMesh || keep.has(mesh) || mesh.children.length || !m?.isMeshStandardMaterial || Array.isArray(mesh.material)) continue;
      if (m.transparent || m.map || m.userData.strobe) continue;
      const key = `${m.roughness}|${m.metalness}|${m.emissive.getHex()}|${m.emissiveIntensity}|${m.side}|${m.flatShading}`;
      const list = buckets.get(key) ?? [];
      list.push(mesh);
      buckets.set(key, list);
    }
    for (const [key, list] of buckets) {
      if (list.length < 2) continue;
      const parts: THREE.BufferGeometry[] = [];
      for (const mesh of list) {
        mesh.updateMatrix();
        let geo = mesh.geometry.clone().applyMatrix4(mesh.matrix);
        if (geo.index) geo = geo.toNonIndexed();
        for (const name of Object.keys(geo.attributes)) if (name !== 'position' && name !== 'normal') geo.deleteAttribute(name);
        const c = (mesh.material as THREE.MeshStandardMaterial).color;
        const n = geo.attributes.position.count, col = new Float32Array(n * 3);
        for (let i = 0; i < n; i++) { col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b; }
        geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
        parts.push(geo);
      }
      const merged = mergeGeometries(parts, false);
      parts.forEach((p) => p.dispose());
      if (!merged) continue;
      const src = list[0].material as THREE.MeshStandardMaterial;
      let mat = mats.get(key);
      if (!mat) {
        mat = new THREE.MeshStandardMaterial({
          vertexColors: true, roughness: src.roughness, metalness: src.metalness, emissive: src.emissive.clone(),
          emissiveIntensity: src.emissiveIntensity, side: src.side, flatShading: src.flatShading,
        });
        mats.set(key, mat);
      }
      const out = new THREE.Mesh(merged, mat);
      out.castShadow = list.some((m) => m.castShadow);
      out.receiveShadow = list.some((m) => m.receiveShadow);
      for (const m of list) { g.remove(m); m.geometry.dispose(); }
      g.add(out);
    }
  }
}

/** `merge: false` keeps every part its own mesh (scripts/boltScan.ts measures the bolt-ons one by one); the game always merges. */
export function buildVehicleMesh(def: VehicleDef, opts: { merge?: boolean } = {}): VehicleMesh {
  const holder = new THREE.Group();
  if (def.kind === 'rail') {
    // a train's cars belong to the trains system, which poses each on the track
    const root = new THREE.Group(), body = new THREE.Group();
    holder.add(root);
    root.add(body);
    return { holder, root, body, wheels: [], steerGroups: [], spinners: [] };
  }
  const scale = def.scale ?? 1;
  if (def.id === 'tomato') {
    const cm = createCarMesh(def as LandDef);
    holder.add(cm.root);
    const lift = dressVehicle(cm.root, cm.body, def, cm.wheels);
    // gold all over (the Passport's Gilded Fleet, render/treats.ts) wins over a paintjob
    if (def.gild !== 2) dressJob(cm.root, cm.body, def, cm.wheels);
    const treats = dressTreats(cm.root, cm.body, def, cm.wheels, []);
    cm.root.scale.setScalar(scale);
    if (opts.merge !== false) mergeStatic(holder, new Set([cm.root, cm.body, ...cm.wheels, ...cm.steerGroups, ...treats]));
    return { holder, root: cm.root, body: cm.body, wheels: cm.wheels, steerGroups: cm.steerGroups, spinners: [], lift, axles: axlesOf(cm.body, cm.wheels) };
  }
  const root = new THREE.Group();
  const body = new THREE.Group();
  holder.add(root);
  root.add(body);
  const k = new Kit();
  const extras: Extras = { holder };
  (BUILDERS[def.id] ?? BUILDERS[STAND_IN[def.id]] ?? BUILDERS.mule)(k, body, def, extras);
  const lift = dressVehicle(root, body, def, k.wheels, k.spinners.map((s) => s.obj));
  if (def.gild !== 2) dressJob(root, body, def, k.wheels);
  const treats = dressTreats(root, body, def, k.wheels, k.spinners.map((s) => s.obj));
  root.scale.setScalar(scale);
  extras.trailer?.scale.setScalar(scale);
  // (a treat's beams and spots are light, not things: they cast no shadow)
  holder.traverse((o) => { if ((o as THREE.Mesh).isMesh) { o.castShadow = !o.userData.noShadow; o.receiveShadow = false; } });
  const moving = [root, body, ...k.wheels, ...k.steer, ...k.spinners.map((s) => s.obj), extras.trailer, extras.sail, extras.jib, extras.flag,
    extras.roof, extras.gear, ...(extras.seats ?? []), ...(extras.legs ?? []).map((l) => l.obj), ...treats];
  if (opts.merge !== false) mergeStatic(holder, new Set(moving.filter((o): o is THREE.Object3D => !!o)));
  return {
    holder, root, body, wheels: k.wheels, steerGroups: k.steer, spinners: k.spinners,
    trailer: extras.trailer, sail: extras.sail, jib: extras.jib, flag: extras.flag, lift, axles: axlesOf(body, k.wheels),
    roof: extras.roof, roofT: roofUp() ? 0 : 1, seats: extras.seats, seatDefault: extras.seats ? Math.floor(Math.random() * (extras.seats.length + 1)) : 0,
    gear: extras.gear, beacons: extras.beacons, legs: extras.legs,
  };
}

/**
 * The mounts the wheels hang from inside the body. The body bobs on its springs (and every tile edge
 * kicks it down, harder on big soft tyres); the wheels must stay on the road rather than dip into it.
 */
function axlesOf(body: THREE.Object3D, wheels: THREE.Object3D[]): { obj: THREE.Object3D; y: number }[] {
  const out = new Map<THREE.Object3D, number>();
  for (const w of wheels) {
    const m = w.parent;
    if (!m || m === body || out.has(m)) continue;
    let under = false;
    for (let p = m.parent; p; p = p.parent) if (p === body) { under = true; break; }
    if (under) out.set(m, m.position.y);
  }
  return [...out].map(([obj, y]) => ({ obj, y }));
}

export function disposeVehicleMesh(m: VehicleMesh): void {
  // a clone of a shared body: only its own lamps are its to throw away, and the body when nobody else wears it
  if (m.shared) {
    for (const x of m.own ?? []) x.dispose();
    const t = templates.get(m.shared);
    if (t && --t.users <= 0 && !t.keep) {
      templates.delete(m.shared);
      disposeVehicleMesh(t.mesh);
    }
    return;
  }
  const mats = new Set<THREE.Material>();
  m.holder.traverse((o) => {
    const mesh = o as THREE.Mesh;
    if (!mesh.isMesh) return;
    // the treats' shared pieces (render/wonderBall.ts, render/treats.ts) outlive any one vehicle
    if (!mesh.userData.shared) mesh.geometry.dispose();
    const mat = mesh.material as THREE.Material;
    if (!mat.userData?.shared) mats.add(mat);
  });
  mats.forEach((x) => x.dispose());
}

/** Copy a vehicle state onto its mesh (spinners are advanced separately, per frame). */
export function poseVehicleMesh(m: VehicleMesh, s: VehicleState, def: VehicleDef, w: World): void {
  m.root.position.set(s.x, s.y, s.z);
  m.root.rotation.set(s.pitch, s.heading, s.roll, 'YXZ');
  m.body.position.y = s.bob + (m.lift ?? 0);
  if (m.axles) for (const a of m.axles) a.obj.position.y = a.y - s.bob;
  m.body.rotation.z = s.lean;
  for (const wheel of m.wheels) wheel.rotation.x = s.wheelSpin;
  for (const g of m.steerGroups) g.rotation.y = s.steerVis;
  if (m.sail) m.sail.rotation.y = s.sailAngle;
  if (m.jib) m.jib.rotation.y = s.sailAngle * 0.7;
  if (m.flag) m.flag.rotation.y = env.windHeading - s.heading;
  if (m.roof) {
    // the soft top swings back and folds into the tonneau behind the seats, or comes up over them
    const want = roofUp() ? 0 : 1;
    const t = (m.roofT ?? want) + Math.max(-1 / 70, Math.min(1 / 70, want - (m.roofT ?? want)));
    m.roofT = t;
    m.roof.rotation.x = t * 1.35;
    m.roof.scale.set(1, 1 - 0.8 * t, 1 - 0.75 * t);
    m.roof.visible = t < 0.98;
  }
  if (m.seats) {
    const n = s.riders ?? m.seatDefault ?? 0;
    for (let k = 0; k < m.seats.length; k++) m.seats[k].visible = k < n; // loops, not forEach: no closure a car a frame
  }
  if (m.beacons) {
    // on the move the siren's lights take turns; parked they glow steady and dim
    const on = Math.sin(performance.now() * 0.014) > 0;
    for (let k = 0; k < m.beacons.length; k++) m.beacons[k].emissiveIntensity = Math.abs(s.v) > 0.3 ? ((k === 0) === on ? 4 : 0.05) : 0.4;
  }
  if (m.legs) {
    // a trot while it moves, standing square once it stops
    const a = 0.55 * Math.min(1, Math.abs(s.v) * 2);
    for (const l of m.legs) l.obj.rotation.x = Math.sin(s.wheelSpin * 0.7 + l.phase) * a;
  }
  if (m.gear) {
    const g = s.gear ?? 1;
    m.gear.scale.y = Math.max(0.001, g);
    m.gear.visible = g > 0.02;
  }
  if (m.trailer && def.kind === 'land' && def.trailer) {
    const { hitch, length } = def.trailer;
    const hx = s.x - Math.sin(s.heading) * hitch, hz = s.z - Math.cos(s.heading) * hitch;
    const hy = s.y + Math.sin(s.pitch) * hitch;
    const th = s.trailerHeading;
    // the axle rides whatever is under it — a bridge deck, a road's painted surface, the ground — not the
    // bare terrain, which on a bridge is the valley floor and would drop the trailer straight through the deck
    const ay = surfaceNear(w, hx - Math.sin(th) * length, hz - Math.cos(th) * length, hy);
    // and it is still a rigid trailer: it can only pitch so far before the hitch would have torn off
    const tilt = Math.max(-TRAILER_TILT, Math.min(TRAILER_TILT, Math.atan2(hy - ay, length)));
    m.trailer.position.set(hx, hy, hz);
    m.trailer.rotation.set(-tilt, th, 0, 'YXZ');
  }
}


// ---- traffic's shared bodies ------------------------------------------------------------------

/**
 * Traffic's cars (docs/localrivals.html, "More cars"): every car of a model wears the same body, so the
 * body is built once, kept as a template, and each car is a clone of it sharing the geometry and the
 * plain materials. Its glowing materials are its own copies, so one ambulance's beacons or one patrol's
 * lightbar can flash without the rest. The template also carries a far body: the whole car merged at rest
 * into a mesh or two per kind of material, shown instead of its thirty-odd parts once it is small on screen.
 * Stock models' templates are kept for good; a livery's or a refit's go when the last car wearing it does.
 */
interface Template { mesh: VehicleMesh; users: number; keep: boolean }
const templates = new Map<VehicleDef, Template>();

export function trafficVehicleMesh(def: VehicleDef, keep: boolean): VehicleMesh {
  if (def.kind === 'rail') return buildVehicleMesh(def);
  let t = templates.get(def);
  if (!t) {
    const mesh = buildVehicleMesh(def);
    shadowFromBodyOnly(mesh);
    // the Wonder Ball and some toppers turn, and a topper's colours are its own (render/wonderBall.ts, render/toppers.ts):
    // a far body would stop the one and repaint the other
    if (!def.topper) addFar(mesh);
    t = { mesh, users: 0, keep };
    templates.set(def, t);
  }
  t.users++;
  const m = cloneMesh(t.mesh);
  m.shared = def;
  return m;
}

/**
 * A traffic car's shadow, from its body alone: its tyres and hubs (eight draws, tucked under the body's
 * own shadow), its glass and its lamps cast none. Traffic was ~80 of the shadow pass's draws (the lag
 * audit, Oct 2026); at the size traffic is seen, the body's shadow is the car's.
 */
function shadowFromBodyOnly(m: VehicleMesh): void {
  for (const tyre of m.wheels) tyre.traverse((o) => { o.castShadow = false; });
  m.holder.traverse((o) => {
    const mesh = o as THREE.Mesh;
    const mat = mesh.material as THREE.MeshStandardMaterial | undefined;
    if (!mesh.isMesh || !mat || Array.isArray(mat)) return;
    if (mat.transparent || (mat.emissiveIntensity > 0 && mat.emissive && mat.emissive.getHex() !== 0)) mesh.castShadow = false;
  });
}

/** How many shared bodies are held, and how many cars wear them: pr.bodies(). */
export function sharedBodies(): { models: number; cars: number } {
  let cars = 0;
  for (const t of templates.values()) cars += t.users;
  return { models: templates.size, cars };
}

/** Show a car's far body or its full one. */
export function setVehicleLod(m: VehicleMesh, far: boolean): void {
  if (!m.far || m.lod === far) return;
  m.lod = far;
  for (const o of m.near ?? []) o.visible = !far;
  for (const o of m.far) o.visible = far;
}

function cloneMesh(src: VehicleMesh): VehicleMesh {
  const holder = src.holder.clone(true);
  const a: THREE.Object3D[] = [], b: THREE.Object3D[] = [];
  src.holder.traverse((o) => a.push(o));
  holder.traverse((o) => b.push(o));
  const map = new Map<THREE.Object3D, THREE.Object3D>(a.map((o, k) => [o, b[k]]));
  const at = <T extends THREE.Object3D>(o: T): T => map.get(o) as T;
  const opt = <T extends THREE.Object3D>(o: T | undefined): T | undefined => (o ? at(o) : undefined);
  // its own copies of the glowing materials
  const mats = new Map<THREE.Material, THREE.MeshStandardMaterial>();
  holder.traverse((o) => {
    const mesh = o as THREE.Mesh;
    const m = mesh.material as THREE.MeshStandardMaterial;
    if (!mesh.isMesh || Array.isArray(mesh.material) || !m?.isMeshStandardMaterial || m.emissive.getHex() === 0) return;
    let c = mats.get(m);
    if (!c) { c = m.clone(); mats.set(m, c); }
    mesh.material = c;
  });
  const lit = [...mats.values()];
  return {
    holder, root: at(src.root), body: at(src.body), wheels: src.wheels.map(at), steerGroups: src.steerGroups.map(at),
    spinners: src.spinners.map((sp) => ({ ...sp, obj: at(sp.obj) })),
    trailer: opt(src.trailer), lift: src.lift, axles: src.axles?.map((x) => ({ obj: at(x.obj), y: x.y })),
    sail: opt(src.sail), jib: opt(src.jib), flag: opt(src.flag),
    roof: opt(src.roof), roofT: src.roof ? (roofUp() ? 0 : 1) : undefined,
    seats: src.seats?.map(at), seatDefault: src.seats ? Math.floor(Math.random() * (src.seats.length + 1)) : 0,
    gear: opt(src.gear), beacons: src.beacons?.map((m) => mats.get(m) ?? m), legs: src.legs?.map((l) => ({ obj: at(l.obj), phase: l.phase })),
    own: lit, lit, far: src.far?.map(at), near: src.near?.map(at), lod: false,
  };
}

/**
 * The far body: each posed part of the car (the root, and a trailer if it has one) gets a hidden child
 * holding everything under it merged at rest — wheels straight, body at its resting lift — one mesh per
 * kind of material, painted with vertex colours. What a far body would stop from moving is only the
 * wheels turning, the steering and the body's bob and lean, none of which shows on a car that small.
 * Anything with a part you would see stop — a convertible's roof and passengers, flashing beacons or a
 * lightbar, propellers and rotors, sails and flags, an undercarriage — gets no far body and always
 * wears its full one.
 */
function addFar(m: VehicleMesh): void {
  let lightbar = false;
  m.holder.traverse((o) => { const mat = (o as THREE.Mesh).material as THREE.Material | undefined; if (mat && !Array.isArray(mat) && (mat.userData?.lightbar || mat.userData?.strobe)) lightbar = true; });
  if (m.roof || m.seats?.length || m.gear || m.beacons?.length || m.spinners.length || m.sail || m.jib || m.flag || lightbar) return;
  const skip = new Set<THREE.Object3D>();
  const bodyY = m.body.position.y;
  m.body.position.y = m.lift ?? 0;
  const far: THREE.Object3D[] = [], near: THREE.Object3D[] = [];
  for (const top of [m.root, m.trailer]) {
    if (!top) continue;
    top.updateMatrixWorld(true);
    const inv = top.matrixWorld.clone().invert();
    const buckets = new Map<string, { mat: THREE.MeshStandardMaterial; geos: THREE.BufferGeometry[]; uv: boolean; shadow: boolean }>();
    const shown = (o: THREE.Object3D): boolean => { for (let p: THREE.Object3D | null = o; p && p !== top; p = p.parent) if (!p.visible) return false; return true; };
    top.traverse((o) => {
      const mesh = o as THREE.Mesh;
      const mat = mesh.material as THREE.MeshStandardMaterial;
      if (!mesh.isMesh || skip.has(mesh) || !shown(mesh) || Array.isArray(mesh.material) || !mat?.isMeshStandardMaterial) return;
      // plain paint is baked into vertex colours; anything textured or see-through keeps its own material
      const own = !!mat.map || mat.transparent;
      const key = own ? `u${mat.uuid}` : `${mat.roughness}|${mat.metalness}|${mat.emissive.getHex()}|${mat.emissiveIntensity}|${mat.side}|${mat.flatShading}`;
      let bk = buckets.get(key);
      if (!bk) {
        const out = own ? mat : new THREE.MeshStandardMaterial({
          vertexColors: true, roughness: mat.roughness, metalness: mat.metalness, emissive: mat.emissive.clone(),
          emissiveIntensity: mat.emissiveIntensity, side: mat.side, flatShading: mat.flatShading,
        });
        bk = { mat: out, geos: [], uv: !!mat.map, shadow: false };
        buckets.set(key, bk);
      }
      let g = mesh.geometry.clone().applyMatrix4(new THREE.Matrix4().multiplyMatrices(inv, mesh.matrixWorld));
      if (g.index) g = g.toNonIndexed();
      if (!g.attributes.normal) g.computeVertexNormals();
      const n = g.attributes.position.count;
      const col = own ? null : new Float32Array(n * 3);
      if (col) {
        const vc = mat.vertexColors ? (g.attributes.color as THREE.BufferAttribute | undefined) : undefined;
        for (let i = 0; i < n; i++) {
          col[i * 3] = mat.color.r * (vc ? vc.getX(i) : 1);
          col[i * 3 + 1] = mat.color.g * (vc ? vc.getY(i) : 1);
          col[i * 3 + 2] = mat.color.b * (vc ? vc.getZ(i) : 1);
        }
      }
      for (const name of Object.keys(g.attributes)) if (name !== 'position' && name !== 'normal' && !(bk.uv && name === 'uv')) g.deleteAttribute(name);
      if (bk.uv && !g.attributes.uv) g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(n * 2), 2));
      if (col) g.setAttribute('color', new THREE.BufferAttribute(col, 3));
      bk.geos.push(g);
      bk.shadow ||= mesh.castShadow;
    });
    const group = new THREE.Group();
    group.name = 'far';
    // the shadow of a car that small is its body's: only the biggest opaque part casts one, so the shadow
    // pass draws the far body once rather than once a material
    let caster: THREE.Mesh | null = null, most = 0;
    for (const bk of buckets.values()) {
      const merged = bk.geos.length === 1 ? bk.geos[0] : mergeGeometries(bk.geos, false);
      if (bk.geos.length > 1) bk.geos.forEach((g) => g.dispose());
      if (!merged) continue;
      const out = new THREE.Mesh(merged, bk.mat);
      out.castShadow = false;
      out.receiveShadow = false;
      group.add(out);
      const n = merged.attributes.position.count;
      if (bk.shadow && !bk.mat.transparent && n > most) { most = n; caster = out; }
    }
    if (caster) caster.castShadow = true;
    near.push(...top.children);
    group.visible = false;
    top.add(group);
    far.push(group);
  }
  m.body.position.y = bodyY;
  m.far = far;
  m.near = near;
}
