/**
 * TinyFleet Online: what the game and the public server say to each other. Imported by both sides;
 * nothing here touches the DOM or Node.
 *
 * The shape of it (docs/multiplayer.html, as built): the world is never sent. Every client generates the
 * cells round its player from the one seed; the server keeps what people have changed about each cell
 * (the edit log, the earthworks, the towns' books, who owns which door) and hands it to whoever comes
 * near. A cell's towns are run by one of the games near it, its host, which sends the books back; so a
 * cell nobody is near does nothing at all, and with nobody signed in the clock itself stands still.
 */

import type { WorkKind } from './community';
import type { Renames } from './names';
import type { DriftRow, GuestRow, HolderRow, LapRow, MarkNews, MarksWelcome, Picks, SignMsg, SignRow } from './marks';
import type { CardPose, Postcard } from './postcards';
import type { FrontierInfo, ReachRow } from './range';
import type { ChalBoard, ChalNews, ChalRow } from './challenges';
import type { RushBoard } from './rushes';
import type { CrewMember, CrewMeta, CrewView, RosterChange, WireDriver, WireUnit } from './fleets';
import type { HolderBoard } from './records';
import type { LeagueBookMsg } from './leagues';
import type { CultureBookMsg, CultureReport } from './culture';
import type { TownsMsg, TownsPage } from './towns';
import type { Counts, CrewPolicy, CrownMine, CrownRow, GoodsBoardKind, GoodsRow, GoodsSummary, InboxItem, Inviters, Joining, NeighbourRow, Profile, TitleId, TitleRow } from './social';

/**
 * Bumped whenever a message changes shape: a client and a server that differ refuse each other. 2: guests and one-click
 * fleets (docs/postcards.html). 3: shared fleets (docs/sharedfleets.html): a game from before them would play a shared
 * fleet's member from its own stale career, so it is asked to reload instead. 4: blueprints (docs/blueprints.html): the
 * `erect` edit, which a game from before it would not know how to lay.
 */
export const PROTOCOL = 5;

/** Cells either way of a player that their plain chat carries to. */
export const CHAT_CELLS = 8;
/** A new fleet's home is within this many cells of the origin… */
export const SPAWN_REACH = 64;
/** …and, when anyone is signed in, within this many of one of them. */
export const SPAWN_NEAR = 8;
/** Cells either way of a player whose vehicles they are sent. */
export const SEE_CELLS = 2;
/** Positions a second, from each game and to each game. */
export const MOVE_HZ = 10;
/** The longest a chat line may be. */
export const CHAT_MAX = 240;
/** Game hours in a real second: the server's clock, and only while somebody is signed in. */
export const HOURS_PER_SECOND = 1 / 25;

/** A player's id on the wire: "p:12". Also how a player's fleet is named in a town's carriage. */
export type Pid = string;
export const isPid = (s: string): boolean => s.startsWith('p:');

export const cellKey = (cx: number, cz: number): string => `${cx},${cz}`;
export const cellOfKey = (k: string): [number, number] => k.split('#')[0].split(',').map(Number) as [number, number];

/** A fleet's livery, as the game keeps it (game/brand.ts). */
export interface Brand { name: string; primary: number; accent: number; logo: string }

/** Who somebody is, for name tags, chat, the towns' carriage and the doors they own. */
export interface Who { id: Pid; name: string; brand: Brand | null }

/**
 * A door a player owns: who, what it is called, the most it may take in a game day, its grade when it is
 * their HQ, and the ground its buildings stand on, [x, z, w, d] in the cell's tiles, which nobody else may bulldoze.
 */
export interface DeedRow { by: Pid; name: string; ceil: number; hq?: number; rects?: [number, number, number, number][] }

/** A town's carriage as saved (game/carriage.ts): [hour, preferred, since, { carrier: dollars }]. */
export type CarriageRow = [number, string, number, Record<string, number>];

/**
 * A work's public numbers (docs/community.html): hearts, crossings by other fleets, how many fleets those
 * were, its builder's name for it, and `l` once it has been listed (it stays listed).
 */
export interface WorkRow { h: number; u: number; f: number; name?: string; l?: 1; sg?: Suggestion[] }

/** A name another player suggested for a work (docs/marks.html): the words, whose, and who has voted for it. */
export interface Suggestion { text: string; by: Pid; v: Pid[] }

/** A line on the World tab: one work, whose and how loved. `len` in tiles (or lifts for a landform), `at` the game hour it was built, `t` a tile of it to fly to. */
export interface WorkLine { k: string; kind: WorkKind; name?: string; by: Pid; h: number; u: number; f: number; len?: number; at?: number; t?: number;
  /** A project of several works near each other (shared/community.ts groupNear): how many, their hearts and crossings added up. Additive. */
  parts?: number }

/**
 * A landform the server knows (shared/community.ts landFeatures), by id "F3": who dug most of it, what it
 * reads as, its lifts, the tile its name goes on, and a few of its tiles, by which it is known again
 * after more digging grows, joins or splits it.
 */
export interface FeatureRow { by: Pid; kind: WorkKind; lifts: number; top: number; s: number[] }

/** A work of mine that was hearted while I was away: how many, and by whom (fleet names, the first few). */
export interface AwayItem { k: string; kind: WorkKind; name?: string; h: number; from: string[] }

/** A player's community totals, kept on their record across worlds: hearts received, crossings of their works, tracks blazed, fleets hearted, works listed and works built. */
export interface CommunityStats {
  loved: number; uses: number; blazed: number; gave: number; listed: number; works: number;
  /**
   * Likes to spend (4 Oct 2026; nothing spends them yet): one for every heart another player leaves on a
   * work of yours and every thumbs-up on a sign of yours, one back when they take it back. Never from yourself.
   */
  likes?: number;
}

/**
 * One change to a player's likes, kept on their record (server/community.ts) for the HQ's Hearts tab: when (ms),
 * how many (+1, −1 taken back, +5 for a postcard ride), why, on what, and from whom.
 */
export interface LikeEntry { t: number; n: number; why: 'heart' | 'sign' | 'postcard'; what?: string; who?: string; k?: string }

/** What happened to a player's works while they were away. */
export interface AwayNews { hearts: number; uses: number; listed: number; tracks: number; items?: AwayItem[]; wearing?: number }

/** Everything shared about one cell. Keys inside are the game's own: town keys "cx,cz#id", lot keys "cx,cz#b12". */
export interface CellDoc {
  /** The edit log (world/delta.ts), in the order the server took them; each carries `by`, and `at`, the game hour it came. */
  edits: unknown[];
  /** Works' hearts and crossings, by id within the cell ("r1x9k2", "r1x9k2.0", "L37", "W37", "b12"). */
  social?: Record<string, WorkRow>;
  /** Who moved each chunk's ground: the biggest diggers first, with their lifts. */
  landBy?: Record<string, [Pid, number][]>;
  /** The landforms big enough to be works, by id ("F3"), and the last id given. */
  features?: Record<string, FeatureRow>;
  fseq?: number;
  /** Passes per tile of open ground, by chunk (shared/community.ts encodePasses). */
  paths?: Record<string, string>;
  /** The fleets that have worn each chunk: the first is its trailblazer. */
  pathsBy?: Record<string, Pid[]>;
  /** Chunks a beaten track has already been announced in. */
  beaten?: number[];
  /** Chunks whose trailblazer has been told their line is wearing in (stage 2). */
  worn?: number[];
  /** The server's own: which fleets have crossed each work. Never sent. */
  usedBy?: Record<string, Pid[]>;
  /** Earthworks by 16×16 chunk (world/landCodec.ts). */
  land?: Record<string, string>;
  towns?: Record<string, unknown>;
  lots?: Record<string, number[]>;
  carriage?: Record<string, CarriageRow>;
  /** The rival firms whose home this is, as they save (game/firms.ts), by id. */
  firms?: Record<string, unknown>;
  deeds?: Record<string, DeedRow>;
  /** Marks (docs/marks.html): signs by id ("s14") and the last id given. */
  signs?: Record<string, SignRow>;
  sseq?: number;
  /** The longest drift in each chunk, by chunk. */
  drifts?: Record<string, DriftRow>;
  /** The best hot lap at each circuit, by its building's uid; the ghost is left out of the cell as sent. */
  laps?: Record<string, LapRow>;
  /** Each circuit's lot as an updated game reports it ([x, z, w, d, facing], island tiles), for checking its record's ghost (server/marks.ts). */
  tracks?: Record<string, number[]>;
  /** HQ guestbooks, by lot id ("b12"). */
  guests?: Record<string, GuestRow>;
  /** Who has held each town as territory, by town key. */
  holders?: Record<string, HolderRow>;
  /**
   * Range (docs/exploration.html): when the server first made this document (ms), and the first fleet ever to
   * set foot in the cell. A document from before range has no `born`: somebody was near it already, so it has no First Footing to give.
   */
  born?: number;
  first?: { by: Pid; at: number };
}

/**
 * A vehicle where it is: cell, tile in the cell, height, heading, speed, pitch, roll, and `t`, the sender's
 * own clock in milliseconds when it was there (Oct 2026: the others are drawn on the sender's timeline, not
 * by when the beat happened to arrive). A game from before `t` sends nine and is drawn as before.
 */
export type Pose = [cx: number, cz: number, x: number, z: number, y: number, heading: number, v: number, pitch: number, roll: number, t?: number];

/** One county of a far run's route (docs/crewtrains.html): entered by side `enter`, left by `exit` (world/rail.ts numbering); -1 the far station in it. */
export interface FarCell { cx: number; cz: number; enter: number; exit: number }

/**
 * A crewed train's far run as it is sent and saved (docs/crewtrains.html, Long haul): the route of the leg it is on,
 * the seconds one county takes, and the seconds into the leg. Sent once a leg (and now and then again), so a game
 * near any county on the route draws a stand-in on its own track at the place the clock gives.
 */
export interface FarWire {
  uid: number;
  /** The set (rollingStock.ts SETS id), the unit's name, and its cars as they left. */
  m: string; n: string; ids: string[];
  cells: FarCell[];
  /** Seconds to run one county (a half for one the far station is in). */
  spc: number;
  /** Seconds into this leg. */
  t: number;
  /** Seconds it stands at the far station at the end of the way out (0 on the way back). */
  dwell: number;
}

/** One of a player's vehicles as others draw it: the model, its parts as saved, and where it is parked if it is. */
export interface UnitLook { uid: number; m: string; p?: unknown; at?: [number, number, number, number, number, number] }
/**
 * What a player is driving and what else of theirs is out on the map. `d`: where the goods aboard the vehicle
 * they drive are going, flat [x, y, z, value] in world tiles, so whoever follows them sees the same green rings.
 */
export interface Look {
  m: string; p?: unknown; units: UnitLook[]; d?: number[];
  /**
   * The Passport's treats this fleet shows (game/treats.ts), each left out when not: `g` the Gilded Fleet's gold (1 trim,
   * 2 whole), `hs` the town style its HQ is dressed in, `em` the visa emblem round its badge (a deeds group), `fp` the
   * Front-row pass on its badge, `np` the gilded nameplate on its HQ. Older games send none and ignore them.
   */
  g?: 1 | 2; hs?: string; em?: string; fp?: 1; np?: 1;
}
/** The most destinations a look carries. */
export const LOOK_DROPS = 16;

/**
 * A friend as the server tells it: who, whether signed in and in which cell, and their HQ's lot when
 * they have one ("cx,cz#b12", its name). `mutual` when they have added you back.
 */
export interface FriendRow { id: Pid; name: string; brand: Brand | null; online: boolean; c?: string; hq?: { key: string; name: string }; mutual: boolean }

/** The most friends one player may keep. */
export const FRIENDS_MAX = 100;

/** One line of the leaderboard. */
/** A fleet's line on the leaderboard. `v` is every metric its game keeps (game/metrics.ts MetricKey), for the Standings window. */
export interface BoardRow {
  id: string; name: string; cpu: boolean; worth: number; units: number; towns: number; primary: number; accent: number; logo: string; online?: boolean; by?: string; v?: Record<string, number>; hearts?: number; works?: number;
  /** A player's line: when their game last saved it (Date.now() ms), their net worth by game day newest first (up to 14) from day `hd`, and their shared fleet's id. */
  seen?: number; hist?: number[]; hd?: number; crew?: string;
  /** A player's HQ in this world, so anyone can go and look at it (not only friends). */
  hq?: { key: string; name: string };
  /** For the fleet card (docs/social.html): the goods it moves most, its vehicles as last saved, and its motto. */
  goods?: [string, number][]; fleet?: { m: string; n: string }[]; motto?: string;
  /** Who sees where they are, when not everyone (their profile's where); and, from a game's save only, every cargo kind's loads and every culture's units (kept apart by the server for the cargo and culture boards, never sent on). */
  wh?: 'friends' | 'hidden'; gA?: Record<string, number>; cA?: Record<string, number>;
  /** From a game's save only, as gA and cA: loads delivered and dollars earned in each vehicle model (the vehicle boards, 5 Nov 2026). Additive: an older game sends none. */
  vA?: Record<string, number>; eA?: Record<string, number>;
}

// ---- client → server -----------------------------------------------------------------------------

export type ClientMsg =
  /**
   * Sign in, or with `create` make a fleet. `create.auto`: made in one click from a postcard (docs/postcards.html),
   * no name or PIN asked: the server names it, and it is kept on this device by its token until the player keeps it.
   * `guest`: no fleet at all, only to watch (see GUEST below).
   */
  | { t: 'hello'; v: number; gen: number; name?: string; pin?: string; token?: string; create?: { brand: Brand; auto?: true; from?: string; /** the title's Play as guest (6 Nov 2026), counted apart from postcards; additive */ guest?: true }; guest?: true;
    /** An invite to a shared fleet this game was opened with (docs/sharedfleets.html): the welcome names the fleet, and the player is asked. */
    invite?: string }
  /** A fleet made in one click takes a name and a PIN of its own. */
  | { t: 'keep'; name: string; pin: string }
  /** A new fleet whose home cell turned out to have no town to start in: another, please. */
  | { t: 'reroll' }
  /** The cells this game has in memory (or is building). */
  | { t: 'sub'; cells: string[] }
  /** Where I am, and my working vehicles: [uid, ...pose]. */
  | { t: 'm'; p: Pose; f?: [number, ...Pose][] }
  | { t: 'look'; look: Look }
  /** One of my crewed trains on a far run (docs/crewtrains.html): its route and clock, or null when it is back. */
  | { t: 'far'; uid: number; w: FarWire | null }
  | { t: 'brand'; brand: Brand }
  /** An edit I made to a cell. `lot` is the door a bulldozed tile belonged to. */
  | { t: 'edit'; c: string; e: unknown; lot?: string }
  /** Earthworks: chunks of a cell as they now stand (null: back to the generator's). */
  | { t: 'land'; c: string; chunks: Record<string, string | null> }
  /** From a cell's host: what changed on its books since the last of these. null removes. */
  | { t: 'state'; c: string; towns?: Record<string, unknown>; lots?: Record<string, number[]>; carriage?: Record<string, CarriageRow>; firms?: Record<string, unknown | null> }
  /** From a guest: trade of mine in a town somebody else's game is running. */
  | { t: 'credit'; town: string; amt: number; lot?: string; lotAmt?: number; dir?: 'in' | 'out'; rent?: boolean }
  /** Doors I hold now and no longer hold. */
  | { t: 'deeds'; set?: Record<string, { name: string; ceil: number; hq?: number; rects?: [number, number, number, number][] }>; del?: string[] }
  /** Trade at other players' doors, dollars gross by lot key. */
  | { t: 'rent'; k: Record<string, number> }
  /** My career, to keep; and my fleets' lines for the leaderboard. */
  /** The career: as it is, or `z`, gzipped JSON in base64 (a big one: the server unzips it and keeps it as if sent plain). */
  | { t: 'record'; record?: unknown; z?: string; board?: { me: Omit<BoardRow, 'id' | 'cpu' | 'online'>; cpu: BoardRow[] } }
  | { t: 'chat'; text: string }
  /**
   * A Passport page filled to the last stamp (game/passportRewards.ts SealId): told to the players near, and the
   * whole book ('book', the Gilded Fleet) to everyone signed in. Once a seal a player.
   */
  | { t: 'sealed'; s: string }
  /** Range (docs/exploration.html): where this career's home is, world tiles (kept by the server the first time), and a model's board, please. */
  | { t: 'rhome'; x: number; z: number }
  | { t: 'reach'; m: string }
  /**
   * PvP Challenges (docs/challenges.html, 0.7.0): a line I can see (a ChalSite; the server keeps the one most fleets send)
   * and its board, please; boards for the Challenges tab (with mine and the ones I hold); the holder's ghost; go from the
   * line (`at`, my own clock as my poses carry it); and a run given up.
   */
  | { t: 'chalSite'; site: unknown }
  | { t: 'chalBoards'; ids?: string[] }
  | { t: 'chalGhost'; id: string }
  | { t: 'chalGo'; site: unknown; at: number }
  | { t: 'chalStop'; id: string }
  /**
   * Rushes (docs/rushes.html, phase 3): boards for these rushes (with mine and the ones I hold), please; a run started
   * (its length, clock and the hold it started with); each delivery as it lands (`crew` one of my drivers'); and the bell.
   */
  | { t: 'rushBoards'; keys?: string[] }
  | { t: 'rushGo'; key: string; name: string; kind: string; len: number; secs: number; hold: number }
  | { t: 'rushDrop'; key: string; n: number; crew?: boolean }
  | { t: 'rushEnd'; key: string; units: number; solo: boolean; v: number }
  /** The HQ's Hearts tab: my likes' recent history and lifetime by source, please. */
  | { t: 'likesLog' }
  /** Add (on) or drop a friend; the server answers with the list. */
  | { t: 'friend'; id: Pid; on: boolean }
  /** My friends as they stand now, please. */
  | { t: 'friends' }
  /** How others see me (docs/social.html): set what is given, and either way the server answers with my profile. */
  | { t: 'profile'; set?: Partial<Profile> }
  /** Another fleet's card: their profile and what goes with it. */
  | { t: 'card'; id: Pid }
  /** The dealings ledger (docs/social.html): me and one other fleet, both ways; and every fleet I have dealings with. */
  | { t: 'pair'; id: Pid }
  | { t: 'neighbours' }
  /** I drove past this door ("cx,cz#b12") today; I have driven a minute beside this player. */
  | { t: 'call'; k: string }
  | { t: 'beside'; id: Pid }
  /**
   * The inbox (docs/social.html, phase 3): a note left for a player, my inbox, a thread read, a player muted or not,
   * and a report of one to the developer. Asks and invites: invite a player into my fleet by name, ask to join a
   * player's fleet, answer an ask (founder or officer), make a member an officer or a member or hand founding over,
   * and set how the fleet is joined and who may invite.
   */
  | { t: 'note'; to: Pid; text: string }
  | { t: 'inbox' }
  | { t: 'read'; id: string }
  | { t: 'mute'; id: Pid; on: boolean }
  | { t: 'reportPlayer'; id: Pid; text?: string }
  | { t: 'crewInvite'; id: Pid; text?: string }
  | { t: 'crewAsk'; id: Pid; text?: string }
  | { t: 'crewAnswer'; id: Pid; ok: boolean }
  | { t: 'crewRole'; id: Pid; role: 'officer' | 'member' | 'founder' }
  | { t: 'crewPolicy'; joining?: Joining; invites?: Inviters }
  /**
   * Phase 4: the week's titles (live and last week's holders) and the lifetime board; a heart on a whole fleet;
   * a minute my camera followed another player's vehicle; the cargo and culture boards, all kinds at a glance or one in full.
   */
  | { t: 'titles' }
  | { t: 'fleetHeart'; id: Pid; on: boolean }
  | { t: 'watched'; id: Pid }
  | { t: 'goodsBoards'; k: GoodsBoardKind }
  | { t: 'goodsBoard'; k: GoodsBoardKind; kind: string }
  /** The crowns (docs/toppers.html phase 2): every podium (`all`), or only what my fleet holds. */
  | { t: 'crowns'; all?: boolean }
  /**
   * The world's league book (server/leagues.ts): a watched game's score, clubs as met, the fixtures this game plays live
   * now (all of them each time). Nothing in it: send me the whole book.
   */
  | ({ t: 'league' } & Omit<LeagueBookMsg, 'full'>)
  /** The world's culture book (server/townCulture.ts): my fleet's own parts in the towns it has written in. Nothing in it: send me the whole book. */
  | ({ t: 'culture' } & Partial<CultureReport>)
  /** The world gazetteer (server/gazetteer.ts, docs/townregister.html): my islands' towns to keep, or a page of the World scope to send me. */
  | ({ t: 'towns' } & TownsMsg)
  /** The camera is watching this cell (a friend, their HQ): send me who moves round it too. null: back to me. */
  | { t: 'watch'; c: string | null }
  | { t: 'board' }
  /** Community (docs/community.html): a heart on a work ("cx,cz#r1x9k2"), or taken back. */
  | { t: 'heart'; k: string; on: boolean }
  /** Open ground I drove over in a cell since the last of these (tile indices), and other players' works I crossed. */
  | { t: 'tread'; c?: string; tiles?: number[]; use?: string[] }
  /** A name for a work of mine ('' takes it off). */
  | { t: 'name'; k: string; text: string }
  /** A work's name is not fit to show: for the developer's page. */
  | { t: 'report'; k: string }
  /** The World tab's lists, please. */
  | { t: 'works' }
  /** Marks (docs/marks.html): a sign put up on a tile of a cell, or one of mine taken down. */
  | { t: 'sign'; c: string; tile: number; m: SignMsg }
  | { t: 'unsign'; c: string; id: string }
  /** A sign rated: 1 up, -1 down, 0 taken back. */
  | { t: 'rate'; c: string; id: string; v: 1 | 0 | -1 }
  /** A drift slid in a chunk: tiles, and its line (island tiles × 4). */
  /** A drift record: its score, its line, and (since the title's picks show it) the model it was made in. */
  | { t: 'drift'; c: string; s: number; p: number[]; m?: string }
  /** A clean hot lap at a circuit: seconds, the model, its ghost, and a tile of the circuit's (for the week's picks to fly to). */
  /** `lot`: the circuit's lot ([x, z, w, d, facing]), its ghost checked against it: a lap without one isn't recorded. */
  | { t: 'lap'; c: string; k: string; s: number; m: string; g: string; at?: number; lot?: number[] }
  /** A circuit's record ghost, please. */
  | { t: 'ghost'; c: string; k: string; lot?: number[] }
  /** I stopped at another player's HQ: their guestbook, signed with a stamp (STAMPS). */
  | { t: 'guest'; k: string; stamp: number }
  /** To the fleet that took a town from me: GG, or I'll be back. */
  | { t: 'gg'; to: Pid; town: string; back?: boolean }
  /** A name suggested for another player's work; a vote for a suggestion (by its suggester); the builder taking one. */
  | { t: 'suggest'; k: string; text: string }
  | { t: 'vote'; k: string; by: Pid; on: boolean }
  | { t: 'accept'; k: string; by: Pid }
  /** The week's picks, please. */
  | { t: 'picks' }
  /**
   * Postcards (docs/postcards.html): a new one where the camera stands (no `id`), or one of mine moved or
   * retitled. `ask` comes back on the answer.
   */
  | { t: 'postcard'; ask: number; id?: string; pose?: CardPose; title?: string }
  | { t: 'unpost'; id: string }
  /** A postcard of mine's picture, its link preview: base64 of a small JPEG (POSTCARD.picMax at most). */
  | { t: 'postcardPic'; id: string; jpg: string }
  /** My postcards, please. */
  | { t: 'postcards' }
  /**
   * Shared fleets (docs/sharedfleets.html). The fleet's invite code, please (made on first asking, from my career as it
   * was last kept: a fleet of my own becomes a shared one of one). Yes to the invite my welcome carried. The creator
   * boots a member; a member leaves.
   */
  | { t: 'invite' }
  | { t: 'join'; code: string }
  | { t: 'boot'; id: Pid }
  | { t: 'leaveCrew' }
  /** Money in (+) or out (−) of the shared purse since the last of these, numbered so the answer can say which it has counted. */
  | { t: 'purse'; d: number; s: number }
  /** My game's changes to the shared roster: vehicles (as saved) and drivers changed or gone, buildings bought or sold, the HQ's terms. */
  | { t: 'roster'; units?: WireUnit[]; gone?: number[]; drivers?: WireDriver[]; fired?: number[]; estate?: Record<string, unknown>; sold?: string[]; meta?: CrewMeta }
  | { t: 'bye' };

// ---- server → client -----------------------------------------------------------------------------

export type RefuseCode = 'version' | 'gen' | 'new' | 'pin' | 'locked' | 'name' | 'elsewhere' | 'full' | 'bad' | 'booted';

export interface Welcome {
  t: 'welcome';
  you: Who;
  /** A fleet made in one click and not yet kept (no PIN): it lives on this device by its token. */
  auto?: true;
  /** The fleet's renames so far (shared/names.ts), when it has had any: the fleet editor says when the next may be. */
  renames?: Renames;
  world: { seed: string; gen: number; hours: number };
  /** The career as last kept, or null for a fleet that has never played. */
  record: unknown | null;
  home: [number, number];
  token: string;
  /** What the doors took in while their owner was away. */
  owed: number;
  online: { who: Who; c: string; look?: Look }[];
  /** Community: the works I have hearted, my totals, and what happened to my works while I was away. */
  community?: { hearts: string[]; s: CommunityStats; away: AwayNews | null };
  /** Marks: news about mine since last time, and who paid rent at my doors. */
  marks?: MarksWelcome;
  /** The shared fleet this player is in (docs/sharedfleets.html); missing for a fleet of their own. */
  crew?: CrewView;
  /** The invite the game signed in with, to be asked about before the world loads: the fleet's name and livery, and how many are in it (`why`: it can't be joined). */
  offer?: { code: string; name: string; brand: Brand | null; members: number; why?: string };
  /** Where to start, having just joined: [cx, cz, x, z] in that cell's tiles (the fleet's HQ, or beside a member). */
  spawn?: [number, number, number, number];
  /** Range (docs/exploration.html): the home this career's records are measured from (world tiles), once the server keeps one, and the world's frontier. */
  rhome?: [number, number];
  frontier?: FrontierInfo;
  /** PvP Challenges (docs/challenges.html): the boards I hold, the ones I am on, and boards taken from me while away. */
  chal?: { held: string[]; on: string[]; news: ChalNews[] };
  /** Rushes (docs/rushes.html): the Fleet boards I hold. */
  rush?: { held: string[] };
  /** This server says 'saved' back for every career it keeps: the game watches for it (net/online.ts). */
  acks?: 1;
}

export type ServerMsg =
  | Welcome
  /** A career kept (the 'record' just sent), and when: the game's proof its saves are landing (the user, 23 Oct 2026). */
  | { t: 'saved'; at: number }
  | { t: 'refuse'; code: RefuseCode; why: string }
  | { t: 'home'; home: [number, number] }
  /** A cell's shared state, on subscribing to it; who is running it; and everyone its doors and books name. */
  | { t: 'cell'; c: string; doc: CellDoc; host: Pid; people: Who[] }
  | { t: 'host'; c: string; host: Pid }
  | { t: 'edit'; c: string; e: unknown }
  | { t: 'land'; c: string; chunks: Record<string, string | null> }
  | { t: 'state'; c: string; towns?: Record<string, unknown>; lots?: Record<string, number[]>; carriage?: Record<string, CarriageRow> }
  | { t: 'credit'; town: string; by: Pid; amt: number; lot?: string; lotAmt?: number; dir?: 'in' | 'out'; rent?: boolean }
  | { t: 'deed'; key: string; row: DeedRow | null; who?: Who }
  /** A door I claimed is somebody else's: mine is void and refunded. */
  | { t: 'deedDeny'; key: string; who: Who }
  /** Refused. A fleet's look ('brand': a rename refused, or not the founder's) comes back as kept, to put back on. */
  | { t: 'deny'; what: string; c?: string; why: string; brand?: Brand }
  /** The fleet was renamed: its renames so far, for the fleet editor's wait (shared/names.ts). */
  | { t: 'renames'; renames: Renames }
  /** Rent taken at one of my doors; `from`, the fleet whose trade it was. */
  | { t: 'rent'; key: string; amt: number; from?: Pid }
  /** Everyone near: [pid, ...pose] and their working vehicles [pid, uid, ...pose]. */
  | { t: 'mv'; a: [Pid, ...Pose][]; f: [Pid, number, ...Pose][] }
  | { t: 'look'; id: Pid; look: Look }
  /** A player's crewed train on a far run, or null when it is back (docs/crewtrains.html): drawn as a stand-in where near. */
  | { t: 'far'; id: Pid; uid: number; w: FarWire | null }
  | { t: 'on'; who: Who; c: string; look?: Look }
  | { t: 'off'; id: Pid }
  /** The clock, and the cell everyone is in. */
  | { t: 'tick'; hours: number; at: Record<Pid, string> }
  /** `alert`: from the server to everyone, in red (a restart coming: server/handover.ts). */
  | { t: 'chat'; kind: 'say' | 'w' | 'wto' | 'sys' | 'alert'; from?: Pid; name?: string; to?: string; text: string }
  | { t: 'board'; rows: BoardRow[] }
  /** My likes' history (newest last), lifetime by source since `since` (ms, when the record began), and my totals. */
  | { t: 'likesLog'; log: LikeEntry[]; by: Record<string, number>; since: number; s: CommunityStats }
  /**
   * Range (docs/exploration.html): the home the server keeps for this career; a model's board (top lines, my own
   * line, how many have one, and every model with a board); the first fleet into a cell (to everyone holding it,
   * and to that fleet); the world's frontier as it now stands; and a frontier bounty won.
   */
  | { t: 'rhome'; x: number; z: number }
  | { t: 'reach'; m: string; rows: ReachRow[]; you: ReachRow | null; n: number; models: string[] }
  | { t: 'first'; c: string; who: Who; sea?: boolean }
  | { t: 'frontier'; f: FrontierInfo }
  | { t: 'bounty'; ring: number; prize: number; who: Who }
  /**
   * PvP Challenges (docs/challenges.html): a board; boards for the tab and the ones I hold; the holder's ghost; the go
   * (the server's start, my clock); a run's result as the server measured it (`why` when it didn't count); the boards I
   * hold now; and one taken from me.
   */
  | { t: 'chalBoard'; b: ChalBoard }
  | { t: 'chalBoards'; rows: ChalBoard[]; held: string[] }
  | { t: 'chalGhost'; id: string; g: string; by: Pid; s: number; m: string }
  | { t: 'chalGo'; id: string; go: number }
  | { t: 'chalRes'; id: string; ok: boolean; why?: string; s?: number; best?: number; rec?: boolean; place?: number; n?: number; top?: ChalRow | null; held?: boolean }
  | { t: 'chalHeld'; held: string[] }
  | { t: 'chalLost'; n: ChalNews; who?: Who }
  /** Rushes (docs/rushes.html): boards (and the game year now); a run's result (`why` when it didn't count); the Fleet boards I hold now, and one I lost. */
  | { t: 'rushBoards'; rows: RushBoard[]; held: string[]; year: number }
  | { t: 'rushRes'; key: string; ok: boolean; why?: string; rec?: boolean; b?: RushBoard; held?: boolean }
  | { t: 'rushHeld'; held: string[]; lost?: string }
  | { t: 'friends'; rows: FriendRow[] }
  /** A fleet's card (docs/social.html): whose, how they show themselves, when the fleet was founded (ms), and their shared fleet's members. */
  | { t: 'card'; id: Pid; profile: Profile; founded: number; crew?: { id: Pid; name: string; online: boolean }[];
    /** The fleets they deal with most (unless they hide it): a player to open and the fleet's name. */
    top?: { id: Pid; name: string }[];
    /** Phase 4: hearts on the whole fleet, whether I have left one, and whether they let me see where they are. */
    fh?: number; hearted?: boolean; whereOk?: boolean }
  /** Me and one other fleet: what each did toward the other, all time and lately, and the towns we both carry for (keys). */
  | { t: 'pair'; id: Pid; o: Counts; i: Counts; lo: Counts; li: Counts; towns: string[] }
  | { t: 'neighbours'; rows: NeighbourRow[] }
  /** My inbox as it stands, and who I have muted; sent when asked and whenever something arrives. */
  | { t: 'inbox'; items: InboxItem[]; muted: { id: Pid; name: string }[] }
  /** A word on something I asked for (a note left, an invite sent, an ask made): shown in the social window. */
  | { t: 'inboxSay'; text: string; ok: boolean; code?: string }
  /** The titles: this week's leaders as they stand, last week's holders (worn this week), and the lifetime board. */
  | { t: 'titles'; live: TitleRow[]; last: TitleRow[]; lifetime: { who: Pid; ids: Pid[]; name: string; n: Partial<Record<TitleId, number>> }[] }
  | { t: 'goodsBoards'; k: GoodsBoardKind; rows: GoodsSummary[] }
  | { t: 'goodsBoard'; k: GoodsBoardKind; kind: string; rows: GoodsRow[]; you: { n: number; place: number } | null; fleets: number }
  /** The crowns my fleet holds and its Crown Roll; every podium too when asked for (`rows`). Sent again whenever mine change. */
  | { t: 'crowns'; held: CrownMine[]; roll: CrownMine[]; rows?: CrownRow[]; more?: string[]; boards?: HolderBoard[] }
  /** The world's league book: all of it (`full`, when asked), then scores and clubs as they come and every game's live fixtures. */
  | ({ t: 'league' } & LeagueBookMsg)
  /** The world's culture book: all of it (`full`, when asked), then each town as any fleet changes it. */
  | ({ t: 'culture' } & CultureBookMsg)
  /** A page of the town register's World scope (server/gazetteer.ts), answering a `towns` ask. */
  | ({ t: 'towns' } & TownsPage)
  /** A work's numbers have changed (to everyone holding its cell); `from` and `on` when it was a heart. */
  | { t: 'social'; k: string; row: WorkRow | null; from?: Who; on?: boolean }
  /** Passes on some chunks of a cell have reached a new stage, and who has worn them. */
  | { t: 'paths'; c: string; chunks: Record<string, string>; by: Record<string, Pid[]> }
  /** Who moved the ground of some chunks of a cell, and the cell's landforms as they now stand. */
  | { t: 'landBy'; c: string; rows: Record<string, [Pid, number][]>; features?: Record<string, FeatureRow> }
  /** Something about a work of mine: a heart, a listing, a track I blazed beaten in, a crossing milestone. */
  | { t: 'nice'; what: 'heart' | 'listed' | 'track' | 'uses' | 'wearing'; k: string; from?: Who; n?: number; name?: string }
  /** My community totals, and the works I have hearted, after a change. */
  | { t: 'cstats'; s: CommunityStats; hearts?: string[] }
  | { t: 'works'; loved: WorkLine[]; busy: WorkLine[]; fresh: WorkLine[] }
  /** Marks (docs/marks.html), to everyone holding the cell: a sign as it stands now (null: gone). */
  | { t: 'signRow'; c: string; id: string; row: SignRow | null }
  /** A chunk's drift record, a circuit's lap record (no ghost), an HQ's guestbook, a town's holders. */
  | { t: 'driftRow'; c: string; k: string; row: DriftRow }
  /** `row` null: the record was taken away (its ghost cut the track: server/marks.ts). */
  | { t: 'lapRow'; c: string; k: string; row: LapRow | null }
  | { t: 'guestRow'; c: string; k: string; row: GuestRow; from?: Pid }
  | { t: 'holderRow'; c: string; town: string; row: HolderRow }
  /** A circuit's record ghost. */
  | { t: 'ghost'; c: string; k: string; g: string; by: Pid; s: number }
  /** Something about a mark of mine, as it happens. */
  | { t: 'mark'; n: MarkNews; who?: Who }
  | { t: 'picks'; picks: Picks }
  /** A guest's welcome: the world, and who is signed in (to be drawn), and how many. */
  | { t: 'guest'; world: { seed: string; gen: number; hours: number }; online: { who: Who; c: string; look?: Look }[]; players: number }
  /** A fleet kept (its new name), or not (`why`). */
  | { t: 'kept'; you: Who | null; why?: string }
  /** A postcard made or changed (its id), or refused (`why`), answering the `ask` it came with. */
  | { t: 'postcard'; ask: number; id: string | null; why?: string }
  | { t: 'postcards'; rows: Postcard[] }
  /** Shared fleets: the invite code (null, and `why`, when there is none to give); who is in the fleet and its livery, after a change. */
  | { t: 'invite'; code: string | null; why?: string }
  | { t: 'crew'; id: string; creator: Pid; brand: Brand | null; members: CrewMember[]; officers?: Pid[]; policy?: CrewPolicy; week?: Record<Pid, number> }
  /** The shared purse as it stands; `s`, the last of my own changes it has counted. */
  | { t: 'purse'; cash: number; s?: number }
  /** Other members' changes to the roster, and (`back`) mine that were refused, as the server has them instead. */
  | ({ t: 'roster'; back?: true } & RosterChange)
  /** Having said yes to an invite: the welcome again, as a member (or why not). */
  | { t: 'joined'; welcome: Welcome | null; why?: string }
  | { t: 'saved' };

/**
 * Guests (docs/postcards.html, phase 3): someone who opened a postcard's link and hasn't taken a car. A guest is
 * sent the cells it asks for and who moves round its camera, never runs a cell, and may say only these.
 */
export const GUEST = {
  /** Guests at once, beside the players (MAX_GUESTS on the server overrides it), and from one address. */
  max: 300, perIp: 3,
  /** Cells a guest may hold. */
  cells: 25,
  /** A guest that has said nothing for this long (ms) is let go: a game whose tab is open says `watch` every minute. */
  idle: 600e3,
  says: ['sub', 'watch', 'bye'] as const,
};

/** What of a saved game is the world's and not the player's: left out of the career the server keeps. */
export const SHARED_SAVE_FIELDS = ['cells', 'lots'] as const;
