/**
 * Where a new game or a new online fleet starts (1 Oct 2026). A start must let the player reach, by
 * car, at least SPAWN.cells cells, SPAWN.dealers land dealers and SPAWN.shops Auto Shops: in the first
 * fleet playtests four worlds in thirteen put the player on an island whose only dealers were across
 * the water, with nothing pointing to the ferry. So candidates are scored from the macro layer alone
 * (no cell is generated, so a few hundred are scored in milliseconds), the ones that fail are thrown
 * out, and the start is picked from the best tenth of the rest, by the seed.
 *
 * The macro layer says which borders a car can cross (a land border between two counties, or a
 * causeway) and which cells keep a land dealer (`plannedDealer`, honoured by world/storefronts.ts).
 * What it can't promise, that the ground on each side really joins up, is checked twice: on the start
 * cell when it is generated (game/firstStart.ts `startReaches`) and over many seeds and whole
 * neighbourhoods by `npm run spawns`.
 */
import { cellKind, landBorder, plannedDealer, straitAt } from './macro';
import { hashString } from './rng';
import type { CellKind } from './tiles';

export const SPAWN = {
  /** Cells a car must be able to reach from the start, the start's own included. */
  cells: 10,
  /** Land dealers that must be reachable within `dealerReach` cells of the start. */
  dealers: 2, dealerReach: 3,
  /** Auto Shops that must be reachable within `shopReach` cells of the start. */
  shops: 2, shopReach: 2,
  /** How far (cells, by road) the reach is counted. */
  depth: 6,
  /** The share of passing candidates the start is chosen among, best first. */
  top: 0.1,
};

/** The cell kinds a start may be in: they hold the towns the first drive needs. */
const START_KINDS: ReadonlySet<CellKind> = new Set(['continent', 'full']);
/** The cell kinds that keep an Auto Shop: every cell with a town gets one (world/storefronts.ts). */
const SHOP_KINDS: ReadonlySet<CellKind> = new Set(['continent', 'full', 'small']);
const STEPS: ReadonlyArray<readonly [number, number]> = [[1, 0], [0, 1], [-1, 0], [0, -1]];

/** Can a car drive across side d of cell (cx, cz): a land border between counties, or a causeway? */
export function carAcross(seedHash: number, cx: number, cz: number, d: number): boolean {
  return landBorder(seedHash, cx, cz, d) || straitAt(seedHash, cx, cz, d) >= 0;
}

interface SpawnScore {
  cx: number; cz: number;
  /** Passes every rule, and why not when it doesn't. */
  ok: boolean; why: string | null;
  /** Cells reachable by car (to SPAWN.depth), land dealers and shops within their reach. */
  cells: number; dealers: number; shops: number;
  /** Higher is better: dealers and shops near, and plenty of country to grow into. */
  score: number;
}

/** The macro facts one scoring run reads, kept so a few hundred candidates share them. */
class Lattice {
  private kinds = new Map<string, CellKind>();
  private edges = new Map<string, boolean>();
  constructor(readonly seedHash: number) {}
  kind(cx: number, cz: number): CellKind {
    const k = `${cx},${cz}`;
    let v = this.kinds.get(k);
    if (v === undefined) { v = cellKind(this.seedHash, cx, cz); this.kinds.set(k, v); }
    return v;
  }
  across(cx: number, cz: number, d: number): boolean {
    // a border is one edge whichever side asks: keyed from its west / north cell
    const [ax, az, ad] = d === 2 ? [cx - 1, cz, 0] : d === 3 ? [cx, cz - 1, 1] : [cx, cz, d];
    const k = `${ax},${az},${ad}`;
    let v = this.edges.get(k);
    if (v === undefined) { v = carAcross(this.seedHash, ax, az, ad); this.edges.set(k, v); }
    return v;
  }
  dealer(cx: number, cz: number): boolean { return plannedDealer(this.seedHash, cx, cz); }
}

/** Score one candidate start cell from the macro layer. */
export function scoreSpawn(seedHash: number, cx: number, cz: number, lat = new Lattice(seedHash)): SpawnScore {
  const out: SpawnScore = { cx, cz, ok: false, why: null, cells: 0, dealers: 0, shops: 0, score: 0 };
  if (!START_KINDS.has(lat.kind(cx, cz))) { out.why = 'not a whole island or a county'; return out; }
  // breadth first over the cells a car can drive into
  const dist = new Map<string, number>([[`${cx},${cz}`, 0]]);
  const queue: [number, number, number][] = [[cx, cz, 0]];
  let score = 0;
  for (let h = 0; h < queue.length; h++) {
    const [x, z, d] = queue[h];
    const dealer = lat.dealer(x, z), shop = SHOP_KINDS.has(lat.kind(x, z));
    if (dealer && d <= SPAWN.dealerReach) out.dealers++;
    if (shop && d <= SPAWN.shopReach) out.shops++;
    score += ((dealer ? 3 : 0) + (shop ? 1 : 0) + 0.4) / (1 + d);
    if (d >= SPAWN.depth) continue;
    for (let s = 0; s < 4; s++) {
      if (!lat.across(x, z, s)) continue;
      const nx = x + STEPS[s][0], nz = z + STEPS[s][1], k = `${nx},${nz}`;
      if (dist.has(k)) continue;
      dist.set(k, d + 1);
      queue.push([nx, nz, d + 1]);
    }
  }
  out.cells = queue.length;
  out.score = score + Math.min(out.cells, 30) * 0.05;
  out.why = out.cells < SPAWN.cells ? `only ${out.cells} cells reachable by car`
    : out.dealers < SPAWN.dealers ? `${out.dealers} land dealer${out.dealers === 1 ? '' : 's'} within ${SPAWN.dealerReach} cells`
      : out.shops < SPAWN.shops ? `${out.shops} shop${out.shops === 1 ? '' : 's'} within ${SPAWN.shopReach} cells` : null;
  out.ok = out.why === null;
  return out;
}

/**
 * Every passing start within `radius` cells (Chebyshev) of `around`, best first, with the pick moved to
 * the front: one of the best tenth, chosen by `pick` (0..1). The rest follow in order, so a caller
 * whose check on the generated cell fails takes the next. Never empty: when nothing passes even far
 * out, the best-scoring candidates come back anyway, failing ones last.
 */
export function rankSpawns(seedHash: number, around: readonly [number, number], radius: number, pick: number,
  allow: (cx: number, cz: number) => boolean = () => true): SpawnScore[] {
  const lat = new Lattice(seedHash);
  let all: SpawnScore[] = [];
  for (const r of [radius, radius * 2, radius * 4]) {
    all = [];
    for (let dz = -r; dz <= r; dz++) {
      for (let dx = -r; dx <= r; dx++) {
        const cx = around[0] + dx, cz = around[1] + dz;
        if (allow(cx, cz)) all.push(scoreSpawn(seedHash, cx, cz, lat));
      }
    }
    if (all.some((s) => s.ok)) break;
  }
  const ok = all.filter((s) => s.ok).sort((a, b) => b.score - a.score || a.cx - b.cx || a.cz - b.cz);
  if (!ok.length) return all.filter((s) => s.why !== 'not a whole island or a county').sort((a, b) => b.score - a.score);
  const top = Math.max(1, Math.ceil(ok.length * SPAWN.top));
  const i = Math.min(top - 1, Math.floor(pick * top));
  return [ok[i], ...ok.slice(0, i), ...ok.slice(i + 1)];
}

/** How far from the origin a single-player world looks for its start. */
const START_RADIUS = 8;

/** A new single-player game's start cells, best first: the seed's pick of the top tenth, then the rest. */
export function startCells(seed: string): SpawnScore[] {
  const seedHash = hashString(seed);
  return rankSpawns(seedHash, [0, 0], START_RADIUS, (hashString(`${seed}|start`) % 10007) / 10007);
}
