/**
 * What traffic knows of the camera this frame (set by main before the updates): where it is, how many
 * pixels a tile-long thing is at one tile away, and what it can see. A car smaller than `lodFar` pixels
 * wears its far body (render/vehicleMeshes.ts) until it grows past `lodNear`; a car out of view with
 * nothing special to do is ticked every other frame, on two frames' time (the frame step is never more
 * than 0.05 s either way, the same as the player's car gets at 20 fps).
 */
/**
 * Milliseconds of route finding each frame's new trips may use, across every island's traffic. A cell
 * arriving starts empty and filled itself a car every 50 ms, each try an A* search or several, all in
 * one frame with every other island doing the same: a new trip can always wait a frame.
 */
const SPAWN_BUDGET_MS = 3;
let spawnSpent = 0;
/**
 * Milliseconds every route search together may take in a frame (landRoute and waterRoute time
 * themselves into routeSpent). Anything that can wait a frame (a new trip, a parked driver asking for
 * work, a stuck car going round, a follower catching up) checks it first and tries again shortly. Before
 * this a cell change set a whole fleet asking at once, each ask a dozen searches: 60 to 300 ms frames.
 */
const ROUTE_BUDGET_MS = 3;
let routeSpent = 0;
/** Is this frame's route-finding spent? Then whatever can wait, waits. */
export function routesSpent(): boolean { return routeSpent >= ROUTE_BUDGET_MS; }
/** Called once a frame, before any traffic updates, to hand out the budget again. */
export function trafficFrame(): void { spawnSpent = 0; routeSpent = 0; haulerPlanned = false; routeCut = false; framed = true; }
/**
 * The most route finding one frame may hold, however it is asked for (11 Nov 2026 perf audit). ROUTE_BUDGET_MS
 * is looked at before work that can wait, but a search under way ran to the end, and several paths (backing
 * off, giving up, closures, tows, police) never looked at it: an unreachable goal flooded the whole county, a
 * few of them in one frame were the 0.4–3.8 s 'traffic' freezes players had. Past this every search stops where
 * it is and finds nothing (routesCut() says so, and whoever would give up on that waits a frame instead).
 * Only once the game's frame has started handing out the budget (trafficFrame): gates and scripts search freely.
 */
const ROUTE_CEIL_MS = 25;
let routeCut = false, framed = false;
/** Was a route search cut short this frame (ROUTE_CEIL_MS)? A null route may then mean "not now", not "no way". */
export function routesCut(): boolean { return routeCut; }
/** Is this frame's route time past the ceiling, counting the search under way from t0? */
function overCeiling(t0: number): boolean {
  if (!framed || routeSpent + (performance.now() - t0) <= ROUTE_CEIL_MS) return false;
  routeCut = true;
  return true;
}
