/**
 * Overtaking (working drivers only): a vehicle ahead going our way at under `slower` of our cruise, that we
 * can beat by `gain` tiles a second, is passed on the left — one lane over (`offset` tiles) — if that lane is
 * drivable and has nothing coming for the whole pass (at most `maxRun` tiles), keeping `gap` tiles clear of
 * it before cutting back in. "Our cruise" is the pace this driver wants on that road, temper and all, and
 * `slower` was 0.75 until a quick driver in a Mule sat behind a working tractor doing 0.8 of it (the user,
 * 15 Oct 2026): anything a seventh slower is worth getting by when the lane is clear. `offset` was 0.95,
 * which from the right-hand lane (LANE_OFFSET) is right over the far kerb: the ground checked for the pass
 * was the verge beyond the road, so a fence or a house along it ruled out passing on a clear two-lane road
 * (the same report). 0.55 is the oncoming lane itself, well clear of what is being passed.
 */
const PASS = { slower: 0.86, gain: 0.5, offset: 0.55, gap: 1.2, maxRun: 16 };
/** Tiles of air a pass keeps between the passer's side and what it passes (traffic.ts passLine). */
const PASS_MARGIN = 0.08;
/**
 * Points along a vehicle's body, in its own frame: its middle, and for a semi the middle and tail of its
 * trailer, which trails the cab along trailerHeading from the hitch.
 */
function bodyPoints(st: VehicleState, d: VehicleDef): { x: number; z: number }[] {
  const pts = [{ x: st.x, z: st.z }];
  const tr = d.kind === 'land' ? d.trailer : undefined;
  if (tr) {
    const th = Number.isFinite(st.trailerHeading) ? st.trailerHeading : st.heading;
    const jx = st.x - Math.sin(st.heading) * tr.hitch, jz = st.z - Math.cos(st.heading) * tr.hitch;
    for (const f of [0.5, 1]) pts.push({ x: jx - Math.sin(th) * tr.length * f, z: jz - Math.cos(th) * tr.length * f });
  }
  return pts;
}
/** How far ahead of itself a vehicle looks for something in its way. */
const lookAhead = (st: VehicleState, d: VehicleDef): number => 0.3 + halfSize(d)[0] * 2 + Math.max(0, st.v) * 0.7;

/** Whether the point (px, pz) is in the lane ahead of `from`: within reach (plus `extra`) and within `wide` of its line. */
function inLane(from: VehicleState, hx: number, hz: number, reach: number, wide: number, px: number, pz: number, extra: number): boolean {
  const rx = px - from.x, rz = pz - from.z;
  const ahead = rx * hx + rz * hz, side = Math.abs(rx * hz - rz * hx);
  return ahead > 0 && ahead < reach + extra && side < wide;
}

/**
 * Whether `from` has `other` in the lane ahead of it, on county w. A semi's trailer is in the way as much as its
 * cab: a van drove on into the trailer, unseen, until it met the cab (the user, 15 Oct 2026), so every point of the
 * other's body is looked for (bodyPoints, worked out here without an array for each pair).
 */
function sees(w: World, from: VehicleState, fromDef: VehicleDef, other: VehicleState, otherDef: VehicleDef): boolean {
  if ((fromDef.kind === 'air') !== (otherDef.kind === 'air')) return false;
  if (fromDef.kind === 'air' && Math.abs(from.y - other.y) > 1.5) return false;
  // one up on a bridge deck and one on the ground under it never meet: the traffic over a car stood
  // beneath a deck braked for it and queued for good (the user, 18 Oct 2026)
  if (fromDef.kind === 'land' && Math.abs(from.y - other.y) > DECK_APART && (onDeckTile(w, from) || onDeckTile(w, other))) return false;
  const hx = Math.sin(from.heading), hz = Math.cos(from.heading);
  const r = lookAhead(from, fromDef), wide = halfSize(fromDef)[1] + halfSize(otherDef)[1] + 0.06;
  if (inLane(from, hx, hz, r, wide, other.x, other.z, halfSize(otherDef)[0])) return true;
  const tr = otherDef.kind === 'land' ? otherDef.trailer : undefined;
  if (!tr) return false;
  const th = Number.isFinite(other.trailerHeading) ? other.trailerHeading : other.heading;
  const jx = other.x - Math.sin(other.heading) * tr.hitch, jz = other.z - Math.cos(other.heading) * tr.hitch;
  const sx = Math.sin(th) * tr.length, sz = Math.cos(th) * tr.length;
  return inLane(from, hx, hz, r, wide, jx - sx * 0.5, jz - sz * 0.5, 0.15) || inLane(from, hx, hz, r, wide, jx - sx, jz - sz, 0.15);
}

/** The way the road runs where a vehicle is on its path (its nose's way where the path gives none), as a unit [x, z]. */
function roadDir(a: Agent): [number, number] {
  const p0 = a.path[a.wp], p1 = a.path[Math.min(a.path.length - 1, a.wp + 1)];
  const len = p0 && p1 ? Math.hypot(p1.x - p0.x, p1.z - p0.z) : 0;
  return len > 0.05 ? [(p1.x - p0.x) / len, (p1.z - p0.z) / len] : [Math.sin(a.state.heading), Math.cos(a.state.heading)];
}
