import type { Mission } from './model';

/**
 * The acts' rides on offer or under way (missions/actTemplates.ts), for the stadium card's Season and Tours tabs
 * (game/stadiumCard.ts): a touring act's next stop or a club's away game shows there with the job beside it, so the
 * player can see the ride is the real tour or fixture. Kept apart from the templates so the card needs nothing more.
 */
export const ACT_BOARD: { missions: (() => Mission[]) | null } = { missions: null };

/** What a ride carries, as its notes say: a tour by id, or a fixture by its key's hash. */
export interface ActJob { m: Mission; form: string; to: string; by: number }

const FORM_LABEL: Record<string, string> = { 'act:bus': 'by bus', 'act:train': 'by train', 'act:jet': 'by Jumbo' };

/** The ride on offer or under way for a tour (its id) or a fixture (the hash of its key), or null. */
export function actJob(q: { tour?: number; fix?: number }): ActJob | null {
  for (const m of ACT_BOARD.missions?.() ?? []) {
    if (!m.tpl.startsWith('act:') || (m.state !== 'offered' && m.state !== 'active')) continue;
    const n = m.notes ?? {};
    if ((q.tour !== undefined && n.tour === q.tour) || (q.fix !== undefined && n.fix === q.fix)) {
      const o = m.objs.find((x) => x.t === 'deliver');
      return { m, form: FORM_LABEL[m.tpl] ?? '', to: o && o.t === 'deliver' ? o.to.name : '', by: n.by ?? 0 };
    }
  }
  return null;
}
