import * as THREE from 'three';
import { N, STEP, heightAt, idx, type Building, type Town, type World } from '../world/tiles';
import { buildingHeight } from '../world/towns';
import type { TownShape } from '../world/townShape';

/**
 * A selected town's border, drawn over the ground (docs/towns.html): a ribbon laid along the traced
 * edge that keeps the same width on screen at any distance and breathes, slowly; a faint wash over the
 * town's tiles from far off, so it reads which side of the line is the town; and, when asked, yellow
 * boxes round a few of its buildings for a few seconds (the card's "show" on its boarded-up ones).
 */

/** The inspector's yellow, for a town with no colour of its own. */
const YELLOW = 0xffc83d;
/** Seconds for one breath of the pulse: slower than a cargo marker's, so a town never reads as a job. */
const BREATH = 1.6;
/** The ribbon's width against the camera's distance, and its bounds, in tiles. */
const WIDTH_K = 0.004, WIDTH_MIN = 0.25, WIDTH_MAX = 5;
/** Beyond this camera distance the wash over the town's tiles comes up. */
const WASH_FROM = 120;
/** Across the ribbon, in widths from the edge (out positive), and how solid it is there: a soft glow inside, a solid core, a soft outer edge. */
const SIDES = [-2.5, -0.55, -0.5, 0.5, 0.9];
const ALPHA = [0, 0.4, 1, 1, 0];

/** Asked once; `matches` follows the setting live. */
let motionQuery: MediaQueryList | null | undefined;
const reduced = (): boolean => {
  if (motionQuery === undefined) {
    try { motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)'); } catch { motionQuery = null; }
  }
  return !!motionQuery?.matches;
};

/** Ground, water or bridge deck at a point of a cell, whichever is on top: where a line lies. */
function surfaceAt(w: World, x: number, z: number): number {
  let y = heightAt(w, x, z);
  const tx = Math.floor(x), tz = Math.floor(z);
  if (tx >= 0 && tz >= 0 && tx < N && tz < N) {
    const i = idx(tx, tz);
    if (w.water[i] >= 0) y = Math.max(y, w.water[i] * STEP);
    if (w.deckAxis[i]) y = Math.max(y, w.deckLo[i], w.deckHi[i]);
  }
  return y;
}

export class TownBorder {
  private group = new THREE.Group();
  private ribbon: THREE.Mesh | null = null;
  private wash: THREE.Mesh | null = null;
  private boxes: THREE.LineSegments | null = null;
  private boxTime = 0;
  private uniforms = { uWidth: { value: 1 }, uColor: { value: new THREE.Color(YELLOW) }, uOpacity: { value: 1 } };
  private washMat = new THREE.MeshBasicMaterial({
    color: YELLOW, transparent: true, opacity: 0.12, depthWrite: false, side: THREE.DoubleSide, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, fog: false,
  });
  private ribbonMat: THREE.ShaderMaterial;
  private time = 0;
  /** The middle of the town in world units, for the camera distance the width is set from. */
  private centre = new THREE.Vector3();
  /** What is drawn: the island, the town and the shape, so the same one isn't built twice. */
  private shown: { w: World; t: Town; shape: TownShape } | null = null;

  constructor(scene: THREE.Scene) {
    this.ribbonMat = new THREE.ShaderMaterial({
      uniforms: this.uniforms,
      vertexShader: /* glsl */ `
        attribute vec2 dir;
        attribute float side;
        attribute float alpha;
        uniform float uWidth;
        varying float vA;
        void main() {
          vec3 p = position + vec3(dir.x * side * uWidth, uWidth * 0.35, dir.y * side * uWidth);
          vA = alpha;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
        }`,
      fragmentShader: /* glsl */ `
        uniform vec3 uColor;
        uniform float uOpacity;
        varying float vA;
        void main() {
          gl_FragColor = vec4(uColor, vA * uOpacity);
        }`,
      transparent: true,
      depthWrite: false,
      polygonOffset: true,
      polygonOffsetFactor: -4,
      polygonOffsetUnits: -4,
      side: THREE.DoubleSide,
    });
    this.group.renderOrder = 20;
    scene.add(this.group);
  }

  /** Draw this town's border, or none. A shape object that hasn't changed is left as it is. */
  set(w: World | null, t: Town | null, shape: TownShape | null): void {
    if (!w || !t || !shape) { this.drop(); this.shown = null; return; }
    if (this.shown && this.shown.w === w && this.shown.t === t && this.shown.shape === shape) return;
    this.drop();
    this.shown = { w, t, shape };
    const colour = t.accent ?? YELLOW;
    this.uniforms.uColor.value.setHex(colour);
    this.washMat.color.setHex(colour);
    this.centre.set(w.ox + shape.cx, surfaceAt(w, shape.cx, shape.cz), w.oz + shape.cz);
    this.ribbon = this.buildRibbon(w, shape);
    this.wash = this.buildWash(w, shape);
    this.group.add(this.ribbon, this.wash);
  }

  /** Yellow boxes round these buildings for a few seconds. */
  showBuildings(w: World, list: Building[], seconds = 5): void {
    this.dropBoxes();
    if (!list.length) return;
    const pos: number[] = [];
    for (const b of list) {
      const ground = heightAt(w, Math.min(N - 0.01, b.x + b.w / 2), Math.min(N - 0.01, b.z + b.d / 2));
      const y0 = (b.level > 0 ? Math.min(b.level * STEP, ground) : ground) - 0.05;
      const y1 = Math.max(b.level * STEP, ground) + Math.max(0.3, buildingHeight(b));
      const x0 = w.ox + b.x - 0.04, x1 = w.ox + b.x + b.w + 0.04, z0 = w.oz + b.z - 0.04, z1 = w.oz + b.z + b.d + 0.04;
      const c = [[x0, z0], [x1, z0], [x1, z1], [x0, z1]];
      for (let k = 0; k < 4; k++) {
        const [ax, az] = c[k], [bx, bz] = c[(k + 1) % 4];
        pos.push(ax, y0, az, bx, y0, bz, ax, y1, az, bx, y1, bz, ax, y0, az, ax, y1, az);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    this.boxes = new THREE.LineSegments(geo, new THREE.LineBasicMaterial({ color: YELLOW, depthTest: false, transparent: true, opacity: 0.95 }));
    this.boxes.renderOrder = 999;
    this.boxes.frustumCulled = false;
    this.group.add(this.boxes);
    this.boxTime = seconds;
  }

  /** Every frame: the breath, the width for how far away the camera is, and the wash by distance. */
  update(dt: number, camera: THREE.Camera): void {
    this.time += dt;
    if (this.boxes) {
      this.boxTime -= dt;
      if (this.boxTime <= 0) this.dropBoxes();
    }
    if (!this.ribbon) return;
    const breath = reduced() ? 0.6 : 0.5 + 0.5 * Math.sin((this.time * Math.PI * 2) / BREATH);
    this.uniforms.uOpacity.value = 0.55 + 0.45 * breath;
    const dist = camera.position.distanceTo(this.centre);
    this.uniforms.uWidth.value = Math.min(WIDTH_MAX, Math.max(WIDTH_MIN, dist * WIDTH_K));
    if (this.wash) {
      this.wash.visible = dist > WASH_FROM;
      this.washMat.opacity = 0.1 + 0.06 * breath;
    }
  }

  /** The breath, 0..1, for the map to pulse in step with the ground. */
  get breath(): number {
    return reduced() ? 0.6 : 0.5 + 0.5 * Math.sin((this.time * Math.PI * 2) / BREATH);
  }

  private buildRibbon(w: World, s: TownShape): THREE.Mesh {
    const pos: number[] = [], dir: number[] = [], side: number[] = [], alpha: number[] = [], index: number[] = [];
    const K = SIDES.length;
    for (const l of s.loops) {
      const n = l.length / 2;
      const base = pos.length / 3;
      for (let k = 0; k < n; k++) {
        const x = l[k * 2], z = l[k * 2 + 1];
        const px = l[((k + n - 1) % n) * 2], pz = l[((k + n - 1) % n) * 2 + 1];
        const qx = l[((k + 1) % n) * 2], qz = l[((k + 1) % n) * 2 + 1];
        // the town is on the left of the way round, at (tz, -tx): out is the other way
        let ox = -(qz - pz), oz = qx - px;
        const len = Math.hypot(ox, oz) || 1;
        ox /= len; oz /= len;
        const y = surfaceAt(w, x, z) + 0.12;
        for (let j = 0; j < K; j++) {
          pos.push(w.ox + x, y, w.oz + z);
          dir.push(ox, oz);
          side.push(SIDES[j]);
          alpha.push(ALPHA[j]);
        }
      }
      for (let k = 0; k < n; k++) {
        const a = base + k * K, b = base + ((k + 1) % n) * K;
        for (let j = 0; j < K - 1; j++) index.push(a + j, b + j, a + j + 1, a + j + 1, b + j, b + j + 1);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('dir', new THREE.Float32BufferAttribute(dir, 2));
    geo.setAttribute('side', new THREE.Float32BufferAttribute(side, 1));
    geo.setAttribute('alpha', new THREE.Float32BufferAttribute(alpha, 1));
    geo.setIndex(index);
    const mesh = new THREE.Mesh(geo, this.ribbonMat);
    mesh.frustumCulled = false;
    mesh.renderOrder = 21;
    return mesh;
  }

  private buildWash(w: World, s: TownShape): THREE.Mesh {
    const pos: number[] = [], index: number[] = [];
    // one height per tile corner, shared by the four tiles round it
    const W1 = s.bw + 1;
    const ys = new Float32Array(W1 * (s.bh + 1)).fill(NaN);
    const yAt = (cx: number, cz: number) => {
      const k = cz * W1 + cx;
      if (Number.isNaN(ys[k])) ys[k] = surfaceAt(w, Math.min(N - 0.001, Math.max(0, s.x0 + cx)), Math.min(N - 0.001, Math.max(0, s.z0 + cz))) + 0.08;
      return ys[k];
    };
    for (let z = 0; z < s.bh; z++) {
      for (let x = 0; x < s.bw; x++) {
        if (!s.mask[z * s.bw + x]) continue;
        const b = pos.length / 3;
        const X = w.ox + s.x0 + x, Z = w.oz + s.z0 + z;
        pos.push(X, yAt(x, z), Z, X + 1, yAt(x + 1, z), Z, X + 1, yAt(x + 1, z + 1), Z + 1, X, yAt(x, z + 1), Z + 1);
        index.push(b, b + 2, b + 1, b, b + 3, b + 2);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setIndex(index);
    const mesh = new THREE.Mesh(geo, this.washMat);
    mesh.frustumCulled = false;
    mesh.renderOrder = 20;
    mesh.visible = false;
    return mesh;
  }

  private drop(): void {
    for (const m of [this.ribbon, this.wash]) {
      if (!m) continue;
      this.group.remove(m);
      m.geometry.dispose();
    }
    this.ribbon = null;
    this.wash = null;
  }

  private dropBoxes(): void {
    if (!this.boxes) return;
    this.group.remove(this.boxes);
    this.boxes.geometry.dispose();
    (this.boxes.material as THREE.Material).dispose();
    this.boxes = null;
  }
}
