/**
 * The HQ window's Factions tab (docs/factions.html, "The Factions screen"): ten bars down the left, drawn
 * to scale in each faction's colours and sorted by standing, and the chosen faction on the right — who
 * they are, who they like and loathe, what they pay for and where, what the player has from them, the
 * Oath, the three unlocks on the turntable, and the last things done for or against them.
 */
import { esc } from '../cargoHud';
import { cargoById } from '../cargoTypes';
import { kindLabel } from '../lobby';
import { badgeUrl } from '../../render/fleetBadges';
import { hero } from '../../render/heroStage';
import { ALL_VEHICLES } from '../vehicles';
import {
  BUILDINGS_OF, CARGO_OF, FACTIONS, FACTION_IDS, LINK_LABEL, PAY_MUL, REP_MAX, REP_MIN, RUNG, RUNGS, fcss, linksOf, type FactionId,
} from './factions';
import { reputation } from './reputation';
import { unlocks } from './unlocks';

interface FactionsTabHost {
  /** A line under the tabs. */
  say(text: string): void;
  /** Point the player at the faction's nearest hall (Show me), or null when none is known. */
  showHall?(f: FactionId): string | null;
  /** The goal crest by the gem chip changed. */
  goalChanged?(f: FactionId | null): void;
  /** Models the fleet owns (an Oath needs the Honoured vehicle). */
  owns(model: string): boolean;
  /** Where the faction's nearest stronghold is, in a few words (docs/strongholds.html), or null. */
  stronghold?(f: FactionId): string | null;
}

/** A faction's crest as an image (the shield badge, in its colours). */
export function crestUrl(f: FactionId): string {
  const d = FACTIONS[f];
  return badgeUrl({ logo: d.glyph, primary: d.colour, accent: d.accent }, 'shield');
}

const SPAN = REP_MAX - REP_MIN;
const pct = (v: number): number => ((v - REP_MIN) / SPAN) * 100;

/** A bar to scale: its bands, the zero mark, and the fill from zero to where it stands. */
export function barHtml(f: FactionId, v: number, small = false): string {
  const d = FACTIONS[f];
  const z = pct(0), at = pct(v);
  const bands = RUNGS.slice(1).map((r) => `<b style="left:${pct(r.at === -5999 ? -6000 : r.at).toFixed(2)}%"></b>`).join('');
  const fill = v >= 0
    ? `<i class="fac-fill" style="left:${z.toFixed(2)}%;width:${(at - z).toFixed(2)}%;background:${fcss(d.colour === 0xf4f2ec ? d.accent : d.colour)}"></i>`
    : `<i class="fac-fill neg" style="left:${at.toFixed(2)}%;width:${(z - at).toFixed(2)}%"></i>`;
  return `<span class="fac-bar${small ? ' sm' : ''}"><span class="neg-zone" style="width:${z.toFixed(2)}%"></span>${fill}${bands}<em style="left:${z.toFixed(2)}%"></em><u style="left:${at.toFixed(2)}%"></u></span>`;
}

export class FactionsTab {
  readonly el = document.createElement('div');
  private list = document.createElement('div');
  private pane = document.createElement('div');
  private stage = document.createElement('div');
  private body = document.createElement('div');
  private sel: FactionId = 'police';
  private pick = 1;
  private shown = false;
  private version = -1;
  private html = '';

  constructor(private host: FactionsTabHost) {
    this.el.className = 'hq-fac';
    this.list.className = 'hq-flist';
    this.pane.className = 'hq-pane hq-fpane';
    this.stage.className = 'hq-stage veh';
    this.body.className = 'hq-pbody';
    this.pane.append(this.stage, this.body);
    this.el.append(this.list, this.pane);
    this.list.addEventListener('click', (e) => {
      const row = (e.target as HTMLElement).closest<HTMLElement>('[data-f]');
      if (!row) return;
      this.sel = row.dataset.f as FactionId;
      this.pick = this.defaultPick();
      this.render(true);
    });
    this.pane.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-act],[data-u]');
      if (!b) return;
      if (b.dataset.u) { this.pick = Number(b.dataset.u); this.render(true); return; }
      if (b.dataset.act === 'goal') {
        reputation.goal = reputation.goal === this.sel ? null : this.sel;
        reputation.version++;
        this.host.goalChanged?.(reputation.goal);
        this.render(true);
      } else if (b.dataset.act === 'hall') {
        const line = this.host.showHall?.(this.sel);
        this.host.say(line ?? `No ${FACTIONS[this.sel].short} hall known near here yet: drive on and look for their crest`);
      }
    });
    try { const f = localStorage.getItem('tinyfleet-fac') as FactionId | null; if (f && FACTION_IDS.includes(f)) this.sel = f; } catch { /* not kept */ }
  }

  /** Open at one faction (from a building's or a vehicle's card). */
  focus(f: FactionId): void { this.sel = f; this.pick = this.defaultPick(); }

  /** The unlock to show first: the next one not yet had, else the top one. */
  private defaultPick(): number {
    const u = FACTIONS[this.sel].unlocks;
    const i = u.findIndex((x) => !unlocks.has(x.id));
    return i < 0 ? 2 : i;
  }

  setVisible(on: boolean): void {
    this.shown = on;
    if (on) { this.pick = this.defaultPick(); this.render(true); }
  }

  /** Number keys aren't ours (they're the tabs); arrows step through the factions. */
  key(code: string): boolean {
    if (code !== 'ArrowDown' && code !== 'ArrowUp') return false;
    const order = this.order();
    const i = order.indexOf(this.sel);
    this.sel = order[(i + (code === 'ArrowDown' ? 1 : order.length - 1)) % order.length];
    this.pick = this.defaultPick();
    this.render(true);
    return true;
  }

  private order(): FactionId[] {
    return [...FACTION_IDS].sort((a, b) => reputation.points(b) - reputation.points(a) || FACTION_IDS.indexOf(a) - FACTION_IDS.indexOf(b));
  }

  render(force = false): void {
    if (!this.shown) return;
    if (!force && this.version === reputation.version) return;
    this.version = reputation.version;
    try { localStorage.setItem('tinyfleet-fac', this.sel); } catch { /* not kept */ }
    const rows = this.order().map((f) => {
      const d = FACTIONS[f], v = reputation.points(f), r = reputation.rung(f);
      const met = reputation.met.has(f) || v !== 0;
      return `<button type="button" class="hq-frow${f === this.sel ? ' on' : ''}${met ? '' : ' unmet'}${r <= RUNG.hostile ? ' bad' : ''}" data-f="${f}">`
        + `<img class="fac-crest" alt="" src="${crestUrl(f)}"><span class="nm"><b>${esc(d.name)}</b><small>${esc(d.common)}${met ? '' : ' · not yet met'}</small></span>`
        + barHtml(f, v)
        + `<span class="rk" style="color:${RUNGS[r].colour}">${RUNGS[r].name}<small>${Math.round(v).toLocaleString()}</small></span>`
        + `${reputation.goal === f ? '<span class="goal" title="Your goal">◎</span>' : ''}</button>`;
    }).join('');
    const top = `<div class="hq-fhead"><b>Standing</b><small>Earned by deliveries, missions and deeds. Some factions can’t stand each other: helping one costs you with the other.</small></div>`;
    const html = top + rows;
    if (force || html !== this.html) { this.html = html; this.list.innerHTML = html; }
    this.renderPane();
  }

  private renderPane(): void {
    const f = this.sel, d = FACTIONS[f], v = reputation.points(f), r = reputation.rung(f);
    const next = RUNGS[r + 1];
    const toGo = next ? Math.max(0, Math.ceil(next.at - v)) : 0;
    const links = linksOf(f).map(({ other, link }) => `<span class="fchip ${link}" title="${LINK_LABEL[link]}">${link === 'opposed' ? '⚔' : link === 'rival' ? '↯' : link === 'allied' ? '❤' : '◐'} ${esc(FACTIONS[other].short)}</span>`).join('');
    const cargo = CARGO_OF[f].map((id) => cargoById(id)).filter((c): c is NonNullable<typeof c> => !!c)
      .map((c) => `<span class="fcg" title="${esc(c.blurb)}">${c.icon} ${esc(c.name)}</span>`).join('');
    const doors = BUILDINGS_OF[f].map((k) => esc(kindLabel(k))).join(' · ');
    // what the player has from them now, and what the next rung adds
    const have: string[] = [];
    const mul = PAY_MUL[r];
    if (mul !== 1) have.push(`their work pays ${mul > 1 ? '+' : '−'}${Math.round(Math.abs(mul - 1) * 100)}%`);
    if (r <= RUNG.hostile) have.push('<span class="neg">none of their work is offered and their doors are shut</span>', `<span class="neg">${esc(d.hostile)}</span>`);
    else if (r === RUNG.wary) have.push('<span class="neg">they’re watching you</span>');
    if (r >= RUNG.honoured) have.push(esc(d.honoured));
    if (r >= RUNG.sworn) have.push(esc(d.sworn));
    d.unlocks.forEach((u, k) => { if (unlocks.has(u.id)) have.push(`${esc(u.name)} ${u.kind === 'job' ? 'paintjob' : 'on sale'} ✓`); void k; });
    const nextLine = r < RUNG.friend ? `Friend at 1,000: their work pays +10% and ${esc(d.unlocks[0].name)} is yours`
      : r === RUNG.friend ? `Honoured at 4,000: ${esc(d.honoured)} · ${esc(d.unlocks[1].name)}`
        : r === RUNG.honoured ? `Sworn at 10,000, after the Oath: ${esc(d.sworn)}` : '';
    // their stronghold (docs/strongholds.html): a rumour at Friend, its place at Honoured, its gate open at Honoured
    const where = this.host.stronghold?.(f) ?? null;
    const keep = !where ? ''
      : r >= RUNG.honoured ? `<p class="oath"><b>🗝️ Stronghold</b> ${esc(where)} · its gates are open to you, and its own loads wait at its door</p>`
        : r >= RUNG.friend ? `<p class="oath"><b>🔒 Stronghold</b> ${esc(where)} · Honoured opens the gate</p>`
          : `<p class="oath"><b>🔒 Stronghold</b> Somewhere near home · Honoured opens the gate</p>`;
    // the Oath
    const steps = reputation.oath[f];
    const honouredModel = d.unlocks[1].model;
    const ownsIt = this.host.owns(honouredModel);
    const dots = [0, 1, 2, 3, 4].map((i) => `<i class="${i < steps ? 'on' : ''}"></i>`).join('');
    const oath = r >= RUNG.sworn ? `<p class="oath done"><b>Sworn</b> <span class="dots">${dots}</span> The Oath is done.</p>`
      : `<p class="oath"><b>The Oath</b> <span class="dots">${dots}</span> ${reputation.oathOpen(f)
        ? (ownsIt ? `<b>Ready.</b> Step ${steps + 1} of 5 waits at a ◆ at their nearest hall (it stays on the map, and doesn't take a mission slot): take the ${esc(nameOf(honouredModel))} there and press Space. J lists it too.`
          : `<b>Ready.</b> Buy the ${esc(nameOf(honouredModel))} at a dealer: once it's in your fleet, step 1 of 5 goes up at a ◆ at their hall, begun in it.`)
        : `At 9,999 their ${esc(d.giver.toLowerCase())} offers the Oath: five tasks, driven in the ${esc(nameOf(honouredModel))}. The bar stops there until it is done.`}</p>`;
    // the unlocks
    const cards = d.unlocks.map((u, k) => {
      const had = unlocks.has(u.id);
      const need = RUNGS[RUNG.friend + k].name;
      return `<button type="button" class="fun${k === this.pick ? ' on' : ''}${had ? ' had' : ''}" data-u="${k}"><small>${need}</small><b>${esc(u.name)}</b><span>${had ? 'Unlocked' : u.kind === 'job' ? `paintjob · ${esc(nameOf(u.model))}` : 'vehicle'}</span></button>`;
    }).join('');
    const pu = d.unlocks[this.pick];
    const log = reputation.lines(f, 8).map((l) => `<li><em class="${l.d > 0 ? 'up' : 'down'}">${l.d > 0 ? '+' : ''}${Math.round(l.d)}</em> ${esc(l.line)}${l.spill ? ` <small>(via ${esc(FACTIONS[l.spill].short)})</small>` : ''}${l.by === 'crew' ? ' <small>(crew)</small>' : ''}</li>`).join('');
    this.body.innerHTML = `<div class="fhead"><img class="fac-crest big" alt="" src="${crestUrl(f)}"><div><h3>${esc(d.name)}</h3><small>${esc(d.common)} · <b style="color:${RUNGS[r].colour}">${RUNGS[r].name}</b> · ${Math.round(v).toLocaleString()}${next ? ` · ${toGo.toLocaleString()} to ${next.name}` : ''}</small></div></div>`
      + barHtml(f, v, true)
      + `<p class="blurb">${esc(d.blurb)}</p>`
      + (links ? `<p class="links">${links}</p>` : '')
      + `<p><b>They want</b> ${esc(d.wants)}</p><p class="cg">${cargo}</p>`
      + `<p><b>They hate</b> ${esc(d.hates)}</p>`
      + `<p><b>Their doors</b> ${doors}</p>`
      + (have.length ? `<p><b>You have</b> ${have.join(' · ')}</p>` : '')
      + (nextLine ? `<p class="next"><b>Next</b> ${nextLine}</p>` : '')
      + keep + oath
      + `<div class="funs">${cards}</div><p class="ublurb">${esc(pu.blurb)}</p>`
      + `<div class="btns"><button type="button" data-act="goal">${reputation.goal === f ? 'Clear goal' : 'Set as goal'}</button><button type="button" data-act="hall">Show me their hall</button></div>`
      + (log ? `<h4>Lately</h4><ul class="flog">${log}</ul>` : '<p class="none">Nothing done for or against them yet.</p>');
    // the turntable: the picked unlock, dark if not yet had
    const known = NAMES.has(pu.model);
    this.stage.hidden = !known;
    if (this.shown && known) {
      hero.mount(this.stage);
      hero.show({ kind: 'vehicle', model: pu.model, ...(pu.kind === 'job' ? { job: pu.id } : {}) }, d.colour);
    }
    this.stage.classList.toggle('locked', !unlocks.has(pu.id));
  }
}

const NAMES = new Map(ALL_VEHICLES.map((v) => [v.id, v.name]));
function nameOf(id: string): string { return NAMES.get(id) ?? (id === 'patrol' ? 'Patrol' : id); }
