import type * as THREE from 'three';
import type { TiltShift } from './tiltshift';

/**
 * Graphics quality, and the automatic setting: the best picture that still holds 30 frames a second.
 *
 * Measured on an Intel UHD laptop at 1080p (docs: README "Performance"), a frame's GPU time is most
 * of all a matter of pixels: the scene's fill, the multisampled scene target and the post passes
 * all scale with the size of the canvas, while the draw calls cost the same at any size. So the
 * levels trade resolution and multisampling first and shadows last, and Auto walks down them while
 * frames are slow and back up while they are quick.
 */
type QualityLevel = 'high' | 'medium' | 'low' | 'lowest';
export type QualitySetting = 'auto' | QualityLevel;

const QUALITY_LEVELS: QualityLevel[] = ['high', 'medium', 'low', 'lowest'];

/** shadowEvery: the shadow map is redrawn every this many frames (the sun hardly moves between them). */
/** Moonlit frames per shadow-map redraw (Quality.tick). */
const NIGHT_SHADOW_EVERY = 3;

/**
 * shadowMap: the shadow map's size in texels a side. Only the size changes with the level, never the filter
 * (PCFSoft): the filter is a shader define, and changing it would rebuild every lit shader as Auto steps.
 */
/**
 * The CPU side (11 Nov 2026 perf audit): Auto reaches Low and Lowest only on machines whose frames are slow, and
 * the players' reports showed those were held by the CPU (28 ms of game a frame at Lowest), which the pixel
 * levers above never touched. crowd: share of the usual traffic and pedestrians; blurRounds: rounds of the
 * tilt-shift's blur (each two full-screen passes); reach: share of the full-detail draw distance (render/stream.ts
 * FAR; beyond it the low-detail blocks stand in).
 */
interface CpuSpec { crowd: number; blurRounds: number; reach: number }
const SPEC: Record<QualityLevel, { label: string; ratio: () => number; samples: number; shadows: boolean; shadowEvery: number; shadowMap: number } & CpuSpec> = {
  high: { label: 'High', ratio: () => Math.min(devicePixelRatio, 1.5), samples: 4, shadows: true, shadowEvery: 1, shadowMap: 2048, crowd: 1, blurRounds: 2, reach: 1 },
  medium: { label: 'Medium', ratio: () => Math.min(devicePixelRatio, 1), samples: 0, shadows: true, shadowEvery: 1, shadowMap: 2048, crowd: 1, blurRounds: 2, reach: 1 },
  low: { label: 'Low', ratio: () => Math.min(devicePixelRatio, 1) * 0.75, samples: 0, shadows: true, shadowEvery: 2, shadowMap: 1024, crowd: 0.75, blurRounds: 1, reach: 0.85 },
  lowest: { label: 'Lowest', ratio: () => Math.min(devicePixelRatio, 1) * 0.55, samples: 0, shadows: false, shadowEvery: 1, shadowMap: 1024, crowd: 0.5, blurRounds: 1, reach: 0.7 },
};

export const QUALITY_LABEL: Record<QualitySetting, string> = {
  auto: 'Auto', high: SPEC.high.label, medium: SPEC.medium.label, low: SPEC.low.label, lowest: SPEC.lowest.label,
};

const KEY = 'pocket-roads-quality';
// Auto leans to the better picture (the user, 19 Oct 2026): it holds 30 frames a second, not 60, so a
// machine that runs High at 40 keeps High instead of being walked down to Medium or Low chasing 60.
/** Frames slower than this on the median (under about 28 a second) are too slow: a step down. */
const SLOW_MS = 1000 / 28;
/** Frames this quick on the median (40 a second), for long enough, leave room to try a step up. */
const QUICK_MS = 1000 / 40;
/** How long a level must run before Auto judges it, and how long it must be quick before a step up. */
const SETTLE_S = 2.5;
const UP_AFTER_S = 6;

/**
 * Integrated graphics, from the WebGL renderer string (the user, 6 Nov 2026: start Auto on Medium on integrated
 * GPUs). The play reports showed Intel machines averaging 33 fps against Auto's 30 floor, spending their first
 * minute, when most new players decide, on High while Auto walked down. Intel HD/UHD/Iris and the integrated Arc
 * (not the Arc A/B cards), AMD's APUs ("Radeon(TM) Graphics", Vega n, 7x0M), Apple's base M chips and Safari's
 * "Apple GPU" (not Pro/Max/Ultra), Qualcomm Adreno, Mali and PowerVR. Auto still steps up from Medium after
 * UP_AFTER_S seconds of quick frames, so a strong one loses only those seconds.
 */
export function integratedGpu(renderer: string): boolean {
  const g = renderer.toLowerCase();
  if (/intel/.test(g)) return !/arc(\(tm\))? [ab]\d{3}/.test(g);
  if (/radeon(\(tm\))? graphics|vega \d+ graphics|radeon(\(tm\))? \d{3}m\b|radeon r\d graphics/.test(g)) return true;
  if (/apple/.test(g)) return !/\b(pro|max|ultra)\b/.test(g);
  return /adreno|mali|powervr/.test(g);
}

/** The renderer string the browser gives for this WebGL context ('' when it hides it). */
function rendererName(gl: WebGLRenderingContext | WebGL2RenderingContext): string {
  try {
    const ext = gl.getExtension('WEBGL_debug_renderer_info');
    return String(ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER));
  } catch { return ''; }
}

export class Quality {
  setting: QualitySetting = 'auto';
  level: QualityLevel = 'high';
  /** The best level Auto has found that it can hold; it will not try above this again. */
  private ceiling: QualityLevel = 'high';
  private intervals: number[] = [];
  private frames = 0;
  /** How far into night it is, 0..1 (render/daynight.ts), set each frame: deep night thins the shadow updates. */
  night = 0;
  private last = 0;
  private sinceChange = 0;
  private quickFor = 0;
  /** A step up that is on trial: if it turns out slow, Auto steps back and stops trying. */
  private trial = false;
  onChange: (() => void) | null = null;
  /**
   * Auto holds still while this is set (main.ts: the loading screen is up). The frames under it build the chunks
   * round the start and run slow on every machine, and judged they walked Auto down to Lowest, so the first look
   * at the world was the blurriest one while Auto climbed back over 45 s (the field profile, 6 Nov 2026).
   */
  hold = false;
  /** Integrated graphics (integratedGpu): Auto starts a level down. */
  readonly integrated: boolean;

  constructor(
    private renderer: THREE.WebGLRenderer, private post: TiltShift, private key: THREE.DirectionalLight,
    private camera: THREE.PerspectiveCamera,
  ) {
    try {
      const saved = localStorage.getItem(KEY) as QualitySetting | null;
      if (saved && (saved === 'auto' || QUALITY_LEVELS.includes(saved as QualityLevel))) this.setting = saved;
    } catch { /* storage blocked: Auto */ }
    // Auto starts at High (Medium on integrated graphics) and steps down only if it can't hold 30 a second
    this.integrated = integratedGpu(rendererName(renderer.getContext()));
    this.apply(this.setting === 'auto' ? this.autoStart() : this.setting);
  }

  /** Where Auto begins on this machine. */
  autoStart(): QualityLevel { return this.integrated ? 'medium' : 'high'; }

  /** The machine on its battery or under CPU pressure (net/perfField.ts strained): Auto stays off High meanwhile. */
  private strained = false;
  setStrained(on: boolean): void {
    if (on === this.strained) return;
    this.strained = on;
    if (this.setting !== 'auto') return;
    if (on) {
      this.ceiling = QUALITY_LEVELS.indexOf(this.ceiling) < 1 ? 'medium' : this.ceiling;
      if (this.level === 'high') { this.trial = false; this.apply('medium'); }
    } else if (this.ceiling === 'medium') this.ceiling = 'high';
  }

  /** Choose a setting from the menu. */
  set(setting: QualitySetting): void {
    this.setting = setting;
    try { localStorage.setItem(KEY, setting); } catch { /* not remembered */ }
    this.ceiling = 'high';
    this.trial = false;
    this.apply(setting === 'auto' ? this.level : setting);
  }

  /** Put a level into effect: the canvas's pixel ratio, the multisampling and the shadows. */
  apply(level: QualityLevel): void {
    this.level = level;
    const s = SPEC[level];
    this.renderer.setPixelRatio(s.ratio());
    this.resize();
    this.post.configure({ samples: s.samples, rounds: s.blurRounds });
    // shadows are faded out rather than switched off: a light that stops casting changes every lit
    // material's shader, and recompiling all of them froze the game for seconds at each step to Lowest
    this.key.castShadow = true;
    this.key.shadow.intensity = s.shadows ? 1 : 0;
    // a new size: the map is let go and three makes it again at the next shadow pass
    if (this.key.shadow.mapSize.x !== s.shadowMap) {
      this.key.shadow.mapSize.set(s.shadowMap, s.shadowMap);
      this.key.shadow.map?.dispose();
      this.key.shadow.map = null;
    }
    this.renderer.shadowMap.autoUpdate = s.shadows && s.shadowEvery === 1;
    this.renderer.shadowMap.needsUpdate = s.shadows;
    this.intervals = [];
    this.sinceChange = 0;
    this.quickFor = 0;
    this.onChange?.();
  }

  /** The window changed size (or the pixel ratio did). */
  resize(): void {
    this.renderer.setSize(innerWidth, innerHeight);
    this.camera.aspect = innerWidth / innerHeight;
    this.camera.updateProjectionMatrix();
    this.post.setSize(innerWidth, innerHeight);
  }

  /**
   * Every frame drawn, with its timestamp: Auto keeps an eye on how long frames take. `capMs` is the
   * least a frame can take under the frame-rate cap (game/frameCap.ts): frames held to 30 a second are
   * the cap, not a slow machine, so slow and quick are judged from there.
   */
  tick(now: number, capMs = 0): void {
    this.frames++;
    const spec = SPEC[this.level];
    // deep in the night the key light is the moon, its shadows faint: redrawn every NIGHT_SHADOW_EVERY
    // frames, not every frame (the shadow pass was a sixth of the slow frames' time in the Oct 2026 playtest)
    const every = spec.shadowEvery * (this.night > 0.85 ? NIGHT_SHADOW_EVERY : 1);
    this.renderer.shadowMap.autoUpdate = spec.shadows && every === 1;
    if (!this.renderer.shadowMap.autoUpdate) this.renderer.shadowMap.needsUpdate = spec.shadows && this.frames % every === 0;
    const dt = this.last ? now - this.last : 16.7;
    this.last = now;
    if (this.setting !== 'auto' || document.hidden || dt > 250) return;
    if (this.hold) { this.intervals.length = 0; this.sinceChange = 0; this.quickFor = 0; return; }
    this.intervals.push(dt);
    if (this.intervals.length > 60) this.intervals.shift();
    this.sinceChange += dt / 1000;
    if (this.sinceChange < SETTLE_S || this.intervals.length < 45) return;
    // the median, so a chunk being built or a world loading does not count as the machine being slow
    const sorted = [...this.intervals].sort((a, b) => a - b);
    const median = sorted[sorted.length >> 1];
    const i = QUALITY_LEVELS.indexOf(this.level);
    const slow = Math.max(SLOW_MS, capMs * 1.08), quick = Math.max(QUICK_MS, capMs * 1.02);
    if (median > slow && i < QUALITY_LEVELS.length - 1) {
      // a step up that did not hold: back down, and that is as high as this machine goes
      if (this.trial) this.ceiling = QUALITY_LEVELS[i + 1];
      this.trial = false;
      this.apply(QUALITY_LEVELS[i + 1]);
      return;
    }
    if (this.trial && this.sinceChange > SETTLE_S + 4) this.trial = false;
    if (median < quick) this.quickFor += dt / 1000;
    else this.quickFor = 0;
    const ceilingIdx = QUALITY_LEVELS.indexOf(this.ceiling);
    if (this.quickFor > UP_AFTER_S && i > ceilingIdx) {
      this.trial = true;
      this.apply(QUALITY_LEVELS[i - 1]);
    }
  }

  /** The level's CPU side (CpuSpec): how much traffic, blur and full-detail distance. */
  get cpu(): CpuSpec { const s = SPEC[this.level]; return { crowd: s.crowd, blurRounds: s.blurRounds, reach: s.reach }; }

  /** "Auto · Medium", "High". */
  describe(): string {
    return this.setting === 'auto' ? `Auto · ${SPEC[this.level].label}` : SPEC[this.level].label;
  }
}
