/**
 * How the tech map lays its lines (game/techTab.ts): each tree is a grid of branch rows (tech.ts ROWS) by
 * tier columns, one node a cell. A line from a parent to its child runs along the row when both stand on
 * it; between rows it runs along one of them and bends once, in a single tier gap, into the other. Which
 * row it runs along is whichever passes only empty cells: the parent's, bending in the last gap before the
 * child ('late', so a trunk's lines share its row until they fork), else the child's ('early').
 *
 * `layoutFaults` is the gate's (scripts/territory.ts part 4): a node off its tree's rows or sharing a cell,
 * a parent more than a row away, a line with no clear run, two bends crossing in one gap, or two parents'
 * runs lying along one row. With none, no line crosses another and none passes under a node.
 */
import { ROWS, TECH, TECH_BY_ID, TREES, type TechNode, type Tree } from './tech';

export type RouteKind = 'row' | 'late' | 'early' | 'direct';

const cell = (tree: Tree, row: number, tier: number) => `${tree}:${row}:${tier}`;
const TAKEN = new Set(TECH.filter((n) => !n.standing).map((n) => cell(n.tree, n.row, n.tier)));
/** No node on `row` strictly between tiers t0 and t1. */
const clear = (tree: Tree, row: number, t0: number, t1: number): boolean => {
  for (let t = t0 + 1; t < t1; t++) if (TAKEN.has(cell(tree, row, t))) return false;
  return true;
};

/** How the line from parent `p` to child `c` is drawn. 'direct' (a plain curve) only when neither row is clear. */
export function route(c: TechNode, p: TechNode): RouteKind {
  if (p.row === c.row) return 'row';
  if (clear(c.tree, p.row, p.tier, c.tier)) return 'late';
  if (clear(c.tree, c.row, p.tier, c.tier)) return 'early';
  return 'direct';
}

/** Every line of the map, with its route: child, parent, and the tier gap its bend sits in (the gap left of column g+1). */
export function lines(): { c: TechNode; p: TechNode; kind: RouteKind; gap: number }[] {
  const out: { c: TechNode; p: TechNode; kind: RouteKind; gap: number }[] = [];
  for (const c of TECH) {
    for (const id of c.from) {
      const p = TECH_BY_ID.get(id);
      if (!p) continue;
      const kind = route(c, p);
      out.push({ c, p, kind, gap: kind === 'early' ? p.tier : c.tier - 1 });
    }
  }
  return out;
}

export function layoutFaults(): string[] {
  const faults: string[] = [];
  const seen = new Map<string, string>();
  for (const n of TECH) {
    if (n.standing) continue;
    if (!(n.row >= 0 && n.row < ROWS[n.tree].length)) faults.push(`${n.id}: row ${n.row} is off the ${n.tree} tree's ${ROWS[n.tree].length} rows`);
    const k = cell(n.tree, n.row, n.tier);
    if (seen.has(k)) faults.push(`${n.id} and ${seen.get(k)} share a cell (${n.tree} row ${n.row}, tier ${n.tier})`);
    seen.set(k, n.id);
  }
  // a run along a row through a tier gap: only one parent's lines may lie there
  const runs = new Map<string, string>();
  const run = (tree: Tree, row: number, g0: number, g1: number, parent: string, child: string) => {
    for (let g = g0; g < g1; g++) {
      const k = `${tree}:${row}:${g}`, was = runs.get(k);
      if (was && was !== parent) faults.push(`${parent} → ${child} runs along ${tree} row ${row} over ${was}'s line at tier ${g}`);
      runs.set(k, parent);
    }
  };
  const bends: { tree: Tree; gap: number; r0: number; r1: number; p: string; c: string }[] = [];
  for (const { c, p, kind, gap } of lines()) {
    if (Math.abs(c.row - p.row) > 1) faults.push(`${p.id} → ${c.id}: ${Math.abs(c.row - p.row)} rows apart (one at most)`);
    if (kind === 'direct') faults.push(`${p.id} → ${c.id}: no clear run along either row`);
    if (kind === 'row') { if (!clear(c.tree, c.row, p.tier, c.tier)) faults.push(`${p.id} → ${c.id}: a node in the way on the row`); run(c.tree, c.row, p.tier, c.tier, p.id, c.id); }
    if (kind === 'late') { run(c.tree, p.row, p.tier, c.tier - 1, p.id, c.id); bends.push({ tree: c.tree, gap, r0: p.row, r1: c.row, p: p.id, c: c.id }); }
    if (kind === 'early') { run(c.tree, c.row, p.tier + 1, c.tier, p.id, c.id); bends.push({ tree: c.tree, gap, r0: p.row, r1: c.row, p: p.id, c: c.id }); }
  }
  // two bends in one gap cross when their rows swap order (sharing a start or an end is a fork or a merge)
  for (let i = 0; i < bends.length; i++) {
    for (let j = i + 1; j < bends.length; j++) {
      const a = bends[i], b = bends[j];
      if (a.tree !== b.tree || a.gap !== b.gap) continue;
      if ((a.r0 - b.r0) * (a.r1 - b.r1) < 0) faults.push(`${a.p} → ${a.c} crosses ${b.p} → ${b.c} between tiers ${a.gap} and ${a.gap + 1}`);
    }
  }
  // every row forks off early: its first node at tier 4 (◆ 32) or sooner, so a late model's branch is a choice made cheaply
  for (const tree of TREES) {
    ROWS[tree].forEach((name, row) => {
      const first = TECH.filter((n) => !n.standing && n.tree === tree && n.row === row).sort((a, b) => a.tier - b.tier)[0];
      if (!first) faults.push(`${tree} row ${name} has no node`);
      else if (first.tier > 4) faults.push(`${tree} row ${name} starts at tier ${first.tier}: should fork off by tier 4`);
    });
  }
  return faults;
}
