import { DIRS, STEP, type Building, type World } from '../world/tiles';
import { mulberry32 } from '../world/rng';
import { setModelSolid } from '../world/footprint';
import { Kit, setOffStrip, setStyle } from './buildings/kit';
import { frontsStrip } from '../world/strip';
import { VARIANTS } from './buildings/variants';
import { builtShare, drawOf } from './townMesh';

/**
 * The walls a car meets, taken from the model a building really draws. A kind with alternative models
 * (buildings/variants) mostly has no hand-drawn shape in world/footprint.ts, so it was solid over its
 * whole lot, and the smaller or set-back alternatives had an invisible wall round them. Here the model
 * is drawn once, off screen, and whatever of it stands in the height band a car's body fills is laid
 * on a fine grid; everything the walls close in is solid too, and the rest of the lot is open ground.
 *
 * Only the car's precise wall test reads this (solidAt with a world): which tiles are blocked is still
 * worldgen's tile mask, so worlds and saves are untouched.
 */

/** The band above the building's floor, world units, that stops a car: steps, kerbs and low hedges are under it, eaves over it. */
const LO = 0.1, HI = 0.32;
/** Grid cells per tile. */
const RES = 12;

type Solid = (lx: number, lz: number) => boolean;
const CACHE = new WeakMap<Building, Solid | null>();

/** The drawn model's walls for any building, for auditing a kind's hand-measured shape against what it draws (from the console). */
function drawnSolid(w: World, b: Building): Solid | null { return probe(w, b); }

function probe(w: World, b: Building): Solid | null {
  const t = w.towns.find((q) => q.buildings.includes(b)) ?? null;
  const k = new Kit(w);
  const style = b.style ?? t?.style ?? 'classic';
  setStyle(style, ((b.seed >>> 0) % 997) / 997);
  // the same model townMesh draws: in a Las Vegas, off the Strip, nothing lit up (kit.ts offStrip)
  if (style === 'vegas') setOffStrip(!frontsStrip(w, b));
  const alongZ = b.facing % 2 === 1;
  const W = alongZ ? b.w : b.d, D = alongZ ? b.d : b.w;
  const ox = b.x + b.w / 2, oy = b.level * STEP, oz = b.z + b.d / 2;
  const yaw = Math.atan2(DIRS[b.facing][0], DIRS[b.facing][1]);
  k.place(ox, oy, oz, yaw);
  drawOf(b, t ?? null, w)(k, W, D, b, mulberry32(b.seed), t);
  const c = Math.cos(yaw), s = Math.sin(yaw);
  // the lot in the model's frame, with a cell of open ground all round for the fill to start from
  const nx = Math.ceil(W * RES) + 2, nz = Math.ceil(D * RES) + 2, x0 = -W / 2 - 1 / RES, z0 = -D / 2 - 1 / RES;
  const wall = new Uint8Array(nx * nz);
  const p = k.pos;
  const mark = (X: number, Y: number, Z: number) => {
    const y = Y - oy;
    if (y < LO || y > HI) return;
    const dx = X - ox, dz = Z - oz;
    const gx = Math.floor((dx * c - dz * s - x0) * RES), gz = Math.floor((dx * s + dz * c - z0) * RES);
    if (gx > 0 && gz > 0 && gx < nx - 1 && gz < nz - 1) wall[gz * nx + gx] = 1;
  };
  for (let i = 0; i < p.length; i += 9) {
    const ay = p[i + 1] - oy, by = p[i + 4] - oy, cy = p[i + 7] - oy;
    if (Math.max(ay, by, cy) < LO || Math.min(ay, by, cy) > HI) continue;
    // sampled at half a cell, so a wall's trace on the grid has no gaps for the fill to leak through
    const L = Math.max(
      Math.hypot(p[i + 3] - p[i], p[i + 4] - p[i + 1], p[i + 5] - p[i + 2]),
      Math.hypot(p[i + 6] - p[i], p[i + 7] - p[i + 1], p[i + 8] - p[i + 2]),
      Math.hypot(p[i + 6] - p[i + 3], p[i + 7] - p[i + 4], p[i + 8] - p[i + 5]),
    );
    const n = Math.max(1, Math.ceil(L * RES * 2));
    for (let u = 0; u <= n; u++) {
      for (let v = 0; u + v <= n; v++) {
        const a = u / n, bb = v / n, cc = 1 - a - bb;
        mark(
          p[i] * a + p[i + 3] * bb + p[i + 6] * cc,
          p[i + 1] * a + p[i + 4] * bb + p[i + 7] * cc,
          p[i + 2] * a + p[i + 5] * bb + p[i + 8] * cc,
        );
      }
    }
  }
  // open ground is what can be reached from outside the lot without crossing a wall; the rest is solid
  const open = new Uint8Array(nx * nz);
  const stack: number[] = [0];
  open[0] = 1;
  while (stack.length) {
    const g = stack.pop()!, gx = g % nx, gz = (g - gx) / nx;
    for (const [ax, az] of [[gx + 1, gz], [gx - 1, gz], [gx, gz + 1], [gx, gz - 1]]) {
      if (ax < 0 || az < 0 || ax >= nx || az >= nz) continue;
      const q = az * nx + ax;
      if (!open[q] && !wall[q]) { open[q] = 1; stack.push(q); }
    }
  }
  return (lx, lz) => {
    const gx = Math.floor((lx - x0) * RES), gz = Math.floor((lz - z0) * RES);
    return gx >= 0 && gz >= 0 && gx < nx && gz < nz && !open[gz * nx + gx];
  };
}

/** The drawn model's walls for a kind with alternative models, the original's included; undefined otherwise. */
export function modelSolid(w: World, b: Building): Solid | null | undefined {
  if (!VARIANTS[b.kind]) return undefined;
  let s = CACHE.get(b);
  if (s !== undefined) return s;
  // still going up: the site isn't the model yet, so the lot's own shape stands for it
  if (builtShare(b) < 1) return undefined;
  try { s = probe(w, b); } catch { s = null; }
  CACHE.set(b, s);
  return s;
}

setModelSolid((w, b) => modelSolid(w, b) ?? undefined);
