import * as THREE from 'three';
import type { VehicleDef } from './vehicles';
import { esc, money } from './cargoHud';
import type { Wallet } from './economy';
import { defOf, type Fleet, type Unit } from './fleet';
import {
  PALETTE, applyParts, coatPrice, colourName, effectLine, fitted, headline, owedFor, owned, slotName, slotOf, slotsFor, tierName,
  type Parts, type SlotId,
} from './parts';
import { FLANK_BOTTLES, nosSpot } from '../render/boltOns';
import { compileReady } from '../render/compileReady';
import { speedText } from './units';

/**
 * The workshop tab of the G menu: the unit's name and numbers across the top, the unit itself large and
 * turning slowly in the middle, and a square for every part it takes set round it, each on a line to the
 * part of the vehicle it belongs to ("STOCK" until something is fitted). A square opens a tray of that
 * part's tiers with their prices; picking one buys it if need be and fits it. A click anywhere off the
 * tray puts it away again.
 */

/** A vehicle built for the stage: its holder, its tyres, how far workshop parts lift its body, and how to let it go. */
interface StageModel {
  holder: THREE.Object3D;
  body?: THREE.Object3D;
  wheels: THREE.Object3D[];
  lift: number;
  dispose(): void;
}

interface WorkshopHost {
  /** The units in the menu's order. */
  units(): Unit[];
  /** The unit the menu has chosen, and choosing another. */
  selected(): number;
  select(uid: number): void;
  /** A line in the menu's note (the wallet line otherwise). */
  say(text: string): void;
  /** Money or parts have changed: bring the whole menu up to date. */
  sync(): void;
  /** The unit built in 3D, as it is now. */
  model(def: VehicleDef): StageModel;
  /**
   * What buying this part costs here, as a multiple of its list price: a Vehicle Shop's rate when the
   * menu was opened at one that stocks it, else null (it can't be bought here; owned tiers still fit).
   */
  partMul(slot: SlotId): number | null;
  /** Where this part can be bought, for the line when it can't be here. */
  whereToBuy(slot: SlotId): string;
  /** Money went over the shop's counter. */
  paid(amount: number): void;
}

/** A tier price at the shop's rate, the way Fleet.fit charges it. */
const at = (owe: number, mul: number): number => (owe > 0 && mul !== 1 ? Math.max(10, Math.round((owe * mul) / 10) * 10) : owe);

/** One tray: the part's tiers, and for paint its colours and the accent once the two-tone is owned. */
type TrayRow = 'tier' | 'colour' | 'accent';

interface Stat { label: string; val: (d: VehicleDef) => number; text: (d: VehicleDef, stock: VehicleDef) => string; lower?: boolean }

const kmh = (v: number) => Math.round(v * 12);
const toTop = (d: VehicleDef) => d.topSpeed / Math.max(0.01, d.accel);
const secs = (v: number) => `${v < 10 ? v.toFixed(1) : Math.round(v)} s`;
const times = (a: number, b: number) => (Math.abs(a - b) < 1e-6 ? 'stock' : `×${(a / b).toFixed(2).replace(/0$/, '')}`);

/** The bars across the top, per kind of vehicle. */
function statsFor(kind: VehicleDef['kind']): Stat[] {
  const out: Stat[] = [
    { label: 'Top speed', val: (d) => d.topSpeed, text: (d) => speedText(kmh(d.topSpeed)) },
    { label: 'Acceleration', val: (d) => d.accel, text: (d) => `0–top ${secs(toTop(d))}` },
    { label: 'Braking', val: (d) => d.brake, text: (d, s) => times(d.brake, s.brake) },
  ];
  if (kind !== 'rail') out.push({ label: 'Holds', val: (d) => d.capacity, text: (d) => `${d.capacity} units` });
  if (kind === 'land') {
    out.push(
      { label: 'Kerbs', val: (d) => (d.kind === 'land' ? d.curb : 0), text: (d) => (d.kind === 'land' ? ['none', 'low', 'high'][d.curb] ?? String(d.curb) : '') },
      { label: 'Off-road grip', val: (d) => (d.kind === 'land' ? d.grip ?? 1 : 1), text: (d) => (d.kind === 'land' ? `×${(d.grip ?? 1).toFixed(1)}` : '') },
    );
  } else if (kind === 'air') {
    out.push(
      { label: 'Climb', val: (d) => (d.kind === 'air' ? d.climbRate : 0), text: (d, s) => (d.kind === 'air' && s.kind === 'air' ? times(d.climbRate, s.climbRate) : '') },
      { label: 'Ceiling', val: (d) => (d.kind === 'air' ? d.maxClear : 0), text: (d) => (d.kind === 'air' ? String(d.maxClear) : '') },
    );
  } else if (kind === 'water') {
    out.push({ label: 'Grip', val: (d) => (d.kind === 'water' ? d.grip : 0), text: (d, s) => (d.kind === 'water' && s.kind === 'water' ? times(d.grip, s.grip) : '') });
  }
  return out;
}

/** Every slot at its top tier: the most a unit can be, for the bars' full width. */
function fullParts(def: VehicleDef): Parts {
  const p: Parts = { t: {}, spent: 0 };
  for (const s of slotsFor(def)) p.t[s.id] = [3, 3];
  return p;
}

/** A unit's parts with one slot's fitted tier swapped, to price and describe it without touching the unit. */
function withTier(p: Parts | undefined, slot: SlotId, tier: number): Parts {
  const out: Parts = { t: { ...(p?.t ?? {}) }, spent: p?.spent ?? 0, c: p?.c, a: p?.a };
  out.t[slot] = [Math.max(owned(p, slot), tier), tier];
  return out;
}

const SQ = 76;       // a part's square, in CSS pixels
const FOV = 26;
/** A part fitted for the player: how long the stage shows the vehicle without it, the poof's cover before it appears, and the red line's run out to its square. */
const POOF_AT = 0.6, SWAP = 0.14, LINE_AT = 1.05, LINE_RUN = 0.3;
const DOWN = new THREE.Vector3(0, -1, 0);

/** One ball of the poof's smoke. */
interface Puff { m: THREE.Mesh; v: THREE.Vector3; spin: THREE.Vector3; r: number; age: number; life: number }

export class WorkshopView {
  readonly el = document.createElement('section');
  private head = document.createElement('header');
  private statsEl = document.createElement('div');
  private stage = document.createElement('div');
  private canvas = document.createElement('canvas');
  private svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  private squares = document.createElement('div');
  private dim = document.createElement('div');
  private tray = document.createElement('div');
  private foot = document.createElement('footer');

  // the 3D stage
  private renderer: THREE.WebGLRenderer | null = null;
  private scene = new THREE.Scene();
  private cam = new THREE.PerspectiveCamera(FOV, 2, 0.05, 200);
  private pivot = new THREE.Group();
  private model: StageModel | null = null;
  /** Which unit and which look the stage holds, so it is only rebuilt when that changes. */
  private builtKey = '';
  /** Each slot's point on the vehicle, in the pivot's frame. */
  private anchors = new Map<SlotId, THREE.Vector3>();
  /** Each square's centre on the stage, in CSS pixels. */
  private pos = new Map<SlotId, { x: number; y: number }>();
  private W = 0;
  private H = 0;
  private visible = false;
  private raf = 0;
  private t = 0;
  private last = 0;
  private yaw = 0;
  private drag: { x: number; yaw: number } | null = null;
  /** Seconds since the pointer last turned it; the sway comes back after a while. */
  private idle = 99;
  /** How far the view is lifted and drawn back while a tray is out, so the vehicle stays in sight above it. */
  private shift = 0;
  /** The press that put a tray away: its click must not open whatever square was under the tray. */
  private swallow = 0;
  private zoom = 1;

  // what the keys and the pointer are on
  /** The square the keys are on; null is the unit switcher across the top. */
  private focus: SlotId | null = null;
  /** The tray, when one is out: its slot, the row and the column the keys are on. */
  private open: { slot: SlotId; row: TrayRow; col: number } | null = null;
  /** The tier (or colour) the pointer is over in the tray, previewed in the bars. */
  private hover: { row: TrayRow; col: number } | null = null;
  private stats = new Map<string, number[]>();
  /** The keys have been used: show where they are. */
  private keyed = false;
  /**
   * A part just fitted for the player (the first drive's nitrous and handbrake): the stage opens without it,
   * it appears in a poof of smoke, then a red line runs out to its square, which glows, badged, until the
   * workshop closes. `stage` 0 is before the poof, 1 the part on the vehicle, 2 its square lit.
   */
  private fresh: { slot: SlotId; note: string; t: number; stage: 0 | 1 | 2; litAt: number } | null = null;
  private puffs: Puff[] = [];
  private puffGeo = new THREE.IcosahedronGeometry(1, 0);
  private v = new THREE.Vector3();
  private size = new THREE.Vector2();

  constructor(private fleet: Fleet, private wallet: Wallet, private defs: VehicleDef[], private host: WorkshopHost) {
    this.el.className = 'wk';
    this.head.className = 'wk-head';
    this.statsEl.className = 'wk-stats';
    this.stage.className = 'wk-stage';
    this.canvas.className = 'wk-canvas';
    this.svg.classList.add('wk-lines');
    this.squares.className = 'wk-squares';
    this.dim.className = 'wk-dim';
    this.tray.className = 'wk-tray';
    this.foot.className = 'wk-foot';
    this.dim.hidden = true;
    this.tray.hidden = true;
    this.stage.append(this.canvas, this.svg, this.squares, this.dim, this.tray);
    const top = document.createElement('div');
    top.className = 'wk-top';
    top.append(this.head, this.statsEl);
    this.el.append(top, this.stage, this.foot);

    this.scene.add(new THREE.HemisphereLight(0xd8ecff, 0x9aa7ae, 1.2));
    const sun = new THREE.DirectionalLight(0xfff1d6, 2.4);
    sun.position.set(3, 6, 4);
    this.scene.add(sun);
    const rim = new THREE.DirectionalLight(0xcfe4ff, 0.8);
    rim.position.set(-4, 3, -3);
    this.scene.add(rim);
    this.scene.add(this.pivot);

    // a press anywhere off the tray puts it away (the squares are under the dimmer while it is out)
    this.el.addEventListener('mousedown', (e) => {
      if (!this.open) return;
      if (this.tray.contains(e.target as Node)) return;
      this.closeTray();
      this.swallow = performance.now() + 600;
      e.preventDefault();
      e.stopPropagation();
    }, true);
    this.head.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-step]');
      if (b) this.step(Number(b.dataset.step));
    });
    this.squares.addEventListener('click', (e) => {
      if (performance.now() < this.swallow) return;
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-slot]');
      if (b) this.openTray(b.dataset.slot as SlotId);
    });
    this.squares.addEventListener('mouseover', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-slot]');
      if (b && !this.open && this.focus !== b.dataset.slot) { this.focus = b.dataset.slot as SlotId; this.keyed = false; this.paintFocus(); }
    });
    this.tray.addEventListener('click', (e) => this.onTrayClick(e));
    this.tray.addEventListener('mouseover', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-col]');
      if (!b) return;
      const h = { row: b.dataset.row as TrayRow, col: Number(b.dataset.col) };
      if (this.hover?.row === h.row && this.hover.col === h.col) return;
      this.hover = h;
      this.preview();
    });
    this.tray.addEventListener('mouseleave', () => { this.hover = null; this.preview(); });
    // drag the vehicle round
    this.canvas.addEventListener('mousedown', (e) => { this.drag = { x: e.clientX, yaw: this.yaw }; e.preventDefault(); });
    window.addEventListener('mousemove', (e) => {
      if (!this.drag) return;
      this.yaw = this.drag.yaw + (e.clientX - this.drag.x) * 0.012;
      this.idle = 0;
    });
    window.addEventListener('mouseup', () => { this.drag = null; });
    new ResizeObserver(() => this.resize()).observe(this.stage);
  }

  private unit(): Unit | null { return this.fleet.unit(this.host.selected()); }

  /** The tab is showing (or not): the stage only draws while it can be seen. */
  setVisible(on: boolean): void {
    if (!on) { this.fresh = null; this.clearPuffs(); }
    if (on === this.visible) return;
    this.visible = on;
    if (!on) {
      cancelAnimationFrame(this.raf);
      this.closeTray(false);
      return;
    }
    // measured now, not when the resize observer next reports: the first frame draws the vehicle rather than nothing
    this.resize();
    this.last = performance.now();
    const loop = (now: number) => {
      if (!this.visible) return;
      this.frame(Math.min(0.1, (now - this.last) / 1000));
      this.last = now;
      this.raf = requestAnimationFrame(loop);
    };
    this.raf = requestAnimationFrame(loop);
  }

  /** Another unit was chosen: back to the view of the whole thing. */
  unitChanged(): void {
    this.fresh = null;
    this.clearPuffs();
    this.closeTray(false);
    this.focus = null;
    this.yaw = 0;
    this.idle = 99;
  }

  /**
   * Make the stage ready before it is first opened (the user, 5 Nov 2026: the first workshop of a game, the
   * free nitrous's, showed an empty stage while the car blinked in). Its WebGL context is made, and the vehicle
   * under you is built as the stage shows it, stock and with every part on, and their shaders compiled, in a
   * scene of its own with the stage's lights, off screen; the models are thrown away. Once a game, a few
   * seconds in; nothing when the stage has been drawn already.
   */
  private warmed = false;
  async warm(): Promise<void> {
    if (this.warmed || this.renderer || this.visible) return;
    this.warmed = true;
    const u = this.fleet.ridden ?? this.unit();
    if (!u) return;
    const def = this.fleet.defFor(u);
    if (def.kind === 'rail') return;
    this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, alpha: true });
    this.renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
    this.renderer.toneMapping = THREE.NeutralToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    const scene = new THREE.Scene();
    for (const o of this.scene.children) if ((o as THREE.Light).isLight) scene.add(o.clone());
    const models = [def, applyParts(def, fullParts(def))].map((d) => this.host.model(d));
    for (const m of models) scene.add(m.holder);
    const cam = this.cam.clone();
    cam.position.set(0, 2, 6);
    cam.lookAt(0, 0, 0);
    try { await compileReady(this.renderer, scene, cam); } catch { /* compiled when it is first drawn instead */ }
    for (const m of models) { scene.remove(m.holder); m.dispose(); }
  }

  /** Show a part the player was just given going on to the unit on the stage: see `fresh`. */
  reveal(slot: SlotId, note: string): void {
    this.clearPuffs();
    this.fresh = { slot, note, t: 0, stage: 0, litAt: 0 };
  }

  /** Skip to the end of a reveal (the player went for a square before it finished). */
  private revealDone(): void {
    const f = this.fresh;
    if (!f || f.stage === 2) return;
    f.t = LINE_AT + LINE_RUN;
    f.stage = 2;
    f.litAt = performance.now();
    this.render();
  }

  /** The unit as a reveal shows it: without the part, before it goes on. */
  private without(u: Unit, slot: SlotId): Unit {
    if (!u.parts || !u.parts.t[slot]) return u;
    const t = { ...u.parts.t };
    delete t[slot];
    return { ...u, parts: { ...u.parts, t } };
  }

  // ---- drawing ----

  render(): void {
    const units = this.host.units();
    const u = this.unit();
    if (!u) {
      this.head.innerHTML = '<div class="wk-id"><div><h3>Workshop</h3><small>Buy something at a Vehicle Dealer and it can be worked on here.</small></div></div>';
      this.statsEl.innerHTML = '';
      this.squares.innerHTML = '';
      this.foot.innerHTML = '';
      this.clearModel();
      return;
    }
    const model = defOf(u.model);
    // a reveal under way: the vehicle without the part until the poof, the squares and bars until its line lights
    const f = this.fresh;
    const shown = f && f.stage < 2 ? this.without(u, f.slot) : u;
    const now = this.fleet.defFor(shown);
    const look = f && f.stage < 1 ? now : this.fleet.defFor(u);
    const at = units.findIndex((q) => q.uid === u.uid);
    const many = units.length > 1;
    this.head.innerHTML = `<div class="wk-id${this.keyed && this.focus === null && !this.open ? ' kfocus' : ''}">
        <button type="button" class="wk-step" data-step="-1" title="Previous unit (Q)"${many ? '' : ' disabled'}>‹</button>
        <div><h3>${esc(u.name)}</h3><small>${u.name !== model.name ? `${esc(model.name)} · ` : ''}${units.length > 1 ? `${at + 1} of ${units.length}` : 'your only unit'}</small></div>
        <button type="button" class="wk-step" data-step="1" title="Next unit (E)"${many ? '' : ' disabled'}>›</button>
      </div>
      <p class="wk-headline">${esc(headline(now))}</p>`;
    this.renderStats(now, null);

    const slots = slotsFor(model);
    if (this.focus && !slots.some((s) => s.id === this.focus)) this.focus = null;
    this.squares.innerHTML = slots.map((s) => {
      const fit = fitted(shown.parts, s.id), have = owned(shown.parts, s.id);
      const label = fit ? tierName(s, model, fit) : 'Stock';
      const pips = [1, 2, 3].map((t) => `<i class="${t <= fit ? 'fit' : t <= have ? 'own' : ''}"></i>`).join('');
      const swatch = s.id === 'paint' && fit ? ` style="--sw:#${(shown.parts?.c ?? model.color).toString(16).padStart(6, '0')}"` : '';
      const fresh = f?.slot === s.id && f.stage === 2;
      // it pops in once, when it lights; a later redraw leaves it still
      const pop = fresh && performance.now() - f!.litAt < 300 ? ' pop' : '';
      const sold = this.host.partMul(s.id) !== null;
      return `<button type="button" class="wk-sq${fit ? ' tuned' : ''}${s.id === 'paint' && fit ? ' painted' : ''}${fresh ? ' fresh' : ''}${pop}${sold ? ' sold' : ''}" data-slot="${s.id}"${swatch}>
        ${fresh ? `<span class="wk-new">${esc(f!.note)}</span>` : sold ? '<span class="wk-sold">In stock</span>' : ''}<span class="ic">${s.icon}</span><span class="nm">${esc(slotName(s, model))}</span><b>${esc(label)}</b><span class="pips">${pips}</span></button>`;
    }).join('');
    this.placeSquares();
    this.paintFocus();

    const spent = u.parts?.spent ?? 0;
    this.foot.innerHTML = `<span>${spent ? `${money(spent)} in parts` : 'Nothing fitted yet'} · sells for ${money(this.fleet.resale(u))}</span>
      <span class="wk-keys"><kbd>←</kbd><kbd>→</kbd><kbd>↑</kbd><kbd>↓</kbd> choose · <kbd>Enter</kbd> open · <kbd>Q</kbd><kbd>E</kbd> unit · drag to turn it</span>`;

    const key = `${u.uid}|${look.id}|${look.looks?.key ?? ''}`;
    if (key !== this.builtKey) this.build(look, key);
    if (this.open) this.renderTray();
  }

  /** The bars, with a preview def's change laid over them: green where it gains, red where it loses. */
  private renderStats(now: VehicleDef, next: VehicleDef | null): void {
    const u = this.unit();
    if (!u) return;
    const stock = defOf(u.model);
    const stats = statsFor(stock.kind);
    const top = this.statTops(stock.kind, stats);
    this.statsEl.innerHTML = stats.map((s, i) => {
      const max = top[i] || 1;
      const a = Math.min(1, s.val(now) / max), b = next ? Math.min(1, s.val(next) / max) : a;
      const lo = Math.min(a, b), hi = Math.max(a, b);
      const cls = b > a + 1e-4 ? 'up' : b < a - 1e-4 ? 'down' : '';
      const text = next && cls ? `${s.text(now, stock)} → ${s.text(next, stock)}` : s.text(now, stock);
      return `<div class="wk-stat ${cls}"><span class="lb">${s.label}</span>
        <span class="bar"><i class="base" style="width:${(lo * 100).toFixed(1)}%"></i>${cls ? `<i class="delta" style="left:${(lo * 100).toFixed(1)}%;width:${((hi - lo) * 100).toFixed(1)}%"></i>` : ''}</span>
        <span class="vl">${esc(text)}</span></div>`;
    }).join('');
  }

  /** How long each bar is when full: the best any model of the kind reaches with everything fitted. */
  private statTops(kind: VehicleDef['kind'], stats: Stat[]): number[] {
    let top = this.stats.get(kind);
    if (!top) {
      top = stats.map(() => 0);
      for (const d of this.defs) {
        if (d.kind !== kind) continue;
        const best = applyParts(d, fullParts(d));
        stats.forEach((s, i) => { top![i] = Math.max(top![i], s.val(best), s.val(d)); });
      }
      this.stats.set(kind, top);
    }
    return top;
  }

  private paintFocus(): void {
    for (const b of Array.from(this.squares.querySelectorAll<HTMLElement>('.wk-sq'))) {
      const s = b.dataset.slot as SlotId;
      b.classList.toggle('kfocus', this.keyed && s === this.focus && !this.open);
      b.classList.toggle('on', s === this.open?.slot);
    }
    this.head.querySelector('.wk-id')?.classList.toggle('kfocus', this.keyed && this.focus === null && !this.open);
  }

  // ---- the stage ----

  private clearModel(): void {
    if (this.model) {
      this.pivot.remove(this.model.holder);
      this.model.dispose();
      this.model = null;
    }
    this.builtKey = '';
    this.anchors.clear();
  }

  private build(def: VehicleDef, key: string): void {
    const sameUnit = this.builtKey.split('|')[0] === key.split('|')[0];
    this.clearModel();
    this.builtKey = key;
    const m = this.host.model(def);
    this.model = m;
    if (m.body) m.body.position.y = m.lift;
    this.pivot.rotation.set(0, 0, 0);
    this.pivot.add(m.holder);
    m.holder.position.set(0, 0, 0);
    this.pivot.updateMatrixWorld(true);
    // centre it on the turntable
    const box = new THREE.Box3().setFromObject(m.holder);
    const c = box.getCenter(new THREE.Vector3());
    m.holder.position.set(-c.x, -box.min.y, -c.z);
    this.pivot.updateMatrixWorld(true);
    box.setFromObject(m.holder);
    this.findAnchors(def, box);
    this.fit(box);
    // a part going on keeps the layout the eye has learned; a new unit lays it out afresh
    if (!sameUnit || !this.pos.size) this.layout();
    else this.placeSquares();
  }

  /** Where each part is on this vehicle: its wheels for the tyres and brakes, the box's faces for the rest. */
  private findAnchors(def: VehicleDef, box: THREE.Box3): void {
    const m = this.model!;
    const min = box.min, max = box.max;
    const len = max.z - min.z, h = max.y - min.y, wid = max.x - min.x;
    const mid = (min.z + max.z) / 2;
    const nose = max.z, tail = min.z;
    const inv = new THREE.Matrix4().copy(this.pivot.matrixWorld).invert();
    // the wheels on the near side (+x faces the camera), front and back
    const wheels = m.wheels.map((w) => w.getWorldPosition(new THREE.Vector3()).applyMatrix4(inv));
    const near = wheels.filter((w) => w.x > 0);
    const side = near.length ? near : wheels;
    const front = side.length ? side.reduce((a, b) => (b.z > a.z ? b : a)) : null;
    const back = side.length ? side.reduce((a, b) => (b.z < a.z ? b : a)) : null;
    const at = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
    // the height of whatever is at a point from above, as the bolt-ons measure it
    const ray = new THREE.Raycaster();
    const topAt = (x: number, z: number): number => {
      ray.set(new THREE.Vector3(x, max.y + 1, z), DOWN);
      const hit = ray.intersectObject(m.holder, true)[0];
      return hit ? hit.point.y : max.y;
    };
    const A = this.anchors;
    const water = def.kind === 'water', air = def.kind === 'air';
    for (const s of slotsFor(def)) {
      let p: THREE.Vector3;
      switch (s.id) {
        case 'paint': p = at(wid * 0.3, min.y + h * 0.62, mid - len * 0.05); break;
        case 'engine': p = water ? at(0, min.y + h * 0.35, tail) : at(0, min.y + h * 0.72, nose - len * 0.16); break;
        case 'gearbox': p = water ? at(0, min.y + h * 0.05, tail + len * 0.05) : air ? at(0, min.y + h * 0.55, mid + len * 0.12) : at(wid * 0.2, min.y + h * 0.18, mid); break;
        case 'tyres': p = front ? front.clone() : at(wid / 2, min.y + h * 0.2, nose - len * 0.2); break;
        case 'brakes': p = !water && !air && back ? back.clone() : air ? at(wid * 0.45, min.y + h * 0.5, tail + len * 0.2) : at(0, min.y + h * 0.3, tail); break;
        case 'suspension': p = front ? front.clone().add(at(0, h * 0.28, -len * 0.04)) : at(wid / 2, min.y + h * 0.4, nose - len * 0.2); break;
        case 'handbrake': p = at(wid * 0.1, min.y + h * 0.55, mid - len * 0.05); break;
        case 'nitrous': {
          // where boltOns puts the bottle: along the flank on the open ones, on top towards the back on the rest
          const spot = nosSpot(def.id);
          if (spot) p = at(spot.x, spot.y, spot.z).multiplyScalar(def.scale ?? 1);
          else if (air || def.kind === 'rail') p = at(wid * 0.18, min.y + h * 0.3, tail);
          else if (FLANK_BOTTLES.has(def.id)) p = at(max.x * 0.55 + 0.05, Math.max(0.28, min.y + 0.26), water ? tail + len * 0.3 : mid - len * 0.1);
          else { const z = tail + len * (water ? 0.2 : 0.22); p = at(0, topAt(0, z), z); }
          break;
        }
        case 'rack': p = at(0, max.y, mid - len * 0.12); break;
        case 'bullbar': p = at(wid * 0.2, min.y + h * 0.3, nose); break;
        case 'horn': p = at(wid * 0.36, min.y + h * 0.5, nose - len * 0.02); break;
        case 'hull': p = at(wid * 0.45, min.y + h * 0.15, mid); break;
        case 'wings': p = at(max.x, min.y + h * 0.65, mid); break;
        default: p = at(0, min.y + h / 2, mid);
      }
      A.set(s.id, p);
    }
  }

  /**
   * Stand the camera off so the vehicle fills the middle of the stage and leaves the ring for the squares:
   * measure its box on screen and move in or out until it takes the room there is.
   */
  private fit(box: THREE.Box3): void {
    const c = box.getCenter(new THREE.Vector3());
    const aspect = this.W && this.H ? this.W / this.H : 2;
    const fy = Math.max(0.45, 1 - (1.7 * SQ) / Math.max(200, this.H));
    const fx = Math.max(0.4, 1 - (2.5 * SQ) / Math.max(300, this.W));
    const dir = new THREE.Vector3(1.25, 0.72, 1.0).normalize();
    const corners: THREE.Vector3[] = [];
    for (const x of [box.min.x, box.max.x]) for (const y of [box.min.y, box.max.y]) for (const z of [box.min.z, box.max.z]) corners.push(new THREE.Vector3(x, y, z));
    this.cam.aspect = aspect;
    this.cam.updateProjectionMatrix();
    let dist = box.getSize(new THREE.Vector3()).length() * 2;
    for (let i = 0; i < 4; i++) {
      this.cam.position.copy(c).addScaledVector(dir, dist);
      this.cam.lookAt(c);
      this.cam.updateMatrixWorld(true);
      let mx = 0, my = 0;
      const mid = c.clone().project(this.cam);
      for (const k of corners) {
        const q = k.clone().project(this.cam);
        mx = Math.max(mx, Math.abs(q.x - mid.x));
        my = Math.max(my, Math.abs(q.y - mid.y));
      }
      // it sways a little either way: keep some over for that
      dist *= Math.max(mx / fx, my / fy) * 1.08;
    }
    this.cam.position.copy(c).addScaledVector(dir, dist);
    this.cam.lookAt(c);
  }

  private resize(): void {
    const r = this.stage.getBoundingClientRect();
    const W = Math.round(r.width), H = Math.round(r.height);
    if (!W || !H || (W === this.W && H === this.H)) return;
    this.W = W; this.H = H;
    this.svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    if (this.renderer) this.renderer.setSize(W, H, false);
    if (this.model) {
      const box = new THREE.Box3().setFromObject(this.model.holder);
      this.fit(box);
      this.layout();
    }
  }

  private project(p: THREE.Vector3): { x: number; y: number; z: number } {
    this.v.copy(p).applyMatrix4(this.pivot.matrixWorld).project(this.cam);
    return { x: (this.v.x + 1) / 2 * this.W, y: (1 - this.v.y) / 2 * this.H, z: this.v.z };
  }

  /**
   * Set the squares round the stage near their parts: each goes out from the middle in the direction of
   * its part on screen, onto a rounded-off rectangle inside the edges, and neighbours that crowd each
   * other are pushed apart round the ring.
   */
  private layout(): void {
    if (!this.W || !this.anchors.size) return;
    this.cam.clearViewOffset();
    this.cam.zoom = 1;
    this.cam.updateProjectionMatrix();
    this.shift = 0;
    this.zoom = 1;
    const saved = this.pivot.rotation.y;
    this.pivot.rotation.y = 0;
    this.pivot.updateMatrixWorld(true);
    const cx = this.W / 2, cy = this.H / 2;
    const items = [...this.anchors].map(([slot, p]) => {
      const s = this.project(p);
      return { slot, a: Math.atan2((s.y - cy) / this.H, (s.x - cx) / this.W) };
    });
    this.pivot.rotation.y = saved;
    this.pivot.updateMatrixWorld(true);
    items.sort((p, q) => p.a - q.a);
    const n = items.length, gap = (Math.PI * 2 / n) * 0.92;
    for (let it = 0; it < 80; it++) {
      for (let i = 0; i < n; i++) {
        const p = items[i], q = items[(i + 1) % n];
        let d = q.a - p.a;
        if (i === n - 1) d += Math.PI * 2;
        if (d < gap) { const push = (gap - d) / 2; p.a -= push; q.a += push; }
      }
    }
    const rx = this.W / 2 - SQ / 2 - 12, ry = this.H / 2 - SQ / 2 - 10;
    this.pos.clear();
    for (const { slot, a } of items) {
      const c = Math.cos(a), s = Math.sin(a);
      // a squircle: the squares hug the sides and fill the corners rather than crowd the car
      const k = 0.45;
      const x = Math.sign(c) * Math.abs(c) ** k, y = Math.sign(s) * Math.abs(s) ** k;
      this.pos.set(slot, { x: cx + x * rx, y: cy + y * ry });
    }
    this.placeSquares();
  }

  private placeSquares(): void {
    for (const b of Array.from(this.squares.querySelectorAll<HTMLElement>('.wk-sq'))) {
      const p = this.pos.get(b.dataset.slot as SlotId);
      if (!p) continue;
      b.style.left = `${Math.round(p.x - SQ / 2)}px`;
      b.style.top = `${Math.round(p.y - SQ / 2)}px`;
    }
  }

  private frame(dt: number): void {
    if (!this.model || !this.W) return;
    if (!this.renderer) {
      this.renderer = new THREE.WebGLRenderer({ canvas: this.canvas, antialias: true, alpha: true });
      this.renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
      this.renderer.setSize(this.W, this.H, false);
      this.renderer.toneMapping = THREE.NeutralToneMapping;
      this.renderer.toneMappingExposure = 1.05;
    }
    // made ahead by warm() at the canvas's default size: sized to the stage on its first frame here
    this.renderer.getSize(this.size);
    if (this.size.x !== this.W || this.size.y !== this.H) this.renderer.setSize(this.W, this.H, false);
    this.t += dt;
    this.idle += dt;
    // a slow sway on the turntable; after a drag it eases back into the sway rather than jumping
    const sway = Math.sin(this.t * 0.45) * 0.32;
    if (!this.drag && this.idle > 4) this.yaw += (sway - this.yaw) * Math.min(1, dt * 0.8);
    this.pivot.rotation.y = this.yaw;
    this.pivot.updateMatrixWorld(true);
    // a tray out: the vehicle rises into the room above it
    const th = this.open ? this.tray.offsetHeight + 14 : 0;
    const k = Math.min(1, dt * 9);
    this.shift += (th / 2 - this.shift) * k;
    this.zoom += ((th ? Math.min(1, (this.H - th) / (this.H * 0.8)) : 1) - this.zoom) * k;
    if (this.shift > 0.5 || this.zoom < 0.999) {
      this.cam.setViewOffset(this.W, this.H, 0, this.shift, this.W, this.H);
      this.cam.zoom = this.zoom;
      this.cam.updateProjectionMatrix();
    } else if (this.cam.view?.enabled || this.cam.zoom !== 1) {
      this.cam.clearViewOffset();
      this.cam.zoom = 1;
      this.cam.updateProjectionMatrix();
    }
    // a part being given: the poof, the part on under its cover, then its line and square
    const f = this.fresh;
    if (f && f.stage < 2) {
      const was = f.t;
      f.t += dt;
      if (was < POOF_AT && f.t >= POOF_AT) this.poof(f.slot);
      if (f.stage === 0 && f.t >= POOF_AT + SWAP) { f.stage = 1; this.render(); }
      if (f.stage === 1 && f.t >= LINE_AT + LINE_RUN) { f.stage = 2; f.litAt = performance.now(); this.render(); }
    }
    this.stepPuffs(dt);
    this.renderer.render(this.scene, this.cam);

    // the lines from each square to its part
    const lines: string[] = [];
    for (const [slot, p] of this.anchors) {
      if (this.open && this.open.slot !== slot) continue;
      const sq = this.pos.get(slot);
      if (!sq) continue;
      const a = this.project(p);
      // the given part's line runs out from the part to its square, in red
      const given = f?.slot === slot && f.t >= LINE_AT;
      const on = this.open?.slot === slot || this.focus === slot || given;
      const k = given ? 1 - (1 - Math.min(1, (f!.t - LINE_AT) / LINE_RUN)) ** 3 : 1;
      const x1 = a.x + (sq.x - a.x) * k, y1 = a.y + (sq.y - a.y) * k;
      lines.push(`<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${a.x.toFixed(1)}" y2="${a.y.toFixed(1)}"${on ? ' class="on"' : ''}/><circle cx="${a.x.toFixed(1)}" cy="${a.y.toFixed(1)}" r="${on ? 4.5 : 3.5}"${on ? ' class="on"' : ''}/>`);
    }
    this.svg.innerHTML = lines.join('');
  }

  // ---- the poof ----

  /** A puff of smoke where the part goes, thick enough to hide it appearing, that spreads and thins away. */
  private poof(slot: SlotId): void {
    const p = this.anchors.get(slot);
    if (!p || !this.model) return;
    const size = new THREE.Box3().setFromObject(this.model.holder).getSize(new THREE.Vector3()).length();
    const r0 = Math.max(0.03, size * 0.055);
    const c = p.clone().applyMatrix4(this.pivot.matrixWorld);
    c.y += r0 * 0.3;
    const add = (r: number, dir: THREE.Vector3, speed: number, life: number, grey: number) => {
      const mat = new THREE.MeshStandardMaterial({ color: grey, roughness: 1, flatShading: true, transparent: true, depthWrite: false });
      const m = new THREE.Mesh(this.puffGeo, mat);
      m.position.copy(c).addScaledVector(dir, r0 * 0.35);
      m.scale.setScalar(0.001);
      m.rotation.set(Math.random() * 6, Math.random() * 6, Math.random() * 6);
      m.renderOrder = 5;
      this.scene.add(m);
      const spin = new THREE.Vector3(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).multiplyScalar(4);
      this.puffs.push({ m, v: dir.clone().multiplyScalar(speed * r0), spin, r, age: 0, life });
    };
    // a thick core over the part, and a ring of balls thrown out from it, mostly sideways and a little up
    add(r0 * 1.5, new THREE.Vector3(0, 0.2, 0), 0.4, 0.55, 0xffffff);
    const n = 12;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2 + Math.random() * 0.4;
      const dir = new THREE.Vector3(Math.cos(a), 0.15 + Math.random() * 0.6, Math.sin(a)).normalize();
      add(r0 * (0.75 + Math.random() * 0.5), dir, 3 + Math.random() * 2.5, 0.8 + Math.random() * 0.45, Math.random() < 0.3 ? 0xdcd8d0 : 0xf4f1ea);
    }
  }

  private stepPuffs(dt: number): void {
    if (!this.puffs.length) return;
    const drag = Math.exp(-3.2 * dt);
    this.puffs = this.puffs.filter((q) => {
      q.age += dt;
      const u = q.age / q.life;
      if (u >= 1) { this.scene.remove(q.m); (q.m.material as THREE.Material).dispose(); return false; }
      q.m.position.addScaledVector(q.v, dt);
      q.m.position.y += q.r * 0.6 * dt;
      q.v.multiplyScalar(drag);
      q.m.rotation.x += q.spin.x * dt; q.m.rotation.y += q.spin.y * dt; q.m.rotation.z += q.spin.z * dt;
      // snaps out to full size, then keeps swelling as it thins
      const grow = Math.min(1, q.age / 0.12);
      const s = q.r * (1 - (1 - grow) ** 3) * (1 + 0.7 * u);
      q.m.scale.setScalar(Math.max(0.001, s));
      (q.m.material as THREE.MeshStandardMaterial).opacity = u < 0.35 ? 1 : 1 - ((u - 0.35) / 0.65) ** 1.5;
      return true;
    });
  }

  private clearPuffs(): void {
    for (const q of this.puffs) { this.scene.remove(q.m); (q.m.material as THREE.Material).dispose(); }
    this.puffs = [];
  }

  // ---- the tray ----

  private openTray(slot: SlotId): void {
    const u = this.unit();
    if (!u) return;
    this.revealDone();
    this.focus = slot;
    this.open = { slot, row: 'tier', col: fitted(u.parts, slot) };
    this.hover = null;
    this.dim.hidden = false;
    this.tray.hidden = false;
    this.el.classList.add('picking');
    this.renderTray();
    this.paintFocus();
  }

  private closeTray(paint = true): void {
    if (!this.open) return;
    this.open = null;
    this.hover = null;
    this.dim.hidden = true;
    this.tray.hidden = true;
    this.el.classList.remove('picking');
    if (paint) { this.paintFocus(); this.preview(); }
  }

  /** Esc: put the tray away if one is out. True when it did. */
  escape(): boolean {
    if (!this.open) return false;
    this.closeTray();
    return true;
  }

  private rows(u: Unit, slot: SlotId): TrayRow[] {
    if (slot !== 'paint') return ['tier'];
    return owned(u.parts, 'paint') >= 3 ? ['tier', 'colour', 'accent'] : ['tier', 'colour'];
  }

  private renderTray(): void {
    const u = this.unit();
    const o = this.open;
    if (!u || !o) return;
    const model = defOf(u.model);
    const s = slotOf(o.slot);
    const fit = fitted(u.parts, o.slot), have = owned(u.parts, o.slot);
    const mul = this.host.partMul(o.slot);
    const tiles = [0, 1, 2, 3].map((t) => {
      const owe = mul === null ? owedFor(model, u.parts, o.slot, t) : at(owedFor(model, u.parts, o.slot, t), mul);
      const state = t === fit ? 'Fitted' : t === 0 ? 'Back to stock' : t <= have ? 'Owned · fit it' : mul === null ? 'At a shop' : money(owe);
      const cls = ['wk-tile', t === fit ? 'fit' : '', t > 0 && t <= have ? 'own' : '', owe && (mul === null || !this.wallet.canAfford(owe)) ? 'dear' : '',
        this.keyed && o.row === 'tier' && o.col === t ? 'kfocus' : ''].filter(Boolean).join(' ');
      const pips = [1, 2, 3].map((k) => `<i class="${k <= t ? 'on' : ''}"></i>`).join('');
      return `<button type="button" class="${cls}" data-row="tier" data-col="${t}"><span class="pips">${pips}</span>
        <b>${esc(t ? tierName(s, model, t) : 'Stock')}</b><span class="pr">${esc(state)}</span></button>`;
    }).join('');
    let extra = '';
    if (o.slot === 'paint') {
      const coat = at(have >= 1 ? coatPrice(model) : owedFor(model, u.parts, 'paint', 1), mul ?? 1);
      const row = (which: 'colour' | 'accent') => {
        const current = which === 'colour' ? (u.parts?.c ?? model.color) : (u.parts?.a ?? -1);
        const sw = PALETTE.map((p, k) => `<button type="button" class="wk-sw${p.c === current ? ' on' : ''}${this.keyed && o.row === which && o.col === k ? ' kfocus' : ''}" data-row="${which}" data-col="${k}" style="--c:#${p.c.toString(16).padStart(6, '0')}" title="${esc(p.name)} · ${p.c === current ? 'on it now' : mul === null ? 'at a shop' : money(coat)}"></button>`).join('');
        return `<div class="wk-pal"><span>${which === 'colour' ? 'Colour' : 'Accent'}</span><div>${sw}</div></div>`;
      };
      extra = row('colour') + (have >= 3 ? row('accent') : '');
    }
    this.tray.innerHTML = `<header><span class="ic">${s.icon}</span><b>${esc(slotName(s, model))}</b><small>${mul === null && have < 3 ? esc(this.host.whereToBuy(o.slot)) + ' · ' : ''}click away to go back</small></header>
      <div class="wk-tiles">${tiles}</div>${extra}<p class="wk-eff"></p>`;
    this.preview();
  }

  /** The tray's line and the bars say what the tier under the pointer (or the keys) would do. */
  private preview(): void {
    const u = this.unit();
    if (!u) return;
    const now = this.fleet.defFor(u);
    const o = this.open;
    if (!o) { this.renderStats(now, null); return; }
    const model = defOf(u.model);
    const hov = this.hover ?? { row: o.row, col: o.col };
    const eff = this.tray.querySelector<HTMLElement>('.wk-eff');
    if (hov.row !== 'tier') {
      const p = PALETTE[hov.col];
      const mul = this.host.partMul('paint');
      const coat = at(owned(u.parts, 'paint') >= 1 ? coatPrice(model) : owedFor(model, u.parts, 'paint', 1), mul ?? 1);
      if (eff) eff.textContent = p ? `${p.name} ${hov.row === 'accent' ? 'on the roof and trim' : 'all over'} · ${mul === null ? 'a coat at a shop that does paint' : `${money(coat)} a coat${owned(u.parts, 'paint') ? '' : ', with the respray'}`}` : '';
      this.renderStats(now, null);
      return;
    }
    const next = applyParts(model, withTier(u.parts, o.slot, hov.col));
    const text = effectLine(o.slot, applyParts(model, withTier(u.parts, o.slot, 0)), next, hov.col);
    if (eff) eff.textContent = text;
    this.renderStats(now, hov.col === fitted(u.parts, o.slot) ? null : next);
  }

  private onTrayClick(e: Event): void {
    const b = (e.target as HTMLElement).closest<HTMLElement>('[data-col]');
    const u = this.unit();
    if (!b || !u || !this.open) return;
    this.open.row = b.dataset.row as TrayRow;
    this.open.col = Number(b.dataset.col);
    this.apply(u);
  }

  /** Fit the tier, or put on the colour, the tray is on. */
  private apply(u: Unit): void {
    const o = this.open;
    if (!o) return;
    if (o.row === 'tier') this.fitTier(u, o.slot, o.col);
    else this.paintWith(u, o.row, PALETTE[o.col].c);
  }

  private fitTier(u: Unit, slot: SlotId, tier: number): void {
    const model = defOf(u.model);
    const list = owedFor(model, u.parts, slot, tier);
    if (tier === fitted(u.parts, slot)) return;
    const mul = this.host.partMul(slot);
    // a tier not owned yet is bought over a shop's counter, and only at one that has it this year
    if (list > 0 && mul === null) {
      this.host.say(`${tierName(slotOf(slot), model, tier)} · ${this.host.whereToBuy(slot)}`);
      this.shake(`[data-row="tier"][data-col="${tier}"]`);
      return;
    }
    const owe = at(list, mul ?? 1);
    if (owe > this.wallet.cash) {
      this.host.say(`${tierName(slotOf(slot), model, tier)} costs ${money(owe)} — you have ${money(this.wallet.cash)}`);
      this.shake(`[data-row="tier"][data-col="${tier}"]`);
      return;
    }
    const why = this.fleet.fit(u, slot, tier, undefined, undefined, mul ?? 1);
    if (!why) this.host.paid(this.fleet.lastCharge);
    const now = this.fleet.defFor(u);
    this.host.say(why ?? (tier === 0 ? `${slotName(slotOf(slot), model)} back to stock` : `${tierName(slotOf(slot), model, tier)} fitted${owe ? ` · −${money(owe)}` : ''} · ${headline(now)}`));
    this.host.sync();
  }

  private paintWith(u: Unit, which: 'colour' | 'accent', c: number): void {
    const model = defOf(u.model);
    const have = owned(u.parts, 'paint');
    if (which === 'colour' && c === (u.parts?.c ?? model.color) && have) return;
    if (which === 'accent' && c === u.parts?.a) return;
    const mul = this.host.partMul('paint');
    if (mul === null) { this.host.say(`A new coat · ${this.host.whereToBuy('paint')}`); return; }
    const cost = at(have >= 1 ? coatPrice(model) : owedFor(model, u.parts, 'paint', 1), mul);
    if (cost > this.wallet.cash) { this.host.say(`A coat costs ${money(cost)} — you have ${money(this.wallet.cash)}`); return; }
    // a colour needs at least a respray fitted to show; an accent needs the two-tone
    const tier = which === 'accent' ? 3 : Math.max(1, fitted(u.parts, 'paint'));
    const why = which === 'colour' ? this.fleet.fit(u, 'paint', tier, c, undefined, mul) : this.fleet.fit(u, 'paint', tier, undefined, c, mul);
    if (!why) this.host.paid(this.fleet.lastCharge);
    this.host.say(why ?? `${u.name} is ${which === 'accent' ? `trimmed in ${colourName(c).toLowerCase()}` : `${colourName(c).toLowerCase()} now`} · −${money(cost)}`);
    this.host.sync();
  }

  private shake(sel: string): void {
    const el = this.tray.querySelector<HTMLElement>(sel);
    if (!el) return;
    el.classList.remove('shake');
    void el.offsetWidth;
    el.classList.add('shake');
  }

  // ---- keys ----

  private step(dir: number): void {
    const units = this.host.units();
    if (units.length < 2) return;
    const at = units.findIndex((q) => q.uid === this.host.selected());
    this.host.select(units[(at + dir + units.length) % units.length].uid);
  }

  /** The workshop's keys; true when the key was used. */
  key(code: string): boolean {
    const u = this.unit();
    this.keyed = true;
    if (code === 'KeyQ') { this.step(-1); return true; }
    if (code === 'KeyE') { this.step(1); return true; }
    if (!u) return false;
    const enter = code === 'Enter' || code === 'NumpadEnter';
    const o = this.open;
    if (o) {
      const rows = this.rows(u, o.slot);
      const width = o.row === 'tier' ? 4 : PALETTE.length;
      switch (code) {
        case 'ArrowLeft': o.col = Math.max(0, o.col - 1); break;
        case 'ArrowRight': o.col = Math.min(width - 1, o.col + 1); break;
        case 'ArrowUp': case 'ArrowDown': {
          const r = rows.indexOf(o.row) + (code === 'ArrowUp' ? -1 : 1);
          if (r < 0 || r >= rows.length) return true;
          const model = defOf(u.model);
          o.row = rows[r];
          if (o.row === 'tier') o.col = fitted(u.parts, o.slot);
          else {
            const c = o.row === 'colour' ? (u.parts?.c ?? model.color) : (u.parts?.a ?? PALETTE[0].c);
            o.col = Math.max(0, PALETTE.findIndex((p) => p.c === c));
          }
          break;
        }
        case 'Backspace': this.closeTray(); return true;
        default:
          if (enter) { this.apply(u); return true; }
          return false;
      }
      this.hover = null;
      this.renderTray();
      return true;
    }
    if (this.focus === null) {
      switch (code) {
        case 'ArrowLeft': this.step(-1); return true;
        case 'ArrowRight': this.step(1); return true;
        case 'ArrowDown': case 'Enter': case 'NumpadEnter': this.focus = this.nearest(this.W / 2, 0, 0, 1) ?? null; this.paintFocus(); return true;
        default: return false;
      }
    }
    if (enter) { this.openTray(this.focus); return true; }
    const dirs: Record<string, [number, number]> = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] };
    const d = dirs[code];
    if (!d) return false;
    const p = this.pos.get(this.focus)!;
    const next = this.nearest(p.x, p.y, d[0], d[1], this.focus);
    if (next) this.focus = next;
    else if (d[1] < 0) this.focus = null;
    this.paintFocus();
    return true;
  }

  /** The square nearest a point in a direction (dx, dy), favouring the ones straight along it. */
  private nearest(x: number, y: number, dx: number, dy: number, not?: SlotId): SlotId | undefined {
    let best: SlotId | undefined, score = Infinity;
    for (const [slot, p] of this.pos) {
      if (slot === not) continue;
      const ax = p.x - x, ay = p.y - y;
      const along = ax * dx + ay * dy;
      if (along <= 4) continue;
      const across = Math.abs(ax * dy - ay * dx);
      const sc = along + across * 2.2;
      if (sc < score) { score = sc; best = slot; }
    }
    return best;
  }
}
