import * as THREE from 'three';
import type { AirDef } from '../game/vehicles';
import { GLIDE, APPROACH_RANGE, GUIDE_RANGE, type Approach } from '../game/air';

/**
 * What the sky layer draws besides the planes themselves (docs/rides.html): contrails behind a jet at
 * height, a soft shadow sliding over the ground beneath it, and the landing aid's glide line. All of
 * it lives in world coordinates, in one group added to the scene.
 */

/** Seconds between the points a contrail is laid down at, and how many it keeps. */
const TRAIL_STEP = 0.12;
const TRAIL_POINTS = 96;

/** Contrails drawn at all: the trailer shoot turns them off (a ribbon high up lies across a low camera's whole view). */
export const CONTRAILS = { on: true };

/** One ribbon of vapour: a flat strip of quads along the last dozen seconds of an engine's path. */
export class Contrail {
  readonly mesh: THREE.Mesh;
  private pts: { x: number; y: number; z: number; age: number }[] = [];
  private acc = 0;
  private geo: THREE.BufferGeometry;
  private pos: Float32Array;
  private col: Float32Array;
  /** The vapour's colour: white, or a display team's smoke. */
  tint: [number, number, number] = [1, 1, 1];

  constructor(parent: THREE.Object3D) {
    this.geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(TRAIL_POINTS * 2 * 3);
    this.col = new Float32Array(TRAIL_POINTS * 2 * 4);
    this.geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    this.geo.setAttribute('color', new THREE.BufferAttribute(this.col, 4));
    const idx: number[] = [];
    for (let k = 0; k < TRAIL_POINTS - 1; k++) {
      const a = k * 2, b = a + 1, c = a + 2, d = a + 3;
      idx.push(a, b, c, b, d, c);
    }
    this.geo.setIndex(idx);
    const mat = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, depthWrite: false, side: THREE.DoubleSide, fog: true });
    this.mesh = new THREE.Mesh(this.geo, mat);
    this.mesh.frustumCulled = false;
    this.mesh.renderOrder = 2;
    parent.add(this.mesh);
  }

  /** Lay the trail on from (x, y, z) while `on`; old vapour spreads, drifts with the wind and fades. */
  update(dt: number, x: number, y: number, z: number, on: boolean, windX: number, windZ: number, bright: number): void {
    this.acc += dt;
    for (const p of this.pts) {
      p.age += dt;
      p.x += windX * dt * 0.35;
      p.z += windZ * dt * 0.35;
    }
    if (on && this.acc >= TRAIL_STEP) {
      this.acc = 0;
      this.pts.unshift({ x, y, z, age: 0 });
    }
    while (this.pts.length > TRAIL_POINTS || (this.pts.length && this.pts[this.pts.length - 1].age > TRAIL_POINTS * TRAIL_STEP)) this.pts.pop();
    const n = this.pts.length;
    this.mesh.visible = n > 1 && CONTRAILS.on;
    if (n < 2) return;
    const life = TRAIL_POINTS * TRAIL_STEP;
    for (let k = 0; k < TRAIL_POINTS; k++) {
      const p = this.pts[Math.min(k, n - 1)];
      const q = this.pts[Math.min(k + 1, n - 1)] ?? p;
      // across the strip, flat to the ground so it reads from above
      let dx = p.x - q.x, dz = p.z - q.z;
      const len = Math.hypot(dx, dz) || 1;
      dx /= len; dz /= len;
      const w = 0.08 + p.age * 0.05;
      const a = k < n ? Math.max(0, 1 - p.age / life) * Math.min(1, p.age * 3 + 0.2) * 0.55 * bright : 0;
      for (const [s, j] of [[-1, 0], [1, 1]] as const) {
        const v = (k * 2 + j) * 3;
        this.pos[v] = p.x - dz * w * s;
        this.pos[v + 1] = p.y;
        this.pos[v + 2] = p.z + dx * w * s;
        const c = (k * 2 + j) * 4;
        this.col[c] = this.tint[0]; this.col[c + 1] = this.tint[1]; this.col[c + 2] = this.tint[2]; this.col[c + 3] = a;
      }
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
  }

  get empty(): boolean { return this.pts.length === 0; }

  dispose(): void {
    this.mesh.removeFromParent();
    this.geo.dispose();
    (this.mesh.material as THREE.Material).dispose();
  }
}

/** A plane's silhouette in soft shade, laid flat on the ground under it, offset away from the sun. */
export class PlaneShadow {
  readonly mesh: THREE.Mesh;

  constructor(parent: THREE.Object3D, def: AirDef) {
    // a cross: the fuselage and the wings, in the model's own size
    const L = def.halfLen * 2, S = def.halfWid * 2;
    const shape = new THREE.Shape();
    const f = L * 0.08, wz = L * 0.05, wd = L * 0.14;
    shape.moveTo(-f, L / 2);
    shape.lineTo(f, L / 2);
    shape.lineTo(f, wz + wd);
    shape.lineTo(S / 2, wz - wd * 0.6);
    shape.lineTo(S / 2, wz - wd * 1.3);
    shape.lineTo(f, wz - wd * 0.5);
    shape.lineTo(f * 0.7, -L / 2 + L * 0.1);
    shape.lineTo(S * 0.18, -L / 2);
    shape.lineTo(-S * 0.18, -L / 2);
    shape.lineTo(-f * 0.7, -L / 2 + L * 0.1);
    shape.lineTo(-f, wz - wd * 0.5);
    shape.lineTo(-S / 2, wz - wd * 1.3);
    shape.lineTo(-S / 2, wz - wd * 0.6);
    shape.lineTo(-f, wz + wd);
    shape.closePath();
    const geo = new THREE.ShapeGeometry(shape);
    // shape y is the plane's nose (+z): lay it flat
    geo.rotateX(Math.PI / 2);
    const mat = new THREE.MeshBasicMaterial({ color: 0x0a1418, transparent: true, opacity: 0.2, depthWrite: false, side: THREE.DoubleSide });
    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.renderOrder = 1;
    parent.add(this.mesh);
  }

  /** Put the shadow under a plane at (x, y, z) over ground `gy`, the sun along `sun` (pointing at the sun). */
  place(x: number, y: number, z: number, heading: number, gy: number, sun: THREE.Vector3, strength: number): void {
    const h = y - gy;
    const ok = strength > 0.01 && sun.y > 0.12 && h < 120;
    this.mesh.visible = ok;
    if (!ok) return;
    const k = h / sun.y;
    this.mesh.position.set(x - sun.x * k, gy + 0.06, z - sun.z * k);
    this.mesh.rotation.set(0, heading, 0);
    // higher up, the shadow is fainter and softer, and a touch bigger
    const fade = Math.max(0.25, 1 - h / 110);
    (this.mesh.material as THREE.MeshBasicMaterial).opacity = 0.22 * strength * fade;
    this.mesh.scale.setScalar(1 + h / 160);
  }

  dispose(): void {
    this.mesh.removeFromParent();
    this.mesh.geometry.dispose();
    (this.mesh.material as THREE.Material).dispose();
  }
}

/** Which part of an approach the guide is showing: near the line, lined up on it, or flying it down. */
type GuidePhase = 'near' | 'offer' | 'landing';

/** Tiles between the guide's lights, how long each is, and lights a second as the chase runs in. */
const LIGHT_STEP = 2.6, LIGHT_LEN = 2.0, LIGHT_WIDE = 0.75, LIGHT_RATE = 9;
/** Lights the chase rests dark for at the threshold before it runs in again. */
const LIGHT_REST = 4;
const PHASE_COLOUR: Record<GuidePhase, number> = { near: 0xffc53d, offer: 0x39d353, landing: 0x7dff9a };

/** A keycap chip: the keys to press drawn as caps, and a word or two after them. */
function chipTexture(keys: string[], label: string): THREE.CanvasTexture {
  const H = 96, font = '600 40px system-ui, sans-serif', small = '600 34px system-ui, sans-serif';
  const probe = document.createElement('canvas').getContext('2d')!;
  probe.font = font;
  const caps = keys.map((k) => Math.max(64, probe.measureText(k).width + 34));
  probe.font = small;
  const W = Math.ceil(24 + caps.reduce((a, b) => a + b + 10, 0) + probe.measureText(label).width + 26);
  const cv = document.createElement('canvas');
  cv.width = W; cv.height = H;
  const g = cv.getContext('2d')!;
  const round = (x: number, y: number, w: number, h: number, r: number) => { g.beginPath(); g.roundRect(x, y, w, h, r); };
  round(2, 2, W - 4, H - 4, 22); g.fillStyle = 'rgba(20,28,34,0.82)'; g.fill();
  let x = 16;
  for (const [k, key] of keys.entries()) {
    const w = caps[k];
    round(x, 14, w, 64, 12); g.fillStyle = '#c9ced4'; g.fill();
    round(x, 12, w, 60, 12); g.fillStyle = '#ffffff'; g.fill();
    g.fillStyle = '#1f2b33'; g.font = font; g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText(key, x + w / 2, 43);
    x += w + 10;
  }
  g.fillStyle = '#ffffff'; g.font = small; g.textAlign = 'left'; g.textBaseline = 'middle';
  g.fillText(label, x + 6, H / 2);
  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.userData.aspect = W / H;
  return tex;
}

/** A floating keycap hint on the guide's path. */
class KeyChip {
  readonly sprite = new THREE.Sprite(new THREE.SpriteMaterial({ transparent: true, depthTest: false, depthWrite: false }));
  private key = '';
  private static cache = new Map<string, THREE.CanvasTexture>();
  constructor(parent: THREE.Object3D) { this.sprite.renderOrder = 5; this.sprite.visible = false; parent.add(this.sprite); }

  set(keys: string[] | null, label = '', x = 0, y = 0, z = 0, size = 1): void {
    this.sprite.visible = !!keys;
    if (!keys) return;
    const id = `${keys.join('+')}|${label}`;
    if (id !== this.key) {
      this.key = id;
      let tex = KeyChip.cache.get(id);
      if (!tex) KeyChip.cache.set(id, tex = chipTexture(keys, label));
      this.sprite.material.map = tex;
      this.sprite.material.needsUpdate = true;
    }
    const aspect = (this.sprite.material.map?.userData.aspect as number) ?? 3;
    this.sprite.scale.set(0.9 * aspect * size, 0.9 * size, 1);
    this.sprite.position.set(x, y, z);
  }
}

/**
 * The landing aid's guide (docs/rides.html). Whenever a plane with wheels is anywhere near a runway's
 * extended centreline, a line of lights runs in along it toward the threshold, one light at a time, from
 * abreast of the plane down the glide slope: amber while it is still to get onto the line, green once
 * it is lined up, bright while the aid flies it down. Keycap chips on the path say what to press (which
 * way to turn onto the line, Shift to land with W let go, S to brake once down) and a ring marks the
 * threshold.
 */
export class GlideGuide {
  private group = new THREE.Group();
  private light: THREE.Mesh;
  private glow: THREE.Mesh;
  private ring: THREE.Mesh;
  private chips: KeyChip[];

  constructor(scene: THREE.Scene) {
    const quad = new THREE.PlaneGeometry(1, 1);
    quad.rotateX(-Math.PI / 2);
    const mat = (o: number) => new THREE.MeshBasicMaterial({ color: 0x39d353, transparent: true, opacity: o, depthTest: false, depthWrite: false, side: THREE.DoubleSide });
    this.glow = new THREE.Mesh(quad, mat(0.35));
    this.light = new THREE.Mesh(quad, mat(1));
    this.glow.renderOrder = 3; this.light.renderOrder = 4;
    this.ring = new THREE.Mesh(new THREE.RingGeometry(1.6, 2.1, 40), new THREE.MeshBasicMaterial({ color: 0x39d353, transparent: true, opacity: 0.7, depthWrite: false, side: THREE.DoubleSide }));
    this.ring.rotation.x = -Math.PI / 2;
    this.group.add(this.glow, this.light, this.ring);
    this.chips = [new KeyChip(this.group), new KeyChip(this.group), new KeyChip(this.group)];
    this.group.visible = false;
    this.group.renderOrder = 3;
    scene.add(this.group);
  }

  /**
   * Draw the guide for this approach end, or hide it. `me` carries the plane's heading and `want` the
   * heading that flies it onto the line (for which way to turn).
   */
  show(ap: Approach | null, phase: GuidePhase, t: number, me?: { heading: number; want: number }): void {
    this.group.visible = !!ap;
    if (!ap) return;
    const r = ap.r;
    const [tx, tz] = ap.dir === 1 ? [r.ax, r.az] : [r.bx, r.bz];
    const ux = r.ux * ap.dir, uz = r.uz * ap.dir;
    const at = (out: number, lift = 0.1) => new THREE.Vector3(tx - ux * out, r.y + Math.max(0, out) * GLIDE + lift, tz - uz * out);
    const colour = PHASE_COLOUR[phase];
    (this.light.material as THREE.MeshBasicMaterial).color.setHex(colour);
    (this.glow.material as THREE.MeshBasicMaterial).color.setHex(colour);
    (this.ring.material as THREE.MeshBasicMaterial).color.setHex(colour);

    // the chase: one light at a time, from just ahead of the plane in to the threshold, then a rest
    const start = Math.min(GUIDE_RANGE, Math.max(0, ap.out - 2));
    const n = Math.max(1, Math.ceil(start / LIGHT_STEP));
    const tick = t * LIGHT_RATE;
    const k = Math.floor(tick) % (n + 1 + LIGHT_REST);
    const lit = k <= n;
    this.light.visible = this.glow.visible = lit;
    if (lit) {
      const p = at(Math.max(0, start - k * LIGHT_STEP));
      const yaw = Math.atan2(ux, uz);
      for (const m of [this.light, this.glow]) { m.position.copy(p); m.rotation.y = yaw; }
      // bigger further out, where the camera is usually pulled back to find the field
      const big = 1 + Math.min(1.2, Math.max(0, ap.out) / 40);
      this.light.scale.set(LIGHT_WIDE * big, 1, LIGHT_LEN * big);
      this.glow.scale.set((LIGHT_WIDE + 1.1) * big, 1, (LIGHT_LEN + 1.2) * big);
      const fade = 1 - 0.55 * (tick - Math.floor(tick));
      (this.light.material as THREE.MeshBasicMaterial).opacity = fade;
      (this.glow.material as THREE.MeshBasicMaterial).opacity = 0.45 * fade;
    }

    this.ring.position.copy(at(0, 0.08));
    const pulse = 1 + 0.08 * Math.sin(t * 5);
    this.ring.scale.setScalar(phase === 'landing' ? 1 : pulse);
    (this.ring.material as THREE.MeshBasicMaterial).opacity = phase === 'landing' ? 0.9 : 0.6;

    // the keys, in the order they come: onto the line, down it, and once on the wheels
    const [first, mid, last] = this.chips;
    const size = 1 + Math.min(1.2, Math.max(0, ap.out) / 40);
    const turn = me ? Math.atan2(Math.sin(me.want - me.heading), Math.cos(me.want - me.heading)) : 0;
    const p1 = at(Math.max(0, ap.out - 5), 1.1);
    if (phase === 'near') {
      // A swings the nose round one way (up the heading), D the other
      if (Math.abs(turn) > 0.12) first.set([turn > 0 ? 'A' : 'D'], 'turn onto the line', p1.x, p1.y, p1.z, size);
      else if (ap.out > APPROACH_RANGE) first.set(['W'], 'fly on in', p1.x, p1.y, p1.z, size);
      else first.set(['Shift'], 'hold to land', p1.x, p1.y, p1.z, size);
    } else if (phase === 'offer') first.set(['Shift'], 'hold to land', p1.x, p1.y, p1.z, size);
    else first.set(['Shift'], 'keep holding', p1.x, p1.y, p1.z, size);
    if (ap.out > 16) {
      const p2 = at(ap.out * 0.45, 1.1);
      mid.set(['W'], phase === 'landing' ? 'off · it steers itself' : 'let go to come down', p2.x, p2.y, p2.z, size * 0.9);
    } else mid.set(null);
    const p3 = at(0, 1.2);
    last.set(['S'], 'brake once down', p3.x, p3.y, p3.z, size * 0.85);
  }
}
