/**
 * Night ops (docs/nightops.html): helicopter work after dark that is done with the searchlight. Each op
 * is one objective of a mission (model.ts, `t: 'op'`); the mission system arms it when that step comes
 * up and hears `opEnd` when it is over, with a score from 0 to 1 that sets the pay.
 *
 * Everything an op needs is here: the test for "in the beam" (the pool of light on the ground and how
 * wide it is, from render/heliSpot.ts), figures that only show where the beam falls, CPU cars driven by
 * the race's driver on the race's planner (race/race.ts, race/route.ts) with a speed cap an op can hold
 * them to, a boat that steers for the light, the strip along the foot of the screen and the big cue in
 * the middle of it. An op waits until the player is near in a helicopter after dark, then runs; while it
 * runs the mission system slows the clock so the night lasts the job.
 */
import * as THREE from 'three';
import { fadingCone } from '../../render/softLight';
import { GroundRing, drapeMat, groundOf } from '../../render/drape';
import { N, SEA, STEP, heightAt, idx, type World } from '../../world/tiles';
import type { VehicleDef, VehicleState, LandDef } from '../vehicles';
import { isHelicopter } from '../vehicles';
import { defOf } from '../fleet';
import { applyParts, type Parts } from '../parts';
import { CpuRacer, RaceDriver } from '../race/race';
import { fastRoute, along, remaining, type Route } from '../race/route';
import { lookMesh, type Look } from '../herds';
import { buildVehicleMesh, disposeVehicleMesh, type VehicleMesh } from '../../render/vehicleMeshes';
import type { AirState } from '../air';
import type { Obj, PlaceRef } from '../missions/model';
import { clamp } from '../../util/math';
import { startPrompt } from '../startPrompt';

export type OpObj = Extract<Obj, { t: 'op' }>;
interface OpResult { ok: boolean; score: number; line: string }

export interface OpHost {
  worldAt(cx: number, cz: number): World | null;
  player(): { w: World; state: VehicleState; def: VehicleDef } | null;
  /** The searchlight's pool on the ground, world tiles; null while it is off. */
  spot(): { x: number; z: number; r: number } | null;
  /** Dark enough for the searchlight. */
  dark(): boolean;
  /** Enter went down this frame. */
  go(): boolean;
  say(title: string, body: string): void;
  beep(final: boolean): void;
  /** Traffic on an island, in its own frame. */
  traffic(w: World): { x: number; z: number }[];
}

/** Seconds of beam that find something hidden, and the extra reach the beam's edge is allowed. */
export const FIND_SECS = 2, SLACK = 0.3;
/** How much the clock slows while an op runs: a night is under five minutes of play otherwise. */
export const OP_CLOCK = 0.25;

const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));
const esc = (s: string) => s.replace(/[<&]/g, (c) => (c === '<' ? '&lt;' : '&amp;'));
const clock = (t: number) => `${Math.floor(Math.max(0, t) / 60)}:${String(Math.floor(Math.max(0, t) % 60)).padStart(2, '0')}`;
const pct = (f: number) => `${Math.round(clamp(f, 0, 1) * 100)}%`;
export const grade = (s: number) => (s >= 0.85 ? 'Gold' : s >= 0.7 ? 'Silver' : s >= 0.5 ? 'Bronze' : 'Scraped by');

/** A land car's def with a handbrake fitted, a colour, and no faster than `top`. */
function opCar(model: string, top: number, colour?: number, hb = 2): LandDef {
  const parts: Parts = { t: { handbrake: [hb, hb], engine: [1, 1] }, c: colour, spent: 0 };
  const d = applyParts(defOf(model), parts) as LandDef;
  return { ...d, topSpeed: Math.min(d.topSpeed, top) };
}
/** The helicopter's top speed: a car an op has you follow is held a good way under it. */
const heliTop = (): number => defOf('dragonfly').topSpeed;

// ---- things in the world ----------------------------------------------------------------------------

function flatRing(r: number, colour: number, opacity = 0.8, tube = 0.07): THREE.Mesh {
  const m = new THREE.Mesh(new THREE.TorusGeometry(r, tube, 6, Math.max(24, Math.round(r * 10))), new THREE.MeshBasicMaterial({ color: colour, transparent: true, opacity, depthWrite: false }));
  m.rotation.x = Math.PI / 2;
  m.userData.own = true;
  return m;
}
/**
 * A ring lying on the ground (or the sea) round (x, z), `r` across: a search zone's edge or a spot to mark, laid
 * over the ground under it so no part sinks into a hillside or floats over a hollow (render/drape.ts).
 */
function groundRing(r: number, colour: number, opacity: number, x: number, z: number, worldAt: (cx: number, cz: number) => World | null, width = 0.16): THREE.Mesh {
  const ring = new GroundRing(r, width, drapeMat(colour, opacity));
  ring.place(x, z, groundOf(worldAt));
  ring.mesh.userData.own = true;
  return ring.mesh;
}
function glowBall(r: number, colour: number): THREE.Mesh {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 10, 8), new THREE.MeshBasicMaterial({ color: colour, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending }));
  m.userData.own = true;
  return m;
}

/**
 * Someone or something out in the dark: unseen until the beam falls on it (a lantern or a torch blinks
 * now and then to say roughly where), found once the beam has held on it for FIND_SECS.
 */
class Figure {
  g = new THREE.Group();
  body: THREE.Group;
  glow: THREE.Mesh;
  ring: THREE.Mesh;
  seen = 0;
  found = false;
  /** Always drawn (a stray cow on the road) rather than only where the beam falls. */
  always = false;
  gone = false;
  lit = false;
  heading = 0;
  private phase: number;

  constructor(public x: number, public z: number, look: Look, coat: number, private glowColour: number, scale: number, seed: number) {
    this.body = lookMesh(look, coat);
    this.body.scale.setScalar(scale);
    this.glow = glowBall(0.13, glowColour);
    this.glow.position.set(0.12, 0.35, 0.08);
    this.ring = flatRing(0.55, 0xf5cf3a, 0.9, 0.05);
    this.ring.position.y = 0.05;
    this.ring.visible = false;
    this.g.add(this.body, this.glow, this.ring);
    this.phase = (seed % 97) / 97 * 3.2;
  }

  update(dt: number, y: number, lit: boolean, t: number): void {
    this.lit = lit && !this.gone;
    if (!this.found) this.seen = this.lit ? this.seen + dt : Math.max(0, this.seen - dt * 0.4);
    this.g.visible = !this.gone;
    this.body.visible = this.always || this.found || this.lit;
    this.body.rotation.y = this.heading;
    const m = this.glow.material as THREE.MeshBasicMaterial;
    // a torch or a lantern: a blink every few seconds while lost, a steady glow once found
    m.opacity = this.found ? 0.35 : ((t + this.phase) % 3.2) < 0.35 ? 0.95 : 0;
    m.color.setHex(this.glowColour);
    this.ring.visible = (this.found || this.lit) && !this.gone;
    this.ring.scale.setScalar(this.lit ? 1 + Math.sin(t * 6) * 0.08 : 1);
    this.g.position.set(this.x, y, this.z);
  }
}

/** A CPU car an op drives: the race's driver on the race's planner, held to a cap when the op says so. */
class OpCar {
  r: CpuRacer;
  driver: RaceDriver | null = null;
  route: Route | null = null;
  /** Other cars (world tiles) this one should brake behind, besides the traffic. */
  constructor(private host: OpHost, scene: THREE.Scene, id: string, name: string, readonly def: LandDef, x: number, z: number, heading: number) {
    this.r = new CpuRacer(id, name, def, x, z, heading, scene);
    this.r.place(host.worldAt, x, z, heading);
  }

  get x(): number { return this.r.x; }
  get z(): number { return this.r.z; }
  get v(): number { return this.r.state?.v ?? 0; }
  get heading(): number { return this.r.heading; }
  set visible(on: boolean) { this.r.group.visible = on && !!this.r.state; }

  /** Plan the line to (x, z) and set off along it; false when there is no way there. */
  goTo(x: number, z: number, drift = false): boolean {
    const route = fastRoute(this.host.worldAt, this.def, this.x, this.z, x, z);
    if (!route) return false;
    this.follow(route, drift);
    return true;
  }

  follow(route: Route, drift = false): void {
    this.route = route;
    this.driver = new RaceDriver(route, this.def);
    this.driver.drift = drift;
  }

  stop(): void { this.driver = null; this.route = null; }

  /** Put it back at a place, standing still. */
  reset(x: number, z: number, heading: number): void {
    this.stop();
    this.r.place(this.host.worldAt, x, z, heading);
  }

  /** At the end of its line. */
  get arrived(): boolean {
    const r = this.route;
    if (!r || !this.driver) return false;
    const last = r.pts[r.pts.length - 1];
    return this.driver.i >= r.pts.length - 2 && Math.hypot(last.x - this.x, last.z - this.z) < 2;
  }

  /** Tiles of its line still to run. */
  get left(): number { return this.route && this.driver ? remaining(this.route.pts, this.driver.i, this.x, this.z) : 0; }

  /** A point this far ahead along its line, or just ahead of the nose with no line. */
  ahead(d: number): { x: number; z: number } {
    if (this.route && this.driver) return along(this.route.pts, this.driver.i, this.x, this.z, d);
    return { x: this.x + Math.sin(this.heading) * d, z: this.z + Math.cos(this.heading) * d };
  }

  drive(dt: number, cap = Infinity, others: { x: number; z: number }[] = []): void {
    const c = this.r;
    if (!c.state || !c.w) {
      // its cell out of memory: it waits where it was and comes back with the cell
      c.place(this.host.worldAt, c.x, c.z, c.heading);
      c.pose();
      return;
    }
    const s = c.state, w = c.w;
    if (!this.driver || this.arrived) {
      s.step(w, { throttle: s.v > 0.05 ? -1 : 0, steer: 0, lift: 0, boost: 0, handbrake: false }, dt);
    } else {
      const ahead = this.host.traffic(w).map((a) => ({ x: a.x + w.ox, z: a.z + w.oz })).concat(others);
      this.driver.cap = cap;
      const k = this.driver.controls(w.ox + s.x, w.oz + s.z, s.heading, s.v, dt, ahead);
      if (k.teleport) c.place(this.host.worldAt, k.teleport.x, k.teleport.z, k.teleport.heading);
      else s.step(w, { throttle: k.throttle, steer: k.steer, lift: 0, boost: k.boost, handbrake: k.handbrake }, dt);
    }
    if (c.state && c.w) {
      if (!c.rebase(this.host.worldAt)) { c.state = null; c.w = null; c.group.visible = false; return; }
      c.x = c.w.ox + c.state.x;
      c.z = c.w.oz + c.state.z;
      c.heading = c.state.heading;
    }
    c.pose();
  }

  dispose(): void { this.r.dispose(); }
}

/** A vehicle model moved by hand (a lifeboat, a rival news helicopter, a wreck on the road). */
export class Prop {
  m: VehicleMesh;
  constructor(parent: THREE.Group, def: VehicleDef, public x: number, public y: number, public z: number, public heading: number, public roll = 0) {
    this.m = buildVehicleMesh(def);
    parent.add(this.m.holder);
    this.pose();
  }
  pose(): void {
    this.m.root.position.set(this.x, this.y, this.z);
    this.m.root.rotation.set(0, this.heading, this.roll, 'YXZ');
  }
  dispose(): void { this.m.holder.parent?.remove(this.m.holder); disposeVehicleMesh(this.m); }
}

// ---- the op itself ----------------------------------------------------------------------------------

export abstract class Op {
  result: OpResult | null = null;
  /** Past waiting: the player came near in a helicopter after dark. */
  started = false;
  /** Seconds since it started. */
  t = 0;
  protected g = new THREE.Group();
  protected cars: OpCar[] = [];
  protected props: Prop[] = [];
  protected figs: Figure[] = [];
  private strip: HTMLDivElement | null = null;
  private big: HTMLDivElement | null = null;
  private tag: HTMLDivElement | null = null;
  private bigText = '';
  private bigT = 0;
  private said = '';
  /** Tiles from the op's place the player must come within, beyond its radius, for it to start. */
  protected startR = 14;
  /** Where the tracker points once running, and the line under the mission. */
  protected aimAt: { x: number; z: number; name: string } | null = null;
  protected next = '';

  constructor(readonly id: number, protected host: OpHost, protected scene: THREE.Scene, readonly o: OpObj) {
    scene.add(this.g);
    if (typeof document !== 'undefined') {
      this.strip = document.createElement('div');
      this.strip.className = 'race-strip hud chip';
      this.big = document.createElement('div');
      this.big.className = 'race-count';
      this.tag = document.createElement('div');
      this.tag.className = 'race-tag';
      this.strip.hidden = this.big.hidden = this.tag.hidden = true;
      document.body.append(this.strip, this.big, this.tag);
    }
  }

  /** It is running now (the clock slows). */
  get running(): boolean { return this.started && !this.result; }

  update(dt: number, paused: boolean): void {
    if (this.result) return;
    if (!paused) {
      if (!this.started) this.waitFor();
      else { this.t += dt; this.run(dt); }
      this.bigT = Math.max(0, this.bigT - dt);
    }
    this.draw();
  }

  /** The player in world tiles, and whether they fly a helicopter. */
  protected me(): { x: number; z: number; y: number; heli: boolean; air: AirState | null } | null {
    const p = this.host.player();
    if (!p) return null;
    const heli = isHelicopter(p.def);
    return { x: p.w.ox + p.state.x, z: p.w.oz + p.state.z, y: p.state.y, heli, air: heli ? (p.state as AirState) : null };
  }

  /** Whether the searchlight's pool falls on (x, z), with `slack` tiles past its edge. */
  lit(x: number, z: number, slack = SLACK): boolean {
    const s = this.host.spot();
    return !!s && Math.hypot(s.x - x, s.z - z) <= s.r + slack;
  }

  /** The ground (or sea) height at a point in world tiles; NaN where no cell is in memory. */
  protected ground(x: number, z: number): number {
    const w = this.host.worldAt(Math.floor(x / N), Math.floor(z / N));
    return w ? Math.max(heightAt(w, x - w.ox, z - w.oz), SEA * STEP - 0.035) : NaN;
  }

  /** Water a boat can float on. */
  protected wet(x: number, z: number): boolean {
    const w = this.host.worldAt(Math.floor(x / N), Math.floor(z / N));
    if (!w) return false;
    const lx = x - w.ox, lz = z - w.oz, i = idx(Math.floor(lx), Math.floor(lz));
    return w.water[i] >= 0 || heightAt(w, lx, lz) < SEA * STEP - 0.15;
  }

  private waitFor(): void {
    const p = this.me();
    if (!p) return;
    const d = Math.hypot(p.x - this.o.at.x, p.z - this.o.at.z);
    if (!p.heli) { this.show(`🚁 Needs the helicopter`); return; }
    if (!this.host.dark()) { this.show(`🌙 Back after dark · ${Math.round(d)} t to ${esc(this.o.at.name)}`); return; }
    if (d > this.startR + this.o.r) { this.show(`🚁 ${Math.round(d)} t to ${esc(this.o.at.name)}`); return; }
    this.started = true;
    this.begin();
  }

  protected abstract begin(): void;
  protected abstract run(dt: number): void;

  /** Where the tracker points: the op's place until it starts, then what the op says. */
  target(): { x: number; z: number; name: string } {
    return this.started && this.aimAt ? this.aimAt : { x: this.o.at.x, z: this.o.at.z, name: this.o.at.name };
  }
  line(): string | null { return this.started ? this.next || null : null; }

  protected finish(ok: boolean, score: number, line: string): void {
    if (this.result) return;
    this.result = { ok, score: clamp(score, 0, 1), line };
    this.host.beep(true);
  }

  /** The strip at the foot of the screen. */
  protected show(html: string): void {
    if (!this.strip) return;
    if (this.strip.innerHTML !== html) this.strip.innerHTML = html;
    this.strip.hidden = false;
  }

  /** The big cue in the middle: "3", "ACTION", "ON AIR". */
  protected cue(text: string, secs = 1.2): void {
    this.bigText = text;
    this.bigT = secs;
    if (this.big) { this.big.textContent = text; this.big.classList.remove('pop'); void this.big.offsetWidth; this.big.classList.add('pop'); }
  }

  /** Say something once (not again while the same line stands). */
  protected once(title: string, body: string): void {
    const k = `${title}|${body}`;
    if (k === this.said) return;
    this.said = k;
    this.host.say(title, body);
  }

  private draw(): void {
    if (this.big) this.big.hidden = this.bigT <= 0 || !this.bigText;
  }

  /** The name tag over the one thing that matters most, projected. */
  protected tagOver(camera: THREE.Camera): { x: number; y: number; z: number; text: string } | null { void camera; return null; }

  label(camera: THREE.Camera): void {
    if (!this.tag) return;
    const t = this.result ? null : this.tagOver(camera);
    if (!t) { this.tag.hidden = true; return; }
    const v = new THREE.Vector3(t.x, t.y, t.z).project(camera);
    if (v.z > 1) { this.tag.hidden = true; return; }
    this.tag.hidden = false;
    this.tag.textContent = t.text;
    this.tag.style.transform = `translate(${((v.x + 1) / 2) * innerWidth}px, ${((1 - v.y) / 2) * innerHeight}px) translate(-50%, -100%)`;
  }

  /** A figure of this look at a spot, added to the op. */
  protected figure(p: { x: number; z: number }, look: Look, coat: number, glow: number, scale: number, k: number): Figure {
    const f = new Figure(p.x, p.z, look, coat, glow, scale, this.id * 31 + k * 7);
    this.g.add(f.g);
    this.figs.push(f);
    return f;
  }

  protected car(id: string, name: string, def: LandDef, x: number, z: number, heading: number): OpCar {
    const c = new OpCar(this.host, this.scene, id, name, def, x, z, heading);
    this.cars.push(c);
    return c;
  }

  dispose(): void {
    for (const c of this.cars) c.dispose();
    for (const p of this.props) p.dispose();
    this.scene.remove(this.g);
    this.g.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.geometry.dispose();
      if (m.userData.own) (m.material as THREE.Material).dispose();
    });
    this.strip?.remove();
    this.big?.remove();
    this.tag?.remove();
    startPrompt.hide(`op${this.id}`);
  }
}

// ---- search and rescue: someone lost ----------------------------------------------------------------

const LOST_LOOK: Record<string, { look: Look; coat: number; scale: number; name: string }> = {
  hiker: { look: 'hiker', coat: 0xf28c38, scale: 2.8, name: 'the hiker' },
  child: { look: 'hiker', coat: 0xf2c14e, scale: 2.1, name: 'the child' },
  dog: { look: 'dog', coat: 0xc8a070, scale: 4.2, name: 'the dog' },
  swimmer: { look: 'surfLie', coat: 0xf06a2a, scale: 2.6, name: 'the swimmer' },
};

/** How near the lost a helicopter must land to take them aboard, and how long they take to climb in. */
const BOARD_R = 4, BOARD_SECS = 1.5;

/** Find someone in the search area; land beside them and fly them to a hospital pad (or, a dog, just find it). */
class SearchOp extends Op {
  private fig!: Figure;
  private stage: 'find' | 'land' | 'fly' = 'find';
  private board = 0;
  private zone: THREE.Mesh | null = null;
  private who = LOST_LOOK[this.o.what ?? 'hiker'] ?? LOST_LOOK.hiker;

  protected begin(): void {
    const s = this.o.spots?.[0] ?? this.o.at;
    this.fig = this.figure(s, this.who.look, this.who.coat, 0xfff1b0, this.who.scale, 0);
    this.zone = groundRing(this.o.r, 0xf5cf3a, 0.35, this.o.at.x, this.o.at.z, (cx, cz) => this.host.worldAt(cx, cz));
    this.g.add(this.zone);
    this.host.say('Search area', `Sweep it with the searchlight · watch for a torch blinking`);
  }

  protected run(dt: number): void {
    const f = this.fig;
    f.update(dt, this.ground(f.x, f.z), this.lit(f.x, f.z), this.t);
    const p = this.me();
    if (this.stage === 'find') {
      this.aimAt = { x: this.o.at.x, z: this.o.at.z, name: 'the search area' };
      this.next = `Sweep the area with the searchlight`;
      this.show(`🔦 Searching for ${this.who.name} <b>${f.seen > 0 ? pct(f.seen / FIND_SECS) : ''}</b><span class="clock">${clock(this.t)}</span>`);
      if (f.seen >= FIND_SECS) {
        f.found = true;
        if (this.zone) this.zone.visible = false;
        if (this.o.what === 'dog') {
          this.finish(true, clamp(90 / Math.max(1, this.t), 0.3, 1), `Found the dog in ${clock(this.t)}`);
          this.host.say('Found!', 'The owner is on the way');
          return;
        }
        this.stage = 'land';
        this.cue('FOUND');
        this.host.say('Found them!', 'Land beside them · slow down and hold Shift');
      }
    } else if (this.stage === 'land') {
      this.aimAt = { x: f.x, z: f.z, name: this.who.name };
      this.next = 'Land beside them';
      const near = p ? Math.hypot(p.x - f.x, p.z - f.z) : 99;
      this.board = p?.air?.landed && near < BOARD_R ? this.board + dt : 0;
      this.show(`🛬 Land within ${BOARD_R} t of ${this.who.name} · ${Math.round(near)} t<span class="clock">${clock(this.t)}</span>`);
      if (this.board >= BOARD_SECS) {
        f.gone = true;
        this.stage = 'fly';
        this.host.say('Aboard', `Fly them to a hospital pad`);
      }
    } else {
      const to = this.o.to ?? this.o.at;
      this.aimAt = { x: to.x, z: to.z, name: to.name };
      this.next = 'Land on a hospital pad';
      const d = p ? Math.hypot(p.x - to.x, p.z - to.z) : 0;
      this.show(`🏥 ${Math.round(d)} t to ${esc(to.name)} · land on the pad<span class="clock">${clock(this.t)}</span>`);
      if (p?.air?.landed && p.air.pad?.kind === 'padHospital') {
        const far = this.o.to ? Math.hypot(this.o.to.x - f.x, this.o.to.z - f.z) : 60;
        const par = 70 + far / 3.5;
        this.finish(true, clamp(par / Math.max(1, this.t), 0.3, 1), `Safe at the hospital in ${clock(this.t)}`);
      }
    }
    if (this.t > 480 && this.stage === 'find') this.finish(false, 0, 'The search was called off');
  }

  protected tagOver(): { x: number; y: number; z: number; text: string } | null {
    const f = this.fig;
    return f && f.found && !f.gone ? { x: f.x, y: this.ground(f.x, f.z) + 0.8, z: f.z, text: cap(this.who.name) } : null;
  }
}

/** A swimmer at sea: find them, then hold the beam where the lifeboat should go; it steers for the light. */
class OverboardOp extends Op {
  private fig!: Figure;
  private boat: Prop | null = null;
  private zone: THREE.Mesh | null = null;
  /** Seconds the swimmer can hold on. */
  private strength = 240;

  protected begin(): void {
    const s = this.o.spots?.[0] ?? this.o.at;
    this.fig = this.figure(s, 'surfLie', LOST_LOOK.swimmer.coat, 0xfff1b0, LOST_LOOK.swimmer.scale, 0);
    this.zone = groundRing(this.o.r, 0xf5cf3a, 0.35, this.o.at.x, this.o.at.z, (cx, cz) => this.host.worldAt(cx, cz));
    this.g.add(this.zone);
    this.host.say('Man overboard', 'Sweep the water with the searchlight');
  }

  protected run(dt: number): void {
    const f = this.fig;
    const sea = SEA * STEP - 0.035;
    f.update(dt, sea + Math.sin(this.t * 2.2) * 0.02, this.lit(f.x, f.z), this.t);
    const left = this.strength - this.t;
    if (!f.found) {
      this.aimAt = { x: this.o.at.x, z: this.o.at.z, name: 'the search area' };
      this.next = 'Sweep the water with the searchlight';
      this.show(`🌊 Searching the water <b>${f.seen > 0 ? pct(f.seen / FIND_SECS) : ''}</b><span class="clock">${clock(left)} left</span>`);
      if (f.seen >= FIND_SECS) {
        f.found = true;
        if (this.zone) this.zone.visible = false;
        const from = this.o.to ?? this.o.at;
        this.boat = new Prop(this.g, defOf('splash'), from.x, sea, from.z, Math.atan2(f.x - from.x, f.z - from.z));
        this.props.push(this.boat);
        this.cue('FOUND');
        this.host.say('Found them!', 'The lifeboat steers for your light · keep the beam ahead of it');
      }
    } else if (this.boat) {
      const b = this.boat;
      this.aimAt = { x: f.x, z: f.z, name: 'the swimmer' };
      this.next = 'Light the lifeboat’s way';
      // the lifeboat makes for the pool of light, wherever it is on the water
      const s = this.host.spot();
      if (s && this.wet(s.x, s.z)) {
        const want = Math.atan2(s.x - b.x, s.z - b.z);
        b.heading += clamp(wrap(want - b.heading), -dt * 1.8, dt * 1.8);
        const d = Math.hypot(s.x - b.x, s.z - b.z);
        const v = Math.min(2.6, d * 1.5);
        const nx = b.x + Math.sin(b.heading) * v * dt, nz = b.z + Math.cos(b.heading) * v * dt;
        if (this.wet(nx, nz)) { b.x = nx; b.z = nz; }
        else if (this.wet(nx, b.z)) b.x = nx;
        else if (this.wet(b.x, nz)) b.z = nz;
      }
      b.y = sea + Math.sin(this.t * 1.7) * 0.02;
      b.pose();
      const gap = Math.hypot(b.x - f.x, b.z - f.z);
      this.show(`🛟 Lifeboat ${Math.round(gap)} t from the swimmer${s ? '' : ' · <b>N</b> for the light'}<span class="clock">${clock(left)} left</span>`);
      if (gap < 1.1) {
        f.gone = true;
        this.finish(true, clamp(left / this.strength + 0.35, 0.3, 1), `Pulled from the water with ${clock(left)} to spare`);
        this.host.say('Rescued!', 'The lifeboat has them');
      }
    }
    if (left <= 0) this.finish(false, 0, 'The swimmer was swept away');
  }

  protected tagOver(): { x: number; y: number; z: number; text: string } | null {
    const f = this.fig;
    return f?.found && !f.gone ? { x: f.x, y: SEA * STEP + 0.6, z: f.z, text: 'Swimmer' } : null;
  }
}

// ---- pursuit: keep a fleeing car lit ---------------------------------------------------------------

/** How long a chase runs at most, and how long the suspect may be out of the beam before they are lost. */
const CHASE_SECS = 80, DARK_LOSE = 8;

/** A pursuit (and a sweep, which is a search for a stolen car that then bolts). */
class ChaseOp extends Op {
  private crook: OpCar | null = null;
  private cop: OpCar | null = null;
  private stage: 'find' | 'rolling' | 'chase' = 'rolling';
  private fig: Figure | null = null;
  private seen = 0;
  private t0 = 0;
  private litT = 0;
  private dark = 0;
  private zone: THREE.Mesh | null = null;

  protected begin(): void {
    const top = heliTop();
    const start = this.o.spots?.[0] ?? this.o.at;
    const to = this.o.to ?? this.o.at;
    const heading = Math.atan2(to.x - start.x, to.z - start.z);
    const crookDef = opCar(this.o.op === 'sweep' ? 'sunny' : 'pip', top * 0.8, 0x2a2a2e);
    this.crook = this.car('crook', 'Suspect', crookDef, start.x, start.z, heading);
    if (this.o.op === 'sweep') {
      this.stage = 'find';
      this.crook.visible = false;
      this.zone = groundRing(this.o.r, 0xf5cf3a, 0.35, this.o.at.x, this.o.at.z, (cx, cz) => this.host.worldAt(cx, cz));
      this.g.add(this.zone);
      this.host.say('Stolen car', 'Parked somewhere in the streets with its lights off · sweep with the searchlight');
    } else this.roll();
  }

  /** The suspect sets off; the patrol car comes on behind. */
  private roll(): void {
    const c = this.crook!;
    const to = this.o.to ?? this.o.at;
    if (!c.goTo(to.x, to.z, true)) { this.finish(true, 0.5, 'Called off: no way out of town'); return; }
    c.visible = true;
    // the patrol a few tiles behind on the same line, as close as the ground allows
    const back = c.route!.pts[0];
    const bx = back.x - Math.sin(c.heading) * 3, bz = back.z - Math.cos(c.heading) * 3;
    const copDef = opCar('patrol', c.def.topSpeed * 0.98, undefined, 2);
    this.cop = this.car('cop', 'Police', copDef, bx, bz, c.heading);
    if (!this.cop.r.state) this.cop.reset(back.x + Math.cos(c.heading) * 1.3, back.z - Math.sin(c.heading) * 1.3, c.heading);
    this.cop.follow(c.route!, true);
    this.stage = 'rolling';
    this.t0 = this.t;
    this.cue('GO');
    this.host.say('He’s running!', 'Keep the suspect in your searchlight');
  }

  protected run(dt: number): void {
    const c = this.crook!;
    if (this.stage === 'find') {
      // the stolen car sits dark: it shows only where the beam falls
      const lit = this.lit(c.x, c.z, 0.5);
      c.visible = lit || this.seen > 0.3;
      this.seen = lit ? this.seen + dt : Math.max(0, this.seen - dt * 0.4);
      c.drive(dt);
      this.aimAt = { x: this.o.at.x, z: this.o.at.z, name: 'the streets' };
      this.next = 'Find the stolen car';
      this.show(`🔦 Searching the streets <b>${this.seen > 0 ? pct(this.seen / FIND_SECS) : ''}</b><span class="clock">${clock(this.t)}</span>`);
      if (this.seen >= FIND_SECS) {
        if (this.zone) this.zone.visible = false;
        this.cue('SPOTTED');
        this.roll();
      }
      if (this.t > 360) this.finish(false, 0, 'The stolen car was never found');
      return;
    }
    const cop = this.cop!;
    const chaseT = this.t - this.t0;
    // a moment for the suspect to get away before the beam is held to it
    const on = this.lit(c.x, c.z, 0.35);
    if (chaseT > 1.5) {
      if (on) { this.litT += dt; this.dark = 0; }
      else this.dark += dt;
    }
    c.drive(dt);
    // the patrol keeps close but never rams: held to the suspect's pace when on its bumper
    const gap = Math.hypot(cop.x - c.x, cop.z - c.z);
    cop.drive(dt, gap < 2.4 ? Math.max(0.5, c.v * 0.92) : Infinity);
    this.stage = 'chase';
    const share = this.litT / Math.max(1, chaseT - 1.5);
    this.aimAt = { x: c.x, z: c.z, name: 'the suspect' };
    this.next = `Keep the suspect lit · ${pct(share)}`;
    this.show(`🚨 Suspect in the beam <b class="${share >= 0.7 ? 'ahead' : 'behind'}">${pct(share)}</b>${this.dark > 2 ? ` · <b class="behind">lost ${this.dark.toFixed(0)} s</b>` : ''}<span class="clock">${clock(CHASE_SECS - chaseT)}</span>`);
    if (this.dark >= DARK_LOSE) { this.finish(false, share, 'The suspect slipped away in the dark'); return; }
    if (c.arrived || chaseT >= CHASE_SECS) {
      if (share < 0.4) this.finish(false, share, `Only ${pct(share)} in the beam: the suspect got away`);
      else {
        this.cue('CAUGHT');
        this.finish(true, share, `${grade(share)} · ${pct(share)} in the beam`);
        this.host.say('Boxed in!', `The police have him · ${pct(share)} in the beam`);
      }
    }
  }

  protected tagOver(): { x: number; y: number; z: number; text: string } | null {
    const c = this.crook;
    if (!c || !c.r.state || this.stage === 'find') return null;
    return { x: c.x, y: c.r.state.y + 0.9, z: c.z, text: 'Suspect' };
  }
}

// ---- live news: hold the story in the beam -----------------------------------------------------------

const ON_AIR = 60;

class LiveOp extends Op {
  private stage: 'count' | 'air' = 'count';
  private ratings = 60;
  private sum = 0;
  private last: { x: number; z: number } | null = null;
  private rival: Prop | null = null;
  private rivalBeam: THREE.Mesh | null = null;
  private fire: THREE.Mesh | null = null;
  private beacons: THREE.Mesh[] = [];
  protected startR = 10;

  protected begin(): void {
    const at = this.o.at, y = this.ground(at.x, at.z);
    // the story: a jack-knifed truck across the road, a patrol car with its lights going, and a fire
    const truck = new Prop(this.g, defOf('dump'), at.x, y, at.z, 0.9, 0.12);
    const patrol = new Prop(this.g, defOf('patrol'), at.x + 1.3, y, at.z - 1.1, -0.6);
    this.props.push(truck, patrol);
    this.fire = glowBall(0.45, 0xff7a1a);
    this.fire.position.set(at.x - 0.6, y + 0.35, at.z + 0.5);
    for (const [k, c] of [[0, 0xff2a2a], [1, 0x2a5aff]] as const) {
      const b = glowBall(0.16, c);
      b.position.set(at.x + 1.3 + (k ? 0.12 : -0.12), y + 0.45, at.z - 1.1);
      this.beacons.push(b);
      this.g.add(b);
    }
    this.g.add(this.fire);
    // Channel 9's helicopter, circling for the same pictures
    const rivalDef = { ...defOf('dragonfly'), color: 0x3f8fd0 };
    this.rival = new Prop(this.g, rivalDef, at.x + 5, y + 4.5, at.z, 0);
    this.props.push(this.rival);
    this.rivalBeam = new THREE.Mesh(fadingCone(16, 0.55), new THREE.MeshBasicMaterial({ color: 0xcfe0ff, vertexColors: true, transparent: true, opacity: 0.06, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide }));
    this.rivalBeam.userData.own = true;
    this.g.add(this.rivalBeam);
    this.cue('3', 1);
    this.host.say('Stand by', 'Light the scene · on air in three');
  }

  protected run(dt: number): void {
    const at = this.o.at, y = this.ground(at.x, at.z);
    // the scene flickers: fire and beacons
    if (this.fire) {
      this.fire.scale.setScalar(0.8 + Math.random() * 0.4);
      (this.fire.material as THREE.MeshBasicMaterial).opacity = 0.45 + Math.random() * 0.25;
    }
    this.beacons.forEach((b, k) => { (b.material as THREE.MeshBasicMaterial).opacity = Math.floor(this.t * 3) % 2 === k ? 0.9 : 0.1; });
    // the rival circles
    const r = this.rival!, a = this.t * 0.35;
    r.x = at.x + Math.cos(a) * 5.5; r.z = at.z + Math.sin(a) * 5.5; r.y = y + 4.5 + Math.sin(this.t * 1.2) * 0.1;
    r.heading = Math.atan2(-Math.sin(a), Math.cos(a)) + Math.PI / 2;
    r.pose();
    const rb = this.rivalBeam!;
    const top = new THREE.Vector3(r.x, r.y - 0.1, r.z), spot = new THREE.Vector3(at.x + Math.sin(this.t) * 0.6, y, at.z);
    const len = top.distanceTo(spot);
    rb.position.copy(top);
    rb.scale.set(len * 0.15, len, len * 0.15);
    rb.quaternion.setFromUnitVectors(new THREE.Vector3(0, -1, 0), spot.sub(top).normalize());
    if (this.stage === 'count') {
      const n = 3 - Math.floor(this.t);
      if (n >= 1 && this.t % 1 < 0.05) this.cue(String(n), 1);
      this.show(`📺 Stand by · on air in ${Math.max(1, n)}`);
      if (this.t >= 3) { this.stage = 'air'; this.cue('ON AIR', 1.4); this.host.beep(true); }
      this.aimAt = { x: at.x, z: at.z, name: 'the story' };
      return;
    }
    const airT = this.t - 3;
    const s = this.host.spot();
    const on = this.lit(at.x, at.z, 0.7);
    // a steady beam makes good pictures; one flung about doesn't
    let steady = 1;
    if (s && this.last) steady = 1 - Math.min(1, Math.hypot(s.x - this.last.x, s.z - this.last.z) / dt / 3);
    this.last = s ? { x: s.x, z: s.z } : null;
    const p = this.me();
    const mine = p ? Math.hypot(p.x - at.x, p.z - at.z) : 99, theirs = Math.hypot(r.x - at.x, r.z - at.z);
    const scooped = theirs < mine;
    if (on) this.ratings += dt * 9 * steady * (scooped ? 0.4 : 1) - dt * (1 - steady) * 4;
    else this.ratings -= dt * 11;
    this.ratings = clamp(this.ratings, 0, 100);
    this.sum += this.ratings * dt;
    this.next = `Hold the story in the beam · ${Math.round(this.ratings)}`;
    this.show(`📺 ON AIR · ratings <b class="${this.ratings >= 60 ? 'ahead' : 'behind'}">${Math.round(this.ratings)}</b>${scooped ? ' · Channel 9 has the better angle: get closer' : on && steady < 0.6 ? ' · steady the beam' : ''}<span class="clock">${clock(ON_AIR - airT)}</span>`);
    if (this.ratings <= 0) { this.finish(false, 0, 'Pulled off air'); return; }
    if (airT >= ON_AIR) {
      const score = this.sum / ON_AIR / 100;
      this.cue('THAT’S A WRAP');
      this.finish(true, score, `${grade(score)} · ratings ${Math.round(score * 100)}`);
    }
  }

  protected tagOver(): { x: number; y: number; z: number; text: string } | null {
    return { x: this.o.at.x, y: this.ground(this.o.at.x, this.o.at.z) + 1.2, z: this.o.at.z, text: 'The story' };
  }
}

// ---- the night shoot: light a stunt for the camera ---------------------------------------------------

/** How far along the stunt's line the mark lies, when the director calls to kill the light, and the reveal. */
const MARK_AT = 0.38, KILL_AT = 0.6, REVEAL_AT = 0.72;
const TAKES = 3, TAKE_SECS = 75;
/** Seconds after a cut with no new take called before the director wraps on the best so far (flying back included). */
const WRAP_IDLE = 60;

class ShootOp extends Op {
  private stunt: OpCar | null = null;
  private stage: 'ready' | 'count' | 'take' = 'ready';
  private take = 0;
  private best = 0;
  private tt = 0;
  private route: Route | null = null;
  private len = 0;
  private followT = 0;
  private followLit = 0;
  private marked: boolean | null = null;
  private killed = false;
  private revealT = -1;
  private revealed: boolean | null = null;
  private markRing: THREE.Mesh | null = null;
  private mark = { x: 0, z: 0 };
  private idle = 0;
  protected startR = 10;

  protected begin(): void {
    const at = this.o.at, to = this.o.to ?? at;
    const def = opCar('wasabi', heliTop() * 0.72, 0xf2c14e, 3);
    this.stunt = this.car('stunt', 'Stunt car', def, at.x, at.z, Math.atan2(to.x - at.x, to.z - at.z));
    const route = fastRoute(this.host.worldAt, def, at.x, at.z, to.x, to.z);
    if (!route) { this.finish(true, 0.5, 'Called off: the street was closed'); return; }
    this.route = route;
    this.len = route.tiles;
    this.mark = along(route.pts, 0, route.pts[0].x, route.pts[0].z, this.len * MARK_AT);
    this.markRing = groundRing(0.9, 0xff5ab4, 0.85, this.mark.x, this.mark.z, (cx, cz) => this.host.worldAt(cx, cz));
    this.g.add(this.markRing);
    this.host.say('Night shoot', 'Hover over the start and press Enter to call Action');
  }

  private action(): void {
    startPrompt.hide(`op${this.id}`);
    const s = this.stunt!;
    s.follow(this.route!, true);
    this.stage = 'count';
    this.tt = 0;
    this.take++;
    this.followT = this.followLit = 0;
    this.marked = null;
    this.killed = false;
    this.revealT = -1;
    this.revealed = null;
    this.cue('3', 1);
  }

  protected run(dt: number): void {
    const s = this.stunt;
    if (!s || !this.route) return;
    if (this.stage === 'ready') {
      s.drive(dt);
      this.idle += dt;
      this.aimAt = { x: this.o.at.x, z: this.o.at.z, name: 'the start' };
      // Action is called over the start, so the prompt (and Enter) only work there: a take ends far down the
      // street, and the prompt used to stand on screen wherever the helicopter was (a player's report, 30 Oct)
      const p = this.me(), d = p ? Math.hypot(p.x - this.o.at.x, p.z - this.o.at.z) : Infinity;
      const over = !!p?.heli && d <= this.startR + this.o.r;
      const left = this.take > 0 ? Math.max(0, Math.ceil(WRAP_IDLE - this.idle)) : -1;
      const wraps = left >= 0 && left <= 20 ? ` · wraps in ${left} s` : '';
      if (!over) {
        startPrompt.hide(`op${this.id}`);
        this.next = 'Back to the start';
        this.show(`🎬 Take ${this.take + 1} of ${TAKES} · back to the start, ${Math.round(d)} t${this.take ? ` · best so far ${pct(this.best)}` : ''}${wraps}`);
      } else {
        this.next = 'Press Enter over the start';
        this.show(`🎬 Take ${this.take + 1} of ${TAKES} · <b>Enter</b> to call Action${this.take ? ` · best so far ${pct(this.best)}` : ''}${wraps}`);
        startPrompt.show(`op${this.id}`, { key: 'Enter', title: `Night shoot · Take ${this.take + 1} of ${TAKES}`, action: 'call Action', sub: this.take ? `Best so far ${pct(this.best)}` : 'Hover over the start, then light the stunt car' });
        if (this.host.go()) { this.idle = 0; this.action(); return; }
      }
      if (this.take > 0 && this.idle > WRAP_IDLE) { startPrompt.hide(`op${this.id}`); this.wrap(); }
      return;
    }
    this.tt += dt;
    if (this.stage === 'count') {
      s.drive(dt, 0);
      const n = 3 - Math.floor(this.tt);
      if (n >= 1 && this.tt % 1 < 0.05) this.cue(String(n), 1);
      this.show(`🎬 Take ${this.take} · rolling in ${Math.max(1, n)}`);
      if (this.tt >= 3) { this.stage = 'take'; this.tt = 0; this.cue('ACTION', 1.2); this.host.beep(true); }
      return;
    }
    s.drive(dt);
    const done = this.len - s.left, f = done / Math.max(1, this.len);
    const on = this.lit(s.x, s.z, 0.35);
    const spot = this.host.spot();
    let call = 'Follow the car';
    if (f < KILL_AT || (this.revealT >= 0 && this.tt - this.revealT > 1.5)) {
      this.followT += dt;
      if (on) this.followLit += dt;
    }
    // the mark: the beam must be on it as the car goes through
    if (this.marked === null && Math.hypot(s.x - this.mark.x, s.z - this.mark.z) < 1.4) {
      this.marked = this.lit(this.mark.x, this.mark.z, 0.4);
      this.cue(this.marked ? 'ON THE MARK' : 'MISSED THE MARK', 1);
    }
    if (f >= MARK_AT - 0.12 && this.marked === null) call = 'Beam on the pink mark';
    // kill the light, then the reveal
    if (f >= KILL_AT && f < REVEAL_AT) {
      call = 'Kill the light · N';
      if (!spot) this.killed = true;
      if (!this.killed && f >= KILL_AT && this.tt % 2 < 0.05) this.cue('KILL THE LIGHT', 1);
    }
    if (f >= REVEAL_AT && this.revealT < 0) { this.revealT = this.tt; this.cue('REVEAL!', 1.2); this.host.beep(false); }
    if (this.revealT >= 0 && this.revealed === null) {
      call = 'Light on · N';
      if (this.killed && spot && on && this.tt - this.revealT <= 1.6) this.revealed = true;
      else if (this.tt - this.revealT > 1.6) this.revealed = false;
    }
    if (this.markRing) this.markRing.visible = this.marked === null;
    const follow = this.followLit / Math.max(1, this.followT);
    this.aimAt = { x: s.x, z: s.z, name: 'the stunt car' };
    this.next = call;
    this.show(`🎬 Take ${this.take} · ${call} · follow <b>${pct(follow)}</b>${this.marked !== null ? ` · mark ${this.marked ? '✔' : '✘'}` : ''}${this.revealed !== null ? ` · reveal ${this.revealed ? '✔' : '✘'}` : ''}<span class="clock">${clock(this.tt)}</span>`);
    if (s.arrived || this.tt > TAKE_SECS) {
      const score = 0.6 * follow + 0.2 * (this.marked ? 1 : 0) + 0.2 * (this.revealed ? 1 : 0);
      this.best = Math.max(this.best, score);
      this.host.say(`Cut! Take ${this.take}`, `${pct(score)} · follow ${pct(follow)}, mark ${this.marked ? 'hit' : 'missed'}, reveal ${this.revealed ? 'hit' : 'missed'}`);
      if (score >= 0.8 || this.take >= TAKES) { this.wrap(); return; }
      // back to the start for another go
      s.reset(this.o.at.x, this.o.at.z, Math.atan2(this.route.pts[1].x - this.route.pts[0].x, this.route.pts[1].z - this.route.pts[0].z));
      this.stage = 'ready';
      this.idle = 0;
      if (this.markRing) this.markRing.visible = true;
    }
  }

  private wrap(): void {
    const b = this.best;
    if (b < 0.45) this.finish(false, b, `Best take ${pct(b)}: the director walked`);
    else { this.cue('THAT’S A WRAP'); this.finish(true, b, `${grade(b)} · best take ${pct(b)}`); }
  }

  protected tagOver(): { x: number; y: number; z: number; text: string } | null {
    const s = this.stunt;
    return s?.r.state ? { x: s.x, y: s.r.state.y + 0.9, z: s.z, text: 'Stunt car' } : null;
  }
}

// ---- blackout: light the ambulance's way -----------------------------------------------------------

/** How fast the ambulance creeps where the road ahead is dark. */
const DARK_CREEP = 0.3;

class BlackoutOp extends Op {
  private amb: OpCar | null = null;
  private runT = 0;
  private plan = 60;
  private litT = 0;

  protected begin(): void {
    const at = this.o.at, to = this.o.to ?? at;
    const def = opCar('ambulance', heliTop() * 0.7, undefined, 1);
    this.amb = this.car('amb', 'Ambulance', def, at.x, at.z, Math.atan2(to.x - at.x, to.z - at.z));
    if (!this.amb.goTo(to.x, to.z, false)) { this.finish(true, 0.5, 'Called off: the road was blocked'); return; }
    this.plan = this.amb.route!.seconds;
    this.cue('GO');
    this.host.say('Power’s out', 'Light the road just ahead of the ambulance');
  }

  protected run(dt: number): void {
    const a = this.amb;
    if (!a || !a.route) return;
    this.runT += dt;
    const ahead = a.ahead(1.8);
    const lit = this.lit(ahead.x, ahead.z, 0.4) || this.lit(a.x, a.z, 0.2);
    if (lit) this.litT += dt;
    a.drive(dt, lit ? Infinity : DARK_CREEP);
    const to = this.o.to ?? this.o.at;
    this.aimAt = { x: a.x, z: a.z, name: 'the ambulance' };
    this.next = 'Light the road ahead of it';
    this.show(`🚑 ${Math.round(a.left)} t to ${esc(to.name)} · ${lit ? '<b class="ahead">road lit</b>' : '<b class="behind">in the dark: crawling</b>'}<span class="clock">${clock(this.runT)}</span>`);
    if (a.arrived) {
      const score = clamp((this.plan * 1.25) / Math.max(1, this.runT), 0.3, 1);
      this.finish(true, score, `At the hospital in ${clock(this.runT)} · ${grade(score)}`);
      this.host.say('Made it', 'The patient is inside');
    } else if (this.runT > this.plan * 2.5 + 25) this.finish(false, 0, 'The ambulance never got through');
  }

  protected tagOver(): { x: number; y: number; z: number; text: string } | null {
    const a = this.amb;
    return a?.r.state ? { x: a.x, y: a.r.state.y + 0.9, z: a.z, text: 'Ambulance' } : null;
  }
}

// ---- loose livestock: light each stray for the rancher --------------------------------------------

const LIVESTOCK_SECS = 240;

class LivestockOp extends Op {
  private truck: OpCar | null = null;
  private goal: Figure | null = null;
  private litFor = new Map<Figure, number>();
  private saved = 0;
  private lost = 0;
  private replan = 0;
  private wander = new Map<Figure, number>();

  protected begin(): void {
    (this.o.spots ?? []).forEach((s, k) => {
      const f = this.figure(s, this.o.what === 'sheep' ? 'sheep' : 'cow', 0xf4f0e6, this.o.what === 'sheep' ? 3.2 : 3, 0xffffff, k);
      f.always = true;
      f.heading = k * 1.7;
      this.wander.set(f, k * 2.1);
    });
    const farm = this.o.to ?? this.o.at;
    this.truck = this.car('rancher', 'Rancher', opCar('mule', heliTop() * 0.7, 0x8a3a2a, 1), farm.x, farm.z, 0);
    this.host.say('Stock on the road', 'Light a stray: the rancher drives to the one in your beam');
  }

  protected run(dt: number): void {
    const tr = this.truck!;
    const live = this.figs.filter((f) => !f.gone);
    for (const f of live) {
      const lit = this.lit(f.x, f.z, 0.2);
      f.update(dt, this.ground(f.x, f.z), lit, this.t);
      this.litFor.set(f, lit ? (this.litFor.get(f) ?? 0) + dt : 0);
      if (!lit) this.stroll(f, dt);
      // a lit stray is the one the rancher heads for
      if (lit && (this.litFor.get(f) ?? 0) > 0.5 && this.goal !== f && this.replan <= 0) {
        this.goal = f;
        this.replan = 1;
        if (!tr.goTo(f.x, f.z)) this.goal = null;
      }
    }
    this.replan -= dt;
    // the one being fetched wanders off its line, or the pickup pulled up short of it: plan again
    if (this.goal && this.replan <= 0) {
      const end = tr.route?.pts[tr.route.pts.length - 1];
      if (!end || tr.arrived || Math.hypot(end.x - this.goal.x, end.z - this.goal.z) > 2.5) {
        if (!tr.goTo(this.goal.x, this.goal.z)) this.goal = null;
        this.replan = 1.5;
      }
    }
    tr.drive(dt);
    for (const f of live) {
      // the rancher gets out and walks the last bit: in reach once the pickup has pulled up beside it
      if (Math.hypot(tr.x - f.x, tr.z - f.z) < 2.2) {
        f.gone = true;
        this.saved++;
        if (this.goal === f) { this.goal = null; tr.stop(); }
        this.host.say('Got one', `${this.saved} safe`);
      }
    }
    // drivers see a lit animal and slow; one in the dark on the road gets clipped
    if (this.t > 12) {
      for (const f of this.figs) {
        if (f.gone || f.lit) continue;
        const w = this.host.worldAt(Math.floor(f.x / N), Math.floor(f.z / N));
        if (!w) continue;
        const lx = f.x - w.ox, lz = f.z - w.oz;
        if (!w.road[idx(Math.floor(lx), Math.floor(lz))]) continue;
        if (this.host.traffic(w).some((a) => Math.hypot(a.x - lx, a.z - lz) < 0.55)) {
          f.gone = true;
          this.lost++;
          if (this.goal === f) { this.goal = null; tr.stop(); }
          this.host.say('Too late', 'A car clipped a stray in the dark');
        }
      }
    }
    const total = this.figs.length, left = total - this.saved - this.lost;
    const next = this.goal ?? live.find((f) => !f.gone) ?? null;
    this.aimAt = next ? { x: next.x, z: next.z, name: 'a stray' } : null;
    this.next = `Light a stray · ${this.saved} of ${total} safe`;
    this.show(`🐄 ${this.saved} of ${total} safe${this.lost ? ` · ${this.lost} lost` : ''} · ${left} on the loose${this.goal ? ' · <b class="ahead">rancher on the way</b>' : ''}<span class="clock">${clock(LIVESTOCK_SECS - this.t)}</span>`);
    if (left === 0 || this.t >= LIVESTOCK_SECS) {
      const score = this.saved / Math.max(1, total);
      if (this.saved * 2 < total) this.finish(false, score, `Only ${this.saved} of ${total} brought in`);
      else this.finish(true, score, `${this.saved} of ${total} brought in · ${grade(score)}`);
    }
  }

  /** A stray ambles about along the road it got out onto, head down, never off it into a field or a building. */
  private stroll(f: Figure, dt: number): void {
    let turn = (this.wander.get(f) ?? 0) - dt;
    if (turn <= 0) { f.heading += (Math.random() - 0.5) * 2; turn = 2 + Math.random() * 3; }
    this.wander.set(f, turn);
    const nx = f.x + Math.sin(f.heading) * 0.25 * dt, nz = f.z + Math.cos(f.heading) * 0.25 * dt;
    const w = this.host.worldAt(Math.floor(nx / N), Math.floor(nz / N));
    if (!w) return;
    const i = idx(Math.floor(nx - w.ox), Math.floor(nz - w.oz));
    if (!w.road[i] || w.blocked[i] || w.deckAxis[i] || this.wet(nx, nz)) { f.heading += Math.PI * 0.7; return; }
    f.x = nx; f.z = nz;
  }

  protected tagOver(): { x: number; y: number; z: number; text: string } | null {
    const t = this.truck;
    return t?.r.state && this.goal ? { x: t.x, y: t.r.state.y + 0.9, z: t.z, text: 'Rancher' } : null;
  }
}

// ---- drop spotter: tag the smugglers' contacts -------------------------------------------------------

const DROPS_SECS = 300;

class DropsOp extends Op {
  private sent = new Map<Figure, OpCar>();
  private tagged = 0;
  private lastTag = 0;
  private zone: THREE.Mesh | null = null;

  protected begin(): void {
    (this.o.spots ?? []).forEach((s, k) => this.figure(s, 'hiker', 0x2a2a30, 0xb45aff, 2.8, k));
    this.zone = groundRing(this.o.r, 0xb45aff, 0.3, this.o.at.x, this.o.at.z, (cx, cz) => this.host.worldAt(cx, cz));
    this.g.add(this.zone);
    this.host.say('Drop tonight', 'Watch for purple lanterns · hold the beam on each contact');
  }

  protected run(dt: number): void {
    const from = this.o.to ?? this.o.at;
    for (const f of this.figs) {
      f.update(dt, this.ground(f.x, f.z), this.lit(f.x, f.z), this.t);
      if (!f.found && f.seen >= FIND_SECS) {
        f.found = true;
        this.tagged++;
        this.lastTag = this.t;
        this.cue('TAGGED', 1);
        // a patrol car goes for them from the station
        const cop = this.car(`cop${this.tagged}`, 'Police', opCar('patrol', heliTop() * 0.75, undefined, 1), from.x, from.z, Math.atan2(f.x - from.x, f.z - from.z));
        if (cop.goTo(f.x, f.z)) this.sent.set(f, cop);
        this.host.say('Tagged', `${this.tagged} of ${this.figs.length} · a patrol car is on its way`);
      }
    }
    for (const [f, cop] of this.sent) {
      cop.drive(dt);
      if (!f.gone && Math.hypot(cop.x - f.x, cop.z - f.z) < 1.6) { f.gone = true; this.host.say('Arrested', 'One contact in the back of a patrol car'); }
    }
    const total = this.figs.length;
    const nextF = this.figs.find((f) => !f.found);
    this.aimAt = nextF ? { x: this.o.at.x, z: this.o.at.z, name: 'the area' } : null;
    this.next = `Tag the contacts · ${this.tagged} of ${total}`;
    this.show(`🟣 Contacts tagged <b>${this.tagged} of ${total}</b>${this.figs.some((f) => !f.found && f.seen > 0) ? ` · holding ${pct(Math.max(...this.figs.filter((f) => !f.found).map((f) => f.seen)) / FIND_SECS)}` : ''}<span class="clock">${clock(DROPS_SECS - this.t)}</span>`);
    if (this.tagged === total) {
      if (this.zone) this.zone.visible = false;
      const arrested = this.figs.every((f) => f.gone);
      if (arrested || this.t - this.lastTag > 25) {
        const score = clamp(150 / Math.max(1, this.lastTag), 0.4, 1);
        this.finish(true, score, `All ${total} tagged in ${clock(this.lastTag)} · ${grade(score)}`);
      }
    } else if (this.t >= DROPS_SECS) {
      if (this.tagged * 3 >= total * 2) this.finish(true, 0.35, `${this.tagged} of ${total} tagged before the drop`);
      else this.finish(false, 0, `Only ${this.tagged} of ${total} tagged: the drop went ahead`);
    }
  }
}

const cap = (s: string) => s[0].toUpperCase() + s.slice(1);

/** The op for an objective. */
export function makeOp(id: number, host: OpHost, scene: THREE.Scene, o: OpObj): Op {
  switch (o.op) {
    case 'search': return new SearchOp(id, host, scene, o);
    case 'overboard': return new OverboardOp(id, host, scene, o);
    case 'pursuit': case 'sweep': return new ChaseOp(id, host, scene, o);
    case 'live': return new LiveOp(id, host, scene, o);
    case 'shoot': return new ShootOp(id, host, scene, o);
    case 'blackout': return new BlackoutOp(id, host, scene, o);
    case 'livestock': return new LivestockOp(id, host, scene, o);
    case 'drops': return new DropsOp(id, host, scene, o);
  }
}

export type { PlaceRef };
