/**
 * The HQ window (docs/hqwindow.html): everything the company owns, in one window on H, the fleet's name in the top bar, or
 * your HQ building's card. Five tabs: Home (the HQ on its plinth and the company's numbers), Fleet (the
 * depot board: what is out, the garage, the bench, and the pane with the vehicle inspector), Estate (the
 * old K window, folded in), Tech (the tech trees as one map) and Books (every dollar, charted). Nothing is
 * bought here: vehicles and parts are bought at a Dealer or Vehicle Shop, by driving there.
 *
 * A full-screen card like the garage's, and the game waits while it is open. 1–6 or Tab for the tabs,
 * Esc (a drag, a rename, then the window) or H to close.
 */
import type { DiamondsTab, HeartsTab } from './purseTabs';
import { esc, money } from './cargoHud';
import { spinGem } from './gem';
import type { Fleet, Unit } from './fleet';
import { FleetBoard, pickKey } from './fleetBoard';
import type { UnitPane } from './unitPane';
import type { EstateTab } from './estateTab';
import type { TechTab } from './techTab';
import type { BooksTab } from './booksTab';
import type { FactionsTab } from './factions/factionsTab';
import type { FactionId } from './factions/factions';
import type { HqHome, HqTab } from './hqHome';
import { gradeName, gradePips } from './hqGrade';
import type { TreatsTab } from './treatsTab';
import { ToppersTab } from './toppersTab';

// the running of the firm first, then where it stands, then the diamonds and what they buy (the user, 28 Oct 2026: tech last)
// The Passport's Treats live on the Toppers tab, one "Treats & Toppers" (the user, 6 Nov 2026: so Tech is 9 again);
// 'treats' stays a tab name only so anything opening it lands there.
// The Diamonds sit over the tree on the Tech tab (the user, 6 Nov 2026): 'diamonds' stays a tab name only, to land there.
const HQ_TABS: HqTab[] = ['home', 'fleet', 'estate', 'books', 'factions', 'hearts', 'toppers', 'tech'];
const TAB_LABEL: Record<HqTab, string> = { home: 'Home', fleet: 'Fleet', estate: 'Estate', tech: 'Tech', books: 'Books', diamonds: 'Tech', hearts: 'Hearts', factions: 'Factions', treats: 'Treats & Toppers', toppers: 'Treats & Toppers' };
const TAB_KEY = 'tinyfleet-hq-tab';

interface HqWindowHost {
  cash(): number;
  diamonds(): number;
  /** The fleet's shield, for the header. */
  shield(): string;
  /** Called on open, so the other windows and tools can step aside. */
  opened(): void;
  /** The crests of the factions the player is Sworn to, as HTML for the header (docs/factions.html). */
  sworn?(): string;
}

interface HqParts {
  home: HqHome;
  board: FleetBoard;
  pane: UnitPane;
  estate: EstateTab;
  tech: TechTab;
  books: BooksTab;
  diamonds: DiamondsTab;
  hearts: HeartsTab;
  factions: FactionsTab;
}

export class HqWindow {
  readonly el = document.createElement('div');
  isOpen = false;
  private tab: HqTab = 'home';
  private tabsEl = document.createElement('nav');
  private head = document.createElement('div');
  private purse = document.createElement('div');
  private note = document.createElement('p');
  private pages = new Map<HqTab, HTMLElement>();
  private message = '';
  private messageT = 0;
  private liveT = 0;
  private headHtml = '';
  /** The toppers (game/toppersTab.ts, docs/toppers.html): the fleet's dress, the Passport's treats, every topper and crown. */
  readonly toppers: ToppersTab;
  /** The Passport's treats (game/treatsTab.ts), a section of the Toppers tab. */
  get treats(): TreatsTab { return this.toppers.treats; }

  constructor(private fleet: Fleet, readonly parts: HqParts, private host: HqWindowHost) {
    this.toppers = new ToppersTab(fleet);
    this.toppers.say = (t) => this.say(t);
    this.el.id = 'hq';
    this.el.hidden = true;
    const panel = document.createElement('div');
    panel.className = 'panel';
    const header = document.createElement('header');
    this.head.className = 'hq-head';
    this.purse.className = 'hq-purse';
    // solo (one vehicle's details): the way back to the whole Fleet tab
    this.soloBack.type = 'button';
    this.soloBack.className = 'hq-solo-back';
    this.soloBack.textContent = 'Whole fleet';
    this.soloBack.title = 'The Fleet tab: the board and this pane';
    this.soloBack.addEventListener('click', () => this.setSolo(false));
    header.append(this.head, this.purse, this.soloBack);
    this.tabsEl.className = 'gtabs hq-tabs';
    this.tabsEl.setAttribute('role', 'tablist');
    for (const [i, t] of HQ_TABS.entries()) {
      const b = document.createElement('button');
      b.type = 'button';
      b.dataset.tab = t;
      b.setAttribute('role', 'tab');
      b.innerHTML = `<kbd>${i + 1}</kbd> ${TAB_LABEL[t]}`;
      b.addEventListener('click', () => this.show(t));
      this.tabsEl.append(b);
    }
    this.note.className = 'note hq-note';
    // the pages
    const fleetPage = document.createElement('section');
    fleetPage.className = 'hq-page hq-fleet';
    fleetPage.append(parts.board.el, parts.pane.el);
    this.pages.set('home', wrap('hq-page', parts.home.el));
    this.pages.set('fleet', fleetPage);
    this.pages.set('estate', wrap('hq-page', parts.estate.el));
    // the diamonds, condensed, over the whole tree that spends them
    const techPage = wrap('hq-page hq-techpage', parts.diamonds.el);
    techPage.append(parts.tech.el);
    this.pages.set('tech', techPage);
    this.pages.set('books', wrap('hq-page', parts.books.el));
    this.pages.set('hearts', wrap('hq-page', parts.hearts.el));
    parts.hearts.onData = () => { if (this.isOpen && this.tab === 'hearts') parts.hearts.render(true); };
    this.pages.set('factions', wrap('hq-page', parts.factions.el));
    this.pages.set('toppers', wrap('hq-page', this.toppers.el));
    panel.append(header, this.tabsEl, this.note, ...this.pages.values());
    this.el.append(panel);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    window.addEventListener('keydown', (e) => this.onKey(e));
    try {
      const t = localStorage.getItem(TAB_KEY) as HqTab | null;
      if (t === 'treats') this.tab = 'toppers';
      else if (t === 'diamonds') this.tab = 'tech';
      else if (t && HQ_TABS.includes(t)) this.tab = t;
    } catch { /* not remembered */ }
  }

  get current(): HqTab { return this.tab; }

  /**
   * One vehicle's details on their own: the Fleet tab's right-hand pane in a card of its own width, without
   * the tabs or the board (the dock's Open details, or a double-click on a fleet square). Any other tab, or
   * Whole fleet, opens the window out again.
   */
  private solo = false;
  private soloBack = document.createElement('button');
  get isSolo(): boolean { return this.isOpen && this.solo; }
  private setSolo(on: boolean): void {
    if (this.solo === on) return;
    this.solo = on;
    this.el.classList.toggle('solo', on);
    if (!on && this.isOpen) this.sync(true);
  }

  /** Open one vehicle's details on their own (see solo). */
  openDetails(u: Unit): void {
    this.parts.pane.set({ k: 'unit', uid: u.uid });
    this.open('fleet');
    this.setSolo(true);
    // from its top: its name, its Watch, what it is doing
    this.parts.pane.el.scrollTop = 0;
  }

  /** Did this Esc go to a drag or a rename? (Read once by the frame, which closes the window otherwise.) */
  private ateEscape = false;
  takeEscape(): boolean { const a = this.ateEscape; this.ateEscape = false; return a; }

  toggle(): void { if (this.isOpen) this.close(); else this.open(); }

  /** Open, at a tab if given (else the last one used). */
  open(tab?: HqTab): void {
    this.setSolo(false);
    if (!this.isOpen) {
      this.isOpen = true;
      this.el.hidden = false;
      this.host.opened();
    }
    this.message = '';
    this.show(tab ?? this.tab);
  }

  /** Open the Fleet tab with one vehicle picked. */
  openUnit(u: Unit): void {
    this.parts.pane.set({ k: 'unit', uid: u.uid });
    this.open('fleet');
  }

  /** Open the Tech tab at a model. */
  openTech(id?: string): void {
    this.parts.tech.focus(id);
    this.open('tech');
  }

  /** Open the Factions tab at one faction. */
  openFaction(f: FactionId): void {
    this.parts.factions.focus(f);
    this.open('factions');
  }

  close(): void {
    if (!this.isOpen) return;
    this.setSolo(false);
    this.parts.board.cancel();
    this.parts.board.endCoach();
    this.isOpen = false;
    this.el.hidden = true;
    for (const p of [this.parts.home, this.parts.pane, this.parts.tech, this.parts.factions, this.toppers]) p.setVisible(false);
    (document.activeElement as HTMLElement | null)?.blur?.();
  }

  /** The tabs offered: all nine, so the number keys reach every one. */
  private get tabs(): HqTab[] { return HQ_TABS; }

  show(t: HqTab): void {
    // another tab is the whole window again
    if (t !== 'fleet') this.setSolo(false);
    // the Treats are a section of the Toppers tab now
    if (t === 'treats') t = 'toppers';
    // and the Diamonds the top of the Tech tab
    if (t === 'diamonds') t = 'tech';
    const tabs = this.tabs;
    if (!tabs.includes(t)) t = 'home';
    this.tab = t;
    try { localStorage.setItem(TAB_KEY, t); } catch { /* not remembered */ }
    for (const b of Array.from(this.tabsEl.querySelectorAll<HTMLElement>('button'))) {
      const k = tabs.indexOf(b.dataset.tab as HqTab);
      b.hidden = k < 0;
      const kbd = b.querySelector('kbd');
      // the number keys reach the first nine tabs offered
      if (kbd && k >= 0) { kbd.textContent = String(k + 1); kbd.hidden = k >= 9; }
      const on = b.dataset.tab === t;
      b.classList.toggle('on', on);
      b.setAttribute('aria-selected', String(on));
    }
    for (const [k, p] of this.pages) p.hidden = k !== t;
    // the one hero stage goes where it is needed now
    this.parts.home.setVisible(this.isOpen && t === 'home');
    this.parts.pane.setVisible(this.isOpen && t === 'fleet');
    this.parts.tech.setVisible(this.isOpen && t === 'tech');
    this.parts.factions.setVisible(this.isOpen && t === 'factions');
    this.toppers.setVisible(this.isOpen && t === 'toppers');
    if (!this.message) this.note.textContent = this.hint();
    this.sync(true);
  }

  /** A line under the tabs, for a few seconds. */
  say(text: string): void {
    this.message = text;
    this.messageT = 6;
    this.note.textContent = text;
  }

  /** Redraw whatever is up (the fleet, the money or the deeds changed). */
  sync(force = false): void {
    if (!this.isOpen) return;
    this.renderHead();
    switch (this.tab) {
      case 'home': this.parts.home.render(force); break;
      case 'fleet': this.parts.board.render(force); if (force) this.parts.pane.render(); break;
      case 'estate': this.parts.estate.render(force); break;
      case 'tech': this.parts.diamonds.render(force); this.parts.tech.render(force); break;
      case 'books': this.parts.books.render(force); break;
      case 'hearts': if (force) this.parts.hearts.shown(); this.parts.hearts.render(force); break;
      case 'factions': this.parts.factions.render(force); break;
      case 'toppers': this.toppers.render(force); break;
    }
  }

  /** Every frame while open: the live lines twice a second, and the note's timer. */
  tick(dt: number): void {
    if (!this.isOpen) return;
    if (this.messageT > 0 && (this.messageT -= dt) <= 0) { this.message = ''; this.note.textContent = this.hint(); }
    this.liveT -= dt;
    if (this.liveT > 0) return;
    this.liveT = 0.5;
    this.renderHead();
    if (!this.message) this.note.textContent = this.hint();
    if (this.tab === 'fleet') {
      if (!this.parts.board.dragging) this.parts.board.render();
      this.parts.board.refresh();
      this.parts.pane.refresh();
    } else this.sync();
  }

  private hint(): string {
    switch (this.tab) {
      case 'fleet': return 'Drag a driver onto a vehicle or the bench (onto someone’s seat to swap them), a garaged vehicle onto a free slot, onto yours, or onto one on the map to swap, a vehicle into the garage. Every move has a button in the pane too.';
      case 'estate': return 'Every load that starts or ends at a door you own pays you, whoever drives it. A lot earns only while its island is loaded.';
      case 'tech': return 'Diamonds come from the towns that prefer your fleet, from PvP boards held and from every achievement tier; the tree below spends them. Unlocking a model puts it on sale at the dealers that stock it.';
      case 'books': return 'Every dollar in and out, by the day. Sales and refunds are not revenue: they show apart.';
      case 'hearts': return 'Likes from other players: a heart on a road or bridge you built, a thumbs-up on a sign of yours, five for every fleet that takes a car from your postcard.';
      case 'toppers': return 'Toppers are kept for good once earned and cost nothing to wear: pick one for each kind of vehicle here, or for one vehicle in its pane on the Fleet tab. A treat comes with every Passport page filled; paintjobs, lamps and horns are fitted in the workshop (G).';
      case 'factions': return 'Standing moves with their work delivered, their missions done and what you do for or against them. Each rung from Friend up unlocks something for good.';
      default: return 'Vehicles and parts are bought at a Vehicle Dealer or Vehicle Shop: drive into its striped ring and press Space.';
    }
  }

  private renderHead(): void {
    const f = this.fleet, h = f.hq;
    const shield = this.host.shield();
    const html = `${shield ? `<img class="shield" alt="" src="${shield}">` : ''}<div><h2>${esc(f.brand?.name ?? 'Your fleet')}<span>.</span>${this.host.sworn?.() ?? ''}</h2>`
      + `<small>${h ? `Headquarters · ${esc(h.name)}${h.town ? `, ${esc(h.town)}` : ''} <span class="stars">${gradePips(h.grade)}</span> ${esc(gradeName(h))} · ${f.slots} slot${f.slots === 1 ? '' : 's'}` : 'No HQ yet'}</small></div>`;
    if (html !== this.headHtml) { this.headHtml = html; this.head.innerHTML = html; }
    const purse = `<span class="cash">${money(this.host.cash())}</span><span class="bal"><canvas class="gem-spin"></canvas>${Math.floor(this.host.diamonds() + 1e-9)}</span><span class="keys"><kbd>H</kbd> close</span>`;
    if (this.purse.dataset.html !== purse) {
      this.purse.dataset.html = purse;
      this.purse.innerHTML = purse;
      const gem = this.purse.querySelector('canvas');
      if (gem) spinGem(gem);
    }
  }

  private onKey(e: KeyboardEvent): void {
    if (!this.isOpen) return;
    const t = e.target as HTMLElement | null;
    const typing = t?.tagName === 'INPUT' && (t as HTMLInputElement).type === 'text';
    if (typing) return;
    // Esc first drops a drag or a rename; the window itself closes in the game's frame (main.ts), so the
    // same press doesn't also open the pause menu, and H likewise
    if (e.code === 'Escape') {
      e.preventDefault();
      if (this.parts.board.cancel() || this.parts.pane.escape()) this.ateEscape = true;
      return;
    }
    if (t?.tagName === 'SELECT' || (t?.tagName === 'INPUT')) return;
    const tabs = this.tabs;
    if (/^Digit[1-9]$/.test(e.code)) { const t = tabs[Number(e.code.slice(5)) - 1]; if (t) this.show(t); e.preventDefault(); return; }
    if (e.code === 'Tab') { this.show(tabs[(tabs.indexOf(this.tab) + (e.shiftKey ? tabs.length - 1 : 1)) % tabs.length]); e.preventDefault(); return; }
    if (this.tab === 'tech' && this.parts.tech.key(e.code)) { e.preventDefault(); return; }
    if (this.tab === 'factions' && this.parts.factions.key(e.code)) { e.preventDefault(); return; }
    if (this.tab === 'fleet' && this.boardKey(e.code)) e.preventDefault();
  }

  /** Arrow keys on the board: along a zone, and up and down between zones. */
  private boardKey(code: string): boolean {
    const f = this.fleet;
    const zones: string[][] = [
      [...(f.ridden ? [pickKey({ k: 'unit', uid: f.ridden.uid })] : []), ...f.deployed.flatMap((u) => [pickKey({ k: 'unit', uid: u.uid }), ...(u.driver ? [pickKey({ k: 'driver', id: u.driver })] : [])])],
      f.garaged.map((u) => pickKey({ k: 'unit', uid: u.uid })),
      [...f.bench.map((d) => pickKey({ k: 'driver', id: d.id })), 'hire'],
    ].filter((z) => z.length);
    const cur = this.parts.pane.pick ? pickKey(this.parts.pane.pick as never) : '';
    let zi = zones.findIndex((z) => z.includes(cur)), i = zi >= 0 ? zones[zi].indexOf(cur) : -1;
    if (zi < 0) { zi = 0; i = -1; }
    if (code === 'ArrowRight') i = (i + 1) % zones[zi].length;
    else if (code === 'ArrowLeft') i = (i - 1 + zones[zi].length) % zones[zi].length;
    else if (code === 'ArrowDown' || code === 'ArrowUp') { zi = (zi + (code === 'ArrowDown' ? 1 : zones.length - 1)) % zones.length; i = Math.min(Math.max(0, i), zones[zi].length - 1); }
    else if (code === 'Enter' || code === 'NumpadEnter') {
      const u = this.parts.pane.unit;
      if (u && u.where !== 'ridden') this.parts.pane.el.querySelector<HTMLButtonElement>('button[data-act="ride"]')?.click();
      return true;
    } else return false;
    const k = zones[zi]?.[i];
    if (!k) return true;
    this.parts.pane.set(k === 'hire' ? { k: 'hire' } : k[0] === 'd' ? { k: 'driver', id: Number(k.slice(1)) } : { k: 'unit', uid: Number(k.slice(1)) });
    this.parts.board.render(true);
    return true;
  }
}

function wrap(cls: string, el: HTMLElement): HTMLElement {
  const s = document.createElement('section');
  s.className = cls;
  s.append(el);
  return s;
}

export { FleetBoard };
