import { cargoById } from '../cargoTypes';
import { chainsShown } from './shown';
import type { Building } from '../../world/tiles';
import { gradeOf } from '../hqGrade';
import type { Plants } from './plants';
import { CHAINS, CHAIN_NAME, hoursOf, pedigreeMul, recipesOf, takersOf } from './recipes';

/**
 * The plant block on a deed card (docs/supplychains.html, "The card and the bar"), shared by the inspector and the
 * HQ window's Estate pane through deedCardHtml. Owned: what it makes from what, the bins, the run's bar, the kerb,
 * the Set chips and its numbers. For sale: one line on what it would make, so the chain is part of the buying.
 */

const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
const icon = (id: string) => cargoById(id)?.icon ?? '📦';
const name = (id: string) => cargoById(id)?.name ?? id;
/** Game hours as the card says them: "1h 10m", "40m". */
export function hoursText(h: number): string {
  const m = Math.max(0, Math.round(h * 60));
  return m >= 60 ? `${Math.floor(m / 60)}h${m % 60 ? ` ${m % 60}m` : ''}` : `${m}m`;
}

/** One recipe as a sentence of icons: "📜 + 🧵 → 📚". */
function recipeLine(takes: { ids: string[]; n: number }[], makes: string[]): string {
  const ins = takes.map((s) => `${s.n > 1 ? `${s.n}×` : ''}${s.ids.map(icon).join('/')}`).join(' + ');
  return `${ins ? `${ins} → ` : ''}${makes.map(icon).join(' ')}`;
}

export function plantCardHtml(plants: Plants | undefined, key: string, b: Building, owned: boolean): string {
  const rs = recipesOf(b.kind);
  if (!plants || !rs.length || key.includes('#p') || !chainsShown()) return '';
  if (!owned) {
    const r = rs[0];
    const h = hoursOf(r, gradeOf(b).grade, false);
    const what = r.takes.length ? `turns ${recipeLine(r.takes, r.makes.map((m) => m.id))}` : `makes ${r.makes.map((m) => icon(m.id)).join(' ')}`;
    return `<div class="plant ask"><b>🔧</b> Owned, it ${what} every ${hoursText(h)} <small>${esc(CHAIN_NAME[r.chain] ?? '')}</small></div>`;
  }
  const v = plants.view(key);
  if (!v) return '';
  let html = `<div class="plant"><div class="ph"><b>🔧 ${v.base ? 'Makes' : 'Turns'}</b><small>${esc(v.chain)}</small></div>`;
  html += v.recipes.map((r) => `<div class="pr">${recipeLine(r.takes, r.makes.map((m) => m.id))}<small>${hoursText(hoursOf(r, gradeOf(b).grade, !!v.set))}</small></div>`).join('');
  // the bins, one row a slot, for every recipe with inputs (a slot shared by two recipes once), each with Fetch
  const fetching = plants.fetchers?.(key) ?? [];
  const seen = new Set<string>();
  for (const slots of v.slots) for (const s of slots) {
    const k = s.ids.join('/');
    if (seen.has(k)) continue;
    seen.add(k);
    const pct = Math.min(100, (s.have / Math.max(1, s.cap)) * 100);
    const on = fetching.some((f) => f.ids.join('/') === k);
    const btn = plants.fetch ? `<button type="button" class="fetch${on ? ' on' : ''}" data-act="plantfetch:${esc(k)}">${on ? 'Stop' : 'Fetch'}</button>` : '';
    html += `<div class="bin${s.have < s.n ? ' short' : ''}"><span>${s.ids.map(icon).join('/')} ${esc(s.ids.map(name).join(' or '))}</span><b>${s.have} / ${s.cap}${btn}</b><div class="bar"><i style="width:${pct.toFixed(0)}%"></i></div></div>`;
  }
  // the run in hand (or the base clock), else why it waits
  if (v.run && !v.waiting) {
    const out = v.run.out ? `${icon(v.run.out)} ${esc(name(v.run.out))}` : 'next load';
    const ped = v.run.steps ? ` · made by you, ${v.run.steps} step${v.run.steps === 1 ? '' : 's'} ×${pedigreeMul(v.run.steps).toFixed(1)}` : '';
    html += `<div class="run"><span>▶ ${out}${ped}</span><b>${hoursText(v.run.left)}</b><div class="bar"><i style="width:${(v.run.done * 100).toFixed(0)}%"></i></div></div>`;
  } else if (v.waiting) html += `<div class="run wait"><span>${esc(v.derelict ? 'Makes nothing while it is boarded up' : v.waiting)}</span></div>`;
  if (fetching.length) html += `<div class="pn">Fetching: ${fetching.map((f) => `${esc(f.name)} (${f.ids.map(icon).join('/')})`).join(', ')}</div>`;
  // the kerb
  if (v.stock.length) {
    const marks = v.stock.map((s) => `<span class="st${s.open ? ' open' : ''}" title="${esc(name(s.id))}${s.steps ? ` · ${s.steps} step${s.steps === 1 ? '' : 's'}` : ''}${s.open ? ' · open to the island' : s.placed ? ` · yours for ${hoursText(s.openIn)} more` : ' · put out when you’re back'}">${icon(s.id)}</span>`).join('');
    html += `<div class="kerb"><span>At the kerb</span>${marks}<small>${v.stock.length} of ${CHAINS.stock}</small></div>`;
  }
  // set: fix it to one of its outputs
  if (v.makes.length > 1) {
    html += `<div class="pset"><small>Make</small>`
      + `<button type="button" data-act="plantset:" class="${v.set ? '' : 'on'}">Any</button>`
      + v.makes.map((id) => `<button type="button" data-act="plantset:${id}" class="${v.set === id ? 'on' : ''}" title="${esc(name(id))}">${icon(id)}</button>`).join('')
      + `</div>`;
  }
  // where its goods go first: the fleet's own plants that take them
  const feeds = [...new Set(v.makes.flatMap((id) => takersOf(id)))];
  const nums = `${v.made} made · ${v.fed} fed in · $${v.fees.toLocaleString('en-US')} in maker’s fees${v.missed ? ` · ${v.missed} went stale` : ''}${v.opened ? ` · ${v.opened} opened to the island` : ''}`;
  html += `<div class="pn">${nums}${feeds.length ? `<br>Feeds ${feeds.length} kind${feeds.length === 1 ? '' : 's'} of plant: your own get it first` : ''}</div></div>`;
  return html;
}
