import { PLAY_ADDRESS } from '../recorder';
import { renderGallery, renderIssue, reviewLine } from './layout';
import type { Article, Issue } from './types';

/**
 * The newspaper on screen (docs/newspaper.html, Delivery): a full-screen card over the dimmed world, opened
 * from the notification that says it is out or from that notification in the log. Esc, a click on the dim or
 * the ✕ puts it away (Esc is read in main.ts's frame, as the HQ window's is, so the same press doesn't pause);
 * ← and → turn to the issues before and after it; the 📷 saves the front page as a PNG, fonts and all, with the
 * game's address in the corner, to post.
 */

interface PaperHost {
  /** Every issue kept, oldest first. */
  issues(): Issue[];
  /** A picture for an article, as a data URL, or null for the wordmark. */
  pic(i: Issue, a: Article): string | null;
  /** Called on open, so the other windows and tools can step aside. */
  opened(): void;
  /** An issue has been read. */
  read(i: Issue): void;
  /** The window has been put away. */
  closed?(): void;
}

/** The smallest a page is set to fit the window before it scrolls instead. */
const FIT_MIN = 0.82;

export class PaperWindow {
  readonly el = document.createElement('div');
  isOpen = false;
  private sheet = document.createElement('div');
  private nav = document.createElement('div');
  private n = 0;
  /** The page showing: 1 the front page, 2 the year in pictures. */
  private page = 1;
  private snapBtn = document.createElement('button');

  constructor(private host: PaperHost) {
    this.el.id = 'paper';
    this.el.hidden = true;
    this.sheet.className = 'pp-sheet';
    this.nav.className = 'pp-nav';
    const close = document.createElement('button');
    close.type = 'button';
    close.className = 'pp-close';
    close.title = 'Close (Esc)';
    close.textContent = '✕';
    close.addEventListener('click', (e) => { e.stopPropagation(); this.close(); });
    this.snapBtn.type = 'button';
    this.snapBtn.className = 'pp-snap';
    this.snapBtn.title = 'Save this front page as a picture';
    this.snapBtn.textContent = '📷';
    this.snapBtn.addEventListener('click', (e) => { e.stopPropagation(); void this.snap(); });
    this.el.append(this.sheet, this.nav, close, this.snapBtn);
    // a click on the dim round the paper puts it away
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    this.nav.addEventListener('click', (e) => {
      const b = (e.target as HTMLElement).closest<HTMLElement>('[data-go], [data-page]');
      if (!b) return;
      e.stopPropagation();
      if (b.dataset.page) { this.page = Number(b.dataset.page); this.render(); } else this.turn(Number(b.dataset.go));
    });
    window.addEventListener('keydown', (e) => {
      if (!this.isOpen) return;
      if (e.code === 'ArrowLeft') { this.turn(-1); e.preventDefault(); e.stopPropagation(); }
      else if (e.code === 'ArrowRight') { this.turn(1); e.preventDefault(); e.stopPropagation(); }
      else if (e.code === 'Tab') { this.flip(); e.preventDefault(); e.stopPropagation(); }
    }, true);
  }

  /** Open at an issue by number (the latest when none is given). */
  open(n?: number): void {
    const list = this.host.issues();
    if (!list.length) return;
    this.n = n !== undefined && list.some((i) => i.n === n) ? n : list[list.length - 1].n;
    this.page = 1;
    if (!this.isOpen) {
      this.isOpen = true;
      this.el.hidden = false;
      this.host.opened();
    }
    this.render();
  }

  close(): void {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.el.hidden = true;
    this.host.closed?.();
  }

  private turn(by: number): void {
    const list = this.host.issues();
    const k = list.findIndex((i) => i.n === this.n) + by;
    if (k < 0 || k >= list.length) return;
    this.n = list[k].n;
    this.page = 1;
    this.render();
  }

  /** Tab: the front page and the year in pictures, when the issue has one. */
  private flip(): void {
    const issue = this.host.issues().find((i) => i.n === this.n);
    if (!issue?.gallery?.length) return;
    this.page = this.page === 1 ? 2 : 1;
    this.render();
  }

  private render(): void {
    const list = this.host.issues();
    const k = list.findIndex((i) => i.n === this.n);
    const issue = list[k];
    if (!issue) { this.close(); return; }
    if (!issue.gallery?.length) this.page = 1;
    this.sheet.innerHTML = this.page === 2 ? renderGallery(issue) : renderIssue(issue, (a) => this.host.pic(issue, a));
    this.sheet.scrollTop = 0;
    this.fit();
    const pages = issue.gallery?.length
      ? `<span class="pp-pages"><button type="button" data-page="1" class="${this.page === 1 ? 'on' : ''}">Front page</button><button type="button" data-page="2" class="${this.page === 2 ? 'on' : ''}">The year in pictures · ${issue.gallery.length}</button><kbd>Tab</kbd></span>`
      : '';
    this.nav.innerHTML = list.length > 1
      ? `<button type="button" data-go="-1"${k <= 0 ? ' disabled' : ''}>← Earlier</button><span>${reviewLine(issue)} · issue ${k + 1} of ${list.length}</span>${pages}<button type="button" data-go="1"${k >= list.length - 1 ? ' disabled' : ''}>Later →</button>`
      : `<span>${reviewLine(issue)} · <kbd>Esc</kbd> to close</span>${pages}`;
    if (!issue.read) this.host.read(issue);
  }

  /** A page a little taller than the window is set a little smaller to fit (never below FIT_MIN); a much taller one scrolls. */
  private fit(): void {
    const page = this.sheet.querySelector<HTMLElement>('.pp-paper');
    if (!page) return;
    page.style.zoom = '';
    const k = this.sheet.clientHeight / Math.max(1, this.sheet.scrollHeight);
    if (k < 1 && k >= FIT_MIN) page.style.zoom = String(Math.max(FIT_MIN, Math.floor(k * 100) / 100));
  }

  /** The front page as a PNG: drawn through an SVG of the page with its stylesheet and fonts inlined, then saved. */
  async snap(): Promise<boolean> {
    const page = this.sheet.querySelector<HTMLElement>('.pp-paper');
    const issue = this.host.issues().find((i) => i.n === this.n);
    if (!page || !issue || this.snapBtn.disabled) return false;
    this.snapBtn.disabled = true;
    // drawn at its own size, whatever the window shrank it to
    const zoom = page.style.zoom;
    try {
      page.style.zoom = '';
      const blob = await pagePng(page);
      page.style.zoom = zoom;
      if (!blob) return false;
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = `${issue.paper.name} · ${reviewLine(issue)}.png`.replace(/[\\/:*?"<>|]/g, '');
      document.body.append(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 4000);
      return true;
    } catch {
      return false;
    } finally {
      page.style.zoom = zoom;
      this.snapBtn.disabled = false;
    }
  }
}

/** The paper's own faces as inlined @font-face rules (the latin set of each), made once. */
let fontRules: Promise<string> | null = null;
/** The faces the paper prints in, and their weights (null: the face's only one). */
const PAPER_FACES: [string, number | null][] = [['UnifrakturMaguntia', null], ['Playfair Display', 700], ['Playfair Display', 900], ['Fredoka', 700]];
/**
 * The game's own @font-face rules for those faces (src/fonts.ts, served with the game), their latin files read and
 * written in as data, so the saved picture carries its type with it.
 */
function fonts(): Promise<string> {
  fontRules ??= (async () => {
    try {
      const faces: CSSFontFaceRule[] = [];
      for (const sheet of Array.from(document.styleSheets)) {
        let rules: CSSRuleList;
        try { rules = sheet.cssRules; } catch { continue; }
        for (const r of Array.from(rules)) if (r instanceof CSSFontFaceRule) faces.push(r);
      }
      const want = faces.filter((r) => {
        const family = r.style.getPropertyValue('font-family').replace(/['"]/g, '').trim();
        const weight = r.style.getPropertyValue('font-weight').trim();
        return PAPER_FACES.some(([f, w]) => f === family && (w === null || String(w) === weight)) && /-latin-\d+-normal[^/)]*\.woff2/.test(r.style.getPropertyValue('src'));
      });
      const inlined = await Promise.all(want.map(async (r) => {
        const m = /url\(["']?([^"')]+\.woff2)["']?\)/.exec(r.style.getPropertyValue('src'));
        if (!m) return '';
        const url = new URL(m[1], r.parentStyleSheet?.href ?? location.href).href;
        const blob = await (await fetch(url)).blob();
        const data = await new Promise<string>((res, rej) => { const fr = new FileReader(); fr.onload = () => res(String(fr.result)); fr.onerror = rej; fr.readAsDataURL(blob); });
        return r.cssText.replace(/src:[^;]+;/, `src: url("${data}") format("woff2");`);
      }));
      return inlined.filter(Boolean).join(String.fromCharCode(10));
    } catch { return ''; }
  })();
  return fontRules;
}

/** The stylesheet rules the paper uses (everything under .pp-), as text. */
function paperCss(): string {
  const out: string[] = [];
  for (const sheet of Array.from(document.styleSheets)) {
    let rules: CSSRuleList;
    try { rules = sheet.cssRules; } catch { continue; } // a font sheet from another origin
    for (const r of Array.from(rules)) if (r.cssText.includes('.pp-') && !r.cssText.includes('#paper')) out.push(r.cssText);
  }
  return out.join(String.fromCharCode(10));
}

/** A front page drawn to a PNG at twice its size, the game's address on a strip under it. */
async function pagePng(page: HTMLElement): Promise<Blob | null> {
  const w = Math.ceil(page.offsetWidth), h = Math.ceil(page.offsetHeight);
  const node = page.cloneNode(true) as HTMLElement;
  const xhtml = new XMLSerializer().serializeToString(node);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><foreignObject x="0" y="0" width="${w}" height="${h}">`
    + `<div xmlns="http://www.w3.org/1999/xhtml" style="width:${w}px;margin:0"><style>${await fonts()} ${paperCss()}</style>${xhtml}</div></foreignObject></svg>`;
  const img = new Image();
  img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  await img.decode();
  // a strip of its own under the page for the game's address
  const k = 2, strip = 18, c = document.createElement('canvas');
  c.width = w * k; c.height = (h + strip) * k;
  const g = c.getContext('2d')!;
  g.scale(k, k);
  g.fillStyle = '#1a1208';
  g.fillRect(0, h, w, strip);
  g.drawImage(img, 0, 0, w, h);
  g.font = '600 10px "IBM Plex Sans", "Segoe UI", sans-serif';
  g.fillStyle = '#f1e9d2';
  g.textAlign = 'right';
  g.fillText(`TinyFleet · ${PLAY_ADDRESS}`, w - 10, h + 12.5);
  return new Promise((res) => c.toBlob((b) => res(b), 'image/png'));
}
