/**
 * Community, the game's side (docs/community.html). Online, everything another player built is a work
 * with their name on it: a road, each bridge, flyover or tunnel span in it, a chunk of earthworks, a
 * beaten track. Bridges carry a plaque in the builder's colours and earthworks a survey stake; clicking
 * a work (or its plaque) opens its card, where a heart can be left. Driving onto another player's work
 * offers the same heart on L. The tiles this game drives over on open ground are told to the server,
 * which counts passes; ground enough fleets have worn draws as a path and, at the last stage, becomes a
 * dirt track for everyone (world/paths.ts). And the World tab of Standings lists the most loved works.
 */

interface CommunityHost {
  scene: THREE.Scene;
  islands(): Islands | null;
  home(): World | null;
  veh(): VehicleState | null;
  def(): VehicleDef;
  /** Hired vehicles out working: where each is, for crossings. */
  movers(): { id: string; w: World; x: number; z: number }[];
  groupOf(w: World): THREE.Group | null;
  /** Tiles changed under the world's feet (a path worn in): their chunks drawn again. */
  redraw(w: World, tiles: number[]): void;
  announce(title: string, body: string, ms?: number): void;
  /** The camera to a point of the world (world tiles), opening the work's card once it is in memory. */
  fly(key: string, name: string, x: number, z: number): void;
  follow(pid: Pid, name: string): void;
  viewHq(key: string, name: string): void;
  /** In play, with nothing (a menu, a tool) over it. */
  playing(): boolean;
  /** My totals have changed: the achievements read them. */
  stats(s: CommunityStats): void;
  /** Another card is about to open (the inspector's): this one steps aside, and the other way about. */
  opened(): void;
}

/** One work in a cell in memory. */
export interface Work {
  key: string; id: string; cell: string; kind: WorkKind; by: Pid; at: number;
  /** Nodes for a road or span, lifts for earthworks, fleets for a track. */
  len: number;
  tiles: number[];
  w: World;
  /** Where its plaques or its stake stand, island-local: x, z, and the way it faces. */
  marks: [number, number, number][];
  /**
   * Where its name tag floats, island-local: over the middle of a bridge's deck (y its world height), or
   * over the first plaque of a tunnel and the stake of earthworks (y NaN: just above the ground there).
   */
  label?: [number, number, number];
}

/**
 * A project (the user, 5 Nov 2026): one builder's works near each other (shared/community.ts groupNear), told as one:
 * the lead (most hearts, then the biggest) carries the one name tag; the name is the first name among them, by hearts,
 * else the lead's; the hearts are all of theirs added up. A work alone is no project.
 */
export interface Project { keys: string[]; lead: string; name: string; h: number; hearted: boolean }

const esc = (s: string): string => s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]!);
const hex = (c: number): string => `#${(c & 0xffffff).toString(16).padStart(6, '0')}`;
const blankStats = (): CommunityStats => ({ loved: 0, uses: 0, blazed: 0, gave: 0, listed: 0, works: 0 });
const KIND_ICON: Record<WorkKind, string> = { road: '🛣️', bridge: '🌉', suspension: '🌉', tunnel: '🕳️', flyover: '🛤️', viaduct: '🌁', land: '⛏️', path: '👣', hq: '🏢',
  mountain: '🏔️', hill: '⛰️', lake: '🏞️', canal: '🚣', valley: '🏜️', reclaim: '🏝️' };
/** A work's name tag over an island, as laid out each frame (Community.layoutTags). */
interface Tag { x: number; y: number; z: number; key: string; aspect: number; sprite: THREE.Sprite; road: boolean; scale: number }

/** A name tag's height on screen, in pixels, at its nearest. */
const TAG_PX = 40;
/**
 * Name tags near what the camera is on, and only there: opaque within TAG_NEAR tiles, fading to TAG_FAINT and a
 * fifth smaller by TAG_FAR - TAG_OUT, gone by TAG_FAR. Shown from across the county they read as clutter, and at
 * full strength from afar they covered the very works they named.
 */
const TAG_NEAR = 12, TAG_FAR = 40, TAG_OUT = 6, TAG_FAINT = 0.35;
/** Pixels kept clear round each tag; one that would overlap a nearer tag waits, faded out, until it has room. */
const TAG_GAP = 6;
/** Tiles of head start a tag already showing has over one that isn't, so two at about the same distance don't take turns. */
const TAG_STICK = 4;
/** How fast a tag fades in or out, in opacity a second. */
const TAG_FADE = 4;

/** How strongly a tag this many tiles from the camera's focus shows, before any overlap. */
function tagAlpha(d: number): number {
  if (d <= TAG_NEAR) return 1;
  if (d >= TAG_FAR) return 0;
  const out = TAG_FAR - TAG_OUT;
  if (d <= out) return 1 - ((1 - TAG_FAINT) * (d - TAG_NEAR)) / (out - TAG_NEAR);
  return (TAG_FAINT * (TAG_FAR - d)) / TAG_OUT;
}
/** A tag's size this many tiles out, as a share of its nearest. */
const tagScale = (d: number): number => 1 - 0.2 * Math.min(1, Math.max(0, (d - TAG_NEAR) / (TAG_FAR - TAG_OUT - TAG_NEAR)));
/** How long the hearts prompt stays up, in seconds. */
const PROMPT_LIFE = 6;
const HIGHLIGHT = 0xffc83d;
/** A selected work's glow: its opacity swings between these, once every GLOW_PERIOD seconds. */
const GLOW_LO = 0.22, GLOW_HI = 0.55, GLOW_PERIOD = 1.6;
/** How far past a work's tiles, in tiles, a triangle's middle may stand and still glow with it. */
const GLOW_SLACK = 0.2;

/** Away news not yet seen, kept on this device by player. */
const AWAY_STORE = 'tinyfleet-away:';
function readAway(pid: Pid): AwayNews | null {
  try { return JSON.parse(localStorage.getItem(AWAY_STORE + pid) ?? 'null') as AwayNews | null; } catch { return null; }
}
function writeAway(pid: Pid, a: AwayNews | null): void {
  try { if (a) localStorage.setItem(AWAY_STORE + pid, JSON.stringify(a)); else localStorage.removeItem(AWAY_STORE + pid); } catch { /* shown this once only */ }
}
/** Two lots of away news as one: the counts added, the works' hearts added and their givers joined. */
function mergeAway(a: AwayNews | null, b: AwayNews | null): AwayNews | null {
  if (!a || !b) return a ?? b;
  const items = [...(a.items ?? []).map((it) => ({ ...it, from: [...it.from] }))];
  for (const it of b.items ?? []) {
    const had = items.find((x) => x.k === it.k);
    if (!had) { items.push({ ...it, from: [...it.from] }); continue; }
    had.h += it.h;
    if (it.name) had.name = it.name;
    for (const f of it.from) if (!had.from.includes(f) && had.from.length < 3) had.from.push(f);
  }
  return { hearts: a.hearts + b.hearts, uses: a.uses + b.uses, listed: a.listed + b.listed, tracks: a.tracks + b.tracks, wearing: (a.wearing ?? 0) + (b.wearing ?? 0), items };
}

/** The kind a key's id implies, for a work not in memory. */
const kindOfId = (id: string): WorkKind => (id.startsWith('F') ? 'land' : id.startsWith('W') ? 'path' : id.startsWith('b') ? 'hq' : id.includes('.') ? 'bridge' : 'road');

export class Community {
  /** Works' numbers as the server last said, by key. */
  private rows = new Map<string, WorkRow>();
  /** Who moved each chunk's ground, by cell. */
  private landBy = new Map<string, Record<string, [Pid, number][]>>();
  /** Each cell's landforms as the server names them (F3), by cell. */
  private features = new Map<string, Record<string, FeatureRow>>();
  /** Each cell's paths: chunk → [passes, fleets], as delta.paths carries them; and who wore each chunk. */
  private paths = new Map<string, { block: PathBlock; by: Record<string, Pid[]> }>();
  /** A version per cell, bumped when its paths or earthworks credit change, so what is drawn from them is drawn again. */
  private ver = new Map<string, number>();
  private rowsVer = 0;
  /** Works I have hearted, by key. */
  hearts = new Set<string>();
  stats: CommunityStats = blankStats();
  private away: AwayNews | null = null;
  /** The World tab's lists, as last sent. */
  lists: { loved: WorkLine[]; busy: WorkLine[]; fresh: WorkLine[] } | null = null;
  onLists: () => void = () => {};
  private listTab: 'loved' | 'busy' | 'fresh' | 'near' | 'friends' = 'loved';
  /** The players whose works the By friends list shows (the social window sets it). */
  friendIds: () => Set<string> = () => new Set();

  private index = new WeakMap<World, { sig: string; works: Map<string, Work>; at: Map<number, Work>; all: Map<number, Work[]> }>();
  /** What is drawn over each island: plaques and stakes, and the paths. */
  private drawn = new Map<World, {
    plaques: THREE.Group; sig: string; paths: THREE.Group; psig: string;
    marks: { x: number; y: number; z: number; key: string }[];
    /**
     * Name tags: where each stands (its bottom middle, in world units), its width over its height, its sprite, whether
     * it is a road's street sign (drawn smaller), and the size it was last laid out at (layoutTags), for a click.
     */
    tags: Tag[];
  }>();
  /** Bumped when my hearts change, so the tags' ♡ fill in. */
  private heartsVer = 0;
  /** The overview is up: its pins say it, so the tags step aside. */
  private inOverview = false;
  /**
   * A screen-sized sprite's scale is multiplied by the lens (projection [1][1], large for this narrow
   * tilt-shift camera), so the scale that makes a tag TAG_PX tall is worked out from the camera each frame.
   */
  private tagUnit = 0.01;

  // the card
  private panel = document.createElement('div');
  private head = document.createElement('header');
  private body = document.createElement('div');
  private bodyHtml = '';
  private selected: Work | null = null;
  private trace: THREE.Mesh | null = null;
  /** Seconds the selected work has been glowing, for its pulse. */
  private traceT = 0;
  private naming = false;
  /** Typing a name to suggest for another player's work (docs/marks.html). */
  private suggesting = false;
  private cardT = 0;
  // the hearts prompt
  private prompt = document.createElement('div');
  private promptKey = '';
  private promptT = 0;
  private prompted = new Set<string>();
  // what this game tells the server
  private trod = new Map<string, Set<number>>();
  private used = new Set<string>();
  private crossing = new Map<string, { key: string; seen: Set<number>; len: number }>();
  private treadT = COMMUNITY.treadEvery;
  private sampleT = 0;

  private mats = new Map<number, THREE.MeshLambertMaterial>();
  private postGeo = new THREE.BoxGeometry(0.05, 0.42, 0.05).translate(0, 0.21, 0);
  private boardGeo = new THREE.BoxGeometry(0.34, 0.2, 0.03);
  private stripeGeo = new THREE.BoxGeometry(0.34, 0.05, 0.035);
  private pennantGeo: THREE.BufferGeometry;
  private stoneGeo = new THREE.IcosahedronGeometry(1, 0);
  private sprites = new Map<string, THREE.SpriteMaterial>();
  private ray = new THREE.Vector3();

  constructor(private online: Online, private host: CommunityHost) {
    // a development build only: window.community, to try the tags' layout from the console (testTags)
    if (import.meta.env.DEV) (window as unknown as { community?: Community }).community = this;
    this.panel.id = 'work-card';
    this.panel.className = 'hud chip';
    this.panel.hidden = true;
    const close = document.createElement('button');
    close.className = 'x';
    close.type = 'button';
    close.title = 'Close';
    close.textContent = '×';
    close.addEventListener('click', () => this.close());
    this.panel.append(close, this.head, this.body);
    document.body.append(this.panel);
    // on pointerdown: the card is drawn again as its numbers move, and a click could land between two
    this.body.addEventListener('pointerdown', (e) => {
      const t = e.target as HTMLElement;
      if (t instanceof HTMLInputElement) return;
      const b = t.closest('button[data-act]') as HTMLElement | null;
      if (!b) return;
      e.preventDefault();
      this.act(b.dataset.act!);
    });
    this.body.addEventListener('keydown', (e) => {
      const t = e.target as HTMLElement;
      if (!(t instanceof HTMLInputElement)) return;
      e.stopPropagation();
      if (e.key === 'Enter') { this.act(this.suggesting ? 'ssave' : 'save'); e.preventDefault(); }
      if (e.key === 'Escape') { this.naming = false; this.suggesting = false; this.render(true); e.preventDefault(); }
    });
    this.body.addEventListener('keyup', (e) => { if (e.target instanceof HTMLInputElement) e.stopPropagation(); });
    this.prompt.id = 'heart-prompt';
    this.prompt.className = 'hud chip';
    this.prompt.hidden = true;
    document.body.append(this.prompt);

    // a pennant: a flat triangle off the top of the pole
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute([0, 0.62, 0, 0, 0.44, 0, 0.26, 0.53, 0], 3));
    g.computeVertexNormals();
    this.pennantGeo = g;
  }

  /** Online and in a world. */
  private get on(): boolean { return this.online.active && !!this.online.me; }
  private get me(): Pid { return this.online.me?.id ?? ''; }
  get open(): boolean { return !!this.selected; }

  // ---- what the server says --------------------------------------------------------------------------

  /** Signed in: my hearts, my totals, and my works' news since last time (told once the world is up). */
  welcome(w: Welcome): void {
    this.reset();
    const c = w.community;
    if (!c) return;
    this.hearts = new Set(c.hearts);
    this.heartsVer++;
    this.stats = { ...blankStats(), ...c.s };
    // the server tells the away news once; it is kept on this device until its card has been seen, so a
    // reload or a dropped connection before then doesn't lose it
    this.away = mergeAway(readAway(w.you.id), c.away);
    writeAway(w.you.id, this.away);
    this.host.stats(this.stats);
  }

  reset(): void {
    this.rows.clear();
    this.landBy.clear();
    this.features.clear();
    this.paths.clear();
    this.ver.clear();
    this.hearts.clear();
    this.used.clear();
    this.trod.clear();
    this.crossing.clear();
    this.prompted.clear();
    this.lists = null;
    this.close();
    for (const d of this.drawn.values()) this.undraw(d);
    this.drawn.clear();
  }

  /** The world is up: what happened while away. */
  ready(): void {
    // the achievements count only once play has begun
    this.host.stats(this.stats);
    const a = this.away;
    this.away = null;
    if (!a) return;
    // the paper hears it too (docs/newspaper.html): the hearts as one tally, the rest as they stand
    {
      const top = [...(a.items ?? [])].sort((x, y) => y.h - x.h)[0];
      const tw = top ? this.find(top.k) : null;
      const work = top ? top.name ?? (tw ? this.title(tw) : '') : '';
      if (a.hearts) press.write({ k: 'hearts', who: 'you', f: { n: a.hearts, by: (a.items ?? []).flatMap((it) => it.from).slice(0, 6).join(', '), work } });
      if (a.uses >= 2) press.write({ k: 'crossings', who: 'you', f: { n: a.uses } });
      if (a.listed) press.write({ k: 'listed', ...(a.listed === 1 ? { v: 'one' } : {}), who: 'you', f: { n: a.listed } });
      if (a.tracks) press.write({ k: 'tracks', ...(a.tracks === 1 ? { v: 'one' } : {}), who: 'you', f: { n: a.tracks } });
    }
    // the hearts first, work by work and who left them; then the rest of the news on a card of its own
    const cards: [string, string][] = [];
    if (a.hearts) {
      const items = [...(a.items ?? [])].sort((x, y) => y.h - x.h);
      const named = items.slice(0, 3).map((it) => {
        const wk = this.find(it.k);
        const what = it.name ?? (wk ? this.title(wk) : `Your ${WORK_LABEL[it.kind].toLowerCase()}`);
        const more = it.h > it.from.length ? ` and ${it.h - it.from.length} more` : '';
        return `${what} ♥ ${it.h}${it.from.length ? ` from ${it.from.join(', ')}${more}` : ''}`;
      });
      if (items.length > 3) named.push(`and ${items.length - 3} more of your works`);
      cards.push([`♥ ${a.hearts} heart${a.hearts === 1 ? '' : 's'} while you were away`, named.length ? named.join(' · ') : 'Other players left hearts on your works']);
    }
    const bits: string[] = [];
    if (a.uses) bits.push(`${a.uses.toLocaleString('en-US')} crossing${a.uses === 1 ? '' : 's'} of your works by other fleets`);
    if (a.listed) bits.push(`${a.listed} work${a.listed === 1 ? '' : 's'} listed`);
    if (a.wearing) bits.push(`${a.wearing} line${a.wearing === 1 ? '' : 's'} of yours wearing in as others follow`);
    if (a.tracks) bits.push(`${a.tracks} shortcut${a.tracks === 1 ? '' : 's'} of yours worn into a beaten track`);
    if (bits.length) cards.push(['While you were away', bits.join(' · ')]);
    const me = this.me;
    cards.forEach(([title, body], n) => setTimeout(() => {
      if (!this.on || this.me !== me) return;
      this.host.announce(title, body, 9000);
      // seen: no need to keep it any more
      if (n === cards.length - 1) writeAway(me, null);
    }, 7000 + n * 9500));
  }

  /** A cell's shared state is being laid into the game: its works' numbers, who dug it, and its paths. */
  cell(k: string, doc: CellDoc, w: World | null, isles: Islands): void {
    for (const key of [...this.rows.keys()]) if (key.startsWith(`${k}#`)) this.rows.delete(key);
    for (const [id, row] of Object.entries(doc.social ?? {})) this.rows.set(`${k}#${id}`, row);
    this.landBy.set(k, { ...(doc.landBy ?? {}) });
    this.features.set(k, { ...(doc.features ?? {}) });
    const block: PathBlock = {};
    for (const [ch, s] of Object.entries(doc.paths ?? {})) block[ch] = [s, doc.pathsBy?.[ch]?.length ?? 0];
    this.paths.set(k, { block, by: { ...(doc.pathsBy ?? {}) } });
    this.bump(k);
    this.rowsVer++;
    const [cx, cz] = cellOfKey(k);
    // a cell still to be built takes them with its delta; one already built has them laid over it now
    const d = isles.delta(cx, cz);
    if (Object.keys(block).length) d.paths = block; else delete d.paths;
    if (w) { const tiles = applyPaths(w, block); if (tiles.length) this.host.redraw(w, tiles); }
  }

  /** A cell has left memory. */
  forget(k: string): void {
    for (const key of [...this.rows.keys()]) if (key.startsWith(`${k}#`)) this.rows.delete(key);
    this.landBy.delete(k);
    this.features.delete(k);
    this.paths.delete(k);
    this.ver.delete(k);
  }

  private bump(k: string): void { this.ver.set(k, (this.ver.get(k) ?? 0) + 1); }

  /** A message from the server, if it is one of community's. */
  got(m: ServerMsg): boolean {
    switch (m.t) {
      case 'social': {
        // a heart on a work of mine, as it comes: the paper's tally (docs/newspaper.html)
        if (m.on && m.from && m.from.id !== this.me) {
          const wk = this.find(m.k);
          if (wk && wk.by === this.me) press.write({ k: 'hearts', who: 'you', f: { by: m.from.name, work: m.row?.name ?? this.title(wk) } });
        }
        if (m.row) this.rows.set(m.k, m.row); else this.rows.delete(m.k);
        this.rowsVer++;
        if (this.selected?.key === m.k) this.render(true);
        return true;
      }
      case 'paths': {
        const p = this.paths.get(m.c);
        if (!p) return true;
        for (const [ch, s] of Object.entries(m.chunks)) { p.block[ch] = [s, m.by[ch]?.length ?? 0]; p.by[ch] = m.by[ch] ?? []; }
        this.bump(m.c);
        const isles = this.host.islands();
        const [cx, cz] = cellOfKey(m.c);
        if (isles) {
          isles.delta(cx, cz).paths = p.block;
          const w = isles.at(cx, cz);
          if (w) { const tiles = applyPaths(w, p.block, Object.keys(m.chunks)); if (tiles.length) this.host.redraw(w, tiles); }
        }
        return true;
      }
      case 'landBy': {
        const had = this.landBy.get(m.c);
        if (!had) return true;
        Object.assign(had, m.rows);
        if (m.features) this.features.set(m.c, m.features);
        this.bump(m.c);
        return true;
      }
      case 'nice': this.nice(m); return true;
      case 'cstats': {
        this.stats = { ...blankStats(), ...m.s };
        if (m.hearts) { this.hearts = new Set(m.hearts); this.heartsVer++; }
        this.host.stats(this.stats);
        if (this.selected) this.render(true);
        return true;
      }
      case 'works': this.lists = { loved: m.loved, busy: m.busy, fresh: m.fresh }; this.onLists(); return true;
      default: return false;
    }
  }

  private nice(m: Extract<ServerMsg, { t: 'nice' }>): void {
    const work = this.find(m.k);
    // mid-sentence: "on your road", not "on Your road"
    const what = m.name ?? (work ? this.title(work).replace(/^Your /, 'your ') : `your ${WORK_LABEL[kindOfId(m.k.split('#')[1] ?? '')].toLowerCase()}`);
    const from = m.from ? (m.from.brand?.name ?? m.from.name) : '';
    if (m.what === 'heart') this.host.announce(`♥ ${from} left a heart`, `On ${what} · thank you for building it`, 6000);
    else if (m.what === 'listed') this.host.announce('Listed', `${what} has ${m.n ?? COMMUNITY.listedAt} hearts: only you can bulldoze it now`, 8000);
    else if (m.what === 'track') this.host.announce('A shortcut of yours is a beaten track', `${m.n ?? 5} fleets have worn in the way you first drove: it is a dirt track for everyone now`, 8000);
    else if (m.what === 'wearing') this.host.announce('👣 Your line is wearing in', `${m.n ?? 3} fleets have followed the way you drove: a few more and it’s a beaten track with your name on it`, 7000);
    else if (m.what === 'uses') this.host.announce(`${(m.n ?? 0).toLocaleString('en-US')} crossings`, `Other fleets have crossed ${what} ${(m.n ?? 0).toLocaleString('en-US')} times`, 6000);
  }

  // ---- the works in memory ----------------------------------------------------------------------------

  private worlds(): World[] {
    const isles = this.host.islands();
    return isles ? [...isles.live.values()] : [];
  }

  /** The projects among the works in memory, by each member's key; worked out again when the works, rows or hearts move. */
  private projCache: { sig: string; of: Map<string, Project>; at: number; groups: string } | null = null;
  /** Bumped whenever the projects in memory group differently: the name tags are drawn again. */
  private projVer = 0;
  project(key: string): Project | null {
    // asked for every work as tags and pins are drawn: looked at again at most twice a second
    const now = performance.now();
    if (this.projCache && now - this.projCache.at < 500) return this.projCache.of.get(key) ?? null;
    const worlds = this.worlds();
    const sig = `${this.rowsVer}|${this.heartsVer}|${this.online.people.size}|${worlds.map((w) => `${w.cx},${w.cz}:${this.worksOf(w) && this.index.get(w)?.sig}`).join(';')}`;
    if (this.projCache?.sig !== sig) {
      const items: Work[] = [];
      // worn paths are many fleets' and an HQ is a building: neither joins a project
      for (const w of worlds) for (const wk of this.worksOf(w).works.values()) if (wk.kind !== 'path' && wk.kind !== 'hq' && wk.tiles.length) items.push(wk);
      const box = (wk: Work): [number, number, number, number] => {
        let x0 = Infinity, z0 = Infinity, x1 = -Infinity, z1 = -Infinity;
        for (const t of wk.tiles) { const x = wk.w.ox + (t % N), z = wk.w.oz + Math.floor(t / N); if (x < x0) x0 = x; if (x > x1) x1 = x; if (z < z0) z0 = z; if (z > z1) z1 = z; }
        return [x0, z0, x1, z1];
      };
      const of = new Map<string, Project>();
      for (const g of groupNear(items, (wk) => wk.by, box)) {
        if (g.length < 2) continue;
        const ws = g.map((i) => items[i]).sort((a, b) => this.row(b.key).h - this.row(a.key).h || b.len - a.len);
        const named = ws.find((wk) => this.row(wk.key).name);
        const p: Project = {
          keys: ws.map((wk) => wk.key), lead: ws[0].key, name: named ? this.row(named.key).name! : this.title(ws[0]),
          h: ws.reduce((s, wk) => s + this.row(wk.key).h, 0), hearted: ws.some((wk) => this.hearts.has(wk.key)),
        };
        for (const wk of ws) of.set(wk.key, p);
      }
      const groups = [...new Set(of.values())].map((p) => `${p.lead}:${p.keys.length}:${p.h}:${p.name}`).sort().join('|');
      if (groups !== this.projCache?.groups) this.projVer++;
      this.projCache = { sig, of, at: now, groups };
    }
    this.projCache.at = now;
    return this.projCache.of.get(key) ?? null;
  }

  /** The works on an island, worked out again whenever its edits, roads, earthworks credit or paths move. */
  worksOf(w: World): { works: Map<string, Work>; at: Map<number, Work>; all: Map<number, Work[]> } {
    const k = cellKey(w.cx, w.cz);
    const d = this.host.islands()?.delta(w.cx, w.cz);
    const sig = `${d?.edits.length ?? 0}|${w.roadStamp}|${this.ver.get(k) ?? 0}|${this.landId(d?.land)}`;
    const had = this.index.get(w);
    if (had && had.sig === sig) return had;
    // `at`: the one work a click on a tile picks (a span over its road); `all`: every road and span on it, for crossings
    const works = new Map<string, Work>(), at = new Map<number, Work>(), all = new Map<number, Work[]>();
    const put = (wk: Work, claim: boolean) => {
      if (!wk.tiles.length) return;
      works.set(wk.key, wk);
      if (claim) for (const t of wk.tiles) { at.set(t, wk); const a = all.get(t); if (a) a.push(wk); else all.set(t, [wk]); }
    };
    const nodeAt = (n: number, wide: Wide): [number, number] => (wide === true ? [n % N, Math.floor(n / N)] : [(n % N) + 0.5, Math.floor(n / N) + 0.5]);
    for (const raw of d?.edits ?? []) {
      const e = raw as Edit & { by?: string; at?: number };
      if (e.k !== 'road' || e.g || !e.n?.length) continue;
      const by = e.by ?? this.me;
      const wide = shapeOf(e.t as RoadType);
      const tilesOf = (nodes: number[]) => [...new Set(nodes.flatMap((n) => nodeTiles(n, wide)))].filter((t) => t >= 0 && t < N * N && w.road[t] > 0);
      const id = roadWorkId(e.n);
      put({ key: `${k}#${id}`, id, cell: k, kind: 'road', by, at: e.at ?? 0, len: e.n.length, tiles: tilesOf(e.n), w, marks: [] }, true);
      (e.b ?? []).forEach((b, j) => {
        const [from, to, h0, h1, flags = 0, peak = 0] = b;
        if (!(to > from)) return;
        const [ax, az] = nodeAt(e.n[from], wide), [bx, bz] = nodeAt(e.n[to], wide);
        const yaw = Math.atan2(bx - ax, bz - az);
        // a plaque at each end, a little to the side of the road
        const side = wide === 'tri' ? 1.8 : wide ? 1.3 : 0.75;
        const px = Math.cos(yaw) * side, pz = -Math.sin(yaw) * side;
        const marks: [number, number, number][] = [[ax + px, az + pz, yaw], [bx - px, bz - pz, yaw + Math.PI]];
        // the name tag over the deck's middle, at its highest; a tunnel's over its first portal
        const label: [number, number, number] = flags & 8 ? [marks[0][0], NaN, marks[0][1]]
          : [(ax + bx) / 2, Math.max(h0, h1, flags & 4 ? peak : 0), (az + bz) / 2];
        put({ key: `${k}#${id}.${j}`, id: `${id}.${j}`, cell: k, kind: spanKind(flags), by, at: e.at ?? 0, len: to - from, tiles: tilesOf(e.n.slice(from, to + 1)), w, marks, label }, true);
      });
    }
    // landforms: the server names them (F3) and says what they are; their tiles are read here from the same
    // earthworks, each patch found by the tiles the server knows it by. A cairn and the name tag on the summit
    const feats = this.features.get(k);
    if (feats && Object.keys(feats).length) {
      const comps = this.landformsOf(d?.land as Record<string, string> | undefined);
      const compOf = new Map<number, number>();
      comps.forEach((c, n) => { for (const t of c.tiles) compOf.set(t, n); });
      for (const [id, f] of Object.entries(feats)) {
        const votes = new Map<number, number>();
        for (const t of f.s) { const n = compOf.get(t); if (n !== undefined) votes.set(n, (votes.get(n) ?? 0) + 1); }
        let best = -1, most = 0;
        for (const [n, v] of votes) if (v > most) { best = n; most = v; }
        const comp = comps[best];
        if (!comp) continue;
        const top = comp.tiles.includes(f.top) ? f.top : comp.top;
        const tx = (top % N) + 0.5, tz = Math.floor(top / N) + 0.5;
        const wk: Work = { key: `${k}#${id}`, id, cell: k, kind: f.kind, by: f.by, at: 0, len: f.lifts, tiles: comp.tiles, w, marks: [[tx, tz, 0]], label: [tx, NaN, tz] };
        works.set(wk.key, wk);
        for (const t of comp.tiles) if (!at.has(t)) at.set(t, wk);
      }
    }
    // beaten tracks: a chunk with a stage-3 tile, credited to the first fleet that wore it
    const p = this.paths.get(k);
    if (p) {
      const stages = pathStages(p.block);
      const byChunk = new Map<number, number[]>();
      for (const [i, s] of stages) if (s >= 2) { const c = chunkOfTile(i); const a = byChunk.get(c); if (a) a.push(i); else byChunk.set(c, [i]); }
      for (const [ch, tiles] of byChunk) {
        if (!tiles.some((i) => stages.get(i) === 3)) continue;
        const by = p.by[String(ch)] ?? [];
        if (!by.length) continue;
        // its name tag over the beaten tile nearest the middle of the worn ground
        const beaten = tiles.filter((i) => stages.get(i) === 3);
        const mx = beaten.reduce((s, i) => s + (i % N), 0) / beaten.length, mz = beaten.reduce((s, i) => s + Math.floor(i / N), 0) / beaten.length;
        const mid = beaten.reduce((b, i) => (Math.hypot((i % N) - mx, Math.floor(i / N) - mz) < Math.hypot((b % N) - mx, Math.floor(b / N) - mz) ? i : b), beaten[0]);
        // a cairn beside the track's middle, in its trailblazer's colours, and the name tag over it (docs/marks.html)
        const lx = (mid % N) + 0.5, lz = Math.floor(mid / N) + 0.5;
        const wk: Work = { key: `${k}#W${ch}`, id: `W${ch}`, cell: k, kind: 'path', by: by[0], at: 0, len: by.length, tiles, w, marks: [[lx + 0.6, lz + 0.6, 0]], label: [lx + 0.6, NaN, lz + 0.6] };
        works.set(wk.key, wk);
        for (const t of tiles) if (!at.has(t)) at.set(t, wk);
      }
    }
    const out = { sig, works, at, all };
    this.index.set(w, out);
    return out;
  }

  /** Each earthworks block's landforms, read once: a block is replaced, never changed, when the ground moves. */
  private landforms = new WeakMap<object, LandFeature[]>();
  private landIds = new WeakMap<object, number>();
  private landSeq = 0;
  private landformsOf(land: Record<string, string> | undefined): LandFeature[] {
    if (!land) return [];
    let f = this.landforms.get(land);
    if (!f) this.landforms.set(land, (f = landFeatures(land)));
    return f;
  }
  private landId(land: object | undefined): number {
    if (!land) return 0;
    let n = this.landIds.get(land);
    if (n === undefined) this.landIds.set(land, (n = ++this.landSeq));
    return n;
  }

  /** A work by key, if its cell is in memory. */
  find(key: string): Work | null {
    const m = WORK_KEY.exec(key);
    if (!m) return null;
    const [cx, cz] = cellOfKey(m[1]);
    const w = this.host.islands()?.at(cx, cz);
    return w ? this.worksOf(w).works.get(key) ?? null : null;
  }

  private row(key: string): WorkRow { return this.rows.get(key) ?? { h: 0, u: 0, f: 0 }; }
  private listed(key: string): boolean { return !!this.rows.get(key)?.l || !!this.rows.get(key.split('.')[0])?.l; }

  /** What a work is called: its builder's name for it, or theirs and its kind. */
  title(wk: Work): string {
    const name = this.row(wk.key).name;
    if (name) return name;
    const whose = wk.by === this.me ? 'Your' : `${this.online.fleetName(wk.by)}’s`;
    // a beaten track is its trailblazer's cut until it has a name
    return `${whose} ${wk.kind === 'path' ? 'Cut' : WORK_LABEL[wk.kind].toLowerCase()}`;
  }

  /**
   * The bulldozer's question about a tile: is it part of a work other players have listed? Then only its
   * builder may clear it (the server says no as well, whatever this game thinks).
   */
  barred(w: World, tile: number): string | null {
    if (!this.on) return null;
    for (const wk of this.worksOf(w).works.values()) {
      if (wk.by === this.me || isGround(wk.kind) || !wk.tiles.includes(tile) || !this.listed(wk.key)) continue;
      return `${this.title(wk)} is listed: only ${this.online.fleetName(wk.by)} can clear it`;
    }
    return null;
  }

  // ---- the card ---------------------------------------------------------------------------------------

  /** A click on the world the inspector didn't take: a plaque, a stake, or a work's ground. */
  click(mx: number, my: number, camera: THREE.PerspectiveCamera): boolean {
    if (!this.on) return false;
    let best: Work | null = null, bestD = Infinity;
    const H = window.innerHeight;
    // name tags first: a click anywhere on one
    for (const d of this.inOverview ? [] : this.drawn.values()) {
      for (const t of d.tags) {
        if (!t.sprite.visible || t.sprite.material.opacity < 0.3) continue;
        this.ray.set(t.x, t.y, t.z).project(camera);
        if (this.ray.z > 1) continue;
        const px = ((this.ray.x + 1) / 2) * window.innerWidth, py = ((1 - this.ray.y) / 2) * H;
        const tall = TAG_PX * t.scale * (t.road ? 0.8 : 1), half = (tall * t.aspect) / 2;
        if (Math.abs(mx - px) <= half && my <= py && my >= py - tall) { const wk = this.find(t.key); if (wk) { best = wk; bestD = 0; } }
      }
    }
    // plaques and stakes, by how near they are on screen
    for (const d of best ? [] : this.drawn.values()) {
      for (const m of d.marks) {
        this.ray.set(m.x, m.y + 0.3, m.z).project(camera);
        if (this.ray.z > 1) continue;
        const px = ((this.ray.x + 1) / 2) * window.innerWidth, py = ((1 - this.ray.y) / 2) * window.innerHeight;
        const dd = Math.hypot(px - mx, py - my);
        if (dd < 18 && dd < bestD) { const wk = this.find(m.key); if (wk) { best = wk; bestD = dd; } }
      }
    }
    if (!best) {
      // the ground under the pointer, on whichever island it falls
      let near = Infinity;
      for (const w of this.worlds()) {
        const p = pickGround(w, camera, mx, my, w.ox, w.oz);
        if (!p) continue;
        const tx = Math.floor(p.x), tz = Math.floor(p.z);
        if (!inB(tx, tz)) continue;
        const dist = camera.position.distanceTo(new THREE.Vector3(p.x + w.ox, p.y, p.z + w.oz));
        if (dist >= near) continue;
        near = dist;
        best = this.worksOf(w).at.get(idx(tx, tz)) ?? null;
      }
    }
    if (!best) { this.close(); return false; }
    this.select(best);
    return true;
  }

  select(wk: Work): void {
    this.host.opened();
    this.selected = wk;
    this.naming = false;
    this.suggesting = false;
    this.panel.hidden = false;
    this.drawTrace(wk);
    this.render(true);
  }

  close(): void {
    if (!this.selected && this.panel.hidden) return;
    this.selected = null;
    this.naming = false;
    this.panel.hidden = true;
    this.dropTrace();
  }

  /** The card's work's middle, in world tiles, for a camera sent to it. */
  centreOf(wk: Work): { x: number; z: number } {
    const t = wk.tiles[Math.floor(wk.tiles.length / 2)];
    return { x: wk.w.ox + (t % N) + 0.5, z: wk.w.oz + Math.floor(t / N) + 0.5 };
  }

  /**
   * The selected work glows: its own drawn triangles (the road and bridge meshes over its tiles, or the
   * ground for earthworks, or the building for an HQ) copied into one mesh in the highlight colour, drawn
   * over the originals and pulsing (frame). A worn path has nothing of its own drawn, so it, or a work whose
   * chunks aren't drawn yet, gets a flat trace over its tiles instead.
   */
  private drawTrace(wk: Work): void {
    this.dropTrace();
    const g = this.host.groupOf(wk.w);
    if (!g) return;
    const parts = wk.kind === 'path' ? null : isFeature(wk.kind) ? ['terrain'] : wk.kind === 'hq' ? ['town'] : ['roads', 'bridges'];
    const glow = parts ? this.glowOf(wk, g, parts) : null;
    if (glow) {
      this.trace = glow;
      this.traceT = 0;
      g.add(glow);
      return;
    }
    const pos: number[] = [];
    for (const t of wk.tiles) {
      const x = t % N, z = Math.floor(t / N);
      const y = (a: number, b: number) => (wk.w.deckAxis[t] ? heightAt(wk.w, x + 0.5, z + 0.5) : heightOnTile(wk.w, x, z, a, b)) + 0.06;
      pos.push(x, y(x, z), z, x, y(x, z + 1), z + 1, x + 1, y(x + 1, z + 1), z + 1, x, y(x, z), z, x + 1, y(x + 1, z + 1), z + 1, x + 1, y(x + 1, z), z);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    const mat = new THREE.MeshBasicMaterial({ color: HIGHLIGHT, transparent: true, opacity: 0.32, depthTest: false, depthWrite: false, side: THREE.DoubleSide });
    this.trace = new THREE.Mesh(geo, mat);
    this.trace.renderOrder = 998;
    g.add(this.trace);
  }

  /** The triangles of the named chunk parts whose middles stand on the work's tiles, as one glowing mesh; null when none are drawn. */
  private glowOf(wk: Work, g: THREE.Object3D, names: string[]): THREE.Mesh | null {
    const on = new Set(wk.tiles);
    // a little slack, so a rail or a pier on a tile's very edge comes along
    const inWork = (x: number, z: number): boolean => {
      for (const [dx, dz] of [[0, 0], [GLOW_SLACK, 0], [-GLOW_SLACK, 0], [0, GLOW_SLACK], [0, -GLOW_SLACK]]) {
        const tx = Math.floor(x + dx), tz = Math.floor(z + dz);
        if (tx >= 0 && tz >= 0 && tx < N && tz < N && on.has(tz * N + tx)) return true;
      }
      return false;
    };
    g.updateMatrixWorld();
    const toG = new THREE.Matrix4().copy(g.matrixWorld).invert();
    const m = new THREE.Matrix4(), a = new THREE.Vector3(), b = new THREE.Vector3(), c = new THREE.Vector3();
    const out: number[] = [];
    // the chunks' parts, named after their build step (render/stream.ts), wherever they hang under the island
    const found: THREE.Object3D[] = [];
    const seek = (o: THREE.Object3D): void => { if (names.includes(o.name)) found.push(o); else for (const ch of o.children) seek(ch); };
    seek(g);
    for (const part of found) {
      part.traverse((o) => {
        if (!(o instanceof THREE.Mesh) || o instanceof THREE.InstancedMesh || !o.visible) return;
        const p = (o.geometry as THREE.BufferGeometry).getAttribute('position');
        if (!p) return;
        const idx = (o.geometry as THREE.BufferGeometry).getIndex();
        m.multiplyMatrices(toG, o.matrixWorld);
        const n = idx ? idx.count : p.count;
        for (let i = 0; i + 2 < n; i += 3) {
          const i0 = idx ? idx.getX(i) : i, i1 = idx ? idx.getX(i + 1) : i + 1, i2 = idx ? idx.getX(i + 2) : i + 2;
          a.fromBufferAttribute(p, i0).applyMatrix4(m);
          b.fromBufferAttribute(p, i1).applyMatrix4(m);
          c.fromBufferAttribute(p, i2).applyMatrix4(m);
          if (!inWork((a.x + b.x + c.x) / 3, (a.z + b.z + c.z) / 3)) continue;
          out.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z);
        }
      });
    }
    if (!out.length) return null;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(out, 3));
    // over the originals it was copied from (polygon offset), hidden by what stands in front of it
    const mat = new THREE.MeshBasicMaterial({
      color: HIGHLIGHT, transparent: true, opacity: GLOW_LO, blending: THREE.AdditiveBlending, depthWrite: false,
      polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, side: THREE.DoubleSide, toneMapped: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.renderOrder = 998;
    mesh.userData.glow = true;
    return mesh;
  }

  private dropTrace(): void {
    if (!this.trace) return;
    this.trace.removeFromParent();
    this.trace.geometry.dispose();
    (this.trace.material as THREE.Material).dispose();
    this.trace = null;
  }

  private render(force = false): void {
    const wk = this.selected;
    if (!wk) return;
    const row = this.row(wk.key);
    const mine = wk.by === this.me;
    const who = this.online.people.get(wk.by);
    const fleet = who?.brand?.name ?? who?.name ?? (mine ? 'you' : 'another fleet');
    const dot = who?.brand ? `<i class="dot" style="background:${hex(who.brand.primary)}"></i>` : '';
    const size = isFeature(wk.kind) ? `${wk.len.toLocaleString('en-US')} lifts` : wk.kind === 'path' ? `worn in by ${wk.len} fleets` : `${wk.len} tiles`;
    const head = `<span class="ic">${KIND_ICON[wk.kind]}</span><b>${esc(this.title(wk))}</b><small>${esc(WORK_LABEL[wk.kind])} · ${size}${this.listed(wk.key) ? ' · <em class="listed">Listed</em>' : ''}</small>`;
    const built = wk.kind === 'path' ? 'First driven by' : isFeature(wk.kind) ? 'Shaped by' : 'Built by';
    const day = wk.at ? ` on day ${Math.floor(wk.at / 24) + 1}` : '';
    const diggers = isFeature(wk.kind) ? this.diggers(wk).filter((p) => p !== wk.by).slice(0, 2).map((p) => this.online.fleetName(p)) : [];
    const hearted = this.hearts.has(wk.key);
    const nameable = mine && wk.kind !== 'hq' && (wk.kind !== 'road' || wk.len >= COMMUNITY.roadMin);
    const hq = !mine ? this.hqOf(wk.by) : null;
    let body = `<dl><dt>${built}</dt><dd>${dot}<b${mine ? '' : ` data-pid="${esc(wk.by)}"`}>${esc(mine ? 'You' : fleet)}</b>${esc(day)}${diggers.length ? ` <small>with ${esc(diggers.join(' and '))}</small>` : ''}</dd>`
      + `<dt>Hearts</dt><dd><b class="hrt">♥ ${row.h}</b>${row.h >= COMMUNITY.listedAt || row.l ? '' : ` <small>${COMMUNITY.listedAt - row.h} more to list it</small>`}</dd>`
      + (!isGround(wk.kind) ? `<dt>Crossings</dt><dd>${row.u.toLocaleString('en-US')} by ${row.f} fleet${row.f === 1 ? '' : 's'}</dd>` : '')
      + (() => { const p = this.project(wk.key); return p ? `<dt>Project</dt><dd><b>${esc(p.name)}</b> <small>${p.keys.length} works near each other · <span class="hrt">♥ ${p.h}</span> in all</small></dd>` : ''; })()
      + '</dl>';
    if (this.naming) body += `<div class="name"><input type="text" maxlength="${COMMUNITY.nameMax}" placeholder="Name it" value="${esc(row.name ?? '')}"><button type="button" data-act="save">Save</button></div>`;
    // names other players have suggested: a vote each, and the builder may take one (docs/marks.html)
    const sg = row.sg ?? [];
    const canSuggest = !mine && wk.kind !== 'hq' && (wk.kind !== 'road' || wk.len >= COMMUNITY.roadMin);
    if (sg.length) {
      body += `<div class="sugg"><dt>Suggested</dt>${sg.map((x) => {
        const voted = x.v.includes(this.me);
        const btn = mine ? `<button type="button" data-act="accept:${esc(x.by)}">Use this name</button>`
          : x.by === this.me ? '<small>yours</small>' : `<button type="button" data-act="vote:${esc(x.by)}" class="heart${voted ? ' on' : ''}">♥ ${voted ? 'Backed' : 'Back it'}</button>`;
        return `<div class="s"><span><b>“${esc(x.text)}”</b> <small><span data-pid="${esc(x.by)}">${esc(this.online.fleetName(x.by))}</span> · ${x.v.length} vote${x.v.length === 1 ? '' : 's'}</small></span>${btn}</div>`;
      }).join('')}${row.name ? '' : `<small class="how">${MARKS.suggestVotes} votes name it</small>`}</div>`;
    }
    if (this.suggesting) body += `<div class="name"><input type="text" maxlength="${COMMUNITY.nameMax}" placeholder="A name for it" value="${esc(sg.find((x) => x.by === this.me)?.text ?? '')}"><button type="button" data-act="ssave">Suggest</button></div>`;
    const btn = (act: string, label: string, cls = '') => `<button type="button" data-act="${act}" class="${cls}">${label}</button>`;
    body += '<div class="acts">'
      + (mine ? (nameable && !this.naming ? btn('name', row.name ? 'Rename' : 'Name it') : '')
        : btn('heart', hearted ? '♥ Hearted · take it back' : '♥ Leave a heart', hearted ? 'on heart' : 'heart'))
      + (!mine && this.online.cellOf(wk.by) ? btn('follow', 'Follow builder') : '')
      + (hq ? btn('hq', 'View their HQ') : '')
      + '</div>';
    if (canSuggest && !this.suggesting) body += `<button type="button" class="report" data-act="suggest">${sg.some((x) => x.by === this.me) ? 'Change your suggested name' : row.name ? 'Suggest another name' : 'Suggest a name'}</button>`;
    if (!mine && row.name) body += `<button type="button" class="report" data-act="report">Report this name</button>`;
    if (mine) body += `<p class="note">${this.listed(wk.key) ? 'Listed: nobody else can bulldoze it.' : `With ${COMMUNITY.listedAt} hearts it is listed, and only you can bulldoze it.`}</p>`;
    else if (!hearted) body += `<p class="note">Hearts are free. <kbd>L</kbd> leaves one as you drive across another player’s work.</p>`;
    if (head !== this.head.innerHTML) this.head.innerHTML = head;
    // while a name is typed the card stays as it is
    if ((force || !(this.naming || this.suggesting)) && body !== this.bodyHtml) {
      this.bodyHtml = body;
      this.body.innerHTML = body;
      if (this.naming || this.suggesting) { const inp = this.body.querySelector('input'); inp?.focus(); inp?.select(); }
    }
  }

  /** Everyone who moved a landform's ground, most first, from the chunks it covers. */
  private diggers(wk: Work): Pid[] {
    const dug = new Map<Pid, number>();
    for (const ch of new Set(wk.tiles.map(chunkOfTile))) for (const [p, l] of this.landBy.get(wk.cell)?.[String(ch)] ?? []) dug.set(p, (dug.get(p) ?? 0) + l);
    return [...dug].sort((a, b) => b[1] - a[1]).map(([p]) => p);
  }

  /** A player's HQ, if this game knows it: from the doors in memory, or the friends list. */
  private hqOf(pid: Pid): { key: string; name: string } | null {
    for (const [key, d] of this.online.deeds) if (d.by === pid && d.hq !== undefined) return { key, name: d.name };
    const f = this.online.friends.find((x) => x.id === pid);
    return f?.hq ?? null;
  }

  private act(a: string): void {
    const wk = this.selected;
    if (!wk) return;
    if (a === 'heart') this.toggleHeart(wk.key);
    else if (a === 'name') { this.naming = true; this.render(true); return; }
    else if (a === 'suggest') { this.suggesting = true; this.render(true); return; }
    else if (a === 'ssave') {
      const inp = this.body.querySelector('input');
      this.online.post({ t: 'suggest', k: wk.key, text: inp?.value ?? '' });
      this.suggesting = false;
    } else if (a.startsWith('vote:')) {
      const by = a.slice(5);
      this.online.post({ t: 'vote', k: wk.key, by, on: !this.row(wk.key).sg?.find((x) => x.by === by)?.v.includes(this.me) });
    } else if (a.startsWith('accept:')) this.online.post({ t: 'accept', k: wk.key, by: a.slice(7) });
    else if (a === 'save') {
      const inp = this.body.querySelector('input');
      this.online.post({ t: 'name', k: wk.key, text: inp?.value ?? '' });
      this.naming = false;
    } else if (a === 'report') { this.online.post({ t: 'report', k: wk.key }); }
    else if (a === 'follow') { this.close(); this.host.follow(wk.by, this.online.fleetName(wk.by)); return; }
    else if (a === 'hq') { const hq = this.hqOf(wk.by); if (hq) { this.close(); this.host.viewHq(hq.key, hq.name); } return; }
    this.render(true);
  }

  /** Leave a heart on a work, or take it back. The server has the last word and answers with my list. */
  toggleHeart(key: string): void {
    const on = !this.hearts.has(key);
    if (on) this.hearts.add(key); else this.hearts.delete(key);
    this.heartsVer++;
    this.online.post({ t: 'heart', k: key, on });
  }

  /** L: a heart for the work the prompt names, or the one whose card is open. */
  heartKey(): boolean {
    if (!this.on) return false;
    if (!this.prompt.hidden && this.promptKey) {
      this.toggleHeart(this.promptKey);
      this.prompt.innerHTML = `<b class="hrt">♥</b> ${this.prompt.dataset.what ?? ''} <em>· thank you</em>`;
      this.promptT = Math.min(this.promptT, 1.6);
      return true;
    }
    if (this.selected && this.selected.by !== this.me) { this.toggleHeart(this.selected.key); this.render(true); return true; }
    return false;
  }

  // ---- every frame ------------------------------------------------------------------------------------

  frame(dt: number): void {
    if (!this.on) return;
    for (const w of this.worlds()) this.draw(w);
    for (const [w, d] of this.drawn) if (this.host.islands()?.at(w.cx, w.cz) !== w) { this.undraw(d); this.drawn.delete(w); }
    if (this.selected) {
      const wk = this.selected;
      if (this.host.islands()?.at(wk.w.cx, wk.w.cz) !== wk.w || !wk.tiles.some((t) => wk.w.road[t] > 0 || isGround(wk.kind))) this.close();
      else { this.cardT -= dt; if (this.cardT <= 0) { this.cardT = 0.5; this.render(); } }
      if (this.trace?.userData.glow) {
        this.traceT += dt;
        const k = 0.5 - 0.5 * Math.cos((this.traceT / GLOW_PERIOD) * Math.PI * 2);
        (this.trace.material as THREE.MeshBasicMaterial).opacity = GLOW_LO + (GLOW_HI - GLOW_LO) * k;
      }
    }
    this.sampleT -= dt;
    if (this.sampleT <= 0) { this.sampleT = 0.2; this.sample(); }
    if (!this.prompt.hidden) { this.promptT -= dt; if (this.promptT <= 0) { this.prompt.hidden = true; this.promptKey = ''; } }
    this.treadT -= dt;
    if (this.treadT <= 0) { this.treadT = COMMUNITY.treadEvery; this.sendTread(); }
  }

  /** Five times a second: the ground under my wheels, the works under them and my fleet's, and the prompt. */
  private sample(): void {
    const w = this.host.home(), v = this.host.veh(), def = this.host.def();
    if (!w || !v) return;
    const tx = Math.floor(v.x), tz = Math.floor(v.z);
    if (!inB(tx, tz)) return;
    const i = idx(tx, tz);
    const k = cellKey(w.cx, w.cz);
    // tyres on open ground: a land vehicle (not a hovercraft) going at more than walking pace
    if (def.kind === 'land' && def.licence !== 'sea' && Math.abs(v.v) * 12 >= COMMUNITY.wearKmh && !(w.flags[i] & Flag.Track) && !pathBarred(w, i)) {
      let s = this.trod.get(k);
      if (!s) this.trod.set(k, (s = new Set()));
      s.add(i);
    }
    this.cross('me', w, i);
    for (const m of this.host.movers()) {
      const mx = Math.floor(m.x), mz = Math.floor(m.z);
      if (inB(mx, mz)) this.cross(m.id, m.w, idx(mx, mz));
    }
    // the prompt: on another player's bridge, tunnel or long road, once a session each
    const wk = this.worksOf(w).at.get(i);
    if (wk && wk.by !== this.me && (wk.kind !== 'road' || wk.len >= COMMUNITY.roadMin) && !this.hearts.has(wk.key) && !this.prompted.has(wk.key) && this.host.playing()) {
      this.prompted.add(wk.key);
      this.promptKey = wk.key;
      this.promptT = PROMPT_LIFE;
      const who = this.online.people.get(wk.by);
      const what = `<b>${esc(this.title(wk))}</b>`;
      this.prompt.dataset.what = what;
      this.prompt.innerHTML = `${who?.brand ? `<i class="dot" style="background:${hex(who.brand.primary)}"></i>` : ''}${what} <kbd>L</kbd> <span class="hrt">♥</span> leave a heart`;
      this.prompt.hidden = false;
    }
  }

  /**
   * A vehicle on a work (a road, and a span of it where there is one): once it has been over enough of the
   * work and leaves it, that is a crossing.
   */
  private cross(id: string, w: World, i: number): void {
    const here = (this.worksOf(w).all.get(i) ?? []).filter((wk) => wk.by !== this.me);
    for (const [key, c] of this.crossing) {
      if (!key.startsWith(`${id}|`) || here.some((wk) => wk.key === c.key)) continue;
      if (c.seen.size >= Math.max(2, 0.4 * c.len)) this.used.add(c.key);
      this.crossing.delete(key);
    }
    for (const wk of here) {
      const k = `${id}|${wk.key}`;
      let c = this.crossing.get(k);
      if (!c) this.crossing.set(k, (c = { key: wk.key, seen: new Set(), len: wk.len }));
      c.seen.add(i);
    }
  }

  /** Every twenty seconds: the ground I wore (in the cell I wore most of) and the works crossed. */
  private sendTread(): void {
    let cell = '', tiles: number[] = [];
    for (const [k, s] of this.trod) if (s.size > tiles.length) { cell = k; tiles = [...s]; }
    this.trod.clear();
    const use = [...this.used];
    this.used.clear();
    if (!tiles.length && !use.length) return;
    this.online.post({ t: 'tread', ...(tiles.length ? { c: cell, tiles: tiles.slice(0, COMMUNITY.treadMax) } : {}), ...(use.length ? { use } : {}) });
  }

  // ---- drawing ----------------------------------------------------------------------------------------

  private mat(c: number): THREE.MeshLambertMaterial {
    let m = this.mats.get(c);
    if (!m) this.mats.set(c, (m = new THREE.MeshLambertMaterial({ color: c, side: THREE.DoubleSide })));
    return m;
  }

  /**
   * A work's name tag: its name (or whose and what it is) over its hearts, always shown so it is plain
   * that it can be hearted. ♡ until you have left one, ♥ once you have (and on your own works). The same
   * size on screen at any distance; cached by what it says.
   */
  private nameTag(title: string, h: number, filled: boolean): THREE.Sprite {
    const text = `${title}|${h}|${filled ? 1 : 0}`;
    let m = lruGet(this.sprites, text);
    if (!m) {
      // drawn at twice the size it shows, so it stays crisp
      const c = document.createElement('canvas');
      const g = c.getContext('2d')!;
      const nameFont = '700 48px "IBM Plex Sans", "Segoe UI", sans-serif', countFont = '700 46px "IBM Plex Sans", "Segoe UI", sans-serif';
      const count = String(h), hs = 38, gap = 12;
      g.font = nameFont;
      const nw = g.measureText(title).width;
      g.font = countFont;
      const cw = g.measureText(count).width;
      const row = hs + gap + cw;
      c.width = Math.ceil(Math.max(nw, row) + 56); c.height = 136;
      g.fillStyle = 'rgba(255,255,255,.94)';
      g.beginPath(); g.roundRect(3, 3, c.width - 6, c.height - 6, 30); g.fill();
      g.textBaseline = 'middle';
      g.textAlign = 'center'; g.font = nameFont; g.fillStyle = '#1f2b33';
      g.fillText(title, c.width / 2, 44);
      // the heart: outlined until you have left one, filled once you have
      const hx = (c.width - row) / 2 + hs / 2, hy = 74;
      g.beginPath();
      g.moveTo(hx, hy + hs * 0.3);
      g.bezierCurveTo(hx, hy, hx - hs / 2, hy, hx - hs / 2, hy + hs * 0.3);
      g.bezierCurveTo(hx - hs / 2, hy + hs * 0.6, hx, hy + hs * 0.78, hx, hy + hs);
      g.bezierCurveTo(hx, hy + hs * 0.78, hx + hs / 2, hy + hs * 0.6, hx + hs / 2, hy + hs * 0.3);
      g.bezierCurveTo(hx + hs / 2, hy, hx, hy, hx, hy + hs * 0.3);
      g.closePath();
      g.strokeStyle = g.fillStyle = '#e0457b';
      g.lineWidth = 5; g.lineJoin = 'round';
      if (filled) g.fill(); else g.stroke();
      g.textAlign = 'left'; g.font = countFont; g.fillStyle = '#e0457b';
      g.fillText(count, hx + hs / 2 + gap, hy + hs / 2 + 2);
      const tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      // readable at night and through haze, like the town names
      m = new THREE.SpriteMaterial({ map: tex, depthWrite: false, sizeAttenuation: false, toneMapped: false, fog: false });
      m.userData.aspect = c.width / c.height;
      lruPut(this.sprites, text, m, 64, (old) => { old.map?.dispose(); old.dispose(); });
    }
    // its own copy of the material (the texture stays shared), so it fades on its own: layoutTags
    const s = new THREE.Sprite(m.clone());
    s.material.opacity = 0;
    s.visible = false;
    s.center.set(0.5, 0);
    s.userData.aspect = m.userData.aspect;
    s.userData.ownMat = true;
    s.scale.set(this.tagUnit * (m.userData.aspect as number), this.tagUnit, 1);
    s.renderOrder = 6;
    return s;
  }

  /** A road's name as a street sign: white on green, its hearts after it. Cached by what it says. */
  private streetSign(name: string, h: number): THREE.Sprite {
    const text = `road|${name}|${h}`;
    let m = lruGet(this.sprites, text);
    if (!m) {
      const c = document.createElement('canvas');
      const g = c.getContext('2d')!;
      const font = '700 44px "IBM Plex Sans", "Segoe UI", sans-serif';
      g.font = font;
      const label = h ? `${name}  ♥ ${h}` : name;
      c.width = Math.ceil(g.measureText(label).width + 52); c.height = 84;
      g.fillStyle = '#1f6b45';
      g.beginPath(); g.roundRect(3, 3, c.width - 6, c.height - 6, 12); g.fill();
      g.strokeStyle = '#ffffff'; g.lineWidth = 4;
      g.beginPath(); g.roundRect(10, 10, c.width - 20, c.height - 20, 8); g.stroke();
      g.fillStyle = '#ffffff'; g.font = font; g.textBaseline = 'middle'; g.textAlign = 'center';
      g.fillText(label, c.width / 2, c.height / 2 + 2);
      const tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      m = new THREE.SpriteMaterial({ map: tex, depthWrite: false, sizeAttenuation: false, toneMapped: false, fog: false });
      m.userData.aspect = c.width / c.height;
      lruPut(this.sprites, text, m, 64, (old) => { old.map?.dispose(); old.dispose(); });
    }
    const sp = new THREE.Sprite(m.clone());
    sp.material.opacity = 0;
    sp.visible = false;
    sp.center.set(0.5, 0);
    sp.userData.aspect = m.userData.aspect;
    sp.userData.ownMat = true;
    sp.userData.road = true;
    sp.scale.set(this.tagUnit * 0.8 * (m.userData.aspect as number), this.tagUnit * 0.8, 1);
    sp.renderOrder = 6;
    return sp;
  }

  private undraw(d: { plaques: THREE.Group; paths: THREE.Group }): void {
    for (const g of [d.plaques, d.paths]) {
      g.removeFromParent();
      g.traverse((o) => {
        if (o instanceof THREE.Mesh && o.userData.own) { o.geometry.dispose(); (o.material as THREE.Material).dispose(); }
        if (o instanceof THREE.Sprite && o.userData.ownMat) o.material.dispose();
      });
    }
  }

  /** Plaques, stakes and paths over an island, drawn again when what they show has changed. */
  private draw(w: World): void {
    const parent = this.host.groupOf(w);
    if (!parent) return;
    let d = this.drawn.get(w);
    if (!d) {
      d = { plaques: new THREE.Group(), sig: '', paths: new THREE.Group(), psig: '', marks: [], tags: [] };
      this.drawn.set(w, d);
    }
    if (d.plaques.parent !== parent) { parent.add(d.plaques); parent.add(d.paths); }
    const { works } = this.worksOf(w);
    const k = cellKey(w.cx, w.cz);
    // names arrive with the people they belong to, and my hearts fill the tags in
    this.project('');
    const sig = `${this.index.get(w)?.sig}|${this.rowsVer}|${this.heartsVer}|${this.online.people.size}|${this.projVer}`;
    if (sig !== d.sig) {
      d.sig = sig;
      // drawn again (a heart left, a name come in): each tag picks up where it was, rather than fading in afresh
      const was = new Map(d.tags.map((t) => [t.key, t.sprite.material.opacity]));
      for (const o of d.plaques.children) if (o instanceof THREE.Sprite && o.userData.ownMat) o.material.dispose();
      d.plaques.clear();
      d.marks = [];
      d.tags = [];
      const keep = (t: Tag) => { const a = was.get(t.key) ?? 0; t.sprite.material.opacity = a; t.sprite.visible = a > 0.01; d!.tags.push(t); };
      for (const wk of works.values()) {
        // a named road: a street sign over its middle, so the name is on the ground as well as the map (docs/marks.html)
        if (wk.kind === 'road') {
          const nm = this.row(wk.key).name;
          const t = wk.tiles[Math.floor(wk.tiles.length / 2)];
          if (nm && t !== undefined) {
            const lx = (t % N) + 0.5, lz = Math.floor(t / N) + 0.5, y = heightAt(w, lx, lz) + 0.55;
            const tag = this.streetSign(nm, this.row(wk.key).h);
            tag.position.set(lx, y, lz);
            d.plaques.add(tag);
            keep({ x: w.ox + lx, y, z: w.oz + lz, key: wk.key, aspect: tag.userData.aspect as number, sprite: tag, road: true, scale: 1 });
          }
          continue;
        }
        if (!wk.marks.length) continue;
        const who = wk.by === this.me ? this.online.me : this.online.people.get(wk.by);
        const primary = who?.brand?.primary ?? 0x7d8a92, accent = who?.brand?.accent ?? 0xffffff;
        const proj = this.project(wk.key);
        if (wk.label && (!proj || proj.lead === wk.key)) {
          const [lx, ly, lz] = wk.label;
          if (lx >= 0 && lz >= 0 && lx < N && lz < N) {
            const y = (Number.isNaN(ly) ? heightAt(w, lx, lz) + 0.9 : ly + 0.5);
            // a project's one tag: its name and all its hearts (the user, 5 Nov 2026)
            const tag = proj ? this.nameTag(proj.name, proj.h, wk.by === this.me || proj.hearted) : this.nameTag(this.title(wk), this.row(wk.key).h, wk.by === this.me || this.hearts.has(wk.key));
            tag.position.set(lx, y, lz);
            d.plaques.add(tag);
            keep({ x: w.ox + lx, y, z: w.oz + lz, key: wk.key, aspect: tag.userData.aspect as number, sprite: tag, road: false, scale: 1 });
          }
        }
        for (const [x, z, yaw] of wk.marks) {
          if (x < 0 || z < 0 || x >= N || z >= N) continue;
          const y = heightAt(w, x, z);
          const g = new THREE.Group();
          g.position.set(x, y, z);
          g.rotation.y = yaw;
          if (wk.kind === 'path') {
            // a cairn: stones piled small on big, and a pennant in the trailblazer's colours
            for (const [sx, sy, sz, r] of [[0, 0.07, 0, 0.16], [0.05, 0.19, -0.02, 0.12], [-0.02, 0.29, 0.02, 0.085]] as const) {
              const st = new THREE.Mesh(this.stoneGeo, this.mat(0x9a968c));
              st.position.set(sx, sy, sz); st.scale.set(r, r * 0.75, r);
              g.add(st);
            }
            const pole = new THREE.Mesh(this.postGeo, this.mat(0xf2efe6));
            pole.position.y = 0.3; pole.scale.set(0.6, 0.9, 0.6);
            const pen = new THREE.Mesh(this.pennantGeo, this.mat(primary));
            pen.position.y = 0.05;
            g.add(pole, pen);
          } else if (isFeature(wk.kind)) {
            // a survey stake: a pole and a pennant in the digger's colours
            const pole = new THREE.Mesh(this.postGeo, this.mat(0xf2efe6));
            pole.scale.set(0.8, 1.5, 0.8);
            g.add(pole, new THREE.Mesh(this.pennantGeo, this.mat(primary)));
            const band = new THREE.Mesh(this.stripeGeo, this.mat(accent));
            band.scale.set(0.15, 0.6, 1.5);
            band.position.y = 0.46;
            g.add(band);
          } else {
            // a plaque: a post and a board in the builder's colours, its accent along the top
            const board = new THREE.Mesh(this.boardGeo, this.mat(primary));
            board.position.y = 0.48;
            const stripe = new THREE.Mesh(this.stripeGeo, this.mat(accent));
            stripe.position.y = 0.57;
            g.add(new THREE.Mesh(this.postGeo, this.mat(0x6b5a48)), board, stripe);
          }
          d.plaques.add(g);
          d.marks.push({ x: w.ox + x, y, z: w.oz + z, key: wk.key });
        }
      }
    }
    const psig = `${this.ver.get(k) ?? 0}|${w.roadStamp}`;
    if (psig !== d.psig) {
      d.psig = psig;
      this.drawPaths(w, d.paths);
    }
  }

  /**
   * The paths over an island: a pale flattened band for a faint one, and two bare ruts down a worn one,
   * running from each tile's middle toward its worn neighbours so a line of tiles reads as one path. A
   * lone tile below worn draws nothing. Beaten tracks are the ground's own (Flag.Track).
   */
  private drawPaths(w: World, into: THREE.Group): void {
    into.traverse((o) => { if (o instanceof THREE.Mesh) { o.geometry.dispose(); (o.material as THREE.Material).dispose(); } });
    into.clear();
    const p = this.paths.get(cellKey(w.cx, w.cz));
    if (!p) return;
    const stages = pathStages(p.block);
    const st = (x: number, z: number): PathStage => (inB(x, z) ? stages.get(idx(x, z)) ?? 0 : 0);
    const band: number[] = [], ruts: number[] = [];
    const quad = (out: number[], x: number, z: number, ax: number, az: number, bx: number, bz: number, half: number, lift: number) => {
      const dx = bx - ax, dz = bz - az, l = Math.hypot(dx, dz) || 1;
      const nx = (-dz / l) * half, nz = (dx / l) * half;
      const h = (px: number, pz: number) => heightOnTile(w, x, z, Math.min(x + 1, Math.max(x, px)), Math.min(z + 1, Math.max(z, pz))) + lift;
      const p0 = [ax + nx, az + nz], p1 = [ax - nx, az - nz], p2 = [bx - nx, bz - nz], p3 = [bx + nx, bz + nz];
      for (const [qx, qz] of [p0, p1, p2, p0, p2, p3]) out.push(qx, h(qx, qz), qz);
    };
    for (const [i, s] of stages) {
      // a beaten track is the ground's own, and so is a farm track already there
      if (s >= 3 || pathBarred(w, i) || w.flags[i] & Flag.Track) continue;
      const x = i % N, z = Math.floor(i / N);
      const cx = x + 0.5, cz = z + 0.5;
      const arms: [number, number][] = [];
      for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) if (st(x + dx, z + dz)) arms.push([dx, dz]);
      // a diagonal only where the path doesn't already turn the corner through a side
      for (const [dx, dz] of [[1, 1], [1, -1], [-1, 1], [-1, -1]] as const) if (st(x + dx, z + dz) && !st(x + dx, z) && !st(x, z + dz)) arms.push([dx, dz]);
      if (!arms.length && s < 2) continue;
      const half = s >= 2 ? 0.3 : 0.2;
      // the middle only where the path bends or ends: on a straight run the two arms meet there already,
      // and a square over them would show as a bead on every tile
      const straight = arms.length === 2 && arms[0][0] === -arms[1][0] && arms[0][1] === -arms[1][1];
      if (!straight) quad(band, x, z, cx - half * 0.7, cz, cx + half * 0.7, cz, half * 0.7, 0.025);
      for (const [dx, dz] of arms) {
        const ex = cx + dx * 0.5, ez = cz + dz * 0.5;
        quad(band, x, z, cx, cz, ex, ez, half, 0.025);
        if (s >= 2) {
          const l = Math.hypot(dx, dz), ox = (-dz / l) * 0.16, oz = (dx / l) * 0.16;
          quad(ruts, x, z, cx + ox, cz + oz, ex + ox, ez + oz, 0.045, 0.03);
          quad(ruts, x, z, cx - ox, cz - oz, ex - ox, ez - oz, 0.045, 0.03);
        }
      }
    }
    const mesh = (pos: number[], mat: THREE.Material, order: number) => {
      if (!pos.length) return;
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
      g.computeVertexNormals();
      const m = new THREE.Mesh(g, mat);
      m.renderOrder = order;
      m.userData.own = true;
      into.add(m);
    };
    // flattened grass, lit like the ground under it; ruts multiply what is drawn, as tyre tracks do
    mesh(band, new THREE.MeshLambertMaterial({ color: 0xd9cf9a, transparent: true, opacity: 0.4, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2, side: THREE.DoubleSide }), 2);
    mesh(ruts, new THREE.MeshBasicMaterial({
      color: 0x9a7f62, transparent: true, depthWrite: false, side: THREE.DoubleSide,
      blending: THREE.CustomBlending, blendEquation: THREE.AddEquation, blendSrc: THREE.ZeroFactor, blendDst: THREE.SrcColorFactor,
      polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3,
    }), 3);
  }

  // ---- the map overlay --------------------------------------------------------------------------------

  private layerBtn: HTMLButtonElement | null = null;
  private pinsEl: HTMLDivElement | null = null;
  private pinEls = new Map<string, HTMLElement>();
  private layerOn = (() => { try { return localStorage.getItem('tinyfleet-community-layer') !== '0'; } catch { return true; } })();
  private roadLayers = new Map<World, { mesh: THREE.Mesh | null; sig: string }>();

  /**
   * The overview (M), online: a Community button, and with it on, every player road in its builder's colour
   * and a heart pin over each loved work in memory. Called every frame; `on` while the overview is up.
   */
  /**
   * Development only: put name tags round world point (x, z) on island w, as if works stood there, to see the layout
   * without a server (`community.testTags(pr.world, pr.world.ox + pr.car.x, pr.world.oz + pr.car.z)`). `spread` tiles apart.
   */
  testTags(w: World, x: number, z: number, n = 8, spread = 3): number {
    const parent = this.host.groupOf(w);
    if (!parent) return 0;
    const d = { plaques: new THREE.Group(), sig: 'test', paths: new THREE.Group(), psig: 'test', marks: [] as { x: number; y: number; z: number; key: string }[], tags: [] as Tag[] };
    parent.add(d.plaques);
    for (let i = 0; i < n; i++) {
      const lx = x - w.ox + (i % 4) * spread, lz = z - w.oz + Math.floor(i / 4) * spread;
      const y = heightAt(w, Math.min(N - 1, Math.max(0, lx)), Math.min(N - 1, Math.max(0, lz))) + 0.9;
      const tag = i % 3 === 2 ? this.streetSign(`Test Road ${i}`, i) : this.nameTag(`Bob1000's Fleet's ${i % 2 ? 'viaduct' : 'flyover'}`, i, i % 2 === 0);
      tag.position.set(lx, y, lz);
      d.plaques.add(tag);
      d.tags.push({ x: w.ox + lx, y, z: w.oz + lz, key: `test#${i}`, aspect: tag.userData.aspect as number, sprite: tag, road: !!tag.userData.road, scale: 1 });
    }
    this.drawn.set(w, d);
    return d.tags.length;
  }

  private tagAt = new THREE.Vector3();
  private tagDir = new THREE.Vector3();
  private tagClock = 0;
  /** Screen boxes of the tags placed this frame, four numbers each (left, top, right, bottom, in pixels). */
  private placed: number[] = [];
  private tagList: { t: Tag; d: number; rank: number }[] = [];

  /** Where the camera is looking: its middle ray met with the ground (a few steps, the ground's height under each guess). */
  private focusOf(camera: THREE.Camera): { x: number; z: number } {
    const o = camera.position, dir = camera.getWorldDirection(this.tagDir);
    let y = 0, x = o.x, z = o.z;
    if (dir.y > -0.05) return { x, z };
    for (let k = 0; k < 3; k++) {
      const t = (y - o.y) / dir.y;
      x = o.x + dir.x * t; z = o.z + dir.z * t;
      const w = this.worlds().find((q) => x >= q.ox && z >= q.oz && x < q.ox + N && z < q.oz + N);
      if (!w) break;
      y = heightAt(w, x - w.ox, z - w.oz);
    }
    return { x, z };
  }

  /**
   * The name tags, every frame: shown only near where the camera is looking (TAG_FAR), opaque only close
   * (TAG_NEAR) and fainter and a little smaller further off; and never on top of one another: laid out nearest
   * first (the work whose card is open before all), a tag that would overlap one already placed fades out until it
   * has room. Each eases toward what it should be, so tags fade rather than pop as the view moves.
   */
  private layoutTags(camera: THREE.Camera): void {
    const now = performance.now();
    const dt = this.tagClock ? Math.min(0.1, (now - this.tagClock) / 1000) : 0;
    this.tagClock = now;
    const focus = this.focusOf(camera);
    const W = window.innerWidth, H = window.innerHeight;
    const list = this.tagList;
    list.length = 0;
    for (const dr of this.drawn.values()) {
      for (const t of dr.tags) {
        const d = Math.hypot(t.x - focus.x, t.z - focus.z);
        const sel = this.selected?.key === t.key;
        list.push({ t, d, rank: sel ? -Infinity : d - (t.sprite.material.opacity > 0.05 ? TAG_STICK : 0) });
      }
    }
    list.sort((a, b) => a.rank - b.rank);
    const placed = this.placed;
    placed.length = 0;
    for (const { t, d, rank } of list) {
      // the overview's pins say it there; the open card's tag shows however far off
      let want = this.inOverview ? 0 : rank === -Infinity ? 1 : tagAlpha(d);
      t.scale = tagScale(d);
      if (want > 0) {
        this.tagAt.set(t.x, t.y, t.z).project(camera);
        if (this.tagAt.z > 1) want = 0;
        else {
          const px = ((this.tagAt.x + 1) / 2) * W, py = ((1 - this.tagAt.y) / 2) * H;
          const tall = TAG_PX * t.scale * (t.road ? 0.8 : 1), half = (tall * t.aspect) / 2 + TAG_GAP / 2;
          const l = px - half, r = px + half, top = py - tall - TAG_GAP / 2, bot = py + TAG_GAP / 2;
          let clash = false;
          for (let i = 0; i < placed.length && !clash; i += 4) clash = l < placed[i + 2] && r > placed[i] && top < placed[i + 3] && bot > placed[i + 1];
          if (clash) want = 0;
          else placed.push(l, top, r, bot);
        }
      }
      const s = t.sprite, m = s.material;
      const step = dt * TAG_FADE;
      const a = Math.abs(want - m.opacity) <= step ? want : m.opacity + Math.sign(want - m.opacity) * step;
      if (a !== m.opacity) m.opacity = a;
      const vis = a > 0.01;
      if (s.visible !== vis) s.visible = vis;
      const u = this.tagUnit * t.scale * (t.road ? 0.8 : 1);
      if (s.scale.y !== u) s.scale.set(u * t.aspect, u, 1);
    }
  }

  overview(on: boolean, camera: THREE.Camera): void {
    if (!this.layerBtn) {
      const b = (this.layerBtn = document.createElement('button'));
      b.className = 'hud chip regionbtn communitybtn';
      b.type = 'button';
      b.hidden = true;
      b.addEventListener('click', () => {
        this.layerOn = !this.layerOn;
        try { localStorage.setItem('tinyfleet-community-layer', this.layerOn ? '1' : '0'); } catch { /* not remembered */ }
      });
      const p = (this.pinsEl = document.createElement('div'));
      p.id = 'community-pins';
      p.addEventListener('click', (e) => {
        const el = (e.target as HTMLElement).closest('[data-k]') as HTMLElement | null;
        const wk = el?.dataset.k ? this.find(el.dataset.k) : null;
        if (wk) { this.select(wk); e.stopPropagation(); }
      });
      document.body.append(b, p);
    }
    const show = on && this.on;
    this.inOverview = on;
    const lens = camera.projectionMatrix.elements[5] || 1;
    this.tagUnit = (2 * TAG_PX) / (window.innerHeight * lens);
    this.layoutTags(camera);
    this.layerBtn.hidden = !show;
    const label = `<b>Community</b><span class="${this.layerOn ? 'on' : ''}">${this.layerOn ? 'on' : 'off'}</span>`;
    if (show && this.layerBtn.innerHTML !== label) this.layerBtn.innerHTML = label;
    const live = show && this.layerOn;
    this.pinsEl!.hidden = !live;
    for (const [w, l] of this.roadLayers) {
      if (l.mesh) l.mesh.visible = live;
      if (this.host.islands()?.at(w.cx, w.cz) !== w) { l.mesh?.removeFromParent(); l.mesh?.geometry.dispose(); this.roadLayers.delete(w); }
    }
    if (!live) return;
    for (const w of this.worlds()) this.roadLayer(w);
    // the pins, placed where their works are on screen
    const seen = new Set<string>();
    for (const p of this.pins()) {
      this.ray.set(p.x, p.y + 0.5, p.z).project(camera);
      if (this.ray.z > 1 || Math.abs(this.ray.x) > 1.05 || Math.abs(this.ray.y) > 1.05) continue;
      seen.add(p.key);
      let el = this.pinEls.get(p.key);
      if (!el) { el = document.createElement('div'); el.className = 'cpin'; el.dataset.k = p.key; this.pinsEl!.append(el); this.pinEls.set(p.key, el); }
      const html = `<b>♥ ${p.h}</b><span>${esc(p.title)}</span>`;
      if (el.innerHTML !== html) el.innerHTML = html;
      el.style.transform = `translate(${Math.round(((this.ray.x + 1) / 2) * window.innerWidth)}px, ${Math.round(((1 - this.ray.y) / 2) * window.innerHeight)}px) translate(-50%, -100%)`;
    }
    for (const [k, el] of this.pinEls) if (!seen.has(k)) { el.remove(); this.pinEls.delete(k); }
  }

  /** One island's player roads as flat strips in their builders' colours, over everything. */
  private roadLayer(w: World): void {
    const sig = this.index.get(w)?.sig ?? '';
    let l = this.roadLayers.get(w);
    if (l && l.sig === sig) return;
    if (!l) this.roadLayers.set(w, (l = { mesh: null, sig: '' }));
    l.sig = sig;
    if (l.mesh) { l.mesh.removeFromParent(); l.mesh.geometry.dispose(); l.mesh = null; }
    const pos: number[] = [], col: number[] = [];
    const c = new THREE.Color();
    for (const { colour, tiles } of this.roadsByBuilder(w)) {
      c.setHex(colour);
      for (const t of tiles) {
        const x = t % N, z = Math.floor(t / N), y = heightAt(w, x + 0.5, z + 0.5) + 0.15;
        for (const [qx, qz] of [[x + 0.15, z + 0.15], [x + 0.15, z + 0.85], [x + 0.85, z + 0.85], [x + 0.15, z + 0.15], [x + 0.85, z + 0.85], [x + 0.85, z + 0.15]]) { pos.push(qx, y, qz); col.push(c.r, c.g, c.b); }
      }
    }
    const g = this.host.groupOf(w);
    if (!pos.length || !g) return;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
    l.mesh = new THREE.Mesh(geo, this.layerMat);
    l.mesh.renderOrder = 997;
    g.add(l.mesh);
  }
  private layerMat = new THREE.MeshBasicMaterial({ vertexColors: true, transparent: true, opacity: 0.85, depthTest: false, depthWrite: false, side: THREE.DoubleSide });

  /** Hearts over works in the overview (the Community toggle): each loved work in memory, where it stands. */
  pins(): { x: number; y: number; z: number; h: number; key: string; title: string }[] {
    const out: { x: number; y: number; z: number; h: number; key: string; title: string }[] = [];
    if (!this.on) return out;
    for (const w of this.worlds()) {
      for (const wk of this.worksOf(w).works.values()) {
        const h = this.row(wk.key).h;
        // a named road shows on the overview even before anyone has hearted it
        const named = wk.kind === 'road' && !!this.row(wk.key).name;
        const proj = this.project(wk.key);
        if (proj) {
          // a project: one pin, over its lead, with all its hearts
          if (proj.lead !== wk.key || !proj.h) continue;
          const c = this.centreOf(wk);
          out.push({ x: c.x, y: heightAt(w, c.x - w.ox, c.z - w.oz), z: c.z, h: proj.h, key: wk.key, title: proj.name });
          continue;
        }
        if ((!h && !named) || (wk.kind === 'road' && [...this.worksOf(w).works.keys()].some((k) => k.startsWith(`${wk.key}.`) && this.row(k).h))) continue;
        const c = this.centreOf(wk);
        out.push({ x: c.x, y: heightAt(w, c.x - w.ox, c.z - w.oz), z: c.z, h, key: wk.key, title: this.title(wk) });
      }
    }
    return out;
  }

  /** Player roads, in their builders' colours, for the overview's Community layer. */
  roadsByBuilder(w: World): { colour: number; tiles: number[] }[] {
    const by = new Map<number, number[]>();
    for (const wk of this.worksOf(w).works.values()) {
      if (isGround(wk.kind) || wk.id.includes('.')) continue;
      const who = wk.by === this.me ? this.online.me : this.online.people.get(wk.by);
      const c = who?.brand?.primary ?? 0x7d8a92;
      const a = by.get(c);
      if (a) a.push(...wk.tiles); else by.set(c, [...wk.tiles]);
    }
    return [...by].map(([colour, tiles]) => ({ colour, tiles }));
  }

  // ---- the World tab ----------------------------------------------------------------------------------

  /** The tab is up: ask for the lists. */
  askLists(): void { this.online.post({ t: 'works' }); }

  /** A press in the tab. True if it was the tab's. */
  press(t: HTMLElement): boolean {
    const b = t.closest('.worldtab [data-wtab], .worldtab [data-fly]') as HTMLElement | null;
    if (!b) return false;
    if (b.dataset.wtab) { this.listTab = b.dataset.wtab as typeof this.listTab; if (this.listTab !== 'near') this.askLists(); return true; }
    const key = b.dataset.fly!;
    const line = [...(this.lists?.loved ?? []), ...(this.lists?.busy ?? []), ...(this.lists?.fresh ?? [])].find((l) => l.k === key);
    this.flyTo(key, line ? this.lineTitle(line) : 'A work', line?.t);
    return true;
  }

  /** Send the camera to a work; its card opens once its cell is in memory. */
  flyTo(key: string, name: string, tile?: number): void {
    const wk = this.find(key);
    if (wk) { const c = this.centreOf(wk); this.host.fly(key, name, c.x, c.z); return; }
    const m = WORK_KEY.exec(key);
    if (!m) return;
    const [cx, cz] = cellOfKey(m[1]);
    // not in memory: the tile the lists gave for it, else the middle of its chunk (a track), else of its cell
    const id = m[2];
    const ch = id.startsWith('W') ? Number(id.slice(1)) : -1;
    const x = tile !== undefined ? cx * N + (tile % N) + 0.5 : ch >= 0 ? cx * N + (ch % CHUNKS) * CHUNK + CHUNK / 2 : (cx + 0.5) * N;
    const z = tile !== undefined ? cz * N + Math.floor(tile / N) + 0.5 : ch >= 0 ? cz * N + Math.floor(ch / CHUNKS) * CHUNK + CHUNK / 2 : (cz + 0.5) * N;
    this.host.fly(key, name, x, z);
  }

  /** The camera has reached a work it was sent to: its card, if it is there. Returns false while it isn't in memory yet. */
  arrived(key: string): boolean {
    const wk = this.find(key);
    if (!wk) return false;
    this.select(wk);
    return true;
  }

  /** Where a work stands now, in world tiles, if its cell is in memory. */
  where(key: string): { x: number; z: number } | null {
    const wk = this.find(key);
    return wk ? this.centreOf(wk) : null;
  }

  private lineTitle(l: WorkLine): string {
    if (l.name) return l.name;
    return `${l.by === this.me ? 'Your' : `${this.online.fleetName(l.by)}’s`} ${l.kind === 'path' ? 'Cut' : WORK_LABEL[l.kind].toLowerCase()}`;
  }

  /** The World tab's works list to show (the social window's picker picks it): asked for unless it is the one near you. */
  showList(tab: 'loved' | 'busy' | 'fresh' | 'near' | 'friends'): void {
    if (this.listTab === tab) return;
    this.listTab = tab;
    if (tab !== 'near') this.askLists();
  }

  worldHtml(): string {
    const tab = (id: typeof this.listTab, label: string) => `<button type="button" data-wtab="${id}" class="${this.listTab === id ? 'on' : ''}">${label}</button>`;
    let lines: WorkLine[];
    const nearLines = (): WorkLine[] => {
      const out: WorkLine[] = [];
      for (const w of this.worlds()) for (const wk of this.worksOf(w).works.values()) {
        if (wk.kind === 'road' && wk.len < COMMUNITY.roadMin) continue;
        const r = this.row(wk.key);
        out.push({ k: wk.key, kind: wk.kind, ...(r.name ? { name: r.name } : {}), by: wk.by, h: r.h, u: r.u, f: r.f, len: wk.len, at: wk.at });
      }
      return out;
    };
    if (this.listTab === 'near') {
      lines = nearLines();
      lines.sort((a, b) => b.h - a.h || b.u - a.u || b.len! - a.len!);
      lines = lines.slice(0, COMMUNITY.worldTop);
    } else if (this.listTab === 'friends') {
      // your friends' works: whatever of theirs is on the server's lists, and in the counties round you
      const ids = this.friendIds();
      const seen = new Set<string>();
      lines = [...(this.lists?.loved ?? []), ...(this.lists?.busy ?? []), ...(this.lists?.fresh ?? []), ...nearLines()]
        .filter((l) => ids.has(l.by) && !seen.has(l.k) && !!seen.add(l.k));
      lines.sort((a, b) => b.h - a.h || b.u - a.u);
      lines = lines.slice(0, COMMUNITY.worldTop);
    } else lines = this.lists?.[this.listTab] ?? [];
    const rows = lines.map((l, n) => {
      const who = this.online.people.get(l.by);
      const dot = who?.brand ? `<i class="dot" style="background:${hex(who.brand.primary)}"></i>` : '';
      const size = isFeature(l.kind) ? `${l.len ?? 0} lifts` : l.kind === 'path' ? `${l.len ?? 0} fleets` : l.len ? `${l.len} tiles` : '';
      const bits = [esc(WORK_LABEL[l.kind]), l.parts && l.parts > 1 ? `${l.parts} works` : '', size, l.by === this.me ? 'yours' : `<span data-pid="${esc(l.by)}">${esc(this.online.fleetName(l.by))}</span>`, l.u ? `${l.u.toLocaleString('en-US')} crossing${l.u === 1 ? '' : 's'}` : ''].filter(Boolean);
      return `<li><span class="rank">${n + 1}</span><span class="what">${dot}<b>${KIND_ICON[l.kind]} ${esc(this.lineTitle(l))}</b><small>${bits.join(' · ')}</small></span>`
        + `<span class="pay hrt">♥ ${l.h}</span><button type="button" class="link" data-fly="${esc(l.k)}">Fly there</button></li>`;
    }).join('');
    const s = this.stats;
    const empty = this.listTab === 'friends' ? (this.friendIds().size ? 'Nothing of your friends’ on the lists or in the counties round you yet.' : 'No friends yet: add one from their card.') : this.listTab === 'near' ? 'Nothing built by players in the counties round you yet.' : this.lists ? 'Nothing here yet: build a bridge, dig a canal or wear in a shortcut.' : 'Asking the server…';
    return `<div class="worldtab"><div class="scope">${tab('loved', 'Most loved')}${tab('busy', 'Busiest')}${tab('fresh', 'Newest')}${tab('near', 'Near me')}</div>`
      + `<div class="lead">Likes to spend: <b class="hrt">♥ ${(s.likes ?? 0).toLocaleString('en-US')}</b> · your works: <b class="hrt">♥ ${s.loved}</b> · ${s.uses.toLocaleString('en-US')} crossing${s.uses === 1 ? '' : 's'} · ${s.works} built · ${s.listed} listed · ${s.blazed} track${s.blazed === 1 ? '' : 's'} blazed</div>`
      + (rows ? `<ul class="people">${rows}</ul>` : `<p class="none">${empty}</p>`)
      + `<p class="foot">Click a bridge, a road or its plaque to see who built it. <kbd>L</kbd> leaves a heart on another player’s work as you drive over it; with ${COMMUNITY.listedAt} it is listed and only its builder can bulldoze it. Ground that five fleets have worn wears into a dirt track for everyone.</p></div>`;
  }

  /** Town card: the most loved works in the town's county. */
  /** Each work's town, as worked out once (a work is replaced, never changed, when its island's works are). */
  private workTown = new WeakMap<Work, number>();

  /**
   * The town a work belongs to (docs/townregister.html): the one whose lines hold the most of its tiles, if that is a
   * third of them or more; -1 for none (a long road between towns belongs to nobody).
   */
  townOfWork(wk: Work): number {
    const had = this.workTown.get(wk);
    if (had !== undefined) return had;
    const town = townOfTiles(wk.tiles, wk.w.townId);
    this.workTown.set(wk, town);
    return town;
  }

  /** A town's works with their hearts and crossings, and the totals; null when its island is not in memory. */
  townWorks(townKey: string): { list: { wk: Work; h: number; u: number }[]; hearts: number; uses: number; builders: number } | null {
    const [cell, id] = townKey.split('#');
    const [cx, cz] = cellOfKey(cell);
    const w = this.host.islands()?.at(cx, cz);
    if (!w) return null;
    const tid = Number(id);
    const list = [...this.worksOf(w).works.values()]
      .filter((wk) => wk.kind !== 'path' && wk.kind !== 'hq' && (wk.kind !== 'road' || wk.len >= COMMUNITY.roadMin) && this.townOfWork(wk) === tid)
      .map((wk) => { const r = this.row(wk.key); return { wk, h: r.h, u: r.u }; });
    return {
      list, hearts: list.reduce((s, x) => s + x.h, 0), uses: list.reduce((s, x) => s + x.u, 0),
      builders: new Set(list.map((x) => x.wk.by)).size,
    };
  }

  /** The town card's Works list (docs/townregister.html): a town's works, by hearts, crossings or newest first. */
  townWorksHtml(townKey: string, by: 'hearts' | 'uses' | 'new'): string {
    const tw = this.townWorks(townKey);
    if (!tw || !tw.list.length) return '';
    const list = [...tw.list].sort((a, b) => (by === 'hearts' ? b.h - a.h || b.u - a.u : by === 'uses' ? b.u - a.u || b.h - a.h : b.wk.at - a.wk.at));
    const who = (by: string) => (by === this.me || !this.on ? 'yours' : `<span data-pid="${esc(by)}">${esc(this.online.fleetName(by))}</span>`);
    return `<div class="built">${list.slice(0, 12).map(({ wk, h, u }) => `<div class="u"><b>${KIND_ICON[wk.kind]} ${esc(this.title(wk))}</b> <span>${who(wk.by)} · ♥ ${h}${u ? ` · ${u} crossing${u === 1 ? '' : 's'}` : ''}</span></div>`).join('')}</div>`
      + (list.length > 12 ? `<p class="note">and ${list.length - 12} more</p>` : '');
  }

  builtHere(townKey: string): string {
    if (!this.on) return '';
    const k = townKey.split('#')[0];
    const [cx, cz] = cellOfKey(k);
    const w = this.host.islands()?.at(cx, cz);
    if (!w) return '';
    const list = [...this.worksOf(w).works.values()]
      .filter((wk) => wk.kind !== 'road' || wk.len >= COMMUNITY.roadMin)
      .sort((a, b) => this.row(b.key).h - this.row(a.key).h || this.row(b.key).u - this.row(a.key).u).slice(0, 5);
    if (!list.length) return '';
    return `<h4>Built here</h4><div class="built">${list.map((wk) => {
      const r = this.row(wk.key);
      return `<div class="u"><b>${KIND_ICON[wk.kind]} ${esc(this.title(wk))}</b> <span>${wk.by === this.me ? 'yours' : `<span data-pid="${esc(wk.by)}">${esc(this.online.fleetName(wk.by))}</span>`} · ♥ ${r.h}${r.u ? ` · ${r.u} crossing${r.u === 1 ? '' : 's'}` : ''}</span></div>`;
    }).join('')}</div>`;
  }

  /** The inspector's card for a building that is another player's HQ: a heart for it. */
  hqHtml(lotKey: string): string {
    if (!this.on) return '';
    const d = this.online.deeds.get(lotKey);
    if (!d || d.hq === undefined) return '';
    const r = this.row(lotKey);
    if (d.by === this.me) return `<p class="note">Your HQ · <b class="hrt">♥ ${r.h}</b> from other players</p>`;
    const on = this.hearts.has(lotKey);
    return `<div class="acts hqheart"><span><b class="hrt">♥ ${r.h}</b> · ${esc(this.online.fleetName(d.by))}’s HQ</span><button type="button" data-heart="${esc(lotKey)}" class="${on ? 'on heart' : 'heart'}">${on ? '♥ Hearted' : '♥ Leave a heart'}</button></div>`;
  }
}
