import { DIRS, N, type Building, type World } from '../world/tiles';
import { hashString, mulberry32 } from '../world/rng';
import { cellKind, crossingAt, landBorder, straitAt } from '../world/macro';
import { modelDims, seatsOf, stadiumPlanOf, stadiumToIsland, type Act } from '../world/stadiums';
import { builtShare } from '../render/townMesh';
import { kerbNear } from './fleet';
import { VEHICLES, type VehicleDef } from './vehicles';
import { TRAFFIC_VIEW, type Agent, type Traffic } from './traffic';
import { actsOf, crowdFor, ticketPrice, tourName, type TourAct } from './leagues';

/**
 * The tours (docs/stadiums.html covers the stadiums themselves). An act from the world's pool (game/leagues.ts) goes
 * out on a tour of the stadiums: a show at one, then — a little while after the crowd has gone home — the
 * tour bus and the stage trucks pull out of the car park and drive, as real traffic, to the stadium in the
 * next town over, where the next show is a couple of game days later. A show waits for its convoy: if the
 * trucks are late in, the show is put back to the evening after they have had time to set up.
 *
 * Where the convoy is near the camera it is three real vehicles (game/traffic.ts `launchTour`) driving on
 * the roads, over county lines (the cells it drives through are pinned in memory by main.ts, as the
 * fleet's convoy's are); out of sight it is a point moving along at a convoy's pace, and it is put back
 * on the road, at a kerb near where that point has got to, when the camera comes near again. Shows are
 * played whether or not anyone is watching (the stadium runtime plays them live when someone is), and
 * every one goes on the act's books, which the save keeps. Convoys are local to each game: online, every
 * player sees their own, as with all ambient traffic.
 */

/** Game hours from leaving one stadium to the next show: "a couple of days later". */
const GAP = 40;
/** Game hours a show needs after its convoy pulls in, and the hour of the evening shows go on. */
const SETUP = 4, EVENING = 20;
/** Game hours after a show before the convoy pulls out; a show nobody saw is reckoned to take SHOW_H. */
const PACK = 2.5, SHOW_H = 6;
/** Out of sight: tiles a game hour, and how much longer than the straight line the road is. */
const OFF_PACE = 28, WANDER = 1.3;
/** The furthest the next stop may be, in a straight line (tiles). */
const MAX_LEG = 2.6 * N;
/** Cells from the camera's that a convoy is driven in; it is put on the road only in the camera's 3x3. */
const REACH = 2;
/** At most this many tours at once, and game hours between one ending and the next setting out. */
const MAX_TOURS = 2, QUIET = 6;
/** The vehicles: the tour bus, then the trucks. */
const RIG: readonly { id: string; role: string }[] = [{ id: 'bus', role: 'Tour bus' }, { id: 'bertha', role: 'Stage truck' }, { id: 'bertha', role: 'Lighting truck' }];
/** Announcements are for someone this near (tiles). */
const HEAR = 200;
/** Real seconds between the convoy's steering checks. */
const TICK = 0.25;

const cellOf = (v: number): number => Math.floor(v / N);
const cheb = (ax: number, az: number, bx: number, bz: number): number => Math.max(Math.abs(ax - bx), Math.abs(az - bz));

/** A stadium on a tour, in world tiles. */
export interface Stop {
  key: string; cx: number; cz: number; uid: number;
  town: string; venue: string;
  /** In front of its gates. */
  x: number; z: number;
  seats: number;
  /** The game hour its show goes on. */
  show: number;
}
/** A show played. */
interface ShowLine { town: string; venue: string; day: number; crowd: number; gross: number; live: boolean }

type TourPhase = 'setup' | 'show' | 'packing' | 'road' | 'home';

interface Rig {
  def: VehicleDef; role: string;
  a: Agent | null; tr: Traffic | null;
  /** Where it is parking, world tiles. */
  spot: { x: number; z: number } | null;
  done: boolean;
  fails: number;
  last: { x: number; z: number };
}

export interface Tour {
  id: number; act: number;
  /** Which of the act's tours (its career before day 0 counted). */
  n: number; name: string;
  /** Shows planned. */
  length: number;
  phase: TourPhase;
  at: Stop;
  next: Stop | null;
  /**
   * Packing up: the stop it will pull out for, booked early because a fleet has been offered the act's ride there
   * (missions/actTemplates.ts), with its show set (Tours.bookNext). Taken as `next` when the convoy pulls out.
   */
  booked?: Stop | null;
  played: ShowLine[];
  /** Packing: when it pulls out. Show: when to give up waiting for the stage. */
  until: number;
  /** The road out of sight: where it was, when, and how far it has to go. */
  from: { x: number; z: number }; leftAt: number; dist: number;
  /** Where the convoy heads when the tour is over. */
  exit: { x: number; z: number } | null;
  rigs: Rig[];
  /** Real seconds a convoy has been waiting to be put on the road out of view. */
  wait: number;
}

/** What an act has done in this world, on top of its career before it. */
interface ActBook { shows: number; tours: number; crowd: number; gross: number; towns: string[]; nights: number }

export interface ToursSave {
  n: number; quiet: number;
  acts: Record<string, ActBook>;
  tours: Omit<Tour, 'rigs' | 'wait'>[];
}

interface TourHost {
  worlds(): World[];
  focus(): { x: number; z: number };
  hours(): number;
  seed(): string;
  trafficOf(w: World): Traffic | null;
  say(title: string, body: string, group?: string): void;
  /** A stadium's name, as its gates say it. */
  venueName(w: World, b: Building): string;
  /**
   * Put the show on now at this stadium if anyone is there to see it: 'live' when it has started (the
   * runtime calls showDone when it ends), 'busy' when a game is still on, 'away' when nobody is near.
   */
  begin(key: string, act: Act, tour: Tour): 'live' | 'busy' | 'away';
}

/** Which tour a vehicle on the road belongs to, for its inspector card. */
const RIGS = new WeakMap<Agent, { tour: Tour; rig: Rig; tours: Tours }>();

/** A vehicle of a tour's convoy, or null: the act, the tour, its part in it and where it is going. */
export function tourRigOf(a: Agent): { act: TourAct; tour: Tour; role: string; doing: string; to: string; from: string } | null {
  const r = RIGS.get(a);
  if (!r) return null;
  const { tour, rig, tours } = r;
  return { act: tours.act(tour.act), tour, role: rig.role, doing: tours.doing(tour, rig), to: tour.next?.town ?? (tour.phase === 'home' ? 'home' : tour.at.town), from: tour.at.town };
}

export class Tours {
  tours: Tour[] = [];
  private books = new Map<number, ActBook>();
  private count = 0;
  private quiet = 0;
  private timer = 0;
  private spawnT = 0;
  private seats = new Map<string, number>();
  private sh = 0;
  private seedFor = '';
  private defs = new Map<string, VehicleDef>();

  constructor(private host: TourHost) {}

  private hash(): number {
    const s = this.host.seed();
    if (s !== this.seedFor) { this.seedFor = s; this.sh = hashString(s); }
    return this.sh;
  }

  acts(): TourAct[] { return actsOf(this.host.seed()); }
  act(id: number): TourAct { return this.acts()[id] ?? this.acts()[0]; }
  book(id: number): ActBook {
    let b = this.books.get(id);
    if (!b) this.books.set(id, (b = { shows: 0, tours: 0, crowd: 0, gross: 0, towns: [], nights: 0 }));
    return b;
  }

  /** Everything an act has done: its career before day 0 and since. */
  lifetime(id: number): { shows: number; tours: number; crowd: number; gross: number; towns: number } {
    const a = this.act(id), b = this.book(id);
    return { shows: a.pastShows + b.shows, tours: a.pastTours + b.tours, crowd: a.pastCrowd + b.crowd, gross: a.pastGross + b.gross, towns: b.towns.length };
  }

  /** The tour playing, booked at or headed for this stadium; else null. */
  at(key: string): Tour | null { return this.tours.find((t) => t.at.key === key || t.next?.key === key || t.booked?.key === key) ?? null; }

  /** The tour nearest a point (world tiles), and how far it is. */
  nearest(x: number, z: number): { tour: Tour; tiles: number } | null {
    let best: { tour: Tour; tiles: number } | null = null;
    for (const t of this.tours) {
      const p = this.posOf(t), d = Math.hypot(p.x - x, p.z - z);
      if (!best || d < best.tiles) best = { tour: t, tiles: d };
    }
    return best;
  }

  /** An act out on a tour right now. */
  touring(id: number): boolean { return this.tours.some((t) => t.act === id); }

  /** The Act a show is put on as: its songs, and this tour's name. */
  showAct(t: Tour): Act { const a = this.act(t.act); return { name: a.name, songs: a.songs, tour: t.name }; }

  // ---- the frame -----------------------------------------------------------------------------------

  update(dt: number): void {
    if (dt <= 0) return;
    const now = this.host.hours();
    this.timer -= dt;
    const tick = this.timer <= 0;
    if (tick) this.timer = TICK;
    this.spawnT -= dt;
    if (this.spawnT <= 0) { this.spawnT = 5; this.spawn(now); }
    for (const t of [...this.tours]) {
      this.progress(t, now);
      if (tick && this.tours.includes(t)) this.drive(t, now, TICK);
    }
  }

  /** Cells to keep in memory with traffic for the convoys on the road near the camera (main.ts pins them). */
  needed(): [number, number][] {
    const out: [number, number][] = [];
    const f = this.host.focus(), fx = cellOf(f.x), fz = cellOf(f.z);
    const add = (cx: number, cz: number) => { if (cheb(cx, cz, fx, fz) <= REACH && !out.some((c) => c[0] === cx && c[1] === cz)) out.push([cx, cz]); };
    for (const t of this.tours) {
      if (!t.rigs.some((r) => r.a)) continue;
      for (const r of t.rigs) {
        if (r.tr?.world) add(r.tr.world.cx, r.tr.world.cz);
        if (r.a) add(r.a.w.cx, r.a.w.cz);
      }
      const goal = t.phase === 'home' ? t.exit : t.next;
      if (goal) add(cellOf(goal.x), cellOf(goal.z));
    }
    return out;
  }

  // ---- the tour --------------------------------------------------------------------------------------

  /** Every stadium standing in memory, as a stop (its show not yet set). */
  private known(): Stop[] {
    const out: Stop[] = [];
    for (const w of this.host.worlds()) {
      for (const b of w.allBuildings) {
        if (b.kind !== 'stadium' || b.gone || builtShare(b) < 1) continue;
        const town = w.towns.find((t) => t.buildings.includes(b));
        if (!town) continue;
        const q = stadiumToIsland(b, 0, modelDims(b).D / 2 + 2);
        out.push({
          key: `${w.cx},${w.cz}#${b.uid}`, cx: w.cx, cz: w.cz, uid: b.uid, town: town.name, venue: this.host.venueName(w, b),
          x: w.ox + q.x, z: w.oz + q.z, seats: this.seatsAt(`${w.cx},${w.cz}#${b.uid}`, b), show: 0,
        });
      }
    }
    return out;
  }

  private seatsAt(key: string, b: Building): number {
    let n = this.seats.get(key);
    if (n === undefined) this.seats.set(key, (n = seatsOf(stadiumPlanOf(b), 0.15, mulberry32(1)).length / 3));
    return n;
  }

  /** A new tour sets out when there is room for one: from the stadium nearest the camera that no tour is using. */
  private spawn(now: number): void {
    if (now < this.quiet || this.tours.length >= MAX_TOURS) return;
    const stops = this.known().filter((s) => !this.tours.some((t) => t.at.key === s.key || t.next?.key === s.key || t.booked?.key === s.key));
    if (!stops.length || (this.tours.length >= 1 && stops.length < 3)) return;
    const free = this.acts().filter((a) => !this.touring(a.id));
    if (!free.length) return;
    const f = this.host.focus();
    stops.sort((a, b) => Math.hypot(a.x - f.x, a.z - f.z) - Math.hypot(b.x - f.x, b.z - f.z));
    const r = mulberry32(hashString(`${this.host.seed()}|tour|${this.count}`));
    const act = free[Math.floor(r() * free.length)];
    const at = { ...stops[Math.min(stops.length - 1, this.tours.length ? 1 : 0)] };
    at.show = evening(now + 3);
    const n = act.pastTours + this.book(act.id).tours + 1;
    const t: Tour = {
      id: ++this.count, act: act.id, n, name: tourName(act, n), length: 4 + Math.floor(r() * 5),
      phase: 'setup', at, next: null, played: [], until: 0, from: { x: at.x, z: at.z }, leftAt: now, dist: 0, exit: null,
      rigs: this.makeRigs(act), wait: 0,
    };
    this.tours.push(t);
    this.near(at) && this.host.say(`🎤 ${act.name}`, `The ${t.name} opens at ${at.venue} · ${dayHour(at.show)}`, at.venue);
  }

  private makeRigs(act: TourAct): Rig[] {
    return RIG.map(({ id, role }) => ({ def: this.liveried(id, act), role, a: null, tr: null, spot: null, done: false, fails: 0, last: { x: 0, z: 0 } }));
  }

  /** The bus and the trucks in the act's colours, one definition an act and model so they share a body. */
  private liveried(id: string, act: TourAct): VehicleDef {
    const key = `${id}|${act.id}`;
    let d = this.defs.get(key);
    if (!d) {
      const base = VEHICLES.find((v) => v.id === id) ?? VEHICLES[0];
      this.defs.set(key, (d = { ...base, color: act.colour, livery: act.alt } as VehicleDef));
    }
    return d;
  }

  /** The tour's clock: shows due, packing done, the road out of sight, and the end. */
  private progress(t: Tour, now: number): void {
    if (t.phase === 'setup' && now >= t.at.show) {
      const res = this.host.begin(t.at.key, this.showAct(t), t);
      if (res === 'live') { t.phase = 'show'; t.until = now + 14; }
      else if (res === 'away' || now > t.at.show + 5) this.played(t, false, Math.max(now, t.at.show + SHOW_H));
    } else if (t.phase === 'show' && now > t.until) {
      this.played(t, false, now);
    } else if (t.phase === 'packing' && now >= t.until) {
      this.depart(t, now);
    } else if (t.phase === 'road' && !t.rigs.some((r) => r.a) && t.next) {
      if (t.dist <= 0 || ((now - t.leftAt) * OFF_PACE) / t.dist >= 1) this.arrive(t, now);
    } else if (t.phase === 'home' && !t.rigs.some((r) => r.a) && now >= t.until) {
      this.finish(t, now);
    }
  }

  /** The show at its stop is over (or was played with nobody near): on the books, and the convoy packs up. */
  private played(t: Tour, live: boolean, ended: number): void {
    if (t.phase !== 'setup' && t.phase !== 'show') return;
    const act = this.act(t.act);
    const crowd = crowdFor(act, t.at.seats, hashString(`${t.at.key}|${t.id}|${t.at.show}`));
    const gross = crowd * ticketPrice(act.draw);
    t.played.push({ town: t.at.town, venue: t.at.venue, day: Math.floor(t.at.show / 24) + 1, crowd, gross, live });
    const b = this.book(t.act);
    b.shows++; b.crowd += crowd; b.gross += gross;
    if (!b.towns.includes(t.at.town)) { b.towns.push(t.at.town); if (b.towns.length > 200) b.towns.shift(); }
    t.phase = 'packing';
    t.until = ended + PACK;
  }

  /** The stadium runtime: the show it put on for this tour has ended (cut short or not). */
  showDone(t: Tour, live: boolean): void {
    if (!this.tours.includes(t) || t.phase !== 'show') return;
    this.played(t, live, this.host.hours());
  }

  /** A one-night show by an act not on tour (a stadium with nothing else on when someone comes by). */
  oneNight(id: number, town: string, seats: number, seed: number): number {
    const act = this.act(id), b = this.book(id);
    const crowd = crowdFor(act, seats, seed);
    b.shows++; b.nights++; b.crowd += crowd; b.gross += crowd * ticketPrice(act.draw);
    if (!b.towns.includes(town)) b.towns.push(town);
    return crowd;
  }

  /**
   * Where the tour goes next, booked now if it is not yet: on the road, the stop it is headed for; packing up after
   * a show, the stop it will pull out for, with its show set, kept for it. A fleet offered the act's ride
   * (missions/actTemplates.ts) needs to know before the convoy leaves. Null when this was the last show, or
   * there is nowhere left to go.
   */
  bookNext(t: Tour): Stop | null {
    if (t.phase === 'road') return t.next;
    if (t.phase !== 'packing' || t.played.length >= t.length) return null;
    if (t.booked && !this.usedBy(t, t.booked.key)) return t.booked;
    const s = this.nextStop(t);
    if (!s) return null;
    s.show = evening(t.until + GAP);
    return (t.booked = s);
  }

  /** Is this stadium another tour's stop, played, headed for or booked? */
  private usedBy(t: Tour, key: string): boolean {
    return this.tours.some((q) => q !== t && (q.at.key === key || q.next?.key === key || q.booked?.key === key));
  }

  /** Pull out for the next town over (the one booked for it, if there is one), or, the tour done (or nowhere left to go), for home. */
  private depart(t: Tour, now: number): void {
    const booked = t.booked && !this.usedBy(t, t.booked.key) ? t.booked : null;
    t.booked = null;
    const next = t.played.length < t.length ? (booked ? { ...booked } : this.nextStop(t)) : null;
    const act = this.act(t.act);
    for (const r of t.rigs) { r.done = false; r.fails = 0; r.spot = null; }
    if (!next) {
      t.phase = 'home';
      t.until = now + 3;
      t.exit = this.exitOf(t);
      this.near(t.at) && this.host.say(`🚌 ${act.name}`, `The ${t.name} is over · ${t.played.length} shows · the convoy heads home`, t.at.venue);
      return;
    }
    // a booked show keeps its date (the act's ride there was promised for it), unless the convoy is too late for it
    next.show = booked ? Math.max(booked.show, evening(now + SETUP)) : evening(now + GAP);
    t.next = next;
    t.phase = 'road';
    t.from = this.posOf(t);
    t.leftAt = now;
    t.dist = Math.hypot(next.x - t.from.x, next.z - t.from.z) * WANDER;
    if (this.near(t.at) || this.near(next)) this.host.say(`🚌 ${act.name} on the road`, `Leaving ${t.at.town} for ${next.venue} · next show ${dayHour(next.show)}`, t.at.venue);
  }

  /**
   * The next town over: the nearest stadium in memory in another town that this tour has not played
   * and no other tour is using, within a couple of counties and with a road there across the lattice.
   */
  private nextStop(t: Tour): Stop | null {
    const done = new Set(t.played.map((p) => p.town));
    const used = new Set(this.tours.filter((q) => q !== t).flatMap((q) => [q.at.key, q.next?.key, q.booked?.key]));
    const list = this.known()
      .filter((s) => s.town !== t.at.town && !done.has(s.town) && !used.has(s.key) && Math.hypot(s.x - t.at.x, s.z - t.at.z) <= MAX_LEG)
      .filter((s) => (s.cx === t.at.cx && s.cz === t.at.cz) || this.step(t.at.cx, t.at.cz, s.cx, s.cz) !== null)
      .sort((a, b) => Math.hypot(a.x - t.at.x, a.z - t.at.z) - Math.hypot(b.x - t.at.x, b.z - t.at.z));
    return list[0] ? { ...list[0] } : null;
  }

  /** In at the next stop: the show goes on as planned, or, late in, the evening after it has had time to set up. */
  private arrive(t: Tour, now: number): void {
    const next = t.next;
    if (!next) return;
    if (next.show < now + SETUP) next.show = evening(now + SETUP);
    t.at = next;
    t.next = null;
    t.phase = 'setup';
    const act = this.act(t.act);
    this.near(next) && this.host.say(`🚌 ${act.name} in town`, `The convoy is in at ${next.venue} · show ${dayHour(next.show)}`, next.venue);
  }

  private finish(t: Tour, now: number): void {
    this.offscreen(t, now);
    this.book(t.act).tours++;
    this.tours = this.tours.filter((q) => q !== t);
    this.quiet = now + QUIET;
  }

  /** Where the convoy is, world tiles: its bus on the road, or its point moving along out of sight. */
  posOf(t: Tour): { x: number; z: number } {
    const bus = t.rigs.find((r) => r.a)?.a;
    if (bus) return { x: bus.w.ox + bus.state.x, z: bus.w.oz + bus.state.z };
    const goal = t.phase === 'road' ? t.next : t.phase === 'home' ? t.exit : null;
    if (!goal || t.dist <= 0) return { x: t.at.x, z: t.at.z };
    const f = Math.min(1, ((this.host.hours() - t.leftAt) * OFF_PACE) / t.dist);
    return { x: t.from.x + (goal.x - t.from.x) * f, z: t.from.z + (goal.z - t.from.z) * f };
  }

  /** Game hours until it is in, out of sight; on the road it is however long the drive takes. */
  eta(t: Tour): number {
    if (t.phase !== 'road' || !t.next) return 0;
    const p = this.posOf(t);
    return (Math.hypot(t.next.x - p.x, t.next.z - p.z) * WANDER) / OFF_PACE;
  }

  /** What one of its vehicles is doing, for its card. */
  doing(t: Tour, rig: Rig): string {
    if (t.phase === 'road') return rig.done ? `Parked at ${t.next?.venue ?? 'the stadium'}, waiting for the others` : `On the road to ${t.next?.town ?? 'the next town'} · ≈ ${Math.max(1, Math.round(this.eta(t)))} h`;
    if (t.phase === 'home') return 'The tour is over: heading home';
    if (t.phase === 'packing') return `Loading up after the show · pulls out ${clockOf(t.until)}`;
    if (t.phase === 'show') return 'The show is on';
    return `Parked at ${t.at.venue} · show ${dayHour(t.at.show)}`;
  }

  // ---- the convoy ----------------------------------------------------------------------------------

  private worldAt(cx: number, cz: number): World | null { return this.host.worlds().find((w) => w.cx === cx && w.cz === cz) ?? null; }

  /** Put the convoy on the road, keep it going, or take it off the road when it is out of reach. */
  private drive(t: Tour, now: number, dt: number): void {
    const p = this.posOf(t), f = this.host.focus();
    const pcx = cellOf(p.x), pcz = cellOf(p.z), fx = cellOf(f.x), fz = cellOf(f.z);
    const on = t.rigs.some((r) => r.a);
    if (on) {
      const keep = cheb(pcx, pcz, fx, fz) <= REACH && t.rigs.every((r) => !r.a || (r.tr && r.tr.world && this.host.trafficOf(r.tr.world) === r.tr));
      if (!keep) { this.offscreen(t, now); return; }
      this.steer(t, now);
      return;
    }
    // off the road: back on it only in the camera's own 3x3, where the cell is already in memory
    if (t.phase === 'home' || t.phase === 'show' || cheb(pcx, pcz, fx, fz) > 1) { t.wait = 0; return; }
    const w = this.worldAt(pcx, pcz), tr = w ? this.host.trafficOf(w) : null;
    if (!w || !tr) return;
    // parked at a stadium it may simply be there; on the road it is put down out of view if it can be
    if (t.phase === 'road') {
      t.wait += dt;
      if (TRAFFIC_VIEW.on && t.wait < 20 && inView(p.x, p.z)) return;
    }
    this.materialize(t, w, tr, p);
  }

  private materialize(t: Tour, w: World, tr: Traffic, p: { x: number; z: number }): void {
    const taken: { x: number; z: number }[] = [];
    const goal = t.phase === 'road' ? t.next! : t.at;
    const heading = Math.atan2(goal.x - p.x, goal.z - p.z);
    const lx = p.x - w.ox, lz = p.z - w.oz;
    const spots: { x: number; z: number }[] = [];
    for (let k = 0; k < t.rigs.length; k++) {
      const s = kerbNear(w, lx, lz, t.phase === 'road' ? 24 : 14, taken);
      if (!s) break;
      taken.push(s);
      spots.push(s);
    }
    if (!spots.length) return;
    t.wait = 0;
    t.rigs.forEach((r, k) => {
      const s = spots[Math.min(k, spots.length - 1)];
      if (k >= spots.length) return;
      const a = tr.launchTour(r.def, s.x, s.z, heading);
      if (!a) return;
      r.a = a; r.tr = tr; r.last = { x: w.ox + s.x, z: w.oz + s.z };
      // parked at the stadium where it was put down, or on its way
      r.done = t.phase !== 'road';
      r.spot = t.phase === 'road' ? null : { ...r.last };
      RIGS.set(a, { tour: t, rig: r, tours: this });
    });
  }

  /** Take the convoy off the road, its point carrying on out of sight from where the bus had got to. */
  private offscreen(t: Tour, now: number): void {
    const p = this.posOf(t);
    for (const r of t.rigs) {
      if (r.a && r.tr) r.tr.dropTour(r.a);
      r.a = null; r.tr = null;
    }
    if (t.phase === 'road' && t.next) {
      t.from = p;
      t.leftAt = now;
      t.dist = Math.hypot(t.next.x - p.x, t.next.z - p.z) * WANDER;
    }
  }

  /** Each vehicle on to where it is going next: a door over the next county line, or its bay at the stadium. */
  private steer(t: Tour, now: number): void {
    // a truck still coming in after the bus has arrived keeps on for its bay
    const goal = t.phase === 'road' ? t.next : t.phase === 'home' ? t.exit : t.at;
    for (const r of t.rigs) {
      if (!r.a || !r.tr) continue;
      const a = r.a;
      if (!r.tr.agents.includes(a)) {
        // the traffic gave up on it (stuck fast and nobody to tow it): back on the road at a kerb near where it was
        RIGS.delete(a);
        r.a = null;
        if (++r.fails > 3) { this.offscreen(t, now); return; }
        const w = this.worldAt(cellOf(r.last.x), cellOf(r.last.z)), tr = w ? this.host.trafficOf(w) : null;
        const k = w && kerbNear(w, r.last.x - w.ox, r.last.z - w.oz, 10);
        const b = tr && k ? tr.launchTour(r.def, k.x, k.z, a.state.heading) : null;
        if (!b || !w) { this.offscreen(t, now); return; }
        r.a = b; r.tr = tr;
        RIGS.set(b, { tour: t, rig: r, tours: this });
        continue;
      }
      r.last = { x: a.w.ox + a.state.x, z: a.w.oz + a.state.z };
      if (!goal || r.done || a.phase !== 'parked') continue;
      // its bay at the stadium (or the door it leaves by), kept apart from the others'
      if (!r.spot) r.spot = this.bayFor(t, r, goal);
      if (!r.spot) continue;
      if (Math.hypot(r.last.x - r.spot.x, r.last.z - r.spot.z) < 2.5) { r.done = true; continue; }
      const aim = this.legTarget(a.w, r.spot);
      if (!aim) continue;
      if (!r.tr.driveOwned(a, aim.x - a.w.ox, aim.z - a.w.oz)) {
        if (++r.fails > 3) { this.offscreen(t, now); return; }
      }
    }
    // in when the tour bus has pulled up at the stadium (the act is aboard it)
    if (t.phase === 'road' && (t.rigs[0].done || !t.rigs[0].a)) this.arrive(t, now);
    if (t.phase === 'home' && (t.rigs.every((r) => r.done || !r.a) || now > t.until + 6)) this.finish(t, now);
  }

  /** A kerb near the goal for this vehicle, apart from where the others are parking. */
  private bayFor(t: Tour, r: Rig, goal: { x: number; z: number }): { x: number; z: number } | null {
    const w = this.worldAt(cellOf(goal.x), cellOf(goal.z));
    if (!w) return null;
    const taken = t.rigs.filter((q) => q !== r && q.spot).map((q) => ({ x: q.spot!.x - w.ox, z: q.spot!.z - w.oz }));
    const k = kerbNear(w, goal.x - w.ox, goal.z - w.oz, 14, taken) ?? kerbNear(w, goal.x - w.ox, goal.z - w.oz, 24);
    return k ? { x: w.ox + k.x, z: w.oz + k.z } : null;
  }

  /** Where to drive from a vehicle's own cell for the goal: straight there when it is this cell or next door, else the door into the next cell on the way. */
  private legTarget(aw: World, goal: { x: number; z: number }): { x: number; z: number } | null {
    const gx = cellOf(goal.x), gz = cellOf(goal.z);
    if (Math.abs(gx - aw.cx) + Math.abs(gz - aw.cz) <= 1) return goal;
    const step = this.step(aw.cx, aw.cz, gx, gz);
    if (!step) return goal;
    const nb = this.worldAt(step[0], step[1]);
    // the next cell is being built (it is pinned, so it will come): wait a moment
    if (!nb) return null;
    let d = -1;
    for (let k = 0; k < 4; k++) if (DIRS[k][0] === aw.cx - nb.cx && DIRS[k][1] === aw.cz - nb.cz) d = k;
    const st = nb.straits.find((s) => s.dir === d);
    const cross = st ? st.at : (crossingAt(this.hash(), nb.cx, nb.cz, d)[0]?.at ?? N / 2);
    const bx = d === 0 ? N - 1.5 : d === 2 ? 1.5 : cross + 0.5;
    const bz = d === 1 ? N - 1.5 : d === 3 ? 1.5 : cross + 0.5;
    const k = kerbNear(nb, bx, bz, 24) ?? { x: bx, z: bz };
    return { x: nb.ox + k.x, z: nb.oz + k.z };
  }

  /** The first cell on the way from one county to another over land (a county road or a causeway), or null. */
  private step(ax: number, az: number, bx: number, bz: number): [number, number] | null {
    if (ax === bx && az === bz) return null;
    const sh = this.hash();
    const key = (x: number, z: number) => `${x},${z}`;
    const back = new Map<string, string>([[key(ax, az), '']]);
    const open: [number, number][] = [[ax, az]];
    for (let h = 0; h < open.length && h < 200; h++) {
      const [cx, cz] = open[h];
      if (cx === bx && cz === bz) break;
      for (let d = 0; d < 4; d++) {
        const nx = cx + DIRS[d][0], nz = cz + DIRS[d][1];
        if (back.has(key(nx, nz)) || cheb(nx, nz, ax, az) > 4) continue;
        if (cellKind(sh, nx, nz) === 'sea' || !(landBorder(sh, cx, cz, d) || straitAt(sh, cx, cz, d) >= 0)) continue;
        back.set(key(nx, nz), key(cx, cz));
        open.push([nx, nz]);
      }
    }
    if (!back.has(key(bx, bz))) return null;
    let at = key(bx, bz);
    while (back.get(at) !== key(ax, az)) {
      const prev = back.get(at);
      if (!prev) return null;
      at = prev;
    }
    const [x, z] = at.split(',').map(Number);
    return [x, z];
  }

  /** Where a convoy leaves the county by when its tour is over: the nearest land border's crossing, just over it. */
  private exitOf(t: Tour): { x: number; z: number } | null {
    const sh = this.hash(), cx = t.at.cx, cz = t.at.cz;
    let best: { x: number; z: number } | null = null, bestD = Infinity;
    for (let d = 0; d < 4; d++) {
      if (!landBorder(sh, cx, cz, d) && straitAt(sh, cx, cz, d) < 0) continue;
      const at = crossingAt(sh, cx, cz, d)[0]?.at ?? N / 2;
      const lx = d === 0 ? N + 3 : d === 2 ? -3 : at + 0.5, lz = d === 1 ? N + 3 : d === 3 ? -3 : at + 0.5;
      const p = { x: cx * N + lx, z: cz * N + lz };
      const dd = Math.hypot(p.x - t.at.x, p.z - t.at.z);
      if (dd < bestD) { bestD = dd; best = p; }
    }
    return best;
  }

  private near(s: { x: number; z: number }): boolean {
    const f = this.host.focus();
    return Math.hypot(s.x - f.x, s.z - f.z) < HEAR;
  }

  // ---- the save --------------------------------------------------------------------------------------

  toSave(): ToursSave {
    const acts: Record<string, ActBook> = {};
    for (const [id, b] of this.books) if (b.shows || b.tours) acts[id] = { ...b, towns: [...b.towns] };
    const now = this.host.hours();
    return {
      n: this.count, quiet: this.quiet, acts,
      tours: this.tours.map((t) => {
        // the convoy is written down where it has got to, and goes on from there out of sight
        const p = this.posOf(t);
        const dist = t.phase === 'road' && t.next ? Math.hypot(t.next.x - p.x, t.next.z - p.z) * WANDER : t.dist;
        const { rigs: _r, wait: _w, ...rest } = t;
        return { ...rest, from: p, leftAt: t.phase === 'road' ? now : t.leftAt, dist, played: t.played.map((s) => ({ ...s })) };
      }),
    };
  }

  fromSave(s: ToursSave | undefined): void {
    this.clear();
    this.books.clear();
    this.count = s?.n ?? 0;
    this.quiet = s?.quiet ?? 0;
    for (const [id, b] of Object.entries(s?.acts ?? {})) this.books.set(Number(id), { shows: b.shows ?? 0, tours: b.tours ?? 0, crowd: b.crowd ?? 0, gross: b.gross ?? 0, towns: [...(b.towns ?? [])], nights: b.nights ?? 0 });
    for (const t of s?.tours ?? []) {
      // a show that was on when it was saved is over by the time it is loaded
      const phase = t.phase === 'show' ? 'packing' : t.phase;
      this.tours.push({ ...t, phase, until: t.phase === 'show' ? 0 : t.until, rigs: this.makeRigs(this.act(t.act)), wait: 0 });
    }
  }

  /** Take every convoy off the road (the world is going away). */
  clear(): void {
    const now = this.host.hours();
    for (const t of this.tours) this.offscreen(t, now);
    this.tours = [];
  }

  /** Console: one line a tour. */
  list(): string[] {
    return this.tours.map((t) => {
      const p = this.posOf(t);
      return `${this.act(t.act).name} · ${t.name} · ${t.phase} · at ${t.at.town}${t.next ? ` → ${t.next.town} (show ${dayHour(t.next.show)})` : ` (show ${dayHour(t.at.show)})`}`
        + ` · ${t.played.length}/${t.length} played · convoy ${t.rigs.filter((r) => r.a).length ? 'on the road' : 'out of sight'} @ ${Math.round(p.x)},${Math.round(p.z)}`;
    });
  }

  /** Console: the next stage of every tour now (a show played, a convoy pulled out, a convoy in). */
  hurry(): string[] {
    const now = this.host.hours();
    for (const t of this.tours) {
      if (t.phase === 'setup') t.at.show = now;
      else if (t.phase === 'packing') t.until = now;
      else if (t.phase === 'road') { this.offscreen(t, now); t.leftAt = now - t.dist / OFF_PACE - 1; }
    }
    return this.list();
  }
}

/** The first EVENING hour at or after `h`. */
function evening(h: number): number {
  const day = Math.floor(h / 24);
  const at = day * 24 + EVENING;
  return at >= h ? at : at + 24;
}

/** "day 3, 20:00". */
export function dayHour(h: number): string { return `day ${Math.floor(h / 24) + 1}, ${clockOf(h)}`; }
export function clockOf(h: number): string {
  const t = ((h % 24) + 24) % 24, hh = Math.floor(t), mm = Math.floor((t - hh) * 60);
  return `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
}

function inView(x: number, z: number): boolean {
  const f = TRAFFIC_VIEW.frustum;
  // a generous sphere round the point: nothing pops into a corner of the screen either
  for (const p of f.planes) if (p.normal.x * x + p.normal.y * 1 + p.normal.z * z + p.constant < -6) return false;
  return true;
}
