/**
 * The Surveyor's Commission (docs/exploration.html, phase 3; 0.7.0 behind NEXT_WORLD): Ada Marchetti, the county
 * surveyor, pays you to push further from home. An eight-step arc (Over the Hill to The Far Shore) and three
 * repeatable trips, all waiting at her diamond by the hall of your home town; once Salt Air is done the trips
 * wait at any far town's hall too, more than FAR tiles from home, where she is the county surveyor of wherever you
 * are. Two objective kinds carry it: `range` (this drive's honest distance from home, game/range.ts) and
 * `discover` (cells the fleet has never set foot in).
 */
import { N, type World, type Town } from '../../world/tiles';
import { cellKind, cellName } from '../../world/macro';
import { hashString } from '../../world/rng';
import { NEXT_WORLD } from '../../world/nextWorld';
import { ALL_VEHICLES } from '../vehicles';
import { money } from '../cargoHud';
import type { MissionCtx, Missions } from './missions';
import type { Arc, Giver, HeroSpec, Obj, PlaceRef, Reward } from './model';
import { squareOf, townRef, type Draft, type Template } from './templates';

const SURVEY_ARC_ID = 'survey';
const STEPS = ['survey:hill', 'survey:three', 'survey:salt', 'survey:chart', 'survey:four', 'survey:long', 'survey:first', 'survey:far'];
export const SURVEY_ARC: Arc = { id: SURVEY_ARC_ID, title: 'The Surveyor’s Commission', thread: 'car', who: 'Ada Marchetti', tpls: STEPS };

/** A far town's hall offers the repeatable trips once it is this many tiles from home. */
export const FAR = 1500;
/** Survey Run asks for this much more than the overall record, and pays this a tile of the point's distance. */
export const RUN_STRETCH = 1.4;
const RUN_PAY = 0.15;
/** Long Way Round's point is at least this far from home. */
const LONG = 2500;
const SURVEY_ORANGE = 0xf28c28;

const kindOf = (model: string) => ALL_VEHICLES.find((d) => d.id === model)?.kind;
const owns = (c: MissionCtx, kind: string) => c.units.some((u) => kindOf(u.model) === kind);

/** The town nearest a point among those in memory, and how far it is. */
function townNear(c: MissionCtx, x: number, z: number): { w: World; t: Town; d: number } | null {
  let best: { w: World; t: Town; d: number } | null = null;
  for (const w of c.worlds) for (const t of w.towns) {
    const d = Math.hypot(w.ox + t.x0 + t.size / 2 - x, w.oz + t.z0 + t.size / 2 - z);
    if (!best || d < best.d) best = { w, t, d };
  }
  return best;
}

/** Ada at the hall of the town nearest home (she keeps her office there), when it is in memory. */
function homeDesk(c: MissionCtx): Giver | null {
  const r = c.range;
  if (!r) return null;
  const n = townNear(c, r.home[0], r.home[1]);
  if (!n || n.d > 160) return null;
  return { who: 'surveyor', name: 'Ada Marchetti', at: squareOf(n.w, n.t, 'the town hall'), town: townRef(n.w, n.t) };
}

/** For the trips: her home desk, or the hall of the far town the player is nearest, FAR tiles and more from home. */
function anyDesk(c: MissionCtx): Giver | null {
  const r = c.range;
  if (!r) return null;
  const n = townNear(c, c.at.x, c.at.z);
  if (n && n.d < 200 && Math.hypot(n.w.ox + n.t.x0 + n.t.size / 2 - r.home[0], n.w.oz + n.t.z0 + n.t.size / 2 - r.home[1]) >= FAR) {
    return { who: 'surveyor', name: 'Ada Marchetti', at: squareOf(n.w, n.t, 'the town hall'), town: townRef(n.w, n.t) };
  }
  return homeDesk(c);
}

/**
 * A point on dry land about `d` tiles from home, the way the fleet has been least: the compass eighth with the
 * fewest cells set foot in, ties settled by `h`. The middle of the land cell there, its county named.
 */
export function surveyPoint(c: MissionCtx, d: number, h: number): PlaceRef | null {
  const r = c.range;
  if (!r) return null;
  const [hx, hz] = r.home, hc = [Math.floor(hx / N), Math.floor(hz / N)];
  const seen = [0, 0, 0, 0, 0, 0, 0, 0];
  for (const k of r.found) {
    const [cx, cz] = k.split(',').map(Number);
    if (cx === hc[0] && cz === hc[1]) continue;
    seen[((Math.round(Math.atan2(cx - hc[0], cz - hc[1]) / (Math.PI / 4)) % 8) + 8) % 8]++;
  }
  const order = [0, 1, 2, 3, 4, 5, 6, 7].sort((a, b) => seen[a] - seen[b] || ((a * 7 + h) % 8) - ((b * 7 + h) % 8));
  const sh = hashString(c.seed);
  for (const e of order) {
    const a = (e * Math.PI) / 4;
    // out along that eighth, a cell further at a time, until the ground is land
    for (let more = 0; more < 4; more++) {
      const x = hx + Math.sin(a) * (d + more * N), z = hz + Math.cos(a) * (d + more * N);
      const cx = Math.floor(x / N), cz = Math.floor(z / N), kind = cellKind(sh, cx, cz);
      if (kind === 'sea') continue;
      const name = cellName(sh, cx, cz, kind);
      return { x: cx * N + N / 2, z: cz * N + N / 2, cell: [cx, cz], name: `the survey mark in ${name.replace(/^the /, '')}` };
    }
  }
  return null;
}

/** Which arc step comes next, and is this it? */
const at = (ms: Missions, id: string) => (ms.arcs?.get(SURVEY_ARC_ID) ?? 0) === STEPS.indexOf(id);
/** Is the 0.7.0 world on, a home known, and the first drive's lessons done? */
function ready(c: MissionCtx, ms: Missions): string | null {
  if (!NEXT_WORLD) return 'the 0.7.0 world';
  if (!c.range) return 'no home yet';
  if (ms.learning?.()) return 'after the first drive';
  return null;
}

const hero = {
  map: { kind: 'stamp' } as HeroSpec,
  trophy: { kind: 'trophy' } as HeroSpec,
};
const tiles = (n: number) => `${n.toLocaleString('en-US')} tiles`;
const rangeObj = (n: number, label: string, kind?: 'land' | 'water' | 'air', icon = '🧭'): Obj => ({ t: 'range', label, icon, tiles: n, kind });
const cash = (n: number): Reward => ({ r: 'cash', n });

/** One of the arc's steps: its gate and a card from Ada's home desk. */
function step(id: string, needs: (c: MissionCtx) => string | null, card: (c: MissionCtx, g: Giver, h: number) => Omit<Draft, 'giver'> | null): Template {
  return {
    id, thread: 'car', kind: 'trip', arc: SURVEY_ARC_ID,
    gate(c, ms) { return ready(c, ms) ?? (at(ms, id) ? needs(c) : 'not its turn'); },
    bind(c, h) {
      const g = homeDesk(c);
      const d = g && card(c, g, h);
      return g && d ? { ...d, giver: g } : null;
    },
  };
}

const hill = step('survey:hill', () => null, () => ({
  title: 'Over the Hill', why: 'The county surveyor wants to know how far your fleet gets. Take anything 400 tiles from home and she pays.',
  details: 'Ada Marchetti has run the county survey for thirty years, and nobody in the office has been past the next hill. She keeps a pin where your fleet began and a ring for the furthest you have been: both are on the map now (M).',
  hero: hero.map, caption: 'A county surveyor’s map',
  objs: [rangeObj(400, 'Reach 400 tiles from home')], reward: [cash(150)],
}));

const three = step('survey:three', () => null, () => ({
  title: 'Three Counties', why: 'Set foot in three cells your fleet has never been in. Ada wants the roads checked against her sheets.',
  details: 'The survey sheets were drawn from the air in a hurry. Ada wants somebody on the ground in three new places to say whether the roads are where the sheets say they are.',
  hero: hero.map, caption: 'Three survey sheets',
  objs: [{ t: 'discover', label: 'Find 3 new cells', icon: '🗺️', n: 3 }], reward: [cash(300)],
}));

const salt = step('survey:salt', (c) => (owns(c, 'water') ? null : 'a boat in the fleet'), () => ({
  title: 'Salt Air', why: 'The coast has not been surveyed since the war. Take a boat 800 tiles from home and Ada tunes its engine.',
  details: 'The charts of the coast are older than Ada, and she does not trust a line on them. A boat taken far out along it settles a dozen of her arguments with the harbourmasters.',
  hero: { kind: 'part', slot: 'engine', tier: 2 }, caption: 'A Stage 2 engine',
  objs: [rangeObj(800, 'Take a boat 800 tiles out', 'water', '⛵')], reward: [cash(400), { r: 'part', slot: 'engine', tier: 2 }],
}));

const chart = step('survey:chart', () => null, () => ({
  title: 'Charting', why: 'Set foot in six new cells within eight hours. The survey office closes its books at the end of the day.',
  details: 'The year’s survey is due, and Ada is six sheets short. Anything will do: drive, sail or fly, as long as the fleet has never been there.',
  hero: hero.map, caption: 'Six blank sheets',
  objs: [{ t: 'discover', label: 'Find 6 new cells', icon: '🗺️', n: 6 }], reward: [cash(600)], hours: 8,
}));

const four = step('survey:four', (c) => (owns(c, 'air') ? (owns(c, 'water') ? null : 'a boat in the fleet') : 'an aircraft in the fleet'), () => ({
  title: 'Four Ways', why: 'Take something 1,000 tiles from home on land, then on water, then in the air. Ada gives you her Scrambler.',
  details: 'Ada surveyed on foot, by boat and from a borrowed biplane. Her old Scrambler, Theodolite, still has the tyres she fitted for the moors.',
  hero: { kind: 'vehicle', model: 'atv' }, caption: 'Theodolite, the surveyor’s ATV',
  objs: [rangeObj(1000, 'Reach 1,000 tiles by land', 'land', '🚙'), rangeObj(1000, 'Reach 1,000 tiles by water', 'water', '⛵'), rangeObj(1000, 'Reach 1,000 tiles by air', 'air', '✈️')],
  reward: [{ r: 'vehicle', model: 'atv', parts: { t: { tyres: [0, 2] }, spent: 0 }, name: 'Theodolite' }],
}));

const long = step('survey:long', () => null, (c, _g, h) => {
  const p = surveyPoint(c, LONG, h);
  if (!p) return null;
  const far = Math.round(Math.hypot(p.x - c.range!.home[0], p.z - c.range!.home[1]));
  return {
    title: 'Long Way Round', why: `A survey mark ${tiles(far)} from home has never been checked. Get to it, any way you like.`,
    details: `It is the way your fleet has been least. Ada set the mark from an aeroplane in her first year and never got back to it.`,
    hero: hero.map, caption: 'An unchecked survey mark',
    objs: [{ t: 'reach', label: 'Reach the survey mark', icon: '📍', at: p, r: 14 }], reward: [cash(1500)],
  };
});

const first = step('survey:first', () => null, () => ({
  title: 'First Footing', why: 'Set foot in twelve cells your fleet has never been in. Ada paints your fleet in the survey’s own orange.',
  details: 'The survey office’s vans were orange so a farmer could see them coming across three fields. Twelve new cells and Ada says your fleet has earned the colour.',
  hero: hero.map, caption: 'Survey Orange',
  objs: [{ t: 'discover', label: 'Find 12 new cells', icon: '🗺️', n: 12 }], reward: [cash(1000), { r: 'livery', colour: SURVEY_ORANGE, name: 'Survey Orange' }],
}));

const farShore = step('survey:far', () => null, () => ({
  title: 'The Far Shore', why: 'Take anything 5,000 tiles from home. Ada signs your commission as the county’s own surveyor.',
  details: 'Nobody from the county has been that far out and come back to say so. Ada has kept the commission in a drawer for years, waiting for somebody to sign it for.',
  hero: hero.trophy, caption: 'The surveyor’s commission',
  objs: [rangeObj(5000, 'Reach 5,000 tiles from home')], reward: [cash(5000)],
}));

/** One of the trips: open once Salt Air is done, at her home desk or a far hall, on its own cooldown. */
function trip(id: string, cooldown: number, needs: (c: MissionCtx) => string | null, card: (c: MissionCtx, g: Giver, h: number) => Omit<Draft, 'giver'> | null): Template {
  return {
    id, thread: 'car', kind: 'trip', side: true, cooldown,
    gate(c, ms) { return ready(c, ms) ?? ((ms.arcs?.get(SURVEY_ARC_ID) ?? 0) > STEPS.indexOf('survey:salt') ? needs(c) : 'after Salt Air'); },
    bind(c, h) {
      const g = anyDesk(c);
      const d = g && card(c, g, h);
      return g && d ? { ...d, giver: g } : null;
    },
  };
}

const run = trip('survey:run', 36, () => null, (c, _g, h) => {
  const want = Math.max(600, Math.round(c.range!.all * RUN_STRETCH));
  const p = surveyPoint(c, want, h);
  if (!p) return null;
  const far = Math.round(Math.hypot(p.x - c.range!.home[0], p.z - c.range!.home[1]));
  const pay = Math.max(50, Math.round((far * RUN_PAY) / 10) * 10);
  return {
    title: 'Survey Run', why: `Check a survey mark ${tiles(far)} from home, further than you have been. Ada pays ${money(pay)}.`,
    details: 'Every run pushes the county’s map out a little. Ada picks a mark beyond anywhere your fleet has been, the way it has been least.',
    hero: hero.map, caption: 'A survey mark',
    objs: [{ t: 'reach', label: 'Reach the survey mark', icon: '📍', at: p, r: 14 }], reward: [cash(pay)],
  };
});

/** A model the fleet owns that has never been taken a thousand tiles from home (and can leave its line). */
function untried(c: MissionCtx, h: number): { id: string; name: string } | null {
  const seen = new Set<string>();
  const list = c.units.filter((u) => {
    const k = kindOf(u.model);
    if (!k || k === 'rail' || seen.has(u.model) || (c.range!.model[u.model] ?? 0) >= 1000) return false;
    seen.add(u.model);
    return true;
  });
  const u = list.length ? list[h % list.length] : null;
  return u ? { id: u.model, name: ALL_VEHICLES.find((d) => d.id === u.model)?.name ?? u.name } : null;
}

const shake = trip('survey:shake', 24, (c) => (untried(c, 0) ? null : 'every model run in'), (c, _g, h) => {
  const m = untried(c, h);
  if (!m) return null;
  return {
    title: 'Shakedown', why: `Take your ${m.name} 1,000 tiles from home. Ada adds ${money(150)} to what running it in pays.`,
    details: `Ada keeps a page for every vehicle in the county, and the ${m.name}’s is blank. A thousand tiles out fills it in.`,
    hero: { kind: 'vehicle', model: m.id }, caption: `Your ${m.name}`,
    objs: [{ t: 'range', label: `Take it 1,000 tiles out`, icon: '🧭', tiles: 1000, model: m.id, mname: m.name }], reward: [cash(150)],
  };
});

const spot = trip('survey:spot', 48, () => null, () => ({
  title: 'Spot Check', why: 'Set foot in four cells your fleet has never been in, within six hours. Ada checks her sheets against yours.',
  details: 'A spot check keeps the survey honest. Four new places, quickly, before the sheets go to print.',
  hero: hero.map, caption: 'Four sheets to check',
  objs: [{ t: 'discover', label: 'Find 4 new cells', icon: '🗺️', n: 4 }], reward: [cash(350)], hours: 6,
}));

export const SURVEY_TEMPLATES: Template[] = [hill, three, salt, chart, four, long, first, farShore, run, shake, spot];
