import { cargoById, type CargoType } from '../cargoTypes';
import { chainsShown } from './shown';
import type { CargoItem, Site } from '../cargo';
import type { Building, World } from '../../world/tiles';
import type { Deed, Estate } from '../estate';
import { gradeOf } from '../hqGrade';
import { CHAINS, CHAIN_NAME, hoursOf, inputsOf, outputsOf, pedigreeMul, recipeBook, recipesOf, takersOf, type Recipe } from './recipes';
import { deeds } from '../deeds';
import { press } from '../press/desk';
import { freshPlant, type Plant, type Stock } from './plantState';
import { madeScale } from './value';
import { SITE_GOODS } from '../cargo';
import { builtShare } from '../../render/townMesh';

/**
 * Plants (docs/supplychains.html): every building the player owns whose kind is in the recipe book makes goods.
 * The clock runs in game hours wherever the building is, and is capped at a full stock; the loads themselves are put
 * at the kerb only while the island is in memory, held for the player's fleet for one period and then opened to the
 * island. Anything delivered to the door that a recipe takes in fills its bin, whoever drove it; only the fleet's own
 * made loads carry pedigree in. The plant takes a maker's fee on every load it made, whoever delivers it.
 */

export interface PlantHost {
  /** The game clock, in hours. */
  hours(): number;
  /** The site goods are fetched from at this building, while its island is in memory. */
  siteOf(w: World, b: Building): Site | null;
  /** Put a made load at the kerb, bound for the best place that wants it; null when nowhere in reach does. */
  produce(from: Site, t: CargoType, made: { key: string; steps: number; scale: number }, own: (s: Site) => number): CargoItem | null;
  /** Where a load is now. */
  where(id: number): 'ground' | 'aboard' | 'gone';
  /** Let the island's haulers take this load now. */
  open(id: number): void;
  /** How keen the fleet's models are on a kind (game/affinity.ts keenestOf), for a base plant's draw. */
  keen(t: CargoType): number;
  /** A gold card in the earnings ticker. */
  ticker(icon: string, head: string, body: string): void;
  /** Something a card shows changed. */
  changed(): void;
  /** Money for the player beyond a load's own pay (a site finished, a crowd that came for what the venue held), floated at a spot. */
  bonus?(amount: number, text: string, x: number, y: number, z: number): void;
  /** A launch pad of the fleet's has sent a satellite up (chain 23): the rocket goes, the county sees it. */
  launched?(key: string): void;
  /** What a building would sell for, for a site's completion bonus. */
  priceOf?(w: World, b: Building): number;
}

/** A delivery that finishes a quarter of what is left of a building site (chain 5), and the share of its price paid when one completes it. */
const SITE_SHARE = 0.25, SITE_BONUS = 0.1;
/** A people load delivered to a venue of the fleet's holding what draws them pays this much more (chains 12, 20, 22). */
const CROWD_BONUS = 0.25;
/** What a venue holds that draws a crowd, by the people it draws. */
const DRAWS: Record<string, string> = { matchCrowd: 'programmes', fans: 'programmes', raceFans: 'racehorse', orchestra: 'instruments', jazzBand: 'instruments' };
/** The launch fee: this share of a pad's price (its rent ceiling times nine), each launch. */
const LAUNCH_FEE = 0.1;

/** What the card shows of one plant. */
export interface PlantView {
  key: string;
  chain: string;
  recipes: Recipe[];
  base: boolean;
  /** What it makes, by id; what it takes in, by slot, with what is in the bin. */
  makes: string[];
  slots: { ids: string[]; n: number; have: number; cap: number }[][];
  /** The run in hand (or the base clock): share done and game hours left; null when waiting. */
  run: { out: string; steps: number; done: number; left: number } | null;
  /** Why it is not running, when it is not. */
  waiting: string;
  stock: { id: string; steps: number; placed: boolean; open: boolean; openIn: number }[];
  set: string;
  period: number;
  made: number; fed: number; fees: number; missed: number; opened: number;
  derelict: boolean;
}

const SWEEP = 1;

export class Plants {
  private sweep = 0;
  /** Made loads standing at a kerb: load id → deed key. */
  private placed = new Map<number, string>();
  /** The last time each plant's made load could find nowhere to go, for the card. */
  private stuck = new Map<string, string>();

  constructor(private estate: Estate, private host: PlantHost) {}

  /**
   * Fetching (docs/supplychains.html): set by main.ts. `fetch` puts the nearest free hired vehicle on these inputs
   * for this plant, or takes it off if one already is (returns why not, or null); `fetchers` names who is on it.
   */
  fetch: ((key: string, ids: string[]) => string | null) | null = null;
  fetchers: ((key: string) => { name: string; ids: string[] }[]) | null = null;

  /** A deed's plant, made fresh the first time it is asked for (a building bought before plants existed has none saved). */
  plantOf(d: Deed): Plant | null {
    if (!d.key.includes('#b') || !recipesOf(d.kind).length) return null;
    d.plant ??= freshPlant(this.host.hours());
    return d.plant;
  }

  private gradeAt(key: string, d: Deed): number {
    const r = this.estate.resolve(key);
    return r ? gradeOf(r.b).grade : this.gradeCache.get(d.kind) ?? 2;
  }
  private gradeCache = new Map<string, number>();

  /** The recipe a plant runs next, or would: the set kind's if it is set, else the first. */
  private recipeFor(d: Deed, p: Plant): Recipe | null {
    const rs = recipesOf(d.kind);
    if (!rs.length) return null;
    if (p.run) return rs[p.run.r] ?? rs[0];
    if (p.set) { const k = rs.findIndex((r) => r.makes.some((m) => m.id === p.set)); if (k >= 0) return rs[k]; }
    const ready = rs.find((r) => r.takes.length && this.full(p, r));
    return ready ?? rs[0];
  }

  /** How many units of an input its bin keeps: enough for CHAINS.binRuns runs of the hungriest recipe. */
  private capOf(kind: string, id: string): number {
    let n = 1;
    for (const r of recipesOf(kind)) for (const s of r.takes) if (s.ids.includes(id)) n = Math.max(n, s.n);
    return n * CHAINS.binRuns;
  }

  /** Units in hand for one slot (any of its ids). */
  private have(p: Plant, s: { ids: string[] }): number {
    let n = 0;
    for (const id of s.ids) n += p.bins[id]?.length ?? 0;
    return n;
  }

  private full(p: Plant, r: Recipe): boolean {
    return r.takes.every((s) => this.have(p, s) >= s.n);
  }

  /** Take a run's inputs out of the bins, best pedigree first; returns the steps the run's output carries. */
  private consume(p: Plant, r: Recipe): number {
    let best = 0;
    for (const s of r.takes) {
      for (let k = 0; k < s.n; k++) {
        // the unit with the most pedigree, from whichever of the slot's ids holds it
        let pick = '', at = -1, v = -1;
        for (const id of s.ids) {
          const l = p.bins[id];
          if (!l) continue;
          for (let j = 0; j < l.length; j++) if (l[j] > v) { v = l[j]; pick = id; at = j; }
        }
        if (at < 0) continue;
        p.bins[pick].splice(at, 1);
        best = Math.max(best, v);
      }
    }
    return best;
  }

  /** One of a recipe's outputs, by weight: a base plant leans to what the fleet's models are keen on; a set plant makes its kind. */
  private draw(r: Recipe, set: string): string {
    if (set && r.makes.some((m) => m.id === set)) return set;
    const ws = r.makes.map((m) => {
      const t = cargoById(m.id);
      return m.w * (r.takes.length || !t ? 1 : Math.max(0.5, this.host.keen(t)));
    });
    let x = Math.random() * ws.reduce((a, b) => a + b, 0);
    for (let k = 0; k < ws.length; k++) { x -= ws[k]; if (x <= 0) return r.makes[k].id; }
    return r.makes[r.makes.length - 1].id;
  }

  private finish(d: Deed, p: Plant, r: Recipe, out: string, steps: number, at: number): void {
    p.stock.push({ id: out, steps, at, load: 0, out: 0 });
    p.made++;
    deeds.add('plantsMade');
    // the paper (docs/newspaper.html): a plant's 50th, 250th and 1,000th load is news in its town
    if ((p.made === 50 || p.made === 250 || p.made === 1000) && chainsShown()) {
      const goods = cargoById(out)?.name.toLowerCase() ?? 'goods';
      press.write({ k: 'plantRun', who: 'you', town: d.townKey || undefined, f: { building: d.name, town: d.town, count: p.made, goods }, w: p.made >= 250 ? 3 : undefined });
    }
    // a launch (chain 23): the satellite goes up, the county sees it, and the pad takes its fee
    if (d.kind === 'launchPad' && out === 'telemetry') {
      this.host.launched?.(d.key);
      const fee = Math.round(d.ceil * 9 * LAUNCH_FEE);
      p.fees += this.estate.makerFee(d.key, fee, { x: d.x, y: 0, z: d.z } as Site);
    }
    for (const a of r.also ?? []) if (Math.random() < a.chance && p.stock.length < CHAINS.stock + 1) p.stock.push({ id: a.id, steps, at, load: 0, out: 0 });
  }

  /** Run a plant's clock forward `h` game hours. */
  private advance(d: Deed, p: Plant, h: number, now: number): void {
    const rs = recipesOf(d.kind);
    if (!rs.length || h <= 0) return;
    const grade = this.gradeAt(d.key, d);
    if (!rs[0].takes.length) {
      // a base plant: its clock alone, held while the kerb is full
      const r = rs[0];
      const period = hoursOf(r, grade, !!p.set);
      if (p.stock.length >= CHAINS.stock) { p.clock = Math.min(p.clock, period); return; }
      p.clock += h;
      while (p.clock >= period && p.stock.length < CHAINS.stock) {
        p.clock -= period;
        this.finish(d, p, r, this.draw(r, p.set), 0, now);
      }
      if (p.stock.length >= CHAINS.stock) p.clock = Math.min(p.clock, period);
      return;
    }
    // a plant with inputs: run what is in hand, then start the next run whose set is in the bins
    let left = h;
    for (let guard = 0; guard < 64; guard++) {
      if (p.run) {
        p.run.left -= left;
        if (p.run.left > 0) return;
        if (p.stock.length >= CHAINS.stock) { p.run.left = 0; return; }
        left = -p.run.left;
        const r = rs[p.run.r] ?? rs[0];
        this.finish(d, p, r, p.run.out, p.run.steps, now);
        p.run = null;
      }
      if (p.stock.length >= CHAINS.stock) return;
      let k = -1;
      if (p.set) k = rs.findIndex((r) => r.makes.some((m) => m.id === p.set) && this.full(p, r));
      if (k < 0 && !p.set) k = rs.findIndex((r) => this.full(p, r));
      if (k < 0) return;
      const r = rs[k];
      const inSteps = this.consume(p, r);
      p.run = { r: k, out: this.draw(r, p.set), steps: inSteps, left: hoursOf(r, grade, !!p.set) };
      if (left <= 0) return;
    }
  }

  /** A load delivered anywhere, by anybody (the ledger's one call per delivery): a plant's input, or a made load paying its maker. */
  delivered(it: CargoItem, player: boolean): void {
    const to = it.to;
    // a building site under its cranes (docs/supplychains.html, chain 5): a quarter of what is left goes up at once
    const sb = to.b;
    if (sb && sb.grownAt !== undefined && SITE_GOODS.has(it.type.id) && builtShare(sb) < 1) {
      const left = (1 - builtShare(sb)) * (sb.buildHours ?? 2);
      // the last quarter's worth tops it out
      sb.grownAt -= left <= 0.5 ? left + 0.01 : left * SITE_SHARE;
      // the delivery that tops it out pays a share of what the building is worth, to whoever's fleet brought it
      if (player && builtShare(sb) >= 1 && this.host.priceOf) {
        const fee = Math.round(this.host.priceOf(to.w, sb) * SITE_BONUS);
        if (fee > 0) this.host.bonus?.(fee, 'Topped out', to.x, to.y + 1.2, to.z);
      }
    }
    // a crowd at a venue of the fleet's that holds what draws them (programmes, a racehorse, instruments)
    const draws = DRAWS[it.type.id];
    if (player && draws && to.b && to.port < 0) {
      const v = this.estate.deeds.get(`${to.w.cx},${to.w.cz}#b${to.b.uid}`)?.plant;
      if (v && (v.bins[draws]?.length ?? 0) > 0) {
        const extra = Math.round(it.value * CROWD_BONUS);
        if (extra > 0) this.host.bonus?.(extra, 'The crowd came', to.x, to.y + 1, to.z);
      }
    }
    // an input at a plant of the player's: into the bin
    if (to.b && to.b.uid >= 0 && to.port < 0) {
      const key = `${to.w.cx},${to.w.cz}#b${to.b.uid}`;
      const d = this.estate.deeds.get(key);
      const p = d ? this.plantOf(d) : null;
      if (d && p && inputsOf(d.kind).has(it.type.id)) {
        const l = (p.bins[it.type.id] ??= []);
        if (l.length < this.capOf(d.kind, it.type.id)) {
          // pedigree comes in only with the fleet's own made goods, delivered by the fleet
          l.push(player && it.made && this.estate.deeds.has(it.made.key) ? it.made.steps + 1 : 0);
          p.fed++;
          this.host.changed();
        }
      }
    }
    // made goods with two steps of the fleet's own making behind them, delivered by the fleet (the Made by You deed)
    if (player && it.made && it.made.steps >= 2) deeds.add('pedigreed');
    // a made load: the plant that made it takes its fee
    if (it.made) {
      const d = this.estate.deeds.get(it.made.key);
      const p = d ? this.plantOf(d) : null;
      // gone from its kerb's books now, not at the next sweep (a save in between would put it out again)
      const k = p ? p.stock.findIndex((s) => s.load === it.id) : -1;
      if (p && k >= 0) { p.stock.splice(k, 1); this.placed.delete(it.id); }
      if (d && p) {
        // its own allowance a game day: CHAINS.feeCeil times the deed's rent ceiling
        const day = Math.floor(this.host.hours() / 24);
        if (p.feeDay !== day) { p.feeDay = day; p.feeToday = 0; }
        const fee = Math.min(Math.round(it.value * CHAINS.makerFee), Math.floor(d.ceil * CHAINS.feeCeil - (p.feeToday ?? 0)));
        const paid = fee > 0 ? this.estate.makerFee(it.made.key, fee, it.to) : 0;
        p.feeToday = (p.feeToday ?? 0) + paid;
        p.fees += paid;
      }
    }
  }

  /** A made load went stale on the ground (cargo.ts's expiry): counted against its plant. */
  expired(it: CargoItem): void {
    if (!it.made) return;
    this.placed.delete(it.id);
    const d = this.estate.deeds.get(it.made.key);
    if (!d?.plant) return;
    const k = d.plant.stock.findIndex((s) => s.load === it.id);
    if (k >= 0) d.plant.stock.splice(k, 1);
    d.plant.missed++;
  }

  /** How a candidate destination ranks for a made load: 3 a plant of the fleet's that takes it in, 2 another door of the fleet's, 0 anybody's. */
  private ownRank(id: string): (s: Site) => number {
    const takers = new Set(takersOf(id));
    return (s: Site) => {
      if (!s.b || s.b.uid < 0 || s.port >= 0) return 0;
      const d = this.estate.deeds.get(`${s.w.cx},${s.w.cz}#b${s.b.uid}`);
      if (!d) return 0;
      return takers.has(d.kind) ? 3 : 2;
    };
  }

  update(dt: number): void {
    this.sweep -= dt;
    if (this.sweep > 0) return;
    this.sweep = SWEEP;
    const now = this.host.hours();
    let any = false;
    // loads standing at a kerb whose plant has gone (sold, razed, lost): the island's now
    for (const [id, key] of [...this.placed]) {
      if (this.estate.deeds.get(key)?.plant) continue;
      this.placed.delete(id);
      if (this.host.where(id) === 'ground') this.host.open(id);
    }
    for (const d of this.estate.deeds.values()) {
      const p = this.plantOf(d);
      if (!p) continue;
      const r = this.estate.resolve(d.key);
      if (r) this.gradeCache.set(d.kind, gradeOf(r.b).grade);
      if (r && !this.seenWorlds.has(r.w)) { this.seenWorlds.add(r.w); for (const q of r.w.allBuildings ?? []) if (q && !q.gone) this.stands.add(q.kind); }
      const h = Math.max(0, now - p.at);
      p.at = now;
      // boarded up makes nothing: the clock is frozen until it is mended
      if (r?.b.derelict) continue;
      const before = p.stock.length + p.made;
      this.advance(d, p, h, now);
      if (p.stock.length + p.made !== before) any = true;
      // the kerb: what is aboard someone is taken, what is gone while the island is here went stale, what has waited a period opens
      const period = this.periodOf(d, p);
      for (let k = p.stock.length - 1; k >= 0; k--) {
        const s = p.stock[k];
        if (!s.load) continue;
        const where = this.host.where(s.load);
        if (where === 'ground') {
          if (!s.open && now - s.out >= period * CHAINS.openAfter) { this.host.open(s.load); s.open = true; p.opened++; any = true; }
          continue;
        }
        this.placed.delete(s.load);
        // its island went away with it on the ground: it is put out again on return
        if (where === 'gone' && !r) { s.load = 0; continue; }
        p.stock.splice(k, 1);
        any = true;
      }
      if (!r) continue;
      const site = this.host.siteOf(r.w, r.b);
      if (!site) continue;
      for (const s of p.stock) {
        if (s.load) continue;
        const t = cargoById(s.id);
        if (!t) { s.load = -1; continue; }
        const it = this.host.produce(site, t, { key: d.key, steps: s.steps, scale: madeScale(s.id) }, this.ownRank(s.id));
        if (!it) { this.stuck.set(d.key, `${t.icon} ${t.name}: nowhere in reach wants it`); continue; }
        this.stuck.delete(d.key);
        s.load = it.id;
        s.out = now;
        if (s.open) this.host.open(it.id);
        this.placed.set(it.id, d.key);
        this.host.ticker(t.icon, `${d.name} made ${t.name}`, s.steps ? `Made by you · ${s.steps} step${s.steps === 1 ? '' : 's'}` : CHAIN_NAME[recipesOf(d.kind)[0].chain] ?? 'Your plant');
        any = true;
      }
      // a stock entry whose kind this build has no cargo for is dropped
      p.stock = p.stock.filter((s) => s.load !== -1);
    }
    if (any) this.host.changed();
    // the Vertical deed: chains of which the fleet owns a plant of every kind (those that stand in this world)
    if ((this.wholeT -= SWEEP) <= 0) {
      this.wholeT = 10;
      const kinds = new Set([...this.estate.deeds.values()].map((d) => d.kind));
      const by = new Map<number, string[]>();
      for (const [kind, rs] of recipeBook()) for (const r of rs) { const l = by.get(r.chain) ?? []; if (!l.includes(kind)) l.push(kind); by.set(r.chain, l); }
      let whole = 0;
      for (const l of by.values()) {
        const standing = l.filter((k) => this.stands.has(k));
        if (standing.length >= 2 && standing.every((k) => kinds.has(k))) whole++;
      }
      if (whole) deeds.best('chainsWhole', whole);
    }
  }

  /** Building kinds seen standing in the worlds the fleet's plants stand in (the Vertical deed counts only kinds the world has). */
  private stands = new Set<string>();
  private seenWorlds = new WeakSet<World>();
  private wholeT = 0;

  /** A plant's period (game hours a run or a base load takes) as it stands now. */
  periodOf(d: Deed, p: Plant): number {
    const r = this.recipeFor(d, p);
    return r ? hoursOf(r, this.gradeAt(d.key, d), !!p.set) : 0;
  }

  /** Fix a plant to one of its outputs ('' for any). Returns why not, or null. */
  setKind(key: string, id: string): string | null {
    const d = this.estate.deeds.get(key);
    const p = d ? this.plantOf(d) : null;
    if (!d || !p) return 'Not a plant of yours';
    if (id && !outputsOf(d.kind).includes(id)) return 'It doesn’t make that';
    p.set = id;
    // a base plant's clock starts again at the new pace; a run in hand finishes as it was
    this.host.changed();
    return null;
  }

  /** Everything the card needs about one deed's plant, or null when it is no plant. */
  view(key: string): PlantView | null {
    const d = this.estate.deeds.get(key);
    const p = d ? this.plantOf(d) : null;
    if (!d || !p) return null;
    const rs = recipesOf(d.kind);
    const base = !rs[0].takes.length;
    const period = this.periodOf(d, p);
    const now = this.host.hours();
    const r = this.estate.resolve(key);
    let run: PlantView['run'] = null;
    let waiting = '';
    if (base) {
      if (p.stock.length >= CHAINS.stock) waiting = 'The kerb is full: it waits until a load is taken';
      else run = { out: p.set || '', steps: 0, done: Math.min(1, p.clock / Math.max(0.01, period)), left: Math.max(0, period - p.clock) };
    } else if (p.run) {
      const full = hoursOf(rs[p.run.r] ?? rs[0], this.gradeAt(key, d), !!p.set);
      if (p.run.left <= 0) waiting = 'Finished, waiting for room at the kerb';
      run = { out: p.run.out, steps: p.run.steps, done: Math.min(1, 1 - p.run.left / Math.max(0.01, full)), left: Math.max(0, p.run.left) };
    } else {
      const want = (p.set ? rs.filter((q) => q.makes.some((m) => m.id === p.set)) : rs)[0] ?? rs[0];
      const short = want.takes.filter((s) => this.have(p, s) < s.n).map((s) => s.ids.map((id) => cargoById(id)?.name.toLowerCase() ?? id).join(' or '));
      waiting = p.stock.length >= CHAINS.stock ? 'The kerb is full: it waits until a load is taken' : `Waiting for ${short.join(' and ') || 'its inputs'}`;
    }
    const stuck = this.stuck.get(key);
    if (stuck && !waiting) waiting = stuck;
    return {
      key, chain: CHAIN_NAME[rs[0].chain] ?? '', recipes: rs, base, makes: outputsOf(d.kind),
      slots: rs.map((q) => q.takes.map((s) => ({ ids: s.ids, n: s.n, have: this.have(p, s), cap: s.ids.reduce((m, id) => Math.max(m, this.capOf(d.kind, id)), 0) }))),
      run, waiting,
      stock: p.stock.map((s) => ({ id: s.id, steps: s.steps, placed: s.load > 0, open: !!s.open, openIn: s.load > 0 && !s.open ? Math.max(0, s.out + period * CHAINS.openAfter - now) : 0 })),
      set: p.set, period, made: p.made, fed: p.fed, fees: p.fees, missed: p.missed, opened: p.opened, derelict: !!r?.b.derelict,
    };
  }

  /** Every plant the fleet holds, for the HQ window and the console. */
  all(): PlantView[] {
    const out: PlantView[] = [];
    for (const d of this.estate.deeds.values()) { const v = this.view(d.key); if (v) out.push(v); }
    return out;
  }

  // ---- the console: pr.plants ----

  console() {
    return {
      list: () => this.all().map((v) => ({ key: v.key, chain: v.chain, makes: v.makes.join(','), run: v.run ? `${v.run.out || 'base'} ${(v.run.done * 100).toFixed(0)}%` : v.waiting, stock: v.stock.map((s) => s.id).join(','), made: v.made, fed: v.fed, fees: v.fees })),
      /** Fill a plant's clock (and a run in hand) to the brim: its next load is made on the next sweep. */
      hurry: (key: string) => {
        const d = this.estate.deeds.get(key);
        const p = d ? this.plantOf(d) : null;
        if (!d || !p) return 'not a plant';
        if (!recipesOf(d.kind)[0].takes.length) p.clock = this.periodOf(d, p) * CHAINS.stock;
        if (p.run) p.run.left = 0;
        this.sweep = 0;
        return `${d.name}: due now`;
      },
      /** Put inputs in a plant's bin by hand, as if delivered (steps of pedigree each). */
      feed: (key: string, id: string, n = 1, steps = 0) => {
        const d = this.estate.deeds.get(key);
        const p = d ? this.plantOf(d) : null;
        if (!d || !p) return 'not a plant';
        if (!inputsOf(d.kind).has(id)) return `${d.kind} doesn’t take ${id}`;
        const l = (p.bins[id] ??= []);
        for (let k = 0; k < n && l.length < this.capOf(d.kind, id); k++) { l.push(steps); p.fed++; }
        this.sweep = 0;
        return `${d.name}: ${id} × ${l.length}`;
      },
      view: (key: string) => this.view(key),
      set: (key: string, id: string) => this.setKind(key, id) ?? 'ok',
      placed: () => [...this.placed],
      /** Pedigree's value multiplier for n steps. */
      pedigree: (n: number) => pedigreeMul(n),
    };
  }
}

/** The stock entries of a plant, for anything that wants to look without the class. */
export type { Stock };
