/**
 * The factions' introductions (docs/factions.html, "Getting to know them"): one five-step chain for each
 * faction, open from Neutral once the player has met it, that builds the bar toward Friend. Each runs the
 * same way:
 *
 *   1. who they are: a word with their contact at the hall, and a first job of their own cargo
 *   2. a faction they like: work done with an ally, so the player sees a favour spill across
 *   3. a faction they don't: work done against a rival, so the player sees what it costs on the other side
 *   4. their story: what the faction is in the middle of
 *   5. their leader: a meeting with the one at the top, at an hour of their choosing, and the job that ends it
 *
 * What each step pays the faction is in factions/wire.ts (RISE_REP): about a Friend's worth over the five.
 */
import { FACTIONS, RUNG, type FactionId } from '../factions/factions';
import { reputation } from '../factions/reputation';
import type { MissionCtx, Missions } from './missions';
