import { findSpot, meet, the, type Spot } from './story/kit';
import type { Draft, Template } from './templates';
import { GIVER, LEADER, giverAt, hall, hero, job } from './factionTemplates';
import { strongholdSpot } from './strongholdAim';
import { NEXT_080 } from '../../world/nextWorld';

interface RiseStep {
  title: string;
  /** The giver's line on the card. */
  why: string;
  /** The story behind it: who the faction is, who it likes and doesn't, and its leader. */
  details: string;
  /** The objectives, bound near the faction's hall; a null among them and the step waits for a better place. */
  build(c: MissionCtx, hall: Spot): (Obj | null)[];
  /** Objectives the step can do without (a first job where the hall has none of its cargo near). */
  optional?: boolean;
}

/** A meeting at the nearest of `kinds`, or at the hall when there are none near. */
function at(c: MissionCtx, s: Spot, kinds: string[], label: string, icon: string, o: Parameters<typeof meet>[3] = {}): Obj {
  const p = findSpot(c, kinds, s, 320, the) ?? s;
  return meet(p, label, icon, o);
}

