const arcId = (f: FactionId) => `rise-${f}`;
const riseTpl = (f: FactionId, i: number) => `rise:${f}:${i + 1}`;
/** How many steps each chain has. */
const RISE_STEPS = 5;

function riseStep(f: FactionId, i: number): Template {
  const d = FACTIONS[f];
  const step = CHAINS[f][i];
  return {
    id: riseTpl(f, i), thread: 'town', kind: 'job', arc: arcId(f),
    gate(_c: MissionCtx, ms: Missions) {
      if ((ms.arcs?.get(arcId(f)) ?? 0) !== i) return 'not its turn';
      // they come to a player who has met them and isn't on their wrong side
      if (!reputation.met.has(f)) return `hasn’t met ${d.name}`;
      if (reputation.rung(f) < RUNG.neutral) return `${d.name} don’t trust you`;
      return null;
    },
    bind(c: MissionCtx): Draft | null {
      const s = hall(c, f, 320);
      if (!s) return null;
      const built = step.build(c, s);
      // a first step's job may be left out where there is none near; the meeting alone introduces them
      const objs = step.optional ? built.filter((o): o is Obj => !!o) : built;
      if (!objs.length || objs.some((o) => !o)) return null;
      const last = i === RISE_STEPS - 1;
      // the leader comes out to meet the player just outside the stronghold's gate, when it stands in memory (0.8.0):
      // they see the place two rungs before it opens to them (docs/strongholds.html)
      const first = objs[0];
      if (last && NEXT_080 && first && first.t === 'reach') {
        const sp = strongholdSpot(c.seed, c.worlds, f, { x: c.at.x, z: c.at.z }, 'outside');
        if (sp.aim.fixed) objs[0] = { ...first, at: sp.at, r: 6 };
      }
      const giver: Giver = last ? { ...giverAt(f, s), name: LEADER[f] } : giverAt(f, s);
      const pay = (objs as Obj[]).reduce((t, o) => t + (o.t === 'deliver' ? o.value : 0), 0);
      return {
        title: step.title, why: step.why, details: step.details,
        giver, hero: hero(f, s), caption: `${d.icon} ${d.name} · ${i + 1} of ${RISE_STEPS}`,
        objs: objs as Obj[], reward: [{ r: 'cash', n: Math.round((pay * 1.4 + 120 + 80 * i) / 10) * 10 }], hours: 24,
      };
    },
  };
}

export const RISE_TEMPLATES: Template[] = (Object.keys(FACTIONS) as FactionId[]).flatMap((f) => CHAINS[f].map((_, i) => riseStep(f, i)));

export const RISE_ARCS: Arc[] = (Object.keys(FACTIONS) as FactionId[]).map((f) => ({
  id: arcId(f), title: `Meet ${FACTIONS[f].name}`, thread: 'town', who: GIVER[f].name, tpls: CHAINS[f].map((_, i) => riseTpl(f, i)),
}));

