import * as THREE from 'three';

/**
 * Where a meteorite came down (game/meteorites.ts): a scorch on the ground, a low rim of thrown-up earth, and while
 * the stone still lies there an ember in the middle, which glows after dark and cools over its day.
 */

/** One crater: its middle in world units, how hot it still is (1 just fallen, 0 at the end of its day), and whether the stone is still in it. */
export interface Mark { x: number; y: number; z: number; heat: number; stone: boolean }

const MAX = 24;

export class MeteorMarks {
  readonly group = new THREE.Group();
  private scorch: THREE.InstancedMesh;
  private rim: THREE.InstancedMesh;
  private ember: THREE.InstancedMesh;
  private halo: THREE.InstancedMesh;
  private haloMat: THREE.MeshBasicMaterial;
  private m = new THREE.Matrix4();
  private q = new THREE.Quaternion();
  private v = new THREE.Vector3();
  private s = new THREE.Vector3();
  private c = new THREE.Color();

  constructor(scene: THREE.Object3D) {
    this.group.name = 'meteorites';
    const flat = (g: THREE.BufferGeometry) => g.rotateX(-Math.PI / 2);
    this.scorch = new THREE.InstancedMesh(flat(new THREE.CircleGeometry(1, 18)), new THREE.MeshBasicMaterial({
      color: 0x1d1714, transparent: true, opacity: 0.62, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2,
    }), MAX);
    this.rim = new THREE.InstancedMesh(flat(new THREE.TorusGeometry(1, 0.1, 4, 18)), new THREE.MeshStandardMaterial({ color: 0x7a6450, roughness: 1, flatShading: true }), MAX);
    this.ember = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(0.12, 0), new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false }), MAX);
    this.haloMat = new THREE.MeshBasicMaterial({ color: 0xff7a2a, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, toneMapped: false });
    this.halo = new THREE.InstancedMesh(flat(new THREE.CircleGeometry(1, 20)), this.haloMat, MAX);
    for (const m of [this.scorch, this.rim, this.ember, this.halo]) { m.count = 0; m.frustumCulled = false; this.group.add(m); }
    scene.add(this.group);
  }

  /** The craters to show now, and how dark it is (0 day .. 1 night). */
  set(list: Mark[], night: number): void {
    const n = Math.min(MAX, list.length);
    let e = 0;
    for (let i = 0; i < n; i++) {
      const k = list[i];
      this.put(this.scorch, i, k.x, k.y + 0.02, k.z, 0.95, 1, 0.95, i * 1.3);
      this.put(this.rim, i, k.x, k.y + 0.01, k.z, 0.7, 0.35, 0.7, i * 0.7);
      if (!k.stone) continue;
      const pulse = 0.85 + 0.15 * Math.sin(performance.now() / 300 + i * 2);
      this.put(this.ember, e, k.x + 0.32, k.y + 0.06, k.z - 0.18, 1, 0.6, 1, i);
      // white-hot when it has just come down, cooling to a dull red over its day
      this.ember.setColorAt(e, this.c.setHSL(0.02 + 0.08 * k.heat, 1, 0.35 + 0.35 * k.heat * pulse));
      this.put(this.halo, e, k.x, k.y + 0.05, k.z, 0.9 + 0.7 * k.heat, 1, 0.9 + 0.7 * k.heat, 0);
      e++;
    }
    this.scorch.count = this.rim.count = n;
    this.ember.count = this.halo.count = e;
    this.haloMat.opacity = 0.15 + 0.45 * night;
    for (const m of [this.scorch, this.rim, this.ember, this.halo]) m.instanceMatrix.needsUpdate = true;
    if (this.ember.instanceColor) this.ember.instanceColor.needsUpdate = true;
    this.group.visible = n > 0;
  }

  private put(mesh: THREE.InstancedMesh, i: number, x: number, y: number, z: number, sx: number, sy: number, sz: number, turn: number): void {
    this.q.setFromAxisAngle(this.v.set(0, 1, 0), turn);
    this.m.compose(this.v.set(x, y, z), this.q, this.s.set(sx, sy, sz));
    mesh.setMatrixAt(i, this.m);
  }
}
