import * as THREE from 'three';
import { NIGHT } from './nightLights';
import { FLOOR } from '../world/towns';
import type { FarBlock } from './mesher';

/**
 * The distant towns' lit windows (the user, 11 Nov 2026: by night a far town's boxes (render/farTown.ts) stood dark and
 * all of its lights popped in at once as the real buildings loaded). Each box's walls get a skin just off them, and
 * its shader draws a window grid a floor high, each window lit on an evening clock of its own (from dusk, some till
 * late, some all night) the way the real models' windows are (render/nightLights.ts), so a far town lights up through
 * the evening and the real windows come in among lights already there. By day nothing is drawn. Up close the windows
 * are crisp; far off, where a window is smaller than a pixel, a wall glows by how many of its windows would be lit,
 * so they shimmer neither in nor out.
 */

/** A window cell across a wall, tiles. */
const CELL = 0.42;
/** The skin's lift off the wall, so it never fights it. */
const LIFT = 0.012;

let material: THREE.MeshBasicMaterial | null = null;
function windowMaterial(): THREE.MeshBasicMaterial {
  if (material) return material;
  const m = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, depthWrite: false, fog: true, toneMapped: false });
  m.onBeforeCompile = (shader) => {
    shader.uniforms.uNight = NIGHT.uNight;
    shader.uniforms.uHour = NIGHT.uHour;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nattribute vec3 aWin;\nvarying vec3 vWin;')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\nvWin = aWin;');
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', `#include <common>\nuniform float uNight;\nuniform float uHour;\nvarying vec3 vWin;\nconst float CELL_W = ${CELL.toFixed(3)};\nconst float CELL_H = ${FLOOR.toFixed(3)};`)
      .replace('#include <alphatest_fragment>', `
        vec2 g = vec2(vWin.x / CELL_W, vWin.y / CELL_H);
        vec2 cell = floor(g), f = fract(g);
        float h = fract(sin(dot(cell + vec2(vWin.z, vWin.z * 1.7), vec2(12.9898, 78.233))) * 43758.5453);
        float h2 = fract(h * 7.31 + 0.17);
        // the evening clock: on between dusk (17:00 to 21:00) and late (22:30 to 03:30), a third of them not at all
        float hh = uHour < 12.0 ? uHour + 24.0 : uHour;
        float lit = step(17.0 + h2 * 4.0, hh) * step(hh, 22.5 + h * 5.0) * step(h, 0.66);
        float pane = step(0.22, f.x) * step(f.x, 0.78) * step(0.28, f.y) * step(f.y, 0.78);
        // far off a window is under a pixel: the wall glows by its share of lit windows instead
        float far = smoothstep(0.35, 0.9, max(fwidth(g.x), fwidth(g.y)));
        float share = 0.31 * 0.66 * clamp((hh - 17.0) / 4.0, 0.0, 1.0) * clamp((27.5 - hh) / 5.0, 0.0, 1.0);
        float a = mix(pane * lit, share * 1.6, far) * smoothstep(0.15, 0.6, uNight);
        if (a < 0.02) discard;
        diffuseColor.rgb = mix(vec3(1.0, 0.82, 0.52), vec3(0.86, 0.93, 1.0), step(0.82, h2));
        diffuseColor.a = a;
        #include <alphatest_fragment>`);
  };
  material = m;
  return m;
}

/** The window skins of a block of chunks (buildFarBlocks's own chunk order), or null where none has windows. */
export function farWindows(chunks: FarBlock[][]): THREE.Mesh | null {
  const pos: number[] = [], win: number[] = [], runs: number[] = [];
  const quad = (ax: number, az: number, bx: number, bz: number, y0: number, y1: number, nx: number, nz: number, seed: number) => {
    const L = Math.hypot(bx - ax, bz - az);
    const ox = nx * LIFT, oz = nz * LIFT;
    const v = [[ax, y0, az, 0, 0], [bx, y0, bz, L, 0], [bx, y1, bz, L, y1 - y0], [ax, y1, az, 0, y1 - y0]];
    for (const k of [0, 1, 2, 0, 2, 3]) {
      const [x, y, z, u, h] = v[k];
      pos.push(x + ox, y, z + oz);
      win.push(u, h, seed);
    }
  };
  for (const list of chunks) {
    const start = pos.length / 3;
    for (const f of list) {
      const n = f.win ?? 0;
      if (n <= 0) continue;
      const y0 = f.y0 + 0.05, y1 = Math.min(f.y1, y0 + n * FLOOR) - 0.02;
      if (y1 - y0 < FLOOR * 0.6) continue;
      const seed = ((f.x0 * 13.37 + f.z0 * 7.91) % 97) / 9.7;
      // each wall facing out, its own seed so two sides don't light alike
      quad(f.x0, f.z0, f.x1, f.z0, y0, y1, 0, -1, seed);
      quad(f.x1, f.z1, f.x0, f.z1, y0, y1, 0, 1, seed + 3.1);
      quad(f.x0, f.z1, f.x0, f.z0, y0, y1, -1, 0, seed + 5.3);
      quad(f.x1, f.z0, f.x1, f.z1, y0, y1, 1, 0, seed + 7.7);
    }
    runs.push(start, pos.length / 3 - start);
  }
  if (!pos.length) return null;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('aWin', new THREE.Float32BufferAttribute(win, 3));
  g.computeBoundingSphere();
  g.addGroup(0, pos.length / 3, 0);
  const mesh = new THREE.Mesh(g, [windowMaterial()]);
  mesh.userData.chunkRuns = runs;
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  mesh.renderOrder = 2;
  return mesh;
}
