import { GATED, UNLOCKS } from './factions';
import { deeds } from '../deeds';

/**
 * Faction unlocks are the player's for good (docs/factions.html, "Online and saves"): every world they
 * play, online or off, starts with every paintjob and every vehicle they have ever earned on the shelf.
 * Kept in this browser under the player's id, and merged with the copy on their online career when they
 * sign in (src/net), so a second machine catches up the first time it is used.
 */

const KEY = 'tinyfleet-unlocks';

class Unlocks {
  private set = new Set<string>();
  private who = 'local';
  /** Told when something new is unlocked (the server copy, the HQ window). */
  onChange: (ids: string[]) => void = () => {};

  /** The player whose shelf this is: switching players reads theirs. */
  use(player: string): void {
    this.who = player || 'local';
    this.set = new Set(this.read());
  }

  private read(): string[] {
    try {
      const raw = localStorage.getItem(`${KEY}:${this.who}`);
      const v = raw ? JSON.parse(raw) : [];
      return Array.isArray(v) ? v.filter((x) => typeof x === 'string' && UNLOCKS.has(x)) : [];
    } catch { return []; }
  }

  private write(): void {
    try { localStorage.setItem(`${KEY}:${this.who}`, JSON.stringify([...this.set])); } catch { /* not kept */ }
  }

  has(id: string): boolean { return this.set.has(id); }
  list(): string[] { return [...this.set]; }

  /** Unlock one; true if it was new. */
  add(id: string): boolean {
    if (!UNLOCKS.has(id) || this.set.has(id)) return false;
    this.set.add(id);
    deeds.mark('facUnlocks', id);
    this.write();
    this.onChange([id]);
    return true;
  }

  /** Take in another copy (the server's): anything there that isn't here is added; returns what was new. */
  merge(ids: unknown): string[] {
    if (!Array.isArray(ids)) return [];
    const fresh = ids.filter((x): x is string => typeof x === 'string' && UNLOCKS.has(x) && !this.set.has(x));
    for (const id of fresh) this.set.add(id);
    if (fresh.length) { this.write(); this.onChange(fresh); }
    return fresh;
  }

  /** Console: forget everything (testing). */
  clear(): void { this.set.clear(); this.write(); }

  /** Is this paintjob unlocked? */
  hasJob(id: string): boolean { return this.set.has(id); }

  /**
   * May a model be sold to this player? Anything not behind a faction is; a gated one needs its unlock (the
   * faction's own vehicles) or, for the military hardware, the rung now held (`rungNow`).
   */
  modelOpen(model: string, rungNow: (f: string) => number): boolean {
    const g = GATED[model];
    if (!g) return true;
    if (this.set.has(`model:${model}`)) return true;
    return rungNow(g.f) >= g.rung;
  }
}

export const unlocks = new Unlocks();
