import * as THREE from 'three';
import { DIRS, N, STEP, heightAt, idx, type Arch, type Building, type World } from '../world/tiles';
import { buildGhost, disposeGhost } from './ghost';
import { buildVehicleMesh, disposeVehicleMesh, type VehicleMesh } from './vehicleMeshes';
import { defOf } from '../game/fleet';
import { GOLD, GOLD_DEEP } from '../game/passportRewards';

/**
 * What the Passport's treats stand on and beside an HQ (game/treats.ts): the gilded nameplate (the Signature
 * buildings seal), a gold sign with the fleet's name standing on its roof; and the gold statue (the whole book),
 * the fleet's favourite vehicle cast in gold on a stone plinth on a free tile just outside the lot. Both are
 * plain meshes in the scene, placed in world tiles; the game says which HQs have them (`set`), twice a second.
 */

export interface HqDress {
  /** The HQ's key (estate key): one dress an HQ. */
  key: string;
  /** The nameplate: the fleet's name, where the roof's middle is (world tiles), and which way the front looks. */
  plate: { name: string; x: number; y: number; z: number; yaw: number; span: number } | null;
  /** The statue: the vehicle's model, where it stands (world tiles; y the ground) and which way it faces. */
  statue: { model: string; x: number; y: number; z: number; yaw: number } | null;
}

/** Gold, shared by every plate's frame and every statue: a warm metal that still reads without an environment map. */
let goldMat: THREE.MeshStandardMaterial | null = null;
export function goldMaterial(): THREE.MeshStandardMaterial {
  return goldMat ??= new THREE.MeshStandardMaterial({ color: GOLD, metalness: 0.75, roughness: 0.28, emissive: GOLD_DEEP, emissiveIntensity: 0.28 });
}
let stoneMat: THREE.MeshStandardMaterial | null = null;
const stone = (): THREE.MeshStandardMaterial => (stoneMat ??= new THREE.MeshStandardMaterial({ color: 0xd8d2c4, roughness: 0.85 }));

/** The plate's face: the name in gold on deep green enamel, a gold rule round it. */
function plateTexture(name: string): THREE.CanvasTexture {
  const W = 512, H = 128;
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d')!;
  const bg = g.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, '#1d4a3a'); bg.addColorStop(1, '#0f2a20');
  g.fillStyle = bg; g.fillRect(0, 0, W, H);
  g.strokeStyle = '#e8c55a'; g.lineWidth = 6; g.strokeRect(10, 10, W - 20, H - 20);
  g.lineWidth = 2; g.strokeRect(20, 20, W - 40, H - 40);
  let size = 64;
  const font = (s: number) => `700 ${s}px Georgia, "Times New Roman", serif`;
  g.font = font(size);
  while (size > 24 && g.measureText(name).width > W - 70) { size -= 2; g.font = font(size); }
  g.textAlign = 'center'; g.textBaseline = 'middle';
  const gold = g.createLinearGradient(0, H * 0.25, 0, H * 0.75);
  gold.addColorStop(0, '#fff1b0'); gold.addColorStop(0.5, '#e2b84a'); gold.addColorStop(1, '#a8801f');
  g.fillStyle = 'rgba(0,0,0,0.45)'; g.fillText(name, W / 2 + 2, H / 2 + 4);
  g.fillStyle = gold; g.fillText(name, W / 2, H / 2 + 2);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

function buildPlate(name: string, span: number): THREE.Group {
  const g = new THREE.Group();
  const w = Math.max(0.7, Math.min(1.8, span * 0.85)), h = w / 4;
  const frame = new THREE.Mesh(new THREE.BoxGeometry(w + 0.08, h + 0.08, 0.05), goldMaterial());
  frame.position.y = 0.22 + h / 2;
  const tex = plateTexture(name);
  const face = new THREE.MeshStandardMaterial({ map: tex, roughness: 0.45, metalness: 0.1, emissive: 0xffffff, emissiveMap: tex, emissiveIntensity: 0.25 });
  const front = new THREE.Mesh(new THREE.PlaneGeometry(w, h), face);
  front.position.set(0, frame.position.y, 0.027);
  const back = front.clone();
  back.rotation.y = Math.PI;
  back.position.z = -0.027;
  g.add(frame, front, back);
  for (const sx of [-1, 1]) {
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.03, 0.24, 6), goldMaterial());
    post.position.set(sx * w * 0.36, 0.12, 0);
    g.add(post);
  }
  g.traverse((o) => { if ((o as THREE.Mesh).isMesh) o.castShadow = true; });
  return g;
}

/** A statue: the model in gold, scaled to stand on a plinth a tile across. */
function buildStatue(model: string): { g: THREE.Group; mesh: VehicleMesh | null } {
  const g = new THREE.Group();
  const plinth = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.26, 0.5), stone());
  plinth.position.y = 0.15;
  const cap = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.04, 0.56), goldMaterial());
  cap.position.y = 0.3;
  const foot = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.05, 0.62), stone());
  foot.position.y = 0.025;
  plinth.castShadow = cap.castShadow = true;
  plinth.receiveShadow = true;
  g.add(foot, plinth, cap);
  let mesh: VehicleMesh | null = null;
  try {
    const def = defOf(model);
    if (def.kind !== 'rail') mesh = buildVehicleMesh(def);
  } catch { mesh = null; }
  if (mesh) {
    const holder = mesh.holder;
    // every face in gold: the old materials are kept to hand back before the mesh is thrown away
    holder.traverse((o) => {
      const m = o as THREE.Mesh;
      if (!m.isMesh) return;
      m.userData.was = m.material;
      m.material = goldMaterial();
      m.castShadow = true;
    });
    holder.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(holder);
    const size = box.getSize(new THREE.Vector3());
    const s = Math.min(0.5 / Math.max(size.x, size.z, 1e-3), 0.45 / Math.max(size.y, 1e-3), 1.2);
    const stand = new THREE.Group();
    stand.add(holder);
    holder.position.set(-(box.min.x + box.max.x) / 2, -box.min.y, -(box.min.z + box.max.z) / 2);
    stand.scale.setScalar(s);
    stand.position.y = 0.32;
    g.add(stand);
  }
  return { g, mesh };
}

function disposeGroup(g: THREE.Object3D, mesh: VehicleMesh | null): void {
  if (mesh) {
    mesh.holder.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh && m.userData.was) m.material = m.userData.was; });
    mesh.holder.parent?.remove(mesh.holder);
    disposeVehicleMesh(mesh);
  }
  g.traverse((o) => {
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    m.geometry.dispose();
    const mat = m.material as THREE.MeshStandardMaterial;
    if (mat !== goldMat && mat !== stoneMat) { mat.map?.dispose(); mat.dispose(); }
  });
}

interface Shown { sig: string; g: THREE.Group; plate: THREE.Group | null; statue: THREE.Group | null; mesh: VehicleMesh | null }

export class HqTreats {
  private root = new THREE.Group();
  private shown = new Map<string, Shown>();

  constructor(scene: THREE.Scene) {
    this.root.name = 'hq-treats';
    scene.add(this.root);
  }

  /** Every HQ's dress as it should be now: new ones built, changed ones rebuilt, the rest moved where they are. */
  set(list: HqDress[]): void {
    const keep = new Set<string>();
    for (const d of list) {
      if (!d.plate && !d.statue) continue;
      keep.add(d.key);
      const sig = `${d.plate ? `${d.plate.name}|${d.plate.span.toFixed(1)}` : ''}#${d.statue?.model ?? ''}`;
      let s = this.shown.get(d.key);
      if (s && s.sig !== sig) { this.drop(d.key); s = undefined; }
      if (!s) {
        const g = new THREE.Group();
        const plate = d.plate ? buildPlate(d.plate.name, d.plate.span) : null;
        const st = d.statue ? buildStatue(d.statue.model) : null;
        if (plate) g.add(plate);
        if (st) g.add(st.g);
        this.root.add(g);
        s = { sig, g, plate, statue: st?.g ?? null, mesh: st?.mesh ?? null };
        this.shown.set(d.key, s);
      }
      if (s.plate && d.plate) { s.plate.position.set(d.plate.x, d.plate.y, d.plate.z); s.plate.rotation.y = d.plate.yaw; }
      if (s.statue && d.statue) { s.statue.position.set(d.statue.x, d.statue.y, d.statue.z); s.statue.rotation.y = d.statue.yaw; }
    }
    for (const k of [...this.shown.keys()]) if (!keep.has(k)) this.drop(k);
  }

  private drop(key: string): void {
    const s = this.shown.get(key);
    if (!s) return;
    this.root.remove(s.g);
    disposeGroup(s.g, s.mesh);
    this.shown.delete(key);
  }

  clear(): void { for (const k of [...this.shown.keys()]) this.drop(k); }

  /** How many are up, for the console. */
  get count(): number { return this.shown.size; }
}

const yawOf = (facing: number): number => Math.atan2(DIRS[facing & 3][0], DIRS[facing & 3][1]);

/** Where an HQ's nameplate stands: the middle of its tallest roof, facing out of its front. */
export function plateSpot(w: World, all: Building[], roofOf: (w: World, b: Building) => number, styleOf: (b: Building) => Arch): { x: number; y: number; z: number; yaw: number; span: number } {
  const b = all.reduce((a, o) => (roofOf(w, o) > roofOf(w, a) ? o : a), all[0]);
  const alongZ = b.facing % 2 === 1;
  // on the model's own top, as drawn in the style it is drawn in (the badge's height is the kind's, not the model's)
  const top = modelTop(b, styleOf(b));
  return { x: w.ox + b.x + b.w / 2, y: top === null ? roofOf(w, b) : b.level * STEP + top - 0.03, z: w.oz + b.z + b.d / 2, yaw: yawOf(b.facing), span: alongZ ? b.w : b.d };
}

/** How tall a building's model stands above its lot, measured once by drawing it alone (render/ghost.ts), by kind, seed and style. */
const tops = new Map<string, number | null>();
function modelTop(b: Building, style: Arch): number | null {
  const k = `${b.kind}|${b.seed}|${style}|${b.w}x${b.d}|${b.floors}|${b.facing}`;
  if (tops.has(k)) return tops.get(k)!;
  let top: number | null = null;
  try {
    const g = buildGhost({ kind: b.kind, wx: b.w, wz: b.d, facing: b.facing, floors: b.floors, seed: b.seed, style }, 0xffffff, null);
    g.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(g);
    if (!box.isEmpty()) top = Math.max(0.2, box.max.y);
    disposeGhost(g);
  } catch { top = null; }
  if (tops.size > 64) tops.clear();
  tops.set(k, top);
  return top;
}

/** Free ground near an HQ, kept by HQ (the search walks rings of tiles; done again only when the island changes). */
const spots = new WeakMap<World, Map<string, { n: number; at: { x: number; z: number; yaw: number } | null }>>();

/**
 * A free tile just outside an HQ's lot for its statue: open, dry, unbuilt, off the road and the railway, near level,
 * the front's side first. Null when none is within three tiles.
 */
export function statueSpot(w: World, key: string, b: Building): { x: number; y: number; z: number; yaw: number } | null {
  let m = spots.get(w);
  if (!m) spots.set(w, (m = new Map()));
  const n = w.allBuildings.length * 31 + w.roadStamp;
  let c = m.get(key);
  if (!c || c.n !== n) {
    c = { n, at: findSpot(w, b) };
    m.set(key, c);
  }
  if (!c.at) return null;
  const { x, z, yaw } = c.at;
  return { x: w.ox + x, y: heightAt(w, x, z), z: w.oz + z, yaw };
}

function findSpot(w: World, b: Building): { x: number; z: number; yaw: number } | null {
  const [fx, fz] = DIRS[b.facing & 3];
  const cx = b.x + b.w / 2, cz = b.z + b.d / 2;
  // the footprints near, so a park or yard lot (which may not block) isn't stood on either
  const near = w.allBuildings.filter((o) => !o.gone && o.x < b.x + b.w + 4 && o.x + o.w > b.x - 4 && o.z < b.z + b.d + 4 && o.z + o.d > b.z - 4);
  const inLot = (x: number, z: number) => near.some((o) => x >= o.x && x < o.x + o.w && z >= o.z && z < o.z + o.d);
  let best = null as { x: number; z: number; score: number } | null;
  for (let ring = 1; ring <= 3; ring++) {
    for (let z = b.z - ring; z < b.z + b.d + ring; z++) {
      for (let x = b.x - ring; x < b.x + b.w + ring; x++) {
        const edge = x === b.x - ring || x === b.x + b.w + ring - 1 || z === b.z - ring || z === b.z + b.d + ring - 1;
        if (!edge || x < 1 || z < 1 || x >= N - 1 || z >= N - 1) continue;
        const i = idx(x, z);
        if (w.road[i] || w.rail[i] || w.blocked[i] || w.deckAxis[i] || w.water[i] >= 0 || w.roof[i] > 0 || inLot(x, z)) continue;
        const c = w.corners.subarray(i * 4, i * 4 + 4);
        if (Math.max(c[0], c[1], c[2], c[3]) - Math.min(c[0], c[1], c[2], c[3]) > 1) continue;
        // the front first, and nearer the middle of it
        const dx = x + 0.5 - cx, dz = z + 0.5 - cz;
        const front = dx * fx + dz * fz;
        const score = ring * 2 - (front > 0 ? 1.5 : 0) + Math.hypot(dx, dz) * 0.1;
        if (!best || score < best.score) best = { x: x + 0.5, z: z + 0.5, score };
      }
    }
    if (best) break;
  }
  if (!best) return null;
  // it looks out the way the HQ does
  return { x: best.x, z: best.z, yaw: yawOf(b.facing) };
}
