/**
 * What the fleet dock (game/fleetDock.ts) shows when it is asked: the bubble over a fleet square (that
 * unit's driver, what they are doing, what they have made you, and while the bubble is hovered or
 * pinned its Work/Follow pair and Bring over), the tray over the YOUR FLEET label (the company line,
 * the whole fleet's Work/Follow, the formation and convoy lines, the bench, and where you stand), and
 * the little corner icon on a square. Nothing of it is on screen until the dock is hovered or clicked.
 *
 * It also keeps the earnings ticker in the notice stack at the top middle of the screen: a green-edged
 * card slides in every time a driver earns you money, on screen or on the books, and fades a few
 * seconds later.
 */
import { esc, money } from './cargoHud';
import { CLASS_LABEL } from './cargoTypes';
import { driverLine, moodWord, rankOf, type Driver } from './drivers';
import { portraitImg } from './crewPortrait';
import type { Convoy } from './convoy';
import type { FleetMode, Formation } from './formation';
import { clock, roadLeft, type Fleet, type Unit } from './fleet';
import { METRICS, placeOf, type FleetMetrics } from './metrics';
import type { VehicleDef } from './vehicles';

/** Seconds an earnings card stays before it fades. One stands at a time: notifications take turns. */
/** A unit's icon when it is doing nothing in particular: its kind, so a train or a boat isn't shown as a car. */
const kindIcon = (def: VehicleDef): string => (def.kind === 'rail' ? '🚆' : def.kind === 'water' ? '🚤' : def.kind === 'air' ? (def.rotor ? '🚁' : '✈️') : '🚗');

const CARD_LIFE = 4.5;

export class FleetPanel {
  private ticker = document.getElementById('earnings')!;
  private cards: { el: HTMLElement; t: number }[] = [];
  /** Cards waiting for the stage, oldest first; those of a kind merge when their turn comes. */
  private waiting: { icon: string; head: string; body: string; kind: 'earn' | 'rent'; amount?: number }[] = [];
  /** Is a card on screen (or fading)? */
  get busy(): boolean { return this.cards.length > 0; }

  /** Asked for the vehicle a bring-over button belongs to, so main can spend the money. */
  onBringOver: (u: Unit) => void = () => {};
  /** The tray's Standings line was clicked. */
  onStandings: () => void = () => {};
  /** The tray's HQ link: the HQ window at a tab (docs/hqwindow.html). */
  onHq: (tab: string) => void = () => {};
  /** Where you stand, for the tray: set by main once the rival firms exist. */
  metrics: FleetMetrics | null = null;

  constructor(private fleet: Fleet, private convoy: Convoy, private formation: Formation) {}

  tick(dt: number, free = true): void {
    // the next card when nothing else is on the stage: everything of its kind that waited, in one
    if (!this.cards.length && free && this.waiting.length) {
      const first = this.waiting[0];
      const same = this.waiting.filter((w) => w.kind === first.kind);
      this.waiting = this.waiting.filter((w) => w.kind !== first.kind);
      const last = same[same.length - 1];
      const total = same.every((w) => w.amount !== undefined) ? same.reduce((s, w) => s + (w.amount ?? 0), 0) : null;
      const head = same.length > 1 && total !== null ? `+${money(total)}` : last.head;
      const body = same.length > 1 ? `${last.body} · and ${same.length - 1} more…` : last.body;
      this.put(last.icon, head, body, last.kind);
    }
    for (const c of [...this.cards]) {
      c.t += dt;
      if (c.t > CARD_LIFE - 0.6) c.el.classList.add('out');
      if (c.t >= CARD_LIFE) { c.el.remove(); this.cards.splice(this.cards.indexOf(c), 1); }
    }
  }

  /** A card in the ticker: green for the fleet, gold for rent (docs/property.html). */
  card(icon: string, head: string, body: string, kind: 'earn' | 'rent', amount?: number): void {
    this.waiting.push({ icon, head, body, kind, amount });
    if (this.waiting.length > 30) this.waiting.shift();
  }

  private put(icon: string, head: string, body: string, kind: 'earn' | 'rent'): void {
    const el = document.createElement('div');
    el.className = `notice ${kind === 'rent' ? 'earn rent' : 'earn'}`;
    el.innerHTML = `<div class="n-icon">${icon}</div><div class="n-body"><b>${esc(head)}</b><span>${esc(body)}</span></div>`;
    this.ticker.prepend(el);
    this.cards.push({ el, t: 0 });
  }

  /**
   * A button in a bubble or the tray was pressed (on pointerdown: both are redrawn a few times a second).
   * Returns whether it was one of ours.
   */
  act(d: DOMStringMap): boolean {
    if (d.standings) { this.onStandings(); return true; }
    if (d.hq) { this.onHq(d.hq); return true; }
    if (d.over) {
      const u = this.fleet.unit(Number(d.over));
      if (u) this.onBringOver(u);
      return true;
    }
    if (d.mode) {
      const uid = Number(d.uid ?? 0);
      const u = uid ? this.fleet.unit(uid) : null;
      if (uid && !u) return true;
      this.formation.setMode(d.mode as FleetMode, u ?? undefined);
      return true;
    }
    return false;
  }

  /** The corner icon on a fleet square: following, being towed, or waiting at a slip. '' for none. */
  icon(uid: number): string {
    const u = this.fleet.unit(uid);
    if (!u) return '';
    if (u.where === 'towing') return '🪝';
    if (this.formation.state(u) || u.mode === 'follow') return '🔗';
    if (u.where === 'waiting') return '⏸';
    return '';
  }

  /** The two buttons: Work and Follow, with whichever is on lit. `uid` marks a unit's pair. */
  private buttons(now: FleetMode | 'mixed', uid = 0, why: string | null = null): string {
    const at = uid ? ` data-uid="${uid}"` : '';
    const one = (mode: FleetMode, label: string, hint: string) =>
      `<button type="button" class="mode${now === mode ? ' on' : ''}${why && mode === 'follow' ? ' off' : ''}" data-mode="${mode}"${at} title="${esc(why && mode === 'follow' ? why : hint)}">${label}</button>`;
    return `<span class="modes">${one('work', 'Work', 'Take loads and earn where it is based, wherever you go')}${one('follow', 'Follow', 'Drop everything and drive in formation behind you, from county to county')}</span>`;
  }

  /** A follower's line: where it is in the formation, and how far it still has to make up. */
  private followLine(u: Unit, state: 'formed' | 'closing' | 'coming' | 'lost'): string {
    const gap = this.formation.gapOf(u);
    const behind = gap === null ? '' : ` · ${Math.max(0, Math.round(gap))} tiles off station`;
    switch (state) {
      case 'formed': return `following · in formation · lending ${this.fleet.defFor(u).capacity} units`;
      case 'closing': return `following · catching up${behind}`;
      case 'coming': return `following · on its way to you${u.road ? ` · ${clock(roadLeft(u.road))}` : ''}`;
      default: return `following · can't reach your line${behind}`;
    }
  }

  /** One crewed unit's row: driver, vehicle, what it is doing, and what it pays. */
  private driverRow(u: Unit, d: Driver): string {
    const f = this.fleet;
    const def = f.defFor(u);
    // its rate a day at work, over its last 30 days of work (Fleet.dayRate; the user, 5 Nov 2026: it was an hour)
    const rate = f.dayRate(u);
    const following = this.formation.state(u);
    const state = f.stateLine(u);
    const road = u.where === 'enroute';
    const kind = following ? (following === 'formed' ? 'form' : 'closing')
      : u.where === 'working' ? (u.agent?.run ? 'haul' : 'look')
        : road ? 'road' : u.where === 'waiting' ? 'held' : u.where === 'towing' ? 'tow' : 'idle';
    const icon = u.where === 'towing' ? '🪝'
      : following ? (following === 'formed' ? '🔗' : '🏁')
        : road ? (u.road?.slip !== undefined ? '⛴️' : u.road?.carried ? '🚛' : '🛣️')
          : u.where === 'waiting' ? '⏸' : u.agent?.run ? '📦' : kindIcon(def);
    // a driver on the road, or one driving with you rather than working, earns nothing: the row says so
    const pay = following || road || u.where === 'waiting' ? '—' : rate > 0 ? `≈ ${money(Math.round(rate))}/day` : 'no rate yet';
    const why = this.formation.whyNot(u);
    // what their incidents have cost you, which comes off what they have paid
    const towed = u.log.towed > 0 ? ` · <b class="towed">−${money(Math.round(u.log.towed))} towing</b>` : '';
    return `<li class="s-${kind}"><span class="ic">${icon}</span>
      <div class="what"><span class="face">${portraitImg(d.name, 22)}</span><b>${esc(d.name)}</b> <small class="mood m-${moodWord(d.mood)}">${moodWord(d.mood)}</small><small>${esc(u.name)}${u.name !== def.name ? ` · ${esc(def.name)}` : ''} · ${esc(driverLine(d))}</small>
        <small class="state">${esc(following ? this.followLine(u, following) : u.mode === 'follow' && why ? `follow · waiting: ${why}` : state)}</small></div>
      <div class="pay"><em class="${pay.startsWith('≈') ? '' : 'none'}">${pay}</em><small>${money(u.log.earned)} earned</small><small>${u.log.deliveries} deliver${u.log.deliveries === 1 ? 'y' : 'ies'} · cut ${Math.round(d.cut * 100)}%${d.nose ? ` · nose for ${CLASS_LABEL[d.nose]}` : ''}</small>
        <small>${u.log.incidents} tow${u.log.incidents === 1 ? '' : 's'}${towed}</small></div></li>`;
  }

  /**
   * The bubble over a fleet square. With `controls` (the bubble is hovered or pinned) a crewed unit gets
   * its Work/Follow pair, and one waiting at a slip its Bring over. Null for a unit the fleet no longer has.
   */
  unitCard(uid: number, controls: boolean): string | null {
    const f = this.fleet;
    const u = f.unit(uid);
    if (!u) return null;
    const d = f.driverOf(u);
    // its details on their own (the HQ window's Fleet pane, solo): on every bubble with controls
    const details = `<button type="button" class="details" data-details="${u.uid}">Open details</button>`;
    if (!d) {
      const def = f.defFor(u);
      return `<ul><li class="s-idle"><span class="ic">${kindIcon(def)}</span>
        <div class="what"><b>${esc(u.name)}</b><small>${u.name !== def.name ? `${esc(def.name)} · ` : ''}no driver</small><small class="state">${esc(f.stateLine(u))}</small></div>
        <div class="pay"><em class="none">—</em><small>${money(u.log.earned)} earned</small><small>${u.log.deliveries} deliver${u.log.deliveries === 1 ? 'y' : 'ies'}</small></div></li></ul>`
        + (controls ? `<div class="dk-ctl">${details}</div>` : '');
    }
    const row = `<ul>${this.driverRow(u, d)}</ul>`;
    if (!controls) return row;
    const over = u.where === 'waiting' ? this.convoy.towOver(u) : null;
    const why = this.formation.whyNot(u);
    return `${row}<div class="dk-ctl">${this.buttons(u.mode === 'follow' ? 'follow' : 'work', u.uid, why)}${over !== null ? `<button type="button" class="over" data-over="${u.uid}">Bring over · ${money(over)}</button>` : ''}${details}</div>`;
  }

  /** The tray over YOUR FLEET: everything about the fleet as a whole. */
  trayHtml(): string {
    const f = this.fleet;
    const c = f.company();
    const net = c.earned - c.towed;
    const idle = f.units.filter((u) => !f.driverOf(u) && u.where !== 'ridden' && u.where !== 'enroute' && u.where !== 'garaged');
    const riding = f.units.filter((u) => !f.driverOf(u) && u.where === 'enroute');
    const bench = f.drivers.filter((d) => !f.units.some((u) => u.driver === d.id));
    const crewed = f.units.some((u) => f.driverOf(u));
    const head = this.convoy.header();
    const form = this.formation.header();
    let standing = '';
    if (this.metrics) {
      const books = this.metrics.list();
      const live = books.filter((b) => b.gone === null).length;
      standing = `<button type="button" class="standing" data-standings="1"><span>Standings</span><b>#${placeOf(books, this.metrics.you(), METRICS[0])} of ${live}</b> by net worth <kbd>I</kbd></button>`;
    }
    return `<div class="tr-head"><b>Your fleet</b><span>${c.units} unit${c.units === 1 ? '' : 's'} · ${c.drivers} driver${c.drivers === 1 ? '' : 's'}</span><button type="button" class="hqlink" data-hq="fleet">HQ <kbd>H</kbd></button></div>
      <div class="tr-money"><em class="rate">≈ ${money(c.day)}/day</em> · ${money(c.earned)} earned${c.towed > 0 ? ` · <b class="towed">−${money(c.towed)} towing</b> · <em class="net">${money(net)} net</em>` : ''}</div>
      ${crewed ? `<div class="allmodes"><span>The whole fleet${this.formation.mode() === 'mixed' ? ' · some of each' : ''}</span>${this.buttons(this.formation.mode())}</div>` : (f.hq ? '<p class="none">No one is driving for you yet. Buy a second vehicle at a dealer and hire a driver for it in your HQ window (<kbd>H</kbd>).</p>'
        : '<p class="none"><b>🔒 No hiring until you have an HQ.</b> Drivers need fleet slots, and slots come only from an HQ: buy a building (a house will do) and make it your HQ, then hire in your HQ window (<kbd>H</kbd>).</p>')}
      ${form ? `<div class="form">⇢ ${esc(form)}</div>` : ''}
      ${head ? `<div class="convoy">↻ ${esc(head)}</div>` : ''}
      ${riding.length ? `<p class="idle">Being delivered: ${riding.map((u) => `${esc(u.name)} ${u.road ? clock(roadLeft(u.road)) : ''}`).join(', ')}</p>` : ''}
      ${idle.length ? `<p class="idle">Parked without a driver: ${idle.map((u) => `${esc(u.name)}${u.laidUp ? ' (laid up)' : ''}`).join(', ')}</p>` : ''}
      ${bench.length ? `<p class="idle">On the bench: ${bench.map((d) => `${esc(d.name)} (${rankOf(d)})`).join(', ')}</p>` : ''}
      ${standing}`;
  }
}
