import { hex } from '../../world/biomes';
import { WILD_INFO, WILD_KINDS, type WildKind } from '../../world/wildKinds';
import type { Draw } from './kit';
import { WILD_A_DRAW } from './wildA';
import { WILD_B_DRAW } from './wildB';
import { WILD_C_DRAW } from './wildC';

/**
 * Out in the middle of nowhere (world/wildKinds.ts), gathered from the three files that draw them: A the
 * strange and the lonely, B what was left behind, C somebody is out here. A kind not drawn yet stands as a
 * plain block.
 */
const placeholder: Draw = (k, W, D, b) => {
  const h = Math.max(0.1, WILD_INFO[b.kind as WildKind]?.h ?? 0.5);
  k.box(0, 0, 0, Math.max(0.4, W - 0.3), h, Math.max(0.4, D - 0.3), hex(0xd8d0c0));
};

const parts: Partial<Record<WildKind, Draw>> = { ...WILD_A_DRAW, ...WILD_B_DRAW, ...WILD_C_DRAW };

export const WILD_DRAW = Object.fromEntries(WILD_KINDS.map((k) => [k, parts[k] ?? placeholder])) as Record<WildKind, Draw>;

const groupOf = (kinds: readonly WildKind[]): Record<string, Draw> => Object.fromEntries(kinds.map((k) => [k, WILD_DRAW[k]]));

/** gallery.html?group=wild (all thirty), wildA|wildB|wildC (one file's). */
export const WILD_GALLERY: Record<string, Record<string, Draw>> = {
  wild: WILD_DRAW,
  wildA: groupOf(WILD_KINDS.slice(0, 10)),
  wildB: groupOf(WILD_KINDS.slice(10, 20)),
  wildC: groupOf(WILD_KINDS.slice(20, 30)),
};
