/**
 * What a freeze came from, worked out the same way in the game (net/perfField.ts, for the whole visit's count by
 * cause) and on the server (server/analytics.ts, for each freeze kept): the frame before it built shaders or
 * chunks, a named job ran inside it (net/perfJobs.ts, since 11 Nov 2026), the game's own code ran long, the heap
 * shrank by a lot (the garbage collector), or none of those, which is outside the game.
 *
 * Reports since 7 Nov 2026 say which chunk step the frame before ran and how much the heap shrank across it: a
 * chunk is blamed only when its steps were a good share of the freeze (finishing one used to blame it for anything).
 */
export const GC_MB = 20;
export interface CauseOf {
  ms: number; cpu: number | null; prog: number; chunks: number; parts: [string, number][];
  steps?: [string, number][]; gc?: number | null; jobs?: [string, number][];
}
export function hitchCause(h: CauseOf): string {
  if (h.prog > 0) return 'shaders';
  const stepMs = (h.steps ?? []).reduce((a, s) => a + s[1], 0);
  if (h.steps && h.steps.length && stepMs >= 0.4 * h.ms) return `chunks: ${h.steps[0][0]}`;
  if (!h.steps && h.chunks > 0) return 'chunks';
  // a named job that filled a good share of it: said before the lap it ran in, which says less
  if (h.jobs && h.jobs.length && h.jobs[0][1] >= 0.4 * h.ms) return `job: ${h.jobs[0][0]}`;
  if (h.cpu == null) return 'unknown';
  if (h.cpu >= 0.6 * h.ms) return `game: ${h.parts[0]?.[0] ?? 'other'}`;
  if (h.gc != null && h.gc >= GC_MB) return 'garbage collection';
  return 'outside the game (GPU, GC, browser)';
}
