/**
 * Where a load is from a train (the user, 3 Nov 2026): "it's very hard to tell whether I'm even travelling in the
 * right direction or on the right track". For the player's train this works out, for a place:
 *
 *  - which way along the rails it lies, ahead (the way the train faces) or behind, and how many stops away, or
 *    that this line never gets there (`railWay`); stations in memory are counted off the track itself
 *    (Trains.lineOrder), stations counties off from the rail plan (world/rail.ts stationsAlong), which the
 *    long-haul work is chosen from in the first place;
 *  - the way along the track to it, as tiles of one county, for the route arrows (`railPath`).
 *
 * Both follow the turnouts the way this train will take them (Trains.walk), so a junction set the wrong way
 * shows as the destination falling off the line.
 */
import { N, type RailStation, type World } from '../world/tiles';
import { hashString } from '../world/rng';
import { stationsAlong } from '../world/rail';
import { sampleAt, type Train, type Trains } from './trains';

/** Above the track's own height, where the route arrows lie: clear of the sleepers and rails (render/railMesh.ts). */
const OVER_RAILS = 0.09;
/** The height of the track under each tile of the last way laid (railPath), for the route arrows. */
export const railHeights = new Map<number, number>();

/** Ahead (+1) or behind (-1) along the line, and how many stops that is counting the destination; or off the line. */
export type RailWay = { way: 1 | -1; stops: number } | { way: 0 };

/** Counties of the rail plan looked down each way for a destination. */
const PLAN_CELLS = 30;
/** Tiles of track walked each way for the arrows and for where the line leaves the county. */
const WALK = 900;
const pt = { x: 0, y: 0, z: 0, ang: 0 };

/**
 * Where on the track a walk sets off: the front, either way (back along the train's own length going back), so
 * the route arrows' way starts under the player, which is how they tell it is still being followed.
 */
function startOf(tr: Train, way: 1 | -1) {
  const f = tr.trail[0];
  if (!f) return null;
  return { t: f.t, s: f.b, dir: (way > 0 ? f.d : -f.d) as 1 | -1 };
}

/** The way the train is going along the track at its front, as a unit vector in world x, z (what "ahead" means here). */
export function forwardOf(tr: Train): { x: number; z: number } {
  const f = tr.trail[0];
  if (!f) return { x: 0, z: 1 };
  sampleAt(f.t, f.b, pt);
  const ax = pt.x, az = pt.z;
  sampleAt(f.t, f.b - f.d * 2, pt);
  const dx = ax - pt.x, dz = az - pt.z, l = Math.hypot(dx, dz) || 1;
  return { x: dx / l, z: dz / l };
}

/** The county the train's front is in. */
function cellOf(tr: Train): [number, number] | null {
  const f = tr.trail[0];
  if (!f) return null;
  sampleAt(f.t, f.b, pt);
  return [Math.floor(pt.x / N), Math.floor(pt.z / N)];
}

/**
 * The side of its county (0 east, 1 south, 2 west, 3 north, as world/rail.ts counts them) the track leaves by
 * going `way`, with the turnouts set as this train takes them; null when it ends first.
 */
export function exitSide(trains: Trains, tr: Train, way: 1 | -1): { side: number; at: number } | null {
  const cell = cellOf(tr), from = startOf(tr, way);
  if (!cell || !from) return null;
  let out: { side: number; at: number } | null = null;
  trains.walk(from, WALK, tr, (t, s0, s1, dist) => {
    const n = Math.max(1, Math.ceil(Math.abs(s1 - s0) / 2));
    for (let k = 0; k <= n; k++) {
      sampleAt(t, s0 + ((s1 - s0) * k) / n, pt);
      const cx = Math.floor(pt.x / N), cz = Math.floor(pt.z / N);
      if (cx === cell[0] && cz === cell[1]) continue;
      out = { side: cx > cell[0] ? 0 : cz > cell[1] ? 1 : cx < cell[0] ? 2 : 3, at: dist + (Math.abs(s1 - s0) * k) / n };
      return true;
    }
    return false;
  });
  return out;
}

/**
 * Which way, and how many stops, to a station called `name` in county (cx, cz). `order` is Trains.lineOrder:
 * stations on the track in memory, by signed distance (ahead positive). `sides` are the exit sides ahead and
 * behind (exitSide), worked out once by the caller for all its loads.
 */
export function railWay(order: Map<RailStation, number>, sides: [Exit, Exit], seed: string, here: [number, number] | null,
  dest: { name: string; cx: number; cz: number }): RailWay {
  // on the track in memory: counted off it
  let at: number | null = null;
  for (const [st, d] of order) if (st.name === dest.name) { at = d; break; }
  if (at !== null && at !== 0) {
    const way = at > 0 ? 1 : -1;
    let stops = 0;
    for (const d of order.values()) if (Math.sign(d) === way && Math.abs(d) <= Math.abs(at)) stops++;
    return { way, stops };
  }
  // further off: down the rail plan from where the line leaves this county, each way
  if (!here) return { way: 0 };
  const sh = hashString(seed);
  for (const [k, way] of [[0, 1], [1, -1]] as const) {
    const ex = sides[k];
    if (!ex) continue;
    const list = stationsAlong(sh, here[0], here[1], ex.side, PLAN_CELLS);
    const i = list.findIndex((q) => q.cx === dest.cx && q.cz === dest.cz);
    if (i < 0) continue;
    // and the stops still to come in this county, on the track in memory before it leaves
    let near = 0;
    for (const d of order.values()) if (Math.sign(d) === way && Math.abs(d) < ex.at) near++;
    return { way, stops: near + i + 1 };
  }
  return { way: 0 };
}

/** The county the train is in, and its exit sides ahead and behind: what railWay needs, worked out once. */
type Exit = { side: number; at: number } | null;

export function railSides(trains: Trains, tr: Train): { here: [number, number] | null; sides: [Exit, Exit] } {
  return { here: cellOf(tr), sides: [exitSide(trains, tr, 1), exitSide(trains, tr, -1)] };
}

/**
 * The way along the rails to world point (tx, tz), as local tiles of `w` (the county the train is in), for the
 * route arrows. `way` when it is known (railWay); else whichever way the track comes nearer the point. It runs
 * to where the track passes nearest the point, or to the county's edge on the way.
 */
export function railPath(trains: Trains, tr: Train, w: World, tx: number, tz: number, way: 1 | -1 | 0 = 0): number[] | null {
  const walkWay = (dir: 1 | -1) => {
    const from = startOf(tr, dir);
    if (!from) return null;
    const tiles: number[] = [];
    const ys = new Map<number, number>();
    let best = Infinity, bestK = -1, out = false;
    trains.walk(from, WALK, tr, (t, s0, s1) => {
      const n = Math.max(1, Math.ceil(Math.abs(s1 - s0)));
      for (let k = 0; k <= n; k++) {
        sampleAt(t, s0 + ((s1 - s0) * k) / n, pt);
        const d = Math.hypot(pt.x - tx, pt.z - tz);
        if (d < best) { best = d; bestK = tiles.length; }
        const lx = Math.floor(pt.x - w.ox), lz = Math.floor(pt.z - w.oz);
        if (lx < 0 || lz < 0 || lx >= N || lz >= N) { out = true; continue; }
        if (out) continue;
        const i = lz * N + lx;
        if (!ys.has(i)) ys.set(i, pt.y + OVER_RAILS);
        if (tiles[tiles.length - 1] !== i) tiles.push(i);
      }
      return false;
    });
    return { tiles, best, bestK, ys };
  };
  const fwd = way >= 0 ? walkWay(1) : null, back = way <= 0 ? walkWay(-1) : null;
  const pick = !fwd ? back : !back ? fwd : fwd.best <= back.best ? fwd : back;
  if (!pick || pick.tiles.length < 2) return null;
  railHeights.clear();
  for (const [i, y] of pick.ys) railHeights.set(i, y);
  // up to where the line passes nearest (the whole stretch in this county when that is further on)
  const end = pick.bestK >= 0 ? Math.min(pick.tiles.length, pick.bestK + 1) : pick.tiles.length;
  return pick.tiles.slice(0, Math.max(2, end));
}
