import { hex, scale } from '../../../world/biomes';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, TRUNK, WARM_GLOW, type Draw, type Kit } from '../kit';

/**
 * The Golden Hills: the old mission with its bell wall and arcade, a ranch house under the oaks, and a
 * winery's barn with barrels at its door. Lime-washed adobe, red clay tile, weathered timber.
 */

const ADOBE = hex(0xf1e8d6), ADOBE_SHADE = hex(0xe0d2b8), TILE = hex(0xb8583a), TILE_DARK = hex(0x96452e);
const TIMBER = hex(0x7a5634), BELL = hex(0xb08a3a), GRASS = hex(0x9ab35a), PATH = hex(0xd9c8a0);
const BARN_RED = hex(0x8e3b2c), OAK = hex(0x4e6a34), ROOF = hex(0x6a6a66);
const EVENING: Sched = [18, 23.5, 1.4];

/** A red clay roof over a box, gabled, with the eaves standing out a little. */
function tiled(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, alongZ = false): void {
  k.gable(x, y, z, w + 0.06, h, d + 0.06, TILE, ADOBE_SHADE, alongZ);
}

/** A round oak, low and wide. */
function oak(k: Kit, x: number, z: number, s: number): void {
  k.cyl(x, 0, z, 0.05 * s, 0.3 * s, TRUNK, 6);
  k.dome(x, 0.22 * s, z, 0.34 * s, OAK, 8, 3);
}

// ---- the mission (the wonder, 12 × 12) ---------------------------------------------------------------

const mission: Draw = (k, W, D) => {
  const hw = W / 2, hd = D / 2;
  // the grounds: a garden square with a path to the church door
  k.box(0, 0, 0, W - 0.4, 0.02, D - 0.4, GRASS);
  k.box(0, 0.02, hd * 0.45, 1.2, 0.01, D * 0.5, PATH);
  // the church along the back, its bell wall facing the front
  const cz = -hd + 3.2, cw = 3.4, cd = 5.2;
  k.box(-hw + 3.4, 0.02, cz, cw, 1.6, cd, ADOBE);
  tiled(k, -hw + 3.4, 1.62, cz, cw, cd, 0.9, true);
  // the espadaña: a stepped wall standing up over the front, pierced for three bells
  const fx = -hw + 3.4, fz = cz + cd / 2 + 0.1;
  k.box(fx, 0.02, fz, cw + 0.3, 2.3, 0.3, ADOBE);
  k.box(fx, 2.32, fz, cw * 0.62, 0.7, 0.3, ADOBE);
  k.box(fx, 3.02, fz, cw * 0.28, 0.5, 0.3, ADOBE);
  for (const [bx, by] of [[-0.55, 2.52], [0.55, 2.52], [0, 3.2]] as const) {
    k.box(fx + bx, by, fz + 0.16, 0.32, 0.32, 0.02, DARK);
    k.cone(fx + bx, by + 0.06, fz, 0.1, 0.18, BELL, 8);
  }
  k.box(fx, 3.52, fz, 0.04, 0.3, 0.04, TIMBER);
  k.box(fx, 3.7, fz, 0.2, 0.04, 0.04, TIMBER);
  // the church door and two deep windows
  k.box(fx, 0.02, fz + 0.16, 0.5, 0.8, 0.02, TIMBER);
  k.pane(fx - 1.0, 1.0, fz + 0.16, 0.2, 0.34, 1, DARK, EVENING, WARM_GLOW);
  k.pane(fx + 1.0, 1.0, fz + 0.16, 0.2, 0.34, 1, DARK, EVENING, WARM_GLOW);
  // the convento: a long low range down the right side, an arcade of arches along its front
  const rx = hw - 2.2, rz = -0.4, rd = D - 3.2;
  k.box(rx, 0.02, rz, 2.4, 1.1, rd, ADOBE);
  tiled(k, rx, 1.12, rz, 2.4, rd, 0.6, true);
  const ax = rx - 1.45;
  k.box(ax, 0.9, rz, 0.5, 0.18, rd, ADOBE_SHADE);
  const n = Math.floor(rd / 0.9);
  for (let i = 0; i <= n; i++) k.box(ax - 0.18, 0.02, rz - rd / 2 + (i * rd) / n, 0.14, 0.88, 0.14, ADOBE);
  k.wedge(ax, 1.08, rz, 0.56, 0.2, rd, TILE_DARK);
  for (let i = 0; i < n; i++) k.pane(rx - 1.21, 0.35, rz - rd / 2 + ((i + 0.5) * rd) / n, 0.16, 0.26, 2, DARK, EVENING, WARM_GLOW);
  // a fountain in the middle of the garden, and oaks round the edge
  k.cyl(0.6, 0.02, 0.8, 0.55, 0.16, ADOBE_SHADE, 12);
  k.cyl(0.6, 0.18, 0.8, 0.42, 0.01, hex(0x6fb3cf), 12);
  k.cyl(0.6, 0.18, 0.8, 0.08, 0.35, ADOBE, 8);
  for (const [ox, oz] of [[-hw + 1, hd - 1], [hw - 1, hd - 1], [-hw + 1, 1.2], [1.8, hd - 1.6]] as const) oak(k, ox, oz, 1.4);
  // the low adobe wall round it all, open at the front
  k.box(0, 0.02, -hd + 0.25, W - 0.5, 0.35, 0.12, ADOBE_SHADE);
  for (const sx of [-1, 1]) k.box(sx * (hw - 0.25), 0.02, 0, 0.12, 0.35, D - 0.5, ADOBE_SHADE);
  for (const sx of [-1, 1]) k.box(sx * (hw / 2 + 0.6), 0.02, hd - 0.25, hw - 1.2, 0.35, 0.12, ADOBE_SHADE);
};

// ---- a ranch house (2 × 2) ----------------------------------------------------------------------------

const ranchHouse: Draw = (k, W, D) => {
  const hw = W / 2;
  k.box(-0.15, 0.02, -0.2, W - 0.8, 0.45, 1.0, ADOBE);
  tiled(k, -0.15, 0.47, -0.2, W - 0.8, 1.0, 0.3);
  // the porch along the front
  k.box(-0.15, 0.02, 0.42, W - 0.8, 0.02, 0.3, TIMBER);
  for (const px of [-0.7, -0.15, 0.4]) k.box(px, 0.04, 0.55, 0.04, 0.42, 0.04, TIMBER);
  k.wedge(-0.15, 0.44, 0.47, W - 0.8, 0.08, 0.36, TILE_DARK);
  k.box(-0.15, 0.04, 0.29, 0.14, 0.28, 0.01, TIMBER);
  k.pane(-0.6, 0.18, 0.3, 0.14, 0.14, 1, DARK, EVENING, WARM_GLOW);
  k.pane(0.3, 0.18, 0.3, 0.14, 0.14, 1, DARK, EVENING, WARM_GLOW);
  // a water tank on stilts, and an oak
  const tx = hw - 0.35, tz = -D / 2 + 0.4;
  for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]] as const) k.bar([tx + sx * 0.12, 0, tz + sz * 0.12], [tx + sx * 0.1, 0.55, tz + sz * 0.1], 0.015, TIMBER);
  k.cyl(tx, 0.55, tz, 0.17, 0.25, scale(TIMBER, 1.2), 8);
  k.cone(tx, 0.8, tz, 0.19, 0.08, ROOF, 8);
  oak(k, hw - 0.35, D / 2 - 0.35, 0.8);
};

// ---- a winery's barn (3 × 2) --------------------------------------------------------------------------

const wineryBarn: Draw = (k, W, D) => {
  k.box(0, 0.02, -0.1, W - 0.5, 0.75, D - 0.7, BARN_RED);
  k.gable(0, 0.77, -0.1, W - 0.4, 0.45, D - 0.6, hex(0x5a5550), BARN_RED);
  // the big doors, trimmed white, and a loft door over them
  k.box(0, 0.02, D / 2 - 0.44, 0.7, 0.62, 0.02, scale(BARN_RED, 0.8));
  k.bar([-0.35, 0.02, D / 2 - 0.43], [0.35, 0.64, D / 2 - 0.43], 0.012, ADOBE);
  k.bar([0.35, 0.02, D / 2 - 0.43], [-0.35, 0.64, D / 2 - 0.43], 0.012, ADOBE);
  k.pane(0, 0.86, D / 2 - 0.44, 0.24, 0.2, 1, DARK, EVENING, WARM_GLOW);
  // barrels stacked by the door
  for (let i = 0; i < 4; i++) {
    const bx = -W / 2 + 0.45 + (i % 2) * 0.24, by = 0.02 + Math.floor(i / 2) * 0.2;
    k.cyl(bx, by, D / 2 - 0.2, 0.1, 0.2, TIMBER, 8, scale(TIMBER, 0.8));
  }
  // a row of vines along the side
  for (let i = 0; i < 5; i++) k.box(W / 2 - 0.3, 0.02, -D / 2 + 0.3 + i * 0.3, 0.08, 0.22, 0.2, hex(0x5f8a3a));
};

export const GOLDHILLS_DRAW: Partial<Record<RegionBuildingKind, Draw>> = { mission, ranchHouse, wineryBarn };
