import { DIRS, N, RoadType, STEP, idx, inB, tileAt, type Town, type World } from '../world/tiles';
import { seatOf } from '../world/townShape';
import { buildingAt, solidAt } from '../world/footprint';
import { nearestRoad } from './nearRoad';

/**
 * The police's side of night runs (docs/smuggling.html), with nothing drawn: each town's beat worked
 * out from the finished world, and a patrol car's line of sight cast over the tiles as a fan of rays.
 * The same fan is drawn on the ground and tested against the player's car, so what the glow shows is
 * exactly what the car can see. Headless, so the gate (npm run smuggle) runs it over whole worlds.
 */

/** The cone: how far it reaches, its half-angle, how many rays make it, and how much the test forgives. */
export const CONE = {
  range: 7,
  half: (28 * Math.PI) / 180,
  rays: 25,
  /** The test uses the fan shrunk this much toward its middle, to forgive jitter at the edge. */
  shrink: 0.9,
  /** Outside the cone but this close to its edge: the outline brightens as a warning. */
  warn: 1.5,
};
/**
 * A cone's shape. CONE is the patrol car's; a tail's target has a mirror of its own (game/tail/sight.ts)
 * whose reach and width change as the player honks or runs dark, so the cast and the test take one.
 */
export interface ConeShape { range: number; half: number; rays: number; shrink: number; warn: number }
/** Along each ray, how far apart the points it looks at are: fine enough not to step over a thin wall. */
const RAY_STEP = 0.2;
/** Terrain this far above the car (world units, two height steps) blocks its view. */
const HILL = 2 * STEP;

/** A place on a beat: a road tile's middle, in its cell's own frame. */
export interface Stop { x: number; z: number; tile: number }

/** A town's beat: the stops its patrols drive between, where they come out from, and the busiest way in. */
export interface Beat {
  town: number;
  stops: Stop[];
  /** Index into stops of the busiest entry, where a checkpoint stands; -1 when the town has no entry. */
  checkpoint: number;
  /** Where patrols come out at dusk and go back to at dawn: the police station's kerb, else the seat's. */
  station: Stop;
  /** Every road tile the beat was scored over, with its score, for the gate and the console. */
  scores: Map<number, number>;
}

/** Tiles of the roads generated between towns (a road with `town` -1), by cell. */
const LINKS = new WeakMap<World, { rev: number; tiles: Set<number> }>();
function linkTiles(w: World): Set<number> {
  let l = LINKS.get(w);
  if (!l || l.rev !== w.roadStamp) {
    const tiles = new Set<number>();
    for (const r of w.roads) if (r.town === -1) for (const t of r.tiles) tiles.add(t);
    l = { rev: w.roadStamp, tiles };
    LINKS.set(w, l);
  }
  return l.tiles;
}

/** A road runs from tile a over its side d into the next tile. */
const roadStep = (w: World, a: number, d: number): number => {
  if (!((w.roadEdges[a] >> d) & 1)) return -1;
  const x = (a % N) + DIRS[d][0], z = Math.floor(a / N) + DIRS[d][1];
  if (!inB(x, z)) return -1;
  const b = idx(x, z);
  return w.road[b] ? b : -1;
};

/** Breadth-first over the road from `from`, inside the box, giving each tile its parent. */
function roadTree(w: World, from: number, box: [number, number, number, number]): Int32Array {
  const [x0, z0, x1, z1] = box;
  const bw = x1 - x0 + 1, bh = z1 - z0 + 1;
  const parent = new Int32Array(bw * bh).fill(-2);
  const local = (t: number) => { const x = t % N, z = (t - x) / N; return x < x0 || x > x1 || z < z0 || z > z1 ? -1 : (z - z0) * bw + (x - x0); };
  const q = [from];
  parent[local(from)] = -1;
  for (let h = 0; h < q.length; h++) {
    const a = q[h];
    for (let d = 0; d < 4; d++) {
      const b = roadStep(w, a, d);
      if (b < 0) continue;
      const lb = local(b);
      if (lb < 0 || parent[lb] !== -2) continue;
      parent[lb] = a;
      q.push(b);
    }
  }
  return parent;
}


const stopOf = (t: number): Stop => ({ x: (t % N) + 0.5, z: Math.floor(t / N) + 0.5, tile: t });
const manhattan = (a: number, b: number) => Math.abs((a % N) - (b % N)) + Math.abs(Math.floor(a / N) - Math.floor(b / N));

const BEATS = new WeakMap<World, { rev: number; beats: Map<number, Beat | null> }>();

/** A town's beat, worked out once per island revision. Null for a town with no road to patrol. */
export function beatOf(w: World, t: Town): Beat | null {
  let c = BEATS.get(w);
  if (!c || c.rev !== w.revision) { c = { rev: w.revision, beats: new Map() }; BEATS.set(w, c); }
  if (c.beats.has(t.id)) return c.beats.get(t.id)!;
  const b = makeBeat(w, t);
  c.beats.set(t.id, b);
  return b;
}

function makeBeat(w: World, t: Town): Beat | null {
  const box: [number, number, number, number] = [
    Math.max(0, t.x0 - 4), Math.max(0, t.z0 - 4), Math.min(N - 1, t.x0 + t.size + 3), Math.min(N - 1, t.z0 + t.size + 3),
  ];
  const bw = box[2] - box[0] + 1;
  const local = (i: number) => (Math.floor(i / N) - box[1]) * bw + ((i % N) - box[0]);
  const seatB = seatOf(t);
  const mid = seatB ? { x: seatB.x + seatB.w / 2, z: seatB.z + seatB.d / 2 } : { x: t.x0 + t.size / 2, z: t.z0 + t.size / 2 };
  const seat = nearestRoad(w, mid.x, mid.z, 8);
  if (seat < 0) return null;
  // everything patrolled must be reachable by road from the seat
  const fromSeat = roadTree(w, seat, box);
  const reach = (i: number) => { const x = i % N, z = Math.floor(i / N); return x >= box[0] && x <= box[2] && z >= box[1] && z <= box[3] && fromSeat[local(i)] !== -2; };
  const entries = [...new Set(t.entry)].filter((e) => w.road[e] && reach(e));

  // how often each tile lies on a shortest way between two entries, or an entry and the seat
  const through = new Map<number, number>();
  const walk = (tree: Int32Array, to: number) => {
    for (let i = to, guard = 0; i >= 0 && guard < 4000; guard++) {
      through.set(i, (through.get(i) ?? 0) + 1);
      i = tree[local(i)];
    }
  };
  for (const e of entries) walk(fromSeat, e);
  for (let a = 0; a < entries.length; a++) {
    const tree = roadTree(w, entries[a], box);
    for (let b = a + 1; b < entries.length; b++) if (tree[local(entries[b])] !== -2) walk(tree, entries[b]);
  }
  const links = linkTiles(w);
  const scores = new Map<number, number>();
  for (let z = box[1]; z <= box[3]; z++) for (let x = box[0]; x <= box[2]; x++) {
    const i = idx(x, z);
    if (!w.road[i] || !reach(i)) continue;
    const inTown = w.townId[i] === t.id;
    if (!inTown && !through.has(i)) continue;
    let s = through.get(i) ?? 0;
    if (w.road[i] === RoadType.FourLane) s += 3;
    if (links.has(i)) s += 3;
    const junction = w.roadAxis[i] === 3 || w.roadCover[i] >= 2;
    if (junction && Math.hypot(x + 0.5 - mid.x, z + 0.5 - mid.z) < 9) s += 2;
    if (s > 0) scores.set(i, s);
  }

  // the stops: the square, the ways in (busiest first), then the busiest junctions, spaced out
  const stops: number[] = [seat];
  const spaced = (i: number, gap: number) => stops.every((s) => manhattan(s, i) >= gap);
  const byScore = (a: number, b: number) => (scores.get(b) ?? 0) - (scores.get(a) ?? 0);
  const ins = [...entries].sort(byScore);
  for (const e of ins) { if (stops.length >= 5) break; if (spaced(e, 5)) stops.push(e); }
  const junctions = [...scores.keys()].filter((i) => w.roadAxis[i] === 3 || w.roadCover[i] >= 2).sort(byScore);
  for (const j of junctions) { if (stops.length >= 6) break; if (spaced(j, 6)) stops.push(j); }
  // a hamlet with one street still gets somewhere to drive to
  for (const i of [...scores.keys()].sort(byScore)) { if (stops.length >= 3) break; if (spaced(i, 5)) stops.push(i); }
  if (stops.length < 2) return null;

  const busiest = ins[0];
  const checkpoint = busiest === undefined ? -1 : stops.indexOf(busiest);
  const station = t.buildings.find((b) => b.kind === 'police' && !b.gone);
  const st = station ? nearestRoad(w, station.x + station.w / 2, station.z + station.d / 2, 6) : -1;
  return { town: t.id, stops: stops.map(stopOf), checkpoint, station: stopOf(st >= 0 && reach(st) ? st : seat), scores };
}

/** How many patrols a town puts out at night, and how many while the player carries contraband. */
export function patrolsFor(t: Town, carrying: boolean): number {
  if (t.kind === 'mega') return carrying ? 7 : 5;
  const n = t.buildings.filter((b) => b.solid && !b.gone).length;
  const base = n < 20 ? 1 : n < 60 ? 2 : n < 150 ? 3 : 4;
  return base + (carrying ? 1 : 0);
}

/** Does anything at (x, z) in w's frame stop the view of a car whose eye is at height y? */
export function blocksSight(w: World, x: number, z: number, y: number): boolean {
  let cw = w, lx = x, lz = z, i: number;
  const tx = Math.floor(x), tz = Math.floor(z);
  if (tx >= 0 && tz >= 0 && tx < N && tz < N) i = idx(tx, tz);
  else {
    const o = tileAt(w, x, z);
    cw = o.w;
    lx = x - (cw.ox - w.ox);
    lz = z - (cw.oz - w.oz);
    i = o.i;
  }
  if (cw.blocked[i]) {
    const b = buildingAt(cw, i);
    if (!b || solidAt(b, lx, lz)) return true;
  }
  // a deck the car could be on (a bridge, a tunnel's bore) carries its view along with it
  if (cw.deckAxis[i] && Math.abs(Math.max(cw.deckLo[i], cw.deckHi[i]) - y) < 1.2) return false;
  const c = cw.corners, k = i * 4;
  const top = Math.max(c[k], c[k + 1], c[k + 2], c[k + 3]) * STEP;
  return top > y + HILL;
}

/**
 * Cast the cone from (ox, oz) at eye height oy, pointing along `dir` (a heading: forward is
 * (sin dir, cos dir)), in w's frame. Each ray's length goes into `out` (CONE.rays long).
 */
export function castCone(w: World, ox: number, oz: number, oy: number, dir: number, out: Float32Array, cone: ConeShape = CONE): void {
  const n = cone.rays;
  for (let r = 0; r < n; r++) {
    const a = dir - cone.half + (2 * cone.half * r) / (n - 1);
    const sx = Math.sin(a), sz = Math.cos(a);
    let len = cone.range;
    for (let d = RAY_STEP; d <= cone.range; d += RAY_STEP) {
      if (blocksSight(w, ox + sx * d, oz + sz * d, oy)) { len = Math.max(RAY_STEP * 0.5, d - RAY_STEP * 0.5); break; }
    }
    out[r] = len;
  }
}

const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));

/** The fan's length toward angle `a` off its middle, between the two rays either side of it. */
function lengthAt(lens: Float32Array, a: number, cone: ConeShape = CONE): number {
  const n = cone.rays;
  const f = ((a + cone.half) / (2 * cone.half)) * (n - 1);
  const k = Math.max(0, Math.min(n - 1, Math.floor(f))), t = f - k;
  return lens[k] + (lens[Math.min(n - 1, k + 1)] - lens[k]) * t;
}

/**
 * Where a point stands against the cone: 'in' inside the fan (shrunk a little), 'near' outside it but
 * within CONE.warn of its edge, else 'out'.
 */
export function coneHas(lens: Float32Array, ox: number, oz: number, dir: number, px: number, pz: number, cone: ConeShape = CONE): 'in' | 'near' | 'out' {
  const dx = px - ox, dz = pz - oz, d = Math.hypot(dx, dz);
  if (d > cone.range + cone.warn) return 'out';
  const a = d < 1e-3 ? 0 : wrap(Math.atan2(dx, dz) - dir);
  if (Math.abs(a) <= cone.half * cone.shrink && d <= lengthAt(lens, a, cone) * cone.shrink) return 'in';
  // within the warning band: past the side by less than cone.warn, or past the far end by as little
  const side = Math.abs(a) > cone.half ? d * Math.sin(Math.min(Math.PI / 2, Math.abs(a) - cone.half)) : 0;
  if (Math.abs(a) - cone.half > Math.PI / 2) return 'out';
  const far = d - lengthAt(lens, Math.max(-cone.half, Math.min(cone.half, a)), cone);
  return side <= cone.warn && far <= cone.warn ? 'near' : 'out';
}
