/**
 * The Oath's way to a faction's stronghold (docs/strongholds.html, "The Oath goes through the gates"). A stronghold is
 * usually counties away and not in memory when a step is bound, so an objective aimed at one (`Obj.stronghold`) points
 * first at its county's middle ("Corran Harbour, 6 counties north-east"), and `resolveAims` (missions/wire.ts, once a
 * second) retargets it to the gate, the headquarters' door or the stage as soon as a world in memory holds it. A county
 * picked from the rolls outside the home square that turns out not to have made its stronghold hands over to the home
 * square's, which always stands.
 */
import { hashString } from '../../world/rng';
import { N, type World } from '../../world/tiles';
import { fromPlan, homeStronghold, strongholdCells, strongholdsIn, type Stronghold } from '../../world/strongholds';
import { STRONGHOLD_NAME, STRONGHOLD_OF, gateOut } from '../../world/strongholdPlans';
import type { FactionId } from '../factions/factions';
import type { Mission, Obj, PlaceRef, StrongholdAim } from './model';

type Pt = { x: number; z: number };
export type AimAt = StrongholdAim['at'];

/** How far out (counties) the rolled strongholds are looked for beyond the home square's. */
const LOOK = 6;
const COMPASS = ['east', 'south-east', 'south', 'south-west', 'west', 'north-west', 'north', 'north-east'];

/** What each faction's stage is, for the line under the card ("Drive to the parade square"). */
const STAGE: Record<FactionId, string> = {
  police: 'the parade square', family: 'the chapel', ministry: 'the chancery steps', visitors: 'the salt',
  unions: 'the rally yard', post: 'the clock tower', army: 'the parade ground', studios: 'the backlot street',
  guild: 'the quay', press: 'the ticker',
};

/** The point at a standing stronghold, world tiles. */
function pointIn(s: Stronghold, at: AimAt): Pt {
  const p = s.plan;
  let px: number, pz: number;
  if (at === 'door') { px = p.door.x; pz = p.door.z; }
  else if (at === 'stage') { px = p.stage.x; pz = p.stage.z; }
  else {
    // the gate the county road comes to (world/strongholds.ts planStronghold): just outside it, or well out for a meeting
    const g = p.gates[0], [ox, oz] = gateOut(p, g), k = at === 'gate' ? 2.2 : 6;
    px = g.x + ox * k; pz = g.z + oz * k;
  }
  const [lx, lz] = fromPlan(s.b, px, pz);
  return { x: s.w.ox + lx, z: s.w.oz + lz };
}

const nameIn = (s: Stronghold, at: AimAt): string =>
  at === 'stage' ? STAGE[s.f] : at === 'gate' || at === 'outside' ? `the gates of ${s.name.replace(/^The /, 'the ')}` : s.name;

/** A stronghold's county, not in memory: its middle, named for how far off it is from `from`. */
function farRef(f: FactionId, cx: number, cz: number, from: Pt): PlaceRef {
  const x = cx * N + N / 2, z = cz * N + N / 2;
  const n = Math.max(Math.abs(cx - Math.floor(from.x / N)), Math.abs(cz - Math.floor(from.z / N)));
  const dir = COMPASS[((Math.round(Math.atan2(z - from.z, x - from.x) / (Math.PI / 4)) % 8) + 8) % 8];
  const name = STRONGHOLD_NAME[STRONGHOLD_OF[f]];
  return { x, z, cell: [cx, cz], name: n >= 1 ? `${name}, ${n} ${n === 1 ? 'county' : 'counties'} ${dir}` : name };
}

/** The faction's stronghold standing in a world in memory nearest `from`, if any. */
export function strongholdHere(worlds: World[], f: FactionId, from: Pt): Stronghold | null {
  let best: Stronghold | null = null, bd = Infinity;
  for (const w of worlds) {
    for (const s of strongholdsIn(w)) {
      if (s.f !== f) continue;
      const d = Math.hypot(s.w.ox + s.b.x - from.x, s.w.oz + s.b.z - from.z);
      if (d < bd) { bd = d; best = s; }
    }
  }
  return best;
}

/**
 * The faction's nearest stronghold as a place to aim at (strongholdSpot in the doc): the real point when it stands in
 * a world in memory, else its county's middle with an aim to retarget once it loads. No reach limit: the home
 * square's is always there.
 */
export function strongholdSpot(seed: string, worlds: World[], f: FactionId, from: Pt, at: AimAt): { at: PlaceRef; aim: StrongholdAim } {
  const here = strongholdHere(worlds, f, from);
  const hash = hashString(seed);
  const pcx = Math.floor(from.x / N), pcz = Math.floor(from.z / N);
  // the counties meant to hold one, nearest first; one in memory that holds none is passed over (it failed to be made)
  const cells = strongholdCells(hash, pcx, pcz, LOOK).filter((q) => q.f === f);
  const home = homeStronghold(hash, f);
  if (home) cells.push({ f, ...home });
  let far: { cx: number; cz: number } | null = null, fd = Infinity;
  for (const q of cells) {
    if (worlds.some((w) => w.cx === q.cx && w.cz === q.cz)) continue;
    const d = Math.hypot(q.cx * N + N / 2 - from.x, q.cz * N + N / 2 - from.z);
    if (d < fd) { fd = d; far = q; }
  }
  if (here) {
    const p = pointIn(here, at);
    const hd = Math.hypot(p.x - from.x, p.z - from.z);
    if (!far || hd <= fd) return { at: { ...p, cell: [here.w.cx, here.w.cz], name: nameIn(here, at) }, aim: { f, at, fixed: true } };
  }
  const c = far ?? home ?? { cx: pcx, cz: pcz };
  return { at: farRef(f, c.cx, c.cz, from), aim: { f, at } };
}

/** The place an aimed objective points at, for reading and for retargeting. */
function refOf(o: Obj): PlaceRef | null {
  if (o.t === 'reach') return o.at;
  if (o.t === 'deliver') return o.stronghold?.end === 'from' ? o.from : o.to;
  return null;
}
function setRef(o: Obj, r: PlaceRef): void {
  if (o.t === 'reach') o.at = { ...r };
  else if (o.t === 'deliver') {
    if (o.stronghold?.end === 'from') o.from = { ...o.from, ...r };
    else o.to = { ...o.to, ...r };
  }
}

/**
 * Point every aimed objective of the missions offered and under way at its stronghold once its county is in memory
 * (or, where that county made none, at the home square's). `from` is the player, for a far county's name. True when
 * anything moved.
 */
export function resolveAims(list: Mission[], worldAt: (cx: number, cz: number) => World | null, seed: string, from: Pt | null): boolean {
  let moved = false;
  for (const m of list) {
    if (m.state !== 'offered' && m.state !== 'active') continue;
    for (const o of m.objs) {
      const aim = o.stronghold;
      if (!aim || aim.fixed) continue;
      const r = refOf(o);
      if (!r) continue;
      const w = worldAt(r.cell[0], r.cell[1]);
      if (!w) continue;
      const s = strongholdsIn(w).find((q) => q.f === aim.f);
      if (s) {
        setRef(o, { ...pointIn(s, aim.at), cell: [w.cx, w.cz], name: nameIn(s, aim.at) });
        aim.fixed = true;
      } else {
        const home = homeStronghold(hashString(seed), aim.f);
        if (home && (home.cx !== w.cx || home.cz !== w.cz)) setRef(o, farRef(aim.f, home.cx, home.cz, from ?? { x: w.ox + N / 2, z: w.oz + N / 2 }));
        else aim.fixed = true;
      }
      moved = true;
    }
  }
  return moved;
}

/** Tiles from a point to an aimed place: what a stronghold step pays for on top of its own. */
export const aimTiles = (from: Pt, at: Pt): number => Math.hypot(at.x - from.x, at.z - from.z);
