import type { Missions } from './missions/missions';
import type { Mission } from './missions/model';

/**
 * The lessons that come with growing (26 Oct 2026): three locked teaching missions, each offered once, when the
 * player is ready for it, and talked through with tooltips pointing at the screen while it is under way:
 *
 *   first:roads  the road builder, once the HQ is level 3 (three fleet slots)
 *   first:tech   the tech trees, once 24 diamonds have come in (lifetime, spending never lowers it)
 *   first:build  putting up a building from the fleet's blueprints, once a town is the fleet's territory and it
 *                holds a blueprint (docs/blueprints.html; it was first:lobby, asking a town for a building, until 3 Nov 2026)
 *   first:bridge a road bridge over water near the player, once roads are learned (27 Oct 2026)
 *   first:land   levelling a patch of rough ground with the terrain tool, once roads are learned and the HQ
 *                is level 4 (four fleet slots)
 *   first:rails  laying track, then a parallel track, once three loads have gone by your own train or a train
 *                coming the other way has blocked yours (28 Oct 2026)
 *
 * They wait for the first drive and the getting-started track (game/fleetTrack.ts) to end, and come one at a
 * time. Done or given up, a lesson isn't offered again (the mission list and Missions.done are saved).
 */

interface Lesson { id: string; ready(h: CoachHost): boolean }
const LESSONS: Lesson[] = [
  { id: 'first:roads', ready: (h) => h.hqSlots() >= 3 },
  { id: 'first:tech', ready: (h) => h.diamondsEarned() >= 24 },
  { id: 'first:build', ready: (h) => h.holdsTown() && h.blueprints() > 0 },
  { id: 'first:bridge', ready: (h) => h.ms.done.has('first:roads') },
  { id: 'first:land', ready: (h) => h.ms.done.has('first:roads') && h.hqSlots() >= 4 },
  { id: 'first:rails', ready: (h) => h.trainLoads() > 2 || h.trainBlocked() },
];
/** A lesson with nowhere near to happen (no water to bridge, no rough ground) is looked for again this much later, s. */
const LOOK_AGAIN = 90;
const IDS = new Set(LESSONS.map((l) => l.id));

export interface CoachHost {
  ms: Missions;
  /** A card, the journal or a menu is up: no new mission is put in front of it. */
  busy(): boolean;
  hqSlots(): number;
  /** Every diamond ever paid in. */
  diamondsEarned(): number;
  /** The fleet holds at least one town as its territory. */
  holdsTown(): boolean;
  /** The road builder: open, which side is up, and whether a road has been started (its first click). */
  builder(): { active: boolean; side: 'roads' | 'rails' | 'buildings' | 'scenery' | 'boosts'; drawing: boolean };
  /** The HQ window's tab while it is open, else null. */
  hqTab(): string | null;
  /** Blueprints the fleet holds (game/blueprints.ts). */
  blueprints(): number;
  /** Diamonds in hand. */
  diamonds(): number;
  /** The terrain tool is in hand. */
  earth(): boolean;
  /** Is the terrain lesson's lot round `at` level now (missions/templates.ts lotLevel)? */
  levelled(at: { x: number; z: number; cell: [number, number] }): boolean;
  /** Loads ever delivered at the regulator of your own train. */
  trainLoads(): number;
  /** Your train has been held nose to nose with one coming the other way (this session). */
  trainBlocked(): boolean;
}

/** A tooltip: what to say, and the element it points at (null: low in the middle of the screen). */
interface Tip { html: string; at: string | null; nth?: number }

export class Coach {
  private wait = 0;
  /** Seconds since the game began, and when each lesson that had nowhere to happen may be looked for again. */
  private clock = 0;
  private later = new Map<string, number>();
  private el = document.createElement('div');
  private glowing: HTMLElement | null = null;
  private shown = '';

  constructor(private host: CoachHost) {
    this.el.id = 'coach-tip';
    this.el.hidden = true;
    document.body.append(this.el);
    injectCss();
  }

  /** Every frame. `playing`: the game is on screen (not paused, not the photo mode). */
  update(dt: number, playing: boolean): void {
    this.clock += dt;
    this.offer(dt);
    const m = this.lesson();
    // the lot levelled: the step is done the moment the ground is flat, however it got that way
    const o = m?.objs[m.step];
    if (m && o?.t === 'make' && o.what === 'level' && o.at && this.wait === 1 && this.host.levelled(o.at)) this.host.ms.bus.emit('made', { what: 'level', n: 1 });
    // not over a card, the journal or the garage: they come first, and the tip comes back when they close
    this.show(playing && m && !this.host.busy() ? this.tipFor(m) : null);
  }

  /** Once a second: the next lesson whose time has come, when nothing else is being taught. */
  private offer(dt: number): void {
    const h = this.host, ms = h.ms;
    this.wait -= dt;
    if (this.wait > 0) return;
    this.wait = 1;
    if (ms.learning() || h.busy()) return;
    // one at a time: a lesson on offer or under way waits for its end
    if (ms.list.some((q) => IDS.has(q.tpl) && (q.state === 'offered' || q.state === 'active'))) return;
    for (const l of LESSONS) {
      if (ms.done.has(l.id) || ms.list.some((q) => q.tpl === l.id && q.state !== 'rejected')) continue;
      if (!l.ready(h) || (this.later.get(l.id) ?? 0) > this.clock) continue;
      ms.force(l.id);
      const f = ms.list.find((q) => q.tpl === l.id && q.state === 'offered');
      // nowhere near to happen: look again in a while rather than every second
      if (!f) { this.later.set(l.id, this.clock + LOOK_AGAIN); continue; }
      // offered on its card the next time the player stops (Missions.maybeOffer)
      if (f) f.shown = false;
      return;
    }
  }

  /** The lesson under way, if any. */
  private lesson(): Mission | null {
    return this.host.ms.active.find((q) => IDS.has(q.tpl)) ?? null;
  }

  private tipFor(m: Mission): Tip | null {
    const h = this.host, b = h.builder();
    const o = m.objs[m.step];
    if (!o || o.t !== 'make') return null;
    const left = o.n - m.count;
    switch (o.what) {
      case 'road':
        if (!b.active) return { html: 'Press <kbd>B</kbd> or click <b>Build</b> to open the road builder', at: '#tb-road' };
        if (b.side !== 'roads') return { html: 'Pick the <b>Roads</b> side', at: '.rb-tab', nth: 0 };
        if (!b.drawing) {
          return { html: m.count ? `<b>${m.count}</b> of ${o.n} tiles built · click to start another road` : 'Click the ground where your road should <b>start</b>: a road end, a junction or open country', at: null };
        }
        return { html: `Now click where it should <b>end</b>: the ghost shows its route and price · click to build it · <kbd>Esc</kbd> starts again${left < o.n ? ` · ${left} tiles to go` : ''}`, at: null };
      case 'unlock': {
        const tab = h.hqTab();
        if (tab === null) return { html: 'Press <kbd>H</kbd> to open your HQ, or click your fleet’s name up here', at: '#fleetname' };
        if (tab !== 'tech') return { html: 'Open the <b>Tech</b> tab', at: '#hq [data-tab="tech"]' };
        if (document.querySelector('#hq button[data-unlock]:not([disabled])')) return { html: 'Press <b>Unlock</b>: the dealers that stock it sell it from now on', at: '#hq button[data-unlock]:not([disabled])' };
        if (document.querySelector('#hq button[data-unlock][disabled]')) return { html: `That one costs more than your <b>◆ ${Math.floor(h.diamonds())}</b>: pick a cheaper lit vehicle`, at: '#hq .node.open' };
        return { html: `Click a <b>lit</b> vehicle on a tree: you have <b>◆ ${Math.floor(h.diamonds())}</b> to spend`, at: '#hq .node.open' };
      }
      case 'erect':
        if (!b.active) return { html: 'Press <kbd>B</kbd> or click <b>Build</b>, then pick the <b>Buildings</b> side', at: '#tb-road' };
        if (b.side !== 'buildings') return { html: 'Pick the <b>Buildings</b> side', at: '.rb-tab', nth: 2 };
        if (document.querySelector('.rb-brow .rb-bsq.on')) return { html: 'Move the ghost onto <b>open ground beside a road</b> and click to break ground · <kbd>R</kbd> turns it · inside a town’s lines only where your fleet holds the town', at: null };
        return { html: 'Pick one of your <b>blueprints</b>: every building your fleet has owned is a square here', at: '.rb-brow .rb-bsq' };
      case 'bridge':
        if (!b.active) return { html: 'Press <kbd>B</kbd> or click <b>Build</b>: a road can bridge the water by the ring', at: '#tb-road' };
        if (b.side !== 'roads') return { html: 'Pick the <b>Roads</b> side', at: '.rb-tab', nth: 0 };
        if (!b.drawing) return { html: 'Click a road end or the ground on one <b>bank</b>, beside the yellow ring', at: null };
        return { html: 'Now click on the <b>far bank</b>: where the gap fits, the bridge goes in by itself · <kbd>V</kbd> Big bridges reach twice as far · <kbd>T</kbd> makes it a toll bridge', at: null };
      case 'rail':
        if (!b.active) return { html: 'Press <kbd>B</kbd> or click <b>Build</b> to open the builder', at: '#tb-road' };
        if (b.side !== 'rails') return { html: 'Pick the <b>Rails</b> side', at: '.rb-tab', nth: 1 };
        if (!b.drawing) return { html: m.count ? `<b>${m.count}</b> of ${o.n} tiles laid · click to start another track` : 'Click where your track should <b>start</b>: a station’s buffers, any line (for a junction) or open ground', at: null };
        return { html: `Now click where it should <b>end</b>: the ghost shows its route and price · click to lay it · <kbd>Esc</kbd> starts again${left < o.n ? ` · ${left} tiles to go` : ''}`, at: null };
      case 'railParallel':
        if (!b.active) return { html: 'Press <kbd>B</kbd> or click <b>Build</b>, then pick the <b>Rails</b> side', at: '#tb-road' };
        if (b.side !== 'rails') return { html: 'Pick the <b>Rails</b> side', at: '.rb-tab', nth: 1 };
        if (!b.drawing) return { html: 'Click beside an existing line to <b>start</b>, a few tiles off it: that gap is the one the new track keeps', at: null };
        return { html: 'Hold <kbd>Shift</kbd> and move along the line: the ghost runs beside it · click to lay the parallel track', at: null };
      case 'level':
        if (!h.earth()) return { html: 'Press <kbd>T</kbd> or click the <b>terrain</b> button to pick up the spade', at: '#tb-earth' };
        return { html: 'Hold <kbd>Shift</kbd> and drag across the ring: everything under the brush comes to one height · <kbd>1</kbd>–<kbd>7</kbd> sizes the brush · <kbd>Z</kbd> undoes · $2 a lift', at: null };
    }
  }

  private show(t: Tip | null): void {
    const target = t?.at ? (Array.from(document.querySelectorAll<HTMLElement>(t.at)).filter((e) => e.offsetParent !== null)[t.nth ?? 0] ?? null) : null;
    if (target !== this.glowing) {
      this.glowing?.classList.remove('coach-glow');
      target?.classList.add('coach-glow');
      this.glowing = target;
    }
    if (!t) { if (!this.el.hidden) { this.el.hidden = true; this.el.classList.remove('on'); this.shown = ''; } return; }
    if (this.shown !== t.html) { this.el.innerHTML = t.html; this.shown = t.html; }
    if (this.el.hidden) { this.el.hidden = false; void this.el.offsetWidth; this.el.classList.add('on'); }
    // beside what it points at: above it in the lower half of the screen, below it in the upper
    const s = this.el.style;
    if (target) {
      const r = target.getBoundingClientRect(), w = this.el.offsetWidth, hgt = this.el.offsetHeight;
      const below = r.top + r.height / 2 < innerHeight / 2;
      const x = Math.max(8, Math.min(innerWidth - w - 8, r.left + r.width / 2 - w / 2));
      s.left = `${x}px`;
      s.top = `${below ? r.bottom + 14 : r.top - hgt - 14}px`;
      s.setProperty('--ax', `${Math.max(14, Math.min(w - 14, r.left + r.width / 2 - x))}px`);
      this.el.classList.toggle('below', below);
      this.el.classList.toggle('free', false);
    } else {
      const w = this.el.offsetWidth;
      s.left = `${Math.max(8, innerWidth / 2 - w / 2)}px`;
      s.top = `${Math.round(innerHeight * 0.68)}px`;
      this.el.classList.toggle('free', true);
      this.el.classList.toggle('below', false);
    }
  }
}

let css = false;
function injectCss(): void {
  if (css) return;
  css = true;
  const st = document.createElement('style');
  st.textContent = `
    #coach-tip { position: fixed; z-index: 40; pointer-events: none; max-width: min(320px, calc(100vw - 32px)); box-sizing: border-box; padding: 10px 14px 11px; border-radius: 14px; background: #1f2b33; color: #fff; font-size: 14px; font-weight: 500; line-height: 1.4; box-shadow: 0 10px 28px rgba(31,43,51,.35), 0 0 0 3px #ffd24a; opacity: 0; transition: opacity .25s; }
    #coach-tip.on { opacity: 1; }
    #coach-tip b { color: #ffd24a; }
    #coach-tip kbd { display: inline-block; font-family: "IBM Plex Mono", monospace; font-size: 12.5px; line-height: 1.3; background: #fff; color: #1f2b33; border-radius: 5px; border-bottom: 2px solid #b9c3c8; padding: 0 6px; margin: 0 2px; }
    #coach-tip::after { content: ""; position: absolute; left: var(--ax, 50%); margin-left: -8px; border: 8px solid transparent; }
    #coach-tip:not(.below):not(.free)::after { bottom: -15px; border-top-color: #ffd24a; }
    #coach-tip.below::after { top: -15px; border-bottom-color: #ffd24a; }
    #coach-tip.free::after { display: none; }
    .coach-glow { outline: 3px solid #ffd24a !important; outline-offset: 2px; animation: coachGlow 1.1s ease-in-out infinite; position: relative; z-index: 41; }
    @keyframes coachGlow { 50% { outline-color: rgba(255, 210, 74, .25); } }
  `;
  document.head.append(st);
}
